
// ── Referências globais do Script 0 ──────────────────────────
var dataHoje = window.dataHoje || function(){var d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');};
var CONTRATOS_UUID_MAP = window.CONTRATOS_UUID_MAP || {};

// ══ MÓDULO GESTÃO DE PONTO POR CONTRATO ══════════════════════
var _gp = { cont:'', ini:'', fim:'', aba:'dashboard', registros:[], limites:[], escopo:[], reSet:{} };

function gpGetCont(){ return (document.getElementById('gp-cont')||{}).value || _gp.cont || ''; }
function gpGetIni(){ return (document.getElementById('gp-ini')||{}).value || _gp.ini || (mesHojeLocal()+'-01'); }
function gpGetFim(){ return (document.getElementById('gp-fim')||{}).value || _gp.fim || dataHojeLocal(); }
function gpPeriodoLabel(){ return fmtD(_gp.ini)+' a '+fmtD(_gp.fim); }
function gpEscopoColabs(cid){
  return colaboradores.filter(function(c){
    if(c.ativo===false || c.dispensado || !c.re) return false;
    if(cid && cid!=='__todos__') return c.contrato_id===cid;
    return true; // __todos__ : empresa inteira
  });
}
function gpHHMM(dec){ dec=parseFloat(dec)||0; var h=Math.floor(dec); var m=Math.round((dec-h)*60); return h+'h'+(m?String(m).padStart(2,'0'):'00'); }
function gpHEporColab(){ var map={}; _gp.registros.forEach(function(r){ var k=String(r.re); map[k]=(map[k]||0)+(parseFloat(r.horas_extras)||0); }); return map; }
function gpLimiteCargo(cargo,contratoId){ var l=_gp.limites.find(function(x){ return x.ativo!==false && (x.cargo||'')===(cargo||'') && (!contratoId || x.contrato_id===contratoId); }); return l?(parseFloat(l.limite_horas_mes)||0):null; }
function gpColabByRe(re){ return _gp.reSet[String(re)] || _gp.reSet[pontoReNorm(re)] || null; }

function gpOnFiltro(){ _gp.cont=gpGetCont(); _gp.ini=gpGetIni(); _gp.fim=gpGetFim(); try{sessionStorage.setItem('gp_contrato',_gp.cont);sessionStorage.setItem('gp_ini',_gp.ini);sessionStorage.setItem('gp_fim',_gp.fim);}catch(e){} gpInit(); }

function gpInit(){
  var selC=document.getElementById('gp-cont');
  if(selC){
    var cur=selC.value||_gp.cont||sessionStorage.getItem('gp_contrato')||'';
    var lista=(typeof _contratosVisiveis==='function'?_contratosVisiveis():contratos)||[];
    selC.innerHTML='<option value="">Selecione o contrato...</option><option value="__todos__">📊 Todos os contratos (empresa)</option>'+lista.map(function(c){return '<option value="'+c.id+'">'+escHtml(c.nome)+'</option>';}).join('');
    if(cur) selC.value=cur;
  }
  var selI=document.getElementById('gp-ini'), selF=document.getElementById('gp-fim');
  if(selI && !selI.value) selI.value=sessionStorage.getItem('gp_ini')||(mesHojeLocal()+'-01');
  if(selF && !selF.value) selF.value=sessionStorage.getItem('gp_fim')||dataHojeLocal();
  _gp.cont=gpGetCont(); _gp.ini=gpGetIni(); _gp.fim=gpGetFim();
  if(_gp.ini>_gp.fim){ var t=_gp.ini; _gp.ini=_gp.fim; _gp.fim=t; if(selI)selI.value=_gp.ini; if(selF)selF.value=_gp.fim; }
  try{ sessionStorage.setItem('gp_contrato',_gp.cont); sessionStorage.setItem('gp_ini',_gp.ini); sessionStorage.setItem('gp_fim',_gp.fim); }catch(e){}
  gpSetAbaBtns();
  if(!_gp.cont){ var d=document.getElementById('gp-tab-dashboard'); if(d) d.innerHTML='<div class="card" style="padding:2rem;text-align:center;color:#aaa">Selecione um contrato e o período (De/Até), depois clique em Atualizar.</div>'; return; }
  gpCarregar();
}

function gpCarregar(){
  var cid=_gp.cont;
  var escopo=gpEscopoColabs(cid); var reSet={}; escopo.forEach(function(c){
    reSet[String(c.re)]=c;
    var rn=pontoReNorm(c.re); if(rn) reSet[rn]=c;
  });
  _gp.escopo=escopo; _gp.reSet=reSet;
  var alvo=document.getElementById('gp-tab-'+_gp.aba);
  if(alvo) alvo.innerHTML='<div class="card" style="padding:2rem;text-align:center;color:#aaa">⏳ Carregando ponto de '+escHtml(gpPeriodoLabel())+'...</div>';
  Promise.all([
    sbFetchAll('ponto_registros',{filters:['data=gte.'+_gp.ini,'data=lte.'+_gp.fim],order:'data'}),
    sbFetchAll('ponto_he_limites',cid==='__todos__'?{}:{filters:['contrato_id=eq.'+cid]})
  ]).then(function(res){
    _gp.registros=(res[0]||[]).filter(function(x){ return reSet[String(x.re)] || reSet[pontoReNorm(x.re)]; });
    // Previsto/antecipação: prioriza escala do cadastro ERP (não o horário divergente do Nexus)
    var corr=gpAplicarEscalaErpNosRegistros(_gp.registros);
    if(corr.length) gpPersistirCorrecoesEscalaErp(corr);
    _gp.limites=res[1]||[];
    gpAtualizarSyncInfo();
    gpRenderAbaAtual();
  }).catch(function(e){ if(alvo) alvo.innerHTML='<div class="card" style="padding:2rem;text-align:center;color:#A32D2D">Erro: '+escHtml((e&&e.message)||e)+'</div>'; });
}
// Indicador: até quando o ponto está sincronizado no período/contrato pesquisado
function gpAtualizarSyncInfo(){
  var el=document.getElementById('gp-sync-info'); if(!el) return;
  if(!_gp.cont){ el.innerHTML=''; return; }
  var regs=_gp.registros||[];
  var datas=regs.map(function(r){return (r.data||'').slice(0,10);}).filter(Boolean).sort();
  var maxData=datas.length?datas[datas.length-1]:null;
  var dias={}; datas.forEach(function(d){dias[d]=1;}); var nDias=Object.keys(dias).length;
  var hoje=dataHojeLocal();
  var fimAlvo=_gp.fim>hoje?hoje:_gp.fim; // só cobra sync até hoje
  var faltando = maxData ? (maxData<fimAlvo) : true;
  if(!regs.length){
    el.innerHTML='⚠ <b>Sem registros de ponto</b> no período/contrato. Clique em <b>📡 Sincronizar período</b> para buscar no relógio (Nexus).';
  } else {
    el.innerHTML='📡 Ponto sincronizado até <b>'+(maxData?fmtD(maxData):'—')+'</b> · '+regs.length+' registros · '+nDias+' dia(s) carregados'
      +(faltando
        ? ' · <span style="color:#A36A00">⚠ o período vai até '+fmtD(fimAlvo)+'; pode faltar sincronizar — clique em <b>📡 Sincronizar período</b></span>'
        : ' · <span style="color:#3B6D11">✓ período coberto</span>');
  }
}
// Botão da barra: vai para a aba Sincronizar e dispara a sincronização (com progresso visível)
function gpSyncAgora(){
  if(!_gp.cont){ progShowToast('Selecione um contrato primeiro.'); return; }
  gpSetAba('sync');
  setTimeout(function(){ if(typeof gpSyncMes==='function') gpSyncMes(); }, 150);
}

function gpSetAbaBtns(){
  ['dashboard','registros','limites','ajuste','vales','sync'].forEach(function(a){
    var el=document.getElementById('gp-tab-'+a); if(el) el.style.display=(a===_gp.aba?'':'none');
    var b=document.getElementById('gp-tab-btn-'+a);
    if(b){ b.style.color=a===_gp.aba?'#1a1a18':'#888'; b.style.fontWeight=a===_gp.aba?'700':'600'; b.style.borderBottomColor=a===_gp.aba?'#1a1a18':'transparent'; }
  });
}
function gpSetAba(aba){ _gp.aba=aba; gpSetAbaBtns(); gpRenderAbaAtual(); }
function gpRenderAbaAtual(){
  if(_gp.aba==='dashboard') gpRenderDashboard();
  else if(_gp.aba==='registros') gpRenderRegistros();
  else if(_gp.aba==='limites') gpRenderLimitesHE();
  else if(_gp.aba==='ajuste') gpRenderAjuste();
  else if(_gp.aba==='vales') gpRenderVales();
  else if(_gp.aba==='sync') gpRenderSync();
}
// ── Vales (descontos em folha — origem mau uso de EPI etc.) ─────
var _gpVales=null, _gpValesKey='';
function gpCarregarValesEpi(cb){
  var key=_gp.ini+'_'+_gp.fim;
  if(_gpValesKey===key && _gpVales){ if(cb)cb(); return; }
  if(DEMO){ _gpVales=(typeof vales!=='undefined'?vales:[]); _gpValesKey=key; if(cb)cb(); return; }
  sbFetchAll('vales',{filters:['data_emissao=gte.'+_gp.ini,'data_emissao=lte.'+_gp.fim],order:'data_emissao.desc'})
    .then(function(r){ _gpVales=r||[]; _gpValesKey=key; if(cb)cb(); }).catch(function(){ _gpVales=[]; _gpValesKey=key; if(cb)cb(); });
}
function gpRenderVales(){
  var el=document.getElementById('gp-tab-vales'); if(!el) return;
  if(!_gp.cont){ el.innerHTML='<div class="card" style="padding:2rem;text-align:center;color:#aaa">Selecione um contrato e o período.</div>'; return; }
  if(_gpValesKey!==(_gp.ini+'_'+_gp.fim) || !_gpVales){ el.innerHTML='<div class="card" style="padding:2rem;text-align:center;color:#aaa">⏳ Carregando vales...</div>'; gpCarregarValesEpi(function(){ if(_gp.aba==='vales') gpRenderVales(); }); return; }
  var idSet={}; (_gp.escopo||[]).forEach(function(c){ idSet[c.id]=true; });
  var rows=_gpVales.filter(function(v){
    if(_gp.cont!=='__todos__' && v.contrato_id && v.contrato_id!==_gp.cont) return false;
    if(v.funcionario_id && !idSet[v.funcionario_id] && _gp.cont!=='__todos__') return false;
    return true;
  });
  var aAplicar=rows.filter(function(v){ return (v.status||'A aplicar')!=='Aplicado'; });
  var aplicados=rows.filter(function(v){ return v.status==='Aplicado'; });
  function colab(v){ return (colaboradores||[]).find(function(c){return c.id===v.funcionario_id;})||{}; }
  function linhaAplicar(v){ var c=colab(v);
    return '<tr><td style="font-weight:600">'+escHtml(String(c.re||'—'))+'</td><td style="font-weight:500">'+escHtml(c.nome||'—')+'</td>'
      +'<td>'+escHtml(v.item||'—')+'</td><td style="font-size:11px;color:#888">'+escHtml(v.motivo||'')+(v.origem?' · '+escHtml(v.origem):'')+'</td>'
      +'<td style="text-align:right;font-weight:700;color:#A32D2D">R$ '+Number(v.valor||0).toLocaleString('pt-BR',{minimumFractionDigits:2})+'</td>'
      +'<td style="text-align:center">'+(v.assinatura_url?'<a onclick="gpVerAssinaturaVale(\''+v.id+'\')" style="cursor:pointer;color:#185FA5;font-size:11px">✍ ver</a>':'<span style="font-size:10px;color:#854F0B">sem assin.</span>')+'</td>'
      +'<td style="text-align:center"><button class="btn btn-sm btn-pri" onclick="gpValeAplicar(\''+v.id+'\')">Aplicar</button></td></tr>';
  }
  function linhaAplicado(v){ var c=colab(v);
    return '<tr><td style="font-weight:600">'+escHtml(String(c.re||'—'))+'</td><td style="font-weight:500">'+escHtml(c.nome||'—')+'</td>'
      +'<td>'+escHtml(v.item||'—')+'</td>'
      +'<td style="text-align:right;font-weight:600">R$ '+Number(v.valor||0).toLocaleString('pt-BR',{minimumFractionDigits:2})+'</td>'
      +'<td style="text-align:center">'+(v.parcelado?(v.parcelas||1)+'x':'à vista')+'</td>'
      +'<td style="text-align:center;font-weight:600;color:#3B6D11">'+escHtml(_gpMesLabel(v.mes_aplicado))+'</td>'
      +'<td style="text-align:center"><button class="btn btn-sm" onclick="gpValeReabrir(\''+v.id+'\')">↩</button></td></tr>';
  }
  var totAplicar=aAplicar.reduce(function(s,v){return s+Number(v.valor||0);},0);
  el.innerHTML='<div class="card" style="margin-bottom:.75rem"><div class="ch"><span class="ct">💸 Vales a aplicar (descontar) — '+escHtml(gpPeriodoLabel())+' ('+aAplicar.length+' · R$ '+totAplicar.toLocaleString('pt-BR',{minimumFractionDigits:2})+')</span></div>'
    +(aAplicar.length?'<div style="overflow-x:auto"><table class="tbl" style="font-size:12px"><thead><tr><th>RE</th><th>Colaborador</th><th>Item</th><th>Motivo/Origem</th><th style="text-align:right">Valor</th><th style="text-align:center">Assin.</th><th></th></tr></thead><tbody>'+aAplicar.map(linhaAplicar).join('')+'</tbody></table></div>':'<div style="padding:1.5rem;text-align:center;color:#3B6D11">Nenhum vale pendente de aplicação.</div>')+'</div>'
    +'<div class="card"><div class="ch"><span class="ct">✅ Vales aplicados ('+aplicados.length+')</span></div>'
    +(aplicados.length?'<div style="overflow-x:auto"><table class="tbl" style="font-size:12px"><thead><tr><th>RE</th><th>Colaborador</th><th>Item</th><th style="text-align:right">Valor</th><th style="text-align:center">Forma</th><th style="text-align:center">Mês aplicado</th><th></th></tr></thead><tbody>'+aplicados.map(linhaAplicado).join('')+'</tbody></table></div>':'<div style="padding:1rem;text-align:center;color:#aaa">Nenhum vale aplicado no período.</div>')+'</div>';
}
function _gpMesLabel(m){ if(!m) return '—'; var p=String(m).split('-'); return p.length>=2?(p[1]+'/'+p[0]):m; }
function gpVerAssinaturaVale(id){ var v=(_gpVales||[]).find(function(x){return x.id===id;}); if(v&&v.assinatura_url&&typeof inspAbrirFotoFull==='function') inspAbrirFotoFull(v.assinatura_url); else progShowToast('Sem assinatura.'); }
function gpValeAplicar(id){
  var v=(_gpVales||[]).find(function(x){return x.id===id;}); if(!v) return;
  var c=(colaboradores||[]).find(function(x){return x.id===v.funcionario_id;})||{};
  var mesAtual=(_gp.fim||dataHojeLocal()).slice(0,7);
  setModal('<div class="modal-bg"><div class="modal" style="max-width:430px">'
    +'<h3 style="margin-bottom:.5rem">💸 Aplicar vale na folha</h3>'
    +'<div style="font-size:12px;color:#555;margin-bottom:.6rem"><b>'+escHtml(c.nome||'—')+'</b> · '+escHtml(v.item||'')+'<br>Valor: <b style="color:#A32D2D">R$ '+Number(v.valor||0).toLocaleString('pt-BR',{minimumFractionDigits:2})+'</b></div>'
    +'<div class="fg" style="margin-bottom:.5rem"><label style="font-size:11px;font-weight:600">Mês de aplicação na folha *</label><input class="inp" id="gpval-mes" type="month" style="width:100%" value="'+mesAtual+'"/></div>'
    +'<div class="fg" style="margin-bottom:.5rem"><label style="font-size:11px;font-weight:600">Forma de desconto</label><select class="inp" id="gpval-forma" style="width:100%" onchange="document.getElementById(\'gpval-parc-wrap\').style.display=this.value===\'parcelado\'?\'\':\'none\'"><option value="avista">À vista (1x)</option><option value="parcelado">Parcelado</option></select></div>'
    +'<div class="fg" id="gpval-parc-wrap" style="margin-bottom:.6rem;display:none"><label style="font-size:11px;font-weight:600">Nº de parcelas</label><input class="inp" id="gpval-parc" type="number" min="2" value="2" style="width:100%"/></div>'
    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn btn-pri" onclick="gpValeSalvarAplicacao(\''+id+'\')">✅ Confirmar aplicação</button></div>'
    +'</div></div>');
}
function gpValeSalvarAplicacao(id){
  var v=(_gpVales||[]).find(function(x){return x.id===id;}); if(!v) return;
  var mes=(document.getElementById('gpval-mes')||{}).value||''; if(!mes){ progShowToast('Informe o mês.','erro'); return; }
  var parcelado=(document.getElementById('gpval-forma')||{}).value==='parcelado';
  var parcelas=parcelado?(parseInt((document.getElementById('gpval-parc')||{}).value)||2):1;
  var payload={ status:'Aplicado', mes_aplicado:mes, aplicado_em:dataHojeLocal(), parcelado:parcelado, parcelas:parcelas };
  Object.assign(v,payload);
  var vg=(typeof vales!=='undefined')?vales.find(function(x){return x.id===id;}):null; if(vg) Object.assign(vg,payload);
  if(!DEMO) sbUpdate('vales',payload,'id=eq.'+id).catch(function(){ progShowToast('❌ Erro ao salvar (rodou o sql_vales_epi.sql?).','erro'); });
  closeModal(); progShowToast('✅ Vale aplicado na folha de '+_gpMesLabel(mes)+(parcelado?' em '+parcelas+'x':' à vista')+'.'); gpRenderVales();
}
function gpValeReabrir(id){
  var v=(_gpVales||[]).find(function(x){return x.id===id;}); if(!v) return;
  if(!confirm('Reabrir este vale (voltar para A aplicar)?')) return;
  var payload={ status:'A aplicar', mes_aplicado:null, aplicado_em:null };
  Object.assign(v,payload); var vg=(typeof vales!=='undefined')?vales.find(function(x){return x.id===id;}):null; if(vg) Object.assign(vg,payload);
  if(!DEMO) sbUpdate('vales',payload,'id=eq.'+id).catch(function(){});
  gpRenderVales();
}

// ── Ajuste de batida (RH): antecipações + validação ──────────────
var _gpAjusteView='antecip', _gpAntecMin=5;
function gpAjusteSetView(v){ _gpAjusteView=v; gpRenderAjuste(); }
function gpDiasPeriodo(){
  var dias=[]; var d=new Date(_gp.ini+'T12:00:00'); var fim=new Date(_gp.fim+'T12:00:00'); var g=0;
  while(d<=fim && g<400){ dias.push(d.toISOString().slice(0,10)); d.setDate(d.getDate()+1); g++; }
  return dias;
}
function _gpEntAtual(r){ return r.entrada_ajustada || r.entrada || ''; }
function _gpSaidaAtual(r, data){
  var ef=typeof pontoEntradaSaidaEfetiva==='function'?pontoEntradaSaidaEfetiva(r, data):{};
  return ef.saida||r.saida_ajustada||r.saida||'';
}
function gpSincronizarPeriodo(){ gpSyncMes(); }
function _gpEntOrig(r){ return r.entrada_original || r.entrada || ''; }
function gpRenderAjuste(){
  var el=document.getElementById('gp-tab-ajuste'); if(!el) return;
  if(!_gp.cont){ el.innerHTML='<div class="card" style="padding:2rem;text-align:center;color:#aaa">Selecione um contrato e o período, depois Atualizar.</div>'; return; }
  var regs=_gp.registros||[];
  var subBtns='<div style="display:flex;gap:6px;margin-bottom:.75rem;flex-wrap:wrap">'
    +'<button onclick="gpAjusteSetView(\'antecip\')" class="btn btn-sm'+(_gpAjusteView==='antecip'?' btn-pri':'')+'">① Antecipações (ajustar)</button>'
    +'<button onclick="gpAjusteSetView(\'validacao\')" class="btn btn-sm'+(_gpAjusteView==='validacao'?' btn-pri':'')+'">② Validação dos ajustes</button>'
    +'<button onclick="gpAjusteSetView(\'verificar\')" class="btn btn-sm'+(_gpAjusteView==='verificar'?' btn-pri':'')+'">③ Verificar (Desconto em Folha)</button>'
    +'</div>';
  if(_gpAjusteView==='validacao'){ el.innerHTML=subBtns+gpAjusteValidacaoHtml(regs); return; }
  if(_gpAjusteView==='verificar'){ el.innerHTML=subBtns+gpAjusteVerificarHtml(); return; }
  el.innerHTML=subBtns+gpAjusteAntecipHtml(regs);
}
// ── ③ Verificar: tratamentos com decisão "Desconto em Folha" ──────
var _gpVerificarRows=null, _gpVerificarKey='';
function gpCarregarVerificar(cb){
  var key=_gp.ini+'_'+_gp.fim;
  if(_gpVerificarKey===key && _gpVerificarRows){ if(cb)cb(); return; }
  if(DEMO){ _gpVerificarRows=_vtDados||[]; _gpVerificarKey=key; if(cb)cb(); return; }
  sbFetchAll('verificar_tratamentos',{filters:['data_ocorrencia=gte.'+_gp.ini,'data_ocorrencia=lte.'+_gp.fim],order:'data_ocorrencia.desc'})
    .then(function(rows){ _gpVerificarRows=rows||[]; _gpVerificarKey=key; if(cb)cb(); })
    .catch(function(){ _gpVerificarRows=[]; _gpVerificarKey=key; if(cb)cb(); });
}
function gpVerificarColab(t){
  // tenta por id no escopo; senão busca em colaboradores
  return (_gp.escopo||[]).find(function(c){return c.id===t.colaborador_id;})
      || (colaboradores||[]).find(function(c){return c.id===t.colaborador_id;}) || {};
}
function gpAjusteVerificarHtml(){
  if(_gpVerificarKey!==(_gp.ini+'_'+_gp.fim) || !_gpVerificarRows){
    gpCarregarVerificar(function(){ if(_gp.aba==='ajuste'&&_gpAjusteView==='verificar') gpRenderAjuste(); });
    return '<div class="card" style="padding:2rem;text-align:center;color:#aaa">⏳ Carregando tratamentos de Verificar...</div>';
  }
  var idSet={}; (_gp.escopo||[]).forEach(function(c){ idSet[c.id]=true; });
  var rows=_gpVerificarRows.filter(function(t){
    if(!idSet[t.colaborador_id]) return false; // mesmo escopo de contrato das outras abas
    return (t.decisoes||'').split(',').indexOf('desconto_folha')>=0; // decisão final = Desconto em Folha
  });
  rows.sort(function(a,b){ return (b.data_ocorrencia||'').localeCompare(a.data_ocorrencia||''); });
  if(!rows.length){ return '<div class="card" style="padding:2rem;text-align:center;color:#3B6D11">✅ Nenhum colaborador com decisão "Desconto em Folha" no período '+escHtml(gpPeriodoLabel())+'.</div>'; }
  var linhas=rows.map(function(t){
    var c=gpVerificarColab(t);
    var outras=(t.decisoes||'').split(',').filter(function(d){return d&&d!=='desconto_folha';})
      .map(function(d){ var o=VT_DECISOES.find(function(x){return x.id===d;}); return o?o.label:d; });
    var dec=t.ponto_decisao;
    var valHtml = dec==='autorizado'
        ? '<span class="bdg ok" style="font-size:10px">✓ Autorizado</span>'+(t.ponto_ajustado&&t.ponto_ajuste_em?'<div style="font-size:9px;color:#3B6D11">ponto ajustado '+fmtD((t.ponto_ajuste_em||'').slice(0,10))+'</div>':'')
        : dec==='negado'
        ? '<span class="bdg danger" style="font-size:10px">🚫 Negado</span>'
        : '<span style="font-size:10px;color:#854F0B">⏳ Pendente</span>';
    var rowBg = dec==='autorizado'?'background:#F6FBF0':dec==='negado'?'background:#FCEFEF':'';
    return '<tr style="'+rowBg+'">'
      +'<td style="font-weight:600">'+escHtml(String(c.re||'—'))+'</td>'
      +'<td style="font-weight:600;color:#1a1a18;white-space:nowrap">'+escHtml(c.nome||'—')+'</td>'
      +'<td style="font-size:12px;color:#A32D2D">'+escHtml(t.decisao_obs||'(sem observação)')+(dec==='negado'&&t.ponto_ajuste_obs?'<div style="font-size:11px;color:#A32D2D">🚫 '+escHtml(t.ponto_ajuste_obs)+'</div>':'')+'</td>'
      +'<td>'+fmtD((t.data_ocorrencia||'').slice(0,10))+'</td>'
      +'<td><span class="bdg danger" style="font-size:10px">💰 Desconto em Folha</span>'+(outras.length?' <span style="font-size:10px;color:#888">+ '+escHtml(outras.join(', '))+'</span>':'')+'</td>'
      +'<td style="text-align:center">'+valHtml+'</td>'
      +'<td style="text-align:center"><button class="btn btn-sm'+(dec?'':' btn-pri')+'" onclick="gpVerificarDecidir(\''+t.id+'\')">'+(dec?'Revisar':'⚖️ Validar')+'</button></td>'
      +'</tr>';
  }).join('');
  var nAut=rows.filter(function(t){return t.ponto_decisao==='autorizado';}).length;
  var nNeg=rows.filter(function(t){return t.ponto_decisao==='negado';}).length;
  var nPend=rows.length-nAut-nNeg;
  return '<div class="card"><div class="ch"><span class="ct">💰 Verificar — Desconto em Folha — '+escHtml(gpPeriodoLabel())+' ('+rows.length+' · '+nPend+' pendentes · '+nAut+' autorizados · '+nNeg+' negados)</span>'
    +'<button class="btn btn-sm" onclick="gpExportVerificar()">⬇ CSV</button></div>'
    +'<div style="padding:.4rem .9rem;font-size:11px;color:#888">Colaboradores cujo <b>Tratamento de Verificar</b> teve decisão <b>Desconto em Folha</b>. Valide cada um (autorizar/negar com justificativa) — ao autorizar, marca quando o ponto foi ajustado. As decisões também aparecem na aba ② Validação.</div>'
    +'<div style="overflow-x:auto"><table class="tbl" style="font-size:12px"><thead><tr><th>RE</th><th>Colaborador</th><th>Observação da decisão</th><th>Data ocorrência</th><th>Decisão Verificar</th><th style="text-align:center">Validação ponto</th><th></th></tr></thead><tbody>'+linhas+'</tbody></table></div></div>';
}
function gpVerificarDecidir(id){
  var t=(_gpVerificarRows||[]).find(function(x){return x.id===id;}); if(!t) return;
  var c=gpVerificarColab(t);
  setModal('<div class="modal-bg"><div class="modal" style="max-width:430px">'
    +'<h3 style="margin-bottom:.5rem">⚖️ Validar desconto em folha</h3>'
    +'<div style="font-size:12px;color:#555;margin-bottom:.5rem"><b>'+escHtml(c.nome||'—')+'</b> · RE '+escHtml(String(c.re||'—'))+'<br>📅 '+fmtD((t.data_ocorrencia||'').slice(0,10))+'</div>'
    +'<div style="background:#FCEBEB;border-radius:8px;padding:.5rem .6rem;margin-bottom:.6rem;font-size:12px;color:#A32D2D">💰 <b>Desconto em Folha</b>'+(t.decisao_obs?'<br><span style="font-size:11px">'+escHtml(t.decisao_obs)+'</span>':'')+'</div>'
    +'<div style="background:#FFFBEB;border:.5px solid #f0e0b0;border-radius:8px;padding:.5rem .6rem;margin-bottom:.6rem;font-size:11px;color:#854F0B">⚖️ <b>Autorizar</b> confirma e marca que o ponto foi ajustado. <b>Negar</b> mantém sem ajuste (justificativa obrigatória).</div>'
    +'<div class="fg" style="margin-bottom:.6rem"><label style="font-size:11px;font-weight:500">Justificativa / observação <span style="color:#A32D2D">(obrigatória ao negar)</span></label><input class="inp" id="gpvf-obs" style="width:100%" value="'+escHtml(t.ponto_ajuste_obs||'')+'" placeholder="Motivo da confirmação ou da recusa"/></div>'
    +(t.ponto_decisao?'<div style="font-size:11px;margin-bottom:.5rem;color:'+(t.ponto_decisao==='negado'?'#A32D2D':'#3B6D11')+'">Decisão atual: <b>'+(t.ponto_decisao==='negado'?'🚫 Negado':'✓ Autorizado')+'</b>'+(t.ponto_ajuste_por?' por '+escHtml(t.ponto_ajuste_por):'')+'</div>':'')
    +'<div class="ma" style="flex-wrap:wrap;gap:6px">'
    +(t.ponto_decisao?'<button class="btn" style="color:#888;border-color:#ccc" onclick="gpVerificarSalvarDecisao(\''+id+'\',\'reabrir\')">↩ Reabrir</button>':'')
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn" style="color:#A32D2D;border-color:#A32D2D" onclick="gpVerificarSalvarDecisao(\''+id+'\',\'negado\')">🚫 Negar</button>'
    +'<button class="btn btn-pri" style="background:#3B6D11;border-color:#3B6D11" onclick="gpVerificarSalvarDecisao(\''+id+'\',\'autorizado\')">✅ Autorizar (ponto ajustado)</button>'
    +'</div></div></div>');
}
function gpVerificarSalvarDecisao(id,decisao){
  var t=(_gpVerificarRows||[]).find(function(x){return x.id===id;}); if(!t) return;
  var obs=((document.getElementById('gpvf-obs')||{}).value||'').trim();
  var payload;
  if(decisao==='reabrir'){
    payload={ponto_decisao:null,ponto_ajustado:false,ponto_ajuste_obs:null,ponto_ajuste_por:null,ponto_ajuste_em:null};
  } else if(decisao==='negado'){
    if(!obs){ progShowToast('⚠ Ao negar, a justificativa é obrigatória.','erro'); return; }
    payload={ponto_decisao:'negado',ponto_ajustado:false,ponto_ajuste_obs:obs,ponto_ajuste_por:(usuarioLogado?usuarioLogado.nome:''),ponto_ajuste_em:new Date().toISOString()};
  } else {
    payload={ponto_decisao:'autorizado',ponto_ajustado:true,ponto_ajuste_obs:obs,ponto_ajuste_por:(usuarioLogado?usuarioLogado.nome:''),ponto_ajuste_em:new Date().toISOString()};
  }
  Object.assign(t,payload);
  var vt=(_vtDados||[]).find(function(x){return x.id===id;}); if(vt) Object.assign(vt,payload);
  if(!DEMO) sbUpdate('verificar_tratamentos',payload,'id=eq.'+id).catch(function(){ progShowToast('❌ Erro ao salvar. Rodou o sql_verificar_ponto_ajuste.sql?','erro'); });
  closeModal();
  progShowToast(decisao==='negado'?'🚫 Desconto negado — sem ajuste de ponto.':decisao==='reabrir'?'↩ Reaberto.':'✅ Autorizado — ponto marcado como ajustado.');
  gpRenderAjuste();
}
function gpExportVerificar(){
  var idSet={}; (_gp.escopo||[]).forEach(function(c){ idSet[c.id]=true; });
  var rows=(_gpVerificarRows||[]).filter(function(t){ return idSet[t.colaborador_id] && (t.decisoes||'').split(',').indexOf('desconto_folha')>=0; });
  var csv='RE,Colaborador,Observacao,Data ocorrencia,Decisoes,Status\n';
  csv+=rows.map(function(t){ var c=gpVerificarColab(t); return [(c.re||''),'"'+(c.nome||'').replace(/"/g,'""')+'"','"'+(t.decisao_obs||'').replace(/"/g,'""')+'"',(t.data_ocorrencia||'').slice(0,10),'"'+(t.decisoes||'')+'"',(t.status||'')].join(','); }).join('\n');
  var a=document.createElement('a'); a.href='data:text/csv;charset=utf-8,'+encodeURIComponent(csv); a.download='verificar_desconto_folha_'+_gp.ini+'_a_'+_gp.fim+'.csv'; a.click();
}
function gpAjusteAntecipHtml(regs){
  var dias=gpDiasPeriodo();
  // colaboradores que anteciparam ao menos 1 dia no período
  var byRe={};
  regs.forEach(function(r){ var k=String(r.re); (byRe[k]||(byRe[k]={}))[(r.data||'').slice(0,10)]=r; });
  var resRe=Object.keys(byRe).filter(function(re){
    return dias.some(function(d){ var r=byRe[re][d]; return r && (r.minutos_antecipacao||0)>_gpAntecMin; });
  });
  resRe.sort(function(a,b){ var ca=gpColabByRe(a)||{},cb=gpColabByRe(b)||{}; return (ca.nome||'').localeCompare(cb.nome||'','pt-BR'); });
  // Detectar dias com batida e previsto MAS sem cálculo de antecipação (sync antigo) — evita confusão
  var diasSet={}; dias.forEach(function(d){diasSet[d]=true;});
  var naoCalc=0;
  regs.forEach(function(r){ if(diasSet[(r.data||'').slice(0,10)] && r.entrada && r.horario_entrada && (r.minutos_antecipacao==null)) naoCalc++; });
  var avisoSync = naoCalc>0 ? '<div style="background:#FFF7E6;border:.5px solid #f0d088;border-radius:8px;padding:.6rem .8rem;margin-bottom:.75rem;font-size:12px;color:#854F0B"><b>⚠ '+naoCalc+' registro(s)</b> têm batida e horário previsto, mas o cálculo de antecipação <b>ainda não foi feito</b> (sincronização anterior à versão atual). Vá na aba <b>🔄 Sincronizar</b> e sincronize o período para o sistema recalcular e destacar as antecipações de todos os dias.</div>' : '';
  if(!resRe.length){ return avisoSync+'<div class="card" style="padding:2rem;text-align:center;color:#3B6D11">✅ Nenhuma antecipação (> '+_gpAntecMin+' min) calculada no período '+escHtml(gpPeriodoLabel())+'.</div>'; }
  var head='<tr><th style="position:sticky;left:0;background:#f5f5f3;z-index:2">RE</th><th style="position:sticky;left:40px;background:#f5f5f3;z-index:2">Colaborador</th>'
    +dias.map(function(d){ return '<th style="text-align:center;font-size:10px;min-width:42px">'+d.slice(8,10)+'</th>'; }).join('')+'</tr>';
  var body=resRe.map(function(re){
    var c=gpColabByRe(re)||{};
    var tds=dias.map(function(d){
      var r=byRe[re][d];
      if(!r||!_gpEntOrig(r)) return '<td style="text-align:center;color:#ddd">·</td>';
      var antec=(r.minutos_antecipacao||0)>_gpAntecMin;
      var orig=_gpEntOrig(r);
      if(r.ajuste_decisao==='autorizado'){
        return '<td style="text-align:center;background:#EAF3DE;cursor:pointer" title="Autorizado: '+escHtml(orig)+' → '+escHtml(r.entrada_ajustada||'')+'" onclick="gpAbrirAjuste(\''+re+'\',\''+d+'\')"><span style="font-size:10px;color:#3B6D11;font-weight:700">'+escHtml(r.entrada_ajustada||orig)+' ✓</span></td>';
      }
      if(r.ajuste_decisao==='negado'){
        return '<td style="text-align:center;background:#FCEBEB;cursor:pointer" title="Negado — '+escHtml(r.ajuste_obs||'sem justificativa')+'" onclick="gpAbrirAjuste(\''+re+'\',\''+d+'\')"><span style="font-size:10px;color:#A32D2D;font-weight:700;text-decoration:line-through">'+escHtml(orig)+'</span><div style="font-size:8px;color:#A32D2D">🚫 negado</div></td>';
      }
      if(antec){
        return '<td style="text-align:center;background:#FEF3E2;cursor:pointer" title="Antecipou '+r.minutos_antecipacao+' min — clique para VALIDAR (prev '+(r.horario_entrada||'—')+')" onclick="gpAbrirAjuste(\''+re+'\',\''+d+'\')"><span style="font-size:10px;color:#854F0B;font-weight:700">'+escHtml(orig)+'</span><div style="font-size:8px;color:#C97A1F">-'+r.minutos_antecipacao+'m ⏳</div></td>';
      }
      return '<td style="text-align:center;font-size:10px;color:#888">'+escHtml(orig)+'</td>';
    }).join('');
    return '<tr><td style="font-weight:600;position:sticky;left:0;background:#fff;z-index:1">'+escHtml(re)+'</td>'
      +'<td style="font-weight:500;position:sticky;left:40px;background:#fff;z-index:1;white-space:nowrap">'+escHtml(c.nome||'—')+'</td>'+tds+'</tr>';
  }).join('');
  return avisoSync+'<div class="card"><div class="ch"><span class="ct">⚠️ Antecipações de entrada — '+escHtml(gpPeriodoLabel())+' ('+resRe.length+' colaboradores)</span>'
    +'<button class="btn btn-sm" onclick="gpExportAntecip()">⬇ CSV</button></div>'
    +'<div style="padding:.4rem .9rem;font-size:11px;color:#888"><span style="background:#FEF3E2;padding:0 4px;border-radius:3px;color:#854F0B">laranja ⏳</span> = antecipou, aguardando validação (clique para autorizar/negar). <span style="background:#EAF3DE;padding:0 4px;border-radius:3px;color:#3B6D11">verde ✓</span> = autorizado/ajustado. <span style="background:#FCEBEB;padding:0 4px;border-radius:3px;color:#A32D2D">vermelho 🚫</span> = negado (com justificativa).</div>'
    +'<div style="overflow:auto;max-height:65vh"><table class="tbl" style="font-size:11px;border-collapse:separate;border-spacing:0"><thead>'+head+'</thead><tbody>'+body+'</tbody></table></div></div>';
}
// Itens de validação unificados (Antecipação + Verificar) — fonte única para tela e CSV
function gpValidacaoItens(regs){
  var itens=[];
  // Origem 1: Antecipações tratadas (ponto_registros)
  (regs||[]).filter(function(r){ return r.ponto_tratado; }).forEach(function(r){
    var c=gpColabByRe(r.re)||{}; var neg=r.ajuste_decisao==='negado';
    itens.push({ origem:'Antecipação', re:String(r.re), nome:c.nome||'—', data:(r.data||'').slice(0,10),
      de:_gpEntOrig(r)||'—', para:(neg?null:(r.entrada_ajustada||'—')), decisao:(r.ajuste_decisao||'autorizado'),
      obs:r.ajuste_obs||'', por:r.ajuste_por||'', em:(r.ajuste_em||'').slice(0,10) });
  });
  // Origem 2: Verificar (Desconto em Folha) com decisão de ponto
  var idSet={}; (_gp.escopo||[]).forEach(function(cc){ idSet[cc.id]=true; });
  (_gpVerificarRows||[]).filter(function(t){
    return idSet[t.colaborador_id] && (t.decisoes||'').split(',').indexOf('desconto_folha')>=0 && t.ponto_decisao;
  }).forEach(function(t){
    var c=gpVerificarColab(t);
    itens.push({ origem:'Verificar', re:String(c.re||'—'), nome:c.nome||'—', data:(t.data_ocorrencia||'').slice(0,10),
      de:'💰 Desconto em Folha', para:null, decisao:t.ponto_decisao,
      obs:t.ponto_ajuste_obs||t.decisao_obs||'', por:t.ponto_ajuste_por||'', em:(t.ponto_ajuste_em||'').slice(0,10) });
  });
  itens.sort(function(a,b){ return (a.data||'').localeCompare(b.data||''); });
  return itens;
}
function gpAjusteValidacaoHtml(regs){
  // garantir dados do Verificar carregados (para incluir na validação)
  if(_gpVerificarKey!==(_gp.ini+'_'+_gp.fim) || !_gpVerificarRows){
    gpCarregarVerificar(function(){ if(_gp.aba==='ajuste'&&_gpAjusteView==='validacao') gpRenderAjuste(); });
  }
  var itens=gpValidacaoItens(regs);
  if(!itens.length){ return '<div class="card" style="padding:2rem;text-align:center;color:#aaa">Nenhum ajuste registrado no período. Trate as antecipações na aba ① ou valide os descontos na aba ③.</div>'; }
  var nAut=itens.filter(function(x){return x.decisao==='autorizado';}).length;
  var nNeg=itens.filter(function(x){return x.decisao==='negado';}).length;
  var ORIG={'Antecipação':{bg:'#FEF3E2',c:'#854F0B'},'Verificar':{bg:'#FCEBEB',c:'#A32D2D'}};
  var linhas=itens.map(function(x){
    var negado=x.decisao==='negado'; var o=ORIG[x.origem]||{bg:'#eee',c:'#555'};
    return '<tr><td style="font-weight:600">'+escHtml(x.re)+'</td><td style="font-weight:500">'+escHtml(x.nome)+'</td>'
      +'<td>'+fmtD(x.data)+'</td>'
      +'<td style="text-align:center"><span style="background:'+o.bg+';color:'+o.c+';border-radius:5px;padding:1px 7px;font-size:10px;font-weight:600">'+x.origem+'</span></td>'
      +'<td style="text-align:center;color:#A32D2D'+(negado||x.origem==='Verificar'?'':';text-decoration:line-through')+'">'+escHtml(x.de)+'</td>'
      +'<td style="text-align:center;color:#3B6D11;font-weight:700">'+(x.para==null?'<span style="color:#aaa">'+(negado?'— mantida':'—')+'</span>':escHtml(x.para))+'</td>'
      +'<td style="text-align:center">'+(negado?'<span class="bdg danger" style="font-size:10px">🚫 Negado</span>':'<span class="bdg ok" style="font-size:10px">✓ Autorizado</span>')+'</td>'
      +'<td style="font-size:11px;color:'+(negado?'#A32D2D':'#888')+'">'+escHtml(x.obs||(negado?'(sem justificativa)':''))+'</td>'
      +'<td style="font-size:10px;color:#aaa">'+escHtml(x.por||'')+(x.em?'<br>'+fmtD(x.em):'')+'</td></tr>';
  }).join('');
  return '<div class="card"><div class="ch"><span class="ct">✅ Validação dos ajustes — '+escHtml(gpPeriodoLabel())+' ('+itens.length+' · '+nAut+' autorizados · '+nNeg+' negados)</span>'
    +'<button class="btn btn-sm" onclick="gpExportValidacao()">⬇ CSV</button></div>'
    +'<div style="padding:.4rem .9rem;font-size:11px;color:#888">Inclui ajustes de <b>Antecipação</b> (aba ①) e de <b>Verificar — Desconto em Folha</b> (aba ③). A coluna <b>Origem</b> identifica cada um.</div>'
    +'<div style="overflow-x:auto"><table class="tbl" style="font-size:12px"><thead><tr><th>RE</th><th>Colaborador</th><th>Data</th><th style="text-align:center">Origem</th><th style="text-align:center">De</th><th style="text-align:center">Para</th><th style="text-align:center">Decisão</th><th>Justificativa / Obs.</th><th>Validado por</th></tr></thead><tbody>'+linhas+'</tbody></table></div></div>';
}
function gpAbrirAjuste(re,data){
  var r=(_gp.registros||[]).find(function(x){ return String(x.re)===String(re) && (x.data||'').slice(0,10)===data; });
  if(!r){ progShowToast('Registro não encontrado.','erro'); return; }
  var c=gpColabByRe(re)||{};
  var orig=_gpEntOrig(r);
  var prev=r.horario_entrada||'';
  setModal('<div class="modal-bg"><div class="modal" style="max-width:420px">'
    +'<h3 style="margin-bottom:.5rem">✏️ Ajustar batida</h3>'
    +'<div style="font-size:12px;color:#555;margin-bottom:.6rem"><b>'+escHtml(c.nome||('RE '+re))+'</b> · RE '+escHtml(String(re))+'<br>📅 '+fmtD(data)+'</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:.6rem">'
    +'<div style="background:#FEF3E2;border-radius:8px;padding:.5rem;text-align:center"><div style="font-size:10px;color:#888">Batida original</div><div style="font-size:18px;font-weight:700;color:#854F0B">'+escHtml(orig||'—')+'</div>'+(r.minutos_antecipacao?'<div style="font-size:10px;color:#C97A1F">-'+r.minutos_antecipacao+' min</div>':'')+'</div>'
    +'<div style="background:#EBF4FD;border-radius:8px;padding:.5rem;text-align:center"><div style="font-size:10px;color:#888">Previsto</div><div style="font-size:18px;font-weight:700;color:#185FA5">'+escHtml(prev||'—')+'</div></div>'
    +'</div>'
    +'<div style="background:#FFFBEB;border:.5px solid #f0e0b0;border-radius:8px;padding:.5rem .6rem;margin-bottom:.6rem;font-size:11px;color:#854F0B">⚖️ Validação humana: <b>autorize</b> para aplicar o ajuste, ou <b>negue</b> (mantém a batida original) justificando o motivo.</div>'
    +'<div class="fg" style="margin-bottom:.5rem"><label style="font-size:11px;font-weight:500">Nova batida (se autorizar)</label><input class="inp" id="gpaj-ent" type="time" style="width:100%" value="'+escHtml((r.entrada_ajustada||prev||orig||'').slice(0,5))+'"/></div>'
    +'<div class="fg" style="margin-bottom:.6rem"><label style="font-size:11px;font-weight:500">Justificativa / observação <span style="color:#A32D2D">(obrigatória ao negar)</span></label><input class="inp" id="gpaj-obs" style="width:100%" value="'+escHtml(r.ajuste_obs||'')+'" placeholder="Motivo do ajuste ou da recusa"/></div>'
    +(r.ajuste_decisao?'<div style="font-size:11px;margin-bottom:.5rem;color:'+(r.ajuste_decisao==='negado'?'#A32D2D':'#3B6D11')+'">Decisão atual: <b>'+(r.ajuste_decisao==='negado'?'🚫 Negado':'✓ Autorizado')+'</b>'+(r.ajuste_por?' por '+escHtml(r.ajuste_por):'')+'</div>':'')
    +'<div class="ma" style="flex-wrap:wrap;gap:6px">'
    +(r.ponto_tratado?'<button class="btn" style="color:#888;border-color:#ccc" onclick="gpReverterAjuste(\''+re+'\',\''+data+'\')">↩ Reabrir</button>':'')
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn" style="color:#A32D2D;border-color:#A32D2D" onclick="gpDecidirAjuste(\''+re+'\',\''+data+'\',\'negado\')">🚫 Negar</button>'
    +'<button class="btn btn-pri" style="background:#3B6D11;border-color:#3B6D11" onclick="gpDecidirAjuste(\''+re+'\',\''+data+'\',\'autorizado\')">✅ Autorizar e aplicar</button>'
    +'</div></div></div>');
}
function gpDecidirAjuste(re,data,decisao){
  var r=(_gp.registros||[]).find(function(x){ return String(x.re)===String(re) && (x.data||'').slice(0,10)===data; });
  if(!r) return;
  var nova=((document.getElementById('gpaj-ent')||{}).value||'').trim();
  var obs=((document.getElementById('gpaj-obs')||{}).value||'').trim();
  if(!r.entrada_original) r.entrada_original=r.entrada||'';  // preserva original sempre
  var payload;
  if(decisao==='negado'){
    if(!obs){ progShowToast('⚠ Ao negar, a justificativa é obrigatória.','erro'); return; }
    r.entrada_ajustada=null; r.ajuste_decisao='negado'; r.ponto_tratado=true; r.ajuste_obs=obs;
    payload={ entrada_original:r.entrada_original, entrada_ajustada:null, ajuste_decisao:'negado', ponto_tratado:true, ajuste_obs:obs };
  } else {
    if(!nova){ progShowToast('⚠ Informe a nova batida para autorizar.','erro'); return; }
    r.entrada_ajustada=nova; r.ajuste_decisao='autorizado'; r.ponto_tratado=true; r.ajuste_obs=obs;
    payload={ entrada_original:r.entrada_original, entrada_ajustada:nova, ajuste_decisao:'autorizado', ponto_tratado:true, ajuste_obs:obs };
  }
  r.ajuste_por=usuarioLogado?usuarioLogado.nome:''; r.ajuste_em=new Date().toISOString();
  payload.ajuste_por=r.ajuste_por; payload.ajuste_em=r.ajuste_em;
  if(!DEMO){
    var filtro = r.id ? 'id=eq.'+r.id : 're=eq.'+re+'&data=eq.'+data;
    sbUpdate('ponto_registros',payload,filtro).catch(function(){ progShowToast('❌ Erro ao salvar. Rodou o sql_ponto_ajustes.sql?','erro'); });
  }
  closeModal();
  progShowToast(decisao==='negado' ? '🚫 Ajuste negado — batida original mantida.' : '✅ Ajuste autorizado — '+_gpEntOrig(r)+' → '+nova+' (original preservada).');
  gpRenderAjuste();
}
function gpReverterAjuste(re,data){
  var r=(_gp.registros||[]).find(function(x){ return String(x.re)===String(re) && (x.data||'').slice(0,10)===data; });
  if(!r) return;
  r.entrada_ajustada=null; r.ponto_tratado=false; r.ajuste_obs=null; r.ajuste_decisao=null;
  var payload={ entrada_ajustada:null, ponto_tratado:false, ajuste_obs:null, ajuste_decisao:null, ajuste_por:null, ajuste_em:null };
  if(!DEMO){ var filtro=r.id?'id=eq.'+r.id:'re=eq.'+re+'&data=eq.'+data; sbUpdate('ponto_registros',payload,filtro).catch(function(){}); }
  closeModal(); progShowToast('↩ Reaberto — voltou para pendente de validação.'); gpRenderAjuste();
}
function gpExportAntecip(){
  var dias=gpDiasPeriodo(); var regs=_gp.registros||[]; var byRe={};
  regs.forEach(function(r){ var k=String(r.re); (byRe[k]||(byRe[k]={}))[(r.data||'').slice(0,10)]=r; });
  var resRe=Object.keys(byRe).filter(function(re){ return dias.some(function(d){ var r=byRe[re][d]; return r&&(r.minutos_antecipacao||0)>_gpAntecMin; }); });
  var csv='RE,Colaborador,'+dias.map(function(d){return d.slice(8,10)+'/'+d.slice(5,7);}).join(',')+'\n';
  csv+=resRe.map(function(re){ var c=gpColabByRe(re)||{}; return [re,'"'+(c.nome||'').replace(/"/g,'""')+'"'].concat(dias.map(function(d){ var r=byRe[re][d]; return r?_gpEntAtual(r):''; })).join(','); }).join('\n');
  var a=document.createElement('a'); a.href='data:text/csv;charset=utf-8,'+encodeURIComponent(csv); a.download='antecipacoes_'+_gp.ini+'_a_'+_gp.fim+'.csv'; a.click();
}
function gpExportValidacao(){
  var itens=gpValidacaoItens(_gp.registros||[]);
  var csv='RE,Colaborador,Data,Origem,De,Para,Decisao,Justificativa,Validado por\n';
  csv+=itens.map(function(x){ return [x.re,'"'+(x.nome||'').replace(/"/g,'""')+'"',x.data,x.origem,'"'+String(x.de).replace(/"/g,'""')+'"',(x.para||''),x.decisao,'"'+(x.obs||'').replace(/"/g,'""')+'"','"'+(x.por||'').replace(/"/g,'""')+'"'].join(','); }).join('\n');
  var a=document.createElement('a'); a.href='data:text/csv;charset=utf-8,'+encodeURIComponent(csv); a.download='validacao_ajustes_'+_gp.ini+'_a_'+_gp.fim+'.csv'; a.click();
}

function _gpCard(icon,label,val,cor,sub){
  return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:10px;padding:.8rem;display:flex;flex-direction:column;gap:3px">'
    +'<div style="font-size:17px">'+icon+'</div><div style="font-size:11px;color:#888">'+label+'</div>'
    +'<div style="font-size:21px;font-weight:700;color:'+(cor||'#1a1a18')+'">'+val+'</div>'
    +(sub?'<div style="font-size:10px;color:#aaa">'+sub+'</div>':'')+'</div>';
}
function _gpLista(titulo,cor,linhas,vazio){
  return '<div class="card" style="margin-bottom:.75rem"><div class="ch"><span class="ct" style="color:'+cor+'">'+titulo+'</span></div>'
    +(linhas.length?'<table class="tbl" style="font-size:12px"><tbody>'+linhas.join('')+'</tbody></table>'
      :'<div style="padding:1rem;text-align:center;color:#aaa;font-size:12px">'+(vazio||'Nenhum')+'</div>')+'</div>';
}

function gpRenderDashboard(){
  var el=document.getElementById('gp-tab-dashboard'); if(!el) return;
  var hoje=dataHojeLocal(), regs=_gp.registros, escopo=_gp.escopo||[];
  var regHoje=regs.filter(function(r){return (r.data||'').slice(0,10)===hoje;});
  var presentesHoje=regHoje.filter(function(r){return r.entrada;}).length;
  var ausentesHoje=regHoje.filter(function(r){return !r.entrada && (r.status==='falta'||r.tipo_dia==='falta');}).length;
  var antecip=regHoje.filter(function(r){return (r.minutos_antecipacao||0)>5;});
  var antecipMin=antecip.reduce(function(s,r){return s+(r.minutos_antecipacao||0);},0);
  var feriasReSet={}, suspReSet={};
  regs.forEach(function(r){ if(r.ferias||r.tipo_dia==='ferias') feriasReSet[String(r.re)]=true; if(r.suspensao||r.tipo_dia==='suspensao') suspReSet[String(r.re)]=true; });
  var ausMot=regs.filter(function(r){return r.ausencia_motivada && !pontoEhAbonoCurso(r);});
  var abonoCurso=regs.filter(function(r){return pontoEhAbonoCurso(r);});
  var heMap=gpHEporColab(); var heTotal=Object.keys(heMap).reduce(function(s,k){return s+heMap[k];},0);
  var acima=[];
  escopo.forEach(function(c){ var he=heMap[String(c.re)]||0; var lim=gpLimiteCargo(c.cargo,c.contrato_id); if(lim!==null&&lim>0&&he>lim) acima.push({c:c,he:he,lim:lim,exc:he-lim}); });
  acima.sort(function(a,b){return b.exc-a.exc;});

  var cards='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(135px,1fr));gap:10px;margin-bottom:1rem">'
    +_gpCard('👥','Colaboradores ativos',escopo.length,'#185FA5',_gp.cont==='__todos__'?'na empresa':'no contrato')
    +_gpCard('✅','Presentes hoje',presentesHoje,'#3B6D11',fmtD(hoje))
    +_gpCard('❌','Ausentes hoje',ausentesHoje,ausentesHoje?'#A32D2D':'#3B6D11','')
    +'<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:10px;padding:.8rem;display:flex;flex-direction:column;gap:3px">'
      +'<div style="font-size:17px">⚠️</div><div style="font-size:11px;color:#888">Entrada antecipada hoje</div>'
      +'<div style="display:flex;gap:16px;align-items:baseline">'
        +'<div><span style="font-size:21px;font-weight:700;color:'+(antecip.length?'#854F0B':'#3B6D11')+'">'+antecip.length+'</span><span style="font-size:10px;color:#aaa"> colab</span></div>'
        +'<div><span style="font-size:21px;font-weight:700;color:'+(antecipMin?'#854F0B':'#3B6D11')+'">'+antecipMin+'</span><span style="font-size:10px;color:#aaa"> min</span></div>'
      +'</div><div style="font-size:10px;color:#aaa">>5 min antes do previsto</div></div>'
    +_gpCard('🏖','Férias (mês)',Object.keys(feriasReSet).length,'#185FA5','colaboradores')
    +_gpCard('⛔','Suspensão (mês)',Object.keys(suspReSet).length,suspReSet&&Object.keys(suspReSet).length?'#A32D2D':'#3B6D11','')
    +_gpCard('📋','Ausência motivada',ausMot.length,'#854F0B','dias no mês')
    +_gpCard('📚','Abono Curso',abonoCurso.length,'#533AB7','dias no mês')
    +_gpCard('⏰','Horas extras (mês)',gpHHMM(heTotal),'#534AB7','total')
    +_gpCard('🔴','Acima da meta HE',acima.length,acima.length?'#A32D2D':'#3B6D11','colaboradores')
    +'</div>';

  // listas
  var lAntec=antecip.map(function(r){ var c=gpColabByRe(r.re)||{}; return '<tr><td style="font-weight:500">'+escHtml(c.nome||('RE '+r.re))+'</td><td style="font-size:11px;color:#888">RE '+escHtml(String(r.re))+' · '+escHtml(c.cargo||'')+'</td><td style="text-align:right">prev '+(r.horario_entrada||'—')+' · bateu '+(r.entrada||'—')+'</td><td style="text-align:right;color:#854F0B;font-weight:700">'+r.minutos_antecipacao+' min</td></tr>'; });
  var lAcima=acima.map(function(x){ return '<tr><td style="font-weight:500">'+escHtml(x.c.nome)+'</td><td style="font-size:11px;color:#888">RE '+escHtml(String(x.c.re))+' · '+escHtml(x.c.cargo||'')+'</td><td style="text-align:right">'+gpHHMM(x.he)+' / meta '+gpHHMM(x.lim)+'</td><td style="text-align:right;color:#A32D2D;font-weight:700">+'+gpHHMM(x.exc)+'</td></tr>'; });
  // ausências motivadas agrupadas por colab
  var ausPorColab={}; ausMot.forEach(function(r){ var k=String(r.re); (ausPorColab[k]||(ausPorColab[k]={re:k,motivos:{},dias:0})); ausPorColab[k].dias++; ausPorColab[k].motivos[r.ausencia_motivo||r.ausencia_tipo||'—']=true; });
  var lAus=Object.keys(ausPorColab).map(function(k){ var a=ausPorColab[k]; var c=gpColabByRe(k)||{}; return '<tr><td style="font-weight:500">'+escHtml(c.nome||('RE '+k))+'</td><td style="font-size:11px;color:#888">RE '+escHtml(k)+'</td><td>'+escHtml(Object.keys(a.motivos).join(', '))+'</td><td style="text-align:right;font-weight:700">'+a.dias+' dia(s)</td></tr>'; });
  var abonoPorColab={}; abonoCurso.forEach(function(r){ var k=String(r.re); (abonoPorColab[k]||(abonoPorColab[k]={re:k,motivos:{},dias:0})); abonoPorColab[k].dias++; abonoPorColab[k].motivos[r.ausencia_motivo||r.ausencia_tipo||'Abono Curso']=true; });
  var lAbono=Object.keys(abonoPorColab).map(function(k){ var a=abonoPorColab[k]; var c=gpColabByRe(k)||{}; return '<tr><td style="font-weight:500">'+escHtml(c.nome||('RE '+k))+'</td><td style="font-size:11px;color:#888">RE '+escHtml(k)+'</td><td>'+escHtml(Object.keys(a.motivos).join(', '))+'</td><td style="text-align:right;font-weight:700">'+a.dias+' dia(s)</td></tr>'; });
  // ferias/suspensao ativas
  var lFer=Object.keys(feriasReSet).map(function(k){ var c=gpColabByRe(k)||{}; var dias=regs.filter(function(r){return String(r.re)===k&&(r.ferias||r.tipo_dia==='ferias');}).map(function(r){return (r.data||'').slice(0,10);}).sort(); return '<tr><td style="font-weight:500">'+escHtml(c.nome||('RE '+k))+'</td><td style="font-size:11px;color:#888">RE '+escHtml(k)+'</td><td>'+(dias.length?fmtD(dias[0])+' a '+fmtD(dias[dias.length-1]):'—')+'</td><td style="text-align:right">'+dias.length+' dia(s)</td></tr>'; });

  // quebra por contrato (modo empresa)
  var lContrato='';
  if(_gp.cont==='__todos__'){
    var porC={}; escopo.forEach(function(c){ var k=c.contrato_id||'—'; (porC[k]||(porC[k]={cid:k,colabs:0,he:0})); porC[k].colabs++; porC[k].he+=heMap[String(c.re)]||0; });
    var cnome={}; (contratos||[]).forEach(function(c){ cnome[c.id]=c.nome; });
    var arrC=Object.keys(porC).map(function(k){return porC[k];}).sort(function(a,b){return b.he-a.he;});
    var linhasC=arrC.map(function(x){ return '<tr><td style="font-weight:500">'+escHtml(cnome[x.cid]||'Sem contrato')+'</td><td style="text-align:center;color:#888">'+x.colabs+'</td><td style="text-align:right;color:#534AB7;font-weight:700">'+gpHHMM(x.he)+'</td></tr>'; });
    lContrato='<div class="card" style="margin-bottom:.75rem"><div class="ch"><span class="ct" style="color:#534AB7">🏢 Horas extras por contrato — '+escHtml(gpPeriodoLabel())+'</span></div><table class="tbl" style="font-size:12px"><thead><tr><th>Contrato</th><th style="text-align:center">Colabs</th><th style="text-align:right">HE no período</th></tr></thead><tbody>'+linhasC.join('')+'</tbody></table></div>';
  }
  el.innerHTML=cards
    +lContrato
    +_gpLista('⚠️ Entrada antecipada hoje (>5 min)','#854F0B',lAntec,'Nenhuma antecipação hoje')
    +_gpLista('🔴 Acima da meta de HE','#A32D2D',lAcima,'Nenhum colaborador acima da meta (ou metas não cadastradas)')
    +_gpLista('📋 Ausências motivadas (mês)','#854F0B',lAus,'Nenhuma ausência motivada')
    +_gpLista('📚 Abono Curso (mês)','#533AB7',lAbono,'Nenhum Abono Curso no período')
    +_gpLista('🏖 Férias no mês','#185FA5',lFer,'Ninguém de férias no mês');
}

function gpRegSetModo(m){ _gp.regModo=m; gpRenderRegistros(); }
function gpRegFiltrar(){
  _gp.regFiltro=(document.getElementById('gp-reg-busca')||{}).value||'';
  gpRenderRegistros();
  var bi=document.getElementById('gp-reg-busca');
  if(bi){ bi.focus(); try{ bi.setSelectionRange(bi.value.length,bi.value.length); }catch(e){} }
}
function gpRegFiltrados(){
  var f=(_gp.regFiltro||'').toLowerCase().trim();
  if(!f) return _gp.registros.slice();
  return _gp.registros.filter(function(r){ var c=gpColabByRe(r.re)||{}; return (c.nome||'').toLowerCase().indexOf(f)>=0 || String(r.re).indexOf(f)>=0; });
}
function gpRenderRegistros(){
  var el=document.getElementById('gp-tab-registros'); if(!el) return;
  var modo=_gp.regModo||'diario';
  var btnA=(modo==='diario'?'background:#1a1a18;color:#fff;border-color:#1a1a18':'');
  var btnB=(modo==='acumulado'?'background:#1a1a18;color:#fff;border-color:#1a1a18':'');
  var ctrl='<div class="card" style="margin-bottom:.5rem;padding:.6rem .85rem;display:flex;gap:10px;flex-wrap:wrap;align-items:center">'
    +'<div style="display:flex;gap:4px">'
    +'<button class="btn btn-sm" onclick="gpRegSetModo(\'diario\')" style="'+btnA+'">📅 Diário</button>'
    +'<button class="btn btn-sm" onclick="gpRegSetModo(\'acumulado\')" style="'+btnB+'">Σ Acumulado/colaborador</button>'
    +'</div>'
    +'<input class="inp" id="gp-reg-busca" placeholder="🔍 Filtrar colaborador (nome ou RE)" value="'+escHtml(_gp.regFiltro||'')+'" oninput="gpRegFiltrar()" style="width:250px;font-size:12px"/>'
    +'<button class="btn btn-sm" onclick="gpExportCsv()" style="margin-left:auto">📥 CSV</button>'
    +'</div>';
  var regs=gpRegFiltrados();

  if(modo==='acumulado'){
    var ag={};
    regs.forEach(function(r){ var k=String(r.re); var a=ag[k]||(ag[k]={re:k,he:0,faltas:0,ausencias:0,abonoCurso:0,ferias:0,folgas:0,trab:0,antecCount:0,antecMin:0});
      a.he+=parseFloat(r.horas_extras)||0;
      if(r.tipo_dia==='falta'||r.status==='falta') a.faltas++;
      if(pontoEhAbonoCurso(r)) a.abonoCurso++;
      else if(r.ausencia_motivada) a.ausencias++;
      if(r.ferias||r.tipo_dia==='ferias') a.ferias++;
      if(r.tipo_dia==='folga') a.folgas++;
      if(r.entrada) a.trab++;
      if((r.minutos_antecipacao||0)>5){ a.antecCount++; a.antecMin+=r.minutos_antecipacao; }
    });
    var rows=Object.keys(ag).map(function(k){ return {a:ag[k], c:gpColabByRe(k)||{}}; })
      .sort(function(x,y){ return (x.c.nome||'').localeCompare(y.c.nome||''); });
    var headA='<tr><th>Colaborador</th><th>RE</th><th>Cargo</th><th style="text-align:center">Dias trab.</th><th style="text-align:right">HE mês</th><th style="text-align:center">Faltas</th><th style="text-align:center">Aus. mot.</th><th style="text-align:center">Abono Curso</th><th style="text-align:center">Férias</th><th style="text-align:center">Antecip. (qtd/min)</th></tr>';
    var linhasA=rows.map(function(o){ var a=o.a,c=o.c; return '<tr><td style="font-weight:500">'+escHtml(c.nome||'—')+'</td><td style="font-family:monospace">'+escHtml(a.re)+'</td><td style="font-size:11px">'+escHtml(c.cargo||'')+'</td>'
      +'<td style="text-align:center">'+a.trab+'</td>'
      +'<td style="text-align:right;color:#534AB7;font-weight:'+(a.he?'700':'400')+'">'+(a.he?gpHHMM(a.he):'—')+'</td>'
      +'<td style="text-align:center;color:'+(a.faltas?'#A32D2D':'#555')+';font-weight:'+(a.faltas?'700':'400')+'">'+a.faltas+'</td>'
      +'<td style="text-align:center">'+(a.ausencias||'—')+'</td>'
      +'<td style="text-align:center;color:'+(a.abonoCurso?'#533AB7':'#555')+';font-weight:'+(a.abonoCurso?'700':'400')+'">'+(a.abonoCurso||'—')+'</td>'
      +'<td style="text-align:center">'+(a.ferias||'—')+'</td>'
      +'<td style="text-align:center;color:'+(a.antecCount?'#854F0B':'#555')+'">'+(a.antecCount?(a.antecCount+' / '+a.antecMin+' min'):'—')+'</td></tr>'; });
    el.innerHTML=ctrl+'<div class="card"><div class="ch"><span class="ct">Σ Acumulado por colaborador — '+escHtml(gpPeriodoLabel())+' ('+rows.length+' colaboradores)</span></div>'
      +'<div style="overflow-x:auto"><table class="tbl" style="font-size:12px"><thead>'+headA+'</thead><tbody>'
      +(linhasA.length?linhasA.join(''):'<tr><td colspan="10" style="text-align:center;color:#aaa;padding:1.5rem">Sem registros para o filtro.</td></tr>')
      +'</tbody></table></div></div>';
    return;
  }

  // ── Diário ──
  var regsD=regs.slice().sort(function(a,b){ var c=gpColabByRe(a.re)||{}, d=gpColabByRe(b.re)||{}; var n=(c.nome||'').localeCompare(d.nome||''); return n!==0?n:(a.data||'').localeCompare(b.data||''); });
  var head='<tr><th>Colaborador</th><th>RE</th><th>Cargo</th><th>Data</th><th>Entrada</th><th>Int.S</th><th>Int.R</th><th>Saída</th><th>HE dia</th><th>Tipo</th><th>Motivo</th><th>⚠️</th></tr>';
  var linhas=regsD.map(function(r){ var c=gpColabByRe(r.re)||{}; var antec=(r.minutos_antecipacao||0)>5;
    var d=(r.data||'').slice(0,10);
    var ef=typeof pontoEntradaSaidaEfetiva==='function'?pontoEntradaSaidaEfetiva(r,d):{entrada:r.entrada,saida:r.saida,intervalo_saida:r.intervalo_saida,intervalo_retorno:r.intervalo_retorno};
    var entEx=_gpEntAtual(r)||ef.entrada||'';
    var entTit=r.entrada_ajustada?('Ajustado · original '+(r.entrada_original||r.entrada||'—')):'';
    var tipoLbl=pontoEhAbonoCurso(r)?'abono_curso':(r.tipo_dia||'—');
    var tipoCor={ferias:'#185FA5',suspensao:'#A32D2D',ausencia:'#854F0B',abono_curso:'#533AB7',falta:'#A32D2D',folga:'#888',normal:'#3B6D11'}[tipoLbl]||'#555';
    return '<tr><td style="font-weight:500">'+escHtml(c.nome||'—')+'</td><td style="font-family:monospace">'+escHtml(String(r.re))+'</td><td style="font-size:11px">'+escHtml(c.cargo||'')+'</td>'
      +'<td>'+fmtD(d)+'</td>'
      +'<td'+(entTit?' title="'+escHtml(entTit)+'" style="font-weight:'+(r.entrada_ajustada?'700':'400')+'"':'')+'>'+(entEx||'—')+'</td>'
      +'<td>'+(ef.intervalo_saida||'—')+'</td><td>'+(ef.intervalo_retorno||'—')+'</td>'
      +'<td style="font-weight:600">'+(ef.saida||'—')+'</td>'
      +'<td style="text-align:right;color:#534AB7;font-weight:'+(parseFloat(r.horas_extras)?'700':'400')+'">'+(parseFloat(r.horas_extras)?gpHHMM(r.horas_extras):'—')+'</td>'
      +'<td><span style="color:'+tipoCor+';font-weight:600;font-size:11px">'+escHtml(tipoLbl)+'</span></td>'
      +'<td style="font-size:11px;color:#888">'+escHtml(r.ausencia_motivo||'')+'</td>'
      +'<td>'+(antec?'<span title="Entrada '+r.minutos_antecipacao+' min antes" style="color:#854F0B">⚠️ '+r.minutos_antecipacao+'m</span>':'')+'</td></tr>'; });
  el.innerHTML=ctrl+'<div class="card"><div class="ch"><span class="ct">📅 Registros diários — '+escHtml(gpPeriodoLabel())+' ('+regsD.length+' dias)</span></div>'
    +'<div style="overflow-x:auto"><table class="tbl" style="font-size:12px"><thead>'+head+'</thead><tbody>'
    +(linhas.length?linhas.join(''):'<tr><td colspan="12" style="text-align:center;color:#aaa;padding:1.5rem">Sem registros. Use a aba Sincronizar.</td></tr>')
    +'</tbody></table></div></div>';
}
function gpExportCsv(){
  var regs=gpRegFiltrados();
  var csv='Colaborador,RE,Cargo,Data,Entrada,IntSaida,IntRetorno,Saida,HE_dia,Tipo,Motivo,MinAntecipacao\n'
    +regs.map(function(r){ var c=gpColabByRe(r.re)||{}; var d=(r.data||'').slice(0,10);
      var ef=typeof pontoEntradaSaidaEfetiva==='function'?pontoEntradaSaidaEfetiva(r,d):{entrada:r.entrada,saida:r.saida,intervalo_saida:r.intervalo_saida,intervalo_retorno:r.intervalo_retorno};
      var tipoCsv=pontoEhAbonoCurso(r)?'abono_curso':(r.tipo_dia||'');
      return ['"'+(c.nome||'').replace(/"/g,'""')+'"',r.re,'"'+(c.cargo||'')+'"',d,_gpEntAtual(r)||ef.entrada||'',ef.intervalo_saida||'',ef.intervalo_retorno||'',ef.saida||'',r.horas_extras||0,tipoCsv,'"'+(r.ausencia_motivo||'')+'"',r.minutos_antecipacao||0].join(','); }).join('\n');
  var a=document.createElement('a'); a.href='data:text/csv;charset=utf-8,'+encodeURIComponent(csv); a.download='gestao_ponto_'+_gp.ini+'_a_'+_gp.fim+'.csv'; a.click();
}

function gpRenderLimitesHE(){
  var el=document.getElementById('gp-tab-limites'); if(!el) return;
  if(_gp.cont==='__todos__'){
    el.innerHTML='<div class="card" style="padding:1.5rem;text-align:center;color:#888"><div style="font-size:13px">⚙️ Os limites de HE são definidos <b>por contrato</b>.</div><div style="font-size:12px;margin-top:.4rem">Selecione um contrato específico no filtro acima para cadastrar/editar os tetos por cargo.</div></div>';
    return;
  }
  var cargos={}; (_gp.escopo||[]).forEach(function(c){ if(c.cargo) cargos[c.cargo]=true; });
  var limMap={}; _gp.limites.forEach(function(l){ limMap[l.cargo]=l; });
  var linhas=Object.keys(cargos).sort().map(function(cargo){
    var l=limMap[cargo]||{}; var n=(_gp.escopo||[]).filter(function(c){return c.cargo===cargo;}).length;
    return '<tr><td style="font-weight:500">'+escHtml(cargo)+'</td><td style="text-align:center;color:#888">'+n+'</td>'
      +'<td style="text-align:right"><input type="number" step="0.5" min="0" id="gphe-'+btoa(unescape(encodeURIComponent(cargo))).replace(/=/g,'')+'" value="'+(l.limite_horas_mes!=null?l.limite_horas_mes:'')+'" style="width:90px;text-align:right" class="inp"/></td>'
      +'<td style="text-align:center"><button class="btn btn-sm btn-pri" onclick="gpSalvarLimite(\''+encodeURIComponent(cargo)+'\')">💾</button></td></tr>';
  });
  el.innerHTML='<div class="card"><div class="ch"><span class="ct">⚙️ Limites de Hora Extra por Cargo (mês)</span></div>'
    +'<div style="font-size:11px;color:#888;padding:.25rem .75rem">Defina o teto de HE mensal por cargo. Acima disso o colaborador entra na lista "Acima da meta".</div>'
    +'<table class="tbl" style="font-size:12px"><thead><tr><th>Cargo</th><th style="text-align:center">Colabs</th><th style="text-align:right">Limite (h/mês)</th><th></th></tr></thead><tbody>'
    +(linhas.length?linhas.join(''):'<tr><td colspan="4" style="text-align:center;color:#aaa;padding:1rem">Nenhum cargo no contrato.</td></tr>')
    +'</tbody></table></div>';
}
function gpSalvarLimite(cargoEnc){
  var cargo=decodeURIComponent(cargoEnc);
  var inp=document.getElementById('gphe-'+btoa(unescape(encodeURIComponent(cargo))).replace(/=/g,''));
  var val=parseFloat((inp||{}).value)||0;
  var existente=_gp.limites.find(function(l){return l.cargo===cargo;});
  var payload={contrato_id:_gp.cont,cargo:cargo,limite_horas_mes:val,ativo:true};
  var p = existente ? sbUpdate('ponto_he_limites',{limite_horas_mes:val,ativo:true},'id=eq.'+existente.id)
                    : sbUpsert('ponto_he_limites',payload,'contrato_id,cargo');
  Promise.resolve(p).then(function(){ progShowToast('✅ Limite salvo: '+cargo+' = '+val+'h');
    sbFetchAll('ponto_he_limites',{filters:['contrato_id=eq.'+_gp.cont]}).then(function(rows){ _gp.limites=rows||[]; }); });
}

function gpRenderSync(){
  var el=document.getElementById('gp-tab-sync'); if(!el) return;
  var r={ini:_gp.ini,fim:_gp.fim}; var n=(_gp.escopo||[]).length;
  var ondeTxt=_gp.cont==='__todos__'?'de TODA a empresa':'do contrato';
  el.innerHTML='<div class="card"><div class="ch"><span class="ct">🔄 Sincronizar período — '+escHtml(gpPeriodoLabel())+'</span></div>'
    +'<div style="padding:1rem;font-size:13px;color:#555">'
    +'<p>Vai buscar o ponto de <b>'+n+'</b> colaboradores '+ondeTxt+' no período <b>'+fmtD(r.ini)+' a '+fmtD(r.fim)+'</b> (API Nexus) e gravar os dias do intervalo.</p>'
    +(_gp.cont==='__todos__'?'<p style="font-size:11px;color:#A32D2D">⚠ Modo empresa: '+n+' colaboradores. Prefira sincronizar por contrato ou poucos dias — o lote inteiro pode levar bastante tempo.</p>':'')
    +'<p style="font-size:11px;color:#888">Processa em lotes de 10 (evita timeout); pode levar alguns minutos. Acompanhe o progresso ao lado do botão.</p>'
    +'<button class="btn btn-pri" id="gp-btn-sync" onclick="gpSyncMes()" style="background:#3B6D11;border-color:#3B6D11">🔄 Sincronizar '+n+' colaboradores</button>'
    +'<span id="gp-sync-status" style="margin-left:10px;font-size:12px;color:#888"></span>'
    +'</div></div>';
}
function gpSyncMes(){
  var escopo=_gp.escopo||[]; if(!escopo.length){ progShowToast('Selecione um contrato com colaboradores.'); return; }
  var r={ini:_gp.ini,fim:_gp.fim};
  var mats=escopo.map(function(c){return String(c.re);}).filter(Boolean);
  var BATCH=10; // lotes pequenos para não estourar o timeout do Azure/proxy
  var btn=document.getElementById('gp-btn-sync'); var st=document.getElementById('gp-sync-status');
  if(btn) btn.disabled=true;
  var idx=0, totDias=0, totSinc=0, totErr=0;
  function proximo(){
    if(idx>=mats.length){
      if(btn){ btn.disabled=false; btn.textContent='🔄 Sincronizar '+mats.length+' colaboradores'; }
      if(st) st.textContent='✅ '+totSinc+'/'+mats.length+' colaboradores · '+totDias+' dias'+(totErr?(' · '+totErr+' falhas'):'');
      progShowToast('✅ Sync concluído: '+totDias+' dias gravados'+(totErr?(' ('+totErr+' falhas)'):''));
      gpCarregar();
      return;
    }
    var lote=mats.slice(idx, idx+BATCH);
    var ate=Math.min(idx+lote.length, mats.length);
    if(btn) btn.textContent='⏳ '+ate+'/'+mats.length+'...';
    if(st) st.textContent='Sincronizando '+(idx+1)+'–'+ate+' de '+mats.length+' (Nexus)...';
    pontoFetchApi('/api/v1/sincronizar-mes',{method:'POST',
      body:JSON.stringify({matriculas:lote,data_inicio:r.ini,data_fim:r.fim})})
      .then(function(j){ totDias+=(j.dias_gravados||0); totSinc+=(j.sincronizados||0); totErr+=(j.erros||0); idx+=BATCH; proximo(); })
      .catch(function(e){ totErr+=lote.length; idx+=BATCH; if(st) st.textContent='⚠ lote com erro ('+(e.message||e)+'), continuando...'; setTimeout(proximo, 300); });
  }
  proximo();
}

// ══ MÓDULO PROGRAMAÇÃO PLPT ══════════════════════════════════
var _plptProgData  = dataHoje();
var _plptProgCid   = CONTRATOS_UUID_MAP['PLPT']; // atualizado ao mudar contrato
var _plptProgDados = {}; // {equipe_id: {prog, projetos, membros}}

// Popular select de contratos que têm equipes cadastradas
function _plptProgPopularContratos(){
  var sel = document.getElementById('plpt-prog-contrato'); if(!sel) return;
  // Coletar contratos únicos das equipes carregadas
  var contratoIds = {};
  equipes.forEach(function(e){
    if(e.contrato_id && e.status==='Ativo') contratoIds[e.contrato_id] = true;
  });
  // Adicionar contratos da lista CONTRATOS_UUID_MAP
  Object.values(CONTRATOS_UUID_MAP).forEach(function(uid){ contratoIds[uid] = true; });

  var opts = '<option value="">Selecione o contrato...</option>';
  // Ordenar por nome
  var lista = contratos.filter(function(c){ return contratoIds[c.id]; })
    .sort(function(a,b){ return (a.codigo||'').localeCompare(b.codigo||''); });
  lista.forEach(function(c){
    opts += '<option value="'+c.id+'"'+(c.id===_plptProgCid?' selected':'')+'>'+c.nome+'</option>';
  });
  // Se lista vazia, mostrar todos os contratos
  if(!lista.length){
    contratos.forEach(function(c){
      opts += '<option value="'+c.id+'"'+(c.id===_plptProgCid?' selected':'')+'>'+c.nome+'</option>';
    });
  }
  sel.innerHTML = opts;
}

function plptProgMudarContrato(){
  var sel = document.getElementById('plpt-prog-contrato');
  if(!sel || !sel.value) return;
  _plptProgCid = sel.value;
  _plptProgDados = {};
  plptProgInit();
}

function plptNavScroll(sec){
  var el = document.getElementById('plpt-sec-'+sec);
  if(el){
    el.scrollIntoView({behavior:'smooth', block:'start'});
    el.style.outline = '2px solid #185FA5';
    setTimeout(function(){ el.style.outline = ''; }, 1500);
  } else {
    var lista = document.getElementById('plpt-prog-lista');
    if(lista) lista.scrollIntoView({behavior:'smooth', block:'start'});
  }
}

function plptNavData(delta){
  var inp = document.getElementById('plpt-prog-data');
  if(!inp) return;
  var atual = inp.value || dataHojeLocal();
  inp.value = typeof dataAddDias==='function' ? dataAddDias(atual, delta) : (function(){
    var d=new Date(atual+'T12:00:00'); d.setDate(d.getDate()+delta);
    return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  })();
  plptProgInit();
}

function plptNavHoje(){
  var inp = document.getElementById('plpt-prog-data');
  if(inp){ inp.value = dataHojeLocal(); plptProgInit(); }
}

function plptProgInit(){
  _plptProgData = (document.getElementById('plpt-prog-data')||{}).value || _plptProgData;
  var inp = document.getElementById('plpt-prog-data');
  if(inp && !inp.value) inp.value = _plptProgData;

  // Popular select de contratos com os que têm equipes
  _plptProgPopularContratos();

  if(DEMO){ plptProgRender(); return; }

  // Carregar veículos se ainda não foram carregados
  var carregarVeiculos = (frt_veiculos&&frt_veiculos.length) ? Promise.resolve() :
    sbFetchPaged ? 
    sbFetch('frotas_veiculos',{filters:['ativo=eq.true'],order:'placa'}).then(function(rows){
      if(rows&&rows.length) frt_veiculos=rows;
    }).catch(function(){}) :
    Promise.resolve();

  carregarVeiculos.then(function(){

    // Verificar se temos equipes e colaboradores do contrato atual
    var temEquipes = equipes.some(function(e){ return e.contrato_id===_plptProgCid && e.status==='Ativo'; });
    var temColabs  = colaboradores.some(function(c){ return c.contrato_id===_plptProgCid && c.ativo!==false; });

    // Buscar equipes e colaboradores do contrato se não estiverem em memória
    var carregarEquipes = temEquipes ? Promise.resolve() :
      sbFetch('equipes',{filters:['contrato_id=eq.'+_plptProgCid,'status=eq.Ativo'],order:'nome_equipe'})
        .then(function(rows){
          if(rows&&rows.length){
            rows.forEach(function(e){
              if(!equipes.find(function(x){return x.id===e.id;})) equipes.push(e);
            });
          }
        }).catch(function(){});

    var carregarColabs = temColabs ? Promise.resolve() :
      sbFetch('colaboradores',{filters:['contrato_id=eq.'+_plptProgCid,'ativo=eq.true'],order:'nome'})
        .then(function(rows){
          if(rows&&rows.length){
            rows.forEach(function(c){
              if(!colaboradores.find(function(x){return x.id===c.id;})) colaboradores.push(c);
            });
          }
        }).catch(function(){});

    Promise.all([carregarEquipes, carregarColabs]).then(function(){
      // Pré-carregar sot_projetos em paralelo para evitar delay ao abrir projetos
      var temSotProj = sot_projetos.some(function(p){ return p.contrato_id===_plptProgCid && p.status!=='Cancelado'; });
      var carregarSotProj = (temSotProj || DEMO) ? Promise.resolve([]) :
        sbFetchPaged('sot_projetos',{filters:['contrato_id=eq.'+_plptProgCid,'status=neq.Cancelado'],order:'criado_em.desc'})
          .then(function(rows){
            if(rows&&rows.length) rows.forEach(function(p){
              p._carregado = true;
              if(!sot_projetos.find(function(x){return x.id===p.id;})) sot_projetos.push(p);
            });
            return rows||[];
          }).catch(function(){ return []; });

      Promise.all([
        sbFetch('plpt_prog_dia',{filters:['contrato_id=eq.'+_plptProgCid,'data=eq.'+_plptProgData]}),
        sbFetch('plpt_equipe_membros',{}),
        sbFetch('plpt_prog_projetos',{}),
        carregarSotProj
      ]).then(function(res){
      var progs=res[0]||[], membros=res[1]||[], projs=res[2]||[];
      _plptProgDados={};
      progs.forEach(function(p){
        var membrosTabela = membros.filter(function(x){return x.equipe_id===p.equipe_id;});
          if(!membrosTabela.length){
            membrosTabela = colaboradores
              .filter(function(c){return c.equipe_id===p.equipe_id && c.ativo!==false;})
              .map(function(c){return {equipe_id:p.equipe_id, colaborador_id:c.id, funcao:'eletricista'};});
          }
          _plptProgDados[p.equipe_id]={
          prog:p,
          projetos:projs.filter(function(x){return x.prog_dia_id===p.id;}).sort(function(a,b){return a.ordem-b.ordem;}),
          membros: membrosTabela
        };
      });
      equipes.filter(function(e){return e.contrato_id===_plptProgCid&&e.status==='Ativo';})
        .forEach(function(eq){
          // Membros da tabela plpt_equipe_membros
          var membrosTabela = membros.filter(function(x){return x.equipe_id===eq.id;});
          // Fallback: colaboradores com equipe_id vinculado a esta equipe
          if(!membrosTabela.length){
            membrosTabela = colaboradores
              .filter(function(c){return c.equipe_id===eq.id && c.ativo!==false;})
              .map(function(c){return {equipe_id:eq.id, colaborador_id:c.id, funcao:'eletricista'};});
          }
          if(!_plptProgDados[eq.id]) _plptProgDados[eq.id]={
            prog:null, projetos:[],
            membros: membrosTabela
          };
        });
      progProjCarregarStatusBanco(_plptProgData, plptProgRender);
    }).catch(function(){ progProjCarregarStatusBanco(_plptProgData, plptProgRender); });
    }); // fim Promise.all([carregarEquipes, carregarColabs])
  });
}

function plptProgRender(){
  var lista=document.getElementById('plpt-prog-lista'); if(!lista)return;
  var filtTipo=(document.getElementById('plpt-prog-tipo')||{}).value||'';
  var filtBusca=((document.getElementById('plpt-busca-texto')||{}).value||'').toLowerCase().trim();
  var filtScope=(document.getElementById('plpt-busca-scope')||{}).value||'todos';
  var filtStatus=(document.getElementById('plpt-filtro-status')||{}).value||'';
  var eqs=equipes.filter(function(e){
    if(e.contrato_id!==_plptProgCid||e.status!=='Ativo')return false;
    if(filtTipo&&(e.nome_equipe||'').toUpperCase().indexOf(filtTipo)<0)return false;
    // Filtro de status
    if(filtStatus){
      var dado=_plptProgDados[e.id]||{};
      var prog=dado.prog||{};
      var projs=dado.projetos||[];
      if(filtStatus==='programada' && !prog.encarregado_id) return false;
      if(filtStatus==='sem_prog' && prog.encarregado_id) return false;
      if(filtStatus==='sem_enc' && prog.encarregado_id) return false;
      if(filtStatus==='com_proj' && !projs.length) return false;
      if(filtStatus==='sem_proj' && projs.length) return false;
    }
    // Filtro de busca
    if(filtBusca){
      var dado=_plptProgDados[e.id]||{};
      var prog=dado.prog||{};
      var membros=dado.membros||[];
      var projs=dado.projetos||[];
      if(filtScope==='equipe'){
        return (e.nome_equipe||'').toLowerCase().indexOf(filtBusca)>=0;
      } else if(filtScope==='colaborador'){
        var encObj=colaboradores.find(function(c){return c.id===prog.encarregado_id;});
        var encNome=encObj?(encObj.nome||'').toLowerCase():'';
        var membNomes=membros.map(function(m){
          var mc=colaboradores.find(function(c){return c.id===m.colaborador_id;});
          return mc?(mc.nome||'').toLowerCase():'';
        });
        return encNome.indexOf(filtBusca)>=0||membNomes.some(function(n){return n.indexOf(filtBusca)>=0;});
      } else if(filtScope==='projeto'){
        return projs.some(function(p){return (p.numero||p.descricao||'').toLowerCase().indexOf(filtBusca)>=0;});
      } else if(filtScope==='status'){
        var stLabel=prog.encarregado_id?'programada':'sem programação';
        return stLabel.indexOf(filtBusca)>=0;
      } else {
        // Todos — busca ampla
        var encObj=colaboradores.find(function(c){return c.id===prog.encarregado_id;});
        var encNome=encObj?(encObj.nome||'').toLowerCase():'';
        return (e.nome_equipe||'').toLowerCase().indexOf(filtBusca)>=0
          ||encNome.indexOf(filtBusca)>=0
          ||projs.some(function(p){return (p.numero||p.descricao||'').toLowerCase().indexOf(filtBusca)>=0;});
      }
    }
    return true;
  }).sort(function(a,b){return (a.nome_equipe||'').localeCompare(b.nome_equipe||'');});

  if(!eqs.length){
    lista.innerHTML='<div style="text-align:center;padding:3rem;color:#aaa">Nenhuma equipe encontrada.</div>';
    return;
  }

  // Métricas
  var metr=document.getElementById('plpt-prog-metricas');
  if(metr){
    var total=eqs.length;
    var progr=eqs.filter(function(e){return _plptProgDados[e.id]&&_plptProgDados[e.id].prog;}).length;
    var comProj=eqs.filter(function(e){return _plptProgDados[e.id]&&(_plptProgDados[e.id].projetos||[]).length>0;}).length;
    var semEnc=eqs.filter(function(e){return !(_plptProgDados[e.id]&&(_plptProgDados[e.id].prog||{}).encarregado_id);}).length;
    metr.innerHTML=[
      {l:'Total equipes',v:total,c:'#555'},
      {l:'Programadas',v:progr,c:'#3B6D11'},
      {l:'Com projetos',v:comProj,c:'#185FA5'},
      {l:'Sem encarregado',v:semEnc,c:semEnc>0?'#A32D2D':'#3B6D11'},
      {l:'Sem programação',v:total-progr,c:total-progr>0?'#854F0B':'#3B6D11'},
    ].map(function(m){
      return '<div style="padding:.4rem .5rem"><div style="font-size:10px;color:#888">'+m.l+'</div>'
        +'<div style="font-size:18px;font-weight:700;color:'+m.c+'">'+m.v+'</div></div>';
    }).join('');
  }

  lista.innerHTML='<div id="plpt-sec-topo"></div>'+eqs.map(function(eq){
    var dado=_plptProgDados[eq.id]||{prog:null,projetos:[],membros:[]};
    var prog=dado.prog||{}, projs=dado.projetos||[], membros=dado.membros||[];
    var tipo=eq.nome_equipe.indexOf('LV')>=0?'LV':eq.nome_equipe.indexOf('VIA')>=0?'VIA':'LM';
    var tipoCor={LM:'#185FA5',LV:'#3B6D11',VIA:'#854F0B'}[tipo]||'#555';
    var isProgr=!!(prog.encarregado_id);

    // Veículos já alocados neste dia (exceto o desta equipe)
    var veiculosOcupados = {};
    eqs.forEach(function(e){
      if(e.id===eq.id) return;
      var d2=_plptProgDados[e.id];
      if(d2&&d2.prog&&d2.prog.veiculo_id) veiculosOcupados[d2.prog.veiculo_id]=e.nome_equipe;
    });

    // Colaboradores já alocados como membros de outras equipes
    var colabsOcupados = {};
    eqs.forEach(function(e){
      if(e.id===eq.id) return;
      var d2=_plptProgDados[e.id];
      if(!d2) return;
      // Encarregado de outra equipe
      if(d2.prog&&d2.prog.encarregado_id) colabsOcupados[d2.prog.encarregado_id]=e.nome_equipe;
      // Membros de outra equipe
      (d2.membros||[]).forEach(function(m){ colabsOcupados[m.colaborador_id]=e.nome_equipe; });
    });

    // Select de encarregado — oculta quem está em outra equipe
    var colabOpts='<option value="">Selecione...</option>'
      +colaboradores.filter(function(c){
        if(c.contrato_id!==_plptProgCid||c.ativo===false||c.vinculo!=='campo') return false;
        // Mostrar mesmo que esteja ocupado SE for o encarregado atual desta equipe
        if(prog.encarregado_id===c.id) return true;
        var _stPlpt=(typeof _progStatus!=='undefined'?_progStatus[c.id]:'')||'disponivel';
        if(['ferias','afastado','treinamento','falta','faltou','verificar','fraude','demitido','integracao','patio'].indexOf(_stPlpt)>=0) return false;
        return !colabsOcupados[c.id];
      }).map(function(c){
        return '<option value="'+c.id+'"'+(prog.encarregado_id===c.id?' selected':'')+'>'+c.nome+(c.re?' ('+c.re+')':'')+'</option>';
      }).join('');

    // Select de veículo — oculta os já alocados
    var veicOpts='<option value="">— Sem veículo —</option>'
      +(frt_veiculos&&frt_veiculos.length
        ? frt_veiculos.filter(function(v){
            if(v.ativo===false) return false;
            var cid=(v.contrato_id||'').trim();
            // Aceitar veículos do contrato atual ou sem contrato definido
            var isContrato = !cid || cid===_plptProgCid
              || (function(){
                var cont=contratos.find(function(x){return x.id===_plptProgCid;});
                if(!cont) return cid==='PLPT-PLPT TERESINA'||cid==='PLPT TERESINA'||cid==='PLPT';
                return cid===cont.id||cid.toUpperCase().indexOf((cont.codigo||'').toUpperCase())>=0
                    || cid.toUpperCase().indexOf((cont.nome||'').split(' ')[0].toUpperCase())>=0;
              })();
            if(!isContrato) return false;
            // Mostrar mesmo que ocupado SE for o veículo atual desta equipe
            if(prog.veiculo_id===v.id) return true;
            return !veiculosOcupados[v.id];
          }).map(function(v){
            return '<option value="'+v.id+'" data-placa="'+(v.placa||'')+'"'
              +(prog.veiculo_id===v.id?' selected':'')+'>'
              +(v.placa||'')+(v.modelo?' — '+v.modelo:'')+'</option>';
          }).join('')
        : '<option disabled>Carregando...</option>');

    // Celular da equipe no PLPT
    var plptCelId  = prog.celular_id||'';
    var plptCelOpts = '<option value="">📱 Sem celular</option>'
      +(_celulares||[]).map(function(x){
        return '<option value="'+x.id+'"'+(plptCelId===x.id?' selected':'')+'>'+escHtml(x.numero+(x.modelo?' ('+x.modelo+')':''))+'</option>';
      }).join('');

    var data=_plptProgData;
    var membrosHtml=membros.map(function(m){
      var col=colaboradores.find(function(c){return c.id===m.colaborador_id;})||{nome:'?'};
      var key=(col.re||'')+'_'+data;
      var ponto=_pontoCache[key];
      var temEnt=ponto&&(ponto.entrada||(ponto.todas_marcacoes&&ponto.todas_marcacoes.some(function(x){return x.tipo==='Entrada';})));
      var pontoBadge=temEnt
        ?'<span style="background:#EAF3DE;color:#3B6D11;border-radius:3px;padding:0 4px;font-size:8px;font-weight:700">✓ '+(ponto.entrada||'')+'</span>'
        :(ponto&&ponto.status==='falta'?'<span style="background:#FCEBEB;color:#A32D2D;border-radius:3px;padding:0 4px;font-size:8px;font-weight:700">● Aus</span>':'');
      return '<span style="background:#f0efe8;border-radius:4px;padding:2px 7px;font-size:10px;display:inline-flex;align-items:center;gap:3px">'+col.nome.split(' ')[0]+' '+pontoBadge+'</span>';
    }).join(' ');

    var projHtml=projs.length
      ?projs.map(function(pj,i){
          var sot=sot_projetos.find(function(x){return x.id===pj.projeto_id;})||{};
          return '<div style="display:flex;align-items:center;gap:6px;padding:3px 0;border-top:.5px solid #f5f5f3">'
            +'<span style="font-size:10px;color:#888;width:16px;text-align:right">'+(i+1)+'.</span>'
            +'<span style="font-size:11px;font-weight:500;flex:1">'+(sot.codigo_cliente||sot.nome||'?')+'</span>'
            +'<span style="font-size:10px;color:#888">'+(sot.nome||'')+'</span>'
            +'<button onclick="plptProgRemoverProjeto(\''+eq.id+'\','+i+')" style="background:none;border:none;color:#A32D2D;cursor:pointer;font-size:13px">✕</button>'
            +'</div>';
        }).join('')
      :'<div style="font-size:11px;color:#ccc;padding:4px 0">Nenhum projeto programado</div>';

    return '<div class="card" style="margin-bottom:.6rem" id="plpt-eq-card-'+eq.id+'">'
      // Header
      +'<div style="display:flex;align-items:center;gap:10px;padding:.6rem 1rem;background:'+(isProgr?'#EAF3DE':'#f9f9f7')+';border-bottom:.5px solid #e0dfd8">'
      +'<span style="background:'+tipoCor+';color:#fff;padding:2px 8px;border-radius:4px;font-size:11px;font-weight:600">'+tipo+'</span>'
      +'<span style="font-weight:700;font-size:14px">'+eq.nome_equipe+'</span>'
      +'<span style="font-size:11px;color:#888">'+(eq.supervisor||'')+'</span>'
      +'<span style="margin-left:auto;font-size:11px;font-weight:600;color:'+(isProgr?'#3B6D11':'#A32D2D')+'">'+(isProgr?'✅ Programada':'⚠ Não programada')+'</span>'
      +'</div>'
      // Body
      +'<div style="padding:.75rem 1rem;display:grid;grid-template-columns:1fr 1fr;gap:.75rem">'
      // Badge ponto do encarregado
      var encColObj = prog.encarregado_id ? colaboradores.find(function(c){return c.id===prog.encarregado_id;}) : null;
      var encKey = encColObj&&encColObj.re ? encColObj.re+'_'+data : '';
      var encPonto = encKey ? _pontoCache[encKey] : null;
      var encTemEnt = encPonto&&(encPonto.entrada||(encPonto.todas_marcacoes&&encPonto.todas_marcacoes.some(function(x){return x.tipo==='Entrada';})));
      var encBadge = encTemEnt
        ? '<span style="background:#EAF3DE;color:#3B6D11;border-radius:3px;padding:0 4px;font-size:8px;font-weight:700">✓ '+(encPonto.entrada||'Presente')+'</span>'
        : (encPonto&&encPonto.status==='falta'?'<span style="background:#FCEBEB;color:#A32D2D;border-radius:3px;padding:0 4px;font-size:8px;font-weight:700">● Ausente</span>':'');
      +'<div><label style="font-size:10px;font-weight:600;color:#555;display:block;margin-bottom:3px">Encarregado '+encBadge+'</label>'
      +'<select class="inp" id="plpt-enc-'+eq.id+'" style="width:100%;font-size:12px" onchange="plptProgOnChange(\''+eq.id+'\')">'+colabOpts+'</select></div>'
      +'<div><label style="font-size:10px;font-weight:600;color:#555;display:block;margin-bottom:3px">Veículo</label>'
      +'<select class="inp" id="plpt-veic-'+eq.id+'" style="width:100%;font-size:12px" onchange="plptProgOnChange(\''+eq.id+'\')">'+veicOpts+'</select></div>'
      +'<div style="grid-column:span 2"><label style="font-size:10px;font-weight:600;color:#555;display:block;margin-bottom:3px">'
      +'Membros fixos <button onclick="plptProgEditarMembros(\''+eq.id+'\')" style="background:none;border:none;cursor:pointer;font-size:10px;color:#185FA5">✎ editar</button></label>'
      +(membrosHtml||'<span style="font-size:11px;color:#ccc">Nenhum membro cadastrado</span>')+'</div>'
      +(function(){
        var _cel=plptCelId?(_celulares||[]).find(function(x){return x.id===plptCelId;}):null;
        var _lbl=_cel?escHtml(_cel.numero):'📱 Cel...';
        var _bg=_cel?'#E6F1FB':'#f5f5f3';var _cor=_cel?'#185FA5':'#888';var _brd=_cel?'#185FA5':'#ccc';
        return '<div><label style="font-size:10px;font-weight:600;color:#555;display:block;margin-bottom:3px">📱 Celular</label>'
          +'<button class="plpt-cel-btn" data-eq="'+eq.id+'" data-dt="'+data+'" '
          +'style="font-size:10px;background:'+_bg+';color:'+_cor+';border:.5px solid '+_brd+';border-radius:4px;padding:3px 8px;cursor:pointer;width:100%;text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'
          +_lbl+'</button></div>';
      })()
      +'<div style="grid-column:span 2"><label style="font-size:10px;font-weight:600;color:#555;display:block;margin-bottom:3px">Obs. do dia</label>'
      +'<input class="inp" id="plpt-obs-'+eq.id+'" value="'+(prog.obs||'')+'" style="width:100%;font-size:12px" placeholder="Opcional..."/></div>'
      +'<div style="grid-column:span 2"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">'
      +'<label style="font-size:10px;font-weight:600;color:#555">Projetos do dia (em ordem)</label>'
      +'<button class="btn btn-sm btn-pri" style="font-size:10px" onclick="plptProgAdicionarProjeto(\''+eq.id+'\')">+ Projeto</button>'
      +'</div><div id="plpt-projs-'+eq.id+'">'+projHtml+'</div></div>'
      // Botão salvar individual
      +'<div style="grid-column:span 2;text-align:right;border-top:.5px solid #f0efe8;padding-top:.5rem;margin-top:.25rem">'
      +'<button class="btn btn-pri" style="font-size:11px" onclick="plptProgSalvarEquipe(\''+eq.id+'\')">💾 Salvar esta equipe</button>'
      +'</div>'
      +'</div></div>';
  }).join('');
  // Bind dos botões de celular PLPT (modal com busca)
  if(lista) lista.querySelectorAll('.plpt-cel-btn').forEach(function(btn){
    btn.addEventListener('click', function(){
      progAbrirSelecionarCelular(this.dataset.eq, this.dataset.dt);
    });
  });
}

function plptProgOnChange(eqId){
  if(!_plptProgDados[eqId])_plptProgDados[eqId]={prog:{},projetos:[],membros:[]};
  var d=_plptProgDados[eqId]; if(!d.prog)d.prog={};
  var selEnc=document.getElementById('plpt-enc-'+eqId);
  var selVeic=document.getElementById('plpt-veic-'+eqId);
  d.prog.encarregado_id=(selEnc||{}).value||null;
  d.prog.encarregado_nome=selEnc?(selEnc.options[selEnc.selectedIndex]||{}).text||'':'';
  d.prog.veiculo_id=(selVeic&&selVeic.value)?selVeic.value:null;
  var card=document.getElementById('plpt-eq-card-'+eqId);
  if(card){var hdr=card.children[0];if(hdr)hdr.style.background=d.prog.encarregado_id?'#EAF3DE':'#f9f9f7';}
  // Re-renderizar para atualizar exclusividade nos outros cards
  setTimeout(function(){ plptProgRender(); }, 100);
}

// Salvar programação de UMA equipe específica
function plptProgSalvarEquipe(eqId){
  var selEnc  = document.getElementById('plpt-enc-'+eqId);
  var selVeic = document.getElementById('plpt-veic-'+eqId);
  var obs     = (document.getElementById('plpt-obs-'+eqId)||{}).value||'';
  if(!selEnc||!selEnc.value){ alert('Selecione o encarregado antes de salvar.'); return; }

  var dado = _plptProgDados[eqId]||{prog:null,projetos:[],membros:[]};
  var encOpt  = selEnc.options[selEnc.selectedIndex]||{};
  var encNome = (encOpt.text||'').replace(/\s*\([^)]*\)\s*$/,'').trim();
  var veicOpt = selVeic ? (selVeic.options[selVeic.selectedIndex]||{}) : {};

  var payload = {
    equipe_id:        eqId,
    contrato_id:      _plptProgCid,
    data:             _plptProgData,
    encarregado_id:   selEnc.value||null,
    encarregado_nome: encNome,
    veiculo_id:       selVeic&&selVeic.value?selVeic.value:null,
    obs:              obs,
    status:           'programado'
  };

  var projs = (dado.projetos||[]).map(function(p,i){
    return {projeto_id:p.projeto_id, ordem:i+1, status:'pendente'};
  });

  var btn = document.querySelector('#plpt-eq-card-'+eqId+' .btn-pri');
  if(btn){ btn.disabled=true; btn.textContent='Salvando...'; }

  if(!DEMO){
    var salvarProjs = function(progId){
      if(!projs.length) return;
      fetch(SB.url+'/rest/v1/plpt_prog_projetos?prog_dia_id=eq.'+progId,{
        method:'DELETE',headers:{'apikey':SB.key,'Authorization':'Bearer '+(_sbAuthToken||SB.key)}
      }).then(function(){
        sbInsert('plpt_prog_projetos', projs.map(function(p){
          return Object.assign({prog_dia_id:progId},p);
        }));
      });
    };

    if(dado.prog&&dado.prog.id){
      sbUpdate('plpt_prog_dia', payload, 'id=eq.'+dado.prog.id).then(function(){
        salvarProjs(dado.prog.id);
        if(!dado.prog) dado.prog={};
        Object.assign(dado.prog, payload);
        progShowToast('✅ '+_plptEqNome(eqId)+' salva');
        plptProgRender();
      });
    } else {
      sbInsert('plpt_prog_dia', payload).then(function(res){
        if(res&&res[0]&&res[0].id){
          if(!dado.prog) dado.prog={};
          Object.assign(dado.prog, payload);
          dado.prog.id = res[0].id;
          salvarProjs(res[0].id);
        }
        progShowToast('✅ '+_plptEqNome(eqId)+' salva');
        plptProgRender();
      });
    }
  } else {
    if(!dado.prog) dado.prog={};
    Object.assign(dado.prog, payload);
    progShowToast('✅ '+_plptEqNome(eqId)+' salva (demo)');
    plptProgRender();
  }
}

function _plptEqNome(eqId){
  var eq = equipes.find(function(e){return e.id===eqId;});
  return eq ? eq.nome_equipe : eqId;
}

function plptProgAdicionarProjeto(eqId){
  window._plptAddingToEq = eqId;

  function abrirModal(projsCid){
    var html = '<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
      +'<div class="modal" style="max-width:480px">'
      +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.5rem">'
      +'<h3 style="margin:0">+ Adicionar Projeto</h3>'
      +'<button onclick="closeModal()" style="background:none;border:none;font-size:20px;cursor:pointer;color:#888;line-height:1">✕</button>'
      +'</div>'
      +'<input class="inp" id="plpt-busca-proj" placeholder="Buscar por código ou nome..." style="width:100%;margin-bottom:.5rem" oninput="plptFiltrarProjetosModal()"/>'
      +'<div id="plpt-lista-proj" style="max-height:320px;overflow-y:auto;border:.5px solid #e0dfd8;border-radius:8px">'
      +(projsCid.length ? projsCid.map(function(p){
        var sc={Recebido:'#888',Programado:'#185FA5','Em execução':'#3B6D11',Viabilizado:'#185FA5'}[p.status]||'#888';
        return '<div onclick="plptSelecionarProjeto(\''+eqId+'\',\''+p.id+'\')" '
          +'style="padding:9px 12px;cursor:pointer;border-bottom:.5px solid #f0efe8" '
          +'onmouseover="this.style.background=\'#f5f5f3\'" onmouseout="this.style.background=\'\'">'
          +'<div style="font-size:12px;font-weight:600">'+(p.codigo_cliente||'S/N')+' — '+p.nome+'</div>'
          +'<div style="font-size:10px;color:'+sc+'">'+p.status+'</div></div>';
      }).join('') : '<div style="padding:1rem;text-align:center;color:#aaa">Nenhum projeto cadastrado para o PLPT.<br>Cadastre projetos em Obras → PLPT.</div>')
      +'</div>'
      +'<div style="margin-top:.75rem;text-align:right">'
      +'<button class="btn" onclick="closeModal()">Cancelar</button>'
      +'</div></div></div>';
    setModal(html);
  }

  // Tentar usar projetos em memória primeiro
  var projsCid = sot_projetos.filter(function(p){
    return p.contrato_id === _plptProgCid && p.status !== 'Cancelado';
  });

  if(projsCid.length || DEMO){
    abrirModal(projsCid);
  } else {
    // Buscar do banco se memória estiver vazia
    abrirModal([]); // Abre com "carregando..."
    var lista = document.getElementById('plpt-lista-proj');
    if(lista) lista.innerHTML = '<div style="padding:1rem;text-align:center;color:#aaa">Carregando projetos...</div>';

    sbFetchPaged('sot_projetos',{filters:['contrato_id=eq.'+_plptProgCid,'status=neq.Cancelado'],order:'criado_em.desc'})
      .then(function(rows){
        if(rows&&rows.length){
          rows.forEach(function(p){
            if(!sot_projetos.find(function(x){return x.id===p.id;})) sot_projetos.push(p);
          });
          projsCid = rows;
        }
        var listaEl = document.getElementById('plpt-lista-proj');
        if(listaEl){
          listaEl.innerHTML = projsCid.length ? projsCid.map(function(p){
            var sc={Recebido:'#888',Programado:'#185FA5','Em execução':'#3B6D11',Viabilizado:'#185FA5'}[p.status]||'#888';
            return '<div onclick="plptSelecionarProjeto(\''+eqId+'\',\''+p.id+'\')" '
              +'style="padding:9px 12px;cursor:pointer;border-bottom:.5px solid #f0efe8" '
              +'onmouseover="this.style.background=\'#f5f5f3\'" onmouseout="this.style.background=\'\'">'
              +'<div style="font-size:12px;font-weight:600">'+(p.codigo_cliente||'S/N')+' — '+p.nome+'</div>'
              +'<div style="font-size:10px;color:'+sc+'">'+p.status+'</div></div>';
          }).join('') : '<div style="padding:1rem;text-align:center;color:#aaa">Nenhum projeto cadastrado para o PLPT.</div>';
        }
      }).catch(function(){
        var listaEl = document.getElementById('plpt-lista-proj');
        if(listaEl) listaEl.innerHTML = '<div style="padding:1rem;text-align:center;color:#A32D2D">Erro ao carregar projetos.</div>';
      });
  }
}

function plptFiltrarProjetosModal(){
  var q=((document.getElementById('plpt-busca-proj')||{}).value||'').toLowerCase();
  Array.from(document.querySelectorAll('#plpt-lista-proj>div')).forEach(function(el){
    el.style.display=el.textContent.toLowerCase().indexOf(q)>=0?'':'none';
  });
}

function plptSelecionarProjeto(eqId,projId){
  if(!_plptProgDados[eqId])_plptProgDados[eqId]={prog:{},projetos:[],membros:[]};
  var projs=_plptProgDados[eqId].projetos;
  if(projs.find(function(p){return p.projeto_id===projId;})){alert('Projeto já adicionado.');return;}
  projs.push({projeto_id:projId,ordem:projs.length+1,status:'pendente'});
  closeModal();
  var el=document.getElementById('plpt-projs-'+eqId);
  if(el){
    var sot=sot_projetos.find(function(x){return x.id===projId;})||{};
    var i=projs.length-1;
    var emptyMsg=el.querySelector('div[style*="color:#ccc"]');
    if(emptyMsg)emptyMsg.remove();
    var row=document.createElement('div');
    row.style.cssText='display:flex;align-items:center;gap:6px;padding:3px 0;border-top:.5px solid #f5f5f3';
    row.innerHTML='<span style="font-size:10px;color:#888;width:16px;text-align:right">'+(i+1)+'.</span>'
      +'<span style="font-size:11px;font-weight:500;flex:1">'+(sot.codigo_cliente||sot.nome||'?')+'</span>'
      +'<span style="font-size:10px;color:#888">'+(sot.nome||'')+'</span>'
      +'<button onclick="plptProgRemoverProjeto(\''+eqId+'\','+i+')" style="background:none;border:none;color:#A32D2D;cursor:pointer;font-size:13px">✕</button>';
    el.appendChild(row);
  }
  progShowToast('Projeto adicionado');
}

function plptProgRemoverProjeto(eqId,idx){
  if(!_plptProgDados[eqId])return;
  _plptProgDados[eqId].projetos.splice(idx,1);
  _plptProgDados[eqId].projetos.forEach(function(p,i){p.ordem=i+1;});
  var el=document.getElementById('plpt-projs-'+eqId);
  if(!el)return;
  var projs=_plptProgDados[eqId].projetos;
  el.innerHTML=projs.length?projs.map(function(pj,i){
    var sot=sot_projetos.find(function(x){return x.id===pj.projeto_id;})||{};
    return '<div style="display:flex;align-items:center;gap:6px;padding:3px 0;border-top:.5px solid #f5f5f3">'
      +'<span style="font-size:10px;color:#888;width:16px;text-align:right">'+(i+1)+'.</span>'
      +'<span style="font-size:11px;font-weight:500;flex:1">'+(sot.codigo_cliente||sot.nome||'?')+'</span>'
      +'<span style="font-size:10px;color:#888">'+(sot.nome||'')+'</span>'
      +'<button onclick="plptProgRemoverProjeto(\''+eqId+'\','+i+')" style="background:none;border:none;color:#A32D2D;cursor:pointer;font-size:13px">✕</button>'
      +'</div>';
  }).join(''):'<div style="font-size:11px;color:#ccc;padding:4px 0">Nenhum projeto programado</div>';
}

function _plptColabsOcupados(eqIdAtual){
  var ocupados={};
  Object.keys(_plptProgDados).forEach(function(eid){
    if(eid===eqIdAtual) return;
    var d=_plptProgDados[eid];
    if(d.prog&&d.prog.encarregado_id) ocupados[d.prog.encarregado_id]=true;
    (d.membros||[]).forEach(function(m){ ocupados[m.colaborador_id]=true; });
  });
  return ocupados;
}

function plptProgEditarMembros(eqId){
  var eq=equipes.find(function(e){return e.id===eqId;});if(!eq)return;
  var colabs=colaboradores.filter(function(c){return c.contrato_id===_plptProgCid&&c.ativo!==false&&c.vinculo==='campo';});
  var memIds=((_plptProgDados[eqId]&&_plptProgDados[eqId].membros)||[]).map(function(m){return m.colaborador_id;});
  var ocupados=_plptColabsOcupados(eqId);
  var html='<div class="modal-bg"><div class="modal" style="max-width:480px">'
    +'<h3 style="margin-bottom:.25rem">Membros — '+eq.nome_equipe+'</h3>'
    +'<div style="font-size:11px;color:#888;margin-bottom:.5rem">🔒 Colaboradores em cinza já estão em outra equipe hoje.</div>'
    +'<input class="inp" id="plpt-busca-mem" placeholder="Buscar..." style="width:100%;margin-bottom:.5rem" oninput="plptFiltrarMembrosModal()"/>'
    +'<div style="max-height:300px;overflow-y:auto;border:.5px solid #e0dfd8;border-radius:8px" id="plpt-lista-mem">'
    +colabs.map(function(c){
      var jaMembro=memIds.indexOf(c.id)>=0;
      var ocupado=!jaMembro&&!!ocupados[c.id];
      return '<label style="display:flex;align-items:center;gap:8px;padding:8px 12px;cursor:'+(ocupado?'not-allowed':'pointer')+';border-bottom:.5px solid #f0efe8;font-size:12px;'+(ocupado?'opacity:.4;background:#f9f9f7':'')+'">'
        +'<input type="checkbox" value="'+c.id+'" '+(jaMembro?'checked':'')+(ocupado?' disabled':'')+' style="width:15px;height:15px"/>'
        +'<span style="flex:1">'+c.nome+'</span>'
        +'<span style="font-size:10px;color:'+(ocupado?'#A32D2D':'#888')+'">'+( ocupado?'outra equipe':(c.cargo||c.re||''))+'</span>'
        +'</label>';
    }).join('')
    +'</div>'
    +'<div class="ma" style="margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="plptSalvarMembros(\''+eqId+'\')">Salvar</button>'
    +'</div></div></div>';
  setModal(html);
  setTimeout(function(){
    document.querySelectorAll('.mn-full-btn').forEach(function(btn){
      btn.onclick=function(){
        closeModal();
        var i=parseInt(this.getAttribute('data-mi'));
        if(itensMenu[i]) itensMenu[i].acao();
      };
    });
    // Bind do campo data de retorno
    var inpData=document.getElementById('retorno-data');
    if(inpData){
      var _orig=inpData.getAttribute('data-original')||'';
      inpData.addEventListener('change',function(){ progVerificarMudancaData(this,_orig); });
    }
  },50);
}

function plptFiltrarMembrosModal(){
  var q=((document.getElementById('plpt-busca-mem')||{}).value||'').toLowerCase();
  Array.from(document.querySelectorAll('#plpt-lista-mem label')).forEach(function(el){
    el.style.display=el.textContent.toLowerCase().indexOf(q)>=0?'':'none';
  });
}

function plptSalvarMembros(eqId){
  var sel=Array.from(document.querySelectorAll('#plpt-lista-mem input:checked')).map(function(cb){return cb.value;});
  if(!_plptProgDados[eqId])_plptProgDados[eqId]={prog:{},projetos:[],membros:[]};
  _plptProgDados[eqId].membros=sel.map(function(cid){return{equipe_id:eqId,colaborador_id:cid,funcao:'eletricista'};});
  if(!DEMO){
    fetch(SB.url+'/rest/v1/plpt_equipe_membros?equipe_id=eq.'+eqId,{
      method:'DELETE',headers:{'apikey':SB.key,'Authorization':'Bearer '+(_sbAuthToken||SB.key)}
    }).then(function(){
      if(sel.length)sbInsert('plpt_equipe_membros',_plptProgDados[eqId].membros);
    });
  }
  closeModal();plptProgRender();
  progShowToast('✅ '+sel.length+' membro(s) salvos');
}

function plptProgSalvarTudo(){
  var eqs=equipes.filter(function(e){return e.contrato_id===_plptProgCid&&e.status==='Ativo';});
  var salvos=0;
  eqs.forEach(function(eq){
    var selEnc=document.getElementById('plpt-enc-'+eq.id);
    if(!selEnc||!selEnc.value)return;
    var selVeic=document.getElementById('plpt-veic-'+eq.id);
    var obs=(document.getElementById('plpt-obs-'+eq.id)||{}).value||'';
    var dado=_plptProgDados[eq.id]||{prog:null,projetos:[],membros:[]};
    var encOpt=selEnc.options[selEnc.selectedIndex]||{};
    // Pegar só o nome sem o RE entre parênteses
    var encNome = (encOpt.text||'').replace(/\s*\([^)]*\)\s*$/, '').trim();
    var payload={equipe_id:eq.id,contrato_id:_plptProgCid,data:_plptProgData,
      encarregado_id:selEnc.value||null,encarregado_nome:encNome,
      veiculo_id:selVeic&&selVeic.value?selVeic.value:null,obs:obs,status:'programado'};
    var projs=(dado.projetos||[]).map(function(p,i){
      return{projeto_id:p.projeto_id,ordem:i+1,status:'pendente'};
    });
    if(!DEMO){
      if(dado.prog&&dado.prog.id){
        sbUpdate('plpt_prog_dia',payload,'id=eq.'+dado.prog.id);
        fetch(SB.url+'/rest/v1/plpt_prog_projetos?prog_dia_id=eq.'+dado.prog.id,{
          method:'DELETE',headers:{'apikey':SB.key,'Authorization':'Bearer '+(_sbAuthToken||SB.key)}
        }).then(function(){
          if(projs.length)sbInsert('plpt_prog_projetos',projs.map(function(p){return Object.assign({prog_dia_id:dado.prog.id},p);}));
        });
      } else {
        sbInsert('plpt_prog_dia',payload).then(function(res){
          if(res&&res[0]&&res[0].id){
            if(!dado.prog)dado.prog={};
            dado.prog.id=res[0].id;
            if(projs.length)sbInsert('plpt_prog_projetos',projs.map(function(p){return Object.assign({prog_dia_id:res[0].id},p);}));
          }
        });
      }
    }
    salvos++;
  });
  plptProgRender();
  progShowToast('✅ Programação salva — '+salvos+' equipe(s)');
}







// ══ MÓDULO PROGRAMAÇÃO PLPT ══════════════════════════════════
var _plptProgData  = dataHoje();
var _plptProgCid   = CONTRATOS_UUID_MAP['PLPT']; // atualizado ao mudar contrato
var _plptProgDados = {}; // {equipe_id: {prog, projetos, membros}}

// Popular select de contratos que têm equipes cadastradas
function _plptProgPopularContratos(){
  var sel = document.getElementById('plpt-prog-contrato'); if(!sel) return;
  // Coletar contratos únicos das equipes carregadas
  var contratoIds = {};
  equipes.forEach(function(e){
    if(e.contrato_id && e.status==='Ativo') contratoIds[e.contrato_id] = true;
  });
  // Adicionar contratos da lista CONTRATOS_UUID_MAP
  Object.values(CONTRATOS_UUID_MAP).forEach(function(uid){ contratoIds[uid] = true; });

  var opts = '<option value="">Selecione o contrato...</option>';
  // Ordenar por nome
  var lista = contratos.filter(function(c){ return contratoIds[c.id]; })
    .sort(function(a,b){ return (a.codigo||'').localeCompare(b.codigo||''); });
  lista.forEach(function(c){
    opts += '<option value="'+c.id+'"'+(c.id===_plptProgCid?' selected':'')+'>'+c.nome+'</option>';
  });
  // Se lista vazia, mostrar todos os contratos
  if(!lista.length){
    contratos.forEach(function(c){
      opts += '<option value="'+c.id+'"'+(c.id===_plptProgCid?' selected':'')+'>'+c.nome+'</option>';
    });
  }
  sel.innerHTML = opts;
}

function plptProgMudarContrato(){
  var sel = document.getElementById('plpt-prog-contrato');
  if(!sel || !sel.value) return;
  _plptProgCid = sel.value;
  _plptProgDados = {};
  plptProgInit();
}

function plptProgInit(){
  _plptProgData = (document.getElementById('plpt-prog-data')||{}).value || _plptProgData;
  var inp = document.getElementById('plpt-prog-data');
  if(inp && !inp.value) inp.value = _plptProgData;

  // Popular select de contratos com os que têm equipes
  _plptProgPopularContratos();

  if(DEMO){ plptProgRender(); return; }

  // Carregar veículos se ainda não foram carregados
  var carregarVeiculos = (frt_veiculos&&frt_veiculos.length) ? Promise.resolve() :
    sbFetchPaged ? 
    sbFetch('frotas_veiculos',{filters:['ativo=eq.true'],order:'placa'}).then(function(rows){
      if(rows&&rows.length) frt_veiculos=rows;
    }).catch(function(){}) :
    Promise.resolve();

  carregarVeiculos.then(function(){

    // Verificar se temos equipes e colaboradores do contrato atual
    var temEquipes = equipes.some(function(e){ return e.contrato_id===_plptProgCid && e.status==='Ativo'; });
    var temColabs  = colaboradores.some(function(c){ return c.contrato_id===_plptProgCid && c.ativo!==false; });

    // Buscar equipes e colaboradores do contrato se não estiverem em memória
    var carregarEquipes = temEquipes ? Promise.resolve() :
      sbFetch('equipes',{filters:['contrato_id=eq.'+_plptProgCid,'status=eq.Ativo'],order:'nome_equipe'})
        .then(function(rows){
          if(rows&&rows.length){
            rows.forEach(function(e){
              if(!equipes.find(function(x){return x.id===e.id;})) equipes.push(e);
            });
          }
        }).catch(function(){});

    var carregarColabs = temColabs ? Promise.resolve() :
      sbFetch('colaboradores',{filters:['contrato_id=eq.'+_plptProgCid,'ativo=eq.true'],order:'nome'})
        .then(function(rows){
          if(rows&&rows.length){
            rows.forEach(function(c){
              if(!colaboradores.find(function(x){return x.id===c.id;})) colaboradores.push(c);
            });
          }
        }).catch(function(){});

    Promise.all([carregarEquipes, carregarColabs]).then(function(){
      Promise.all([
        sbFetch('plpt_prog_dia',{filters:['contrato_id=eq.'+_plptProgCid,'data=eq.'+_plptProgData]}),
        sbFetch('plpt_equipe_membros',{}),
        sbFetch('plpt_prog_projetos',{})
      ]).then(function(res){
      var progs=res[0]||[], membros=res[1]||[], projs=res[2]||[];
      _plptProgDados={};
      progs.forEach(function(p){
        var membrosTabela = membros.filter(function(x){return x.equipe_id===p.equipe_id;});
          if(!membrosTabela.length){
            membrosTabela = colaboradores
              .filter(function(c){return c.equipe_id===p.equipe_id && c.ativo!==false;})
              .map(function(c){return {equipe_id:p.equipe_id, colaborador_id:c.id, funcao:'eletricista'};});
          }
          _plptProgDados[p.equipe_id]={
          prog:p,
          projetos:projs.filter(function(x){return x.prog_dia_id===p.id;}).sort(function(a,b){return a.ordem-b.ordem;}),
          membros: membrosTabela
        };
      });
      equipes.filter(function(e){return e.contrato_id===_plptProgCid&&e.status==='Ativo';})
        .forEach(function(eq){
          // Membros da tabela plpt_equipe_membros
          var membrosTabela = membros.filter(function(x){return x.equipe_id===eq.id;});
          // Fallback: colaboradores com equipe_id vinculado a esta equipe
          if(!membrosTabela.length){
            membrosTabela = colaboradores
              .filter(function(c){return c.equipe_id===eq.id && c.ativo!==false;})
              .map(function(c){return {equipe_id:eq.id, colaborador_id:c.id, funcao:'eletricista'};});
          }
          if(!_plptProgDados[eq.id]) _plptProgDados[eq.id]={
            prog:null, projetos:[],
            membros: membrosTabela
          };
        });
      progProjCarregarStatusBanco(_plptProgData, plptProgRender);
    }).catch(function(){ progProjCarregarStatusBanco(_plptProgData, plptProgRender); });
    }); // fim Promise.all([carregarEquipes, carregarColabs])
  });
}

function plptProgRender(){
  var lista=document.getElementById('plpt-prog-lista'); if(!lista)return;
  var filtTipo=(document.getElementById('plpt-prog-tipo')||{}).value||'';
  var eqs=equipes.filter(function(e){
    if(e.contrato_id!==_plptProgCid||e.status!=='Ativo')return false;
    if(filtTipo&&(e.nome_equipe||'').toUpperCase().indexOf(filtTipo)<0)return false;
    return true;
  }).sort(function(a,b){return (a.nome_equipe||'').localeCompare(b.nome_equipe||'');});

  if(!eqs.length){
    lista.innerHTML='<div style="text-align:center;padding:3rem;color:#aaa">Nenhuma equipe encontrada.</div>';
    return;
  }

  // Métricas
  var metr=document.getElementById('plpt-prog-metricas');
  if(metr){
    var total=eqs.length;
    var progr=eqs.filter(function(e){return _plptProgDados[e.id]&&_plptProgDados[e.id].prog;}).length;
    var comProj=eqs.filter(function(e){return _plptProgDados[e.id]&&(_plptProgDados[e.id].projetos||[]).length>0;}).length;
    var semEnc=eqs.filter(function(e){return !(_plptProgDados[e.id]&&(_plptProgDados[e.id].prog||{}).encarregado_id);}).length;
    metr.innerHTML=[
      {l:'Total equipes',v:total,c:'#555'},
      {l:'Programadas',v:progr,c:'#3B6D11'},
      {l:'Com projetos',v:comProj,c:'#185FA5'},
      {l:'Sem encarregado',v:semEnc,c:semEnc>0?'#A32D2D':'#3B6D11'},
      {l:'Sem programação',v:total-progr,c:total-progr>0?'#854F0B':'#3B6D11'},
    ].map(function(m){
      return '<div style="padding:.4rem .5rem"><div style="font-size:10px;color:#888">'+m.l+'</div>'
        +'<div style="font-size:18px;font-weight:700;color:'+m.c+'">'+m.v+'</div></div>';
    }).join('');
  }

  lista.innerHTML='<div id="plpt-sec-topo"></div>'+eqs.map(function(eq){
    var dado=_plptProgDados[eq.id]||{prog:null,projetos:[],membros:[]};
    var prog=dado.prog||{}, projs=dado.projetos||[], membros=dado.membros||[];
    var plptCelId = (dado.prog||{}).celular_id||'';
    var tipo=eq.nome_equipe.indexOf('LV')>=0?'LV':eq.nome_equipe.indexOf('VIA')>=0?'VIA':'LM';
    var tipoCor={LM:'#185FA5',LV:'#3B6D11',VIA:'#854F0B'}[tipo]||'#555';
    var isProgr=!!(prog.encarregado_id);

    // Veículos já alocados neste dia (exceto o desta equipe)
    var veiculosOcupados = {};
    eqs.forEach(function(e){
      if(e.id===eq.id) return;
      var d2=_plptProgDados[e.id];
      if(d2&&d2.prog&&d2.prog.veiculo_id) veiculosOcupados[d2.prog.veiculo_id]=e.nome_equipe;
    });

    // Colaboradores já alocados como membros de outras equipes
    var colabsOcupados = {};
    eqs.forEach(function(e){
      if(e.id===eq.id) return;
      var d2=_plptProgDados[e.id];
      if(!d2) return;
      // Encarregado de outra equipe
      if(d2.prog&&d2.prog.encarregado_id) colabsOcupados[d2.prog.encarregado_id]=e.nome_equipe;
      // Membros de outra equipe
      (d2.membros||[]).forEach(function(m){ colabsOcupados[m.colaborador_id]=e.nome_equipe; });
    });

    // Select de encarregado — oculta quem está em outra equipe
    var colabOpts='<option value="">Selecione...</option>'
      +colaboradores.filter(function(c){
        if(c.contrato_id!==_plptProgCid||c.ativo===false||c.vinculo!=='campo') return false;
        // Mostrar mesmo que esteja ocupado SE for o encarregado atual desta equipe
        if(prog.encarregado_id===c.id) return true;
        var _stPlpt=(typeof _progStatus!=='undefined'?_progStatus[c.id]:'')||'disponivel';
        if(['ferias','afastado','treinamento','falta','faltou','verificar','fraude','demitido','integracao','patio'].indexOf(_stPlpt)>=0) return false;
        return !colabsOcupados[c.id];
      }).map(function(c){
        return '<option value="'+c.id+'"'+(prog.encarregado_id===c.id?' selected':'')+'>'+c.nome+(c.re?' ('+c.re+')':'')+'</option>';
      }).join('');

    // Select de veículo — oculta os já alocados
    var veicOpts='<option value="">— Sem veículo —</option>'
      +(frt_veiculos&&frt_veiculos.length
        ? frt_veiculos.filter(function(v){
            if(v.ativo===false) return false;
            var cid=(v.contrato_id||'').trim();
            // Aceitar veículos do contrato atual ou sem contrato definido
            var isContrato = !cid || cid===_plptProgCid
              || (function(){
                var cont=contratos.find(function(x){return x.id===_plptProgCid;});
                if(!cont) return cid==='PLPT-PLPT TERESINA'||cid==='PLPT TERESINA'||cid==='PLPT';
                return cid===cont.id||cid.toUpperCase().indexOf((cont.codigo||'').toUpperCase())>=0
                    || cid.toUpperCase().indexOf((cont.nome||'').split(' ')[0].toUpperCase())>=0;
              })();
            if(!isContrato) return false;
            // Mostrar mesmo que ocupado SE for o veículo atual desta equipe
            if(prog.veiculo_id===v.id) return true;
            return !veiculosOcupados[v.id];
          }).map(function(v){
            return '<option value="'+v.id+'" data-placa="'+(v.placa||'')+'"'
              +(prog.veiculo_id===v.id?' selected':'')+'>'
              +(v.placa||'')+(v.modelo?' — '+v.modelo:'')+'</option>';
          }).join('')
        : '<option disabled>Carregando...</option>');

    var membrosHtml=membros.map(function(m){
      var col=colaboradores.find(function(c){return c.id===m.colaborador_id;})||{nome:'?'};
      return '<span style="background:#f0efe8;border-radius:4px;padding:2px 7px;font-size:10px">'+col.nome.split(' ')[0]+'</span>';
    }).join(' ');

    var projHtml=projs.length
      ?projs.map(function(pj,i){
          var sot=sot_projetos.find(function(x){return x.id===pj.projeto_id;})||{};
          return '<div style="display:flex;align-items:center;gap:6px;padding:3px 0;border-top:.5px solid #f5f5f3">'
            +'<span style="font-size:10px;color:#888;width:16px;text-align:right">'+(i+1)+'.</span>'
            +'<span style="font-size:11px;font-weight:500;flex:1">'+(sot.codigo_cliente||sot.nome||'?')+'</span>'
            +'<span style="font-size:10px;color:#888">'+(sot.nome||'')+'</span>'
            +'<button onclick="plptProgRemoverProjeto(\''+eq.id+'\','+i+')" style="background:none;border:none;color:#A32D2D;cursor:pointer;font-size:13px">✕</button>'
            +'</div>';
        }).join('')
      :'<div style="font-size:11px;color:#ccc;padding:4px 0">Nenhum projeto programado</div>';

    return '<div class="card" style="margin-bottom:.6rem" id="plpt-eq-card-'+eq.id+'">'
      // Header
      +'<div style="display:flex;align-items:center;gap:10px;padding:.6rem 1rem;background:'+(isProgr?'#EAF3DE':'#f9f9f7')+';border-bottom:.5px solid #e0dfd8">'
      +'<span style="background:'+tipoCor+';color:#fff;padding:2px 8px;border-radius:4px;font-size:11px;font-weight:600">'+tipo+'</span>'
      +'<span style="font-weight:700;font-size:14px">'+eq.nome_equipe+'</span>'
      +'<span style="font-size:11px;color:#888">'+(eq.supervisor||'')+'</span>'
      +'<span style="margin-left:auto;font-size:11px;font-weight:600;color:'+(isProgr?'#3B6D11':'#A32D2D')+'">'+(isProgr?'✅ Programada':'⚠ Não programada')+'</span>'
      +'</div>'
      // Body
      +'<div style="padding:.75rem 1rem;display:grid;grid-template-columns:1fr 1fr;gap:.75rem">'
      +'<div><label style="font-size:10px;font-weight:600;color:#555;display:block;margin-bottom:3px">Encarregado</label>'
      +'<select class="inp" id="plpt-enc-'+eq.id+'" style="width:100%;font-size:12px" onchange="plptProgOnChange(\''+eq.id+'\')">'+colabOpts+'</select></div>'
      +'<div><label style="font-size:10px;font-weight:600;color:#555;display:block;margin-bottom:3px">Veículo</label>'
      +'<select class="inp" id="plpt-veic-'+eq.id+'" style="width:100%;font-size:12px" onchange="plptProgOnChange(\''+eq.id+'\')">'+veicOpts+'</select></div>'
      +'<div style="grid-column:span 2"><label style="font-size:10px;font-weight:600;color:#555;display:block;margin-bottom:3px">'
      +'Membros fixos <button onclick="plptProgEditarMembros(\''+eq.id+'\')" style="background:none;border:none;cursor:pointer;font-size:10px;color:#185FA5">✎ editar</button></label>'
      +(membrosHtml||'<span style="font-size:11px;color:#ccc">Nenhum membro cadastrado</span>')+'</div>'
      +(function(){
        var _celB=plptCelId?(_celulares||[]).find(function(x){return x.id===plptCelId;}):null;
        var _lblB=_celB?escHtml(_celB.numero):'📱 Cel...';
        var _bgB=_celB?'#E6F1FB':'#f5f5f3';var _corB=_celB?'#185FA5':'#888';var _brdB=_celB?'#185FA5':'#ccc';
        return '<div><label style="font-size:10px;font-weight:600;color:#555;display:block;margin-bottom:3px">📱 Celular</label>'
          +'<button class="plpt-cel-btn" data-eq="'+eq.id+'" data-dt="'+data+'" '
          +'style="font-size:10px;background:'+_bgB+';color:'+_corB+';border:.5px solid '+_brdB+';border-radius:4px;padding:3px 8px;cursor:pointer;width:100%;text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'
          +_lblB+'</button></div>';
      })()
      +'<div style="grid-column:span 2"><label style="font-size:10px;font-weight:600;color:#555;display:block;margin-bottom:3px">Obs. do dia</label>'
      +'<input class="inp" id="plpt-obs-'+eq.id+'" value="'+(prog.obs||'')+'" style="width:100%;font-size:12px" placeholder="Opcional..."/></div>'
      +'<div style="grid-column:span 2"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">'
      +'<label style="font-size:10px;font-weight:600;color:#555">Projetos do dia (em ordem)</label>'
      +'<button class="btn btn-sm btn-pri" style="font-size:10px" onclick="plptProgAdicionarProjeto(\''+eq.id+'\')">+ Projeto</button>'
      +'</div><div id="plpt-projs-'+eq.id+'">'+projHtml+'</div></div>'
      // Botão salvar individual
      +'<div style="grid-column:span 2;text-align:right;border-top:.5px solid #f0efe8;padding-top:.5rem;margin-top:.25rem">'
      +'<button class="btn btn-pri" style="font-size:11px" onclick="plptProgSalvarEquipe(\''+eq.id+'\')">💾 Salvar esta equipe</button>'
      +'</div>'
      +'</div></div>';
  }).join('');
  // Bind dos botões de celular PLPT
  if(lista) lista.querySelectorAll('.plpt-cel-btn').forEach(function(btn){
    btn.addEventListener('click', function(){
      progAbrirSelecionarCelular(this.dataset.eq, this.dataset.dt);
    });
  });
}

function plptProgOnChange(eqId){
  if(!_plptProgDados[eqId])_plptProgDados[eqId]={prog:{},projetos:[],membros:[]};
  var d=_plptProgDados[eqId]; if(!d.prog)d.prog={};
  var selEnc=document.getElementById('plpt-enc-'+eqId);
  var selVeic=document.getElementById('plpt-veic-'+eqId);
  d.prog.encarregado_id=(selEnc||{}).value||null;
  d.prog.encarregado_nome=selEnc?(selEnc.options[selEnc.selectedIndex]||{}).text||'':'';
  d.prog.veiculo_id=(selVeic&&selVeic.value)?selVeic.value:null;
  var card=document.getElementById('plpt-eq-card-'+eqId);
  if(card){var hdr=card.children[0];if(hdr)hdr.style.background=d.prog.encarregado_id?'#EAF3DE':'#f9f9f7';}
  // Re-renderizar para atualizar exclusividade nos outros cards
  setTimeout(function(){ plptProgRender(); }, 100);
}

// Salvar programação de UMA equipe específica
function plptProgSalvarEquipe(eqId){
  var selEnc  = document.getElementById('plpt-enc-'+eqId);
  var selVeic = document.getElementById('plpt-veic-'+eqId);
  var obs     = (document.getElementById('plpt-obs-'+eqId)||{}).value||'';
  if(!selEnc||!selEnc.value){ alert('Selecione o encarregado antes de salvar.'); return; }

  var dado = _plptProgDados[eqId]||{prog:null,projetos:[],membros:[]};
  var encOpt  = selEnc.options[selEnc.selectedIndex]||{};
  var encNome = (encOpt.text||'').replace(/\s*\([^)]*\)\s*$/,'').trim();
  var veicOpt = selVeic ? (selVeic.options[selVeic.selectedIndex]||{}) : {};

  var payload = {
    equipe_id:        eqId,
    contrato_id:      _plptProgCid,
    data:             _plptProgData,
    encarregado_id:   selEnc.value||null,
    encarregado_nome: encNome,
    veiculo_id:       selVeic&&selVeic.value?selVeic.value:null,
    obs:              obs,
    status:           'programado'
  };

  var projs = (dado.projetos||[]).map(function(p,i){
    return {projeto_id:p.projeto_id, ordem:i+1, status:'pendente'};
  });

  var btn = document.querySelector('#plpt-eq-card-'+eqId+' .btn-pri');
  if(btn){ btn.disabled=true; btn.textContent='Salvando...'; }

  if(!DEMO){
    var salvarProjs = function(progId){
      if(!projs.length) return;
      fetch(SB.url+'/rest/v1/plpt_prog_projetos?prog_dia_id=eq.'+progId,{
        method:'DELETE',headers:{'apikey':SB.key,'Authorization':'Bearer '+(_sbAuthToken||SB.key)}
      }).then(function(){
        sbInsert('plpt_prog_projetos', projs.map(function(p){
          return Object.assign({prog_dia_id:progId},p);
        }));
      });
    };

    if(dado.prog&&dado.prog.id){
      sbUpdate('plpt_prog_dia', payload, 'id=eq.'+dado.prog.id).then(function(){
        salvarProjs(dado.prog.id);
        if(!dado.prog) dado.prog={};
        Object.assign(dado.prog, payload);
        progShowToast('✅ '+_plptEqNome(eqId)+' salva');
        plptProgRender();
      });
    } else {
      sbInsert('plpt_prog_dia', payload).then(function(res){
        if(res&&res[0]&&res[0].id){
          if(!dado.prog) dado.prog={};
          Object.assign(dado.prog, payload);
          dado.prog.id = res[0].id;
          salvarProjs(res[0].id);
        }
        progShowToast('✅ '+_plptEqNome(eqId)+' salva');
        plptProgRender();
      });
    }
  } else {
    if(!dado.prog) dado.prog={};
    Object.assign(dado.prog, payload);
    progShowToast('✅ '+_plptEqNome(eqId)+' salva (demo)');
    plptProgRender();
  }
}

function _plptEqNome(eqId){
  var eq = equipes.find(function(e){return e.id===eqId;});
  return eq ? eq.nome_equipe : eqId;
}

function plptProgAdicionarProjeto(eqId){
  window._plptAddingToEq = eqId;

  function abrirModal(projsCid){
    var html = '<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
      +'<div class="modal" style="max-width:480px">'
      +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.5rem">'
      +'<h3 style="margin:0">+ Adicionar Projeto</h3>'
      +'<button onclick="closeModal()" style="background:none;border:none;font-size:20px;cursor:pointer;color:#888;line-height:1">✕</button>'
      +'</div>'
      +'<input class="inp" id="plpt-busca-proj" placeholder="Buscar por código ou nome..." style="width:100%;margin-bottom:.5rem" oninput="plptFiltrarProjetosModal()"/>'
      +'<div id="plpt-lista-proj" style="max-height:320px;overflow-y:auto;border:.5px solid #e0dfd8;border-radius:8px">'
      +(projsCid.length ? projsCid.map(function(p){
        var sc={Recebido:'#888',Programado:'#185FA5','Em execução':'#3B6D11',Viabilizado:'#185FA5'}[p.status]||'#888';
        return '<div onclick="plptSelecionarProjeto(\''+eqId+'\',\''+p.id+'\')" '
          +'style="padding:9px 12px;cursor:pointer;border-bottom:.5px solid #f0efe8" '
          +'onmouseover="this.style.background=\'#f5f5f3\'" onmouseout="this.style.background=\'\'">'
          +'<div style="font-size:12px;font-weight:600">'+(p.codigo_cliente||'S/N')+' — '+p.nome+'</div>'
          +'<div style="font-size:10px;color:'+sc+'">'+p.status+'</div></div>';
      }).join('') : '<div style="padding:1rem;text-align:center;color:#aaa">Nenhum projeto cadastrado para o PLPT.<br>Cadastre projetos em Obras → PLPT.</div>')
      +'</div>'
      +'<div style="margin-top:.75rem;text-align:right">'
      +'<button class="btn" onclick="closeModal()">Cancelar</button>'
      +'</div></div></div>';
    setModal(html);
  }

  // Tentar usar projetos em memória primeiro
  var projsCid = sot_projetos.filter(function(p){
    return p.contrato_id === _plptProgCid && p.status !== 'Cancelado';
  });

  if(projsCid.length || DEMO){
    abrirModal(projsCid);
  } else {
    // Buscar do banco se memória estiver vazia
    abrirModal([]); // Abre com "carregando..."
    var lista = document.getElementById('plpt-lista-proj');
    if(lista) lista.innerHTML = '<div style="padding:1rem;text-align:center;color:#aaa">Carregando projetos...</div>';

    sbFetchPaged('sot_projetos',{filters:['contrato_id=eq.'+_plptProgCid,'status=neq.Cancelado'],order:'criado_em.desc'})
      .then(function(rows){
        if(rows&&rows.length){
          rows.forEach(function(p){
            if(!sot_projetos.find(function(x){return x.id===p.id;})) sot_projetos.push(p);
          });
          projsCid = rows;
        }
        var listaEl = document.getElementById('plpt-lista-proj');
        if(listaEl){
          listaEl.innerHTML = projsCid.length ? projsCid.map(function(p){
            var sc={Recebido:'#888',Programado:'#185FA5','Em execução':'#3B6D11',Viabilizado:'#185FA5'}[p.status]||'#888';
            return '<div onclick="plptSelecionarProjeto(\''+eqId+'\',\''+p.id+'\')" '
              +'style="padding:9px 12px;cursor:pointer;border-bottom:.5px solid #f0efe8" '
              +'onmouseover="this.style.background=\'#f5f5f3\'" onmouseout="this.style.background=\'\'">'
              +'<div style="font-size:12px;font-weight:600">'+(p.codigo_cliente||'S/N')+' — '+p.nome+'</div>'
              +'<div style="font-size:10px;color:'+sc+'">'+p.status+'</div></div>';
          }).join('') : '<div style="padding:1rem;text-align:center;color:#aaa">Nenhum projeto cadastrado para o PLPT.</div>';
        }
      }).catch(function(){
        var listaEl = document.getElementById('plpt-lista-proj');
        if(listaEl) listaEl.innerHTML = '<div style="padding:1rem;text-align:center;color:#A32D2D">Erro ao carregar projetos.</div>';
      });
  }
}

function plptFiltrarProjetosModal(){
  var q=((document.getElementById('plpt-busca-proj')||{}).value||'').toLowerCase();
  Array.from(document.querySelectorAll('#plpt-lista-proj>div')).forEach(function(el){
    el.style.display=el.textContent.toLowerCase().indexOf(q)>=0?'':'none';
  });
}

function plptSelecionarProjeto(eqId,projId){
  if(!_plptProgDados[eqId])_plptProgDados[eqId]={prog:{},projetos:[],membros:[]};
  var projs=_plptProgDados[eqId].projetos;
  if(projs.find(function(p){return p.projeto_id===projId;})){alert('Projeto já adicionado.');return;}
  projs.push({projeto_id:projId,ordem:projs.length+1,status:'pendente'});
  closeModal();
  var el=document.getElementById('plpt-projs-'+eqId);
  if(el){
    var sot=sot_projetos.find(function(x){return x.id===projId;})||{};
    var i=projs.length-1;
    var emptyMsg=el.querySelector('div[style*="color:#ccc"]');
    if(emptyMsg)emptyMsg.remove();
    var row=document.createElement('div');
    row.style.cssText='display:flex;align-items:center;gap:6px;padding:3px 0;border-top:.5px solid #f5f5f3';
    row.innerHTML='<span style="font-size:10px;color:#888;width:16px;text-align:right">'+(i+1)+'.</span>'
      +'<span style="font-size:11px;font-weight:500;flex:1">'+(sot.codigo_cliente||sot.nome||'?')+'</span>'
      +'<span style="font-size:10px;color:#888">'+(sot.nome||'')+'</span>'
      +'<button onclick="plptProgRemoverProjeto(\''+eqId+'\','+i+')" style="background:none;border:none;color:#A32D2D;cursor:pointer;font-size:13px">✕</button>';
    el.appendChild(row);
  }
  progShowToast('Projeto adicionado');
}

function plptProgRemoverProjeto(eqId,idx){
  if(!_plptProgDados[eqId])return;
  _plptProgDados[eqId].projetos.splice(idx,1);
  _plptProgDados[eqId].projetos.forEach(function(p,i){p.ordem=i+1;});
  var el=document.getElementById('plpt-projs-'+eqId);
  if(!el)return;
  var projs=_plptProgDados[eqId].projetos;
  el.innerHTML=projs.length?projs.map(function(pj,i){
    var sot=sot_projetos.find(function(x){return x.id===pj.projeto_id;})||{};
    return '<div style="display:flex;align-items:center;gap:6px;padding:3px 0;border-top:.5px solid #f5f5f3">'
      +'<span style="font-size:10px;color:#888;width:16px;text-align:right">'+(i+1)+'.</span>'
      +'<span style="font-size:11px;font-weight:500;flex:1">'+(sot.codigo_cliente||sot.nome||'?')+'</span>'
      +'<span style="font-size:10px;color:#888">'+(sot.nome||'')+'</span>'
      +'<button onclick="plptProgRemoverProjeto(\''+eqId+'\','+i+')" style="background:none;border:none;color:#A32D2D;cursor:pointer;font-size:13px">✕</button>'
      +'</div>';
  }).join(''):'<div style="font-size:11px;color:#ccc;padding:4px 0">Nenhum projeto programado</div>';
}


function plptFiltrarMembrosModal(){
  var q=((document.getElementById('plpt-busca-mem')||{}).value||'').toLowerCase();
  Array.from(document.querySelectorAll('#plpt-lista-mem label')).forEach(function(el){
    el.style.display=el.textContent.toLowerCase().indexOf(q)>=0?'':'none';
  });
}

function plptSalvarMembros(eqId){
  var sel=Array.from(document.querySelectorAll('#plpt-lista-mem input:checked')).map(function(cb){return cb.value;});
  if(!_plptProgDados[eqId])_plptProgDados[eqId]={prog:{},projetos:[],membros:[]};
  _plptProgDados[eqId].membros=sel.map(function(cid){return{equipe_id:eqId,colaborador_id:cid,funcao:'eletricista'};});
  if(!DEMO){
    fetch(SB.url+'/rest/v1/plpt_equipe_membros?equipe_id=eq.'+eqId,{
      method:'DELETE',headers:{'apikey':SB.key,'Authorization':'Bearer '+(_sbAuthToken||SB.key)}
    }).then(function(){
      if(sel.length)sbInsert('plpt_equipe_membros',_plptProgDados[eqId].membros);
    });
  }
  closeModal();plptProgRender();
  progShowToast('✅ '+sel.length+' membro(s) salvos');
}

function plptProgSalvarTudo(){
  var eqs=equipes.filter(function(e){return e.contrato_id===_plptProgCid&&e.status==='Ativo';});
  var salvos=0;
  eqs.forEach(function(eq){
    var selEnc=document.getElementById('plpt-enc-'+eq.id);
    if(!selEnc||!selEnc.value)return;
    var selVeic=document.getElementById('plpt-veic-'+eq.id);
    var obs=(document.getElementById('plpt-obs-'+eq.id)||{}).value||'';
    var dado=_plptProgDados[eq.id]||{prog:null,projetos:[],membros:[]};
    var encOpt=selEnc.options[selEnc.selectedIndex]||{};
    // Pegar só o nome sem o RE entre parênteses
    var encNome = (encOpt.text||'').replace(/\s*\([^)]*\)\s*$/, '').trim();
    var payload={equipe_id:eq.id,contrato_id:_plptProgCid,data:_plptProgData,
      encarregado_id:selEnc.value||null,encarregado_nome:encNome,
      veiculo_id:selVeic&&selVeic.value?selVeic.value:null,obs:obs,status:'programado'};
    var projs=(dado.projetos||[]).map(function(p,i){
      return{projeto_id:p.projeto_id,ordem:i+1,status:'pendente'};
    });
    if(!DEMO){
      if(dado.prog&&dado.prog.id){
        sbUpdate('plpt_prog_dia',payload,'id=eq.'+dado.prog.id);
        fetch(SB.url+'/rest/v1/plpt_prog_projetos?prog_dia_id=eq.'+dado.prog.id,{
          method:'DELETE',headers:{'apikey':SB.key,'Authorization':'Bearer '+(_sbAuthToken||SB.key)}
        }).then(function(){
          if(projs.length)sbInsert('plpt_prog_projetos',projs.map(function(p){return Object.assign({prog_dia_id:dado.prog.id},p);}));
        });
      } else {
        sbInsert('plpt_prog_dia',payload).then(function(res){
          if(res&&res[0]&&res[0].id){
            if(!dado.prog)dado.prog={};
            dado.prog.id=res[0].id;
            if(projs.length)sbInsert('plpt_prog_projetos',projs.map(function(p){return Object.assign({prog_dia_id:res[0].id},p);}));
          }
        });
      }
    }
    salvos++;
  });
  plptProgRender();
  progShowToast('✅ Programação salva — '+salvos+' equipe(s)');
}
var sug_dados = [];
var _sugEditId = null;
var _sugEditFotos = [];

var SUG_STATUS = {
  analise:  {label:'Em análise',  cor:'#185FA5', bg:'#E6F1FB', icon:'🔍'},
  aprovada: {label:'Aprovada',    cor:'#3B6D11', bg:'#EAF3DE', icon:'✅'},
  aplicada: {label:'Aplicada',    cor:'#0F6E56', bg:'#E0F4EE', icon:'🚀'},
  recusada: {label:'Recusada',    cor:'#A32D2D', bg:'#FCEBEB', icon:'❌'},
};

function sug_init(){
  // Carregar do banco
  if(!DEMO){
    sbFetch('sugestoes_melhorias',{order:'criado_em.desc'}).then(function(rows){
      if(rows&&rows.length){
        sug_dados = rows.map(function(r){
          var fotos = [];
          try{ fotos = JSON.parse(r.fotos||'[]'); }catch(e){}
          return {
            id:r.id, texto:r.texto, status:r.status||'analise',
            usuario_id:r.usuario_id, usuario_nome:r.usuario_nome||'Usuário',
            criado_em:r.criado_em, fotos:fotos,
            resposta:r.resposta||'', arquivada:r.arquivada||false
          };
        });
      }
      sug_render();
    }).catch(function(){ sug_render(); });
  } else {
    sug_render();
  }
}

function sug_render(){
  var lista = document.getElementById('sug-lista');
  if(!lista) return;

  var filtSt  = (document.getElementById('sug-fil-status')||{}).value||'';
  var busca   = ((document.getElementById('sug-busca')||{}).value||'').toLowerCase();

  var dados = sug_dados.filter(function(s){
    if(s.arquivada) return false;
    if(filtSt && s.status !== filtSt) return false;
    if(busca && (s.texto||'').toLowerCase().indexOf(busca)<0
             && (s.usuario_nome||'').toLowerCase().indexOf(busca)<0) return false;
    return true;
  });

  if(!dados.length){
    lista.innerHTML = '<div style="text-align:center;padding:3rem;color:#aaa">'
      +'<div style="font-size:40px;margin-bottom:.5rem">💡</div>'
      +'<div>Nenhuma sugestão encontrada.</div></div>';
    return;
  }

  lista.innerHTML = dados.map(function(s){
    var st  = SUG_STATUS[s.status] || SUG_STATUS.analise;
    var dtF = s.criado_em ? new Date(s.criado_em).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit',year:'2-digit',hour:'2-digit',minute:'2-digit'}) : '—';
    var isAdmin = usuarioLogado && (usuarioLogado.perfil==='admin'||usuarioLogado.perfil==='gestor');
    var podeEditar = sug_podeEditar(s);

    var fotosHtml = '';
    if(s.fotos && s.fotos.length){
      fotosHtml = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:.5rem">'
        +s.fotos.map(function(f,i){
          return '<img src="'+f+'" style="height:64px;width:64px;object-fit:cover;border-radius:6px;cursor:pointer;border:.5px solid #e0dfd8" onclick="sug_verFoto(\''+s.id+'\','+i+')" title="Ver foto"/>';
        }).join('')
        +'</div>';
    }

    var respostaHtml = s.resposta
      ? '<div style="margin-top:.5rem;padding:.4rem .6rem;background:#f5f5f3;border-radius:6px;font-size:11px;color:#555;border-left:2px solid '+st.cor+'">'
        +'<b>Resposta:</b> '+s.resposta+'</div>'
      : '';

    var acoesHtml = '';
    if(podeEditar || isAdmin){
      acoesHtml = '<div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:.6rem">'
        +(podeEditar
          ?'<button class="btn btn-sm" onclick="sug_abrirEditar(\''+s.id+'\')" style="font-size:10px">✏️ Editar</button>'
          :'')
        +(isAdmin
          ?Object.keys(SUG_STATUS).filter(function(k){ return k!==s.status; }).map(function(k){
          var sx = SUG_STATUS[k];
          return '<button class="btn btn-sm" onclick="sug_setStatus(\''+s.id+'\',\''+k+'\')" style="font-size:10px;color:'+sx.cor+';border-color:'+sx.cor+'">'+sx.icon+' '+sx.label+'</button>';
        }).join('')
        +'<button class="btn btn-sm" onclick="sug_responder(\''+s.id+'\')" style="font-size:10px">💬 Responder</button>'
        +(s.status==='aplicada'
          ?'<button class="btn btn-sm" onclick="sug_arquivar(\''+s.id+'\')" style="font-size:10px;color:#A32D2D;border-color:#A32D2D">🗑 Arquivar</button>'
          :'')
          :'')
        +'</div>';
    }

    return '<div class="card" style="margin-bottom:.6rem;padding:.75rem 1rem">'
      +'<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px">'
      +'<div style="flex:1">'
      +'<div style="display:flex;align-items:center;gap:6px;margin-bottom:.35rem">'
      +'<span style="font-size:11px;background:'+st.bg+';color:'+st.cor+';padding:2px 8px;border-radius:20px;font-weight:600">'+st.icon+' '+st.label+'</span>'
      +'<span style="font-size:11px;color:#888">'+s.usuario_nome+'</span>'
      +'<span style="font-size:10px;color:#bbb">'+dtF+'</span>'
      +'</div>'
      +'<div style="font-size:13px;color:#1a1a18;line-height:1.5">'+s.texto+'</div>'
      +fotosHtml
      +respostaHtml
      +acoesHtml
      +'</div>'
      +'</div></div>';
  }).join('');
}

function sug_abrirNova(){
  var html = '<div class="modal-bg"><div class="modal" style="max-width:520px">'
    +'<h3 style="margin-bottom:.5rem">💡 Nova Sugestão de Melhoria</h3>'
    +'<div style="font-size:12px;color:#888;margin-bottom:.75rem">Sua sugestão será analisada pela equipe responsável.</div>'
    +'<div class="fg"><label>Descreva sua sugestão *</label>'
    +'<textarea id="sug-novo-texto" class="inp" style="width:100%;height:100px;resize:vertical" placeholder="Descreva a melhoria que você sugere, o problema que resolveria ou a funcionalidade que gostaria de ver..."></textarea></div>'
    +'<div class="fg"><label>Foto / Print (opcional)</label>'
    +'<input type="file" id="sug-novo-foto" accept="image/*" multiple style="width:100%;font-size:12px" onchange="sug_previewFotos()"/>'
    +'<div id="sug-fotos-prev" style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px"></div>'
    +'</div>'
    +'<div class="ma">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="sug_salvarNova()">Enviar sugestão</button>'
    +'</div></div></div>';
  setModal(html);
  setTimeout(function(){
    document.querySelectorAll('.mn-full-btn').forEach(function(btn){
      btn.onclick=function(){
        closeModal();
        var i=parseInt(this.getAttribute('data-mi'));
        if(itensMenu[i]) itensMenu[i].acao();
      };
    });
    // Bind do campo data de retorno
    var inpData=document.getElementById('retorno-data');
    if(inpData){
      var _orig=inpData.getAttribute('data-original')||'';
      inpData.addEventListener('change',function(){ progVerificarMudancaData(this,_orig); });
    }
  },50);
}

function sug_previewFotos(){
  var inp = document.getElementById('sug-novo-foto');
  var prev = document.getElementById('sug-fotos-prev');
  if(!inp||!prev) return;
  prev.innerHTML = '';
  Array.from(inp.files).forEach(function(file){
    var r = new FileReader();
    r.onload = function(e){
      var img = document.createElement('img');
      img.src = e.target.result;
      img.style.cssText = 'height:60px;width:60px;object-fit:cover;border-radius:6px;border:.5px solid #e0dfd8';
      prev.appendChild(img);
    };
    r.readAsDataURL(file);
  });
}

function sug_salvarNova(){
  var texto = ((document.getElementById('sug-novo-texto')||{}).value||'').trim();
  if(!texto){ alert('Descreva sua sugestão antes de enviar.'); return; }

  var inp = document.getElementById('sug-novo-foto');
  var files = inp ? Array.from(inp.files) : [];

  function salvarComFotos(fotos){
    var nova = {
      id: 'sug'+Date.now(),
      texto: texto,
      status: 'analise',
      usuario_id:   usuarioLogado ? usuarioLogado.id   : 'anonimo',
      usuario_nome: usuarioLogado ? usuarioLogado.nome : 'Usuário',
      criado_em: new Date().toISOString(),
      fotos: fotos,
      resposta: '',
      arquivada: false
    };
    sug_dados.unshift(nova);
    if(!DEMO){
      sbInsert('sugestoes_melhorias',{
        texto:nova.texto, status:nova.status,
        usuario_id:nova.usuario_id, usuario_nome:nova.usuario_nome,
        fotos:JSON.stringify(fotos), resposta:'', arquivada:false
      }).then(function(res){
        if(res&&res[0]&&res[0].id){
          nova.id = res[0].id;
          console.log('Sugestão salva no banco, id:', nova.id);
        } else {
          console.warn('sbInsert retornou sem id:', res);
          alert('⚠ Sugestão salva localmente mas pode não ter sido gravada no banco. Verifique o console.');
        }
      }).catch(function(e){
        console.error('Erro ao salvar sugestão:', e);
        alert('❌ Erro ao salvar no banco: ' + e);
      });
    } else {
      console.log('Modo DEMO — sugestão salva só na memória');
    }
    closeModal();
    sug_render();
    alert('✅ Sugestão enviada! Nossa equipe irá analisar em breve.');
  }

  if(!files.length){ salvarComFotos([]); return; }

  // Converter fotos para base64
  var fotos = [];
  var done  = 0;
  files.forEach(function(file, i){
    var reader = new FileReader();
    reader.onload = function(e){
      fotos[i] = e.target.result;
      done++;
      if(done === files.length) salvarComFotos(fotos);
    };
    reader.readAsDataURL(file);
  });
}

function sug_setStatus(id, novoStatus){
  var s = sug_dados.find(function(x){ return x.id===id; });
  if(!s) return;
  s.status = novoStatus;
  if(!DEMO) sbUpdate('sugestoes_melhorias',{status:novoStatus},'id=eq.'+id);
  sug_render();
}

function sug_responder(id){
  var s = sug_dados.find(function(x){ return x.id===id; });
  if(!s) return;
  var resp = prompt('Resposta para a sugestão:\n"'+(s.texto.length>80?s.texto.slice(0,80)+'...':s.texto)+'"', s.resposta||'');
  if(resp === null) return;
  s.resposta = resp;
  if(!DEMO) sbUpdate('sugestoes_melhorias',{resposta:resp},'id=eq.'+id);
  sug_render();
}

function sug_arquivar(id){
  if(!confirm('Arquivar esta sugestão? Ela será removida da lista mas ficará no banco.')) return;
  var s = sug_dados.find(function(x){ return x.id===id; });
  if(!s) return;
  s.arquivada = true;
  if(!DEMO) sbUpdate('sugestoes_melhorias',{arquivada:true},'id=eq.'+id);
  sug_render();
}

function sug_limparAplicadas(){
  var aplicadas = sug_dados.filter(function(s){ return s.status==='aplicada'&&!s.arquivada; });
  if(!aplicadas.length){ alert('Nenhuma sugestão aplicada para limpar.'); return; }
  if(!confirm('Arquivar '+aplicadas.length+' sugestão(ões) aplicada(s)? Elas serão removidas da lista.')) return;
  aplicadas.forEach(function(s){
    s.arquivada = true;
    if(!DEMO) sbUpdate('sugestoes_melhorias',{arquivada:true},'id=eq.'+s.id);
  });
  sug_render();
}

function sug_verFoto(id, idx){
  var s = sug_dados.find(function(x){ return x.id===id; });
  if(!s||!s.fotos||!s.fotos[idx]) return;
  setModal('<div class="modal-bg" onclick="closeModal()" style="display:flex;align-items:center;justify-content:center;cursor:pointer">'
    +'<img src="'+s.fotos[idx]+'" style="max-width:90vw;max-height:90vh;border-radius:10px;box-shadow:0 8px 32px rgba(0,0,0,.4)"/>'
    +'<div style="position:fixed;top:1rem;right:1rem;color:#fff;font-size:22px;cursor:pointer" onclick="closeModal()">✕</div>'
    +'</div>');
}

function sug_podeEditar(s){
  if(!s || s.arquivada) return false;
  if(!usuarioLogado) return false;
  var isAdmin = usuarioLogado.perfil==='admin'||usuarioLogado.perfil==='gestor';
  if(isAdmin) return true;
  return String(s.usuario_id)===String(usuarioLogado.id);
}

function sug_renderFotosEditPrev(){
  var prev = document.getElementById('sug-edit-fotos-prev');
  if(!prev) return;
  prev.innerHTML = _sugEditFotos.map(function(f,i){
    return '<div style="position:relative;display:inline-block">'
      +'<img src="'+f+'" style="height:60px;width:60px;object-fit:cover;border-radius:6px;border:.5px solid #e0dfd8"/>'
      +'<button type="button" onclick="sug_removerFotoEdit('+i+')" style="position:absolute;top:-4px;right:-4px;width:18px;height:18px;border-radius:50%;border:none;background:#A32D2D;color:#fff;font-size:11px;cursor:pointer;line-height:1">×</button>'
      +'</div>';
  }).join('');
}

function sug_abrirEditar(id){
  var s = sug_dados.find(function(x){ return x.id===id; });
  if(!s || !sug_podeEditar(s)){ alert('Você não tem permissão para editar esta sugestão.'); return; }
  _sugEditId = id;
  _sugEditFotos = (s.fotos||[]).slice();
  var html = '<div class="modal-bg"><div class="modal" style="max-width:520px">'
    +'<h3 style="margin-bottom:.5rem">✏️ Editar Sugestão</h3>'
    +'<div class="fg"><label>Descrição *</label>'
    +'<textarea id="sug-edit-texto" class="inp" style="width:100%;height:100px;resize:vertical" placeholder="Descreva a melhoria..."></textarea></div>'
    +'<div class="fg"><label>Fotos / Prints</label>'
    +'<div id="sug-edit-fotos-prev" style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:6px"></div>'
    +'<input type="file" id="sug-edit-foto" accept="image/*" multiple style="width:100%;font-size:12px" onchange="sug_previewFotosEdit()"/>'
    +'</div>'
    +'<div class="ma">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="sug_salvarEdicao()">Salvar alterações</button>'
    +'</div></div></div>';
  setModal(html);
  setTimeout(function(){
    var ta = document.getElementById('sug-edit-texto');
    if(ta) ta.value = s.texto||'';
    sug_renderFotosEditPrev();
  },50);
}

function sug_previewFotosEdit(){
  var inp = document.getElementById('sug-edit-foto');
  if(!inp) return;
  Array.from(inp.files).forEach(function(file){
    var r = new FileReader();
    r.onload = function(e){
      _sugEditFotos.push(e.target.result);
      sug_renderFotosEditPrev();
    };
    r.readAsDataURL(file);
  });
  inp.value = '';
}

function sug_removerFotoEdit(idx){
  _sugEditFotos.splice(idx,1);
  sug_renderFotosEditPrev();
}

function sug_salvarEdicao(){
  if(!_sugEditId) return;
  var s = sug_dados.find(function(x){ return x.id===_sugEditId; });
  if(!s || !sug_podeEditar(s)){ alert('Você não tem permissão para editar esta sugestão.'); return; }
  var texto = ((document.getElementById('sug-edit-texto')||{}).value||'').trim();
  if(!texto){ alert('Descreva sua sugestão antes de salvar.'); return; }
  var fotos = _sugEditFotos.slice();
  s.texto = texto;
  s.fotos = fotos;
  if(!DEMO){
    sbUpdate('sugestoes_melhorias',{
      texto:texto,
      fotos:JSON.stringify(fotos)
    },'id=eq.'+_sugEditId).catch(function(e){
      console.error('Erro ao atualizar sugestão:', e);
      alert('❌ Erro ao salvar no banco: ' + e);
    });
  }
  _sugEditId = null;
  _sugEditFotos = [];
  closeModal();
  sug_render();
  alert('✅ Sugestão atualizada!');
}






