function rhPermKeyPagina(pageId){
  if(pageId==='rh-cargos') return 'cadastros';
  if(pageId==='rh-vagas') return 'rh-vagas';
  if(pageId==='rh-testes') return 'rh-testes';
  if(pageId==='rh-contratacao') return 'rh-contratacao';
  if(pageId==='rh-assinaturas') return 'rh-contratacao';
  if(pageId==='rh-pisos') return 'rh-pisos';
  if(pageId==='rh-beneficios') return 'rh-beneficios';
  if(pageId==='rh-conciliacao-synergy') return 'rh-conciliacao-synergy';
  if(pageId==='rh-central-divergencias') return 'rh-central-divergencias';
  if(pageId==='rh-documentos') return 'rh-documentos';
  if(pageId==='rh-entrada-ia') return 'rh-entrada-ia';
  if(pageId==='rh-regras') return 'rh-regras';
  if(pageId==='rh-pendencias') return 'rh-pendencias';
  if(pageId==='rh-conformidade') return 'rh-conformidade';
  if(pageId==='rh-prontidao') return 'rh-prontidao';
  return 'rh-dossie';
}
function rhModuloPermitido(pageId){
  var p = (usuarioLogado && usuarioLogado.perfil) || '';
  if(typeof perfilAcessoTotal==='function' && perfilAcessoTotal()) return true;
  if(['admin','gestor','administrativo','dp','rh','diretoria'].indexOf(p) < 0) return false;
  if(typeof permTemAcesso !== 'function') return true;
  if(permTemAcesso('rh-dossie')===false) return false;
  var extra = rhPermKeyPagina(pageId);
  if(extra!=='rh-dossie' && permTemAcesso(extra)===false) return false;
  return true;
}
function rhInit(pageId){
  if(!rhModuloPermitido(pageId)) return;
  rhGarantirDados(function(){
    try{
      if(pageId==='rh-dashboard') rhRenderDashboard();
      else if(pageId==='rh-dossie') rhRenderDossie();
      else if(pageId==='rh-documentos') rhRenderDocumentos();
      else if(pageId==='rh-entrada-ia') rhRenderEntradaIa();
      else if(pageId==='rh-regras') rhRenderRegras();
      else if(pageId==='rh-pendencias') rhRenderPendencias();
      else if(pageId==='rh-conformidade') rhRenderConformidade();
      else if(pageId==='rh-prontidao'){
        if(typeof rhProntidaoCarregarFontes==='function') rhProntidaoCarregarFontes().then(function(){ rhRenderProntidao(); });
        else rhRenderProntidao();
      }
      else if(pageId==='rh-vagas') rhSelRender();
      else if(pageId==='rh-testes') rhTesteRender();
      else if(pageId==='rh-contratacao') rhRenderContratacoes();
      else if(pageId==='rh-assinaturas') rhDocRenderFilaAssinaturas();
      else if(pageId==='rh-pisos') rhRenderPisos();
      else if(pageId==='rh-beneficios') rhBeneficioInit();
      else if(pageId==='rh-conciliacao-synergy') rhSynRender();
      else if(pageId==='rh-central-divergencias'){ if(typeof rhCentralAbrir==='function') rhCentralAbrir(false); else if(typeof rhCentralRender==='function') rhCentralRender(); }
      else if(pageId==='rh-atalhos') rhRenderAtalhos();
      else if(pageId==='rh-cargos'){ if(typeof rhAbrirCadastroCargos==='function') rhAbrirCadastroCargos(); }
    }catch(e){
      console.error('rhInit',pageId,e);
      if(typeof progShowToast==='function') progShowToast('Erro ao abrir tela do RH. Recarregue com Ctrl+F5.','erro');
    }
  });
}

