function rhSynNormHeader(h){
  return String(h==null?'':h)
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase().replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();
}
function rhSynNormCpf(v){
  if(v==null||v==='') return '';
  if(typeof v==='number' && isFinite(v)) v=String(Math.round(v));
  var raw=String(v).trim();
  // BRO / códigos alfanuméricos (ex.: BR0070127856) não são CPF
  if(/[A-Za-z]/.test(raw)) return '';
  var d=raw.replace(/\D/g,'');
  // Excel às vezes corta zero à esquerda
  if(d.length>=9 && d.length<11) d=('00000000000'+d).slice(-11);
  if(d.length>11) d=d.slice(-11);
  return d.length===11?d:'';
}
function rhSynNormRe(v){
  if(typeof v==='number' && isFinite(v)) v=String(Math.round(v));
  return String(v==null?'':v).replace(/\D/g,'').replace(/^0+/,'');
}
function rhSynNormMat(v){
  if(typeof v==='number' && isFinite(v)) v=String(Math.round(v));
  return String(v==null?'':v).trim().toUpperCase().replace(/\s+/g,'');
}
/** Dígitos da matrícula/RE sem zeros à esquerda — no CENA a matrícula Synergy costuma estar em colaboradores.re */
function rhSynMatDigits(v){
  return rhSynNormRe(v);
}
function rhSynNormNome(v){
  return String(v==null?'':v)
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toUpperCase().replace(/[^A-Z0-9 ]+/g,' ').replace(/\s+/g,' ').trim();
}
function rhSynParseData(v){
  if(v==null||v==='') return '';
  if(v instanceof Date && !isNaN(v.getTime())){
    var y=v.getFullYear(), m=String(v.getMonth()+1).padStart(2,'0'), d=String(v.getDate()).padStart(2,'0');
    return y+'-'+m+'-'+d;
  }
  if(typeof v==='number' && typeof XLSX!=='undefined' && XLSX.SSF){
    try{
      var parsed=XLSX.SSF.parse_date_code(v);
      if(parsed) return parsed.y+'-'+String(parsed.m).padStart(2,'0')+'-'+String(parsed.d).padStart(2,'0');
    }catch(_e){}
  }
  if(typeof rhSitDataStr==='function') return rhSitDataStr(v)||'';
  var s=String(v).trim();
  if(/^\d{2}\/\d{2}\/\d{4}/.test(s)){ var p=s.split('/'); return p[2]+'-'+p[1]+'-'+p[0]; }
  if(/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0,10);
  return '';
}
function rhSynFmtData(v){
  var s=rhSynParseData(v);
  if(!s) return '—';
  return typeof rhFmtD==='function'?rhFmtD(s):(s.slice(8,10)+'/'+s.slice(5,7)+'/'+s.slice(0,4));
}
function rhSynCell(row, field){
  var h=_rhSyn.mapping[field];
  if(!h) return '';
  var v=row[h];
  if(v==null) return '';
  if(typeof v==='number' && isFinite(v)){
    // Evita notação científica em CPF/RE/matrícula vindos do Excel
    if(field==='cpf'||field==='re'||field==='matricula') return String(Math.round(v));
  }
  if(typeof v==='string') return v.trim();
  return v;
}

/** Parser unificado — fonte: xlsx | csv | synergy_api (futuro). */
function rhSynParseSource(sourceType, payload){
  sourceType=String(sourceType||'').toLowerCase();
  var aoa=[];
  if(sourceType==='xlsx' || sourceType==='xls'){
    if(typeof XLSX==='undefined') throw new Error('Biblioteca SheetJS (XLSX) não carregada.');
    var wb=XLSX.read(payload,{type: payload instanceof ArrayBuffer ? 'array' : 'array', cellDates:true, raw:false});
    var ws=wb.Sheets[wb.SheetNames[0]];
    aoa=XLSX.utils.sheet_to_json(ws,{header:1, defval:'', blankrows:false});
  } else if(sourceType==='csv'){
    var text=typeof payload==='string'?payload:String(payload||'');
    if(text.charCodeAt(0)===0xFEFF) text=text.slice(1);
    if(typeof XLSX!=='undefined'){
      var wb2=XLSX.read(text,{type:'string', raw:false});
      var ws2=wb2.Sheets[wb2.SheetNames[0]];
      aoa=XLSX.utils.sheet_to_json(ws2,{header:1, defval:'', blankrows:false});
    } else {
      aoa=text.split(/\r?\n/).filter(function(l){return l.trim();}).map(function(line){
        var sep=line.indexOf(';')>=0?';':',';
        return line.split(sep).map(function(c){ return c.replace(/^"|"$/g,'').trim(); });
      });
    }
  } else if(sourceType==='synergy_api'){
    // Preparação futura: payload = array de objetos já tipados
    var rows=Array.isArray(payload)?payload:[];
    if(!rows.length) return {headers:[], aoa:[], dataRows:[]};
    var headers=Object.keys(rows[0]);
    aoa=[headers].concat(rows.map(function(r){ return headers.map(function(h){ return r[h]; }); }));
  } else {
    throw new Error('Fonte não suportada: '+sourceType);
  }
  while(aoa.length && !(aoa[0]||[]).some(function(c){ return String(c||'').trim(); })) aoa.shift();
  if(!aoa.length) throw new Error('Arquivo sem linhas.');
  var headers2=(aoa[0]||[]).map(function(h,i){
    var s=String(h==null?'':h).trim();
    return s||('COLUNA_'+ (i+1));
  });
  var dataRows=[];
  for(var i=1;i<aoa.length;i++){
    var r=aoa[i]||[];
    if(!r.some(function(c){ return String(c==null?'':c).trim(); })) continue;
    var obj={__linha:i+1};
    headers2.forEach(function(h,idx){ obj[h]=r[idx]==null?'':r[idx]; });
    dataRows.push(obj);
  }
  return {headers:headers2, aoa:aoa, dataRows:dataRows};
}

function rhSynScoreAlias(headerNorm, aliasNorm){
  if(!headerNorm||!aliasNorm) return 0;
  if(headerNorm===aliasNorm) return 1;
  if(headerNorm.indexOf(aliasNorm)>=0 || aliasNorm.indexOf(headerNorm)>=0){
    var longer=Math.max(headerNorm.length, aliasNorm.length);
    var shorter=Math.min(headerNorm.length, aliasNorm.length);
    return 0.72 + 0.2*(shorter/longer);
  }
  var ht=headerNorm.split(' '), at=aliasNorm.split(' ');
  var hit=0;
  at.forEach(function(t){ if(t.length>1 && ht.indexOf(t)>=0) hit++; });
  if(!hit) return 0;
  return 0.45 + 0.35*(hit/at.length);
}

function rhSynDetectMapping(headers){
  var mapping={}, confidence={}, used={};
  var needsManual=false;
  RH_SYN_FIELDS.forEach(function(f){
    var bestH=null, bestS=0;
    headers.forEach(function(h){
      if(used[h]) return;
      var hn=rhSynNormHeader(h);
      var score=0;
      f.aliases.forEach(function(a){
        score=Math.max(score, rhSynScoreAlias(hn, rhSynNormHeader(a)));
      });
      // RE curto: só match exato / quase exato
      if(f.key==='re'){
        if(hn==='re' || hn==='r e') score=1;
        else if(hn.indexOf('matricula')>=0 || hn.indexOf('cpf')>=0 || hn.indexOf('nome')>=0) score=0;
        else if(hn==='registro' || hn==='chapa') score=0.4;
      }
      if(score>bestS){ bestS=score; bestH=h; }
    });
    if(bestH && bestS>=0.72){
      mapping[f.key]=bestH; confidence[f.key]=bestS; used[bestH]=true;
    } else if(bestH && bestS>=0.45){
      mapping[f.key]=bestH; confidence[f.key]=bestS; used[bestH]=true; needsManual=true;
    } else {
      mapping[f.key]=''; confidence[f.key]=0;
      if(['cpf','nome','matricula','re'].indexOf(f.key)>=0) needsManual=true;
    }
  });
  // Evitar que a mesma coluna sirva para matricula e re se ambos fracos
  if(mapping.matricula && mapping.re && mapping.matricula===mapping.re){
    if((confidence.matricula||0)>=(confidence.re||0)){ mapping.re=''; confidence.re=0; }
    else { mapping.matricula=''; confidence.matricula=0; }
    needsManual=true;
  }
  var idOk=(confidence.cpf||0)>=0.72 || (confidence.matricula||0)>=0.72 || (confidence.re||0)>=0.72;
  if(!idOk) needsManual=true;
  return {mapping:mapping, confidence:confidence, needsManual:needsManual};
}

function rhSynInterpretSituacaoSyn(row){
  var sitRaw=String(rhSynCell(row,'situacao')||'').trim();
  var desl=rhSynParseData(rhSynCell(row,'desligamento'));
  var n=rhSynNormHeader(sitRaw);
  var codigo='desconhecido', label=sitRaw||'—', ativoLike=null;
  if(desl){
    codigo='desligado'; label='Desligado'; ativoLike=false;
  } else if(n){
    if(/\b(demit|deslig|inativo|rescis|baixado|cancel)\b/.test(n) || n==='d' || n==='inativo'){
      codigo='desligado'; label=sitRaw||'Desligado'; ativoLike=false;
    } else if(/\b(ativo|normal|trabalhando|efetiv)\b/.test(n) || n==='a' || n==='ativo'){
      codigo='ativo'; label=sitRaw||'Ativo'; ativoLike=true;
    } else if(/\bferias\b/.test(n)){ codigo='ferias'; label=sitRaw||'Férias'; ativoLike=true; }
    else if(/\bafast/.test(n)){ codigo='afastado'; label=sitRaw||'Afastado'; ativoLike=true; }
    else { codigo='outro'; label=sitRaw; ativoLike=null; }
  } else {
    // Planilha de "ativos": sem coluna situação → assume ativo
    codigo='ativo'; label='Ativo (assumido — planilha de ativos)'; ativoLike=true;
  }
  return {codigo:codigo, label:label, ativoLike:ativoLike, raw:sitRaw, desligamento:desl||null};
}

/** CPF(s) do colaborador CENA. Campo `bro` é misto (BRO/CPF) — indexa cpf e bro se parecerem CPF. */
function rhSynCenaCpfs(c){
  var out=[], seen={};
  [c.cpf, c.bro].forEach(function(v){
    var n=rhSynNormCpf(v);
    if(n && !seen[n]){ seen[n]=true; out.push(n); }
  });
  return out;
}
function rhSynCenaCpf(c){
  // Prefere coluna cpf; senão bro (legado BRO/CPF no mesmo campo)
  return rhSynNormCpf(c.cpf) || rhSynNormCpf(c.bro) || '';
}
function rhSynCenaTemCpf(c, cpf){
  if(!cpf) return false;
  return rhSynCenaCpfs(c).indexOf(cpf)>=0;
}
function rhSynCenaLabelBase(c){
  if(c.base_nome) return c.base_nome;
  if(c.base) return c.base;
  if(c.filial_id && typeof filiais!=='undefined'){
    var f=(filiais||[]).find(function(x){ return String(x.id)===String(c.filial_id); });
    if(f) return f.nome||f.codigo||'';
  }
  return '';
}
function rhSynCenaLabelContrato(c){
  if(c.contrato_nome) return c.contrato_nome;
  var ct=(contratos||[]).find(function(x){ return String(x.id)===String(c.contrato_id); });
  return ct?(ct.codigo||ct.nome||''):'';
}

async function rhSynCarregarColabs(force){
  if(_rhSyn.colabsLoaded && !force && _rhSyn.colabs && _rhSyn.colabs.length) return _rhSyn.colabs;
  // Cascata: muitos ambientes usam bro (não cpf). Evitar select com cpf/cnpj no 1º attempt → menos HTTP 400.
  var selects=[
    'id,nome,re,bro,ativo,dispensado,data_dispensa,motivo_dispensa,cargo,contrato_id,filial_id,equipe_id,vinculo,eh_pj,synergy_matricula,admissao,situacao_vinculo,vinculo_ref,fonte_dp,synergy_synced_at',
    'id,nome,re,bro,ativo,dispensado,data_dispensa,motivo_dispensa,cargo,contrato_id,filial_id,equipe_id,vinculo,eh_pj,synergy_matricula,admissao,situacao_vinculo,fonte_dp,synergy_synced_at',
    'id,nome,re,bro,ativo,dispensado,data_dispensa,motivo_dispensa,cargo,contrato_id,filial_id,equipe_id,vinculo,eh_pj,synergy_matricula,admissao,situacao_vinculo,vinculo_ref',
    'id,nome,re,bro,cpf,ativo,dispensado,data_dispensa,motivo_dispensa,cargo,contrato_id,filial_id,equipe_id,vinculo,eh_pj,cnpj,razao_social,synergy_matricula,admissao,situacao_vinculo,vinculo_ref,fonte_dp,synergy_synced_at',
    'id,nome,re,bro,ativo,dispensado,data_dispensa,motivo_dispensa,cargo,contrato_id,filial_id,vinculo,eh_pj,synergy_matricula,admissao,situacao_vinculo',
    'id,nome,re,bro,ativo,dispensado,data_dispensa,motivo_dispensa,cargo,contrato_id,filial_id,synergy_matricula,admissao,situacao_vinculo',
    'id,nome,re,bro,ativo,dispensado,data_dispensa,motivo_dispensa,cargo,contrato_id,filial_id,admissao',
    'id,nome,re,bro,ativo,dispensado,data_dispensa,motivo_dispensa,cargo,contrato_id,filial_id',
    'id,nome,re,bro,ativo,dispensado,cargo,contrato_id,filial_id'
  ];
  if(_rhSyn.colabsSelect){
    selects=[_rhSyn.colabsSelect].concat(selects.filter(function(s){ return s!==_rhSyn.colabsSelect; }));
  }
  function merge(rows){
    var map={}, out=[];
    (rows||[]).forEach(function(c){
      if(!c||c.id==null) return;
      var id=String(c.id);
      if(!map[id]){ map[id]=true; out.push(c); }
    });
    return out;
  }
  if(typeof DEMO!=='undefined' && DEMO){
    _rhSyn.colabs=merge(colaboradores||[]);
    _rhSyn.colabsLoaded=true;
    return _rhSyn.colabs;
  }
  async function fetchSet(select){
    var a=await sbFetch('colaboradores',{select:select, filters:['ativo=eq.true'], order:'nome', limit:8000}).catch(function(){return null;});
    if(a===null) throw new Error('select_fail');
    var d=await sbFetch('colaboradores',{select:select, filters:['dispensado=eq.true'], order:'nome', limit:8000}).catch(function(){return [];});
    var i=await sbFetch('colaboradores',{select:select, filters:['ativo=eq.false','dispensado=eq.false'], order:'nome', limit:3000}).catch(function(){return [];});
    return merge([].concat(a||[], d||[], i||[]));
  }
  _rhSyn.colabs=null;
  for(var si=0;si<selects.length;si++){
    try{
      _rhSyn.colabs=await fetchSet(selects[si]);
      _rhSyn.colabsSelect=selects[si];
      break;
    }catch(_e){ /* tenta próximo select */ }
  }
  if(!_rhSyn.colabs) _rhSyn.colabs=merge(colaboradores||[]);
  // Enriquecer memória local sem gravar
  var byId={};
  (_rhSyn.colabs||[]).forEach(function(c){ byId[String(c.id)]=c; });
  (colaboradores||[]).forEach(function(c){
    if(!byId[String(c.id)]){ _rhSyn.colabs.push(c); byId[String(c.id)]=c; }
  });
  _rhSyn.colabsLoaded=true;
  return _rhSyn.colabs;
}

function rhSynIndexColabs(list){
  var byCpf={}, byMat={}, byRe={}, byNome={};
  function add(map, key, c){
    if(!key) return;
    if(!map[key]) map[key]=[];
    if(!map[key].some(function(x){ return String(x.id)===String(c.id); })) map[key].push(c);
  }
  (list||[]).forEach(function(c){
    rhSynCenaCpfs(c).forEach(function(cp){ add(byCpf, cp, c); });
    var matRaw=rhSynNormMat(c.synergy_matricula);
    add(byMat, matRaw, c);
    add(byMat, rhSynMatDigits(c.synergy_matricula), c);
    add(byRe, rhSynNormRe(c.re), c);
    // Também indexa synergy_matricula como se fosse RE (legado)
    add(byRe, rhSynMatDigits(c.synergy_matricula), c);
    add(byNome, rhSynNormNome(c.nome), c);
  });
  return {byCpf:byCpf, byMat:byMat, byRe:byRe, byNome:byNome};
}

function rhSynColabAtivoLike(c){
  if(!c) return false;
  if(c.dispensado) return false;
  if(c.ativo===false) return false;
  return true;
}

/** Tipo/fonte do vínculo — reusa eh_pj + vinculo. NÃO cria coluna nova se não precisar. */
function rhSynFonteVinculo(c){
  if(!c) return {codigo:'desconhecido', label:'Desconhecido', administrado_synergy:false, beneficio_independente_synergy:true};
  if(typeof colabEhPj==='function' ? colabEhPj(c) : (c.eh_pj===true||c.eh_pj===1||c.eh_pj==='true')){
    return {codigo:'pj', label:'PJ', administrado_synergy:false, beneficio_independente_synergy:true};
  }
  var v=String(c.vinculo||c.tipo_vinculo||c.tipo_pessoa||'').toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  if(v==='pj'||v==='juridica'||v.indexOf('pessoa juridica')>=0){
    return {codigo:'pj', label:'PJ', administrado_synergy:false, beneficio_independente_synergy:true};
  }
  if(v==='terceiro'||v==='terceiros'||v==='externo'||v==='prestador'){
    return {codigo:'terceiro', label:'Terceiro', administrado_synergy:false, beneficio_independente_synergy:true};
  }
  if(v==='temporario'||v.indexOf('tempor')>=0){
    return {codigo:'temporario', label:'Temporário', administrado_synergy:false, beneficio_independente_synergy:true};
  }
  if(v==='outro'||v==='nao_synergy'||v==='fora_synergy'){
    return {codigo:'outro', label:'Outro (não Synergy)', administrado_synergy:false, beneficio_independente_synergy:true};
  }
  // Default operacional CENA: CLT / vínculo controlado pelo Synergy
  return {codigo:'clt_synergy', label:'CLT / Synergy', administrado_synergy:true, beneficio_independente_synergy:false};
}
function rhSynNovoVinculoRef(){
  try{
    if(typeof crypto!=='undefined' && crypto.randomUUID) return crypto.randomUUID();
  }catch(_e){}
  return 'vin-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10);
}
function rhSynAdmissaoFutura(adm){
  var d=rhSynParseData(adm);
  if(!d) return false;
  var hoje=(typeof dataHoje==='function'?dataHoje():new Date().toISOString().slice(0,10));
  return d>hoje;
}
function rhSynProgSitLabel(c){
  if(!c||!c.id) return '—';
  try{
    if(typeof _progStatus!=='undefined' && _progStatus[c.id]!=null) return String(_progStatus[c.id]);
  }catch(_e){}
  return '—';
}
function rhSynRevisaoAnteriorAusente(colabId){
  var id=String(colabId||'');
  if(!id) return null;
  var mem=(_rhSynDemoImp||[]).concat(_rhSyn.historico||[]);
  for(var i=0;i<mem.length;i++){
    var itens=mem[i]._itens||mem[i].itens||[];
    for(var j=0;j<(itens||[]).length;j++){
      var it=itens[j];
      if(String(it.colaborador_id||'')!==id) continue;
      var ac=String(it.acao_aplicada||'');
      var pay=it.payload_aplicacao||{};
      var acoes=pay.acoes||[];
      if(ac==='manter_ativo' || (Array.isArray(acoes)&&acoes.indexOf('manter_ativo_ausente')>=0)){
        return {revisado_em:it.revisado_em||it.aplicado_em, revisado_por:it.revisado_por||it.aplicado_por, justificativa:it.justificativa||''};
      }
    }
  }
  return (_rhSyn._revisoesAusente||{})[id]||null;
}


/** Entre vários hits CENA (ex.: RE 331 ativo + inativo), escolhe o melhor. */
function rhSynPreferirEntreHits(hits, lineVals){
  if(!hits || hits.length<=1) return hits||[];
  var cpf=lineVals&&lineVals.cpf, nome=lineVals&&lineVals.nome;
  var scored=hits.map(function(c){
    var score=0;
    if(cpf && rhSynCenaTemCpf(c, cpf)) score+=100;
    if(nome && rhSynNomesCompativeis(nome, c.nome)) score+=50;
    if(rhSynColabAtivoLike(c)) score+=20;
    else if(c.ativo===false && !c.dispensado) score+=5;
    return {c:c, score:score};
  });
  scored.sort(function(a,b){ return b.score-a.score; });
  if(scored[0].score > scored[1].score) return [scored[0].c];
  // Empate: se só um está ativo, fica com o ativo
  var ativos=scored.filter(function(x){ return rhSynColabAtivoLike(x.c); });
  if(ativos.length===1) return [ativos[0].c];
  return hits;
}

function rhSynNomesCompativeis(a, b){
  var na=rhSynNormNome(a), nb=rhSynNormNome(b);
  if(!na||!nb) return false;
  if(na===nb) return true;
  var ta=na.split(' ').filter(Boolean), tb=nb.split(' ').filter(Boolean);
  if(ta.length>=2 && tb.length>=2 && ta[0]===tb[0] && ta[ta.length-1]===tb[tb.length-1]) return true;
  return false;
}

function rhSynMatchColab(lineVals, idx){
  var hits=[], method='', ambigua=false, rejeitados=[];
  var cpf=lineVals.cpf, mat=lineVals.matricula, re=lineVals.re, nome=lineVals.nome;

  function rejeitar(cands, methodTried, motivoFn){
    (cands||[]).forEach(function(c){
      rejeitados.push({
        id:c.id, nome:c.nome, re:c.re, method:methodTried,
        motivo:motivoFn?motivoFn(c):('Candidato rejeitado via '+methodTried)
      });
    });
  }
  function filtrarCpfOk(cands, methodTried){
    if(!cpf) return cands||[];
    var ok=[], bad=[];
    (cands||[]).forEach(function(c){
      var cps=rhSynCenaCpfs(c);
      if(!cps.length) ok.push(c);
      else if(cps.indexOf(cpf)>=0) ok.push(c);
      else bad.push(c);
    });
    if(bad.length){
      rejeitar(bad, methodTried, function(c){
        return 'CPF Synergy '+cpf+' ≠ CENA '+(rhSynCenaCpfs(c).join('/')||'—')+' ('+(c.nome||'')+'). Match por '+methodTried+' descartado.';
      });
    }
    return ok;
  }
  function filtrarNomeSeTemCpfSyn(cands, methodTried){
    // Com CPF no Synergy sem hit por CPF: exige nome compatível,
    // EXCETO se o candidato CENA tiver o mesmo CPF
    if(!cpf || !nome) return cands||[];
    var ok=[], bad=[];
    (cands||[]).forEach(function(c){
      if(rhSynCenaTemCpf(c, cpf)){ ok.push(c); return; }
      if(rhSynNomesCompativeis(nome, c.nome)) ok.push(c);
      else bad.push(c);
    });
    if(bad.length){
      rejeitar(bad, methodTried, function(c){
        return 'Match por '+methodTried+' rejeitado: Synergy "'+nome+'" ≠ CENA "'+(c.nome||'')+'" (havia CPF Synergy sem correspondência por CPF).';
      });
    }
    return ok;
  }
  function filtrarNomeUnicoEntre(cands, methodTried){
    if(!nome) return [];
    var named=(cands||[]).filter(function(c){ return rhSynNomesCompativeis(nome, c.nome); });
    if(named.length===1) return named;
    if(named.length>1){
      rejeitar(named, methodTried, function(c){
        return 'Vários com RE/chave "'+re+'" e nome parecido — ambíguo ('+(c.nome||'')+').';
      });
    }
    return [];
  }

  // 1) CPF — único vínculo automático confiável quando existe
  if(cpf && idx.byCpf[cpf]){
    hits=idx.byCpf[cpf].slice();
    method='cpf';
  }

  // 2) Matrícula Synergy → coluna synergy_matricula
  if(!hits.length && mat && idx.byMat[mat]){
    var mHits=filtrarCpfOk(idx.byMat[mat].slice(), 'synergy_matricula');
    mHits=filtrarNomeSeTemCpfSyn(mHits, 'synergy_matricula');
    if(mHits.length){ hits=mHits; method='synergy_matricula'; }
  }

  // 2b) Matrícula Synergy → colaboradores.re (padrão real do CENA: RE = matrícula/chapa)
  if(!hits.length && mat){
    var matDig=rhSynMatDigits(mat);
    if(matDig && idx.byRe[matDig]){
      var mrHits=filtrarCpfOk(idx.byRe[matDig].slice(), 'matricula_re');
      // Matrícula com ≥4 dígitos é chave forte: 1 candidato sem conflito de CPF = vínculo
      // (evita “novo” quando o nome no CENA difere levemente). Com vários candidatos, exige nome.
      if(matDig.length >= 4 && mrHits.length === 1){
        /* ok */
      } else if(cpf && nome){
        mrHits=filtrarNomeSeTemCpfSyn(mrHits, 'matricula_re');
      } else if(nome && mrHits.length > 1){
        mrHits=mrHits.filter(function(c){ return rhSynNomesCompativeis(nome, c.nome); });
      }
      if(mrHits.length){ hits=mrHits; method='matricula_re'; }
    }
  }

  // 3) RE Synergy → colaboradores.re (protegido contra RE curta e conflito)
  // Caso real: várias pessoas com RE "33" (Marcia × Vanessa) — desambigua por CPF ou nome
  if(!hits.length && re && idx.byRe[re]){
    var reLen=String(re).length;
    var poolRe=idx.byRe[re].slice();
    if(reLen < 3 && !cpf && !nome){
      rejeitar(poolRe, 're', function(c){
        return 'RE "'+re+'" muito curta para vínculo automático sem CPF/nome ('+(c.nome||'')+').';
      });
    } else {
      var rHits=filtrarCpfOk(poolRe, 're');
      // Se o filtro de CPF zerou (ex.: bro com valor que não é o CPF), tenta nome único na mesma RE
      if(!rHits.length && (cpf || nome)){
        rHits=filtrarNomeUnicoEntre(poolRe, 're_nome');
      } else if(cpf){
        rHits=filtrarNomeSeTemCpfSyn(rHits, 're');
        if(!rHits.length) rHits=filtrarNomeUnicoEntre(poolRe, 're_nome');
      } else if(nome){
        var comNome=rHits.filter(function(c){ return rhSynNomesCompativeis(nome, c.nome); });
        if(comNome.length) rHits=comNome;
        else if(reLen < 4){
          rejeitar(rHits, 're', function(c){
            return 'RE "'+re+'" sem CPF e sem nome compatível — não vincula a '+(c.nome||'')+'.';
          });
          rHits=[];
        }
      } else if(reLen < 4){
        rejeitar(rHits, 're', function(c){
          return 'RE curta sem CPF/nome — match com '+(c.nome||'')+' descartado.';
        });
        rHits=[];
      }
      if(rHits.length){ hits=rHits; method='re'; }
    }
  }

  var sugestoes=[];
  if(!hits.length && nome && idx.byNome[nome]){
    sugestoes=idx.byNome[nome].slice();
    // Nome exatamente igual e único: vincula (mesmo com CPF divergente — a flag CPF DIVERGENTE aparece na análise)
    if(sugestoes.length===1){
      var onlyN=sugestoes[0];
      var cpsN=rhSynCenaCpfs(onlyN);
      var cpfOkN=!cpf || !cpsN.length || cpsN.indexOf(cpf)>=0;
      var reOkN=re && rhSynNormRe(onlyN.re)===String(re);
      if(cpfOkN || reOkN){
        hits=[onlyN];
        method=cpfOkN?'nome_unico':'nome_re';
        sugestoes=[];
      }
    }
  }
  // Se ainda sem hit: nome compatível único em TODO o cadastro (primeiro+último)
  if(!hits.length && nome){
    var allNome=[];
    Object.keys(idx.byNome||{}).forEach(function(k){
      (idx.byNome[k]||[]).forEach(function(c){
        if(rhSynNomesCompativeis(nome, c.nome) && !allNome.some(function(x){return String(x.id)===String(c.id);})) allNome.push(c);
      });
    });
    if(allNome.length===1){
      var only=allNome[0];
      var cps2=rhSynCenaCpfs(only);
      var cpfOk2=!cpf || !cps2.length || cps2.indexOf(cpf)>=0;
      var reOk2=re && rhSynNormRe(only.re)===String(re);
      if(cpfOk2 || reOk2){
        hits=[only];
        method=reOk2&&!cpfOk2?'nome_re':'nome_compativel';
        sugestoes=[];
      }
    } else if(allNome.length>1 && !sugestoes.length){
      sugestoes=allNome;
    }
  }
  if(hits.length>1){
    var preferidos=rhSynPreferirEntreHits(hits, {cpf:cpf, nome:nome});
    if(preferidos.length===1){
      // Guarda os demais como candidatos (duplicata CENA: ativo+inativo etc.)
      var escolhido=preferidos[0];
      var outros=hits.filter(function(c){ return String(c.id)!==String(escolhido.id); });
      if(outros.length){
        rejeitar(outros, method||'preferencia', function(c){
          return 'Cadastro duplicado no CENA (RE '+(c.re||'—')+'): preferido '+(escolhido.nome||'')+
            (rhSynColabAtivoLike(escolhido)?' (ativo)':'')+' em vez de '+(c.nome||'')+
            (rhSynColabAtivoLike(c)?'':' (inativo/dispensado)')+'.';
        });
      }
      hits=[escolhido];
      ambigua=false;
    } else {
      ambigua=true;
    }
  }
  return {hits:hits, method:method, ambigua:ambigua, sugestoes:sugestoes, rejeitados:rejeitados, candidatos:ambigua?hits.slice():[]};
}

function rhSynAddFlag(flags, codigo, label, motivo, severidade){
  flags.push({codigo:codigo, label:label, motivo:motivo||'', severidade:severidade||'alerta'});
}

function rhSynCompararLinha(row, match, fileDup){
  var flags=[];
  var synSit=rhSynInterpretSituacaoSyn(row);
  var cpf=rhSynNormCpf(rhSynCell(row,'cpf'));
  var mat=rhSynNormMat(rhSynCell(row,'matricula'));
  var re=rhSynNormRe(rhSynCell(row,'re'));
  var nome=String(rhSynCell(row,'nome')||'').trim();
  var adm=rhSynParseData(rhSynCell(row,'admissao'));
  var cargo=String(rhSynCell(row,'cargo')||rhSynCell(row,'funcao')||'').trim();

  if(fileDup.cpf && cpf) rhSynAddFlag(flags,'DUPLICIDADE','DUPLICIDADE','CPF '+cpf+' aparece mais de uma vez no arquivo Synergy.');
  if(fileDup.mat && mat) rhSynAddFlag(flags,'DUPLICIDADE','DUPLICIDADE','Matrícula '+mat+' aparece mais de uma vez no arquivo Synergy.');
  if(fileDup.re && re) rhSynAddFlag(flags,'DUPLICIDADE','DUPLICIDADE','RE '+re+' aparece mais de uma vez no arquivo Synergy.');

  if(!cpf && !mat && !re){
    rhSynAddFlag(flags,'SEM IDENTIFICAÇÃO','SEM IDENTIFICAÇÃO','Linha sem CPF, matrícula Synergy nem RE — não é possível vincular automaticamente.');
  }

  var colab=null, cenaSit=null, method=match.method||'';
  var candidatosCena=(match.candidatos&&match.candidatos.length)?match.candidatos.slice()
    :((match.hits&&match.hits.length>1)?match.hits.slice():[]);

  if(match.ambigua){
    rhSynAddFlag(flags,'DUPLICIDADE','DUPLICIDADE',
      'Há mais de um cadastro CENA para esta chave ('+method+' / RE '+(re||'—')+'). Não marque como novo — escolha qual vincular ou inative o duplicado.');
    rhSynAddFlag(flags,'CADASTRO AMBÍGUO NO CENA','CADASTRO AMBÍGUO NO CENA',
      (match.hits||[]).map(function(c){
        return (c.nome||'?')+' RE '+(c.re||'—')+(rhSynColabAtivoLike(c)?' ativo':' inativo');
      }).join(' | '));
    candidatosCena=(match.hits||[]).slice();
  } else if(match.hits && match.hits.length===1){
    colab=match.hits[0];
    // Rede de segurança: só descarta se for pessoa claramente errada (CPF e nome conflitam)
    if(colab && method!=='cpf' && cpf){
      var cpfHit=rhSynCenaCpf(colab);
      var nomeOk=!nome || rhSynNomesCompativeis(nome, colab.nome);
      if(cpfHit && cpfHit!==cpf && !nomeOk){
        rhSynAddFlag(flags,'MATCH INVÁLIDO','MATCH INVÁLIDO',
          'Vínculo por '+method+' com '+(colab.nome||'')+' descartado: CPF e nome incompatíveis.');
        colab=null; method='';
      }
      // CPF diverge mas nome (ou método nome_*) bate → mantém vínculo; flag CPF DIVERGENTE abaixo
    }
    if(colab && match.rejeitados && match.rejeitados.length){
      var dupCena=match.rejeitados.some(function(z){ return (z.motivo||'').indexOf('Cadastro duplicado no CENA')>=0; });
      if(dupCena){
        rhSynAddFlag(flags,'DUPLICIDADE CENA','DUPLICIDADE CENA',
          'Existe outro cadastro CENA com a mesma RE/chave (ex.: inativo). Preferido o ativo/compatível: '+(colab.nome||'')+'.');
      }
    }
  } else if(match.sugestoes && match.sugestoes.length){
    rhSynAddFlag(flags,'SEM IDENTIFICAÇÃO','SEM IDENTIFICAÇÃO',
      'Nome igual a '+(match.sugestoes.length===1?match.sugestoes[0].nome:match.sugestoes.length+' cadastros')+
      ', mas sem CPF/matrícula/RE confiável para vínculo automático.');
    candidatosCena=match.sugestoes.slice();
  }

  if((!colab) && match.rejeitados && match.rejeitados.length){
    var top=match.rejeitados[0];
    rhSynAddFlag(flags,'MATCH REJEITADO','MATCH REJEITADO',
      top.motivo||('Candidato '+(top.nome||'')+' rejeitado para evitar vínculo errado.'));
  }

  if(!colab){
    var ambiguoCena=flags.some(function(f){ return f.codigo==='CADASTRO AMBÍGUO NO CENA'; });
    if(ambiguoCena){
      // NÃO é "novo" — já existe no CENA (possivelmente duplicado/inativo)
    } else if(!(flags.some(function(f){ return f.codigo==='SEM IDENTIFICAÇÃO'; }))){
      rhSynAddFlag(flags,'NOVO NO SYNERGY','NOVO NO SYNERGY','Colaborador presente no Synergy e não identificado no cadastro CENA.');
      rhSynAddFlag(flags,'NÃO ENCONTRADO NO CENA','NÃO ENCONTRADO NO CENA','Nenhum vínculo automático confiável por CPF (prioritário), matrícula Synergy ou RE.');
    }
  } else {
    cenaSit=(typeof rhResolverSituacaoColaborador==='function')
      ? rhResolverSituacaoColaborador(colab, null, {statusRows:[]})
      : null;
    var cenaCpf=rhSynCenaCpf(colab);
    var cenaMat=rhSynNormMat(colab.synergy_matricula);
    var cenaRe=rhSynNormRe(colab.re);
    var cenaNome=rhSynNormNome(colab.nome);
    var cenaAdm=rhSynParseData(colab.admissao);
    var cenaCargo=String(colab.cargo||'').trim();

    if(cpf && cenaCpf && cpf!==cenaCpf){
      rhSynAddFlag(flags,'CPF DIVERGENTE','CPF DIVERGENTE','Synergy CPF '+cpf+' × CENA CPF '+cenaCpf+'.');
    }
    if(mat && cenaMat && mat!==cenaMat){
      rhSynAddFlag(flags,'MATRÍCULA DIVERGENTE','MATRÍCULA DIVERGENTE','Synergy matrícula '+mat+' × CENA synergy_matricula '+cenaMat+'.');
    }
    if(mat && !cenaMat && method!=='synergy_matricula'){
      // informativo: CENA ainda sem matrícula — não é divergência forte
    }
    if(nome && cenaNome && rhSynNormNome(nome)!==cenaNome){
      rhSynAddFlag(flags,'NOME DIVERGENTE','NOME DIVERGENTE','Synergy "'+nome+'" × CENA "'+(colab.nome||'')+'".');
    }
    if(adm && cenaAdm && adm!==cenaAdm){
      rhSynAddFlag(flags,'ADMISSAO DIVERGENTE','ADMISSAO DIVERGENTE','Synergy admissão '+rhSynFmtData(adm)+' × CENA '+rhSynFmtData(cenaAdm)+'.');
    }
    if(cargo && cenaCargo && rhSynNormNome(cargo)!==rhSynNormNome(cenaCargo)){
      rhSynAddFlag(flags,'CARGO DIVERGENTE','CARGO DIVERGENTE','Synergy cargo/função "'+cargo+'" × CENA "'+cenaCargo+'".');
    }

    var cenaCod=cenaSit?cenaSit.situacao_codigo:'';
    var cenaAtivoLike=cenaCod && cenaCod!=='desligado' && cenaCod!=='inativo';
    var cenaDesligado=cenaCod==='desligado';

    var fonteVin=rhSynFonteVinculo(colab);
    if(synSit.ativoLike===false && cenaAtivoLike){
      if(!fonteVin.administrado_synergy){
        rhSynAddFlag(flags,'NÃO APLICÁVEL À CONCILIAÇÃO SYNERGY','NÃO APLICÁVEL À CONCILIAÇÃO SYNERGY',
          'Vínculo '+fonteVin.label+' — Synergy não é fonte oficial. Sem sugestão de desligamento.', 'info');
      } else {
        rhSynAddFlag(flags,'DESLIGADO NO SYNERGY / ATIVO NO CENA','DESLIGADO NO SYNERGY / ATIVO NO CENA',
          'Synergy informa desligamento'+(synSit.desligamento?' em '+rhSynFmtData(synSit.desligamento):'')+
          '. No CENA o colaborador permanece '+(cenaSit?cenaSit.situacao:'ativo')+
          (colab.dispensado?'':' e não possui dispensa formal')+'.', 'critica');
      }
    }
    if(synSit.ativoLike===true && cenaDesligado){
      rhSynAddFlag(flags,'ATIVO NO SYNERGY / DESLIGADO NO CENA','ATIVO NO SYNERGY / DESLIGADO NO CENA',
        'Synergy indica ativo. No CENA a situação é Desligado'+(colab.data_dispensa?' em '+rhSynFmtData(colab.data_dispensa):'')+
        '. Possível recontratação — sem reativação automática.', 'alta');
      rhSynAddFlag(flags,'POSSÍVEL RECONTRATAÇÃO','POSSÍVEL RECONTRATAÇÃO',
        'Revisar e, se confirmado, usar INICIAR RECONTRATAÇÃO (gera novo vinculo_ref).', 'alta');
    }
  }

  var statusPrincipal='OK';
  var priority=['DUPLICIDADE','CADASTRO AMBÍGUO NO CENA','DUPLICIDADE CENA','SEM IDENTIFICAÇÃO',
    'REVISAR — ATIVO NO CENA E AUSENTE NO SYNERGY','DESLIGADO NO SYNERGY / ATIVO NO CENA',
    'ATIVO NO SYNERGY / DESLIGADO NO CENA','POSSÍVEL RECONTRATAÇÃO',
    'CPF DIVERGENTE','MATRÍCULA DIVERGENTE','NOME DIVERGENTE','ADMISSAO DIVERGENTE','CARGO DIVERGENTE',
    'NOVO NO SYNERGY','NÃO ENCONTRADO NO CENA','NÃO APLICÁVEL À CONCILIAÇÃO SYNERGY','DIVERGÊNCIA'];
  if(flags.length){
    statusPrincipal='DIVERGÊNCIA';
    for(var pi=0;pi<priority.length;pi++){
      var hit=flags.find(function(f){ return f.label===priority[pi] || f.codigo===priority[pi]; });
      if(hit){ statusPrincipal=hit.label; break; }
    }
  }

  var fonteOut=colab?rhSynFonteVinculo(colab):null;
  return {
    linha:row.__linha,
    tipo_resultado:'synergy_linha',
    cpf:cpf, matricula:mat, re:re, nome:nome,
    cargo_syn:cargo, admissao_syn:adm,
    syn_situacao:synSit,
    colab:colab,
    match_method:method,
    sugestoes:match.sugestoes||[],
    candidatos_cena:candidatosCena||[],
    cena_sit:cenaSit,
    flags:flags,
    status:statusPrincipal,
    is_div:flags.length>0,
    motivo:flags.map(function(f){ return f.motivo; }).filter(Boolean).join(' | '),
    contrato_cena:colab?rhSynCenaLabelContrato(colab):'',
    base_cena:colab?rhSynCenaLabelBase(colab):'',
    cargo_cena:colab?(colab.cargo||''):'',
    nome_cena:colab?(colab.nome||''):'',
    id_cena:colab?colab.id:null,
    fonte_vinculo:fonteOut,
    beneficio_status_futuro:null
  };
}

function rhSynExecutarConciliacao(){
  var idx=rhSynIndexColabs(_rhSyn.colabs||[]);
  var cpfCount={}, matCount={}, reCount={};
  _rhSyn.dataRows.forEach(function(row){
    var cpf=rhSynNormCpf(rhSynCell(row,'cpf'));
    var mat=rhSynNormMat(rhSynCell(row,'matricula'));
    var re=rhSynNormRe(rhSynCell(row,'re'));
    if(cpf) cpfCount[cpf]=(cpfCount[cpf]||0)+1;
    if(mat) matCount[mat]=(matCount[mat]||0)+1;
    if(re) reCount[re]=(reCount[re]||0)+1;
  });
  var results=_rhSyn.dataRows.map(function(row){
    var cpf=rhSynNormCpf(rhSynCell(row,'cpf'));
    var mat=rhSynNormMat(rhSynCell(row,'matricula'));
    var re=rhSynNormRe(rhSynCell(row,'re'));
    var nome=rhSynNormNome(rhSynCell(row,'nome'));
    var match=rhSynMatchColab({cpf:cpf,matricula:mat,re:re,nome:nome}, idx);
    var fileDup={cpf:(cpf&&cpfCount[cpf]>1), mat:(mat&&matCount[mat]>1), re:(re&&reCount[re]>1)};
    return rhSynCompararLinha(row, match, fileDup);
  });

  // Duplicidade: várias linhas Synergy → mesmo colaborador CENA
  var byCena={};
  results.forEach(function(r,i){
    if(!r.id_cena) return;
    var k=String(r.id_cena);
    if(!byCena[k]) byCena[k]=[];
    byCena[k].push(i);
  });
  Object.keys(byCena).forEach(function(k){
    if(byCena[k].length<2) return;
    byCena[k].forEach(function(i){
      rhSynAddFlag(results[i].flags,'DUPLICIDADE','DUPLICIDADE',
        'Mais de uma linha Synergy aponta para o mesmo colaborador CENA ('+(results[i].nome_cena||k)+').');
      results[i].is_div=true;
      if(results[i].status==='OK') results[i].status='DUPLICIDADE';
      results[i].motivo=results[i].flags.map(function(f){return f.motivo;}).filter(Boolean).join(' | ');
    });
  });

  // Etapa 3: ativos CENA (vínculo Synergy) ausentes da lista importada
  var ausentes=rhSynDetectarAusentes(results, _rhSyn.colabs||[]);
  results=results.concat(ausentes);

  _rhSyn.results=results;
  _rhSyn.summary=rhSynResumo(results);
  return results;
}

/** Reverse pass: CENA ativo + vínculo Synergy + não encontrado na planilha. */
function rhSynDetectarAusentes(results, colabs){
  var matchedIds={}, keysCpf={}, keysMat={}, keysRe={};
  (results||[]).forEach(function(r){
    if(r.id_cena) matchedIds[String(r.id_cena)]=true;
    if(r.cpf) keysCpf[r.cpf]=true;
    if(r.matricula){
      keysMat[rhSynNormMat(r.matricula)]=true;
      keysMat[rhSynMatDigits(r.matricula)]=true;
    }
    if(r.re) keysRe[rhSynNormRe(r.re)]=true;
  });
  // Chaves brutas do arquivo (mesmo se match falhou — CPF na lista = não ausente)
  (_rhSyn.dataRows||[]).forEach(function(row){
    var cpf=rhSynNormCpf(rhSynCell(row,'cpf'));
    var mat=rhSynNormMat(rhSynCell(row,'matricula'));
    var re=rhSynNormRe(rhSynCell(row,'re'));
    if(cpf) keysCpf[cpf]=true;
    if(mat){ keysMat[mat]=true; keysMat[rhSynMatDigits(mat)]=true; }
    if(re) keysRe[re]=true;
  });

  var out=[], linhaBase=900000;
  (colabs||[]).forEach(function(c, ix){
    if(!rhSynColabAtivoLike(c)) return;
    var fonte=rhSynFonteVinculo(c);
    if(!fonte.administrado_synergy) return; // PJ/terceiro/etc. fora da fila crítica
    if(matchedIds[String(c.id)]) return;
    var cpf=rhSynCenaCpf(c);
    if(cpf && keysCpf[cpf]) return; // presente por CPF (mesmo se nome divergir)
    var mat=rhSynNormMat(c.synergy_matricula);
    if(mat && (keysMat[mat] || keysMat[rhSynMatDigits(mat)])) return;
    var re=rhSynNormRe(c.re);
    if(re && keysRe[re]) return;

    var cenaSit=(typeof rhResolverSituacaoColaborador==='function')
      ? rhResolverSituacaoColaborador(c, null, {statusRows:[]}) : null;
    var flags=[];
    var revAnt=rhSynRevisaoAnteriorAusente(c.id);
    var motivo='Este colaborador está ativo no ERP CENA, porém não foi encontrado na lista oficial de funcionários ativos importada do Synergy.';
    if(revAnt){
      motivo+=' Já houve revisão anterior ('+(revAnt.revisado_por||'?')+
        (revAnt.revisado_em?' em '+new Date(revAnt.revisado_em).toLocaleString('pt-BR'):'')+
        '): manter ativo'+(revAnt.justificativa?' — '+revAnt.justificativa:'')+'.';
    }
    rhSynAddFlag(flags,'REVISAR — ATIVO NO CENA E AUSENTE NO SYNERGY','REVISAR — ATIVO NO CENA E AUSENTE NO SYNERGY', motivo, 'critica');
    out.push({
      linha:linhaBase+ix,
      tipo_resultado:'ausente_synergy',
      cpf:cpf||'', matricula:mat||'', re:re||'', nome:c.nome||'',
      cargo_syn:'', admissao_syn:rhSynParseData(c.admissao)||'',
      syn_situacao:{codigo:'ausente', label:'Ausente da lista de ativos', ativoLike:null, desligamento:''},
      colab:c, match_method:'', sugestoes:[], candidatos_cena:[],
      cena_sit:cenaSit, flags:flags,
      status:'REVISAR — ATIVO NO CENA E AUSENTE NO SYNERGY',
      is_div:true, critico:true,
      motivo:motivo,
      contrato_cena:rhSynCenaLabelContrato(c),
      base_cena:rhSynCenaLabelBase(c),
      cargo_cena:c.cargo||'',
      nome_cena:c.nome||'',
      id_cena:c.id,
      fonte_vinculo:fonte,
      beneficio_status_futuro:'VINCULO_NAO_CONFIRMADO',
      revisao_anterior:revAnt,
      equipe_cena:(function(){
        try{
          var eq=((typeof equipes_disp!=='undefined'&&equipes_disp)||equipes||[]).find(function(x){return String(x.id)===String(c.equipe_id);});
          return eq?(eq.codigo||eq.nome||''): (c.equipe_id||'');
        }catch(_e){ return c.equipe_id||''; }
      })(),
      prog_sit:rhSynProgSitLabel(c)
    });
  });
  return out;
}

function rhSynResumo(results){
  var s={
    total:0, identificados:0, ok:0, divergencias:0, novos:0,
    poss_deslig:0, poss_reativ:0, duplicidades:0, sem_id:0,
    ausentes_synergy:0, ativos_cena_synergy:0, encontrados_synergy:0,
    nao_aplicavel:0
  };
  var foundIds={};
  results.forEach(function(r){
    if(r.tipo_resultado==='ausente_synergy'){
      s.ausentes_synergy++;
      s.divergencias++;
      return;
    }
    s.total++;
    if(r.id_cena){ s.identificados++; foundIds[String(r.id_cena)]=true; }
    if(!r.is_div) s.ok++; else s.divergencias++;
    var labels={};
    (r.flags||[]).forEach(function(f){ labels[f.label]=true; });
    if(labels['NOVO NO SYNERGY']) s.novos++;
    if(labels['DESLIGADO NO SYNERGY / ATIVO NO CENA']) s.poss_deslig++;
    if(labels['ATIVO NO SYNERGY / DESLIGADO NO CENA']||labels['POSSÍVEL RECONTRATAÇÃO']) s.poss_reativ++;
    if(labels['DUPLICIDADE']) s.duplicidades++;
    if(labels['SEM IDENTIFICAÇÃO']) s.sem_id++;
    if(labels['NÃO APLICÁVEL À CONCILIAÇÃO SYNERGY']) s.nao_aplicavel++;
  });
  (_rhSyn.colabs||[]).forEach(function(c){
    if(!rhSynColabAtivoLike(c)) return;
    var f=rhSynFonteVinculo(c);
    if(!f.administrado_synergy) return;
    s.ativos_cena_synergy++;
    if(foundIds[String(c.id)]) s.encontrados_synergy++;
  });
  // encontrados = ativos Synergy-managed que bateram na planilha
  s.encontrados_synergy=Math.max(0, (s.ativos_cena_synergy||0)-(s.ausentes_synergy||0));
  return s;
}

function rhSynResultadosFiltrados(){
  var f=_rhSyn.filters||{};
  var q=String(f.q||'').trim().toLowerCase();
  var qDigits=q.replace(/\D/g,'');
  return (_rhSyn.results||[]).filter(function(r){
    if(f.soDiv && !r.is_div) return false;
    if(f.status){
      var st=String(f.status);
      if(st==='OK' && r.is_div) return false;
      if(st==='DIVERGÊNCIA' && !r.is_div) return false;
      if(st!=='OK' && st!=='DIVERGÊNCIA'){
        var has=r.flags.some(function(x){ return x.label===st || x.codigo===st; }) || r.status===st;
        if(!has) return false;
      }
    }
    if(f.contrato && String(r.contrato_cena||'')!==String(f.contrato)) return false;
    if(f.base && String(r.base_cena||'')!==String(f.base)) return false;
    if(f.cargo){
      var cg=String(f.cargo).toLowerCase();
      if(String(r.cargo_syn||'').toLowerCase().indexOf(cg)<0 && String(r.cargo_cena||'').toLowerCase().indexOf(cg)<0) return false;
    }
    if(q){
      var blob=[r.nome,r.nome_cena,r.re,r.matricula,r.cpf,r.status,r.motivo].join(' ').toLowerCase();
      if(blob.indexOf(q)<0 && !(qDigits && String(r.cpf||'').indexOf(qDigits)>=0)) return false;
    }
    return true;
  });
}

// ── UI ──────────────────────────────────────────────────────────────────────
function rhSynRender(){
  rhSynExtInitState();
  var wrap=document.getElementById('rh-syn-wrap'); if(!wrap) return;
  var meta=_rhSyn.fileMeta;
  var stImp=(_rhSyn.importacao&&_rhSyn.importacao.status)||'';
  var badge=stImp
    ? '<span style="font-size:11px;background:#E6F1FB;color:#185FA5;border:1px solid #185FA533;padding:3px 8px;border-radius:999px">Importação: '+rhEsc(stImp)+'</span>'
    : '<span style="font-size:11px;color:#854F0B;background:#FEF3E2;border:1px solid #E8B931;padding:3px 8px;border-radius:999px">Análise + aplicação seletiva (sem sync em massa)</span>';
  var html='<div class="card" style="margin-bottom:12px">'
    +'<div class="ch" style="flex-wrap:wrap;gap:8px;align-items:center">'
    +'<span class="ct">🔄 Conciliação Synergy × CENA</span>'+badge
    +'</div>'
    +'<div style="font-size:12px;color:#666;margin-top:4px">Compara Synergy × CENA. Alterações só com confirmação e apenas em campos Synergy-mestre (matrícula, admissão, desligamento). Contrato/base/equipe/Prog/VT-VR bloqueados.</div>'
    +'</div>';
  html+=rhSynHtmlHistorico();
  if(_rhSyn.dupCandidate) html+=rhSynHtmlDupModal();
  if(_rhSyn.step==='upload' || (!_rhSyn.fileMeta && !_rhSyn.dupCandidate)){
    html+=rhSynHtmlUpload();
  } else if(_rhSyn.step==='map'){
    html+=rhSynHtmlMeta(meta)+rhSynHtmlMap();
  } else if(_rhSyn.step==='results'){
    html+=rhSynHtmlMeta(meta)+rhSynHtmlResumo()+rhSynHtmlFiltros()+rhSynHtmlTabela()+rhSynHtmlDetalhe();
  } else {
    html+=rhSynHtmlUpload();
  }
  wrap.innerHTML=html;
  rhSynBindDropzone();
  if(_rhSyn.step==='map'){
    RH_SYN_FIELDS.forEach(function(f){
      var el=document.getElementById('rh-syn-map-'+f.key);
      if(el && _rhSyn.mapping[f.key]) el.value=_rhSyn.mapping[f.key];
    });
  }
  if(!_rhSyn.historico || !_rhSyn.historico.length){
    rhSynCarregarHistorico().then(function(h){ if(h&&h.length) rhSynRender(); });
  }
}

function rhSynHtmlMeta(meta){
  if(!meta) return '';
  var st=(_rhSyn.importacao&&_rhSyn.importacao.status)||'—';
  return '<div class="card" style="margin-bottom:12px;padding:12px 14px">'
    +'<div style="display:flex;flex-wrap:wrap;gap:16px;align-items:center;justify-content:space-between">'
    +'<div style="font-size:12px;line-height:1.6">'
    +'<div><b>Arquivo:</b> '+rhEsc(meta.nome)+'</div>'
    +'<div><b>Tamanho:</b> '+rhEsc(meta.tamanhoLabel)+' · <b>Linhas:</b> '+(meta.linhas||0)
    +' · <b>Fonte:</b> '+rhEsc(meta.sourceType||'')+'</div>'
    +'<div><b>Importação:</b> '+rhEsc(meta.quando)+' · <b>Usuário:</b> '+rhEsc(meta.usuario)
    +(_rhSyn.fileHash?' · <b>Hash:</b> <code style="font-size:10px">'+rhEsc(String(_rhSyn.fileHash).slice(0,12))+'…</code>':'')
    +'</div>'
    +'<div><b>Status importação:</b> '+rhEsc(st)
    +(_rhSyn.importacaoId?' · id '+rhEsc(String(_rhSyn.importacaoId).slice(0,8))+'…':'')+'</div>'
    +'</div>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap">'
    +(_rhSyn.step==='results'?'<button class="btn btn-sm" onclick="rhSynAplicarMassaBaixoRisco()">⚡ Massa baixo risco</button>':'')
    +'<button class="btn btn-sm" onclick="rhSynLimpar()">Limpar análise</button>'
    +'</div></div></div>';
}

function rhSynHtmlUpload(){
  return '<div class="card" style="margin-bottom:12px">'
    +'<div id="rh-syn-drop" style="border:2px dashed #185FA5;border-radius:14px;padding:2.2rem 1.2rem;text-align:center;background:linear-gradient(180deg,#F3F8FD,#fff);cursor:pointer">'
    +'<div style="font-size:40px;margin-bottom:8px">📂</div>'
    +'<div style="font-size:16px;font-weight:700;color:#185FA5;margin-bottom:6px">Arraste aqui a planilha de FUNCIONÁRIOS ATIVOS DO SYNERGY</div>'
    +'<div style="font-size:12px;color:#666;max-width:520px;margin:0 auto 10px">Aceita XLSX, XLS ou CSV. O arquivo será analisado e o histórico persistido. Alterações no cadastro só ocorrem com <b>Revisar</b> + confirmação.</div>'
    +'<button type="button" class="btn btn-pri" onclick="event.stopPropagation();document.getElementById(\'rh-syn-file\').click()">Selecionar arquivo</button>'
    +'<input type="file" id="rh-syn-file" accept=".xlsx,.xls,.csv,text/csv,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" style="display:none"/>'
    +'</div>'
    +'<div style="font-size:11px;color:#888;margin-top:10px">Motor preparado para fontes futuras: <code>xlsx</code> · <code>csv</code> · <code>synergy_api</code>. Histórico em <code>rh_synergy_importacoes</code> (SQL Etapa 2). Sem binário da planilha.</div>'
    +'</div>';
}

function rhSynBindDropzone(){
  var drop=document.getElementById('rh-syn-drop');
  var inp=document.getElementById('rh-syn-file');
  if(!inp) return;
  inp.onchange=function(){ if(inp.files&&inp.files[0]) rhSynOnFile(inp.files[0]); };
  if(!drop) return;
  drop.onclick=function(e){ if(e.target&&e.target.tagName==='BUTTON') return; inp.click(); };
  drop.ondragover=function(e){ e.preventDefault(); drop.style.borderColor='#0C447C'; drop.style.background='#EAF3DE'; };
  drop.ondragleave=function(){ drop.style.borderColor='#185FA5'; drop.style.background='linear-gradient(180deg,#F3F8FD,#fff)'; };
  drop.ondrop=function(e){
    e.preventDefault();
    drop.style.borderColor='#185FA5'; drop.style.background='linear-gradient(180deg,#F3F8FD,#fff)';
    var f=e.dataTransfer&&e.dataTransfer.files&&e.dataTransfer.files[0];
    if(f) rhSynOnFile(f);
  };
}

function rhSynOnFile(file){
  var nome=(file.name||'').toLowerCase();
  var sourceType='';
  if(/\.csv$/i.test(nome)) sourceType='csv';
  else if(/\.xlsx$/i.test(nome)) sourceType='xlsx';
  else if(/\.xls$/i.test(nome)) sourceType='xls';
  else { progShowToast('Formato não suportado. Use XLSX, XLS ou CSV.','erro'); return; }
  var reader=new FileReader();
  reader.onload=function(ev){
    try{
      var payload=ev.target.result;
      rhSynProcessarArquivo(file, payload, sourceType, false);
    }catch(err){
      console.error(err);
      progShowToast('Falha ao ler arquivo: '+(err&&err.message||err),'erro');
    }
  };
  if(sourceType==='csv') reader.readAsText(file,'UTF-8');
  else reader.readAsArrayBuffer(file);
}

function rhSynHtmlMap(){
  var rows=RH_SYN_FIELDS.map(function(f){
    var conf=_rhSyn.mapConfidence[f.key]||0;
    var confLabel=conf>=0.72?'alta':(conf>=0.45?'média':'baixa');
    var cor=conf>=0.72?'#3B6D11':(conf>=0.45?'#854F0B':'#A32D2D');
    var sel=_rhSyn.mapping[f.key]||'';
    var opts='<option value="">— não mapear —</option>'+_rhSyn.headers.map(function(h){
      return '<option value="'+rhEsc(h)+'"'+(h===sel?' selected':'')+'>'+rhEsc(h)+'</option>';
    }).join('');
    return '<tr>'
      +'<td style="padding:8px;font-size:12px;font-weight:600">'+rhEsc(f.label)+'</td>'
      +'<td style="padding:8px"><select class="inp" style="width:100%;font-size:12px" id="rh-syn-map-'+f.key+'">'+opts+'</select></td>'
      +'<td style="padding:8px;font-size:11px;color:'+cor+'">confiança '+confLabel+(conf?(' ('+Math.round(conf*100)+'%)'):'')+'</td>'
      +'</tr>';
  }).join('');
  return '<div class="card" style="margin-bottom:12px">'
    +'<div class="ch"><span class="ct">Mapeamento de colunas</span></div>'
    +'<div style="font-size:12px;color:#666;margin-bottom:10px">O Synergy pode exportar nomes diferentes. Revise o de-para antes de analisar. Campos de identificação: CPF (prioridade), matrícula Synergy, RE.</div>'
    +(_rhSyn.needsManualMap?'<div style="background:#FEF3E2;border:1px solid #E8B931;border-radius:8px;padding:8px 10px;font-size:12px;color:#854F0B;margin-bottom:10px">⚠ Confiança baixa em um ou mais campos de identificação — confirme o mapeamento manualmente.</div>':'')
    +'<div style="overflow:auto"><table style="width:100%;border-collapse:collapse">'
    +'<thead><tr style="background:#f5f5f3"><th style="text-align:left;padding:8px;font-size:11px">Campo CENA</th><th style="text-align:left;padding:8px;font-size:11px">Coluna do arquivo</th><th style="text-align:left;padding:8px;font-size:11px">Detecção</th></tr></thead>'
    +'<tbody>'+rows+'</tbody></table></div>'
    +'<div style="display:flex;gap:8px;margin-top:14px;flex-wrap:wrap">'
    +'<button class="btn btn-pri" onclick="rhSynAnalisar()">🔎 Analisar arquivo</button>'
    +'<button class="btn" onclick="rhSynLimpar()">Limpar análise</button>'
    +'</div>'
    +'<div style="font-size:11px;color:#888;margin-top:8px">Não há aplicação em massa automática. Após analisar, use Revisar por linha (ou massa baixo risco).</div>'
    +'</div>';
}

function rhSynColetarMapping(){
  RH_SYN_FIELDS.forEach(function(f){
    var el=document.getElementById('rh-syn-map-'+f.key);
    _rhSyn.mapping[f.key]=el?el.value:'';
  });
}

async function rhSynAnalisar(){
  rhSynColetarMapping();
  if(!_rhSyn.mapping.cpf && !_rhSyn.mapping.matricula && !_rhSyn.mapping.re){
    progShowToast('Mapeie ao menos CPF, matrícula ou RE para analisar.','erro'); return;
  }
  progShowToast('Analisando e persistindo importação…');
  try{
    await rhSynCarregarColabs(true);
    rhSynExecutarConciliacao();
    // marcar critico nos results
    (_rhSyn.results||[]).forEach(function(r){
      r.critico=!!(r.flags||[]).some(function(f){
        return f.label==='DESLIGADO NO SYNERGY / ATIVO NO CENA'
          || f.label==='ATIVO NO SYNERGY / DESLIGADO NO CENA'
          || f.label==='REVISAR — ATIVO NO CENA E AUSENTE NO SYNERGY'
          || f.label==='DUPLICIDADE'
          || f.severidade==='critica';
      });
    });
    await rhSynPersistirAnalise();
    _rhSyn.step='results';
    _rhSyn.detalheIdx=null;
    rhSynRender();
    var s=_rhSyn.summary||{};
    progShowToast('Análise salva: '+(s.total||0)+' linhas · '+(s.divergencias||0)+' divergências');
  }catch(e){
    console.error(e);
    progShowToast('Falha na análise: '+(e&&e.message||e),'erro');
  }
}

function rhSynVoltarMap(){ _rhSyn.step='map'; _rhSyn.detalheIdx=null; rhSynRender(); }
function rhSynLimpar(){ rhSynReset(); rhSynRender(); progShowToast('Análise limpa (memória).'); }

function rhSynFiltrarStatus(st){
  _rhSyn.filters=_rhSyn.filters||{};
  _rhSyn.filters.status=st||'';
  _rhSyn.filters.soDiv=!!st && st!=='OK';
  rhSynRender();
}
