function rhCentralHtmlCards(s){
  s=s||{};
  function card(key, label, val, cor){
    var ativo=(_rhCentral.filtros&&_rhCentral.filtros.card===key);
    return '<button type="button" onclick="rhCentralFiltrarCard(\''+key+'\')" '
      +'style="text-align:left;cursor:pointer;border:1px solid '+(ativo?cor:'#e5e5e5')+';'
      +'background:'+(ativo?cor+'14':'#fff')+';border-radius:12px;padding:10px 12px;min-width:120px">'
      +'<div style="font-size:11px;color:#666">'+rhCentralEsc(label)+'</div>'
      +'<div style="font-size:22px;font-weight:800;color:'+cor+'">'+(val==null?0:val)+'</div>'
      +'</button>';
  }
  return '<div style="display:flex;flex-wrap:wrap;gap:8px;margin:10px 0">'
    +card('total','Total colaboradores', s.total_colabs,'#185FA5')
    +card('confirmados','Confirmados Synergy/CENA', s.confirmados,'#3B6D11')
    +card('pj','PJ / não Synergy', s.pj_nao_syn,'#5B5B5B')
    +card('criticos','Críticos', s.criticos,'#A32D2D')
    +card('revisar','Em revisão', s.revisar,'#854F0B')
    +card('ausentes','Ausentes no Synergy', s.ausentes,'#A32D2D')
    +card('recontratacoes','Possíveis recontratações', s.recontratacoes,'#533AB7')
    +card('pre_admissao','Pré-admissões pendentes', s.pre_admissao,'#185FA5')
    +card('cpf_dup','CPF duplicado', s.cpf_dup,'#A32D2D')
    +card('re_dup','RE duplicado', s.re_dup,'#854F0B')
    +card('mat_dup','Matrícula duplicada', s.mat_dup,'#A32D2D')
    +'</div>';
}

