// Fim RH-0B Etapa 4 — Central de Divergências RH/DP


// ══════════════════════════════════════════════════════════════
// RH C1 — Benefícios VT/VR (camada acima da Gestão de Ponto)
// Lê ponto_registros. Não altera batida, falta, férias nem escala.
// Permanência: relTmaPontoEntradaSaida + relTmaResolverIntervaloPonto (sem mudar).
// Ajuste só muda VT/VR no dia da apuração. Fechamento = C2.
// ══════════════════════════════════════════════════════════════
var RH_BEN_MIN_MINUTOS=120;
var RH_BEN_VT_POR_DIA=2;
var RH_BEN_VR_POR_DIA=1;
var RH_BEN_VR_VALOR_PADRAO=31.80;
/** VT unitário padrão PLPT Teresina (ticket), regra pat_valor_dia */
var RH_BEN_VT_VALOR_PLPT=7.50;
var _rhBen={
  pagAno:0, pagMes:0, contratoId:'', busca:'',
  periodoModo:'mes_anterior', diaCorte:16, apurIni:'', apurFim:'',
  dataCarga:'', movimentos:[], movOk:true,
  ocultarZeradosNegativos:false, view:'lista', operadoras:[], lotes:[], selecao:{}, filtro2c:{},
  sortCol:'nome', sortDir:'asc',
  competencia:null, lista:[],
  carregando:false, salvando:false, sujo:false, erro:'',
  pontoOk:true
};

function rhBeneficioUsuario(){
  return (usuarioLogado && (usuarioLogado.nome||usuarioLogado.email)) || 'RH';
}
function rhBeneficioPad2(n){ return (n<10?'0':'')+n; }
function rhBeneficioCompetenciaPadrao(){
  var h=typeof rhHoje==='function'?rhHoje():new Date().toISOString().slice(0,10);
  return {pagAno:parseInt(h.slice(0,4),10), pagMes:parseInt(h.slice(5,7),10)};
}
function rhBeneficioUltimoDiaMes(ano, mes){
  return new Date(Number(ano), Number(mes), 0).getDate();
}
function rhBeneficioPeriodoMesAnterior(pagAno, pagMes){
  pagAno=Number(pagAno); pagMes=Number(pagMes);
  var am=pagMes-1, ay=pagAno;
  if(am<1){ am=12; ay--; }
  var last=rhBeneficioUltimoDiaMes(ay, am);
  return {
    ini:ay+'-'+rhBeneficioPad2(am)+'-01',
    fim:ay+'-'+rhBeneficioPad2(am)+'-'+rhBeneficioPad2(last),
    apurAno:ay, apurMes:am, modo:'mes_anterior'
  };
}
function rhBeneficioPeriodoApuracao(pagAno, pagMes){
  pagAno=Number(pagAno); pagMes=Number(pagMes);
  var modo=_rhBen.periodoModo||'mes_anterior';
  if(modo==='personalizado'){
    var ini=String(_rhBen.apurIni||'').slice(0,10);
    var fim=String(_rhBen.apurFim||'').slice(0,10);
    if(ini && fim && ini<=fim) return {ini:ini, fim:fim, apurAno:null, apurMes:null, modo:modo};
  }
  if(modo==='dia_corte'){
    var dia=Math.min(31, Math.max(1, Number(_rhBen.diaCorte)||16));
    var fimAno=pagAno, fimMes=pagMes, fimDia=dia-1;
    if(fimDia<1) return rhBeneficioPeriodoMesAnterior(pagAno, pagMes);
    var iniMes=pagMes-1, iniAno=pagAno;
    if(iniMes<1){ iniMes=12; iniAno--; }
    var iniDia=Math.min(dia, rhBeneficioUltimoDiaMes(iniAno, iniMes));
    fimDia=Math.min(fimDia, rhBeneficioUltimoDiaMes(fimAno, fimMes));
    return {
      ini:iniAno+'-'+rhBeneficioPad2(iniMes)+'-'+rhBeneficioPad2(iniDia),
      fim:fimAno+'-'+rhBeneficioPad2(fimMes)+'-'+rhBeneficioPad2(fimDia),
      apurAno:iniAno, apurMes:iniMes, modo:modo, diaCorte:dia
    };
  }
  return rhBeneficioPeriodoMesAnterior(pagAno, pagMes);
}
function rhBeneficioMesValor(){
  return _rhBen.pagAno+'-'+rhBeneficioPad2(_rhBen.pagMes);
}
function rhBeneficioBaseNome(c){
  if(!c) return '';
  if(c.base_nome) return c.base_nome;
  var bid=c.filial_id||c.base_id||'';
  var f=(filiais||[]).find(function(x){ return String(x.id)===String(bid); });
  return f?(f.nome||f.codigo||''):'';
}
function rhBeneficioRoster(){
  var cid=_rhBen.contratoId;
  return (colaboradores||[]).filter(function(c){
    if(!c || !String(c.re||'').trim()) return false;
    // PJ entra na lista com direito zero (política empresarial) — não ocultar
    if(cid && String(c.contrato_id||'')!==String(cid)) return false;
    return true;
  });
}
function rhBeneficioMapAjustes(lista){
  var map={};
  (lista||[]).forEach(function(a){
    (a.dias||[]).forEach(function(d){
      if(!d || !d.ajuste_em) return;
      map[pontoReNorm(a.re)+'|'+String(d.data||'').slice(0,10)]=d;
    });
  });
  return map;
}
function rhBeneficioAplicarAjuste(dia, prev){
  if(!prev || !prev.ajuste_em) return dia;
  dia.vt_anterior=prev.vt_anterior!=null?prev.vt_anterior:prev.vt_final;
  dia.vr_anterior=prev.vr_anterior!=null?prev.vr_anterior:prev.vr_final;
  dia.vt_final=prev.vt_final;
  dia.vr_final=prev.vr_final;
  dia.ajuste_justificativa=prev.ajuste_justificativa;
  dia.ajuste_por=prev.ajuste_por;
  dia.ajuste_em=prev.ajuste_em;
  dia.divergencia=false;
  return dia;
}
function rhBeneficioSomarApuracao(a){
  var d=a.dias||[];
  a.dias_elegiveis=0; a.dias_sem_direito=0; a.faltas=0; a.ferias=0;
  a.afastamentos=0; a.abono_curso=0; a.menos_2h=0; a.sem_marcacao=0; a.batida_incompleta=0;
  a.qtd_vt=0; a.qtd_vr=0;
  var temAj=false, temDiv=false;
  if(!d.length){
    a.status='divergencia';
    a.obs_periodo='Sem registros no período';
    return rhBeneficioEstimarValores(a);
  }
  d.forEach(function(x){
    a.qtd_vt+=(Number(x.vt_final)||0);
    a.qtd_vr+=(Number(x.vr_final)||0);
    if(x.status_beneficio==='Elegível') a.dias_elegiveis++;
    else a.dias_sem_direito++;
    if(x.status_beneficio==='Falta') a.faltas++;
    if(x.status_beneficio==='Férias') a.ferias++;
    if(x.status_beneficio==='Afastado') a.afastamentos++;
    if(x.status_beneficio==='Abono Curso') a.abono_curso++;
    if(x.status_beneficio==='Menos de 2 horas') a.menos_2h++;
    if(x.status_beneficio==='Sem marcação') a.sem_marcacao++;
    if(x.status_beneficio==='Batida incompleta') a.batida_incompleta++;
    if(x.ajuste_em) temAj=true;
    if(x.divergencia && !x.ajuste_em) temDiv=true;
  });
  a.obs_periodo='';
  a.status=temDiv?'divergencia':(temAj?'ajustado':'ok');
  return rhBeneficioEstimarValores(a);
}

function rhBeneficioColabDaApuracao(a){
  if(!a) return null;
  if(a.colaborador_id){
    var byId=(colaboradores||[]).find(function(c){ return String(c.id)===String(a.colaborador_id); });
    if(byId) return byId;
  }
  return (colaboradores||[]).find(function(c){ return pontoReNorm(c.re)===pontoReNorm(a.re); })||null;
}
function rhBeneficioUnitarioDoBenef(b){
  if(!b || b.ativo===false) return null;
  var val=typeof rhRemNum==='function'?rhRemNum(b.valor,0):Number(b.valor||0);
  if(!val) return null;
  var regra=String(b.regra||'');
  var dias=typeof rhRemNum==='function'?rhRemNum(b.dias_mes,0):Number(b.dias_mes||0);
  var round=typeof rhRemRound==='function'?rhRemRound:function(n){ return Math.round((Number(n)||0)*100)/100; };
  if(regra==='percentual_piso') return null;
  if(regra==='pat_valor_dia') return {unitario:round(val), modo:'quantidade'};
  if(dias>0) return {unitario:round(val/dias), modo:'dia'};
  return {unitario:round(val), modo:'quantidade'};
}
function rhBeneficioEstimarValores(a){
  if(!a) return a;
  a.valor_vt_est=null; a.valor_vr_est=null; a.valor_total_est=null;
  a.vt_unitario=null; a.vr_unitario=null; a.piso_label=''; a.vr_padrao=false;
  var round=typeof rhRemRound==='function'?rhRemRound:function(n){ return Math.round((Number(n)||0)*100)/100; };
  var c=rhBeneficioColabDaApuracao(a);
  var piso=(c && typeof rhRemMatchPiso==='function')?rhRemMatchPiso(c.cargo, c.funcao||'', c.contrato_id):null;
  var vtU=null, vrU=null;
  if(piso){
    a.piso_label=(piso.cargo||'')+(piso.funcao?' · '+piso.funcao:'');
    var bens=typeof rhRemBenefsDoPiso==='function'?rhRemBenefsDoPiso(piso.id):[];
    vtU=rhBeneficioUnitarioDoBenef(bens.filter(function(b){ return b.tipo==='vale_transporte'; })[0]);
    vrU=rhBeneficioUnitarioDoBenef(bens.filter(function(b){ return b.tipo==='vale_refeicao'; })[0]);
  }
  if(!vrU && RH_BEN_VR_VALOR_PADRAO){
    vrU={unitario:round(RH_BEN_VR_VALOR_PADRAO), modo:'quantidade'};
    a.vr_padrao=true;
    if(!a.piso_label) a.piso_label='VR padrão (sem piso cadastrado)';
  }
  var qVt=Number(a.direito_final_vt!=null?a.direito_final_vt:a.qtd_vt)||0;
  var qVr=Number(a.direito_final_vr!=null?a.direito_final_vr:a.qtd_vr)||0;
  var dEleg=Number(a.dias_elegiveis)||0;
  if(vtU){
    a.vt_unitario=vtU.unitario;
    a.valor_vt_est=round(vtU.modo==='dia'?vtU.unitario*dEleg:vtU.unitario*qVt);
  }
  if(vrU){
    a.vr_unitario=vrU.unitario;
    a.valor_vr_est=round(vrU.modo==='dia'?vrU.unitario*dEleg:vrU.unitario*qVr);
  }
  if(a.valor_vt_est!=null || a.valor_vr_est!=null)
    a.valor_total_est=round((a.valor_vt_est||0)+(a.valor_vr_est||0));
  return a;
}
function rhBeneficioAplicarEstimativas(lista){
  (lista||[]).forEach(function(a){ rhBeneficioEstimarValores(a); });
  return lista;
}
function rhBeneficioFmtR(v){
  if(v==null || v==='') return '—';
  return typeof fmtR==='function'?fmtR(v):('R$ '+Number(v).toFixed(2));
}

function rhBeneficioPermanenciaMin(p, pontoMap, reN){
  if(!p) return {ok:false, minutos:null, entrada:'', saida:'', motivo:'sem_registro'};
  var rec={
    entrada:p.entrada_ajustada||p.entrada||'',
    saida:p.saida_ajustada||p.saida||'',
    intervalo_saida:p.intervalo_saida,
    intervalo_retorno:p.intervalo_retorno,
    todas_marcacoes:p.todas_marcacoes,
    intervalo:p.intervalo
  };
  var es=(typeof relTmaPontoEntradaSaida==='function')
    ? relTmaPontoEntradaSaida(rec)
    : {entrada:rec.entrada, saida:rec.saida};
  var entrada=es.entrada||rec.entrada||'';
  var saida=es.saida||rec.saida||'';
  if(!entrada && !saida) return {ok:false, minutos:null, entrada:'', saida:'', motivo:'sem_marcacao'};
  if(!entrada || !saida) return {ok:false, minutos:null, entrada:entrada, saida:saida, motivo:'incompleta'};
  var data=String(p.data||'').slice(0,10);
  if(typeof relTmaResolverIntervaloPonto==='function'){
    var res=relTmaResolverIntervaloPonto(reN, data, entrada, saida, pontoMap||{});
    if(res && res.ok) return {ok:true, minutos:res.minutos, entrada:entrada, saida:res.saida||saida, overnight:!!res.overnight};
    return {ok:false, minutos:null, entrada:entrada, saida:saida, motivo:'incompleta'};
  }
  var em=typeof pontoHhmmToMin==='function'?pontoHhmmToMin(entrada):null;
  var sm=typeof pontoHhmmToMin==='function'?pontoHhmmToMin(saida):null;
  if(em==null || sm==null) return {ok:false, minutos:null, entrada:entrada, saida:saida, motivo:'incompleta'};
  return {ok:true, minutos:sm>em?sm-em:(sm+1440)-em, entrada:entrada, saida:saida};
}

function rhBeneficioClassificarDia(p, prog, perm){
  var td=((p&&p.tipo_dia)||'').toLowerCase();
  var st=((p&&p.status)||'').toLowerCase();
  var progSt=((prog&&prog.status)||'').toLowerCase();
  var ausTipo=String((p&&p.ausencia_tipo)||'').toLowerCase();
  var treinamento=(progSt==='treinamento' || td==='treinamento');
  var folgaDia=(td==='folga' || progSt==='folga');
  if(!p){
    return {status:'Sem marcação', vt:0, vr:0, divergencia:true, motivo:'Ausência de batidas válidas'};
  }
  if(td==='ferias' || p.ferias || st==='ferias' || progSt==='ferias')
    return {status:'Férias', vt:0, vr:0, divergencia:false, motivo:'Colaborador em férias'};
  if(pontoEhAbonoCurso(p))
    return {status:'Abono Curso', vt:0, vr:0, divergencia:false, motivo:'Abono Curso no relógio — sem VT/VR automático'};
  if(td==='afastado' || st==='afastado' || progSt==='afastado')
    return {status:'Afastado', vt:0, vr:0, divergencia:false, motivo:'Colaborador afastado'};
  if(td==='suspensao' || p.suspensao)
    return {status:'Suspensão', vt:0, vr:0, divergencia:false, motivo:'Suspensão registrada'};
  if(p.ausencia_motivada || td==='ausencia' || ausTipo.indexOf('atestado')>=0)
    return {status:'Atestado / Ausência motivada', vt:0, vr:0, divergencia:false, motivo:'Ausência justificada sem presença física'};
  if(!perm || (!perm.entrada && !perm.saida && !perm.ok)){
    if(treinamento) return {status:'Treinamento', vt:0, vr:0, divergencia:true, motivo:'Treinamento sem batida válida'};
    if(folgaDia) return {status:'Folga', vt:0, vr:0, divergencia:false, motivo:'Dia de folga sem batida'};
    if(td==='falta' || st==='falta' || st==='faltou')
      return {status:'Falta', vt:0, vr:0, divergencia:false, motivo:'Falta registrada no ponto'};
    return {status:'Sem marcação', vt:0, vr:0, divergencia:true, motivo:'Ausência de batidas válidas'};
  }
  if(!perm.ok){
    if(treinamento) return {status:'Treinamento', vt:0, vr:0, divergencia:true, motivo:'Treinamento: não foi possível calcular permanência'};
    return {status:'Batida incompleta', vt:0, vr:0, divergencia:true, motivo:'Não foi possível calcular permanência'};
  }
  if((perm.minutos||0)<RH_BEN_MIN_MINUTOS){
    if(folgaDia) return {status:'Folga', vt:0, vr:0, divergencia:false, motivo:'Folga com permanência abaixo de 2 horas'};
    return {status:'Menos de 2 horas', vt:0, vr:0, divergencia:true, motivo:'Permanência inferior ao mínimo'};
  }
  var motivoElig='Dia trabalhado com permanência mínima';
  if(folgaDia) motivoElig='Trabalhou na folga com permanência mínima (≥2h)';
  else if(td==='falta' || st==='falta' || st==='faltou') motivoElig='Presença no ponto ≥2h (status falta no cadastro)';
  else if(treinamento) motivoElig='Treinamento com permanência mínima';
  return {status:'Elegível', vt:RH_BEN_VT_POR_DIA, vr:RH_BEN_VR_POR_DIA, divergencia:false, motivo:motivoElig};
}

// ── RH Benefícios VT/VR Fase 2A (direito bruto × vínculo na carga × cargo confiança) ──
// Injetado em index.html. Não cria segundo módulo.

function rhBeneficioDataCargaPadrao(pagAno, pagMes){
  pagAno=Number(pagAno)||0; pagMes=Number(pagMes)||0;
  if(!pagAno||!pagMes){
    var pad=rhBeneficioCompetenciaPadrao();
    pagAno=pad.pagAno; pagMes=pad.pagMes;
  }
  var last=rhBeneficioUltimoDiaMes(pagAno, pagMes);
  return pagAno+'-'+rhBeneficioPad2(pagMes)+'-'+rhBeneficioPad2(last);
}
function rhBeneficioGarantirDataCarga(){
  if(!_rhBen.dataCarga || !/^\d{4}-\d{2}-\d{2}$/.test(String(_rhBen.dataCarga))){
    _rhBen.dataCarga=rhBeneficioDataCargaPadrao(_rhBen.pagAno, _rhBen.pagMes);
  }
  return String(_rhBen.dataCarga).slice(0,10);
}
function rhBeneficioAddDiaIso(iso, n){
  var d=new Date(String(iso).slice(0,10)+'T12:00:00');
  if(isNaN(d.getTime())) return iso;
  d.setDate(d.getDate()+(n||0));
  return d.getFullYear()+'-'+rhBeneficioPad2(d.getMonth()+1)+'-'+rhBeneficioPad2(d.getDate());
}
function rhBeneficioCadaDia(ini, fim, fn){
  var cur=String(ini||'').slice(0,10), end=String(fim||'').slice(0,10);
  if(!cur||!end||cur>end) return;
  var guard=0;
  while(cur<=end && guard++<400){
    fn(cur);
    cur=rhBeneficioAddDiaIso(cur, 1);
  }
}
/** Dias úteis (seg–sex). Sem fonte de feriado confiável no CENA → não inventa feriado. */
function rhBeneficioDiasUteis(ini, fim, opts){
  opts=opts||{};
  var adm=String(opts.admissao||'').slice(0,10);
  var desl=String(opts.desligamento||'').slice(0,10);
  var feriados={};
  (opts.feriados||[]).forEach(function(f){ feriados[String(f).slice(0,10)]=1; });
  var excluir=opts.excluir||{};
  var dias=[], limitacao='';
  if(!(opts.feriados&&opts.feriados.length)) limitacao='sem_feriados_cadastrados';
  rhBeneficioCadaDia(ini, fim, function(data){
    var wd=new Date(data+'T12:00:00').getDay();
    if(wd===0||wd===6) return;
    if(feriados[data]) return;
    if(excluir[data]) return;
    if(adm && data<adm) return;
    if(desl && data>desl) return;
    dias.push(data);
  });
  return {dias:dias, total:dias.length, limitacao:limitacao};
}
function rhBeneficioAdmissaoColab(c){
  return String((c&&(c.admissao||c.data_admissao||c.data_admissao_cena))||'').slice(0,10);
}
function rhBeneficioDesligamentoColab(c){
  if(!c) return '';
  if(c.dispensado || c.data_dispensa) return String(c.data_dispensa||'').slice(0,10);
  return '';
}
/** Preferência: campos explícitos. Não hardcodar nome Supervisor no motor. */
function rhBeneficioEhRegimeDiasUteis(c){
  if(!c) return false;
  if(String(c.regime_beneficio||'')==='dias_uteis') return true;
  if(c.cargo_confianca===true || c.cargo_confianca===1 || c.cargo_confianca==='true') return true;
  return false;
}
/** PJ = eh_pj ou vínculo classificado como PJ no CENA. Sem consulta Synergy. */
function rhBeneficioEhPj(c){
  if(!c) return false;
  if(typeof colabEhPj==='function' && colabEhPj(c)) return true;
  if(c.eh_pj===true || c.eh_pj===1 || c.eh_pj==='true' || c.eh_pj==='t') return true;
  if(typeof rhSynFonteVinculo==='function'){
    try{
      var f=rhSynFonteVinculo(c);
      if(f && f.codigo==='pj') return true;
    }catch(_e){}
  }
  var v=String(c.vinculo||c.tipo_vinculo||c.tipo_pessoa||'').toLowerCase();
  try{ v=v.normalize('NFD').replace(/[\u0300-\u036f]/g,''); }catch(_e2){}
  return v==='pj' || v.indexOf('pessoa jurid')>=0 || v==='juridica';
}
function rhBeneficioTemMovimentoBeneficio(colaboradorId){
  if(!colaboradorId) return false;
  return rhBeneficioMovimentosAtivos(_rhBen.movimentos||[]).some(function(m){
    return String(m.colaborador_id||'')===String(colaboradorId);
  });
}
function rhBeneficioEhSemHistoricoAnterior(c, per){
  var adm=rhBeneficioAdmissaoColab(c);
  if(!adm) return false;
  if(!per||!per.ini) return false;
  return adm>=String(per.ini).slice(0,10);
}
function rhBeneficioDiaExcluidoConfianca(data, c, progBy, pontoMap){
  var prog=progBy?progBy[String(c.id)+'|'+data]:null;
  var progSt=String((prog&&prog.status)||'').toLowerCase();
  if(progSt==='ferias') return {status:'Férias', motivo:'Colaborador em férias'};
  if(progSt==='afastado') return {status:'Afastado', motivo:'Colaborador afastado'};
  if(progSt==='suspensao'||progSt==='licenca') return {status:'Suspensão', motivo:'Suspensão/licença'};
  var reN=pontoReNorm(c.re);
  var p=pontoMap?pontoMap[reN+'|'+data]:null;
  if(p){
    var td=String(p.tipo_dia||'').toLowerCase();
    var st=String(p.status||'').toLowerCase();
    if(td==='ferias'||p.ferias||st==='ferias') return {status:'Férias', motivo:'Férias no ponto'};
    if(pontoEhAbonoCurso(p)) return {status:'Abono Curso', motivo:'Abono Curso no relógio'};
    if(td==='afastado'||st==='afastado') return {status:'Afastado', motivo:'Afastamento no ponto'};
    if(td==='suspensao'||p.suspensao) return {status:'Suspensão', motivo:'Suspensão no ponto'};
  }
  return null;
}
function rhBeneficioMontarApuracaoConfianca(a, c, per, pontoMap, progBy, prevAj){
  a.regra_apuracao='dias_uteis_confianca';
  a.cargo_confianca_snapshot=true;
  a.regime_beneficio_snapshot=String(c.regime_beneficio||'dias_uteis');
  var excluir={};
  var feriasN=0, afN=0, abonoN=0;
  rhBeneficioCadaDia(per.ini, per.fim, function(data){
    var ex=rhBeneficioDiaExcluidoConfianca(data, c, progBy, pontoMap);
    if(ex){
      excluir[data]=1;
      var wd=new Date(data+'T12:00:00').getDay();
      if(wd!==0&&wd!==6){
        if(ex.status==='Férias') feriasN++;
        else if(ex.status==='Afastado') afN++;
        else if(ex.status==='Abono Curso') abonoN++;
      }
    }
  });
  var du=rhBeneficioDiasUteis(per.ini, per.fim, {
    admissao:rhBeneficioAdmissaoColab(c),
    desligamento:rhBeneficioDesligamentoColab(c),
    excluir:excluir
  });
  a.dias_uteis=du.total;
  a._limitacao_feriados=du.limitacao||'';
  a.dias=[];
  du.dias.forEach(function(data){
    var dia={
      data:data,
      tipo_dia_fonte:'dias_uteis',
      status_fonte:'cargo_confianca',
      entrada:'', saida:'', permanencia_min:null,
      status_beneficio:'Elegível',
      motivo:'Regime dias úteis / cargo de confiança (sem exigência de ponto)',
      divergencia:false,
      vt_calc:RH_BEN_VT_POR_DIA, vr_calc:RH_BEN_VR_POR_DIA,
      vt_final:RH_BEN_VT_POR_DIA, vr_final:RH_BEN_VR_POR_DIA
    };
    var reN=pontoReNorm(c.re);
    rhBeneficioAplicarAjuste(dia, prevAj[reN+'|'+data]);
    a.dias.push(dia);
  });
  // registrar exclusões úteis (férias/afast) como dias sem direito (opcional no detalhe)
  Object.keys(excluir).forEach(function(data){
    var wd=new Date(data+'T12:00:00').getDay();
    if(wd===0||wd===6) return;
    var adm=rhBeneficioAdmissaoColab(c), desl=rhBeneficioDesligamentoColab(c);
    if(adm && data<adm) return;
    if(desl && data>desl) return;
    var ex=rhBeneficioDiaExcluidoConfianca(data, c, progBy, pontoMap);
    if(!ex) return;
    a.dias.push({
      data:data, tipo_dia_fonte:'dias_uteis', status_fonte:ex.status,
      entrada:'', saida:'', permanencia_min:null,
      status_beneficio:ex.status, motivo:ex.motivo, divergencia:false,
      vt_calc:0, vr_calc:0, vt_final:0, vr_final:0
    });
  });
  a.dias.sort(function(x,y){ return String(x.data).localeCompare(String(y.data)); });
  rhBeneficioSomarApuracao(a);
  a.ferias=Math.max(a.ferias||0, feriasN);
  a.afastamentos=Math.max(a.afastamentos||0, afN);
  a.abono_curso=Math.max(a.abono_curso||0, abonoN);
  a.sem_marcacao=0;
  a.batida_incompleta=0;
  a.menos_2h=0;
  if(a.status==='divergencia' && a.obs_periodo && !(a.dias||[]).some(function(d){return d.status_beneficio==='Elegível';})){
    // sem dias úteis líquidos — ok sem inventar
    a.obs_periodo='Sem dias úteis líquidos no período (admissão/desligamento/férias/afastamento/abono curso)';
  } else if(a.status!=='ajustado'){
    a.status='cargo_confianca';
    a.obs_periodo='';
  }
  return a;
}
function rhBeneficioValidarVinculoCarga(c, dataCarga){
  var out={
    status_vinculo_carga:'ok',
    motivo_bloqueio:'',
    zerar:false,
    situacao_codigo:'',
    status_hint:''
  };
  if(!c){
    out.status_vinculo_carga='revisar_vinculo';
    out.motivo_bloqueio='Colaborador não encontrado no cadastro CENA.';
    out.status_hint='REVISAR VÍNCULO';
    return out;
  }
  var data=String(dataCarga||'').slice(0,10);
  var evidPre=c.situacao_vinculo==='pre_admissao' || c.situacao_vinculo==='pre-admissao';
  var sit=typeof rhResolverSituacaoColaborador==='function'
    ? rhResolverSituacaoColaborador(c, data, {evidencia_pre_admissao:evidPre||undefined})
    : null;
  var cod=sit?(sit.situacao_codigo||''):'';
  out.situacao_codigo=cod;

  // Pré-admissão (não confundir com desligamento)
  if(cod==='pre_admissao' || (c.ativo===false && evidPre) || (c.ativo===false && sit&&sit.detalhes&&sit.detalhes.evidencia_pre_admissao)){
    out.status_vinculo_carga='pre_admissao';
    out.motivo_bloqueio='Colaborador em pré-admissão — não liberar benefício.';
    out.zerar=true;
    out.status_hint='PRÉ-ADMISSÃO — NÃO LIBERAR BENEFÍCIO';
    return out;
  }

  var ativoCad=!(c.ativo===false||c.ativo===0||c.ativo==='false');
  var dispensadoInterp=sit?!!sit.dispensado:!!c.dispensado;
  // Se data_dispensa > data carga, resolver já interpreta como não desligado
  if(!ativoCad || dispensadoInterp || cod==='desligado' || cod==='inativo'){
    out.status_vinculo_carga='bloqueado_desligado';
    out.motivo_bloqueio='Colaborador inativo ou dispensado na data prevista da carga.';
    out.zerar=true;
    out.status_hint='BLOQUEADO — SEM VÍNCULO ATIVO NA DATA DA CARGA';
    return out;
  }

  // Confiabilidade (camada adicional) — PJ nao_aplicavel não bloqueia por Synergy
  if(typeof rhStatusConfiabilidadeVinculo==='function'){
    try{
      var conf=rhStatusConfiabilidadeVinculo(c, {ignoreAusente:true});
      if(conf && conf.status==='critico'){
        out.status_vinculo_carga='revisar_vinculo';
        out.motivo_bloqueio=(conf.motivo||'Divergência crítica de vínculo — revisar antes de liberar.');
        out.zerar=false; // não zerar silenciosamente
        out.status_hint='REVISAR VÍNCULO';
        return out;
      }
      if(conf && conf.status==='nao_aplicavel'){
        out.status_vinculo_carga='nao_aplicavel_synergy';
        out.motivo_bloqueio='';
        out.status_hint='';
        return out;
      }
    }catch(_e){}
  }
  return out;
}
function rhBeneficioFinalizarApuracao(a, c, per){
  if(!a) return a;
  var dataCarga=rhBeneficioGarantirDataCarga();
  a.data_carga_snapshot=dataCarga;
  a.cargo_confianca_snapshot=!!(c && (c.cargo_confianca===true||c.cargo_confianca===1||c.cargo_confianca==='true'));
  a.regime_beneficio_snapshot=c?String(c.regime_beneficio||(a.cargo_confianca_snapshot?'dias_uteis':'ponto')):'ponto';
  if(!a.regra_apuracao) a.regra_apuracao=rhBeneficioEhRegimeDiasUteis(c)?'dias_uteis_confianca':'ponto';

  if(a.dias_uteis==null){
    var du=rhBeneficioDiasUteis(per.ini, per.fim, {
      admissao:rhBeneficioAdmissaoColab(c),
      desligamento:rhBeneficioDesligamentoColab(c)
    });
    a.dias_uteis=du.total;
    a._limitacao_feriados=du.limitacao||'';
  }

  // Política empresarial: PJ não tem direito a VT/VR (sem consulta Synergy)
  if(rhBeneficioEhPj(c)){
    a._eh_pj=true;
    a.direito_bruto_vt=0;
    a.direito_bruto_vr=0;
    a.direito_final_vt=0;
    a.direito_final_vr=0;
    a.qtd_vt=0;
    a.qtd_vr=0;
    a.status='pj_sem_direito';
    a.regra_apuracao='pj_sem_direito';
    a.motivo_bloqueio='Política empresarial: colaboradores PJ não participam dos benefícios VT/VR.';
    a.status_vinculo_carga='pj_sem_direito';
    a.situacao_carga_snapshot='pj';
    a.snapshot_regra={
      data_carga:dataCarga,
      regra_apuracao:'pj_sem_direito',
      cargo_confianca:a.cargo_confianca_snapshot,
      regime_beneficio:a.regime_beneficio_snapshot,
      eh_pj:true,
      direito_bruto_vt:0, direito_bruto_vr:0,
      direito_final_vt:0, direito_final_vr:0,
      motivo:a.motivo_bloqueio
    };
    rhBeneficioEstimarValores(a);
    return rhBeneficioAplicarContaCorrenteLinha(a, c);
  }

  var brutoVt=Number(a.qtd_vt)||0;
  var brutoVr=Number(a.qtd_vr)||0;
  a.direito_bruto_vt=brutoVt;
  a.direito_bruto_vr=brutoVr;

  var semHist=rhBeneficioEhSemHistoricoAnterior(c, per);
  if(semHist){
    a._sem_historico=true;
    if(a.regra_apuracao==='ponto') a.regra_apuracao='sem_historico';
  }

  var vin=rhBeneficioValidarVinculoCarga(c, dataCarga);
  a.status_vinculo_carga=vin.status_vinculo_carga;
  a.motivo_bloqueio=vin.motivo_bloqueio||'';
  a.situacao_carga_snapshot=vin.situacao_codigo||'';

  if(vin.zerar){
    a.direito_final_vt=0;
    a.direito_final_vr=0;
    a.qtd_vt=0;
    a.qtd_vr=0;
    if(vin.status_vinculo_carga==='pre_admissao') a.status='pre_admissao';
    else a.status='bloqueado';
  } else {
    a.direito_final_vt=brutoVt;
    a.direito_final_vr=brutoVr;
    a.qtd_vt=brutoVt;
    a.qtd_vr=brutoVr;
    if(vin.status_vinculo_carga==='revisar_vinculo') a.status='revisar_vinculo';
    else if(a.regra_apuracao==='dias_uteis_confianca' && a.status!=='ajustado' && a.status!=='divergencia')
      a.status='cargo_confianca';
    else if(semHist && a.status!=='ajustado' && a.status!=='divergencia' && a.status!=='bloqueado')
      a.status='sem_historico';
  }

  a.snapshot_regra={
    data_carga:dataCarga,
    regra_apuracao:a.regra_apuracao,
    cargo_confianca:a.cargo_confianca_snapshot,
    regime_beneficio:a.regime_beneficio_snapshot,
    situacao_vinculo_carga:a.situacao_carga_snapshot,
    status_vinculo_carga:a.status_vinculo_carga,
    dias_uteis:a.dias_uteis,
    direito_bruto_vt:a.direito_bruto_vt,
    direito_bruto_vr:a.direito_bruto_vr,
    direito_final_vt:a.direito_final_vt,
    direito_final_vr:a.direito_final_vr,
    limitacao_feriados:a._limitacao_feriados||'sem_feriados_cadastrados',
    sem_historico_anterior:!!semHist
  };
  rhBeneficioEstimarValores(a);
  return rhBeneficioAplicarContaCorrenteLinha(a, c);
}
function rhBeneficioStatusVinculoLabel(a){
  var s=a&&a.status_vinculo_carga;
  if(s==='pj_sem_direito' || (a&&a._eh_pj)) return 'PJ — SEM DIREITO';
  if(s==='bloqueado_desligado') return 'BLOQUEADO — DESLIGADO';
  if(s==='pre_admissao') return 'PRÉ-ADMISSÃO';
  if(s==='revisar_vinculo') return 'REVISAR VÍNCULO';
  if(s==='nao_aplicavel_synergy') return 'OK (não Synergy)';
  if(s==='ok'||!s) return 'OK';
  return String(s);
}
function rhBeneficioRegimeLabel(a){
  var r=a&&(a.regime_beneficio_snapshot||a.regra_apuracao);
  if(r==='dias_uteis'||r==='dias_uteis_confianca'||a&&a.cargo_confianca_snapshot) return 'Dias úteis';
  if(r==='sem_historico') return 'Ponto (1ª comp.)';
  return 'Ponto';
}
