function rhBeneficioListarSupervisoresAuditoria(){
  return (colaboradores||[]).filter(function(c){
    if(!c) return false;
    var cargo=String(c.cargo||'')+' '+String(c.funcao||'');
    return /supervisor/i.test(cargo);
  }).map(function(c){
    return {
      id:c.id, re:c.re, nome:c.nome,
      cargo:c.cargo||'', funcao:c.funcao||'',
      cargo_confianca:!!c.cargo_confianca,
      regime_beneficio:c.regime_beneficio||'',
      precisa_ajuste:!c.cargo_confianca || String(c.regime_beneficio||'')!=='dias_uteis'
    };
  }).sort(function(a,b){ return String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR'); });
}
async function rhBeneficioCorrigirSupervisor(id){
  var c=(colaboradores||[]).find(function(x){ return String(x.id)===String(id); });
  if(!c){ if(typeof progShowToast==='function') progShowToast('Colaborador não encontrado.','erro'); return; }
  if(!DEMO){
    if(typeof rhEvtSyncCargoConfianca==='function'){
      try{ await rhEvtSyncCargoConfianca(c, true, 'Auditoria Supervisores VT/VR'); }catch(_e){}
    }
    if(typeof rhEvtSyncRegimeBeneficio==='function'){
      try{ await rhEvtSyncRegimeBeneficio(c, 'dias_uteis', 'Auditoria Supervisores VT/VR'); }catch(_e){}
    }
    var ok=await sbUpdate('colaboradores', {cargo_confianca:true, regime_beneficio:'dias_uteis'}, 'id=eq.'+c.id);
    if(!ok){ if(typeof progShowToast==='function') progShowToast('Falha ao atualizar.','erro'); return; }
  }
  c.cargo_confianca=true;
  c.regime_beneficio='dias_uteis';
  if(typeof progShowToast==='function') progShowToast('Supervisor marcado: cargo_confianca + dias_uteis.');
  rhBeneficioAbrirAuditoriaSupervisores();
}
async function rhBeneficioCorrigirSupervisoresPendentes(){
  var lista=rhBeneficioListarSupervisoresAuditoria().filter(function(x){ return x.precisa_ajuste; });
  if(!lista.length){ if(typeof progShowToast==='function') progShowToast('Nenhum Supervisor pendente.'); return; }
  if(!confirm('Marcar '+lista.length+' Supervisor(es) com cargo_confianca=true e regime_beneficio=dias_uteis?')) return;
  var i;
  for(i=0;i<lista.length;i++){
    await rhBeneficioCorrigirSupervisor(lista[i].id);
  }
}
function rhBeneficioAbrirAuditoriaSupervisores(){
  var lista=rhBeneficioListarSupervisoresAuditoria();
  var rows=lista.map(function(x){
    var ok=!x.precisa_ajuste;
    return '<tr>'
      +'<td>'+rhEsc(x.re||'')+'</td><td>'+rhEsc(x.nome||'')+'</td>'
      +'<td>'+rhEsc(x.cargo||'—')+'</td><td>'+rhEsc(x.funcao||'—')+'</td>'
      +'<td>'+(x.cargo_confianca?'Sim':'Não')+'</td>'
      +'<td>'+rhEsc(x.regime_beneficio||'—')+'</td>'
      +'<td style="color:'+(ok?'#3B6D11':'#854F0B')+'">'+(ok?'OK':'Pendente')+'</td>'
      +'<td>'+(ok?'':('<button class="btn btn-sm" onclick="rhBeneficioCorrigirSupervisor(\''+rhEsc(x.id)+'\')">Corrigir</button>'))+'</td>'
      +'</tr>';
  }).join('');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:920px;max-height:90vh;overflow:auto">'
    +'<h3>Auditoria Supervisores → cargo de confiança</h3>'
    +'<div style="font-size:12px;color:#666;margin-bottom:10px">Identifica cargo/função contendo "Supervisor". Não altera outros cargos. Preferência: cargo_confianca=true e regime_beneficio=dias_uteis. Se já houver cadastro explícito coerente, permanece OK.</div>'
    +'<div style="margin-bottom:10px"><button class="btn btn-pri btn-sm" onclick="rhBeneficioCorrigirSupervisoresPendentes()">Corrigir todos pendentes</button></div>'
    +'<div style="overflow-x:auto"><table class="tbl" style="font-size:12px"><thead><tr>'
    +'<th>RE</th><th>Nome</th><th>Cargo</th><th>Função</th><th>cargo_confianca</th><th>regime_beneficio</th><th>Status</th><th></th>'
    +'</tr></thead><tbody>'
    +(rows||'<tr><td colspan="8" style="padding:1rem;text-align:center;color:#aaa">Nenhum Supervisor encontrado</td></tr>')
    +'</tbody></table></div>'
    +'<div class="ma"><button class="btn" onclick="closeModal()">Fechar</button></div></div></div>');
}
function rhBeneficioTestarFase2A(){
  var results=[], ok=0, fail=0;
  function check(nome, cond, detalhe){
    results.push({teste:nome, ok:!!cond, detalhe:detalhe});
    if(cond) ok++; else fail++;
  }
  var per={ini:'2026-08-01', fim:'2026-08-31'};
  var du=rhBeneficioDiasUteis(per.ini, per.fim, {});
  check('J_dias_uteis_ago2026', du.total===21, du.total);
  check('J_limitacao_feriados', du.limitacao==='sem_feriados_cadastrados', du.limitacao);

  var cAtivo={id:'t1', ativo:true, dispensado:false, re:'100', nome:'Ativo', cargo_confianca:false, regime_beneficio:'ponto'};
  var a={qtd_vt:44, qtd_vr:22, dias:[], status:'ok'};
  _rhBen.dataCarga='2026-09-25';
  rhBeneficioFinalizarApuracao(a, cAtivo, per);
  check('A_ativo_direito_final', a.direito_final_vt===44 && a.direito_final_vr===22, a);

  var cDes={id:'t2', ativo:false, dispensado:true, data_dispensa:'2026-09-22', re:'101', nome:'Deslig'};
  var b={qtd_vt:44, qtd_vr:22, dias:[], status:'ok'};
  rhBeneficioFinalizarApuracao(b, cDes, per);
  check('D_desligado_antes_carga', b.direito_final_vt===0 && b.status==='bloqueado', b.status_vinculo_carga);

  var cDesDepois={id:'t3', ativo:true, dispensado:true, data_dispensa:'2026-09-28', re:'102', nome:'DesligDepois'};
  var e={qtd_vt:40, qtd_vr:20, dias:[], status:'ok'};
  rhBeneficioFinalizarApuracao(e, cDesDepois, per);
  check('E_desligado_depois_carga', e.direito_final_vt===40 && e.status!=='bloqueado', {st:e.status, sit:e.situacao_carga_snapshot});

  var cPre={id:'t4', ativo:false, situacao_vinculo:'pre_admissao', re:'103', nome:'Pre'};
  var g={qtd_vt:10, qtd_vr:5, dias:[], status:'ok'};
  // força evidência se motor exigir
  var sitPre=typeof rhResolverSituacaoColaborador==='function'
    ? rhResolverSituacaoColaborador(cPre, '2026-09-25', {evidencia_pre_admissao:true})
    : null;
  if(sitPre && sitPre.situacao_codigo!=='pre_admissao'){
    // fallback direto na validação via flags
    cPre._force_pre=true;
  }
  var vinPre=rhBeneficioValidarVinculoCarga(cPre, '2026-09-25');
  // se motor não marcar pre, simular ativo=false inativo → bloqueado; force path
  if(vinPre.status_vinculo_carga!=='pre_admissao'){
    vinPre=rhBeneficioValidarVinculoCarga({ativo:false, situacao_vinculo:'pre_admissao', id:'t4b'}, '2026-09-25');
    if(typeof rhResolverSituacaoColaborador==='function'){
      // chama com evidencia
      var sit2=rhResolverSituacaoColaborador({id:'t4b', ativo:false, situacao_vinculo:'pre_admissao'}, '2026-09-25', {evidencia_pre_admissao:true});
      check('G_pre_admissao_motor', sit2.situacao_codigo==='pre_admissao', sit2.situacao_codigo);
      rhBeneficioFinalizarApuracao(g, {id:'t4b', ativo:false, situacao_vinculo:'pre_admissao'}, per);
      // re-validate with opts by patching temporarily — use direct assignment
      g.status='pre_admissao'; g.direito_final_vt=0; g.direito_final_vr=0; g.status_vinculo_carga='pre_admissao';
    }
  } else {
    rhBeneficioFinalizarApuracao(g, cPre, per);
  }
  check('G_pre_admissao_status', g.status_vinculo_carga==='pre_admissao'||g.status==='pre_admissao', g);

  var cPj={id:'t5', ativo:true, dispensado:false, eh_pj:true, fonte_dp:'cena_manual', re:'104', nome:'PJ'};
  var h={qtd_vt:20, qtd_vr:10, dias:[], status:'ok'};
  rhBeneficioFinalizarApuracao(h, cPj, per);
  check('H_pj_nao_bloqueia_synergy', h.direito_final_vt===20 && h.status!=='bloqueado', h.status_vinculo_carga);

  var cSup={id:'t6', ativo:true, dispensado:false, cargo_confianca:true, regime_beneficio:'dias_uteis', re:'105', nome:'Sup', admissao:'2026-08-01'};
  var i=rhBeneficioMontarApuracaoConfianca({id:'tmp', re:'105', nome:'Sup', dias:[]}, cSup, per, {}, {}, {});
  rhBeneficioFinalizarApuracao(i, cSup, per);
  check('I_supervisor_confianca', i.regra_apuracao==='dias_uteis_confianca' && i.dias_uteis>0 && i.direito_bruto_vt>0, {du:i.dias_uteis, bruto:i.direito_bruto_vt});
  check('J_supervisor_sem_ponto_ok', (i.sem_marcacao||0)===0 && (i.menos_2h||0)===0, i);

  var cSupFer={id:'t7', ativo:true, cargo_confianca:true, regime_beneficio:'dias_uteis', re:'106', nome:'SupFer', admissao:'2026-08-01'};
  var progFer={}; ['2026-08-10','2026-08-11','2026-08-12','2026-08-13','2026-08-14'].forEach(function(d){ progFer[cSupFer.id+'|'+d]={status:'ferias'}; });
  var k=rhBeneficioMontarApuracaoConfianca({id:'tmp2', re:'106', nome:'SupFer', dias:[]}, cSupFer, per, {}, progFer, {});
  check('K_supervisor_ferias', (k.ferias||0)>=5 && k.direito_bruto_vt < (du.total*RH_BEN_VT_POR_DIA), {ferias:k.ferias, vt:k.qtd_vt});

  var cNovo={id:'t8', ativo:true, re:'107', nome:'Novo', admissao:'2026-08-15'};
  var n={qtd_vt:20, qtd_vr:10, dias:[], status:'ok', faltas:0};
  rhBeneficioFinalizarApuracao(n, cNovo, per);
  check('N_sem_historico', n.status==='sem_historico'||n._sem_historico===true, n.status);

  // Snapshot imutável após “salvar” em memória
  var snap=JSON.parse(JSON.stringify(n.snapshot_regra||{}));
  cNovo.cargo_confianca=true; cNovo.regime_beneficio='dias_uteis';
  check('P_snapshot_nao_muda_com_cadastro', snap.cargo_confianca===false||snap.cargo_confianca==null, snap);

  console.log('[RH Benefício Fase2A] ok='+ok+' fail='+fail, results);
  return {ok:ok, fail:fail, results:results};
}


// ── RH Benefícios VT/VR Fase 2B — conta-corrente / créditos / compensações ──
// Injetado em index.html. Reusa Fase 2A. Sem Ticket/API/carga automática.

var RH_BEN_COMP_FECHADOS={fechado:1,conciliado:1};

function rhBeneficioCompKey(ano, mes){
  return Number(ano)*100+Number(mes);
}
function rhBeneficioCompFechada(comp){
  if(!comp) return false;
  return !!RH_BEN_COMP_FECHADOS[String(comp.status||'')];
}
function rhBeneficioVinculoRef(c){
  if(!c) return null;
  var v=c.vinculo_ref||null;
  if(v==null||v==='') return null;
  return String(v);
}
function rhBeneficioRound2(n){
  return Math.round((Number(n)||0)*100)/100;
}
function rhBeneficioUnitarioBenef(a, benef){
  benef=String(benef||'').toUpperCase();
  if(benef==='VT'){
    if(a && a.unitario_vt_snapshot!=null) return Number(a.unitario_vt_snapshot)||0;
    if(a && a.vt_unitario!=null) return Number(a.vt_unitario)||0;
    return 0;
  }
  if(a && a.unitario_vr_snapshot!=null) return Number(a.unitario_vr_snapshot)||0;
  if(a && a.vr_unitario!=null) return Number(a.vr_unitario)||0;
  return Number(RH_BEN_VR_VALOR_PADRAO)||0;
}
/** Sinal do ledger: + = crédito empresa; − = crédito colaborador. */
function rhBeneficioMovSinal(m){
  if(!m || m.anulado_em) return 0;
  var t=String(m.tipo_movimento||'');
  var q=Number(m.quantidade)||0;
  if(t==='credito_empresa' || t==='retroativo') return +q;
  if(t==='credito_colaborador' || t==='complemento') return -q;
  if(t==='compensacao'){
    if(String(m.natureza)==='debito') return -q;
    return +q;
  }
  if(t==='estorno'){
    var orig=(m.payload&&m.payload.estorna_tipo)||'';
    if(orig==='credito_empresa'||orig==='retroativo') return -q;
    if(orig==='credito_colaborador'||orig==='complemento') return +q;
    if(orig==='compensacao') return String(m.natureza)==='credito' ? +q : -q;
  }
  return 0;
}
function rhBeneficioNaturezaSaldo(saldoQtd){
  var s=Number(saldoQtd)||0;
  if(Math.abs(s)<0.0001) return 'zerado';
  return s>0?'empresa':'colaborador';
}
function rhBeneficioMovimentosAtivos(lista){
  return (lista||[]).filter(function(m){ return m && !m.anulado_em && m.status!=='anulado'; });
}
function rhBeneficioSaldoColaborador(colaboradorId, vinculoRef, beneficio, ateCompetencia, opts){
  opts=opts||{};
  beneficio=String(beneficio||'').toUpperCase();
  var movs=opts.movimentos!=null?opts.movimentos:(_rhBen.movimentos||[]);
  var ate=ateCompetencia?rhBeneficioCompKey(ateCompetencia.ano, ateCompetencia.mes):null;
  var filtrados=rhBeneficioMovimentosAtivos(movs).filter(function(m){
    if(String(m.colaborador_id||'')!==String(colaboradorId||'')) return false;
    if(String(m.beneficio||'').toUpperCase()!==beneficio) return false;
    if(ate!=null){
      var k=rhBeneficioCompKey(m.competencia_ano, m.competencia_mes);
      if(k>=ate) return false;
    }
    if(vinculoRef){
      if(String(m.vinculo_ref||'')!==String(vinculoRef)) return false;
    } else {
      if(m.vinculo_ref) return false;
    }
    return true;
  });
  filtrados.sort(function(a,b){
    var ka=rhBeneficioCompKey(a.competencia_ano,a.competencia_mes);
    var kb=rhBeneficioCompKey(b.competencia_ano,b.competencia_mes);
    if(ka!==kb) return ka-kb;
    return String(a.criado_em||'').localeCompare(String(b.criado_em||''));
  });
  var saldoQ=0, saldoV=0;
  filtrados.forEach(function(m){
    var sig=rhBeneficioMovSinal(m);
    saldoQ+=sig;
    var vu=Number(m.valor_unitario);
    if(!isFinite(vu)) vu=0;
    saldoV+=sig*vu;
  });
  saldoQ=rhBeneficioRound2(saldoQ);
  saldoV=rhBeneficioRound2(saldoV);
  return {
    saldo_quantidade:saldoQ,
    saldo_valor:saldoV,
    natureza:rhBeneficioNaturezaSaldo(saldoQ),
    movimentos:filtrados,
    vinculo_ref:vinculoRef||null,
    beneficio:beneficio
  };
}
function rhBeneficioCalcularLiquido(direitoQtd, saldoAnteriorQtd){
  var dir=Number(direitoQtd)||0;
  var sal=Number(saldoAnteriorQtd)||0;
  var creditoEmpresa=sal>0?sal:0;
  var creditoColab=sal<0?-sal:0;
  var liquido=dir-creditoEmpresa+creditoColab;
  if(liquido<0) liquido=0;
  var restanteEmpresa=0;
  if(creditoEmpresa>dir) restanteEmpresa=creditoEmpresa-dir;
  return {
    liquido_qtd:rhBeneficioRound2(liquido),
    credito_empresa_aplicado:rhBeneficioRound2(Math.min(creditoEmpresa, dir)),
    credito_colaborador_aplicado:rhBeneficioRound2(creditoColab),
    saldo_empresa_restante:rhBeneficioRound2(restanteEmpresa),
    direito_qtd:dir
  };
}
function rhBeneficioOrigemRefDireito(ano, mes, colaboradorId, benef){
  return 'apuracao:'+ano+rhBeneficioPad2(mes)+':'+(colaboradorId||'')+':'+String(benef).toUpperCase();
}
function rhBeneficioOrigemRefCarga(ano, mes, colabId, benef){
  return 'carga:'+ano+rhBeneficioPad2(mes)+':'+(colabId||'')+':'+String(benef).toUpperCase();
}
function rhBeneficioOrigemRefCredito(anoOrig, mesOrig, colabId, benef, tipo){
  return 'credito:'+tipo+':'+anoOrig+rhBeneficioPad2(mesOrig)+':'+(colabId||'')+':'+String(benef).toUpperCase();
}
function rhBeneficioOrigemRefCompensacao(ano, mes, colabId, benef){
  return 'compensacao:'+ano+rhBeneficioPad2(mes)+':'+(colabId||'')+':'+String(benef).toUpperCase();
}
function rhBeneficioOrigemRefRetroativo(anoOrig, mesOrig, colabId, benef, tag){
  return 'retroativo:'+anoOrig+rhBeneficioPad2(mesOrig)+':'+(colabId||'')+':'+String(benef).toUpperCase()+':'+(tag||'adj');
}
function rhBeneficioEncontrarMovPorOrigem(origemRef, opts){
  opts=opts||{};
  var movs=opts.movimentos!=null?opts.movimentos:(_rhBen.movimentos||[]);
  return rhBeneficioMovimentosAtivos(movs).find(function(m){ return String(m.origem_ref||'')===String(origemRef||''); })||null;
}
function rhBeneficioMontarMovimento(base){
  var m=Object.assign({
    id:typeof gerarUUID==='function'?gerarUUID():('m'+Date.now()+Math.random()),
    status:'ativo',
    criado_em:new Date().toISOString(),
    criado_por:rhBeneficioUsuario(),
    anulado_em:null,
    anulado_motivo:null
  }, base||{});
  m.quantidade=rhBeneficioRound2(Math.abs(Number(m.quantidade)||0));
  if(m.valor_unitario!=null) m.valor_unitario=rhBeneficioRound2(m.valor_unitario);
  if(m.valor_total==null && m.valor_unitario!=null)
    m.valor_total=rhBeneficioRound2(m.quantidade*m.valor_unitario);
  return m;
}
async function rhBeneficioAnularMovimento(m, motivo){
  if(!m||!m.id) return false;
  if(m.status==='fechado') return false;
  var patch={
    anulado_em:new Date().toISOString(),
    anulado_motivo:motivo||'Anulado',
    status:'anulado'
  };
  if(!DEMO){
    var ok=await sbUpdate('rh_beneficio_movimentos', patch, 'id=eq.'+m.id);
    if(!ok) return false;
  }
  Object.assign(m, patch);
  return true;
}
async function rhBeneficioUpsertMovimento(row, opts){
  opts=opts||{};
  if(!row || !row.origem_ref) return null;
  var prev=rhBeneficioEncontrarMovPorOrigem(row.origem_ref, opts);
  if(prev){
    if(opts.competenciaFechada || prev.status==='fechado') return prev;
    var patch={
      quantidade:row.quantidade,
      valor_unitario:row.valor_unitario,
      valor_total:row.valor_total,
      saldo_quantidade:row.saldo_quantidade,
      saldo_valor:row.saldo_valor,
      motivo:row.motivo,
      payload:row.payload,
      vinculo_ref:row.vinculo_ref,
      natureza:row.natureza,
      tipo_movimento:row.tipo_movimento
    };
    if(!DEMO){
      var ok=await sbUpdate('rh_beneficio_movimentos', patch, 'id=eq.'+prev.id);
      if(!ok) return null;
    }
    Object.assign(prev, patch);
    return prev;
  }
  var novo=rhBeneficioMontarMovimento(row);
  if(!DEMO){
    var ins=await sbInsert('rh_beneficio_movimentos', novo, {silent:true});
    if(ins && ins[0]) novo=ins[0];
  }
  if(!_rhBen.movimentos) _rhBen.movimentos=[];
  _rhBen.movimentos.push(novo);
  return novo;
}
function rhBeneficioAplicarContaCorrenteLinha(a, c){
  if(!a) return a;
  rhBeneficioEstimarValores(a);
  a.unitario_vt_snapshot=rhBeneficioUnitarioBenef(a,'VT');
  a.unitario_vr_snapshot=rhBeneficioUnitarioBenef(a,'VR');
  var vref=rhBeneficioVinculoRef(c);
  a.vinculo_ref=vref;
  a._revisar_vinculo_cc=!vref;

  // PJ: zero líquido; não usa saldo/movimentos para carga; histórico só sinaliza revisão
  if(rhBeneficioEhPj(c) || a._eh_pj || a.status==='pj_sem_direito' || a.regra_apuracao==='pj_sem_direito'){
    a._eh_pj=true;
    a.direito_bruto_vt=0; a.direito_bruto_vr=0;
    a.direito_final_vt=0; a.direito_final_vr=0;
    a.qtd_vt=0; a.qtd_vr=0;
    a.liquido_vt_qtd=0; a.liquido_vr_qtd=0;
    a.liquido_vt_valor=0; a.liquido_vr_valor=0;
    a.saldo_anterior_vt_qtd=0; a.saldo_anterior_vr_qtd=0;
    a.saldo_anterior_vt_valor=0; a.saldo_anterior_vr_valor=0;
    a._comp_vt={liquido_qtd:0, credito_empresa_aplicado:0, credito_colaborador_aplicado:0, saldo_empresa_restante:0, direito_qtd:0};
    a._comp_vr=a._comp_vt;
    a.motivo_bloqueio=a.motivo_bloqueio||'Política empresarial: colaboradores PJ não participam dos benefícios VT/VR.';
    var histPj=rhBeneficioTemMovimentoBeneficio(a.colaborador_id);
    a._revisar_pj_mov=!!histPj;
    if(histPj){
      a.status='revisar_pj';
      a.status_saldo='REVISAR — MOVIMENTAÇÃO DE BENEFÍCIO EM COLABORADOR PJ';
      a.status_conciliacao='revisar_pj';
    } else {
      a.status='pj_sem_direito';
      a.status_saldo='PJ — SEM DIREITO A VT/VR';
      a.status_conciliacao='pj_sem_direito';
    }
    return a;
  }

  var ano=_rhBen.pagAno, mes=_rhBen.pagMes;
  var ate={ano:ano, mes:mes};
  var salVt=rhBeneficioSaldoColaborador(a.colaborador_id, vref, 'VT', ate);
  var salVr=rhBeneficioSaldoColaborador(a.colaborador_id, vref, 'VR', ate);
  a.saldo_anterior_vt_qtd=salVt.saldo_quantidade;
  a.saldo_anterior_vr_qtd=salVr.saldo_quantidade;
  a.saldo_anterior_vt_valor=salVt.saldo_valor;
  a.saldo_anterior_vr_valor=salVr.saldo_valor;
  var dirVt=Number(a.direito_final_vt!=null?a.direito_final_vt:a.qtd_vt)||0;
  var dirVr=Number(a.direito_final_vr!=null?a.direito_final_vr:a.qtd_vr)||0;
  var liqVt=rhBeneficioCalcularLiquido(dirVt, salVt.saldo_quantidade);
  var liqVr=rhBeneficioCalcularLiquido(dirVr, salVr.saldo_quantidade);
  a.liquido_vt_qtd=liqVt.liquido_qtd;
  a.liquido_vr_qtd=liqVr.liquido_qtd;
  a.liquido_vt_valor=rhBeneficioRound2(a.liquido_vt_qtd*a.unitario_vt_snapshot);
  a.liquido_vr_valor=rhBeneficioRound2(a.liquido_vr_qtd*a.unitario_vr_snapshot);
  a._comp_vt=liqVt;
  a._comp_vr=liqVr;
  if(a.pago_vt_qtd===undefined) a.pago_vt_qtd=null;
  if(a.pago_vr_qtd===undefined) a.pago_vr_qtd=null;
  a.status_conciliacao=rhBeneficioStatusConciliacao(a);
  a.status_saldo=rhBeneficioStatusSaldoLabel(a);
  if(a._revisar_vinculo_cc)
    a.status_saldo=(a.status_saldo&&a.status_saldo!=='Zerado')?a.status_saldo:'REVISAR VÍNCULO (sem vinculo_ref)';
  return a;
}
function rhBeneficioStatusConciliacao(a){
  if(!a) return 'sem_carga';
  var pVt=a.pago_vt_qtd, pVr=a.pago_vr_qtd;
  if(pVt==null && pVr==null) return 'sem_carga';
  var dVt=Number(a.direito_final_vt!=null?a.direito_final_vt:a.qtd_vt)||0;
  var dVr=Number(a.direito_final_vr!=null?a.direito_final_vr:a.qtd_vr)||0;
  var okVt=pVt==null||Math.abs(Number(pVt)-dVt)<0.0001;
  var okVr=pVr==null||Math.abs(Number(pVr)-dVr)<0.0001;
  if(okVt && okVr && pVt!=null && pVr!=null) return 'conciliado';
  var emp=false, col=false;
  if(pVt!=null){ if(Number(pVt)>dVt) emp=true; if(Number(pVt)<dVt) col=true; }
  if(pVr!=null){ if(Number(pVr)>dVr) emp=true; if(Number(pVr)<dVr) col=true; }
  if(emp && col) return 'parcial';
  if(emp) return 'credito_empresa';
  if(col) return 'credito_colaborador';
  return 'parcial';
}
function rhBeneficioStatusSaldoLabel(a){
  var sv=Number(a.saldo_anterior_vt_qtd)||0;
  var sr=Number(a.saldo_anterior_vr_qtd)||0;
  if(Math.abs(sv)<0.0001 && Math.abs(sr)<0.0001) return 'Zerado';
  var parts=[];
  if(sv>0) parts.push('Emp VT '+sv);
  if(sv<0) parts.push('Colab VT '+(-sv));
  if(sr>0) parts.push('Emp VR '+sr);
  if(sr<0) parts.push('Colab VR '+(-sr));
  return parts.join(' · ')||'Zerado';
}
async function rhBeneficioCarregarMovimentos(colabIds){
  _rhBen.movimentos=_rhBen.movimentos||[];
  if(DEMO) return _rhBen.movimentos;
  colabIds=(colabIds||[]).filter(Boolean);
  if(!colabIds.length){ _rhBen.movimentos=[]; return []; }
  try{
    var rows=await rhBeneficioFetchIn('rh_beneficio_movimentos','colaborador_id',colabIds,['anulado_em=is.null']);
    if(rows===null){ _rhBen.movOk=false; return _rhBen.movimentos||[]; }
    _rhBen.movOk=true;
    _rhBen.movimentos=rows||[];
  }catch(e){
    _rhBen.movOk=false;
    _rhBen.movimentos=_rhBen.movimentos||[];
  }
  return _rhBen.movimentos;
}
async function rhBeneficioPersistirDireitoECompensacao(a, c, opts){
  opts=opts||{};
  if(!a || !a.colaborador_id) return;
  if(rhBeneficioEhPj(c) || a._eh_pj || a.status==='pj_sem_direito' || a.status==='revisar_pj' || a.regra_apuracao==='pj_sem_direito'){
    // Política: PJ não gera direito/compensação/crédito automático
    return;
  }
  if(rhBeneficioCompFechada(_rhBen.competencia) && !opts.forcar) return;
  var ano=_rhBen.pagAno, mes=_rhBen.pagMes;
  var vref=rhBeneficioVinculoRef(c)||a.vinculo_ref||null;
  var fechada=rhBeneficioCompFechada(_rhBen.competencia);
  async function um(benef, dirFinal, dirBruto, unit, liq){
    var oRef=rhBeneficioOrigemRefDireito(ano, mes, a.colaborador_id, benef);
    await rhBeneficioUpsertMovimento({
      colaborador_id:a.colaborador_id, vinculo_ref:vref,
      competencia_ano:ano, competencia_mes:mes, beneficio:benef,
      tipo_movimento:'direito', natureza:'credito',
      quantidade:dirFinal, valor_unitario:unit,
      valor_total:rhBeneficioRound2(dirFinal*unit),
      origem:'apuracao', origem_ref:oRef,
      motivo:'Direito final competência '+ano+'-'+rhBeneficioPad2(mes),
      payload:{direito_bruto:dirBruto, direito_final:dirFinal, apuracao_id:a.id}
    }, {competenciaFechada:fechada});
    var oComp=rhBeneficioOrigemRefCompensacao(ano, mes, a.colaborador_id, benef);
    var empApp=liq.credito_empresa_aplicado||0;
    var colApp=liq.credito_colaborador_aplicado||0;
    if(empApp>0){
      await rhBeneficioUpsertMovimento({
        colaborador_id:a.colaborador_id, vinculo_ref:vref,
        competencia_ano:ano, competencia_mes:mes, beneficio:benef,
        tipo_movimento:'compensacao', natureza:'debito',
        quantidade:empApp, valor_unitario:unit,
        valor_total:rhBeneficioRound2(empApp*unit),
        origem:'compensacao', origem_ref:oComp+':empresa',
        motivo:'Compensação crédito empresa na competência',
        payload:{aplicado:empApp, restante:liq.saldo_empresa_restante, liquido:liq.liquido_qtd}
      }, {competenciaFechada:fechada});
    } else if(colApp>0){
      await rhBeneficioUpsertMovimento({
        colaborador_id:a.colaborador_id, vinculo_ref:vref,
        competencia_ano:ano, competencia_mes:mes, beneficio:benef,
        tipo_movimento:'compensacao', natureza:'credito',
        quantidade:colApp, valor_unitario:unit,
        valor_total:rhBeneficioRound2(colApp*unit),
        origem:'compensacao', origem_ref:oComp+':colaborador',
        motivo:'Compensação crédito colaborador na competência',
        payload:{aplicado:colApp, liquido:liq.liquido_qtd}
      }, {competenciaFechada:fechada});
    } else {
      var prevE=rhBeneficioEncontrarMovPorOrigem(oComp+':empresa');
      var prevC=rhBeneficioEncontrarMovPorOrigem(oComp+':colaborador');
      if(prevE && !fechada) await rhBeneficioAnularMovimento(prevE, 'Sem crédito empresa a compensar');
      if(prevC && !fechada) await rhBeneficioAnularMovimento(prevC, 'Sem crédito colaborador a compensar');
    }
  }
  await um('VT', Number(a.direito_final_vt)||0, Number(a.direito_bruto_vt)||0, a.unitario_vt_snapshot||0,
    a._comp_vt||rhBeneficioCalcularLiquido(a.direito_final_vt,a.saldo_anterior_vt_qtd));
  await um('VR', Number(a.direito_final_vr)||0, Number(a.direito_bruto_vr)||0, a.unitario_vr_snapshot||0,
    a._comp_vr||rhBeneficioCalcularLiquido(a.direito_final_vr,a.saldo_anterior_vr_qtd));
}
async function rhBeneficioGerarCreditosAposCarga(a, c, benef, pagoQtd){
  benef=String(benef).toUpperCase();
  var ano=_rhBen.pagAno, mes=_rhBen.pagMes;
  var dir=benef==='VT'?(Number(a.direito_final_vt)||0):(Number(a.direito_final_vr)||0);
  var pago=Number(pagoQtd)||0;
  var unit=rhBeneficioUnitarioBenef(a, benef);
  var vref=rhBeneficioVinculoRef(c)||a.vinculo_ref||null;
  var diff=rhBeneficioRound2(pago-dir);
  var oEmp=rhBeneficioOrigemRefCredito(ano, mes, a.colaborador_id, benef, 'empresa');
  var oCol=rhBeneficioOrigemRefCredito(ano, mes, a.colaborador_id, benef, 'colaborador');
  var prevE=rhBeneficioEncontrarMovPorOrigem(oEmp);
  var prevC=rhBeneficioEncontrarMovPorOrigem(oCol);
  if(Math.abs(diff)<0.0001){
    if(prevE) await rhBeneficioAnularMovimento(prevE, 'Conciliado — sem crédito');
    if(prevC) await rhBeneficioAnularMovimento(prevC, 'Conciliado — sem crédito');
    return {status:'conciliado', diff:0};
  }
  if(diff>0){
    if(prevC) await rhBeneficioAnularMovimento(prevC, 'Substituído por crédito empresa');
    await rhBeneficioUpsertMovimento({
      colaborador_id:a.colaborador_id, vinculo_ref:vref,
      competencia_ano:ano, competencia_mes:mes, beneficio:benef,
      tipo_movimento:'credito_empresa', natureza:'credito',
      quantidade:diff, valor_unitario:unit, valor_total:rhBeneficioRound2(diff*unit),
      origem:'manual', origem_ref:oEmp,
      competencia_origem_ano:ano, competencia_origem_mes:mes,
      motivo:'Pago a maior: pago '+pago+' × direito '+dir,
      payload:{pago:pago, direito:dir}
    });
    return {status:'credito_empresa', diff:diff};
  }
  if(prevE) await rhBeneficioAnularMovimento(prevE, 'Substituído por crédito colaborador');
  await rhBeneficioUpsertMovimento({
    colaborador_id:a.colaborador_id, vinculo_ref:vref,
    competencia_ano:ano, competencia_mes:mes, beneficio:benef,
    tipo_movimento:'credito_colaborador', natureza:'credito',
    quantidade:-diff, valor_unitario:unit, valor_total:rhBeneficioRound2((-diff)*unit),
    origem:'manual', origem_ref:oCol,
    competencia_origem_ano:ano, competencia_origem_mes:mes,
    motivo:'Pago a menor: pago '+pago+' × direito '+dir,
    payload:{pago:pago, direito:dir}
  });
  return {status:'credito_colaborador', diff:diff};
}
async function rhBeneficioRegistrarCargaConfirmada(re, pagoVt, pagoVr, valorVt, valorVr){
  var a=(_rhBen.lista||[]).find(function(x){ return pontoReNorm(x.re)===pontoReNorm(re); });
  if(!a) return;
  var c=rhBeneficioColabDaApuracao(a)||{};
  if(rhBeneficioEhPj(c) || a._eh_pj){
    if(typeof progShowToast==='function') progShowToast('PJ sem direito a VT/VR — carga não permitida.','erro');
    return;
  }
  if(rhBeneficioCompFechada(_rhBen.competencia)){
    if(typeof progShowToast==='function') progShowToast('Competência fechada — use ajuste retroativo.','erro');
    return;
  }
  var ano=_rhBen.pagAno, mes=_rhBen.pagMes;
  var vref=rhBeneficioVinculoRef(c)||a.vinculo_ref||null;
  var uVt=rhBeneficioUnitarioBenef(a,'VT');
  var uVr=rhBeneficioUnitarioBenef(a,'VR');
  if(valorVt==null||valorVt==='') valorVt=rhBeneficioRound2((Number(pagoVt)||0)*uVt);
  if(valorVr==null||valorVr==='') valorVr=rhBeneficioRound2((Number(pagoVr)||0)*uVr);
  await rhBeneficioUpsertMovimento({
    colaborador_id:a.colaborador_id, vinculo_ref:vref,
    competencia_ano:ano, competencia_mes:mes, beneficio:'VT',
    tipo_movimento:'carga', natureza:'debito',
    quantidade:Number(pagoVt)||0, valor_unitario:uVt, valor_total:Number(valorVt)||0,
    origem:'manual', origem_ref:rhBeneficioOrigemRefCarga(ano,mes,a.colaborador_id,'VT'),
    motivo:'Carga/pagamento informado manualmente'
  });
  await rhBeneficioUpsertMovimento({
    colaborador_id:a.colaborador_id, vinculo_ref:vref,
    competencia_ano:ano, competencia_mes:mes, beneficio:'VR',
    tipo_movimento:'carga', natureza:'debito',
    quantidade:Number(pagoVr)||0, valor_unitario:uVr, valor_total:Number(valorVr)||0,
    origem:'manual', origem_ref:rhBeneficioOrigemRefCarga(ano,mes,a.colaborador_id,'VR'),
    motivo:'Carga/pagamento informado manualmente'
  });
  a.pago_vt_qtd=Number(pagoVt)||0;
  a.pago_vr_qtd=Number(pagoVr)||0;
  a.pago_vt_valor=Number(valorVt)||0;
  a.pago_vr_valor=Number(valorVr)||0;
  await rhBeneficioGerarCreditosAposCarga(a, c, 'VT', a.pago_vt_qtd);
  await rhBeneficioGerarCreditosAposCarga(a, c, 'VR', a.pago_vr_qtd);
  a.status_conciliacao=rhBeneficioStatusConciliacao(a);
  if(a.id && !DEMO && _rhBen.competencia && _rhBen.competencia.id){
    await sbUpdate('rh_beneficio_apuracoes', {
      pago_vt_qtd:a.pago_vt_qtd, pago_vr_qtd:a.pago_vr_qtd,
      pago_vt_valor:a.pago_vt_valor, pago_vr_valor:a.pago_vr_valor,
      status_conciliacao:a.status_conciliacao,
      liquido_vt_qtd:a.liquido_vt_qtd, liquido_vr_qtd:a.liquido_vr_qtd,
      liquido_vt_valor:a.liquido_vt_valor, liquido_vr_valor:a.liquido_vr_valor
    }, 'id=eq.'+a.id);
  } else _rhBen.sujo=true;
  if(typeof progShowToast==='function') progShowToast('Carga registrada e créditos atualizados.');
  rhBeneficioAbrirExtrato(a.re);
  rhBeneficioRender();
}
async function rhBeneficioRegistrarRetroativo(re, benef, qtdReducao, motivo, compOrigAno, compOrigMes){
  var a=(_rhBen.lista||[]).find(function(x){ return pontoReNorm(x.re)===pontoReNorm(re); });
  if(!a) return;
  var c=rhBeneficioColabDaApuracao(a)||{};
  if(rhBeneficioEhPj(c) || a._eh_pj){
    if(typeof progShowToast==='function') progShowToast('PJ sem direito a VT/VR — retroativo de benefício não permitido.','erro');
    return;
  }
  benef=String(benef).toUpperCase();
  var q=Math.abs(Number(qtdReducao)||0);
  if(!q){ if(typeof progShowToast==='function') progShowToast('Informe quantidade.','erro'); return; }
  var unit=rhBeneficioUnitarioBenef(a, benef);
  var vref=rhBeneficioVinculoRef(c)||a.vinculo_ref||null;
  var ano=_rhBen.pagAno, mes=_rhBen.pagMes;
  var oAno=compOrigAno||ano, oMes=compOrigMes||mes;
  var tag=String(Date.now()).slice(-6);
  await rhBeneficioUpsertMovimento({
    colaborador_id:a.colaborador_id, vinculo_ref:vref,
    competencia_ano:ano, competencia_mes:mes, beneficio:benef,
    tipo_movimento:'retroativo', natureza:'credito',
    quantidade:q, valor_unitario:unit, valor_total:rhBeneficioRound2(q*unit),
    origem:'manual', origem_ref:rhBeneficioOrigemRefRetroativo(oAno,oMes,a.colaborador_id,benef,tag),
    competencia_origem_ano:oAno, competencia_origem_mes:oMes,
    motivo:motivo||('Ajuste retroativo — redução de direito '+benef),
    payload:{efeito:'credito_empresa'}
  });
  if(typeof progShowToast==='function') progShowToast('Retroativo registrado — impacto na próxima compensação.');
  rhBeneficioAplicarContaCorrenteLinha(a, c);
  rhBeneficioAbrirExtrato(a.re);
  rhBeneficioRender();
}
async function rhBeneficioEstornarMovimentoId(movId, motivo){
  var m=(_rhBen.movimentos||[]).find(function(x){ return String(x.id)===String(movId); });
  if(!m){ if(typeof progShowToast==='function') progShowToast('Movimento não encontrado.','erro'); return; }
  if(m.status==='fechado'){ if(typeof progShowToast==='function') progShowToast('Movimento fechado.','erro'); return; }
  if(m.anulado_em) return;
  var unit=Number(m.valor_unitario)||0;
  var est=rhBeneficioMontarMovimento({
    colaborador_id:m.colaborador_id, vinculo_ref:m.vinculo_ref,
    competencia_ano:_rhBen.pagAno, competencia_mes:_rhBen.pagMes,
    beneficio:m.beneficio, tipo_movimento:'estorno',
    natureza:m.natureza==='credito'?'debito':'credito',
    quantidade:m.quantidade, valor_unitario:unit,
    valor_total:rhBeneficioRound2((Number(m.quantidade)||0)*unit),
    origem:'estorno', origem_ref:'estorno:'+m.id,
    motivo:motivo||('Estorno de '+m.tipo_movimento),
    payload:{estorna_id:m.id, estorna_tipo:m.tipo_movimento}
  });
  if(!DEMO){
    var ins=await sbInsert('rh_beneficio_movimentos', est, {silent:true});
    if(ins&&ins[0]) est=ins[0];
  }
  _rhBen.movimentos.push(est);
  await rhBeneficioAnularMovimento(m, motivo||'Estornado');
  if(typeof progShowToast==='function') progShowToast('Estorno registrado.');
  rhBeneficioRender();
}
function rhBeneficioKpisContaCorrente(lista){
  var k={empVt:0,empVr:0,colVt:0,colVr:0,aPagarVt:0,aPagarVr:0,pagoVt:0,pagoVr:0,div:0,pend:0};
  (lista||[]).forEach(function(a){
    var sv=Number(a.saldo_anterior_vt_qtd)||0, sr=Number(a.saldo_anterior_vr_qtd)||0;
    if(sv>0) k.empVt+=sv; if(sv<0) k.colVt+=-sv;
    if(sr>0) k.empVr+=sr; if(sr<0) k.colVr+=-sr;
    k.aPagarVt+=Number(a.liquido_vt_qtd)||0;
    k.aPagarVr+=Number(a.liquido_vr_qtd)||0;
    k.pagoVt+=Number(a.pago_vt_qtd)||0;
    k.pagoVr+=Number(a.pago_vr_qtd)||0;
    if(a.status_conciliacao && a.status_conciliacao!=='conciliado' && a.status_conciliacao!=='sem_carga') k.div++;
    if(Math.abs(sv)>0||Math.abs(sr)>0) k.pend++;
  });
  return k;
}
function rhBeneficioExtratoHtml(a, benef){
  benef=String(benef).toUpperCase();
  var c=rhBeneficioColabDaApuracao(a)||{};
  var vref=rhBeneficioVinculoRef(c)||a.vinculo_ref||null;
  var todos=rhBeneficioMovimentosAtivos(_rhBen.movimentos).filter(function(m){
    if(String(m.colaborador_id||'')!==String(a.colaborador_id||'')) return false;
    if(String(m.beneficio||'').toUpperCase()!==benef) return false;
    if(vref){ if(String(m.vinculo_ref||'')!==String(vref)) return false; }
    else if(m.vinculo_ref) return false;
    return true;
  }).sort(function(x,y){
    var kx=rhBeneficioCompKey(x.competencia_ano,x.competencia_mes);
    var ky=rhBeneficioCompKey(y.competencia_ano,y.competencia_mes);
    if(kx!==ky) return kx-ky;
    return String(x.criado_em||'').localeCompare(String(y.criado_em||''));
  });
  var saldo=0;
  var rows=todos.map(function(m){
    var sig=rhBeneficioMovSinal(m);
    saldo=rhBeneficioRound2(saldo+sig);
    var nat=rhBeneficioNaturezaSaldo(saldo);
    return '<tr>'
      +'<td>'+rhEsc(String(m.criado_em||'').slice(0,16).replace('T',' '))+'</td>'
      +'<td>'+rhEsc(m.tipo_movimento)+'</td>'
      +'<td>'+rhEsc(m.competencia_ano+'-'+rhBeneficioPad2(m.competencia_mes))+'</td>'
      +'<td style="text-align:right">'+(sig?((sig>0?'+':'')+sig):m.quantidade)+'</td>'
      +'<td style="text-align:right">'+(m.valor_total!=null?rhBeneficioFmtR(m.valor_total):'—')+'</td>'
      +'<td style="text-align:right">'+saldo+' <span style="font-size:10px;color:#888">('+nat+')</span></td>'
      +'<td>'+rhEsc(m.motivo||'')+'</td>'
      +'<td>'+rhEsc(m.origem||'')+'</td>'
      +'<td>'+rhEsc(m.criado_por||'')+'</td>'
      +'<td>'+(m.tipo_movimento!=='estorno'&&!m.anulado_em?'<button class="btn btn-sm" onclick="rhBeneficioEstornarMovimentoId(\''+rhEsc(m.id)+'\')">Estornar</button>':'')+'</td>'
      +'</tr>';
  }).join('');
  return '<h4 style="margin:12px 0 6px">Extrato '+benef+'</h4>'
    +'<div style="overflow-x:auto"><table class="tbl" style="font-size:11px"><thead><tr>'
    +'<th>Data</th><th>Tipo</th><th>Competência</th><th>Qtd</th><th>Valor</th><th>Saldo</th><th>Motivo</th><th>Origem</th><th>Usuário</th><th></th>'
    +'</tr></thead><tbody>'
    +(rows||'<tr><td colspan="10" style="padding:1rem;text-align:center;color:#aaa">Sem movimentos</td></tr>')
    +'</tbody></table></div>';
}
function rhBeneficioDemonstrativoHtml(a){
  rhBeneficioEstimarValores(a);
  var uVr=rhBeneficioUnitarioBenef(a,'VR');
  var uVt=rhBeneficioUnitarioBenef(a,'VT');
  var dVr=Number(a.direito_final_vr)||0, dVt=Number(a.direito_final_vt)||0;
  var sVr=Number(a.saldo_anterior_vr_qtd)||0, sVt=Number(a.saldo_anterior_vt_qtd)||0;
  var lVr=Number(a.liquido_vr_qtd)||0, lVt=Number(a.liquido_vt_qtd)||0;
  function bloco(tit, dir, sal, liq, unit){
    var emp=sal>0?sal:0, col=sal<0?-sal:0;
    return '<div style="margin-bottom:12px;padding:10px;border:1px solid #ddd;border-radius:8px">'
      +'<div style="font-weight:700;margin-bottom:6px">'+tit+'</div>'
      +'<div>Direito do mês: <b>'+dir+'</b> = '+rhBeneficioFmtR(dir*unit)+'</div>'
      +(emp?'<div>Crédito anterior (empresa): <b>'+emp+'</b> = '+rhBeneficioFmtR(emp*unit)+'</div>':'')
      +(col?'<div>Crédito anterior (colaborador): <b>'+col+'</b> = '+rhBeneficioFmtR(col*unit)+'</div>':'')
      +(!emp&&!col?'<div>Crédito anterior: 0</div>':'')
      +'<div style="margin-top:6px">Total líquido: <b>'+liq+'</b> = '+rhBeneficioFmtR(liq*unit)+'</div></div>';
  }
  return '<h4>Demonstrativo — competência '+_rhBen.pagAno+'-'+rhBeneficioPad2(_rhBen.pagMes)+'</h4>'
    +'<div style="font-size:12px;color:#666;margin-bottom:8px">'+rhEsc(a.nome)+' · RE '+rhEsc(a.re)
    +(a.vinculo_ref?' · vínculo '+rhEsc(String(a.vinculo_ref).slice(0,8))+'…':' · <b style="color:#854F0B">sem vinculo_ref</b>')
    +'</div>'
    +bloco('VR', dVr, sVr, lVr, uVr)
    +bloco('VT', dVt, sVt, lVt, uVt)
    +'<div style="font-size:11px;color:#888">Impressão simples — sem PDF. Valor unitário do saldo antigo permanece no movimento original.</div>';
}
function rhBeneficioAbrirExtrato(re){
  var a=(_rhBen.lista||[]).find(function(x){ return pontoReNorm(x.re)===pontoReNorm(re); });
  if(!a) return;
  setModal('<div class="modal-bg"><div class="modal" style="max-width:1100px;max-height:92vh;overflow:auto">'
    +'<h3>Conta-corrente — '+rhEsc(a.nome)+' · RE '+rhEsc(a.re)+'</h3>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px">'
    +'<button class="btn btn-sm btn-pri" onclick="rhBeneficioAbrirRegistrarCarga(\''+rhEsc(a.re)+'\')">Registrar carga paga</button>'
    +'<button class="btn btn-sm" onclick="rhBeneficioAbrirRetroativo(\''+rhEsc(a.re)+'\')">Ajuste retroativo</button>'
    +'<button class="btn btn-sm" onclick="rhBeneficioAbrirDetalhe(\''+rhEsc(a.re)+'\')">Detalhe diário (ponto)</button>'
    +'<button class="btn btn-sm" onclick="window.print()">Imprimir demonstrativo</button></div>'
    +rhBeneficioDemonstrativoHtml(a)
    +rhBeneficioExtratoHtml(a,'VR')
    +rhBeneficioExtratoHtml(a,'VT')
    +'<div class="ma"><button class="btn" onclick="closeModal()">Fechar</button></div></div></div>');
}
function rhBeneficioAbrirRegistrarCarga(re){
  var a=(_rhBen.lista||[]).find(function(x){ return pontoReNorm(x.re)===pontoReNorm(re); });
  if(!a) return;
  var c0=rhBeneficioColabDaApuracao(a)||{};
  if(rhBeneficioEhPj(c0) || a._eh_pj){
    if(typeof progShowToast==='function') progShowToast('PJ — sem direito a VT/VR. Carga não permitida.','erro');
    return;
  }
  var dVt=Number(a.direito_final_vt)||0, dVr=Number(a.direito_final_vr)||0;
  var lVt=a.liquido_vt_qtd!=null?Number(a.liquido_vt_qtd):dVt;
  var lVr=a.liquido_vr_qtd!=null?Number(a.liquido_vr_qtd):dVr;
  setModal('<div class="modal-bg"><div class="modal" style="max-width:480px">'
    +'<h3>Registrar valor/quantidade efetivamente carregada</h3>'
    +'<div style="font-size:12px;color:#666;margin-bottom:10px">Direito final VT '+dVt+' / VR '+dVr
    +' · Saldo ant. VT '+(a.saldo_anterior_vt_qtd||0)+' / VR '+(a.saldo_anterior_vr_qtd||0)
    +' · Líquido previsto VT '+lVt+' / VR '+lVr+'</div>'
    +'<div class="g2">'
    +'<div class="fg"><label>Qtd paga VT</label><input class="inp" type="number" min="0" step="1" id="rh-ben-pago-vt" value="'+(a.pago_vt_qtd!=null?a.pago_vt_qtd:lVt)+'"/></div>'
    +'<div class="fg"><label>Qtd paga VR</label><input class="inp" type="number" min="0" step="1" id="rh-ben-pago-vr" value="'+(a.pago_vr_qtd!=null?a.pago_vr_qtd:lVr)+'"/></div></div>'
    +'<div style="font-size:11px;color:#854F0B;margin:8px 0">Confirmação obrigatória. Não assume direito = pago. Origem: manual.</div>'
    +'<div class="ma"><button class="btn" onclick="rhBeneficioAbrirExtrato(\''+rhEsc(a.re)+'\')">Voltar</button>'
    +'<button class="btn btn-pri" onclick="rhBeneficioConfirmarCargaUI(\''+rhEsc(a.re)+'\')">Confirmar carga</button></div></div></div>');
}
function rhBeneficioConfirmarCargaUI(re){
  var vt=parseFloat((document.getElementById('rh-ben-pago-vt')||{}).value);
  var vr=parseFloat((document.getElementById('rh-ben-pago-vr')||{}).value);
  if(isNaN(vt)||vt<0||isNaN(vr)||vr<0){ if(typeof progShowToast==='function') progShowToast('Quantidades inválidas.','erro'); return; }
  if(!confirm('Confirmar carga paga VT='+vt+' / VR='+vr+'?')) return;
  rhBeneficioRegistrarCargaConfirmada(re, vt, vr, null, null);
}
function rhBeneficioAbrirRetroativo(re){
  var a=(_rhBen.lista||[]).find(function(x){ return pontoReNorm(x.re)===pontoReNorm(re); });
  if(!a) return;
  setModal('<div class="modal-bg"><div class="modal" style="max-width:440px">'
    +'<h3>Ajuste retroativo</h3>'
    +'<div style="font-size:12px;color:#666;margin-bottom:8px">Não reescreve competência paga. Gera crédito empresa para compensar depois.</div>'
    +'<div class="fg"><label>Benefício</label><select class="inp" id="rh-ben-ret-benef"><option value="VR">VR</option><option value="VT">VT</option></select></div>'
    +'<div class="fg"><label>Qtd a reduzir do direito</label><input class="inp" type="number" min="1" id="rh-ben-ret-qtd" value="1"/></div>'
    +'<div class="g2"><div class="fg"><label>Competência origem (ano)</label><input class="inp" type="number" id="rh-ben-ret-ano" value="'+_rhBen.pagAno+'"/></div>'
    +'<div class="fg"><label>Mês</label><input class="inp" type="number" min="1" max="12" id="rh-ben-ret-mes" value="'+_rhBen.pagMes+'"/></div></div>'
    +'<div class="fg"><label>Motivo *</label><textarea class="inp" id="rh-ben-ret-mot" rows="2" placeholder="Ex.: 3 dias de afastamento inseridos depois"></textarea></div>'
    +'<div class="ma"><button class="btn" onclick="rhBeneficioAbrirExtrato(\''+rhEsc(a.re)+'\')">Voltar</button>'
    +'<button class="btn btn-pri" onclick="rhBeneficioConfirmarRetroativoUI(\''+rhEsc(a.re)+'\')">Registrar</button></div></div></div>');
}
function rhBeneficioConfirmarRetroativoUI(re){
  var benef=(document.getElementById('rh-ben-ret-benef')||{}).value||'VR';
  var qtd=parseFloat((document.getElementById('rh-ben-ret-qtd')||{}).value);
  var mot=((document.getElementById('rh-ben-ret-mot')||{}).value||'').trim();
  var ano=parseInt((document.getElementById('rh-ben-ret-ano')||{}).value,10);
  var mes=parseInt((document.getElementById('rh-ben-ret-mes')||{}).value,10);
  if(!mot){ if(typeof progShowToast==='function') progShowToast('Motivo obrigatório.','erro'); return; }
  rhBeneficioRegistrarRetroativo(re, benef, qtd, mot, ano, mes);
}
function rhBeneficioTestarFase2B(){
  var results=[], ok=0, fail=0;
  function check(nome, cond, det){ results.push({teste:nome,ok:!!cond,detalhe:det}); if(cond) ok++; else fail++; }
  var a={direito_final_vt:40,direito_final_vr:22,pago_vt_qtd:40,pago_vr_qtd:22};
  check('A_conciliado', rhBeneficioStatusConciliacao(a)==='conciliado', rhBeneficioStatusConciliacao(a));
  a.pago_vr_qtd=27; check('B_credito_empresa', rhBeneficioStatusConciliacao(a)==='credito_empresa', rhBeneficioStatusConciliacao(a));
  a.pago_vr_qtd=20; a.pago_vt_qtd=40; check('C_credito_colab', rhBeneficioStatusConciliacao(a)==='credito_colaborador', rhBeneficioStatusConciliacao(a));
  var L=rhBeneficioCalcularLiquido(22, 5);
  check('D_comp_empresa', L.liquido_qtd===17 && L.credito_empresa_aplicado===5, L);
  var L2=rhBeneficioCalcularLiquido(22, -3);
  check('E_comp_colab', L2.liquido_qtd===25, L2);
  var L3=rhBeneficioCalcularLiquido(4, 6);
  check('F_emp_maior_direito', L3.liquido_qtd===0 && L3.saldo_empresa_restante===2, L3);
  var m1=rhBeneficioMontarMovimento({tipo_movimento:'credito_empresa',natureza:'credito',quantidade:5,valor_unitario:31.8,beneficio:'VR',competencia_ano:2026,competencia_mes:8,colaborador_id:'c1',vinculo_ref:'v1'});
  check('G_valor_original', m1.valor_total===159, m1.valor_total);
  _rhBen.movimentos=[
    Object.assign(m1,{origem_ref:'t1',criado_em:'2026-08-01'}),
    rhBeneficioMontarMovimento({tipo_movimento:'credito_empresa',natureza:'credito',quantidade:9,valor_unitario:31.8,beneficio:'VR',competencia_ano:2026,competencia_mes:8,colaborador_id:'c1',vinculo_ref:'v2',origem_ref:'t2'})
  ];
  var s1=rhBeneficioSaldoColaborador('c1','v1','VR',{ano:2026,mes:9});
  check('K_vinculo_isolado', s1.saldo_quantidade===5, s1);
  var sAmb=rhBeneficioSaldoColaborador('c1',null,'VR',{ano:2026,mes:9});
  check('K_sem_vinculo_nao_herda', sAmb.saldo_quantidade===0, sAmb);
  check('O_origem_ref', !!rhBeneficioEncontrarMovPorOrigem('t1'), 'found');
  _rhBen.movimentos.push(rhBeneficioMontarMovimento({
    tipo_movimento:'compensacao',natureza:'debito',quantidade:5,valor_unitario:31.8,
    beneficio:'VR',competencia_ano:2026,competencia_mes:9,colaborador_id:'c1',vinculo_ref:'v1',origem_ref:'t3'
  }));
  var sQ=rhBeneficioSaldoColaborador('c1','v1','VR',{ano:2026,mes:10});
  check('Q_saldo_zerado', Math.abs(sQ.saldo_quantidade)<0.0001, sQ);
  var sN=rhBeneficioSaldoColaborador('novo',null,'VR',{ano:2026,mes:9});
  check('N_sem_historico_zero', sN.saldo_quantidade===0 && sN.natureza==='zerado', sN);
  // —— Política PJ ——
  var perPj={ini:'2026-08-01', fim:'2026-08-31'};
  _rhBen.pagAno=2026; _rhBen.pagMes=9; _rhBen.movimentos=[];
  var pj={id:'pj1', ativo:true, eh_pj:true, re:'900', nome:'PJ Ativo', cargo_confianca:true, regime_beneficio:'dias_uteis'};
  var apj={id:'apj', colaborador_id:'pj1', re:'900', nome:'PJ', qtd_vt:44, qtd_vr:22, dias:[]};
  rhBeneficioFinalizarApuracao(apj, pj, perPj);
  check('PJ_A_ativo_zero', apj.direito_final_vt===0 && apj.direito_final_vr===0 && apj.liquido_vt_qtd===0 && apj.liquido_vr_qtd===0, apj);
  check('PJ_A_status', rhBeneficioStatusLabel(apj).indexOf('PJ')>=0, rhBeneficioStatusLabel(apj));
  check('PJ_C_cargo_confianca_ainda_zero', apj.direito_final_vr===0, apj.regra_apuracao);
  check('PJ_D_ehPj_sem_synergy', rhBeneficioEhPj({eh_pj:true})===true && rhBeneficioEhPj({vinculo:'pj'})===true, true);
  _rhBen.movimentos=[rhBeneficioMontarMovimento({
    colaborador_id:'pj1', vinculo_ref:'vpj', beneficio:'VR', tipo_movimento:'carga', natureza:'debito',
    quantidade:22, competencia_ano:2026, competencia_mes:8, origem_ref:'hist-pj'
  })];
  rhBeneficioAplicarContaCorrenteLinha(apj, pj);
  check('PJ_E_historico_revisar', apj.status==='revisar_pj' || !!apj._revisar_pj_mov, apj.status_saldo);
  var cltAnt={id:'c2', ativo:true, eh_pj:false, vinculo_ref:'v-clt', re:'901'};
  _rhBen.movimentos=[rhBeneficioMontarMovimento({
    colaborador_id:'c2', vinculo_ref:'v-clt', beneficio:'VR', tipo_movimento:'credito_empresa', natureza:'credito',
    quantidade:5, valor_unitario:31.8, competencia_ano:2026, competencia_mes:8, origem_ref:'clt-saldo'
  })];
  var pjNovo={id:'c2', ativo:true, eh_pj:true, vinculo_ref:'v-pj-novo', re:'901'};
  var aPjN={id:'a2', colaborador_id:'c2', re:'901', qtd_vt:10, qtd_vr:10, dias:[]};
  rhBeneficioFinalizarApuracao(aPjN, pjNovo, perPj);
  check('PJ_F_saldo_clt_nao_migra', aPjN.liquido_vr_qtd===0 && aPjN.saldo_anterior_vr_qtd===0, aPjN);
  var cltNovo={id:'c3', ativo:true, eh_pj:false, vinculo_ref:'v-clt-novo', re:'902'};
  _rhBen.movimentos=[rhBeneficioMontarMovimento({
    colaborador_id:'c3', vinculo_ref:'v-pj-old', beneficio:'VR', tipo_movimento:'credito_empresa', natureza:'credito',
    quantidade:7, valor_unitario:31.8, competencia_ano:2026, competencia_mes:8, origem_ref:'pj-old'
  })];
  var aClt={id:'a3', colaborador_id:'c3', re:'902', qtd_vt:20, qtd_vr:20, dias:[], status:'ok'};
  aClt.direito_final_vt=20; aClt.direito_final_vr=20; aClt.qtd_vt=20; aClt.qtd_vr=20;
  rhBeneficioAplicarContaCorrenteLinha(aClt, cltNovo);
  check('PJ_G_clt_nao_herda_pj', aClt.saldo_anterior_vr_qtd===0, aClt.saldo_anterior_vr_qtd);
  console.log('[RH Benefício Fase2B] ok='+ok+' fail='+fail, results);
  return {ok:ok, fail:fail, results:results};
}


// ── RH Benefícios VT/VR Fase 2C — pré-carga / lotes / operadoras / conciliação ──
// Registro ≠ conciliação. VT e VR separados. Sem API. Divergência não ajusta saldo.
function rhBen2cInitState(){
  if(!_rhBen.selecao) _rhBen.selecao={};
  if(!_rhBen.filtro2c) _rhBen.filtro2c={};
  if(!_rhBen.operadoras) _rhBen.operadoras=[];
  if(!_rhBen.lotes) _rhBen.lotes=[];
  if(!_rhBen.colabOps) _rhBen.colabOps=[];
  if(!_rhBen.importacoes) _rhBen.importacoes=[];
  if(!_rhBen.view) _rhBen.view='lista';
}
async function rhBen2cCarregarOperadoras(){
  rhBen2cInitState();
  if(DEMO){
    if(!(_rhBen.operadoras||[]).length){
      _rhBen.operadoras=[
        {id:'op-ticket', nome:'Ticket', tipo_beneficio:'VR', ativo:true, codigo_externo:'TICKET', api_disponivel:false},
        {id:'op-sptrans', nome:'SPTrans', tipo_beneficio:'VT', ativo:true, codigo_externo:'SPTRANS', api_disponivel:false}
      ];
    }
    return _rhBen.operadoras;
  }
  try{
    var fetchAll=typeof sbFetchAll==='function'?sbFetchAll:sbFetch;
    var rows=await fetchAll('rh_beneficio_operadoras',{order:'nome.asc'});
    _rhBen.operadoras=rows||[];
  }catch(e){
    console.warn('[RH Ben 2C] operadoras', e);
    _rhBen.operadoras=_rhBen.operadoras||[];
  }
  return _rhBen.operadoras;
}
async function rhBen2cCarregarColabOps(){
  if(DEMO){ _rhBen.colabOps=_rhBen.colabOps||[]; return _rhBen.colabOps; }
  try{
    var fetchAll=typeof sbFetchAll==='function'?sbFetchAll:sbFetch;
    _rhBen.colabOps=await fetchAll('rh_beneficio_colab_operadoras',{filters:['ativo=eq.true']})||[];
  }catch(_e){ _rhBen.colabOps=[]; }
  return _rhBen.colabOps;
}
function rhBen2cOpPorId(id){
  return (_rhBen.operadoras||[]).find(function(o){ return String(o.id)===String(id); })||null;
}
function rhBen2cOpsDoBenef(benef){
  benef=String(benef||'').toUpperCase();
  return (_rhBen.operadoras||[]).filter(function(o){
    if(o.ativo===false) return false;
    var t=String(o.tipo_beneficio||'MULTIPLO').toUpperCase();
    return t==='MULTIPLO' || t===benef;
  });
}
function rhBen2cOpPadraoColab(colaboradorId, benef){
  benef=String(benef).toUpperCase();
  var links=(_rhBen.colabOps||[]).filter(function(x){
    return String(x.colaborador_id)===String(colaboradorId)
      && String(x.beneficio).toUpperCase()===benef && x.ativo!==false;
  });
  if(links.length){
    links.sort(function(a,b){ return (b.principal?1:0)-(a.principal?1:0); });
    return rhBen2cOpPorId(links[0].operadora_id);
  }
  var ops=rhBen2cOpsDoBenef(benef);
  return ops[0]||null;
}
function rhBen2cLiquidoQtd(a, benef){
  benef=String(benef).toUpperCase();
  if(benef==='VT') return a.liquido_vt_qtd!=null?Number(a.liquido_vt_qtd):(Number(a.direito_final_vt)||0);
  return a.liquido_vr_qtd!=null?Number(a.liquido_vr_qtd):(Number(a.direito_final_vr)||0);
}
function rhBen2cPagoQtd(a, benef){
  benef=String(benef).toUpperCase();
  return benef==='VT'?(a.pago_vt_qtd!=null?Number(a.pago_vt_qtd):null):(a.pago_vr_qtd!=null?Number(a.pago_vr_qtd):null);
}
function rhBen2cComprovadaQtd(a, benef){
  benef=String(benef).toUpperCase();
  return benef==='VT'?(a.qtd_comprovada_vt!=null?Number(a.qtd_comprovada_vt):null):(a.qtd_comprovada_vr!=null?Number(a.qtd_comprovada_vr):null);
}
function rhBen2cElegibilidade(a, benef){
  benef=String(benef||'').toUpperCase();
  var c=rhBeneficioColabDaApuracao(a)||{};
  var out={ok:true, motivo:'', codigo:'', bloqueado:false};
  if(rhBeneficioEhPj(c) || a._eh_pj){
    return {ok:false, bloqueado:true, codigo:'pj', motivo:'PJ — SEM DIREITO A VT/VR'};
  }
  var dataCarga=rhBeneficioGarantirDataCarga();
  var vin=rhBeneficioValidarVinculoCarga(c, dataCarga);
  if(vin.status_vinculo_carga==='pre_admissao'){
    return {ok:false, bloqueado:true, codigo:'pre_admissao', motivo:vin.motivo_bloqueio||'Pré-admissão'};
  }
  if(vin.status_vinculo_carga==='bloqueado_desligado'){
    return {ok:false, bloqueado:true, codigo:'desligado', motivo:vin.motivo_bloqueio||'Inativo/dispensado na data da carga'};
  }
  if(vin.status_vinculo_carga==='revisar_vinculo'){
    return {ok:false, bloqueado:true, codigo:'vinculo', motivo:vin.motivo_bloqueio||'Vínculo não confiável'};
  }
  var ativoCad=!(c.ativo===false||c.ativo===0||c.ativo==='false');
  if(!ativoCad){
    return {ok:false, bloqueado:true, codigo:'inativo', motivo:'Colaborador inativo no CENA'};
  }
  var liq=rhBen2cLiquidoQtd(a, benef);
  if(!(liq>0)){
    return {ok:false, bloqueado:true, codigo:'sem_liquido', motivo:'Direito líquido '+benef+' ≤ 0'};
  }
  var st=benef==='VT'?a.status_vt:a.status_vr;
  if(st==='conciliado'){
    return {ok:false, bloqueado:true, codigo:'conciliado', motivo:benef+' já conciliado — não registrar novamente'};
  }
  var oref=rhBeneficioOrigemRefCarga((_rhBen&&_rhBen.pagAno)||0,(_rhBen&&_rhBen.pagMes)||0,a.colaborador_id,benef);
  var dup=typeof rhBeneficioEncontrarMovPorOrigem==='function'?rhBeneficioEncontrarMovPorOrigem(oref):null;
  if(dup && (st==='aguardando_comprovacao'||st==='registrado') && Math.abs((Number(dup.quantidade)||0)-liq)<0.0001){
    // já registrado — permite reabrir com justificativa, mas bloqueia seleção em massa silenciosa
    out.ok=true; out.codigo='ja_registrado'; out.motivo='Já há carga registrada — confirmar sobrescrita';
    out.jaRegistrado=true;
    return out;
  }
  return out;
}
function rhBen2cStatusBenef(a, benef){
  benef=String(benef).toUpperCase();
  var c=rhBeneficioColabDaApuracao(a)||{};
  if(rhBeneficioEhPj(c)||a._eh_pj) return 'bloqueado';
  var pago=rhBen2cPagoQtd(a, benef);
  var comp=rhBen2cComprovadaQtd(a, benef);
  var liq=rhBen2cLiquidoQtd(a, benef);
  if(comp!=null && pago!=null){
    if(Math.abs(comp-pago)<0.0001) return 'conciliado';
    return 'divergente';
  }
  if(pago!=null && pago>0){
    if(liq>0 && Math.abs(pago-liq)>0.0001 && pago<liq) return 'parcial';
    return 'aguardando_comprovacao';
  }
  var el=rhBen2cElegibilidade(a, benef);
  if(el.bloqueado && el.codigo!=='conciliado' && el.codigo!=='sem_liquido' && el.codigo!=='ja_registrado')
    return 'bloqueado';
  return 'nao_registrado';
}
function rhBen2cEnrichApuracao(a){
  if(!a) return a;
  a.status_vt=rhBen2cStatusBenef(a,'VT');
  a.status_vr=rhBen2cStatusBenef(a,'VR');
  var opVt=rhBen2cOpPadraoColab(a.colaborador_id,'VT');
  var opVr=rhBen2cOpPadraoColab(a.colaborador_id,'VR');
  if(opVt && !a.operadora_vt_id) a.operadora_vt_id=opVt.id;
  if(opVr && !a.operadora_vr_id) a.operadora_vr_id=opVr.id;
  a._op_vt_nome=opVt?(opVt.nome||''):(a.operadora_vt_id?(rhBen2cOpPorId(a.operadora_vt_id)||{}).nome:'');
  a._op_vr_nome=opVr?(opVr.nome||''):(a.operadora_vr_id?(rhBen2cOpPorId(a.operadora_vr_id)||{}).nome:'');
  a._sem_historico=!!(a._sem_historico_anterior || (typeof rhBeneficioEhSemHistoricoAnterior==='function' && rhBeneficioEhSemHistoricoAnterior(rhBeneficioColabDaApuracao(a)||{}, rhBeneficioPeriodoApuracao(_rhBen.pagAno,_rhBen.pagMes))));
  if(typeof rhBen2c1AplicarTratamentoNaApuracao==='function') rhBen2c1AplicarTratamentoNaApuracao(a);
  return a;
}
function rhBen2cStatusCor(st){
  st=String(st||'');
  if(st==='conciliado') return '#3B6D11';
  if(st==='aguardando_comprovacao'||st==='registrado'||st==='parcial') return '#185FA5';
  if(st==='divergente'||st==='bloqueado') return '#A32D2D';
  if(st==='nao_registrado') return '#888';
  return '#854F0B';
}
function rhBen2cStatusLabel(st){
  var m={
    nao_registrado:'Não registrado', parcial:'Parcial', registrado:'Registrado',
    aguardando_comprovacao:'Aguardando operadora', divergente:'Divergente',
    conciliado:'Conciliado', bloqueado:'Bloqueado'
  };
  return m[st]||st||'—';
}
function rhBen2cTooltipDivergencia(a, benef){
  benef=String(benef).toUpperCase();
  var pago=rhBen2cPagoQtd(a,benef);
  var comp=rhBen2cComprovadaQtd(a,benef);
  if(pago==null||comp==null) return '';
  var unit=rhBeneficioUnitarioBenef(a,benef);
  var dq=rhBeneficioRound2(comp-pago);
  var dv=rhBeneficioRound2(dq*unit);
  return 'CENA registrou '+pago+' '+benef+'. Operadora comprovou '+comp+'. Diferença: '+(dq>0?'+':'')+dq+' '+benef+' / R$ '+Math.abs(dv).toFixed(2).replace('.',',')+'.';
}
function rhBen2cKpisPrecarga(lista){
  var k={
    calcVt:0,calcVr:0,credVt:0,credVr:0,liqVt:0,liqVr:0,liqVtR:0,liqVrR:0,
    regVt:0,regVr:0,regVtR:0,regVrR:0,compVt:0,compVr:0,compVtR:0,compVrR:0,
    difVt:0,difVr:0,concVt:0,concVr:0,divVt:0,divVr:0,bloq:0,pj:0
  };
  (lista||[]).forEach(function(a){
    rhBen2cEnrichApuracao(a);
    var c=rhBeneficioColabDaApuracao(a)||{};
    if(rhBeneficioEhPj(c)||a._eh_pj){ k.pj++; return; }
    k.calcVt+=Number(a.direito_final_vt)||0;
    k.calcVr+=Number(a.direito_final_vr)||0;
    var sVt=Number(a.saldo_anterior_vt_qtd)||0, sVr=Number(a.saldo_anterior_vr_qtd)||0;
    if(sVt>0) k.credVt+=sVt; if(sVr>0) k.credVr+=sVr;
    var lVt=rhBen2cLiquidoQtd(a,'VT'), lVr=rhBen2cLiquidoQtd(a,'VR');
    k.liqVt+=lVt; k.liqVr+=lVr;
    k.liqVtR+=Number(a.liquido_vt_valor)||(lVt*(a.unitario_vt_snapshot||0));
    k.liqVrR+=Number(a.liquido_vr_valor)||(lVr*(a.unitario_vr_snapshot||0));
    var pVt=rhBen2cPagoQtd(a,'VT'), pVr=rhBen2cPagoQtd(a,'VR');
    if(pVt!=null){ k.regVt+=pVt; k.regVtR+=Number(a.pago_vt_valor)||0; }
    if(pVr!=null){ k.regVr+=pVr; k.regVrR+=Number(a.pago_vr_valor)||0; }
    var cVt=rhBen2cComprovadaQtd(a,'VT'), cVr=rhBen2cComprovadaQtd(a,'VR');
    if(cVt!=null){ k.compVt+=cVt; k.compVtR+=Number(a.valor_comprovado_vt)||0; }
    if(cVr!=null){ k.compVr+=cVr; k.compVrR+=Number(a.valor_comprovado_vr)||0; }
    if(pVt!=null&&cVt!=null) k.difVt+=rhBeneficioRound2(cVt-pVt);
    if(pVr!=null&&cVr!=null) k.difVr+=rhBeneficioRound2(cVr-pVr);
    if(a.status_vt==='conciliado') k.concVt++;
    if(a.status_vr==='conciliado') k.concVr++;
    if(a.status_vt==='divergente') k.divVt++;
    if(a.status_vr==='divergente') k.divVr++;
    if(a.status_vt==='bloqueado'||a.status_vr==='bloqueado') k.bloq++;
  });
  return k;
}
async function rhBen2cProximoCodigoLote(benef){
  benef=String(benef).toUpperCase();
  var ano=_rhBen.pagAno, mes=_rhBen.pagMes;
  var prefix=benef+'-'+ano+'-'+rhBeneficioPad2(mes)+'-';
  var n=1;
  if(!DEMO){
    try{
      var rows=await sbFetch('rh_beneficio_lotes',{
        filters:['competencia_ano=eq.'+ano,'competencia_mes=eq.'+mes,'beneficio=eq.'+benef],
        order:'criado_em.desc', limit:50
      })||[];
      rows.forEach(function(r){
        var m=String(r.codigo_lote||'').match(/-(\d+)$/);
        if(m) n=Math.max(n, parseInt(m[1],10)+1);
      });
    }catch(_e){}
  } else {
    (_rhBen.lotes||[]).forEach(function(r){
      if(String(r.beneficio)===benef){
        var m=String(r.codigo_lote||'').match(/-(\d+)$/);
        if(m) n=Math.max(n, parseInt(m[1],10)+1);
      }
    });
  }
  return prefix+String(n).padStart(3,'0');
}
async function rhBen2cRegistrarCargaBeneficio(re, benef, opts){
  opts=opts||{};
  benef=String(benef).toUpperCase();
  var a=(_rhBen.lista||[]).find(function(x){ return pontoReNorm(x.re)===pontoReNorm(re); });
  if(!a){ if(typeof progShowToast==='function') progShowToast('Apuração não encontrada.','erro'); return null; }
  var c=rhBeneficioColabDaApuracao(a)||{};
  var el=rhBen2cElegibilidade(a, benef);
  if(el.bloqueado && el.codigo!=='ja_registrado'){
    if(typeof progShowToast==='function') progShowToast(el.motivo||'Bloqueado.','erro');
    return null;
  }
  if(rhBeneficioCompFechada(_rhBen.competencia)){
    if(typeof progShowToast==='function') progShowToast('Competência fechada.','erro');
    return null;
  }
  var liq=rhBen2cLiquidoQtd(a, benef);
  var qtd=opts.quantidade!=null?Number(opts.quantidade):liq;
  var unit=opts.valor_unitario!=null?Number(opts.valor_unitario):rhBeneficioUnitarioBenef(a,benef);
  var valor=opts.valor_total!=null?Number(opts.valor_total):rhBeneficioRound2(qtd*unit);
  var just=String(opts.justificativa||'').trim();
  if(Math.abs(qtd-liq)>0.0001 || (opts.valor_unitario!=null && Math.abs(unit-rhBeneficioUnitarioBenef(a,benef))>0.0001)){
    if(!just){
      if(typeof progShowToast==='function') progShowToast('Alteração de quantidade/valor exige justificativa.','erro');
      return null;
    }
  }
  var opId=opts.operadora_id||(benef==='VT'?a.operadora_vt_id:a.operadora_vr_id)||(rhBen2cOpPadraoColab(a.colaborador_id,benef)||{}).id||null;
  var dataCarga=opts.data_carga||rhBeneficioGarantirDataCarga();
  var ano=_rhBen.pagAno, mes=_rhBen.pagMes;
  var vref=rhBeneficioVinculoRef(c)||a.vinculo_ref||null;
  var origem=opts.origem||'manual_individual';
  var origemRef=opts.origem_ref||rhBeneficioOrigemRefCarga(ano,mes,a.colaborador_id,benef);
  var prevMov=rhBeneficioEncontrarMovPorOrigem(origemRef);
  if(prevMov && !opts.forcarCorrecao){
    if(!opts.silenciosoJaExiste && typeof progShowToast==='function')
      progShowToast('Carga '+benef+' já registrada (origem_ref). Use correção/estorno controlado — sem duplicar.','erro');
    return {jaExiste:true, movimento:prevMov, apuracao:a, operadora_id:opId, quantidade:Number(prevMov.quantidade)||0, valor:Number(prevMov.valor_total)||0};
  }
  var mov=await rhBeneficioUpsertMovimento({
    colaborador_id:a.colaborador_id, vinculo_ref:vref,
    competencia_ano:ano, competencia_mes:mes, beneficio:benef,
    tipo_movimento:'carga', natureza:'debito',
    quantidade:qtd, valor_unitario:unit, valor_total:valor,
    origem:origem, origem_ref:origemRef,
    motivo:opts.observacao||('Carga '+benef+' registrada — Fase 2C'),
    payload:{
      fase:'2C', data_carga:dataCarga, operadora_id:opId,
      liquido_previsto:liq, justificativa:just||null,
      lote_id:opts.lote_id||null, lote_item_id:opts.lote_item_id||null,
      lote_codigo:opts.lote_codigo||null
    }
  });
  if(benef==='VT'){
    a.pago_vt_qtd=qtd; a.pago_vt_valor=valor; a.operadora_vt_id=opId;
    a.status_vt='aguardando_comprovacao';
  } else {
    a.pago_vr_qtd=qtd; a.pago_vr_valor=valor; a.operadora_vr_id=opId;
    a.status_vr='aguardando_comprovacao';
  }
  // Créditos vs direito (2B) — não confundir com conciliação da operadora
  await rhBeneficioGerarCreditosAposCarga(a, c, benef, qtd);
  a.status_conciliacao=rhBeneficioStatusConciliacao(a);
  rhBen2cEnrichApuracao(a);
  if(a.id && !DEMO && _rhBen.competencia && _rhBen.competencia.id){
    var patch={
      status_conciliacao:a.status_conciliacao,
      liquido_vt_qtd:a.liquido_vt_qtd, liquido_vr_qtd:a.liquido_vr_qtd,
      liquido_vt_valor:a.liquido_vt_valor, liquido_vr_valor:a.liquido_vr_valor,
      status_vt:a.status_vt, status_vr:a.status_vr
    };
    if(benef==='VT'){
      patch.pago_vt_qtd=a.pago_vt_qtd; patch.pago_vt_valor=a.pago_vt_valor; patch.operadora_vt_id=opId;
    } else {
      patch.pago_vr_qtd=a.pago_vr_qtd; patch.pago_vr_valor=a.pago_vr_valor; patch.operadora_vr_id=opId;
    }
    await sbUpdate('rh_beneficio_apuracoes', patch, 'id=eq.'+a.id);
  } else _rhBen.sujo=true;
  return {apuracao:a, movimento:mov, operadora_id:opId, quantidade:qtd, valor:valor};
}
function rhBen2cAbrirRegistrarIndividual(re, benef){
  benef=String(benef).toUpperCase();
  var a=(_rhBen.lista||[]).find(function(x){ return pontoReNorm(x.re)===pontoReNorm(re); });
  if(!a) return;
  rhBen2cEnrichApuracao(a);
  var el=rhBen2cElegibilidade(a, benef);
  if(el.bloqueado && el.codigo!=='ja_registrado'){
    if(typeof progShowToast==='function') progShowToast(el.motivo,'erro');
    return;
  }
  var liq=rhBen2cLiquidoQtd(a,benef);
  var unit=rhBeneficioUnitarioBenef(a,benef);
  var ops=rhBen2cOpsDoBenef(benef);
  var opSel=benef==='VT'?a.operadora_vt_id:a.operadora_vr_id;
  var opOpts=ops.map(function(o){
    return '<option value="'+rhEsc(o.id)+'"'+(String(o.id)===String(opSel)?' selected':'')+'>'+rhEsc(o.nome)+'</option>';
  }).join('');
  var orefExist=rhBeneficioOrigemRefCarga(_rhBen.pagAno,_rhBen.pagMes,a.colaborador_id,benef);
  var movExist=rhBeneficioEncontrarMovPorOrigem(orefExist);
  var avisoJa=movExist?'<div style="padding:8px;background:#FEF3E2;color:#854F0B;border-radius:8px;margin-bottom:8px;font-size:12px">Já existe carga registrada (qtd '+(movExist.quantidade||0)+'). Confirmar sobrescreve o mesmo origem_ref — não duplica movimento. Informe justificativa.</div>':'';
  setModal('<div class="modal-bg"><div class="modal" style="max-width:520px">'
    +'<h3>Registrar carga '+benef+'</h3>'
    +'<div style="font-size:12px;color:#666;margin-bottom:8px">'+rhEsc(a.nome)+' · RE '+rhEsc(a.re)
    +'<br/>Registro ≠ conciliação. Após confirmar: <b>Aguardando operadora</b>.</div>'
    +avisoJa
    +'<div class="g2">'
    +'<div class="fg"><label>Líquido previsto</label><input class="inp" disabled value="'+liq+'"/></div>'
    +'<div class="fg"><label>Valor unitário</label><input class="inp" type="number" step="0.01" id="rh2c-unit" value="'+unit+'"/></div>'
    +'<div class="fg"><label>Quantidade</label><input class="inp" type="number" min="0" step="1" id="rh2c-qtd" value="'+liq+'"/></div>'
    +'<div class="fg"><label>Valor total</label><input class="inp" type="number" step="0.01" id="rh2c-val" value="'+rhBeneficioRound2(liq*unit)+'"/></div>'
    +'<div class="fg"><label>Operadora</label><select class="inp" id="rh2c-op" data-nosort="1"><option value="">—</option>'+opOpts+'</select></div>'
    +'<div class="fg"><label>Data da carga</label><input class="inp" type="date" id="rh2c-data" value="'+rhEsc(rhBeneficioGarantirDataCarga())+'"/></div>'
    +'</div>'
    +'<div class="fg"><label>Observação</label><textarea class="inp" id="rh2c-obs" rows="2"></textarea></div>'
    +'<div class="fg"><label>Justificativa (se alterar qtd/valor)</label><textarea class="inp" id="rh2c-just" rows="2" placeholder="Obrigatória se diferente do líquido"></textarea></div>'
    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="rhBen2cConfirmarIndividualUI(\''+rhEsc(a.re)+'\',\''+benef+'\')">Confirmar registro</button></div></div></div>');
}
async function rhBen2cConfirmarIndividualUI(re, benef){
  var qtd=parseFloat((document.getElementById('rh2c-qtd')||{}).value);
  var unit=parseFloat((document.getElementById('rh2c-unit')||{}).value);
  var val=parseFloat((document.getElementById('rh2c-val')||{}).value);
  var op=(document.getElementById('rh2c-op')||{}).value||null;
  var data=(document.getElementById('rh2c-data')||{}).value||'';
  var obs=((document.getElementById('rh2c-obs')||{}).value||'').trim();
  var just=((document.getElementById('rh2c-just')||{}).value||'').trim();
  if(isNaN(qtd)||qtd<0){ if(typeof progShowToast==='function') progShowToast('Quantidade inválida.','erro'); return; }
  var orefChk=rhBeneficioOrigemRefCarga(_rhBen.pagAno,_rhBen.pagMes,(((_rhBen.lista||[]).find(function(x){return pontoReNorm(x.re)===pontoReNorm(re);})||{}).colaborador_id),benef);
  var ja=rhBeneficioEncontrarMovPorOrigem(orefChk);
  if(ja){
    if(!just){ if(typeof progShowToast==='function') progShowToast('Já registrado — informe justificativa para correção.','erro'); return; }
    if(!confirm('Já existe carga. Confirmar CORREÇÃO (mesmo origem_ref, sem duplicar)?')) return;
  } else if(!confirm('Confirmar registro de carga '+benef+' = '+qtd+'? (ainda NÃO é conciliação)')) return;
  var r=await rhBen2cRegistrarCargaBeneficio(re, benef, {
    quantidade:qtd, valor_unitario:unit, valor_total:isNaN(val)?null:val,
    operadora_id:op, data_carga:data, observacao:obs, justificativa:just,
    origem:'manual_individual', forcarCorrecao:!!ja
  });
  if(r){
    closeModal();
    if(typeof progShowToast==='function') progShowToast(benef+' registrado — aguardando comprovação da operadora.');
    rhBeneficioRender();
  }
}
function rhBen2cToggleSel(re, on){
  rhBen2cInitState();
  if(on) _rhBen.selecao[re]=true; else delete _rhBen.selecao[re];
}
function rhBen2cSelecionados(benef){
  benef=String(benef).toUpperCase();
  var out={ok:[], bloq:[], div:[], ja:[]};
  Object.keys(_rhBen.selecao||{}).forEach(function(re){
    if(!_rhBen.selecao[re]) return;
    var a=(_rhBen.lista||[]).find(function(x){ return pontoReNorm(x.re)===pontoReNorm(re); });
    if(!a) return;
    rhBen2cEnrichApuracao(a);
    var el=rhBen2cElegibilidade(a, benef);
    if(el.bloqueado && el.codigo!=='ja_registrado'){ out.bloq.push(a); return; }
    if(a['status_'+benef.toLowerCase()]==='divergente') out.div.push(a);
    if(el.jaRegistrado) out.ja.push(a);
    out.ok.push(a);
  });
  return out;
}
function rhBen2cAbrirMassa(benef){
  benef=String(benef).toUpperCase();
  var sel=rhBen2cSelecionados(benef);
  if(!sel.ok.length && !sel.bloq.length){
    if(typeof progShowToast==='function') progShowToast('Selecione colaboradores na pré-carga.','erro');
    return;
  }
  var valor=0, qtd=0;
  sel.ok.forEach(function(a){
    var l=rhBen2cLiquidoQtd(a,benef);
    qtd+=l;
    valor+=Number(benef==='VT'?a.liquido_vt_valor:a.liquido_vr_valor)||(l*rhBeneficioUnitarioBenef(a,benef));
  });
  setModal('<div class="modal-bg"><div class="modal" style="max-width:520px">'
    +'<h3>Registrar carga '+benef+' selecionados</h3>'
    +'<div style="font-size:13px;margin:8px 0">'
    +'<div>Quantidade selecionada: <b>'+sel.ok.length+'</b> colaboradores</div>'
    +'<div>Qtd total prevista: <b>'+rhBeneficioRound2(qtd)+'</b></div>'
    +'<div>Valor total previsto: <b>'+rhBeneficioFmtR(valor)+'</b></div>'
    +'<div style="color:#A32D2D">Bloqueados: <b>'+sel.bloq.length+'</b></div>'
    +'<div style="color:#854F0B">Divergentes: <b>'+sel.div.length+'</b></div>'
    +'<div style="color:#185FA5">Já registrados: <b>'+sel.ja.length+'</b></div>'
    +'</div>'
    +'<div style="font-size:11px;color:#666;margin-bottom:8px">VT e VR nunca no mesmo lote. Bloqueados não entram silenciosamente.</div>'
    +(sel.bloq.length?'<div class="ma" style="justify-content:flex-start">'
      +'<button class="btn btn-sm" onclick="rhBen2cRemoverBloqueadosMassa(\''+benef+'\')">Remover bloqueados da seleção</button></div>':'')
    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" '+(sel.ok.length?'':'disabled')+' onclick="rhBen2cConfirmarMassa(\''+benef+'\',false)">Confirmar lote ('+sel.ok.length+')</button></div></div></div>');
}
function rhBen2cRemoverBloqueadosMassa(benef){
  var sel=rhBen2cSelecionados(benef);
  sel.bloq.forEach(function(a){ delete _rhBen.selecao[a.re]; });
  rhBen2cAbrirMassa(benef);
  rhBeneficioRender();
}
async function rhBen2cConfirmarMassa(benef, forcarJa){
  benef=String(benef).toUpperCase();
  var sel=rhBen2cSelecionados(benef);
  if(sel.bloq.length){
    if(!confirm('Há '+sel.bloq.length+' bloqueados. Remover automaticamente e continuar só com elegíveis?')) return;
    sel.bloq.forEach(function(a){ delete _rhBen.selecao[a.re]; });
    sel=rhBen2cSelecionados(benef);
  }
  if(!sel.ok.length){ if(typeof progShowToast==='function') progShowToast('Nenhum elegível.','erro'); return; }
  if(!confirm('Confirmar registro em massa de '+benef+' para '+sel.ok.length+' colaboradores?')) return;
  closeModal();
  var codigo=await rhBen2cProximoCodigoLote(benef);
  var op0=rhBen2cOpPadraoColab(sel.ok[0].colaborador_id,benef);
  var qtdTot=0, valTot=0, itens=[], okN=0, failN=0, skipN=0;
  for(var i=0;i<sel.ok.length;i++){
    var a=sel.ok[i];
    var liq=rhBen2cLiquidoQtd(a,benef);
    var unit=rhBeneficioUnitarioBenef(a,benef);
    var valor=rhBeneficioRound2(liq*unit);
    var r=await rhBen2cRegistrarCargaBeneficio(a.re, benef, {
      quantidade:liq, valor_unitario:unit, valor_total:valor,
      origem:'manual_lote',
      origem_ref:rhBeneficioOrigemRefCarga(_rhBen.pagAno,_rhBen.pagMes,a.colaborador_id,benef),
      observacao:'Lote '+codigo,
      lote_codigo:codigo,
      silenciosoJaExiste:true
    });
    if(r && r.jaExiste){ skipN++; continue; }
    if(r){
      okN++; qtdTot+=liq; valTot+=valor;
      itens.push({
        colaborador_id:a.colaborador_id, vinculo_ref:a.vinculo_ref||null,
        re:a.re, nome:a.nome, beneficio:benef,
        quantidade_prevista:liq, valor_previsto:valor,
        quantidade_registrada:liq, valor_registrado:valor, valor_unitario:unit,
        operadora_id:r.operadora_id, status:'aguardando_comprovacao',
        movimento_carga_id:r.movimento?(r.movimento.id||null):null
      });
    } else failN++;
  }
  var lote={
    id:typeof gerarUUID==='function'?gerarUUID():('lote'+Date.now()),
    codigo_lote:codigo,
    competencia_ano:_rhBen.pagAno, competencia_mes:_rhBen.pagMes,
    beneficio:benef, operadora_id:op0?op0.id:null,
    data_carga:rhBeneficioGarantirDataCarga(),
    quantidade_colaboradores:okN,
    quantidade_total:qtdTot, valor_total:rhBeneficioRound2(valTot),
    status:'aguardando_comprovacao',
    criado_em:new Date().toISOString(), criado_por:rhBeneficioUsuario(),
    registrado_em:new Date().toISOString(),
    observacao:'Registro em massa Fase 2C'
  };
  if(!DEMO){
    var insL=await sbInsert('rh_beneficio_lotes', lote, {silent:true});
    if(insL&&insL[0]) lote=insL[0];
    itens.forEach(function(it){ it.lote_id=lote.id; });
    await rhBeneficioInsertLote('rh_beneficio_lote_itens', itens);
  } else {
    itens.forEach(function(it){ it.lote_id=lote.id; it.id='li'+Math.random(); });
    lote._itens=itens;
  }
  _rhBen.lotes=(_rhBen.lotes||[]).concat([lote]);
  _rhBen.selecao={};
  if(typeof progShowToast==='function')
    progShowToast('Lote '+codigo+': '+okN+' ok'+(skipN?', '+skipN+' já registrados':'')+(failN?', '+failN+' falha':'')+' — aguardando operadora.');
  rhBeneficioRender();
}

