    +rhCard('Div. pendentes',fin.pendVr,fin.pendVr?'#854F0B':'#3B6D11')+rhCard('Div. reconhecidas',fin.recVr,'#185FA5')
    +rhCard('A maior R$',rhBeneficioFmtR(fin.vrMaiorR),fin.vrMaiorR?'#A32D2D':'#3B6D11')
    +rhCard('A menor R$',rhBeneficioFmtR(fin.vrMenorR),fin.vrMenorR?'#854F0B':'#3B6D11')
    +'</div><div style="font-size:11px;color:#888;margin-top:6px">Valor líquido '+rhBeneficioFmtR(k.liqVrR)+' · registrado '+rhBeneficioFmtR(k.regVrR)+' · a maior/a menor separados</div></div>'
    +'<div class="card" style="padding:12px"><div style="font-weight:800;margin-bottom:8px;color:#185FA5">VT</div>'
    +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:6px">'
    +rhCard('Calculado',k.calcVt)+rhCard('Créd. ant.',k.credVt)+rhCard('Líquido',k.liqVt,'#3B6D11')
    +rhCard('Registrado',k.regVt,'#185FA5')+rhCard('Comprovado',k.compVt,'#185FA5')
    +rhCard('Conciliados',k.concVt,'#3B6D11')+rhCard('Divergentes',k.divVt,k.divVt?'#A32D2D':'#3B6D11')
    +rhCard('Div. pendentes',fin.pendVt,fin.pendVt?'#854F0B':'#3B6D11')+rhCard('Div. reconhecidas',fin.recVt,'#185FA5')
    +rhCard('A maior R$',rhBeneficioFmtR(fin.vtMaiorR),fin.vtMaiorR?'#A32D2D':'#3B6D11')
    +rhCard('A menor R$',rhBeneficioFmtR(fin.vtMenorR),fin.vtMenorR?'#854F0B':'#3B6D11')
    +'</div><div style="font-size:11px;color:#888;margin-top:6px">Valor líquido '+rhBeneficioFmtR(k.liqVtR)+' · registrado '+rhBeneficioFmtR(k.regVtR)+' · a maior/a menor separados</div></div>'
    +'</div>'
    +'<div class="card" style="padding:10px;margin-bottom:10px">'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:end">'
