// ══════════════════════════════════════════════════════════════
// RH C1.2 — Pisos, benefícios e cláusulas CLT
// Catálogo por cargo/função. Snapshot no processo (remuneracao jsonb).
// Não efetiva colaboradores nem folha.
// ══════════════════════════════════════════════════════════════
var _rhRemParams=[], _rhRemPisos=[], _rhRemBenefs=[], _rhRemCarregado=false, _rhRemDisponivel=true, _rhRemErro='';
var RH_REM_BENEF_TIPOS=[
  {id:'vale_transporte', label:'Vale-transporte', regra:'vt_lei_7418', lei:'Lei 7.418/85 — desconto do empregado limitado a 6% do salário'},
  {id:'vale_refeicao', label:'Vale-refeição', regra:'pat_valor_dia', lei:'PAT — em regra não integra o salário se enquadrado'},
  {id:'vale_alimentacao', label:'Vale-alimentação', regra:'pat_valor_dia', lei:'PAT — em regra não integra o salário se enquadrado'},
  {id:'plano_saude', label:'Plano de saúde', regra:'valor_fixo', lei:'Conferir CCT; habitualidade pode ter natureza salarial'},
  {id:'plano_odontologico', label:'Plano odontológico', regra:'valor_fixo', lei:'Conferir CCT'},
  {id:'seguro_vida', label:'Seguro de vida', regra:'valor_fixo', lei:'Em regra não salarial se exclusivo de risco'},
  {id:'cesta_basica', label:'Cesta básica', regra:'valor_fixo', lei:'Conferir CCT / PAT'}
];
function rhRemSqlHint(){ return 'Aplique sql_rh_remuneracao_c12.sql no SQL Editor do Supabase. O ERP não aplica SQL sozinho.'; }
function rhRemNum(v, d){ var n=parseFloat(v); return isFinite(n)?n:(d||0); }
function rhRemRound(n){ return Math.round((Number(n)||0)*100)/100; }
function rhRemParamsAtivos(){
  var lista=(_rhRemParams||[]).filter(function(p){return p.ativo!==false;}).slice().sort(function(a,b){return String(b.vigencia_inicio||'').localeCompare(String(a.vigencia_inicio||''));});
  return lista[0]||{
    salario_minimo:1621, salario_minimo_diario:54.04, salario_minimo_hora:7.37,
    adicional_noturno_pct:20, hora_noturna_minutos:52.5, periculosidade_pct:30,
    insalubridade_min_pct:10, insalubridade_med_pct:20, insalubridade_max_pct:40,
    vt_desconto_max_pct:6, cargo_confianca_diferencial_pct:40, carga_mensal_padrao:220,
    fonte:'Decreto 12.797/2025 (padrão local — cadastre em Pisos e Benefícios)', vigencia_inicio:'2026-01-01'
  };
}
function rhRemCarregar(){
  if(_rhRemCarregado) return Promise.resolve();
  if(DEMO){ _rhRemCarregado=true; _rhRemDisponivel=true; return Promise.resolve(); }
  return sbFetch('rh_parametros_legais',{select:'id',limit:1}).then(function(probe){
    if(probe===null){
      _rhRemCarregado=true; _rhRemDisponivel=false; _rhRemErro=rhRemSqlHint();
      _rhRemParams=[]; _rhRemPisos=[]; _rhRemBenefs=[];
      return;
    }
    var fetchAll=typeof sbFetchAll==='function'?sbFetchAll:sbFetch;
    return Promise.all([
      fetchAll('rh_parametros_legais',{order:'vigencia_inicio.desc'}),
      fetchAll('rh_remuneracao_pisos',{order:'cargo.asc'}),
      fetchAll('rh_remuneracao_piso_beneficios',{order:'tipo.asc'})
    ]).then(function(res){
      _rhRemCarregado=true; _rhRemDisponivel=true; _rhRemErro='';
      _rhRemParams=res[0]||[]; _rhRemPisos=res[1]||[]; _rhRemBenefs=res[2]||[];
    });
  }).catch(function(){
    _rhRemCarregado=true; _rhRemDisponivel=false; _rhRemErro=rhRemSqlHint();
  });
}
function rhRemReset(){ _rhRemCarregado=false; return rhRemCarregar(); }
function rhRemBenefsDoPiso(pisoId){
  return (_rhRemBenefs||[]).filter(function(b){return String(b.piso_id)===String(pisoId) && b.ativo!==false;});
}
async function rhRemAplicarVrPadraoTodos(){
  var valor=RH_BEN_VR_VALOR_PADRAO;
  if(typeof rhRemCarregar==='function') await rhRemCarregar();
  var pisos=(_rhRemPisos||[]).filter(function(p){ return p.ativo!==false; });
  if(!pisos.length){
    if(typeof progShowToast==='function') progShowToast('Nenhum piso cadastrado em RH → Pisos e Benefícios.','erro');
    return;
  }
  var ok=0, falha=0;
  for(var i=0;i<pisos.length;i++){
    var p=pisos[i];
    var exist=(_rhRemBenefs||[]).find(function(b){ return String(b.piso_id)===String(p.id) && b.tipo==='vale_refeicao'; });
    var payload={piso_id:p.id, tipo:'vale_refeicao', regra:'pat_valor_dia', valor:valor, percentual:null, dias_mes:22, ativo:true};
    if(DEMO){
      if(exist) Object.assign(exist, payload);
      else _rhRemBenefs.push(Object.assign({id:'bvr'+Date.now()+i}, payload));
      ok++;
      continue;
    }
    if(exist && exist.id){
      var up=await sbUpdate('rh_remuneracao_piso_beneficios', payload, 'id=eq.'+exist.id);
      if(up) ok++; else falha++;
    } else {
      var ins=await sbInsert('rh_remuneracao_piso_beneficios', payload);
      if(ins && ins[0]) ok++; else falha++;
    }
  }
  if(!DEMO && typeof rhRemReset==='function') await rhRemReset();
  rhBeneficioAplicarEstimativas(_rhBen.lista||[]);
  rhBeneficioRender();
  if(typeof progShowToast==='function'){
    progShowToast(falha
      ?('VR aplicado em '+ok+' piso(s); '+falha+' falha(s).')
      :('VR R$ '+valor.toFixed(2).replace('.',',')+' cadastrado em '+ok+' piso(s). Recalcule a apuração se necessário.'));
  }
}

/**
 * Cadastra VT unitário R$ 7,50 (pat_valor_dia) para todos os cargos
 * dos colaboradores do PLPT Teresina — em pisos com contrato_id = PLPT
 * (não altera pisos de outros contratos).
 */
async function rhRemAplicarVtPlpt750(){
  var cid=(typeof CONTRATOS_UUID_MAP!=='undefined' && CONTRATOS_UUID_MAP.PLPT) || '430df4d5-6d0a-459f-ae82-92546ff9e57f';
  var valor=Number(RH_BEN_VT_VALOR_PLPT)||7.5;
  if(!confirm('Cadastrar VT unitário R$ '+valor.toFixed(2).replace('.', ',')+' (por ticket) nos pisos do contrato PLPT Teresina?\n\nIsso cobre todos os cargos dos colaboradores desse contrato. Não altera outros contratos.')) return;

  if(typeof rhRemCarregar==='function') await rhRemCarregar();
  if(!_rhRemDisponivel && !DEMO){
    progShowToast(_rhRemErro||'Pisos/benefícios indisponíveis. Aplique o SQL de remuneração.','erro');
    return;
  }

  var par=typeof rhRemParamsAtivos==='function'?rhRemParamsAtivos():{};
  var sm=typeof rhRemNum==='function'?rhRemNum(par.salario_minimo,1621):1621;
  var contNome='PLPT TERESINA';
  try{
    var ct=(contratos||[]).find(function(c){ return String(c.id)===String(cid); });
    if(ct) contNome=ct.nome||ct.codigo||contNome;
  }catch(e){}

  var roster=(colaboradores||[]).filter(function(c){
    if(!c || String(c.contrato_id||'')!==String(cid)) return false;
    if(c.ativo===false) return false;
    return !!String(c.cargo||'').trim();
  });
  if(!roster.length){
    progShowToast('Nenhum colaborador ativo encontrado no contrato PLPT Teresina.','erro');
    return;
  }

  // Cargos distintos (função vazia no piso = vale para todas as funções do cargo)
  var cargosMap={};
  roster.forEach(function(c){
    var cargo=String(c.cargo||'').trim();
    if(!cargo) return;
    var key=typeof rhNormTxt==='function'?rhNormTxt(cargo):cargo.toLowerCase();
    if(!cargosMap[key]) cargosMap[key]={cargo:cargo, count:0};
    cargosMap[key].count++;
  });
  var cargos=Object.keys(cargosMap).map(function(k){ return cargosMap[k]; });

  var criados=0, atualizados=0, falha=0, colabs=roster.length;

  for(var i=0;i<cargos.length;i++){
    var cargo=cargos[i].cargo;
    var pisoPlpt=(_rhRemPisos||[]).find(function(p){
      return p.ativo!==false
        && String(p.contrato_id||'')===String(cid)
        && (typeof rhNormTxt==='function'?rhNormTxt(p.cargo)===rhNormTxt(cargo):String(p.cargo||'')===cargo)
        && !String(p.funcao||'').trim();
    });
    if(!pisoPlpt){
      // Qualquer piso do mesmo cargo no contrato (mesmo com função)
      pisoPlpt=(_rhRemPisos||[]).find(function(p){
        return p.ativo!==false
          && String(p.contrato_id||'')===String(cid)
          && (typeof rhNormTxt==='function'?rhNormTxt(p.cargo)===rhNormTxt(cargo):String(p.cargo||'')===cargo);
      });
    }
    if(!pisoPlpt){
      var base=(_rhRemPisos||[]).find(function(p){
        return p.ativo!==false
          && (typeof rhNormTxt==='function'?rhNormTxt(p.cargo)===rhNormTxt(cargo):String(p.cargo||'')===cargo);
      });
      var pisoVal=base && base.piso!=null ? Number(base.piso) : sm;
      if(!(pisoVal>0)) pisoVal=sm;
      if(pisoVal<sm) pisoVal=sm;
      var cargoObj=(_cad_cargos||[]).find(function(c){ return String(c.nome||'')===cargo; });
      var novoPayload={
        cargo:cargo,
        cargo_id:cargoObj?cargoObj.id:null,
        funcao:null,
        contrato_id:cid,
        contrato_nome:contNome,
        piso:pisoVal,
        carga_horaria_mensal:(base&&base.carga_horaria_mensal)||220,
        jornada_padrao:(base&&base.jornada_padrao)||'diurna',
        periculosidade_padrao:!!(base&&base.periculosidade_padrao),
        insalubridade_grau:(base&&base.insalubridade_grau)||'',
        cargo_confianca_padrao:!!(base&&base.cargo_confianca_padrao),
        observacao:'VT PLPT R$ 7,50 — cadastro automático',
        ativo:true,
        criado_por:usuarioLogado?(usuarioLogado.nome||usuarioLogado.email):'sistema'
      };
      if(DEMO){
        pisoPlpt=Object.assign({id:'piso_plpt_'+Date.now()+'_'+i}, novoPayload);
        _rhRemPisos.unshift(pisoPlpt);
        criados++;
      } else {
        var insP=await sbInsert('rh_remuneracao_pisos', novoPayload);
        pisoPlpt=insP&&insP[0];
        if(!pisoPlpt){ falha++; continue; }
        _rhRemPisos.unshift(pisoPlpt);
        criados++;
      }
    }

    var exist=(_rhRemBenefs||[]).find(function(b){
      return String(b.piso_id)===String(pisoPlpt.id) && b.tipo==='vale_transporte';
    });
    var benPayload={
      piso_id:pisoPlpt.id,
      tipo:'vale_transporte',
      regra:'pat_valor_dia',
      valor:valor,
      percentual:null,
      dias_mes:22,
      ativo:true,
      observacao:'VT unitário PLPT Teresina R$ 7,50'
    };
    if(DEMO){
      if(exist) Object.assign(exist, benPayload);
      else _rhRemBenefs.push(Object.assign({id:'bvt'+Date.now()+i}, benPayload));
      atualizados++;
      continue;
    }
    if(exist && exist.id){
      var up=await sbUpdate('rh_remuneracao_piso_beneficios', benPayload, 'id=eq.'+exist.id);
      if(up) atualizados++; else falha++;
    } else {
      var insB=await sbInsert('rh_remuneracao_piso_beneficios', benPayload);
      if(insB && insB[0]){
        _rhRemBenefs.push(insB[0]);
        atualizados++;
      } else falha++;
    }
  }

  if(!DEMO && typeof rhRemReset==='function') await rhRemReset();
  if(typeof rhBeneficioAplicarEstimativas==='function') rhBeneficioAplicarEstimativas(_rhBen.lista||[]);
  if(typeof rhBeneficioRender==='function') rhBeneficioRender();

  var msg='VT R$ '+valor.toFixed(2).replace('.', ',')+' no PLPT: '
    +colabs+' colaborador(es), '+cargos.length+' cargo(s), '
    +atualizados+' benefício(s) VT, '+criados+' piso(s) criado(s)'
    +(falha?'; '+falha+' falha(s)':'')
    +'. Selecione o contrato PLPT e recalcule a apuração.';
  progShowToast(msg, falha?'erro':'ok');
  try{
    if(typeof auditLog==='function'){
      auditLog('APLICOU_VT_PLPT','rh_beneficio',msg,{
        contrato_id:cid, valor:valor, colaboradores:colabs, cargos:cargos.length, beneficios:atualizados, pisos_criados:criados
      });
    }
  }catch(e){}
}
function rhRemMatchPiso(cargo, funcao, contratoId){
  cargo=String(cargo||'').trim(); funcao=String(funcao||'').trim();
  var cid=String(contratoId||'');
  var ativos=(_rhRemPisos||[]).filter(function(p){return p.ativo!==false && rhNormTxt(p.cargo)===rhNormTxt(cargo);});
  function score(p){
    var s=0;
    var pf=String(p.funcao||'').trim();
    if(pf && rhNormTxt(pf)===rhNormTxt(funcao)) s+=20;
    else if(!pf) s+=5;
    else return -1;
    if(p.contrato_id && String(p.contrato_id)===cid) s+=10;
    else if(!p.contrato_id) s+=2;
    else return -1;
    return s;
  }
  var best=null, bestS=-1;
  ativos.forEach(function(p){ var sc=score(p); if(sc>bestS){ bestS=sc; best=p; } });
  return best;
}
function rhRemInsalPct(grau, par){
  grau=String(grau||'');
  if(grau==='minimo') return rhRemNum(par.insalubridade_min_pct,10);
  if(grau==='medio') return rhRemNum(par.insalubridade_med_pct,20);
  if(grau==='maximo') return rhRemNum(par.insalubridade_max_pct,40);
  return 0;
}
function rhRemCalc(st){
  st=st||{};
  var par=rhRemParamsAtivos();
  var sm=rhRemNum(par.salario_minimo,1621);
  var piso=rhRemNum(st.piso_base,0);
  var salario=rhRemNum(st.salario_proposto, piso||sm);
  var avisos=[];
  if(salario<sm){ salario=sm; avisos.push('Salário elevado ao mínimo nacional (CLT art. 7º IV / Decreto 12.797/2025).'); }
  if(piso && salario<piso){ salario=piso; avisos.push('Salário elevado ao piso do cargo/função.'); }
  var carga=rhRemNum(st.carga_horaria_mensal, rhRemNum(par.carga_mensal_padrao,220))||220;
  var valorHora=carga?salario/carga:0;
  var pericOn=!!st.periculosidade, grau=String(st.insalubridade_grau||'');
  var pericPct=rhRemNum(par.periculosidade_pct,30);
  var pericValor=pericOn?rhRemRound(salario*(pericPct/100)):0;
  var insalPct=rhRemInsalPct(grau, par);
  var insalValor=insalPct?rhRemRound(sm*(insalPct/100)):0;
  var clausulaEscolhida='';
  var adicionalInsalPeric=0;
  if(pericValor && insalValor){
    avisos.push('CLT art. 193 §2º: periculosidade e insalubridade não acumulam. Aplicado o de maior valor.');
    if(pericValor>=insalValor){ adicionalInsalPeric=pericValor; clausulaEscolhida='periculosidade'; }
    else { adicionalInsalPeric=insalValor; clausulaEscolhida='insalubridade'; }
  } else if(pericValor){ adicionalInsalPeric=pericValor; clausulaEscolhida='periculosidade'; }
  else if(insalValor){ adicionalInsalPeric=insalValor; clausulaEscolhida='insalubridade'; }
  var noturnoOn=!!st.periodo_noturno || st.jornada==='noturna' || st.jornada==='mista';
  var notPct=rhRemNum(st.adicional_noturno_pct, rhRemNum(par.adicional_noturno_pct,20));
  var minNot=rhRemNum(par.hora_noturna_minutos,52.5)||52.5;
  var fator=60/minNot;
  var horasNot=rhRemNum(st.horas_noturnas_mes,0);
  if(noturnoOn && !horasNot){
    if(st.jornada==='noturna') horasNot=rhRemRound(carga*7/8);
    else if(st.jornada==='mista') horasNot=rhRemRound(carga*0.4);
  }
  var noturnoValor=0;
  if(noturnoOn && horasNot>0){
    noturnoValor=rhRemRound(valorHora*horasNot*fator*(notPct/100));
  }
  var confianca=!!st.cargo_confianca;
  var difPct=rhRemNum(par.cargo_confianca_diferencial_pct,40);
  var pisoConf=piso?rhRemRound(piso*(1+difPct/100)):0;
  if(confianca){
    avisos.push('Cargo de confiança (CLT art. 62 II): em regra sem horas extras. Conferir fidúcia e CCT.');
    if(pisoConf && salario<pisoConf) avisos.push('Salário abaixo de '+difPct+'% sobre o piso do cargo — conferir padrão da categoria (não é regra universal fora de casos específicos).');
  }
  var bens=Array.isArray(st.beneficios)?st.beneficios:[];
  var vtCusto=0, vtDesc=0, patEmpresa=0, outros=0;
  bens.forEach(function(b){
    if(!b || b.ativo===false) return;
    var regra=b.regra||'valor_fixo';
    var val=rhRemNum(b.valor,0);
    var dias=rhRemNum(b.dias_mes,22);
    var mensal=val;
    if(regra==='pat_valor_dia') mensal=rhRemRound(val*dias);
    if(regra==='percentual_piso') mensal=rhRemRound(salario*(rhRemNum(b.percentual,0)/100));
    b.valor_mensal=mensal;
    if(b.tipo==='vale_transporte' || regra==='vt_lei_7418'){
      vtCusto+=mensal;
    } else if(regra==='pat_valor_dia' || b.tipo==='vale_refeicao' || b.tipo==='vale_alimentacao'){
      patEmpresa+=mensal;
    } else outros+=mensal;
  });
  var vtTeto=rhRemRound(salario*(rhRemNum(par.vt_desconto_max_pct,6)/100));
  vtDesc=Math.min(vtCusto, vtTeto);
  var vtEmpresa=rhRemRound(Math.max(0, vtCusto-vtDesc));
  var adicionais=rhRemRound(adicionalInsalPeric+noturnoValor);
  var remuneracaoDireta=rhRemRound(salario+adicionais);
  return {
    salario_minimo:sm, piso_base:piso, salario:rhRemRound(salario), carga:carga, valor_hora:rhRemRound(valorHora),
    periculosidade:pericOn, periculosidade_pct:pericPct, periculosidade_valor:pericValor,
    insalubridade_grau:grau, insalubridade_pct:insalPct, insalubridade_valor:insalValor,
    clausula_aplicada:clausulaEscolhida, adicional_insal_peric:adicionalInsalPeric,
    periodo_noturno:noturnoOn, adicional_noturno_pct:notPct, hora_noturna_minutos:minNot,
    fator_hora_noturna:rhRemRound(fator), horas_noturnas_mes:horasNot, adicional_noturno_valor:noturnoValor,
    cargo_confianca:confianca, cargo_confianca_piso_sugerido:pisoConf,
    vt_custo:rhRemRound(vtCusto), vt_desconto_colaborador:vtDesc, vt_custo_empresa:vtEmpresa,
    beneficios_pat:rhRemRound(patEmpresa), beneficios_outros:rhRemRound(outros),
    adicionais:adicionais, remuneracao_direta:remuneracaoDireta,
    custo_empresa_estimado:rhRemRound(remuneracaoDireta+patEmpresa+outros+vtEmpresa),
    avisos:avisos, beneficios:bens, fonte:par.fonte||'', par:par
  };
}
function rhRemStateFromForm(){
  if(!_rhCtAtual) return {};
  var g=function(id){ var e=document.getElementById(id); if(!e) return ''; return String(e.value||'').trim(); };
  var chk=function(id){ var e=document.getElementById(id); return !!(e&&e.checked); };
  var piso=rhRemMatchPiso(rhCtVal('cargo')||_rhCtAtual.cargo, rhCtVal('funcao')||_rhCtAtual.funcao, rhCtVal('contrato_id')||_rhCtAtual.contrato_id);
  var jornada=g('rh-rem-jornada')||(piso&&piso.jornada_padrao)||'diurna';
  var noturno=jornada==='noturna'||jornada==='mista'||chk('rh-rem-noturno');
  var bens=[];
  RH_REM_BENEF_TIPOS.forEach(function(t){
    if(!chk('rh-rem-b-'+t.id)) return;
    bens.push({
      tipo:t.id, regra:g('rh-rem-br-'+t.id)||t.regra, valor:rhRemNum(g('rh-rem-bv-'+t.id),0),
      percentual:rhRemNum(g('rh-rem-bp-'+t.id),0), dias_mes:rhRemNum(g('rh-rem-bd-'+t.id),22)||22, ativo:true
    });
  });
  return {
    piso_id:piso?piso.id:null, piso_base:piso?rhRemNum(piso.piso,0):rhRemNum(g('rh-rem-piso'),0),
    salario_proposto:rhRemNum(g('rh-rem-salario'),0),
    carga_horaria_mensal:rhRemNum(g('rh-rem-carga'), piso?piso.carga_horaria_mensal:220),
    jornada:jornada, periodo_noturno:noturno,
    adicional_noturno_pct:rhRemNum(g('rh-rem-noturno-pct'),20),
    horas_noturnas_mes:rhRemNum(g('rh-rem-horas-not'),0),
    periculosidade:chk('rh-rem-peric'),
    insalubridade_grau:g('rh-rem-insal')||'',
    cargo_confianca:chk('rh-rem-confianca'),
    beneficios:bens
  };
}
function rhRemDefaultsFromPiso(){
  var piso=rhRemMatchPiso(rhCtVal('cargo')||(_rhCtAtual&&_rhCtAtual.cargo), rhCtVal('funcao')||(_rhCtAtual&&_rhCtAtual.funcao), rhCtVal('contrato_id')||(_rhCtAtual&&_rhCtAtual.contrato_id));
  var prev=(_rhCtAtual&&_rhCtAtual.remuneracao)||{};
  if(typeof prev==='string'){ try{prev=JSON.parse(prev);}catch(e){prev={};} }
  var elet=typeof rhCtBool==='function'&&rhCtBool('trabalho_eletricidade');
  var st={
    piso_id:piso?piso.id:null,
    piso_base:piso?rhRemNum(piso.piso,0):rhRemNum(prev.piso_base,0),
    salario_proposto:rhRemNum(prev.salario_proposto, piso?piso.piso:0),
    carga_horaria_mensal:rhRemNum(prev.carga_horaria_mensal, piso?piso.carga_horaria_mensal:220),
    jornada:prev.jornada||(piso&&piso.jornada_padrao)||'diurna',
    periodo_noturno:prev.periodo_noturno!=null?!!prev.periodo_noturno:((piso&&piso.jornada_padrao)==='noturna'||(piso&&piso.jornada_padrao)==='mista'),
    adicional_noturno_pct:rhRemNum(prev.adicional_noturno_pct, rhRemParamsAtivos().adicional_noturno_pct),
    horas_noturnas_mes:rhRemNum(prev.horas_noturnas_mes,0),
    periculosidade:prev.periculosidade!=null?!!prev.periculosidade:!!((piso&&piso.periculosidade_padrao)||elet),
    insalubridade_grau:prev.insalubridade_grau!=null?prev.insalubridade_grau:(piso?piso.insalubridade_grau:''),
    cargo_confianca:prev.cargo_confianca!=null?!!prev.cargo_confianca:!!(piso&&piso.cargo_confianca_padrao),
    beneficios:Array.isArray(prev.beneficios)&&prev.beneficios.length?prev.beneficios:(piso?rhRemBenefsDoPiso(piso.id).map(function(b){
      return {tipo:b.tipo, regra:b.regra, valor:b.valor, percentual:b.percentual, dias_mes:b.dias_mes||22, ativo:true};
    }):[])
  };
  return st;
}
function rhRemAplicarSnapshot(st, calc){
  if(!_rhCtAtual) return;
  var prevRem=_rhCtAtual.remuneracao; if(typeof prevRem==='string'){ try{prevRem=JSON.parse(prevRem);}catch(e){prevRem={};} }
  var keep=(prevRem&&prevRem.preenchimento_contrato)||_rhCtAtual.contrato_preenchimento||null;
  var snap=Object.assign({}, st, {
    adicionais_resumo: rhRemResumoAdicionaisTexto(st, calc),
    beneficios_resumo: rhRemResumoBeneficiosTexto(st, calc),
    calculo:{
      salario:calc.salario, adicionais:calc.adicionais, remuneracao_direta:calc.remuneracao_direta,
      adicional_noturno_valor:calc.adicional_noturno_valor, adicional_insal_peric:calc.adicional_insal_peric,
      clausula_aplicada:calc.clausula_aplicada, vt_desconto_colaborador:calc.vt_desconto_colaborador,
      vt_custo_empresa:calc.vt_custo_empresa, beneficios_pat:calc.beneficios_pat,
      custo_empresa_estimado:calc.custo_empresa_estimado, avisos:calc.avisos, fonte:calc.fonte
    }
  });
  if(keep) snap.preenchimento_contrato=keep;
  _rhCtAtual.remuneracao=snap;
}
function rhRemOnJornada(){
  var j=((document.getElementById('rh-rem-jornada')||{}).value||'diurna');
  var box=document.getElementById('rh-rem-noturno-box');
  var chk=document.getElementById('rh-rem-noturno');
  var show=j==='noturna'||j==='mista'||(chk&&chk.checked);
  if(j==='noturna'||j==='mista'){ if(chk) chk.checked=true; show=true; }
  if(box) box.style.display=show?'':'none';
  rhRemRefreshCalculo();
}
function rhRemRefreshCalculo(){
  if(!_rhCtAtual) return;
  var st=rhRemStateFromForm();
  if(!st.salario_proposto && !st.piso_base) st=rhRemDefaultsFromPiso();
  var calc=rhRemCalc(st);
  rhRemAplicarSnapshot(st, calc);
  var el=document.getElementById('rh-rem-resumo');
  if(el) el.innerHTML=rhRemResumoHtml(calc, st);
}
function rhRemResumoHtml(calc, st){
  var avisos=(calc.avisos||[]).map(function(a){return '<div style="font-size:12px;color:#854F0B;margin:2px 0">⚠ '+rhEsc(a)+'</div>';}).join('');
  return '<div class="card" style="margin-top:12px;background:#f9f9f7"><div class="ch"><span class="ct">Memória de cálculo (estimativa CLT — não é holerite)</span></div>'
    +'<div style="padding:1rem">'
    +(st.piso_base?'<div style="font-size:12px;color:#555;margin-bottom:8px">Piso do cargo/função: <b>'+fmtR(st.piso_base)+'</b>'+(calc.fonte?' · '+rhEsc(calc.fonte):'')+'</div>':'<div style="font-size:12px;color:#A32D2D;margin-bottom:8px">Sem piso cadastrado para este cargo/função. Cadastre em RH → Pisos e Benefícios. Aplicado o salário mínimo nacional se o valor informado ficar abaixo.</div>')
    +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:8px">'
    +rhRemKpi('Salário-base',calc.salario)+rhRemKpi('Adic. noturno',calc.adicional_noturno_valor)
    +rhRemKpi(calc.clausula_aplicada==='insalubridade'?'Insalubridade':'Periculosidade',calc.adicional_insal_peric)
    +rhRemKpi('Remuneração direta',calc.remuneracao_direta)
    +rhRemKpi('VT (empresa)',calc.vt_custo_empresa)+rhRemKpi('Desconto VT (6%)',calc.vt_desconto_colaborador)
    +rhRemKpi('Benefícios PAT',calc.beneficios_pat)+rhRemKpi('Custo estimado empresa',calc.custo_empresa_estimado)
    +'</div>'
    +'<div style="font-size:11px;color:#888;margin-top:10px">Noturno: 20% sobre as horas noturnas (art. 73), período 22h–5h, hora reduzida de 52min30s. Periculosidade: 30% do salário (art. 193). Insalubridade: 10/20/40% do salário mínimo (art. 192). Encargos (INSS/FGTS) e CCT do sindicato não estão neste cálculo.</div>'
    +avisos+'</div></div>';
}
function rhRemKpi(lab,val){
  return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:8px;padding:8px 10px"><div style="font-size:10px;color:#888">'+rhEsc(lab)+'</div><div style="font-size:16px;font-weight:800">'+fmtR(val)+'</div></div>';
}
/** Texto humano dos adicionais para tokens de documento ([[ADICIONAIS]]). */
function rhRemResumoAdicionaisTexto(st, calc){
  st=st||{}; calc=calc||st.calculo||{};
  var parts=[];
  if(Number(calc.adicional_noturno_valor||0)>0){
    parts.push('Adicional noturno '+rhEsc(String(st.adicional_noturno_pct||20))+'%: '+fmtR(calc.adicional_noturno_valor));
  }
  if(st.periculosidade && Number(calc.adicional_insal_peric||0)>0){
    parts.push('Periculosidade 30%: '+fmtR(calc.adicional_insal_peric));
  } else if(st.insalubridade_grau && Number(calc.adicional_insal_peric||0)>0){
    var grau={minimo:'mínimo 10%', medio:'médio 20%', maximo:'máximo 40%'}[st.insalubridade_grau]||st.insalubridade_grau;
    parts.push('Insalubridade ('+grau+'): '+fmtR(calc.adicional_insal_peric));
  }
  if(!parts.length && Number(calc.adicionais||0)>0){
    parts.push('Adicionais: '+fmtR(calc.adicionais));
  }
  return parts.length ? parts.join('; ') : 'Sem adicionais';
}
/** Texto humano dos benefícios para tokens de documento ([[BENEFICIOS]]). */
function rhRemResumoBeneficiosTexto(st, calc){
  st=st||{}; calc=calc||st.calculo||{};
  var labels={};
  (RH_REM_BENEF_TIPOS||[]).forEach(function(t){ labels[t.id]=t.label; });
  var bens=(st.beneficios||[]).filter(function(b){ return b && b.ativo!==false; });
  if(!bens.length){
    if(Number(calc.beneficios_pat||0)>0 || Number(calc.vt_custo_empresa||0)>0){
      var alt=[];
      if(Number(calc.vt_custo_empresa||0)>0) alt.push('VT empresa '+fmtR(calc.vt_custo_empresa));
      if(Number(calc.beneficios_pat||0)>0) alt.push('PAT '+fmtR(calc.beneficios_pat));
      return alt.join('; ');
    }
    return 'Sem benefícios';
  }
  return bens.map(function(b){
    var lab=labels[b.tipo]||b.tipo||'Benefício';
    if(b.regra==='pat_valor_dia') return lab+' R$ '+(b.valor!=null?b.valor:0)+'/dia × '+(b.dias_mes||22)+' dias';
    if(b.regra==='percentual_piso') return lab+' '+(b.percentual||0)+'% do salário';
    if(b.regra==='vt_lei_7418') return lab+' (Lei 7.418/85)';
    if(b.valor!=null && b.valor!=='') return lab+' R$ '+b.valor+'/mês';
    return lab;
  }).join('; ');
}
function rhRemSimNaoChk(id, on, onchange){
  return '<label style="display:flex;gap:6px;align-items:center;font-size:13px"><input type="checkbox" id="'+id+'" '+(on?'checked':'')+' onchange="'+(onchange||'rhRemRefreshCalculo()')+'"/> Sim</label>';
}
function rhRemAssistenteHtml(){
  var st=rhRemDefaultsFromPiso();
  var calc=rhRemCalc(st);
  var piso=rhRemMatchPiso(rhCtVal('cargo')||(_rhCtAtual&&_rhCtAtual.cargo), rhCtVal('funcao')||(_rhCtAtual&&_rhCtAtual.funcao), rhCtVal('contrato_id')||(_rhCtAtual&&_rhCtAtual.contrato_id));
  var showNot=st.periodo_noturno||st.jornada==='noturna'||st.jornada==='mista';
  var benefOn={}; (st.beneficios||[]).forEach(function(b){ benefOn[b.tipo]=b; });
  var benefHtml=RH_REM_BENEF_TIPOS.map(function(t){
    var b=benefOn[t.id]||{};
    var on=!!benefOn[t.id];
    return '<div style="border:.5px solid #eee;border-radius:8px;padding:8px 10px;margin-bottom:6px">'
      +'<label style="display:flex;gap:8px;align-items:center"><input type="checkbox" id="rh-rem-b-'+t.id+'" '+(on?'checked':'')+' onchange="rhRemRefreshCalculo()"/><b>'+rhEsc(t.label)+'</b></label>'
      +'<div style="font-size:11px;color:#888;margin:4px 0 6px">'+rhEsc(t.lei)+'</div>'
      +'<div class="g2">'
      +'<div class="fg"><label>Regra</label><select class="inp" id="rh-rem-br-'+t.id+'" data-nosort="1" onchange="rhRemRefreshCalculo()">'
      +[['vt_lei_7418','VT Lei 7.418 (teto 6%)'],['pat_valor_dia','PAT — valor/dia × dias'],['valor_fixo','Valor mensal fixo'],['percentual_piso','% do salário']].map(function(o){
        return '<option value="'+o[0]+'"'+((b.regra||t.regra)===o[0]?' selected':'')+'>'+o[1]+'</option>';
      }).join('')+'</select></div>'
      +'<div class="fg"><label>Valor (R$)</label><input class="inp" type="number" step="0.01" id="rh-rem-bv-'+t.id+'" value="'+(b.valor!=null?b.valor:'')+'" oninput="rhRemRefreshCalculo()"/></div>'
      +'<div class="fg"><label>Dias/mês (PAT)</label><input class="inp" type="number" id="rh-rem-bd-'+t.id+'" value="'+(b.dias_mes||22)+'" oninput="rhRemRefreshCalculo()"/></div>'
      +'<div class="fg"><label>% salário</label><input class="inp" type="number" step="0.01" id="rh-rem-bp-'+t.id+'" value="'+(b.percentual||'')+'" oninput="rhRemRefreshCalculo()"/></div>'
      +'</div></div>';
  }).join('');
  return '<div style="font-size:12px;color:#666;margin-bottom:10px">Piso vem do cadastro de cargo/função (RH → Pisos e Benefícios). Período noturno abre o adicional. Eletricidade no passo 2 só <b>sugere</b> periculosidade — o RH confirma. Não grava no cadastro da pessoa nesta fase.</div>'
    +(!_rhRemDisponivel?'<div style="margin-bottom:10px;padding:8px 10px;background:#FEF3E2;color:#854F0B;font-size:12px">'+rhEsc(_rhRemErro||rhRemSqlHint())+'</div>':'')
    +'<div class="g2">'
    +'<div class="fg"><label>Piso do cargo/função</label><input class="inp" id="rh-rem-piso" value="'+(st.piso_base||'')+'" disabled/>'
    +'<div style="font-size:11px;color:#888;margin-top:4px">'+(piso?(rhEsc(piso.cargo)+(piso.funcao?' · '+rhEsc(piso.funcao):' · todas as funções')):'Nenhum piso para '+rhEsc(rhCtVal('cargo')||'este cargo')+'. <a href="#" onclick="showSub(\'rh-pisos\');return false">Cadastrar</a>')+'</div></div>'
    +'<div class="fg"><label>Salário proposto (R$) *</label><input class="inp" type="number" step="0.01" id="rh-rem-salario" value="'+(st.salario_proposto||'')+'" oninput="rhRemRefreshCalculo()"/></div>'
    +'<div class="fg"><label>Carga mensal (h)</label><input class="inp" type="number" step="0.5" id="rh-rem-carga" value="'+(st.carga_horaria_mensal||220)+'" oninput="rhRemRefreshCalculo()"/></div>'
    +'<div class="fg"><label>Jornada / período</label><select class="inp" id="rh-rem-jornada" data-nosort="1" onchange="rhRemOnJornada()">'
    +[['diurna','Diurna'],['noturna','Noturna (22h–5h)'],['mista','Mista']].map(function(o){
      return '<option value="'+o[0]+'"'+(st.jornada===o[0]?' selected':'')+'>'+o[1]+'</option>';
    }).join('')+'</select></div>'
    +'</div>'
    +'<div style="margin:8px 0">'+rhRemSimNaoChk('rh-rem-noturno', showNot, 'rhRemOnJornada()')+' <span style="font-size:12px;color:#555">Período noturno — abre adicional (CLT art. 73)</span></div>'
    +'<div id="rh-rem-noturno-box" style="'+(showNot?'':'display:none')+'">'
    +'<div class="g2"><div class="fg"><label>Adicional noturno %</label><input class="inp" type="number" step="0.01" id="rh-rem-noturno-pct" value="'+(st.adicional_noturno_pct||20)+'" oninput="rhRemRefreshCalculo()"/><div style="font-size:11px;color:#888">Padrão urbano 20%. Rural pode ser 25% (lei específica).</div></div>'
    +'<div class="fg"><label>Horas noturnas/mês (relógio)</label><input class="inp" type="number" step="0.5" id="rh-rem-horas-not" value="'+(st.horas_noturnas_mes||'')+'" oninput="rhRemRefreshCalculo()"/><div style="font-size:11px;color:#888">Vazio = estima 7/8 da carga se jornada noturna. Hora noturna reduzida 52min30s entra no cálculo.</div></div></div></div>'
    +'<div class="g2" style="margin-top:8px">'
    +'<div class="fg"><label>Periculosidade (30% do salário)</label>'+rhRemSimNaoChk('rh-rem-peric', st.periculosidade)+'<div style="font-size:11px;color:#888">CLT art. 193. Sugestão se eletricidade = sim; não acumula com insalubridade.</div></div>'
    +'<div class="fg"><label>Insalubridade</label><select class="inp" id="rh-rem-insal" data-nosort="1" onchange="rhRemRefreshCalculo()">'
    +'<option value="">Não se aplica</option><option value="minimo"'+(st.insalubridade_grau==='minimo'?' selected':'')+'>Mínimo 10% do SM</option>'
    +'<option value="medio"'+(st.insalubridade_grau==='medio'?' selected':'')+'>Médio 20% do SM</option>'
    +'<option value="maximo"'+(st.insalubridade_grau==='maximo'?' selected':'')+'>Máximo 40% do SM</option></select>'
    +'<div style="font-size:11px;color:#888">CLT art. 192 — base = salário mínimo nacional, não o piso do cargo.</div></div>'
    +'<div class="fg"><label>Cargo de confiança</label>'+rhRemSimNaoChk('rh-rem-confianca', st.cargo_confianca)+'<div style="font-size:11px;color:#888">CLT art. 62 II — em regra sem HE. Conferir fidúcia e CCT.</div></div>'
    +'</div>'
    +'<div style="margin-top:12px;font-weight:700;font-size:13px">Benefícios do piso</div>'
    +'<div style="font-size:12px;color:#666;margin:4px 0 8px">Marcados a partir do cadastro do cargo. Ajuste valores neste processo sem alterar o piso-mestre.</div>'
    +benefHtml
    +'<div id="rh-rem-resumo">'+rhRemResumoHtml(calc, st)+'</div>';
}

function rhRenderPisos(){
  var wrap=document.getElementById('rh-pisos-wrap'); if(!wrap) return;
  if(!_rhRemCarregado){
    wrap.innerHTML='<div class="card"><div class="ch"><span class="ct">Pisos e Benefícios</span></div><div style="padding:1.5rem;color:#888">Carregando…</div></div>';
    rhGarantirLookups().then(function(){ return rhRemCarregar(); }).then(function(){ rhRenderPisos(); });
    return;
  }
  var par=rhRemParamsAtivos();
  var rows=(_rhRemPisos||[]).map(function(p){
    var id=String(p.id||'').replace(/'/g,'');
    var bens=rhRemBenefsDoPiso(p.id).map(function(b){return b.tipo;}).join(', ');
    return '<tr'+(p.ativo===false?' style="opacity:.5"':'')+'>'
      +'<td>'+rhEsc(p.cargo)+'</td><td>'+rhEsc(p.funcao||'Todas')+'</td><td>'+rhEsc(p.contrato_nome||'Todos')+'</td>'
      +'<td style="font-weight:700">'+fmtR(p.piso)+'</td><td>'+rhEsc(p.jornada_padrao||'diurna')+'</td>'
      +'<td style="font-size:11px">'+rhEsc(bens||'—')+'</td>'
      +'<td><button class="btn btn-sm" onclick="rhRemAbrirPiso(\''+id+'\')">Editar</button> '
      +'<button class="btn btn-sm" onclick="rhRemTogglePiso(\''+id+'\')">'+(p.ativo===false?'Reativar':'Inativar')+'</button></td></tr>';
  }).join('');
  wrap.innerHTML='<div class="card" style="margin-bottom:1rem;padding:1rem;background:linear-gradient(135deg,#1a1a18,#29384d);color:#fff;border:none">'
    +'<div style="font-size:20px;font-weight:800">💰 Pisos e benefícios por cargo</div>'
    +'<div style="font-size:12px;opacity:.85;margin-top:4px">Cadastro-mestre do piso. A Contratação só aplica o recorte. Cargo continua em Cadastros → Cargos.</div></div>'
    +(!_rhRemDisponivel?'<div class="card" style="padding:.75rem 1rem;background:#FEF3E2;color:#854F0B;font-size:12px;margin-bottom:1rem">'+rhEsc(_rhRemErro||rhRemSqlHint())+'</div>':'')
    +'<div class="card"><div class="ch"><span class="ct">Parâmetros legais vigentes</span><button class="btn btn-sm" onclick="rhRemAbrirParametros()">Editar salário mínimo / % legais</button></div>'
    +'<div style="padding:1rem;font-size:13px">Salário mínimo <b>'+fmtR(par.salario_minimo)+'</b> · vigência '+rhEsc(par.vigencia_inicio||'—')
    +' · noturno '+rhEsc(par.adicional_noturno_pct)+'% · periculosidade '+rhEsc(par.periculosidade_pct)+'% · VT até '+rhEsc(par.vt_desconto_max_pct)+'%'
    +'<div style="font-size:11px;color:#888;margin-top:6px">'+rhEsc(par.fonte||'')+'</div></div></div>'
    +'<div class="card"><div class="ch"><span class="ct">Pisos cadastrados</span><button class="btn btn-pri" onclick="rhRemAbrirPiso()">+ Piso</button></div>'
    +'<div style="overflow-x:auto"><table class="tbl" style="font-size:12px"><thead><tr><th>Cargo</th><th>Função</th><th>Contrato</th><th>Piso</th><th>Jornada</th><th>Benefícios</th><th></th></tr></thead><tbody>'
    +(rows||'<tr><td colspan="7" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum piso. Clique em + Piso e escolha um cargo já cadastrado.</td></tr>')
    +'</tbody></table></div></div>';
}
function rhRemAbrirParametros(){
  var par=rhRemParamsAtivos();
  setModal('<div class="modal-bg"><div class="modal" style="max-width:520px"><h3>Parâmetros legais</h3>'
    +'<div style="font-size:12px;color:#666;margin-bottom:10px">Altere quando sair decreto novo. Não substitui CCT do sindicato.</div>'
    +'<div class="g2">'
    +'<div class="fg"><label>Vigência</label><input class="inp" type="date" id="rh-par-vig" value="'+rhEsc(par.vigencia_inicio||'2026-01-01')+'"/></div>'
    +'<div class="fg"><label>Salário mínimo (R$)</label><input class="inp" type="number" step="0.01" id="rh-par-sm" value="'+rhEsc(par.salario_minimo)+'"/></div>'
    +'<div class="fg"><label>Adicional noturno %</label><input class="inp" type="number" step="0.01" id="rh-par-not" value="'+rhEsc(par.adicional_noturno_pct)+'"/></div>'
    +'<div class="fg"><label>Periculosidade %</label><input class="inp" type="number" step="0.01" id="rh-par-per" value="'+rhEsc(par.periculosidade_pct)+'"/></div>'
    +'<div class="fg"><label>VT desconto máx. %</label><input class="inp" type="number" step="0.01" id="rh-par-vt" value="'+rhEsc(par.vt_desconto_max_pct)+'"/></div>'
    +'<div class="fg"><label>Carga mensal padrão (h)</label><input class="inp" type="number" step="0.5" id="rh-par-carga" value="'+rhEsc(par.carga_mensal_padrao)+'"/></div>'
    +'</div>'
    +'<div class="fg"><label>Fonte / decreto</label><input class="inp" id="rh-par-fonte" value="'+rhEsc(par.fonte||'')+'"/></div>'
    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn btn-pri" onclick="rhRemSalvarParametros()">Salvar</button></div></div></div>');
}
async function rhRemSalvarParametros(){
  var payload={
    vigencia_inicio:(document.getElementById('rh-par-vig')||{}).value||'2026-01-01',
    salario_minimo:rhRemNum((document.getElementById('rh-par-sm')||{}).value,1621),
    adicional_noturno_pct:rhRemNum((document.getElementById('rh-par-not')||{}).value,20),
    periculosidade_pct:rhRemNum((document.getElementById('rh-par-per')||{}).value,30),
    vt_desconto_max_pct:rhRemNum((document.getElementById('rh-par-vt')||{}).value,6),
    carga_mensal_padrao:rhRemNum((document.getElementById('rh-par-carga')||{}).value,220),
    fonte:((document.getElementById('rh-par-fonte')||{}).value||'').trim(),
    ativo:true
  };
  payload.salario_minimo_diario=rhRemRound(payload.salario_minimo/30);
  payload.salario_minimo_hora=rhRemRound(payload.salario_minimo/220);
  if(DEMO){
    var i=_rhRemParams.findIndex(function(p){return p.vigencia_inicio===payload.vigencia_inicio;});
    if(i>=0) Object.assign(_rhRemParams[i], payload); else _rhRemParams.unshift(Object.assign({id:'par'+Date.now()},payload));
  } else {
    var ok=null;
    if(_rhRemParams[0]&&_rhRemParams[0].id) ok=await sbUpdate('rh_parametros_legais', payload, 'id=eq.'+_rhRemParams[0].id);
    if(!ok){
      var ins=await sbInsert('rh_parametros_legais', payload);
      if(!ins){ progShowToast(rhRemSqlHint(),'erro'); return; }
    }
    await rhRemReset();
  }
  closeModal(); rhRenderPisos(); progShowToast('Parâmetros legais salvos.');
}
function rhRemAbrirPiso(id){
  var p=id?(_rhRemPisos||[]).find(function(x){return String(x.id)===String(id);})||{}:{};
  var cargoSel=typeof cargoSelectHtml==='function'
    ? cargoSelectHtml(p.cargo||'','class="inp" id="rh-piso-cargo" style="width:100%" data-nosort="1"')
    : '<input class="inp" id="rh-piso-cargo" value="'+rhEsc(p.cargo||'')+'"/>';
  var funcSel=typeof rhCtFuncaoSelect==='function'?String(rhCtFuncaoSelect(p.funcao||'')).replace('id="rh-ct-funcao"','id="rh-piso-funcao"'):'<input class="inp" id="rh-piso-funcao" value="'+rhEsc(p.funcao||'')+'"/>';
  var cont='<select class="inp" id="rh-piso-contrato" data-nosort="1"><option value="">Todos os contratos</option>'
    +(contratos||[]).map(function(c){return '<option value="'+c.id+'"'+(String(p.contrato_id||'')===String(c.id)?' selected':'')+'>'+rhEsc(c.nome||c.codigo)+'</option>';}).join('')+'</select>';
  var bens=id?rhRemBenefsDoPiso(id):[];
  var onB={}; bens.forEach(function(b){onB[b.tipo]=b;});
  var benef=RH_REM_BENEF_TIPOS.map(function(t){
    var b=onB[t.id]||{};
    return '<div style="border:.5px solid #eee;border-radius:8px;padding:8px;margin-bottom:6px">'
      +'<label><input type="checkbox" id="rh-pb-'+t.id+'" '+(onB[t.id]?'checked':'')+'/> <b>'+rhEsc(t.label)+'</b></label>'
      +'<div class="g2" style="margin-top:6px">'
      +'<div class="fg"><label>Regra</label><select class="inp" id="rh-pbr-'+t.id+'" data-nosort="1">'
      +'<option value="vt_lei_7418"'+(b.regra==='vt_lei_7418'?' selected':'')+'>VT 6%</option>'
      +'<option value="pat_valor_dia"'+(b.regra==='pat_valor_dia'||(!b.regra&&t.regra==='pat_valor_dia')?' selected':'')+'>PAT valor/dia</option>'
      +'<option value="valor_fixo"'+(b.regra==='valor_fixo'||(!b.regra&&t.regra==='valor_fixo')?' selected':'')+'>Valor mensal</option>'
      +'<option value="percentual_piso"'+(b.regra==='percentual_piso'?' selected':'')+'>% salário</option></select></div>'
      +'<div class="fg"><label>Valor</label><input class="inp" type="number" step="0.01" id="rh-pbv-'+t.id+'" value="'+(b.valor!=null?b.valor:'')+'"/></div>'
      +'<div class="fg"><label>Dias</label><input class="inp" type="number" id="rh-pbd-'+t.id+'" value="'+(b.dias_mes||22)+'"/></div>'
      +'<div class="fg"><label>%</label><input class="inp" type="number" step="0.01" id="rh-pbp-'+t.id+'" value="'+(b.percentual||'')+'"/></div>'
      +'</div></div>';
  }).join('');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:640px;max-height:90vh;overflow:auto"><h3>'+(id?'Editar piso':'Novo piso')+'</h3>'
    +'<div class="g2">'+'<div class="fg"><label>Cargo *</label>'+cargoSel+'</div><div class="fg"><label>Função</label>'+funcSel+'<div style="font-size:11px;color:#888">Vazio = todas as funções do cargo</div></div>'
    +'<div class="fg"><label>Contrato</label>'+cont+'</div>'
    +'<div class="fg"><label>Piso (R$) *</label><input class="inp" type="number" step="0.01" id="rh-piso-val" value="'+(p.piso||'')+'"/></div>'
    +'<div class="fg"><label>Carga mensal (h)</label><input class="inp" type="number" step="0.5" id="rh-piso-carga" value="'+(p.carga_horaria_mensal||220)+'"/></div>'
    +'<div class="fg"><label>Jornada padrão</label><select class="inp" id="rh-piso-jor" data-nosort="1">'
    +'<option value="diurna"'+(p.jornada_padrao==='diurna'||!p.jornada_padrao?' selected':'')+'>Diurna</option>'
    +'<option value="noturna"'+(p.jornada_padrao==='noturna'?' selected':'')+'>Noturna</option>'
    +'<option value="mista"'+(p.jornada_padrao==='mista'?' selected':'')+'>Mista</option></select></div>'
    +'<div class="fg"><label>Insalubridade padrão</label><select class="inp" id="rh-piso-insal" data-nosort="1">'
    +'<option value="">Não</option><option value="minimo"'+(p.insalubridade_grau==='minimo'?' selected':'')+'>Mínimo 10%</option>'
    +'<option value="medio"'+(p.insalubridade_grau==='medio'?' selected':'')+'>Médio 20%</option>'
    +'<option value="maximo"'+(p.insalubridade_grau==='maximo'?' selected':'')+'>Máximo 40%</option></select></div>'
    +'</div>'
    +'<div style="margin:8px 0"><label><input type="checkbox" id="rh-piso-peric" '+(p.periculosidade_padrao?'checked':'')+'/> Periculosidade padrão</label> '
    +'<label style="margin-left:12px"><input type="checkbox" id="rh-piso-conf" '+(p.cargo_confianca_padrao?'checked':'')+'/> Cargo de confiança padrão</label></div>'
    +'<div class="fg"><label>Observação / CCT</label><input class="inp" id="rh-piso-obs" value="'+rhEsc(p.observacao||'')+'"/></div>'
    +'<div style="font-weight:700;margin:10px 0 6px">Benefícios deste piso</div>'+benef
    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn btn-pri" onclick="rhRemSalvarPiso(\''+(id||'')+'\')">Salvar piso</button></div></div></div>');
}
async function rhRemSalvarPiso(id){
  var cargo=((document.getElementById('rh-piso-cargo')||{}).value||'').trim();
  var piso=rhRemNum((document.getElementById('rh-piso-val')||{}).value,0);
  if(!cargo||piso<=0){ progShowToast('Informe cargo e piso maior que zero.','erro'); return; }
  var par=rhRemParamsAtivos();
  if(piso<rhRemNum(par.salario_minimo,1621)){ progShowToast('Piso não pode ser inferior ao salário mínimo vigente ('+fmtR(par.salario_minimo)+').','erro'); return; }
  var cid=((document.getElementById('rh-piso-contrato')||{}).value||'');
  var cont=(contratos||[]).find(function(c){return String(c.id)===String(cid);});
  var cargoObj=(_cad_cargos||[]).find(function(c){return c.nome===cargo;});
  var payload={
    cargo:cargo, cargo_id:cargoObj?cargoObj.id:null,
    funcao:((document.getElementById('rh-piso-funcao')||{}).value||'').trim()||null,
    contrato_id:cid||null, contrato_nome:cont?(cont.nome||cont.codigo):null,
    piso:piso, carga_horaria_mensal:rhRemNum((document.getElementById('rh-piso-carga')||{}).value,220),
    jornada_padrao:((document.getElementById('rh-piso-jor')||{}).value||'diurna'),
    periculosidade_padrao:!!(document.getElementById('rh-piso-peric')||{}).checked,
    insalubridade_grau:((document.getElementById('rh-piso-insal')||{}).value||''),
    cargo_confianca_padrao:!!(document.getElementById('rh-piso-conf')||{}).checked,
    observacao:((document.getElementById('rh-piso-obs')||{}).value||'').trim()||null,
    ativo:true, criado_por:usuarioLogado?(usuarioLogado.nome||usuarioLogado.email):null
  };
  var pisoId=id;
  if(DEMO){
    if(id){ var row=_rhRemPisos.find(function(x){return String(x.id)===String(id);}); if(row) Object.assign(row,payload); }
    else { pisoId='piso'+Date.now(); _rhRemPisos.unshift(Object.assign({id:pisoId},payload)); }
  } else {
    if(id){
      var ok=await sbUpdate('rh_remuneracao_pisos', payload, 'id=eq.'+id);
      if(!ok){ progShowToast('Falha ao salvar piso. '+rhRemSqlHint(),'erro'); return; }
    } else {
      var ins=await sbInsert('rh_remuneracao_pisos', payload);
      var saved=ins&&ins[0];
      if(!saved){ progShowToast('Falha ao criar piso. '+rhRemSqlHint(),'erro'); return; }
      pisoId=saved.id; _rhRemPisos.unshift(saved);
    }
  }
  var wanted=[];
  RH_REM_BENEF_TIPOS.forEach(function(t){
    var on=!!(document.getElementById('rh-pb-'+t.id)||{}).checked;
    if(!on) return;
    wanted.push({
      piso_id:pisoId, tipo:t.id,
      regra:((document.getElementById('rh-pbr-'+t.id)||{}).value||t.regra),
      valor:rhRemNum((document.getElementById('rh-pbv-'+t.id)||{}).value,0)||null,
      percentual:rhRemNum((document.getElementById('rh-pbp-'+t.id)||{}).value,0)||null,
      dias_mes:rhRemNum((document.getElementById('rh-pbd-'+t.id)||{}).value,22)||22, ativo:true
    });
  });
  if(!DEMO && pisoId){
    await sbDelete('rh_remuneracao_piso_beneficios','piso_id=eq.'+pisoId);
    if(wanted.length){
      var insB=await sbInsert('rh_remuneracao_piso_beneficios', wanted);
      if(!insB){ progShowToast('Piso salvo, mas benefícios falharam (PGRST/SQL).','erro'); }
    }
  }
  _rhRemBenefs=(_rhRemBenefs||[]).filter(function(b){return String(b.piso_id)!==String(pisoId);}).concat(wanted.map(function(w,i){return Object.assign({id:'b'+Date.now()+i},w);}));
  if(!DEMO) await rhRemReset();
  closeModal(); rhRenderPisos(); progShowToast('Piso salvo.');
}
async function rhRemTogglePiso(id){
  var p=(_rhRemPisos||[]).find(function(x){return String(x.id)===String(id);}); if(!p) return;
  p.ativo=!(p.ativo===false);
  if(!DEMO) await sbUpdate('rh_remuneracao_pisos',{ativo:p.ativo},'id=eq.'+id);
  rhRenderPisos();
}

