    +'<div class="fg"><label>CNPJ</label><input class="inp" id="rh-emp-cnpj" value="'+rhEsc(e?e.cnpj||'':'')+'"/></div>'
    +'<div class="fg"><label>Endereço</label><input class="inp" id="rh-emp-end" value="'+rhEsc(e?e.endereco||'':'')+'"/></div>'
    +'</div>'
    +'<div style="margin-top:12px;display:flex;gap:8px;justify-content:flex-end">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
