function rhKitEquivalencia(tipoEnc){
  var it=rhCtFindItem(decodeURIComponent(tipoEnc||''));
  if(!it) return;
  var colId=_rhCtAtual&&_rhCtAtual.colaborador_id;
  var docs=colId&&typeof rhDocsReaisColab==='function'?rhDocsReaisColab(colId):[];
  var eqs=rhKitCatalogoEquivalencias().filter(function(eq){ return rhCtTipoEq(eq.tipo_atendido, it.tipo_documento); });
  var opts=[];
  eqs.forEach(function(eq){
    docs.filter(function(d){ return rhCtTipoEq(d.tipo_documento, eq.tipo_apresentado) && rhDocumentoTemArquivo(d); }).forEach(function(d){
      opts.push({id:d.id, tipo:eq.tipo_apresentado, nome:d.arquivo_nome||d.tipo_documento, cpf:eq.condicao==='cpf_visivel'||rhKitEhCpfArquivo(it.tipo_documento)});
    });
  });
  if(!opts.length){
    progShowToast('Não há no dossiê um documento equivalente (ex.: CNH para RG). Anexe o original ou a CNH primeiro.','erro');
    return;
  }
  var sel=opts.map(function(o,i){
    return '<label style="display:block;margin:6px 0"><input type="radio" name="rh-kit-eq" value="'+o.id+'" data-tipo="'+rhEsc(o.tipo)+'" data-cpf="'+(o.cpf?'1':'')+'" '+(i===0?'checked':'')+'/> '
      +rhEsc(o.tipo)+' — '+rhEsc(o.nome)+'</label>';
  }).join('');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:480px"><h3>Equivalência de arquivo</h3>'
    +'<div style="font-size:13px;color:#555;margin-bottom:.75rem">'+rhEsc(it.tipo_documento)+' pode ser atendido por outro documento já no dossiê. Não duplica o arquivo. Dado cadastral CPF nunca é dispensado.</div>'
    +sel
    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="rhKitConfirmarEquivalencia(\''+tipoEnc+'\')">Aplicar</button></div></div></div>');
}
async function rhKitConfirmarEquivalencia(tipoEnc){
  var it=rhCtFindItem(decodeURIComponent(tipoEnc||''));
  var inp=document.querySelector('input[name="rh-kit-eq"]:checked');
  if(!it||!inp){ closeModal(); return; }
  var cpfOn=inp.getAttribute('data-cpf')==='1' || rhKitEhCpfArquivo(it.tipo_documento);
  it.equivalente_documento_id=inp.value;
  it.equivalente_tipo=inp.getAttribute('data-tipo')||'';
  it.obrigatorio=false;
  if(cpfOn){
    it.status_kit='Dispensado';
    it.dispensado_motivo='Arquivo de CPF dispensado por equivalência. Dado cadastral CPF permanece obrigatório.';
    it.acao='CPF cadastral permanece obrigatório';
  } else {
    it.status_kit='Atendido por documento equivalente';
    it.acao='Equivalência de arquivo — não duplicar';
  }
  closeModal();
  await rhKitFlush();
  rhRenderAssistente();
}
