function rhCtLerIa(tipoEnc){
  if(!_rhCtAtual) return;
  if(typeof rhCtIaSetContexto==='function') rhCtIaSetContexto();
  else if(typeof _rhIaContextoPadrao!=='undefined'){
    _rhIaContextoPadrao={
      origem_entrada:'upload',
      contexto_origem: rhEhPromocao()?'promocao':'contratacao',
      colaborador_id_contexto:_rhCtAtual.colaborador_id||null,
      contratacao_id:_rhCtAtual.id||null,
      candidatura_id:_rhCtAtual.candidatura_id||null,
      vaga_id:_rhCtAtual.vaga_id||null,
      cargo_id:_rhCtAtual.cargo_id||null
    };
  }
  try{ auditLog('PROCESSOU_DOCUMENTO_IA','rh','Abriu Entrada Inteligente a partir da Contratação',{contratacao_id:_rhCtAtual.id,contexto:_rhIaContextoPadrao&&_rhIaContextoPadrao.contexto_origem,tipo:tipoEnc||null,vaga_id:_rhCtAtual.vaga_id||null}); }catch(e){}
  // Preferência: painel embutido na etapa 2 (id estável). Caixa completa só se pedido ou fora da etapa.
  var embutido=document.getElementById('rh-contratacao-docs-inteligente');
  if(embutido && Number(_rhCtStep)===2 && !tipoEnc){
    if(typeof rhCtIaInitPainel==='function') rhCtIaInitPainel();
    progShowToast('Use a Entrada Inteligente nesta etapa. Documentos ficam ligados a este processo.');
    return;
  }
  if(typeof showPage==='function') showPage('rh-entrada-ia');
  else if(typeof showMain==='function'){ showMain('rh'); if(typeof showSub==='function') showSub('rh-entrada-ia'); }
  setTimeout(function(){
    rhCtEnfileirarKitParaIa(tipoEnc).catch(function(e){
      progShowToast((e&&e.message)||'Falha ao reaproveitar arquivos do kit.','erro');
    });
  }, 280);
}
async function rhCtFetchUrlComoFile(url, nome){
  if(!url) throw new Error('URL vazia');
  if(String(url).indexOf('demo://')===0){
    var blobDemo=new Blob(['demo'],{type:'image/jpeg'});
    try{ return new File([blobDemo], nome||'demo.jpg', {type:'image/jpeg'}); }
    catch(e){ blobDemo.name=nome||'demo.jpg'; return blobDemo; }
  }
  var r=null;
  try{ r=await fetch(url); }catch(e0){ r=null; }
  if(!r || !r.ok){
    var h={'apikey':SB.key,'Authorization':'Bearer '+(_sbAuthToken||SB.key)};
    r=await fetch(url,{headers:h});
  }
  if(!r || !r.ok) throw new Error('Não foi possível ler o arquivo já salvo no processo');
  var blob=await r.blob();
  var mime=blob.type||'application/octet-stream';
  var fname=nome||('kit_'+Date.now()+'.bin');
  try{ return new File([blob], fname, {type:mime}); }
  catch(eF){ try{ blob.name=fname; }catch(e2){} return blob; }
}
async function rhCtEnfileirarKitParaIa(tipoEnc){
  if(!_rhCtAtual||!_rhCtAtual.id) return;
  if(typeof rhIaAdicionarArquivos!=='function'){
    progShowToast('Entrada Inteligente indisponível neste build.','erro');
    return;
  }
  var tipoFiltro=tipoEnc?decodeURIComponent(tipoEnc):'';
  var lista=(_rhCtKit||[]).filter(function(it){
    if(!it||!it.arquivo_url) return false;
    var st=it.status_kit||'';
    if(st==='Nao se aplica'||st==='Dispensado') return false;
    if(tipoFiltro && !rhCtTipoEq(it.tipo_documento, tipoFiltro)) return false;
    return true;
  });
  if(!lista.length){
    progShowToast(tipoFiltro
      ? 'Este item do kit não tem arquivo no processo para a IA ler. Capture/anexe antes.'
      : 'Nenhum arquivo no kit para a IA. Capture/anexe na etapa 2 ou use o upload da Entrada Inteligente.',
      'erro');
    return;
  }
  progShowToast('Reaproveitando '+lista.length+' arquivo(s) do kit na Entrada Inteligente…');
  var files=[];
  for(var i=0;i<lista.length;i++){
    var it=lista[i];
    try{
      var f=await rhCtFetchUrlComoFile(it.arquivo_url, it.arquivo_nome||((it.tipo_documento||'doc')+'.jpg'));
      f._rhIaMeta={
        origem_entrada:'upload',
        contexto_origem:(_rhIaContextoPadrao&&_rhIaContextoPadrao.contexto_origem)||(rhEhPromocao()?'promocao':'contratacao'),
        colaborador_id_contexto:(_rhIaContextoPadrao&&_rhIaContextoPadrao.colaborador_id_contexto)||_rhCtAtual.colaborador_id||null,
        contratacao_id:_rhCtAtual.id,
        candidatura_id:_rhCtAtual.candidatura_id||null,
        vaga_id:(_rhIaContextoPadrao&&_rhIaContextoPadrao.vaga_id)||_rhCtAtual.vaga_id||null,
        cargo_id:(_rhIaContextoPadrao&&_rhIaContextoPadrao.cargo_id)||_rhCtAtual.cargo_id||null,
        kit_tipo_documento:it.tipo_documento||null,
        kit_ia_item_id:it.ia_item_id||null
      };
      files.push(f);
    }catch(eOne){
      console.warn('rhCtEnfileirarKitParaIa', it.tipo_documento, eOne);
    }
  }
  if(!files.length){
    progShowToast('Não foi possível carregar os arquivos do kit para a IA.','erro');
    return;
  }
  if(typeof _rhIaSelecao!=='undefined') _rhIaSelecao=[];
  rhIaAdicionarArquivos(files);
  if(typeof rhRenderEntradaIa==='function') rhRenderEntradaIa();
  progShowToast(files.length+' arquivo(s) do kit na seleção. Enviando para staging…');
  if(typeof rhIaIniciarUpload==='function'){
    try{ await rhIaIniciarUpload(); }
    catch(eUp){ progShowToast((eUp&&eUp.message)||'Arquivos na seleção — clique em Enviar para staging.','erro'); }
  }
}
function rhCtAplicarDadoAdmissional(campo, valor, meta){
  if(!_rhCtAtual) return;
  meta=meta||{};
  var da=_rhCtAtual.dados_admissionais; if(!da||typeof da!=='object') da={};
  if(typeof da==='string'){ try{da=JSON.parse(da);}catch(e){da={};} }
  var prev=da[campo]&&da[campo].valor;
  // CPF crítico: bloquear divergência
  if(campo==='cpf'){
    var digDoc=String(valor||'').replace(/\D/g,'');
    var digProc=String(_rhCtAtual.cpf_pretendido||'').replace(/\D/g,'');
    if(digProc.length===11 && digDoc.length===11 && digDoc!==digProc){
      progShowToast('CPF do documento diverge do processo de contratação. Não aplicado.','erro');
      try{ auditLog('IDENTIFICOU_DIVERGENCIA_DOCUMENTAL','rh','CPF diverge — aplicação bloqueada',{contratacao_id:_rhCtAtual.id,campo:'cpf'}); }catch(e){}
      return false;
    }
  }
  da[campo]={
    valor:valor, status:'APLICADO',
    fonte_tipo:meta.fonte_tipo||'IA',
    fonte:meta.fonte||meta.tipo_documento||null,
    documento_id:meta.documento_id||null,
    ia_item_id:meta.ia_item_id||null,
    confianca:meta.confianca||null,
    confirmado_por:(usuarioLogado&&(usuarioLogado.nome||usuarioLogado.email))||'',
    confirmado_em:new Date().toISOString(),
    valor_anterior:prev!=null?prev:null
  };
  _rhCtAtual.dados_admissionais=da;
  _rhCtAtual.dados_admissionais_status='EM_REVISAO';
  try{ auditLog('APLICOU_DADO_DOCUMENTO','rh','Aplicou dado documental na admissão',{contratacao_id:_rhCtAtual.id,campo:campo}); }catch(e){}
  return true;
}
function rhAdmissaoDadosParaDocumento(proc){
  proc=proc||_rhCtAtual||{};
  var da=proc.dados_admissionais; if(typeof da==='string'){ try{da=JSON.parse(da);}catch(e){da={};} }
  da=da||{};
  function v(k){ return (da[k]&&da[k].valor!=null&&da[k].valor!=='')?String(da[k].valor):''; }
  var cargoObj=null;
  if(proc.cargo_id && (_cad_cargos||[]).length){
    cargoObj=(_cad_cargos||[]).filter(function(c){return String(c.id)===String(proc.cargo_id);})[0]||null;
  }
  if(!cargoObj && proc.cargo){
    cargoObj=(_cad_cargos||[]).filter(function(c){return String(c.nome||'')===String(proc.cargo);})[0]||null;
  }
  var tokensCargo=typeof cadCargoTokensDocumento==='function'?cadCargoTokensDocumento(cargoObj||{nome:proc.cargo}):{};
  var rem=proc.remuneracao||{};
  if(typeof rem==='string'){ try{rem=JSON.parse(rem);}catch(e){rem={};} }
  // Deriva textos de documento se o snapshot antigo não tinha resumo
  if(!String(rem.adicionais_resumo||'').trim() && typeof rhRemResumoAdicionaisTexto==='function'){
    rem.adicionais_resumo=rhRemResumoAdicionaisTexto(rem, rem.calculo||{});
  }
  if(!String(rem.beneficios_resumo||'').trim() && typeof rhRemResumoBeneficiosTexto==='function'){
    rem.beneficios_resumo=rhRemResumoBeneficiosTexto(rem, rem.calculo||{});
  }
  var end=[v('logradouro'),v('numero'),v('complemento'),v('bairro'),v('cidade'),v('uf'),v('cep')].filter(Boolean).join(', ');
  var out={
    '[[NOME_COMPLETO]]': v('nome_completo')||proc.nome_pretendido||'',
    '[[CPF]]': v('cpf')||proc.cpf_pretendido||'',
    '[[RG]]': v('rg_numero')||'',
    '[[RG_ORGAO_EMISSOR]]': v('rg_orgao_emissor')||'',
    '[[DATA_NASCIMENTO]]': v('data_nascimento')||'',
    '[[ENDERECO_COMPLETO]]': end,
    '[[CEP]]': v('cep')||'',
    '[[CIDADE]]': v('cidade')||'',
    '[[UF]]': v('uf')||'',
    '[[CARGO]]': tokensCargo['[[CARGO]]']||proc.cargo||'',
    '[[OBJETO_DA_FUNÇÃO]]': tokensCargo['[[OBJETO_DA_FUNÇÃO]]']||'',
    '[[DESCRIÇÃO_DAS_ATIVIDADES_E_RESPONSABILIDADES]]': tokensCargo['[[DESCRIÇÃO_DAS_ATIVIDADES_E_RESPONSABILIDADES]]']||'',
    '[[SALARIO]]': rem.salario_proposto!=null?String(rem.salario_proposto):(rem.piso!=null?String(rem.piso):''),
    '[[JORNADA]]': rem.jornada||rem.carga_horaria_mensal!=null?String(rem.carga_horaria_mensal||rem.jornada||''):'',
    '[[ADICIONAIS]]': rem.adicionais_resumo||'',
    '[[BENEFICIOS]]': rem.beneficios_resumo||'',
    '[[DATA_ADMISSAO]]': proc.data_prevista_admissao||proc.admitido_em||'',
    '[[CONTRATO]]': proc.contrato_nome||'',
    '[[BASE]]': proc.base_nome||''
  };
  var pend=[];
  Object.keys(out).forEach(function(k){ if(!String(out[k]||'').trim()) pend.push(k); });
  return {tokens:out, pendencias:pend, fontes:{
    cargo: cargoObj?'Cargo Master':(proc.cargo?'Processo':''),
    objeto: tokensCargo['[[OBJETO_DA_FUNÇÃO]]']?'Cargo Master':'',
    salario: rem.salario_proposto!=null||rem.piso!=null?'Remuneração':''
  }};
}
function rhCtKitResumoHtml(){
  rhMontarKit();
  rhKitSincronizarDossie();
  var vis=typeof rhCtKitItensAdmissao==='function'?rhCtKitItensAdmissao():(_rhCtKit||[]);
  var pend=vis.filter(rhKitGeraPendencia).length;
  var conf=vis.filter(rhKitGeraConferencia).length;
  var ok=vis.filter(function(it){ return it.status_kit==='Validado'||it.status_kit==='Recebido'||it.status_kit==='Atendido por documento equivalente'; }).length;
  var total=vis.length;
  return {pend:pend, conf:conf, ok:ok, total:total};
}
var _rhCtIaMatrizDocs = null;
var _rhCtIaMatrizCargoId = null;

function rhCtIaSetContexto(){
  if(!_rhCtAtual || typeof _rhIaContextoPadrao==='undefined') return;
  _rhIaContextoPadrao = {
    origem_entrada:'upload',
    contexto_origem: (typeof rhEhPromocao==='function' && rhEhPromocao()) ? 'promocao' : 'contratacao',
    colaborador_id_contexto: _rhCtAtual.colaborador_id || null,
    contratacao_id: _rhCtAtual.id || null,
    candidatura_id: _rhCtAtual.candidatura_id || null,
    vaga_id: _rhCtAtual.vaga_id || null,
    cargo_id: _rhCtAtual.cargo_id || null
  };
}

function rhCtIaContextoBannerHtml(){
  var p = _rhCtAtual || {};
  var cand = p.nome_pretendido || '—';
  var vaga = (p.cargo || '—') + (p.vaga_id ? ' · vaga '+String(p.vaga_id).slice(0,8)+'…' : '');
  var proc = p.id ? (String(p.id).slice(0,8)+'…') : '—';
  return '<div style="margin-bottom:10px;padding:10px 12px;background:#EBF4FD;border:1px solid #B5D4F4;border-radius:8px;font-size:12px;color:#185FA5;display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px">'
    +'<div><div style="font-size:10px;text-transform:uppercase;opacity:.75">Candidato</div><b>'+rhEsc(cand)+'</b></div>'
    +'<div><div style="font-size:10px;text-transform:uppercase;opacity:.75">Vaga</div><b>'+rhEsc(vaga)+'</b></div>'
    +'<div><div style="font-size:10px;text-transform:uppercase;opacity:.75">Processo</div><b>'+rhEsc(proc)+'</b>'
    +(p.candidatura_id?' · candidatura '+rhEsc(String(p.candidatura_id).slice(0,8))+'…':'')
    +'</div></div>';
}

function rhCtIaItensDoProcesso(){
  if(!_rhCtAtual || !_rhCtAtual.id) return [];
  var ct = String(_rhCtAtual.id);
  return (_rhIaItens||[]).filter(function(it){
    return String(it.contratacao_id||'')===ct;
  });
}

function rhCtIaSituacaoLabel(it){
  var st = String((it&&it.status)||'');
  if(st==='RECEBIDO') return 'Aguardando processamento';
  if(st==='PROCESSANDO'||st==='NA_FILA') return 'Processando';
  if(st==='IDENTIFICADO'||st==='CLASSIFICADO'||st==='EXTRAIDO'||st==='AGUARDANDO_REVISAO') return 'Aguardando conferência';
  if(st==='REVISADO'||st==='APROVADO') return 'Confirmado (humano)';
  if(st==='SALVO'||st==='SALVO_PROCESSO') return 'Salvo no processo';
  if(st==='RECUSADO'||st==='CANCELADO') return 'Recusado';
  if(st==='ERRO_UPLOAD'||st==='FALHA_NA_LEITURA_IA') return 'Erro';
  if(st==='DUPLICADO') return 'Duplicado';
  return st || '—';
}

function rhCtIaMatchTipo(a, b){
  if(typeof rhCtTipoEq==='function') return rhCtTipoEq(a,b);
  return String(a||'').toLowerCase()===String(b||'').toLowerCase();
}

function rhCtIaKitItemPorTipo(tipo){
  var kit = (typeof rhCtKitItensAdmissao==='function' ? rhCtKitItensAdmissao() : (_rhCtKit||[])) || [];
  for(var i=0;i<kit.length;i++){
    if(rhCtIaMatchTipo(kit[i].tipo_documento, tipo)) return kit[i];
  }
  return null;
}

function rhCtIaItemPorTipo(tipo){
  var itens = rhCtIaItensDoProcesso();
  var best = null;
  for(var i=0;i<itens.length;i++){
    var it = itens[i];
    var t = (it.decisoes&&it.decisoes.processo&&it.decisoes.processo.tipo_documento) || it.tipo_documento_sugerido || '';
    if(!rhCtIaMatchTipo(t, tipo)) continue;
    if(it.status==='CANCELADO'||it.status==='RECUSADO') continue;
    if(!best) best = it;
    else if(String(it.status).indexOf('REVIS')>=0 || it.status==='APROVADO' || it.status==='SALVO') best = it;
  }
  return best;
}

async function rhCtIaCarregarMatriz(){
  var cargoId = _rhCtAtual && _rhCtAtual.cargo_id;
  if(!cargoId){ _rhCtIaMatrizDocs=[]; _rhCtIaMatrizCargoId=null; return []; }
  if(_rhCtIaMatrizCargoId===String(cargoId) && Array.isArray(_rhCtIaMatrizDocs)) return _rhCtIaMatrizDocs;
  if(DEMO){ _rhCtIaMatrizDocs=[]; _rhCtIaMatrizCargoId=String(cargoId); return []; }
  try{
    if(typeof rhCarregarRegras==='function' && !(_rhRegras||[]).length){
      try{ await rhCarregarRegras(); }catch(e0){}
    }
    var rows = await sbFetch('rh_cargo_requisitos_documentos',{
      filters:['cargo_id=eq.'+cargoId,'ativo=eq.true'],
      limit:100
    });
    _rhCtIaMatrizDocs = rows||[];
    _rhCtIaMatrizCargoId = String(cargoId);
  }catch(e){
    _rhCtIaMatrizDocs = [];
    _rhCtIaMatrizCargoId = String(cargoId);
  }
  return _rhCtIaMatrizDocs;
}

function rhCtIaMatrizHtml(){
  var cargoId = _rhCtAtual && _rhCtAtual.cargo_id;
  if(!cargoId){
    return '<div style="font-size:12px;color:#854F0B;padding:8px;background:#FEF3E2;border-radius:6px">Defina o cargo na etapa 1 para carregar a Matriz de Requisitos.</div>';
  }
  var docs = _rhCtIaMatrizDocs;
  if(!Array.isArray(docs)){
    return '<div style="font-size:12px;color:#888">Carregando matriz…</div>';
  }
  if(!docs.length){
    return '<div style="font-size:12px;color:#666">Nenhum documento na matriz oficial deste cargo. O kit da admissão abaixo continua válido.</div>';
  }
  var lis = docs.map(function(d){
    var nome = (typeof rhMatrizDocLabel==='function' ? rhMatrizDocLabel(d.tipo_documento_id) : null)
      || ( (_rhRegras||[]).filter(function(r){ return String(r.id)===String(d.tipo_documento_id); })[0]||{} ).tipo_documento
      || String(d.tipo_documento_id||'Documento');
    var kit = rhCtIaKitItemPorTipo(nome);
    var ia = rhCtIaItemPorTipo(nome);
    var ok = false, pend = true, label = 'pendente';
    if(kit && (kit.status_kit==='Validado'||kit.status_kit==='Recebido'||kit.status_kit==='Atendido por documento equivalente'||kit.arquivo_url)){
      ok = true; pend = false; label = 'identificado';
    } else if(ia && ia.tipo_documento_sugerido){
      ok = true; pend = false; label = (ia.status==='REVISADO'||ia.status==='APROVADO'||ia.status==='SALVO') ? 'confirmado' : 'identificado';
    }
    var icon = ok ? '✓' : '⚠';
    var cor = ok ? '#047857' : '#854F0B';
    return '<li style="margin:4px 0;color:'+cor+'"><b>'+icon+' '+rhEsc(nome)+'</b> — '+rhEsc(label)
      +(d.nivel_exigencia?' <span style="opacity:.7;font-size:11px">('+rhEsc(d.nivel_exigencia)+')</span>':'')
      +'</li>';
  }).join('');
  return '<ul style="margin:0;padding-left:18px;font-size:12px">'+lis+'</ul>';
}

function rhCtIaGradeHtml(){
  var itens = rhCtIaItensDoProcesso();
  var kitVis = (typeof rhCtKitItensAdmissao==='function' ? rhCtKitItensAdmissao() : (_rhCtKit||[])) || [];
  var rows = [];
  var vistos = {};

  itens.forEach(function(it){
    var tipo = (it.decisoes&&it.decisoes.processo&&it.decisoes.processo.tipo_documento)
      || it.tipo_documento_sugerido || '—';
    var idSafe = String(it.id||'').replace(/'/g,'');
    vistos[String(it.id)] = 1;
    var conf = it.confianca_tipo!=null ? (typeof rhIaFaixaConf==='function'?rhIaFaixaConf(it.confianca_tipo):it.confianca_tipo) : '—';
    var acoes = '';
    if(it.arquivo_url_staging){
      acoes += '<a class="btn btn-sm" href="'+rhEsc(it.arquivo_url_staging)+'" target="_blank" rel="noopener">Ver</a> ';
    }
    if(it.status!=='RECEBIDO' && it.status!=='ERRO_UPLOAD' && it.status!=='CANCELADO'){
      acoes += '<button type="button" class="btn btn-sm" onclick="rhIaAbrirRevisao(\''+idSafe+'\')">Corrigir / Conferir</button> ';
    }
    if(it.status==='RECEBIDO'){
      acoes += '<button type="button" class="btn btn-sm" onclick="rhIaProcessarItemUi(\''+idSafe+'\',{provider:RH_IA_PROVIDER_PADRAO,modo:\'automatico\'}).then(function(){rhCtIaRefreshPainel();})">Processar</button> ';
    }
    if(typeof rhIaPodeSalvarProcesso==='function' && rhIaPodeSalvarProcesso(it)){
      acoes += '<button type="button" class="btn btn-sm btn-pri" onclick="rhIaGravarProcessoDaFila(\''+idSafe+'\').then(function(){rhCtIaRefreshPainel();})">Confirmar no kit</button> ';
    }
    rows.push('<tr>'
      +'<td><b>'+rhEsc(tipo)+'</b></td>'
      +'<td>'+rhEsc(it.arquivo_nome||'—')
      +(it.aviso_hash_historico?'<div style="font-size:10px;color:#854F0B">Possível documento duplicado.</div>':'')
      +'</td>'
      +'<td>'+rhEsc(it.tipo_documento_sugerido||'—')+'<div style="font-size:10px;color:#888">Confiança: '+rhEsc(String(conf))+'</div></td>'
      +'<td>'+(typeof rhIaStatusBadge==='function'?rhIaStatusBadge(it.status):rhEsc(it.status))
      +'<div style="font-size:10px;color:#666;margin-top:2px">'+rhEsc(rhCtIaSituacaoLabel(it))+'</div></td>'
      +'<td style="white-space:nowrap">'+acoes+'</td></tr>');
  });

  kitVis.forEach(function(kit){
    if(kit.arquivo_url || kit.ia_item_id) return;
    if(kit.status_kit==='Nao se aplica'||kit.status_kit==='Dispensado') return;
    if(!kit.obrigatorio && kit.status_kit==='Pendente'){
      /* ainda mostrar obrigatórios e pendentes relevantes */
    }
    var jaIa = rhCtIaItemPorTipo(kit.tipo_documento);
    if(jaIa) return;
    rows.push('<tr style="background:#FFFBF5">'
      +'<td><b>'+rhEsc(kit.tipo_documento)+'</b></td>'
      +'<td>—</td><td>—</td>'
      +'<td style="color:#854F0B">Pendente</td>'
      +'<td><button type="button" class="btn btn-sm" onclick="document.getElementById(\'rh-ct-ia-file\').click()">Solicitar / Enviar</button></td></tr>');
  });

  if(!rows.length){
    return '<div style="font-size:12px;color:#888;padding:10px">Nenhum documento neste processo ainda. Envie um lote acima.</div>';
  }
  return '<div style="overflow-x:auto"><table class="tbl" style="font-size:12px;min-width:720px"><thead><tr>'
    +'<th>Documento</th><th>Arquivo</th><th>Identificação</th><th>Status</th><th>Ação</th></tr></thead><tbody>'
    +rows.join('')+'</tbody></table></div>';
}

function rhCtIaSelecaoHtml(){
  if(!(_rhIaSelecao||[]).length){
    return '<div style="font-size:12px;color:#888;padding:6px 0">Nenhum arquivo na seleção deste lote.</div>';
  }
  return '<table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr style="background:#F5F5F0;text-align:left">'
    +'<th style="padding:6px">Arquivo</th><th>Tamanho</th><th>Status</th><th>Aviso</th><th></th></tr></thead><tbody>'
    +_rhIaSelecao.map(function(s,idx){
      return '<tr style="border-top:.5px solid #e8e8e0">'
        +'<td style="padding:6px">'+rhEsc(s.nome)+'</td>'
        +'<td>'+(typeof rhIaFmtBytes==='function'?rhIaFmtBytes(s.tamanho):s.tamanho)+'</td>'
        +'<td>'+rhEsc(s.uiStatus)+'</td>'
        +'<td style="color:#A32D2D;font-size:11px">'
          +(s.erro?rhEsc(s.erro):'')
          +(s.avisoHist?'<div style="color:#854F0B">Possível documento duplicado.</div>':'')
        +'</td>'
        +'<td>'+(!_rhIaUploadBusy?'<button type="button" class="btn btn-sm" onclick="rhIaRemoverSelecao('+idx+');rhCtIaAposSelecao()">Remover</button>':'')+'</td></tr>';
    }).join('')+'</tbody></table>';
}

function rhCtIaAposSelecao(){
  var el = document.getElementById('rh-ct-ia-selecao');
  if(el) el.innerHTML = rhCtIaSelecaoHtml();
  var prog = document.getElementById('rh-ct-ia-progresso');
  if(prog && typeof rhIaProgressoHtml==='function'){
    /* opcional */
  }
}

function rhCtIaBindDrop(){
  var zone = document.getElementById('rh-ct-ia-drop');
  if(!zone || zone._rhCtIaBound) return;
  zone._rhCtIaBound = true;
  zone.addEventListener('dragover', function(e){
    e.preventDefault();
    zone.style.borderColor='#185FA5';
    zone.style.background='#EBF4FD';
  });
  zone.addEventListener('dragleave', function(){
    zone.style.borderColor='#c5d4e8';
    zone.style.background='#F7FAFC';
  });
  zone.addEventListener('drop', function(e){
    e.preventDefault();
    zone.style.borderColor='#c5d4e8';
    zone.style.background='#F7FAFC';
    rhCtIaSetContexto();
    var files = e.dataTransfer && e.dataTransfer.files ? Array.prototype.slice.call(e.dataTransfer.files) : [];
    if(typeof rhIaAdicionarArquivos==='function') rhIaAdicionarArquivos(files);
  });
}

function rhCtIaOnFiles(inp){
  rhCtIaSetContexto();
  var files = inp && inp.files ? Array.prototype.slice.call(inp.files) : [];
  if(inp) inp.value = '';
  if(typeof rhIaAdicionarArquivos==='function') rhIaAdicionarArquivos(files);
}

async function rhCtIaEnviarStaging(){
  rhCtIaSetContexto();
  if(!_rhCtAtual || !_rhCtAtual.id){
    progShowToast('Salve o rascunho do processo antes de enviar documentos.','erro');
    return;
  }
  if(typeof rhIaIniciarUpload!=='function'){
    progShowToast('Entrada Inteligente indisponível.','erro');
    return;
  }
  try{
    await rhIaIniciarUpload();
  }catch(e){
    progShowToast((e&&e.message)||'Falha no upload.','erro');
  }
  await rhCtIaRefreshPainel();
}

async function rhCtIaProcessarPendentes(){
  rhCtIaSetContexto();
  if(typeof rhIaProcessarPendentes!=='function'){
    progShowToast('Processamento IA indisponível.','erro');
    return;
  }
  try{ await rhIaProcessarPendentes(); }catch(e){}
  await rhCtIaRefreshPainel();
}

async function rhCtIaRefreshPainel(){
  if(!document.getElementById('rh-contratacao-docs-inteligente')) return;
  rhCtIaSetContexto();
  try{
    if(typeof rhIaCarregarFila==='function') await rhIaCarregarFila();
  }catch(e){}
  await rhCtIaCarregarMatriz();
  var m = document.getElementById('rh-ct-ia-matriz');
  if(m) m.innerHTML = rhCtIaMatrizHtml();
  var g = document.getElementById('rh-ct-ia-grade');
  if(g) g.innerHTML = rhCtIaGradeHtml();
  rhCtIaAposSelecao();
}

async function rhCtIaInitPainel(){
  if(!document.getElementById('rh-contratacao-docs-inteligente')) return;
  rhCtIaSetContexto();
  rhCtIaBindDrop();
  if(typeof rhIaProbeTabelas==='function'){
    try{ await rhIaProbeTabelas(); }catch(e){}
  }
  await rhCtIaRefreshPainel();
}

function rhCtIaAbrirCaixaCompleta(){
  rhCtIaSetContexto();
  if(typeof showPage==='function') showPage('rh-entrada-ia');
  else if(typeof showMain==='function'){ showMain('rh'); if(typeof showSub==='function') showSub('rh-entrada-ia'); }
}

