  var kitRows=kitVis.map(function(it){
    var st=it.status_kit||'Pendente';
    var dest=rhKitGeraPendencia(it)||rhKitGeraConferencia(it);
    var dim=(st==='Nao se aplica'||st==='Dispensado');
    return '<tr'+(dim?' style="opacity:.55"':(dest?'':' style="opacity:.92"'))+'>'
      +'<td><b>'+rhEsc(it.tipo_documento)+'</b></td><td>'+rhEsc(it.categoria||'')+'</td><td>'+rhEsc(it.origem_esperada||'')+'</td>'
      +'<td>'+(it.obrigatorio?'Sim':'Não')+'</td>'
      +'<td>'+rhEsc(st)+'</td><td style="font-size:11px">'+rhEsc(it.motivo_exigencia||'')+'</td>'
      +'<td>'+rhCtKitAcoesHtml(it)+'</td></tr>';
  }).join('')||'<tr><td colspan="7" style="padding:1rem;color:#aaa;text-align:center">Preencha a etapa 1 (e atividade quando aplicável) para montar o kit.</td></tr>';
  var da=_rhCtAtual.dados_admissionais; if(typeof da==='string'){ try{da=JSON.parse(da);}catch(e){da={};} }
  da=da||{};
  var camposPrev=['nome_completo','data_nascimento','rg_numero','rg_orgao_emissor','cep','logradouro','cidade','uf','pis_nit'];
  var dadosCards=camposPrev.map(function(k){
    var item=da[k], val=item&&item.valor, st=item?item.status:'SEM_DADO';
    return '<div style="border:1px solid #eee;border-radius:8px;padding:8px;font-size:11px">'
      +'<div style="color:#888">'+rhEsc(k)+'</div>'
      +'<div style="font-weight:600">'+(val?rhEsc(String(val)):'—')+'</div>'
      +'<div style="color:#666">'+rhEsc(st)+(item&&item.fonte?' · '+rhEsc(item.fonte):'')+'</div></div>';
  }).join('');
  var depJson=_rhCtAtual.dependentes_rascunho||[];
  if(typeof depJson==='string'){ try{depJson=JSON.parse(depJson);}catch(e){depJson=[];} }
  var depHtml=[0,1,2].map(function(i){
    var d=depJson[i]||{};
    return '<div class="g2"><div class="fg"><label>Dependente '+(i+1)+' — nome</label><input class="inp" id="rh-ct-dep-nome-'+(i+1)+'" value="'+rhEsc(d.nome||'')+'"/></div>'
      +'<div class="fg"><label>Parentesco</label><input class="inp" id="rh-ct-dep-par-'+(i+1)+'" value="'+rhEsc(d.parentesco||'filho')+'"/></div>'
      +'<div class="fg"><label>Nascimento</label><input class="inp" type="date" id="rh-ct-dep-dn-'+(i+1)+'" value="'+rhEsc(d.data_nascimento||'')+'"/></div></div>';
  }).join('');
  var deps=rhCtBool('tem_dependentes');
