  var maxLab = (typeof rhIaFmtBytes==='function'?rhIaFmtBytes(maxBytes):(Math.round(maxBytes/1024/1024)+' MB'));

  return '<div style="font-size:12px;color:#666;margin-bottom:8px">RH-2A — Documentos e Dados. Necessários: <b>'+r.total+'</b> · Recebidos/validados: <b>'+r.ok+'</b> · Falta arquivo: <b>'+r.pend+'</b> · Conferência: <b>'+r.conf+'</b>. IA sugere; RH confirma. Sem templates.</div>'
    +rhCtIaContextoBannerHtml()
    +(!_rhCtAtual.admitido_em?'<div style="margin-bottom:8px;padding:8px 10px;background:#EBF4FD;color:#185FA5;font-size:12px">Documentos e dados ficam neste processo até a efetivação. Não cria colaborador só por receber arquivos.</div>':'')
    +(inconsist?'<div style="margin-bottom:8px;padding:8px 10px;background:#FCEBEB;color:#A32D2D;font-size:12px">Atividade marca dirigir=Sim sem CNH no kit — anexe a CNH na Entrada Inteligente abaixo.</div>':'')

    +'<div id="rh-contratacao-docs-inteligente" style="margin-bottom:16px;border:1px solid #B5D4F4;border-radius:12px;overflow:hidden;background:#fff">'
    +'<div style="padding:12px 14px;background:#F0F7FF;border-bottom:1px solid #D6E8FA">'
    +'<div style="font-weight:700;font-size:14px;color:#185FA5">Entrada Inteligente de Documentos do Candidato</div>'
