    +'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px">'
    +'<button type="button" class="btn" onclick="document.getElementById(\'rh-ct-ia-file\').click()">Selecionar arquivos</button>'
    +'<button type="button" class="btn btn-pri" onclick="rhCtIaEnviarStaging()">Enviar para staging</button>'
    +'<button type="button" class="btn" onclick="rhCtIaProcessarPendentes()">Processar pendentes (IA)</button>'
    +'<button type="button" class="btn" onclick="rhCtIaAbrirCaixaCompleta()">Abrir caixa completa</button>'
    +'<button type="button" class="btn" onclick="rhCtRepararKitUi()">Corrigir tipos do kit</button>'
    +'<button type="button" class="btn" onclick="rhCtIaRefreshPainel()">Atualizar</button>'
