    +'<div class="fg" style="margin-bottom:10px"><label>Empresa empregadora (tokens EMPRESA_*)</label>'
    +(typeof rhDocSelectEmpresaProcessoHtml==='function'?rhDocSelectEmpresaProcessoHtml(_rhCtAtual.empresa_empregadora_id):'<span style="color:#888">—</span>')
    +'<div style="font-size:11px;color:#666;margin-top:4px">Cadastro oficial: Contratação → aba Empregadora. Não inventa razão social/CNPJ.</div>'
    +'</div>'
    +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:8px;margin-bottom:12px">'
