  if(!col||!col.id) return;
  var hoje=rhEvtDataStr(new Date().toISOString());
  var origem=contratacaoId?('rh_contratacao:'+String(contratacaoId)+':pre_admissao'):('pre_admissao:'+String(col.id)+':'+hoje);
