var _rhSel = {lista:[], atual:null, matriz:null, matrizItens:{}, catalogoTestes:[], vagaTestes:[], cargoTestes:[], vagaTestesDisponivel:true, view:'lista', carregado:false, disponivel:false, erro:'', filtro:'', filtroStatus:''};
var _rhSelEnt = {lista:[], filtro:{}, atalho:'proximas', atual:null, criterios:{}, mode:'agenda'};
var _rhSelCandEntByCand = {}; // candidatura_id -> entrevistas[]
var _rhSelIntByCand = {}; // candidatura_id -> análise
var _rhSelIntItens = {}; // integridade_id -> itens[]
var _rhSelIntFiltro = ''; // filtro lista: '', NAO_INICIADA, EM_ANALISE, PENDENTE, CONCLUIDA
var _rhSelResByCand = {}; // candidatura_id -> resultado
var _rhSelResFiltro = ''; // filtro resultado lista
function rhSelSqlHint(){ return 'Aplique SQLS/sql_rh_selecao_vagas_fase1a.sql e SQLS/sql_rh_selecao_vagas_fase_sel1a.sql no SQL Editor. O ERP não aplica SQL sozinho.'; }
function rhSelPodeEditar(){
  if(typeof cadPodeEditarCargos==='function') return cadPodeEditarCargos();
  var p=(usuarioLogado&&usuarioLogado.perfil)||'';
  return p==='admin'||p==='diretoria'||p==='dp'||p==='rh'||p==='gestor'||p==='coordenador';
}
/** RH-SEL-1F: detalhe AC/PT e edição de integridade — não inclui gestor/coordenador por padrão. */
function rhSelIntPodeVerDetalhe(){
  var p=String((usuarioLogado&&usuarioLogado.perfil)||'').toLowerCase();
  return p==='admin'||p==='diretoria'||p==='dp'||p==='rh';
}
function rhSelIntPodeEditar(){ return rhSelIntPodeVerDetalhe() && rhSelPodeEditar(); }
/** RH-SEL-1G: decisão final e encaminhamento — não gestor/coordenador por padrão. */
function rhSelResPodeDecidir(){
  var p=String((usuarioLogado&&usuarioLogado.perfil)||'').toLowerCase();
  return (p==='admin'||p==='diretoria'||p==='dp'||p==='rh') && rhSelPodeEditar();
}
function rhSelStatusLabel(st){
  return ({RASCUNHO:'Rascunho',ABERTA:'Aberta',PAUSADA:'Pausada',SUSPENSA:'Pausada',ENCERRADA:'Encerrada',CANCELADA:'Cancelada'})[st]||st||'—';
}
function rhSelTipoLabel(t){
  return ({NOVA_VAGA:'Nova vaga',SUBSTITUICAO:'Substituição',AUMENTO_QUADRO:'Aumento de quadro',TEMPORARIA:'Temporária',OUTRO:'Outro'})[t]||t||'—';
}
function rhSelQtdPlan(v){ var n=parseInt(v&&(v.quantidade_planejada!=null?v.quantidade_planejada:v.quantidade),10); return n>=1?n:1; }
function rhSelQtdPre(v){ var n=parseInt(v&&v.quantidade_preenchida,10); return n>=0?n:0; }
function rhSelQtdDisp(v){ var d=rhSelQtdPlan(v)-rhSelQtdPre(v); return d<0?0:d; }
function rhSelCargoObj(id){
  return (_cad_cargos||[]).filter(function(x){ return String(x.id)===String(id); })[0]||null;
}
function rhSelCargoNome(id){
  var list=_cad_cargos||[];
  var c=list.filter(function(x){ return String(x.id)===String(id); })[0];
  return c?(c.nome||c.descricao||id):id;
}
function rhSelOptCargos(sel){
  return '<option value="">Selecione o cargo…</option>'+(_cad_cargos||[]).map(function(c){
    var id=String(c.id||'');
    return '<option value="'+rhEsc(id)+'"'+(String(sel)===id?' selected':'')+'>'+rhEsc(c.nome||c.descricao||id)+'</option>';
  }).join('');
}
function rhSelOptFiliais(sel){
  return '<option value="">—</option>'+(filiais||[]).map(function(f){
    var id=String(f.id||'');
    return '<option value="'+rhEsc(id)+'"'+(String(sel)===id?' selected':'')+'>'+rhEsc(f.nome||id)+'</option>';
  }).join('');
}
function rhSelOptContratos(sel){
  return '<option value="">—</option>'+(contratos||[]).map(function(c){
    var id=String(c.id||'');
    return '<option value="'+rhEsc(id)+'"'+(String(sel)===id?' selected':'')+'>'+rhEsc(c.nome||c.codigo||id)+'</option>';
  }).join('');
}
function rhSelNormTxt(s){
  return String(s||'').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Z0-9]+/g,' ').trim();
}
function rhSelCargoOficialDoColab(c){
  if(!c) return null;
  if(c.cargo_id){
    var cg=(_cad_cargos||[]).filter(function(x){ return String(x.id)===String(c.cargo_id); })[0];
    if(cg) return cg;
  }
  var nome=String(c.cargo||'').trim();
  if(!nome) return null;
  var exact=(_cad_cargos||[]).filter(function(x){ return rhSelNormTxt(x.nome)===rhSelNormTxt(nome); })[0];
  return exact||{nome:nome, categoria:''};
}
function rhSelCargoEhGestorGerente(cg){
  if(!cg) return false;
  var n=rhSelNormTxt(cg.nome);
  var cat=rhSelNormTxt(cg.categoria);
  if(/\b(ASSISTENTE|AUXILIAR|SECRETARI|ESTAGIARI|APRENDIZ)\b/.test(n)) return false;
  if(/\b(SUPERVISOR|COORDENADOR|DIRETOR|ENCARREGADO)\b/.test(n) && !/\b(GESTOR|GERENTE)\b/.test(n)) return false;
  return /\bGESTOR\b/.test(n) || /\bGERENTE\b/.test(n) || /\bGESTOR\b/.test(cat) || /\bGERENTE\b/.test(cat);
}
function rhSelColabEhGestorGerente(c){
  return rhSelCargoEhGestorGerente(rhSelCargoOficialDoColab(c));
}
function rhSelOptColabs(sel){
  var cols=(colaboradores||[]).filter(function(c){ return c.ativo!==false && !c.deleted_at; });
  return '<option value="">—</option>'+cols.map(function(c){
    var id=String(c.id||'');
    return '<option value="'+rhEsc(id)+'"'+(String(sel)===id?' selected':'')+'>'+rhEsc((c.nome||'')+(c.re?' · '+c.re:''))+'</option>';
  }).join('');
}
function rhSelOptGestores(sel){
  var cols=(colaboradores||[]).filter(function(c){ return c.ativo!==false && !c.deleted_at; });
  var eleg=cols.filter(rhSelColabEhGestorGerente);
  var html='<option value="">—</option>'+eleg.map(function(c){
    var id=String(c.id||'');
    var cg=rhSelCargoOficialDoColab(c);
    return '<option value="'+rhEsc(id)+'" data-rh-sel-gestor="oficial"'+(String(sel)===id?' selected':'')+'>'
      +rhEsc((c.nome||'')+(c.re?' · '+c.re:'')+(cg&&cg.nome?' · '+cg.nome:''))+'</option>';
  }).join('');
  if(sel){
    var ja=eleg.some(function(c){ return String(c.id)===String(sel); });
    if(!ja){
      var legado=rhSelColab(sel)||cols.filter(function(c){ return String(c.id)===String(sel); })[0];
      var lab=legado?((legado.nome||'')+(legado.re?' · '+legado.re:'')):'Responsável legado';
      html+='<option value="'+rhEsc(String(sel))+'" data-rh-sel-gestor="legado" selected>'+rhEsc(lab)+' · atribuição legada</option>';
    }
  }
  return html;
}
function rhSelCarregar(){
  if(DEMO){ _rhSel.carregado=true; _rhSel.disponivel=true; _rhSel.lista=_rhSel.lista||[]; return Promise.resolve(_rhSel.lista); }
  function aplicar(rows){
    _rhSel.carregado=true;
    _rhSel.disponivel=true;
    _rhSel.erro='';
    _rhSel.lista=(rows||[]).filter(function(v){ return v && v.ativo!==false; });
    return _rhSel.lista;
  }
  function falha(){
    _rhSel.carregado=true;
    if(!(_rhSel.lista&&_rhSel.lista.length)){
      _rhSel.disponivel=false;
      _rhSel.erro=rhSelSqlHint();
      _rhSel.lista=[];
    }
    return _rhSel.lista||[];
  }
  return sbFetch('rh_vagas',{select:'id',limit:1}).then(function(probe){
    if(probe===null) return falha();
    return sbFetch('rh_vagas',{order:'created_at.desc',limit:1000}).then(function(rows){
      if(rows===null){
        return sbFetch('rh_vagas',{order:'id.desc',limit:1000}).then(function(rows2){
          if(rows2===null) return falha();
          return aplicar(rows2);
        });
      }
      return aplicar(rows);
    });
  }).catch(falha);
}
function rhSelDashHtml(lista){
  var hoje=new Date().toISOString().slice(0,10);
  var rasc=(lista||[]).filter(function(v){ return v.status==='RASCUNHO'; }).length;
  var abertas=(lista||[]).filter(function(v){ return v.status==='ABERTA'; });
  var pos=abertas.reduce(function(s,v){ return s+rhSelQtdDisp(v); },0);
  var paus=(lista||[]).filter(function(v){ return v.status==='PAUSADA'||v.status==='SUSPENSA'; }).length;
  var venc=(lista||[]).filter(function(v){ return v.status==='ABERTA' && v.data_desejada && String(v.data_desejada).slice(0,10)<hoje; }).length;
  function card(t,n,c,st){
    var on=st!=null?' onclick="rhSelFiltroStatus(\''+st+'\')" style="cursor:pointer;border:.5px solid '+(_rhSel.filtroStatus===st?'#1F4E79':'#e8e6df')+';border-radius:10px;padding:10px 12px;background:#fff;min-width:120px"':' style="border:.5px solid #e8e6df;border-radius:10px;padding:10px 12px;background:#fff;min-width:120px"';
    return '<div'+on+'><div style="font-size:11px;color:#888">'+t+'</div><div style="font-size:22px;font-weight:700;color:'+c+'">'+n+'</div></div>';
  }
  return '<div style="display:flex;flex-wrap:wrap;gap:8px;padding:.4rem 1rem 0">'
    +card('Rascunhos',rasc,'#555','RASCUNHO')
    +card('Vagas abertas',abertas.length,'#1F4E79','ABERTA')
    +card('Posições disponíveis',pos,'#3B6D11')
    +card('Pausadas',paus,'#854F0B','PAUSADA')
    +card('Data desejada vencida',venc,venc?'#A32D2D':'#555')
    +'</div>';
}
function rhSelRender(){
  var wrap=document.getElementById('rh-vagas-wrap'); if(!wrap) return;
  if(!_rhSel.carregado){
    wrap.innerHTML='<div class="card"><div class="ch"><span class="ct">Recrutamento e Seleção</span></div><div style="padding:1.5rem;color:#888">Carregando…</div></div>';
    rhGarantirLookups().then(function(){ return rhSelCarregar(); }).then(function(){ rhSelRender(); });
    return;
  }
  if(_rhSel.view==='ficha'){ rhSelRenderFicha(); return; }
  if(_rhSel.view==='entrevistas' || _rhSel.view==='entrevista_painel'){ rhSelEntRender(); return; }
  var q=(_rhSel.filtro||'').toLowerCase();
  var fs=_rhSel.filtroStatus||'';
  var rows=(_rhSel.lista||[]).filter(function(v){
    if(fs==='RASCUNHO' && v.status!=='RASCUNHO') return false;
    if(fs==='ABERTA' && v.status!=='ABERTA') return false;
    if(fs==='PAUSADA' && v.status!=='PAUSADA' && v.status!=='SUSPENSA') return false;
    if(!q) return true;
    return [v.codigo,v.cargo_nome,v.contrato_nome,v.filial_nome,v.gestor_nome,v.responsavel_rh_nome,v.status].join(' ').toLowerCase().indexOf(q)>=0;
  });
  var pode=rhSelPodeEditar();
  wrap.innerHTML='<div class="card"><div class="ch"><span class="ct">📣 Recrutamento e Seleção</span>'
    +(pode?'<button class="btn btn-pri" onclick="rhSelNova()">+ Nova vaga</button>':'')
    +'</div>'
    +'<div style="padding:.4rem 1rem 0;display:flex;gap:8px;flex-wrap:wrap">'
    +'<button type="button" class="btn btn-sm btn-pri" onclick="_rhSel.view=\'lista\';rhSelRender()">Vagas</button>'
    +'<button type="button" class="btn btn-sm" onclick="_rhSel.view=\'entrevistas\';rhSelEntRender()">Entrevistas</button>'
    +'</div>'
    +'<div style="padding:.6rem 1rem;font-size:12px;color:#666">Vagas + candidatos + entrevistas humanas (RH-SEL-1E). Testes são apoio — sem aprovação automática. SQL entrevistas: sql_rh_selecao_entrevistas_fase_sel1e.sql.</div>'
    +(_rhSel.disponivel?'':'<div style="padding:.6rem 1rem;color:#854F0B;background:#FEF3E2;font-size:12px">'+rhEsc(_rhSel.erro||rhSelSqlHint())+'</div>')
    +rhSelDashHtml(_rhSel.lista)
    +'<div style="padding:.6rem 1rem;display:flex;flex-wrap:wrap;gap:8px;align-items:center">'
    +'<input class="inp" placeholder="Buscar código, cargo, contrato, filial…" style="width:min(100%,320px)" value="'+rhEsc(_rhSel.filtro||'')+'" oninput="_rhSel.filtro=this.value;rhSelRender()"/>'
    +'<select class="inp" style="width:auto" onchange="_rhSel.filtroStatus=this.value;rhSelRender()">'
    +[['','Todos os status'],['RASCUNHO','Rascunho'],['ABERTA','Aberta'],['PAUSADA','Pausada'],['ENCERRADA','Encerrada'],['CANCELADA','Cancelada']].map(function(p){
      return '<option value="'+p[0]+'"'+(fs===p[0]?' selected':'')+'>'+p[1]+'</option>';
    }).join('')+'</select>'
    +'</div>'
    +'<div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Código</th><th>Cargo</th><th>Filial</th><th>Contrato</th><th>Gestor</th><th>Qtd</th><th>Preenchidas</th><th>Status</th><th>Desejada</th><th>RH</th><th></th></tr></thead><tbody>'
    +(rows.map(function(v){
      var id=String(v.id||'').replace(/'/g,'');
      var acoes='<button class="btn btn-sm" onclick="rhSelAbrir(\''+id+'\')">Abrir</button>';
      if(pode && v.status==='ABERTA') acoes+=' <button class="btn btn-sm" onclick="rhSelSetStatus(\''+id+'\',\'PAUSADA\')">Pausar</button>';
      if(pode && (v.status==='ABERTA'||v.status==='PAUSADA'||v.status==='SUSPENSA')) acoes+=' <button class="btn btn-sm" onclick="rhSelSetStatus(\''+id+'\',\'ENCERRADA\')">Encerrar</button>';
      if(pode && v.status!=='CANCELADA' && v.status!=='ENCERRADA') acoes+=' <button class="btn btn-sm" style="color:#A32D2D;border-color:#A32D2D" onclick="rhSelSetStatus(\''+id+'\',\'CANCELADA\')">Cancelar</button>';
      return '<tr><td>'+rhEsc(v.codigo||'—')+'</td><td>'+rhEsc(v.cargo_nome||rhSelCargoNome(v.cargo_id))+'</td>'
        +'<td>'+rhEsc(v.filial_nome||'—')+'</td><td>'+rhEsc(v.contrato_nome||'—')+'</td>'
        +'<td>'+rhEsc(v.gestor_nome||'—')+'</td>'
        +'<td>'+rhSelQtdPlan(v)+'</td><td>'+rhSelQtdPre(v)+'</td>'
        +'<td>'+rhEsc(rhSelStatusLabel(v.status))+'</td>'
        +'<td>'+rhEsc(v.data_desejada?String(v.data_desejada).slice(0,10):'—')+'</td>'
        +'<td>'+rhEsc(v.responsavel_rh_nome||'—')+'</td>'
        +'<td style="white-space:nowrap">'+acoes+'</td></tr>';
    }).join('')||'<tr><td colspan="11" style="padding:1.5rem;text-align:center;color:#aaa">Nenhuma vaga. '+(pode?'Clique em Nova vaga.':'')+'</td></tr>')
    +'</tbody></table></div></div>';
}
function rhSelFiltroStatus(st){
  _rhSel.filtroStatus=(_rhSel.filtroStatus===st)?'':st;
  rhSelRender();
}
function rhSelNova(){
  if(!rhSelPodeEditar()){ progShowToast('Sem permissão para criar vaga.','erro'); return; }
  if(!_rhSel.disponivel && !DEMO){ progShowToast(_rhSel.erro||rhSelSqlHint(),'erro'); return; }
  _rhSel.atual={status:'RASCUNHO',quantidade:1,quantidade_planejada:1,quantidade_preenchida:0,empresa:'CENA',tipo_vaga:'NOVA_VAGA',ativo:true};
  _rhSel.matriz=null; _rhSel.matrizItens={}; _rhSel.catalogoTestes=[]; _rhSel.vagaTestes=[]; _rhSel.cargoTestes=[]; _rhSel.view='ficha';
  rhSelRender();
}
function rhSelAbrir(id){
  var v=(_rhSel.lista||[]).filter(function(x){ return String(x.id)===String(id); })[0];
  if(!v && !DEMO){
    sbFetch('rh_vagas',{filters:['id=eq.'+id],limit:1}).then(function(r){
      _rhSel.atual=(r&&r[0])||null;
      if(!_rhSel.atual){ progShowToast('Vaga não encontrada.','erro'); return; }
      rhSelCarregarFilhos();
    });
    return;
  }
  _rhSel.atual=v||null;
  rhSelCarregarFilhos();
}
function rhSelCarregarFilhos(){
  var v=_rhSel.atual; if(!v) return;
  Promise.all([
    rhSelCarregarMatriz(v.cargo_id),
    rhSelCarregarVagaTestes(v)
  ]).then(function(){ _rhSel.view='ficha'; rhSelRender(); });
}
function rhSelCarregarCargoTestes(cargoId){
  _rhSel.cargoTestes=[];
  if(!cargoId || DEMO) return Promise.resolve([]);
  return Promise.all([
    sbFetch('rh_cargo_testes',{filters:['cargo_id=eq.'+cargoId,'ativo=eq.true'],order:'ordem.asc',limit:100}),
    sbFetch('rh_testes',{filters:['ativo=eq.true'],limit:500})
  ]).then(function(arr){
    if(arr[0]===null){ _rhSel.vagaTestesDisponivel=false; return []; }
    _rhSel.vagaTestesDisponivel=true;
    var cat=arr[1]||[];
    var byId={}; cat.forEach(function(t){ if(t&&t.id) byId[String(t.id)]=t; });
    _rhSel.catalogoTestes=cat;
    if(!_rhCargoTestes.byId) _rhCargoTestes.byId={};
    cat.forEach(function(t){ if(t&&t.id) _rhCargoTestes.byId[String(t.id)]=t; });
    _rhCargoTestes.catalogo=cat;
    _rhSel.cargoTestes=(arr[0]||[]).map(function(r){
      var t=byId[String(r.teste_id)]||{};
      return Object.assign({}, r, {teste_nome:t.nome, teste_codigo:t.codigo, teste_versao:t.versao, _teste:t});
    });
    return _rhSel.cargoTestes;
  }).catch(function(){ _rhSel.vagaTestesDisponivel=false; return []; });
}
function rhSelCarregarVagaTestes(v){
  _rhSel.vagaTestes=[];
  if(!v||!v.id||DEMO){
    return rhSelCarregarCargoTestes(v&&v.cargo_id);
  }
  return sbFetch('rh_vaga_testes',{filters:['vaga_id=eq.'+v.id],order:'ordem.asc',limit:200}).then(function(rows){
    if(rows===null){ _rhSel.vagaTestesDisponivel=false; return rhSelCarregarCargoTestes(v.cargo_id); }
    _rhSel.vagaTestesDisponivel=true;
    _rhSel.vagaTestes=rows||[];
    return rhSelCarregarCargoTestes(v.cargo_id);
  }).catch(function(){ return rhSelCarregarCargoTestes(v.cargo_id); });
}
function rhSelCarregarMatriz(cargoId){
  _rhSel.matriz=null; _rhSel.matrizItens={};
  if(!cargoId || DEMO) return Promise.resolve();
  return sbFetch('rh_cargo_requisitos',{filters:['cargo_id=eq.'+cargoId,'ativo=eq.true'],limit:1}).then(function(r){
    _rhSel.matriz=(r&&r[0])||null;
    if(!_rhSel.matriz) return;
    return Promise.all([
      sbFetch('rh_cargo_requisitos_cnh',{filters:['cargo_id=eq.'+cargoId,'ativo=eq.true'],limit:50}),
      sbFetch('rh_cargo_requisitos_nrs',{filters:['cargo_id=eq.'+cargoId,'ativo=eq.true'],limit:50}),
      sbFetch('rh_cargo_requisitos_treinamentos',{filters:['cargo_id=eq.'+cargoId,'ativo=eq.true'],limit:50}),
      sbFetch('rh_cargo_requisitos_documentos',{filters:['cargo_id=eq.'+cargoId,'ativo=eq.true'],limit:50}),
      sbFetch('rh_cargo_requisitos_testes',{filters:['cargo_id=eq.'+cargoId,'ativo=eq.true'],limit:50})
    ]).then(function(arr){
      _rhSel.matrizItens={cnh:arr[0]||[],nrs:arr[1]||[],trein:arr[2]||[],docs:arr[3]||[],testes:arr[4]||[]};
      return sbFetch('rh_testes',{filters:['cargo_id=eq.'+cargoId,'ativo=eq.true'],order:'perfil.asc'});
    }).then(function(cat){
      _rhSel.catalogoTestes=cat||[];
    });
  }).catch(function(){});
}
function rhSelVoltar(){ _rhSel.view='lista'; _rhSel.atual=null; rhSelCarregar().then(function(){ rhSelRender(); }); }
function rhSelColab(id){
  return (colaboradores||[]).filter(function(c){ return String(c.id)===String(id); })[0]||null;
}
function rhSelProximoCodigo(){
  var y=String(new Date().getFullYear());
  var max=0;
  (_rhSel.lista||[]).forEach(function(v){
    var m=String(v.codigo||'').match(new RegExp('^VAG-'+y+'-(\\d+)$'));
    if(m) max=Math.max(max,parseInt(m[1],10)||0);
  });
  return 'VAG-'+y+'-'+String(max+1).padStart(4,'0');
}
function rhSelLerForm(){
  var cargoId=((document.getElementById('rh-sel-cargo')||{}).value)||'';
  var filId=((document.getElementById('rh-sel-filial')||{}).value)||'';
  var ctId=((document.getElementById('rh-sel-contrato')||{}).value)||'';
  var geId=((document.getElementById('rh-sel-gestor')||{}).value)||'';
  var rhId=((document.getElementById('rh-sel-rh')||{}).value)||'';
  var fil=(filiais||[]).filter(function(f){ return String(f.id)===filId; })[0];
  var ct=(contratos||[]).filter(function(c){ return String(c.id)===ctId; })[0];
  var ge=rhSelColab(geId);
  var rh=rhSelColab(rhId);
  var plan=parseInt((document.getElementById('rh-sel-qtd')||{}).value,10);
  var pre=parseInt((document.getElementById('rh-sel-pre')||{}).value,10);
  if(!(plan>=1)) plan=1;
  if(!(pre>=0)) pre=0;
  if(pre>plan) pre=plan;
  var st=((document.getElementById('rh-sel-status')||{}).value)||'RASCUNHO';
  return {
    cargo_id:cargoId,
    cargo_nome:rhSelCargoNome(cargoId),
    empresa:((document.getElementById('rh-sel-emp')||{}).value||'CENA').trim()||'CENA',
    filial_id:filId||null,
    filial_nome:fil?(fil.nome||''):null,
    local_trabalho:((document.getElementById('rh-sel-local')||{}).value||'').trim()||null,
    contrato_id:ctId||null,
    contrato_nome:ct?(ct.nome||ct.codigo||''):null,
    projeto:((document.getElementById('rh-sel-proj')||{}).value||'').trim()||null,
    centro_custo:((document.getElementById('rh-sel-cc')||{}).value||'').trim()||null,
    gestor_id:geId||null,
    gestor_nome:ge?(ge.nome||''):null,
    responsavel_rh_id:rhId||null,
    responsavel_rh_nome:rh?(rh.nome||''):null,
    quantidade:plan,
    quantidade_planejada:plan,
    quantidade_preenchida:pre,
    tipo_vaga:((document.getElementById('rh-sel-tipo')||{}).value)||null,
    motivo:((document.getElementById('rh-sel-motivo')||{}).value||'').trim()||null,
    data_abertura:((document.getElementById('rh-sel-dab')||{}).value)||null,
    data_desejada:((document.getElementById('rh-sel-ddes')||{}).value)||null,
    status:st,
    matriz_status:(_rhSel.matriz&&_rhSel.matriz.status)||'NAO_CONFIGURADA',
    observacoes:((document.getElementById('rh-sel-obs')||{}).value||'').trim()||null,
    updated_at:new Date().toISOString()
  };
}
function rhSelMatrizAprovada(){ return _rhSel.matriz && _rhSel.matriz.status==='APROVADA'; }
function rhSelSalvar(){
  if(!rhSelPodeEditar()){ progShowToast('Sem permissão para editar vaga.','erro'); return; }
  var p=rhSelLerForm();
  if(!p.cargo_id){ progShowToast('Selecione o cargo oficial.','erro'); return; }
  var origGe=(_rhSel.atual&&_rhSel.atual.gestor_id)||'';
  if(p.gestor_id && String(p.gestor_id)!==String(origGe)){
    var geNovo=rhSelColab(p.gestor_id);
    if(!rhSelColabEhGestorGerente(geNovo)){
      progShowToast('O campo Gestor aceita somente Gestores ou Gerentes ativos do cadastro oficial.','erro');
      return;
    }
  }
  if(p.status==='ABERTA' && !rhSelMatrizAprovada()){
    progShowToast('Não é possível marcar ABERTA sem Matriz de Requisitos aprovada.','erro');
    return;
  }
  var antes=_rhSel.atual?(_rhSel.atual.status||''):'';
  if(DEMO){
    if(!_rhSel.atual.id){ _rhSel.atual=Object.assign({id:'vg'+Date.now(),codigo:rhSelProximoCodigo(),created_at:new Date().toISOString()},p); _rhSel.lista.unshift(_rhSel.atual); }
    else Object.assign(_rhSel.atual,p);
    progShowToast('Vaga salva (demo).'); rhSelRender(); return;
  }
  function ok(row){
    _rhSel.atual=row;
    var i=_rhSel.lista.findIndex(function(x){ return String(x.id)===String(row.id); });
    if(i>=0) _rhSel.lista[i]=row; else _rhSel.lista.unshift(row);
    var ev=antes===row.status?'EDITOU_VAGA':(row.status==='ABERTA'?'ABRIU_VAGA':(row.status==='PAUSADA'||row.status==='SUSPENSA'?'PAUSOU_VAGA':(row.status==='ENCERRADA'?'ENCERROU_VAGA':(row.status==='CANCELADA'?'CANCELOU_VAGA':'EDITOU_VAGA'))));
    if(!antes) ev='CRIOU_VAGA';
    if(typeof auditLog==='function') auditLog('editar','rh',ev+' '+(row.codigo||row.id),{antes:antes,depois:row.status,cargo_id:row.cargo_id});
    progShowToast('Vaga salva.');
    rhSelVagaGarantirSnapshot(row).then(function(){ rhSelCarregarFilhos(); });
  }
  if(_rhSel.atual&&_rhSel.atual.id){
    sbUpdate('rh_vagas',p,'id=eq.'+_rhSel.atual.id).then(function(r){
      if(!r){ progShowToast('Falha ao atualizar a vaga. Aplique sql_rh_selecao_vagas_fase_sel1a.sql.','erro'); return; }
      ok(Array.isArray(r)?(r[0]||Object.assign(_rhSel.atual,p)):r);
    });
  } else {
    p.criado_por=usuarioLogado?(usuarioLogado.nome||usuarioLogado.email):null;
    p.ativo=true;
    if(!p.data_abertura) p.data_abertura=new Date().toISOString().slice(0,10);
    sbFetch('rh_vagas',{select:'codigo',limit:1000}).then(function(existentes){
      var y=String(new Date().getFullYear());
      var max=0;
      (existentes||[]).concat(_rhSel.lista||[]).forEach(function(v){
        var m=String(v.codigo||'').match(new RegExp('^VAG-'+y+'-(\\d+)$'));
        if(m) max=Math.max(max,parseInt(m[1],10)||0);
      });
      p.codigo='VAG-'+y+'-'+String(max+1).padStart(4,'0');
      return sbInsert('rh_vagas',p);
    }).then(function(r){
      if(!r||!r[0]){ progShowToast('Falha ao criar a vaga. '+rhSelSqlHint(),'erro'); return; }
      ok(r[0]);
    });
  }
}
function rhSelSetStatus(id, st){
  if(!rhSelPodeEditar()) return;
  var v=(_rhSel.lista||[]).filter(function(x){ return String(x.id)===String(id); })[0];
  if(!v){ progShowToast('Vaga não encontrada.','erro'); return; }
  if(st==='ABERTA'){
    _rhSel.atual=v;
    rhSelCarregarMatriz(v.cargo_id).then(function(){
      if(!rhSelMatrizAprovada()){ progShowToast('Este cargo ainda não possui Matriz de Requisitos aprovada.','erro'); return; }
      rhSelAplicarStatus(v,st);
    });
    return;
  }
  rhSelAplicarStatus(v,st);
}
function rhSelAplicarStatus(v,st){
  var payload={status:st,updated_at:new Date().toISOString()};
  if(DEMO){ v.status=st; rhSelRender(); return; }
  sbUpdate('rh_vagas',payload,'id=eq.'+v.id).then(function(r){
    if(!r){ progShowToast('Falha ao alterar status.','erro'); return; }
    v.status=st;
    var ev=st==='PAUSADA'||st==='SUSPENSA'?'PAUSOU_VAGA':(st==='ENCERRADA'?'ENCERROU_VAGA':(st==='CANCELADA'?'CANCELOU_VAGA':'EDITOU_VAGA'));
    if(typeof auditLog==='function') auditLog('editar','rh',ev+' '+(v.codigo||v.id),{depois:st});
    rhSelRender();
  });
}
function rhSelOnCargoChange(){
  var id=(document.getElementById('rh-sel-cargo')||{}).value;
  if(_rhSel.atual) _rhSel.atual.cargo_id=id;
  var cargoBox=document.getElementById('rh-sel-cargo-txt');
  if(cargoBox) cargoBox.innerHTML=rhSelCargoDescHtml(id);
  if(!id){
    _rhSel.matriz=null; _rhSel.matrizItens={}; _rhSel.cargoTestes=[];
    var b=document.getElementById('rh-sel-matriz'); if(b) b.innerHTML=rhSelMatrizHtml();
    var a=document.getElementById('rh-sel-avaliacoes'); if(a) a.innerHTML=rhSelAvaliacoesHtml();
    return;
  }
  Promise.all([
    rhSelCarregarMatriz(id),
    rhSelCarregarCargoTestes(id)
  ]).then(function(){
    var b=document.getElementById('rh-sel-matriz'); if(b) b.innerHTML=rhSelMatrizHtml();
    var a=document.getElementById('rh-sel-avaliacoes'); if(a) a.innerHTML=rhSelAvaliacoesHtml();
  });
}
function rhSelVagaLinhaHtml(r, origem){
  var nome=r.teste_nome||(r._teste&&r._teste.nome)||r.teste_codigo||r.teste_id;
  var bits=[];
  bits.push(r.obrigatorio!==false?'Obrigatório':'Opcional');
  bits.push(r.eliminatorio?'Eliminatório':'não eliminatório');
  if(r.nota_minima!=null) bits.push('mínimo '+r.nota_minima+'%');
  if(r.tentativas_maximas) bits.push((r.tentativas_maximas)+' tentativa'+(Number(r.tentativas_maximas)===1?'':'s'));
  bits.push(rhCargoTestesEtapaLabel(r.etapa_processo));
  var orig=origem||r.origem||'HERDADO_DO_CARGO';
  var origLab=orig==='ADICIONADO_NA_VAGA'?'Adicionado na vaga':'Herdado do cargo';
  return '<div style="padding:6px 0;border-bottom:.5px solid #f0efe8">'
    +'<div>✓ <b>'+rhEsc(nome)+'</b>'+(r.teste_versao?' <span style="font-size:10px;color:#888">v'+rhEsc(r.teste_versao)+'</span>':'')
    +' <span style="font-size:10px;background:#eef5fb;color:#185FA5;border-radius:4px;padding:1px 6px">'+rhEsc(origLab)+'</span>'
    +(r.ativo===false?' <span style="font-size:10px;color:#888">inativo</span>':'')+'</div>'
    +'<div style="font-size:11px;color:#666;padding-left:16px">'+rhEsc(bits.join(' · '))+'</div></div>';
}
function rhSelVagaGarantirSnapshot(row){
  if(!row||!row.id||DEMO) return Promise.resolve();
  if(_rhSel.vagaTestesDisponivel===false) return Promise.resolve();
  return sbFetch('rh_vaga_testes',{filters:['vaga_id=eq.'+row.id,'ativo=eq.true'],limit:50}).then(function(exist){
    if(exist===null){ _rhSel.vagaTestesDisponivel=false; return; }
    if(exist&&exist.length){ _rhSel.vagaTestes=exist; return; }
    return rhSelCarregarCargoTestes(row.cargo_id).then(function(){
      var src=(_rhSel.cargoTestes||[]).filter(function(x){ return x.ativo!==false; });
      if(!src.length){ _rhSel.vagaTestes=[]; return; }
      var payload=src.map(function(x,i){
        return {
          vaga_id:row.id,
          cargo_id:row.cargo_id||null,
          teste_id:x.teste_id,
          teste_codigo:x.teste_codigo||null,
          teste_nome:x.teste_nome||null,
          teste_versao:x.teste_versao||null,
          origem:'HERDADO_DO_CARGO',
          obrigatorio:x.obrigatorio!==false,
          eliminatorio:!!x.eliminatorio,
          nota_minima:x.nota_minima!=null?x.nota_minima:null,
          tentativas_maximas:x.tentativas_maximas||1,
          ordem:x.ordem||(i+1),
          etapa_processo:x.etapa_processo||'ANTES_ENTREVISTA',
          ativo:true,
          criado_por:rhCargoTestesQuem(),
          criado_em:new Date().toISOString(),
          atualizado_em:new Date().toISOString()
        };
      });
      return sbInsert('rh_vaga_testes', payload.length===1?payload[0]:payload).then(function(r){
        _rhSel.vagaTestes=Array.isArray(r)?r:(r?[r]:payload);
      });
    });
  });
}
function rhSelCargoDescHtml(cargoId){
  var c=rhSelCargoObj(cargoId);
  if(!c) return '<div style="font-size:12px;color:#888">Selecione o cargo para ver Objeto da Função e Atividades.</div>';
  var obj=String(c.objeto_funcao||'').trim();
  var at=String(c.descricao_atividades_responsabilidades||'').trim();
  return '<div style="font-size:12px"><div style="font-weight:700;margin-bottom:4px">Objeto da Função</div>'
    +'<div style="white-space:pre-wrap;color:#333;margin-bottom:10px">'+(obj?rhEsc(obj):'<span style="color:#aaa">Não informado no cadastro mestre.</span>')+'</div>'
    +'<div style="font-weight:700;margin-bottom:4px">Atividades / Responsabilidades</div>'
    +'<div style="white-space:pre-wrap;color:#333">'+(at?rhEsc(at):'<span style="color:#aaa">Não informado no cadastro mestre.</span>')+'</div></div>';
}
function rhSelItensResumo(arr, labelFn){
  if(!arr||!arr.length) return '—';
  return arr.map(function(x){ return rhEsc(labelFn(x)); }).join(', ');
}
function rhSelMatrizHtml(){
  var m=_rhSel.matriz;
  var it=_rhSel.matrizItens||{};
  if(!m) return '<div style="font-size:12px;color:#854F0B;background:#FEF3E2;padding:8px;border-radius:8px">Este cargo ainda não possui Matriz de Requisitos. O rascunho pode ser salvo; <b>ABERTA</b> exige matriz aprovada. Em Cadastros → Cargos → Requisitos use <b>Importar do SESMT</b> (trilha + docs de contratação).</div>';
  var st=m.status||'NAO_CONFIGURADA';
  var lab=({NAO_CONFIGURADA:'Não configurada',EM_CONFIGURACAO:'Em configuração',APROVADA:'Aprovada'})[st]||st;
  var cor=st==='APROVADA'?'#3B6D11':(st==='EM_CONFIGURACAO'?'#854F0B':'#888');
  var alerta=st!=='APROVADA'
    ?'<div style="font-size:12px;color:#854F0B;background:#FEF3E2;padding:8px;border-radius:8px;margin-bottom:8px">Este cargo ainda não possui Matriz de Requisitos aprovada. Complete/aprove em Cadastros → Cargos → Requisitos (pode importar trilha e docs SESMT).</div>':'';
  var vaziaTreino=!(it.trein&&it.trein.length); var vaziaDoc=!(it.docs&&it.docs.length);
  var dicaSesmt=(vaziaTreino||vaziaDoc)
    ?'<div style="font-size:11px;color:#555;background:#f7f7f4;padding:6px 8px;border-radius:8px;margin-bottom:8px">Matriz sem '+(vaziaTreino&&vaziaDoc?'treinamentos e documentos':vaziaTreino?'treinamentos':'documentos')+'. Sugestão: <b>Importar do SESMT</b> na aba Requisitos do cargo.</div>':'';
  function nrLab(x){ return (typeof rhMatrizNormaLabel==='function'?rhMatrizNormaLabel(x.norma_id):x.norma_id); }
  function curLab(x){ return (typeof rhMatrizCursoLabel==='function'?rhMatrizCursoLabel(x.curso_id):x.curso_id); }
  function docLab(x){ return (typeof rhMatrizDocLabel==='function'?rhMatrizDocLabel(x.tipo_documento_id):x.tipo_documento_id); }
  return alerta+dicaSesmt+'<div style="font-size:12px">Status da matriz: <b style="color:'+cor+'">'+rhEsc(lab)+'</b></div>'
    +'<div style="font-size:12px;margin-top:8px;display:grid;gap:4px">'
    +'<div><b>CNH:</b> '+(m.exige_cnh?'Sim':'Não')+(it.cnh&&it.cnh.length?' — '+rhSelItensResumo(it.cnh,function(x){return x.categoria; }):'')+'</div>'
    +'<div><b>NRs:</b> '+rhSelItensResumo(it.nrs,nrLab)+'</div>'
    +'<div><b>Treinamentos:</b> '+rhSelItensResumo(it.trein,curLab)+'</div>'
    +'<div><b>ASO:</b> '+(m.exige_aso?'Obrigatório':'Não informado')+'</div>'
    +'<div><b>Documentos:</b> '+rhSelItensResumo(it.docs,docLab)+'</div>'
    +'<div><b>Jornada/regime:</b> '+rhEsc(m.regime_jornada||'—')+(m.regime_beneficio?' · benefício '+rhEsc(m.regime_beneficio):'')+'</div>'
    +'<div><b>Cargo de confiança:</b> '+(m.cargo_confianca?'Sim':'Não')+'</div>'
    +'<div><b>Testes de aptidão:</b> '+(m.exige_teste_aptidao?'Sim':'Não')+(it.testes&&it.testes.length?' — '+rhSelItensResumo(it.testes,function(x){return x.perfil; }):'')+'</div>'
    +'</div><div style="font-size:11px;color:#888;margin-top:6px">Somente leitura. A regra oficial permanece na RH-1B. Sem versionamento da matriz nesta fase — gravamos só o status no save.</div>';
}
function rhSelAvaliacoesHtml(){
  var pode=rhSelPodeEditar();
  var snap=(_rhSel.vagaTestes||[]).filter(function(x){ return x && x.ativo!==false; });
  var preview=(_rhSel.cargoTestes||[]).filter(function(x){ return x && x.ativo!==false; });
  var temSnap=!!((_rhSel.atual&&_rhSel.atual.id)&&snap.length);
  var list=temSnap?snap:preview;
  var html='';
  if(_rhSel.vagaTestesDisponivel===false){
    html+='<div style="font-size:12px;color:#854F0B;background:#FEF3E2;padding:8px;border-radius:8px;margin-bottom:8px">'+rhEsc(rhCargoTestesSqlHint())+'</div>';
  }
  if(temSnap){
    html+='<div style="font-size:12px;margin-bottom:6px">Snapshot desta vaga. Se o cargo mudar a nota mínima depois, esta vaga <b>não</b> altera o critério.</div>';
  } else if(list.length){
    html+='<div style="font-size:12px;margin-bottom:6px">Prévia herdada do cargo. Ao salvar a vaga, esses testes viram snapshot do processo.</div>';
  } else {
    html+='<div style="font-size:12px;color:#888;margin-bottom:6px">Nenhum teste ativo neste cargo. Vincule em Cadastros → Cargos → Testes e Avaliações.</div>';
  }
  html+=list.map(function(r){ return rhSelVagaLinhaHtml(r, temSnap?r.origem:'HERDADO_DO_CARGO'); }).join('')
    ||'<div style="font-size:12px;color:#aaa">Nenhum teste na vaga.</div>';
  if(pode && _rhSel.atual && _rhSel.atual.id && _rhSel.vagaTestesDisponivel!==false){
    html+='<div style="margin-top:10px"><button type="button" class="btn btn-sm" onclick="rhSelVagaAddComplementar()">+ Adicionar avaliação complementar</button>'
      +'<div style="font-size:11px;color:#888;margin-top:4px">Complementar vale só nesta vaga. Não altera a matriz do cargo.</div>'
      +'<div id="rh-sel-vaga-comp"></div></div>';
  } else if(pode && !(_rhSel.atual&&_rhSel.atual.id)){
    html+='<div style="font-size:11px;color:#888;margin-top:8px">Salve a vaga para gravar o snapshot e, se preciso, adicionar avaliação complementar.</div>';
  }
  return html;
}
function rhSelVagaAddComplementar(){
  var box=document.getElementById('rh-sel-vaga-comp'); if(!box) return;
  var usados={};
  (_rhSel.vagaTestes||[]).forEach(function(x){ if(x&&x.ativo!==false) usados[String(x.teste_id)]=true; });
  var opts=((_rhCargoTestes.catalogo&&_rhCargoTestes.catalogo.length)?_rhCargoTestes.catalogo:(_rhSel.catalogoTestes||[])).slice();
  if(!opts.length){
    sbFetch('rh_testes',{filters:['ativo=eq.true'],limit:500}).then(function(rows){
      _rhCargoTestes.catalogo=rows||[];
      (rows||[]).forEach(function(t){ if(t&&t.id) _rhCargoTestes.byId[String(t.id)]=t; });
      rhSelVagaAddComplementar();
    });
    box.innerHTML='<div style="color:#888;margin-top:6px">Carregando Banco de Testes…</div>';
    return;
  }
  var byCod={};
  opts.forEach(function(t){
    if(!t||t.ativo===false||usados[String(t.id)]) return;
    var k=String(t.codigo||t.id);
    if(!byCod[k] || Number(t.versao||1)>Number(byCod[k].versao||1)) byCod[k]=t;
  });
  var pubs=Object.keys(byCod).map(function(k){ return byCod[k]; });
  box.innerHTML='<div style="border:.5px solid #e8e6df;border-radius:8px;padding:8px;margin-top:8px">'
    +'<label style="font-size:11px">Teste complementar (somente esta vaga)</label>'
    +'<select class="inp" id="rh-sel-comp-teste"><option value="">Selecione…</option>'
    +pubs.map(function(t){ return '<option value="'+rhEsc(String(t.id))+'">'+rhEsc((t.nome||t.codigo)+' · v'+(t.versao||1))+'</option>'; }).join('')
    +'</select>'
    +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;margin-top:8px">'
    +'<div><label style="font-size:11px">Obrigatório</label><select class="inp" id="rh-sel-comp-obrig"><option value="1">Sim</option><option value="0">Não</option></select></div>'
    +'<div><label style="font-size:11px">Eliminatório</label><select class="inp" id="rh-sel-comp-elim"><option value="0">Não</option><option value="1">Sim</option></select></div>'
    +'<div><label style="font-size:11px">Nota mín. %</label><input class="inp" id="rh-sel-comp-nota" type="number" min="0" max="100"/></div>'
    +'</div>'
    +'<div style="margin-top:8px"><button type="button" class="btn btn-pri btn-sm" onclick="rhSelVagaSalvarComplementar()">Incluir na vaga</button> '
    +'<button type="button" class="btn btn-sm" onclick="this.parentNode.parentNode.innerHTML=\'\'">Cancelar</button></div></div>';
}
function rhSelVagaSalvarComplementar(){
  var v=_rhSel.atual; if(!v||!v.id){ progShowToast('Salve a vaga primeiro.','erro'); return; }
  var tid=((document.getElementById('rh-sel-comp-teste')||{}).value)||'';
  if(!tid){ progShowToast('Selecione o teste.','erro'); return; }
  if((_rhSel.vagaTestes||[]).some(function(x){ return x.ativo!==false && String(x.teste_id)===String(tid); })){
    progShowToast('Este teste já está no snapshot da vaga.','erro'); return;
  }
  var t=(_rhCargoTestes.byId&&_rhCargoTestes.byId[String(tid)])||((_rhSel.catalogoTestes||[]).filter(function(x){ return String(x.id)===String(tid); })[0])||{};
  var nota=((document.getElementById('rh-sel-comp-nota')||{}).value);
  var payload={
    vaga_id:v.id,
    cargo_id:v.cargo_id||null,
    teste_id:tid,
    teste_codigo:t.codigo||null,
    teste_nome:t.nome||null,
    teste_versao:t.versao||null,
    origem:'ADICIONADO_NA_VAGA',
    obrigatorio:((document.getElementById('rh-sel-comp-obrig')||{}).value)!=='0',
    eliminatorio:((document.getElementById('rh-sel-comp-elim')||{}).value)==='1',
    nota_minima:(nota===''||nota==null)?null:Number(nota),
    tentativas_maximas:1,
    ordem:((_rhSel.vagaTestes||[]).length||0)+1,
    etapa_processo:'ANTES_ENTREVISTA',
    ativo:true,
    criado_por:rhCargoTestesQuem(),
    criado_em:new Date().toISOString(),
    atualizado_em:new Date().toISOString()
  };
  sbInsert('rh_vaga_testes',payload).then(function(r){
    if(!r||!r[0]){ progShowToast('Falha ao incluir. '+rhCargoTestesSqlHint(),'erro'); return; }
    progShowToast('Avaliação complementar incluída só nesta vaga.');
    rhSelCarregarVagaTestes(v).then(function(){
      var a=document.getElementById('rh-sel-avaliacoes'); if(a) a.innerHTML=rhSelAvaliacoesHtml();
    });
  });
}
function rhSelBloco(t, html){
  return '<div style="border:.5px solid #eee;border-radius:10px;padding:10px 12px;margin:0 0 10px"><div style="font-weight:700;font-size:12px;margin-bottom:8px;color:#1F4E79">'+t+'</div>'+html+'</div>';
}
function rhSelRenderFicha(){
  var wrap=document.getElementById('rh-vagas-wrap'); if(!wrap) return;
  var v=_rhSel.atual||{};
  var pode=rhSelPodeEditar();
  var dis=pode?'':' disabled';
  var stAtual=v.status==='SUSPENSA'?'PAUSADA':(v.status||'RASCUNHO');
  wrap.innerHTML='<div class="card"><div class="ch"><span class="ct">'+(v.id?'Vaga '+rhEsc(v.codigo||''):'Nova vaga')+'</span>'
    +'<button class="btn" onclick="rhSelVoltar()">← Lista</button></div>'
    +'<div style="padding:1rem">'
    +rhSelBloco('1. Identificação',
      '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px">'
      +'<div><label style="font-size:11px">Código</label><input class="inp" value="'+rhEsc(v.codigo||'(gerado ao salvar)')+'" disabled/></div>'
      +'<div><label style="font-size:11px">Status</label><select class="inp" id="rh-sel-status"'+dis+'>'
      +['RASCUNHO','ABERTA','PAUSADA','ENCERRADA','CANCELADA'].map(function(s){
        return '<option value="'+s+'"'+(stAtual===s?' selected':'')+'>'+rhSelStatusLabel(s)+'</option>';
      }).join('')+'</select></div>'
      +'<div><label style="font-size:11px">Cargo oficial *</label><select class="inp" id="rh-sel-cargo"'+dis+' onchange="rhSelOnCargoChange()">'+rhSelOptCargos(v.cargo_id)+'</select></div>'
      +'<div><label style="font-size:11px">Tipo</label><select class="inp" id="rh-sel-tipo"'+dis+'>'
      +[['NOVA_VAGA','Nova vaga'],['SUBSTITUICAO','Substituição'],['AUMENTO_QUADRO','Aumento de quadro'],['TEMPORARIA','Temporária'],['OUTRO','Outro']].map(function(p){
        return '<option value="'+p[0]+'"'+(v.tipo_vaga===p[0]?' selected':'')+'>'+p[1]+'</option>';
      }).join('')+'</select></div></div>')
    +rhSelBloco('2. Localização',
      '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px">'
      +'<div><label style="font-size:11px">Empresa</label><input class="inp" id="rh-sel-emp"'+dis+' value="'+rhEsc(v.empresa||'CENA')+'"/></div>'
      +'<div><label style="font-size:11px">Filial</label><select class="inp" id="rh-sel-filial"'+dis+'>'+rhSelOptFiliais(v.filial_id)+'</select></div>'
      +'<div><label style="font-size:11px">Local de trabalho</label><input class="inp" id="rh-sel-local"'+dis+' value="'+rhEsc(v.local_trabalho||'')+'"/></div></div>')
    +rhSelBloco('3. Necessidade',
      '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px">'
      +'<div><label style="font-size:11px">Quantidade planejada</label><input class="inp" id="rh-sel-qtd" type="number" min="1"'+dis+' value="'+rhSelQtdPlan(v)+'"/></div>'
      +'<div><label style="font-size:11px">Preenchidas</label><input class="inp" id="rh-sel-pre" type="number" min="0"'+dis+' value="'+rhSelQtdPre(v)+'"/></div>'
      +'<div><label style="font-size:11px">Disponíveis</label><input class="inp" value="'+rhSelQtdDisp(v)+'" disabled/></div>'
      +'<div><label style="font-size:11px">Data de abertura</label><input class="inp" id="rh-sel-dab" type="date"'+dis+' value="'+rhEsc(v.data_abertura?String(v.data_abertura).slice(0,10):'')+'"/></div>'
      +'<div><label style="font-size:11px">Data desejada</label><input class="inp" id="rh-sel-ddes" type="date"'+dis+' value="'+rhEsc(v.data_desejada?String(v.data_desejada).slice(0,10):'')+'"/></div>'
      +'<div style="grid-column:1/-1"><label style="font-size:11px">Motivo</label><textarea class="inp" id="rh-sel-motivo" rows="2"'+dis+'>'+rhEsc(v.motivo||'')+'</textarea></div></div>')
    +rhSelBloco('4. Responsáveis',
      '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px">'
      +'<div><label style="font-size:11px">Gestor / requisitante</label><select class="inp" id="rh-sel-gestor"'+dis+'>'+rhSelOptGestores(v.gestor_id)+'</select>'
      +(v.gestor_id && !rhSelColabEhGestorGerente(rhSelColab(v.gestor_id))
        ?'<div data-rh-sel-gestor-legado="1" style="font-size:11px;color:#854F0B;margin-top:4px">Atribuição legada: o responsável salvo nesta vaga não é Gestor/Gerente ativo. O valor histórico é preservado. Só será exigida uma seleção válida se você alterar o campo.</div>':'')
      +'</div>'
      +'<div><label style="font-size:11px">Responsável RH</label><select class="inp" id="rh-sel-rh"'+dis+'>'+rhSelOptColabs(v.responsavel_rh_id)+'</select></div></div>')
    +rhSelBloco('5. Projeto / Contrato',
      '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px">'
      +'<div><label style="font-size:11px">Contrato</label><select class="inp" id="rh-sel-contrato"'+dis+'>'+rhSelOptContratos(v.contrato_id)+'</select></div>'
      +'<div><label style="font-size:11px">Projeto</label><input class="inp" id="rh-sel-proj"'+dis+' value="'+rhEsc(v.projeto||'')+'"/></div>'
      +'<div><label style="font-size:11px">Centro de custo</label><input class="inp" id="rh-sel-cc"'+dis+' value="'+rhEsc(v.centro_custo||'')+'"/></div></div>')
    +rhSelBloco('6. Cargo (Cadastro Mestre)',
      '<div id="rh-sel-cargo-txt">'+rhSelCargoDescHtml(v.cargo_id)+'</div>')
    +rhSelBloco('7. Matriz de Requisitos (RH-1B, só leitura)',
      '<div id="rh-sel-matriz">'+rhSelMatrizHtml()+'</div>')
    +rhSelBloco('Testes / avaliações herdados do cargo',
      '<div id="rh-sel-avaliacoes">'+rhSelAvaliacoesHtml()+'</div>')
    +rhSelBloco('8. Candidatos', rhSelCandidatosHtml(v, pode))
    +'<div><label style="font-size:11px">Observações</label><textarea class="inp" id="rh-sel-obs" rows="2"'+dis+'>'+rhEsc(v.observacoes||'')+'</textarea></div>'
    +(pode?'<div style="margin-top:12px"><button class="btn btn-pri" onclick="rhSelSalvar()">Salvar vaga</button></div>':'')
    +'</div></div>';
  if(v && v.id) setTimeout(function(){ rhSelCandidatosCarregar(v.id); }, 0);
}

// =============================================================================
// RH-SEL-1B — Convites individuais + QR local (reutiliza rh_vaga_candidatos)
// =============================================================================
var _rhSelCand = { lista:[], vagaId:null, carregando:false };
/** Segredos só em memória da sessão (nunca localStorage/sessionStorage). */
var _rhSelCandSecretMem = {};

function rhSelConviteExigeAuth(){
  if(!_sbAuthToken){
    progShowToast('Esta operação exige sessão segura Supabase Auth.','erro');
    return false;
  }
  return true;
}
function rhSelFmtDt(iso){
  if(!iso) return '—';
  try{
    var d=new Date(iso);
    if(isNaN(d.getTime())) return String(iso).slice(0,16);
    return d.toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
  }catch(e){ return '—'; }
}
function rhSelCandStatusLabel(s){
  var m={CONVIDADO:'Convidado',INICIOU:'Iniciou',IDENTIFICADO:'Identificado',
    TESTES_EM_ANDAMENTO:'Testes em andamento',TESTES_CONCLUIDOS:'Testes concluídos',
    ENTREVISTA_AGENDADA:'Entrevista agendada',ENTREVISTAS_EM_ANDAMENTO:'Entrevistas em andamento',
    ENTREVISTAS_CONCLUIDAS:'Entrevistas concluídas',
    INTEGRIDADE_EM_ANALISE:'Integridade em análise',INTEGRIDADE_CONCLUIDA:'Integridade concluída',
    EM_DECISAO_FINAL:'Em decisão final',APROVADO_PARA_ADMISSAO:'Aprovado para admissão',
    NAO_SELECIONADO:'Não selecionado',ENCAMINHADO_ADMISSAO:'Encaminhado para admissão',
    CONCLUIU:'Concluiu',EXPIRADO:'Expirado',REVOGADO:'Revogado',
    INSCRITO:'Inscrito',EM_ANALISE:'Em análise',DESISTENTE:'Desistente',DESCARTADO:'Descartado'};
  return m[s]||s||'—';
}
function rhSelCpfMascarado(cpf){
  var d=String(cpf||'').replace(/\D/g,'');
  if(d.length!==11) return cpf?'***':'—';
  return '***.***.***-'+d.slice(9);
}
function rhSelCpfDigits(v){
  if(typeof rhPortalCpfDigits==='function') return rhPortalCpfDigits(v);
  return String(v||'').replace(/\D/g,'');
}
function rhSelCpfValido(v){
  if(typeof rhPortalCpfValido==='function') return rhPortalCpfValido(v);
  var cpf=rhSelCpfDigits(v);
  return cpf.length===11 && !/^(\d)\1{10}$/.test(cpf);
}
/** Corrige CPF da candidatura (digits). Usado quando o convite/portal gravou CPF errado. */
function rhSelCandCorrigirCpf(candId, cpfNovo){
  if(!rhSelPodeEditar()){ progShowToast('Sem permissão para corrigir CPF.','erro'); return Promise.resolve(false); }
  var id=String(candId||'').trim();
  var dig=rhSelCpfDigits(cpfNovo);
  if(!id){ progShowToast('Candidato inválido.','erro'); return Promise.resolve(false); }
  if(!rhSelCpfValido(dig)){ progShowToast('CPF inválido. Use 11 dígitos.','erro'); return Promise.resolve(false); }
  var c=(_rhSelCand.lista||[]).filter(function(x){ return String(x.id)===id; })[0];
  var antes=c?String(c.cpf||''):'';
  if(rhSelCpfDigits(antes)===dig){ progShowToast('CPF já está '+dig+'.'); return Promise.resolve(true); }
  var dup=(_rhSelCand.lista||[]).find(function(x){
    return String(x.id)!==id && rhSelCpfDigits(x.cpf)===dig;
  });
  if(dup){ progShowToast('⚠ Já existe candidato nesta vaga com esse CPF ('+rhEsc(dup.nome)+').','erro'); return Promise.resolve(false); }
  if(DEMO){
    if(c) c.cpf=dig;
    if(typeof auditLog==='function') auditLog('editar','rh','Corrigiu CPF do candidato',{tabela:'rh_vaga_candidatos',id:id,anterior:antes,novo:dig});
    rhSelCandidatosRenderLista();
    if(document.getElementById('rh-sel-cand-detalhe')&&!document.getElementById('rh-sel-cand-detalhe').classList.contains('hidden')) rhSelCandDetalhe(id);
    progShowToast('✅ CPF atualizado (demo) para '+dig+'.');
    return Promise.resolve(true);
  }
  return Promise.resolve(sbUpdate('rh_vaga_candidatos',{cpf:dig,updated_at:new Date().toISOString()},'id=eq.'+id)).then(function(ok){
    if(ok===false){ progShowToast('❌ Não gravou o CPF.','erro'); return false; }
    if(c) c.cpf=dig;
    if(typeof auditLog==='function') auditLog('editar','rh','Corrigiu CPF do candidato',{tabela:'rh_vaga_candidatos',id:id,anterior:antes,novo:dig,nome:c&&c.nome});
    rhSelCandidatosRenderLista();
    if(document.getElementById('rh-sel-cand-detalhe')&&!document.getElementById('rh-sel-cand-detalhe').classList.contains('hidden')) rhSelCandDetalhe(id);
    progShowToast('✅ CPF corrigido para '+dig+'.');
    return true;
  });
}
/** Prompt / atalho: se a lista tiver 1 candidato, corrige esse; senão pede id. */
function rhSelCandCorrigirCpfPrompt(cpfNovo, candId){
  var dig=rhSelCpfDigits(cpfNovo||'');
  if(!dig){
    dig=rhSelCpfDigits(window.prompt('Novo CPF (somente números):','04416606818')||'');
  }
  if(!rhSelCpfValido(dig)){ progShowToast('CPF inválido.','erro'); return; }
  var id=candId?String(candId):'';
  if(!id){
    var lista=_rhSelCand.lista||[];
    if(lista.length===1) id=String(lista[0].id);
    else if(lista.length>1){
      var nomes=lista.map(function(c,i){ return (i+1)+') '+(c.nome||c.id); }).join('\n');
      var n=parseInt(window.prompt('Qual candidato?\n'+nomes+'\nDigite o número:','1'),10);
      if(!n||!lista[n-1]){ progShowToast('Cancelado.','erro'); return; }
      id=String(lista[n-1].id);
    }
  }
  if(!id){ progShowToast('Nenhum candidato na lista. Abra a vaga e tente de novo.','erro'); return; }
  var c=(_rhSelCand.lista||[]).filter(function(x){ return String(x.id)===id; })[0];
  if(!confirm('Corrigir CPF de "'+(c&&c.nome||id)+'" para '+dig+'?')) return;
  rhSelCandCorrigirCpf(id, dig);
}
function rhSelIsLinkLocal(){
  var proto=String(location.protocol||'');
  var host=String(location.hostname||'').toLowerCase();
  return proto==='file:' || host==='localhost' || host==='127.0.0.1' || host==='';
}
function rhSelConviteBaseUrl(){
  return String(location.href||'').split('#')[0].split('?')[0];
}
/** Link público: usa ?candidato= (WhatsApp/e-mail removem #fragmento). */
function rhSelConviteLink(fragment){
  var base=rhSelConviteBaseUrl();
  var frag=String(fragment||'');
  var sep=base.indexOf('?')>=0?'&':'?';
  return base+sep+'candidato='+encodeURIComponent(frag);
}
function rhSelCandidatosHtml(v, pode){
  if(!v || !v.id){
    return '<div style="font-size:12px;color:#666">Salve a vaga para convidar candidatos. Identificação, testes e entrevistas ficam na candidatura.</div>';
  }
  var st=v.status==='SUSPENSA'?'PAUSADA':(v.status||'');
  var podeConv=pode && st==='ABERTA';
  return '<div style="font-size:12px;color:#666;margin-bottom:8px">Convite → identificação → testes → entrevistas → integridade → <b>resultado humano</b> (RH-SEL-1G). Sem score automático; admissão só no módulo Contratação/Promoção.</div>'
    +(podeConv?'<div style="margin-bottom:10px"><button type="button" class="btn btn-pri" onclick="rhSelConviteAbrirModal()">+ Convidar candidato</button></div>':'')
    +(!podeConv && pode?'<div style="font-size:11px;color:#854F0B;margin-bottom:8px">Convites só com vaga <b>ABERTA</b>.</div>':'')
    +'<div style="margin-bottom:8px;display:flex;flex-wrap:wrap;gap:8px;align-items:center">'
    +'<label style="font-size:12px;color:#555">Integridade:</label>'
    +'<select class="inp" style="width:auto" id="rh-sel-f-int" onchange="_rhSelIntFiltro=this.value;rhSelCandidatosRenderLista()">'
    +'<option value="">Todas</option>'
    +'<option value="NAO_INICIADA">Não iniciada</option>'
    +'<option value="EM_ANALISE">Em análise</option>'
    +'<option value="PENDENTE">Com pendência</option>'
    +'<option value="CONCLUIDA">Concluída</option></select>'
    +'<label style="font-size:12px;color:#555;margin-left:8px">Resultado:</label>'
    +'<select class="inp" style="width:auto" id="rh-sel-f-res" onchange="_rhSelResFiltro=this.value;rhSelCandidatosRenderLista()">'
    +'<option value="">Todos</option>'
    +'<option value="AGUARDANDO">Aguardando decisão</option>'
    +'<option value="APROVADO">Aprovado p/ admissão</option>'
    +'<option value="NAO">Não selecionado</option>'
    +'<option value="ENC">Encaminhado</option></select></div>'
    +'<div id="rh-sel-cands-lista" style="font-size:12px;color:#888">Carregando candidatos…</div>'
    +'<div id="rh-sel-cand-detalhe" class="hidden"></div>'
    +'<div id="rh-sel-ent-modal" class="hidden"></div>'
    +'<div id="rh-sel-int-modal" class="hidden"></div>'
    +'<div id="rh-sel-res-modal" class="hidden"></div>'
    +'<div id="rh-sel-convite-modal" class="hidden"></div>';
}
function rhSelCandidatosCarregar(vagaId){
  _rhSelCand.vagaId=vagaId;
  var el=document.getElementById('rh-sel-cands-lista');
  if(!el) return;
  el.textContent='Carregando candidatos…';
  if(DEMO){
    _rhSelCand.lista=[];
    _rhSelCandEntByCand={};
    _rhSelIntByCand={};
    _rhSelResByCand={};
    rhSelCandidatosRenderLista();
    return;
  }
  Promise.all([
    sbFetch('rh_vaga_candidatos',{filters:['vaga_id=eq.'+encodeURIComponent(vagaId),'ativo=eq.true'],order:'convite_criado_em.desc'}),
    sbFetch('rh_candidato_entrevistas',{filters:['vaga_id=eq.'+encodeURIComponent(vagaId)],order:'agendada_para.asc',limit:500}).catch(function(){return null;}),
    sbFetch('rh_candidato_integridade',{filters:['vaga_id=eq.'+encodeURIComponent(vagaId)],limit:500}).catch(function(){return null;}),
    sbFetch('rh_candidato_resultado_selecao',{filters:['vaga_id=eq.'+encodeURIComponent(vagaId)],limit:500}).catch(function(){return null;})
  ]).then(function(arr){
    _rhSelCand.lista=arr[0]||[];
    _rhSelCandEntByCand={};
    (arr[1]||[]).forEach(function(e){
      var k=String(e.candidatura_id);
      if(!_rhSelCandEntByCand[k]) _rhSelCandEntByCand[k]=[];
      _rhSelCandEntByCand[k].push(e);
    });
    _rhSelIntByCand={};
    (arr[2]||[]).forEach(function(a){ _rhSelIntByCand[String(a.candidatura_id)]=a; });
    _rhSelResByCand={};
    (arr[3]||[]).forEach(function(r){ _rhSelResByCand[String(r.candidatura_id)]=r; });
    var sel=document.getElementById('rh-sel-f-int');
    if(sel) sel.value=_rhSelIntFiltro||'';
    var selR=document.getElementById('rh-sel-f-res');
    if(selR) selR.value=_rhSelResFiltro||'';
    rhSelCandidatosRenderLista();
  }).catch(function(){
    el.innerHTML='<div style="color:#854F0B;background:#FEF3E2;padding:8px;border-radius:8px">Não foi possível listar candidatos. Confira SQLs 1B–1G.</div>';
  });
}
function rhSelEntResumoCand(cid){
  var ents=_rhSelCandEntByCand[String(cid)]||[];
  if(!ents.length) return '— Não iniciada';
  var ativas=ents.filter(function(e){ return e.status==='AGENDADA'||e.status==='EM_ANDAMENTO'; });
  var conc=ents.filter(function(e){ return e.status==='CONCLUIDA'; });
  var nc=ents.filter(function(e){ return e.status==='NAO_COMPARECEU'; });
  if(ativas.length){
    var e=ativas[0];
    if(e.status==='EM_ANDAMENTO') return '🟡 Em andamento';
    return '📅 Agendada '+(e.agendada_para?rhSelFmtDt(e.agendada_para):'');
  }
  if(nc.length && !conc.length) return '⚠ Não compareceu';
  if(conc.length) return '✅ Concluída ('+conc.length+')';
  return '—';
}
function rhSelCandidatosRenderLista(){
  var el=document.getElementById('rh-sel-cands-lista'); if(!el) return;
  var rows=_rhSelCand.lista||[];
  var fInt=_rhSelIntFiltro||'';
  if(fInt){
    rows=rows.filter(function(c){
      var a=_rhSelIntByCand[String(c.id)];
      var st=a?a.status_analise:'';
      if(fInt==='NAO_INICIADA') return !a || st==='NAO_INICIADA';
      if(fInt==='EM_ANALISE') return st==='EM_ANALISE';
      if(fInt==='CONCLUIDA') return st==='CONCLUIDA' || c.status==='INTEGRIDADE_CONCLUIDA' || c.integridade_concluida_em;
      if(fInt==='PENDENTE') return st==='PENDENTE_REVISAO' || st==='EM_ANALISE';
      return true;
    });
  }
  var fRes=_rhSelResFiltro||'';
  if(fRes){
    rows=rows.filter(function(c){
      var r=_rhSelResByCand[String(c.id)];
      var st=c.status||'';
      if(fRes==='AGUARDANDO') return (!r || r.decisao==='EM_ANALISE') && (st==='INTEGRIDADE_CONCLUIDA'||st==='EM_DECISAO_FINAL');
      if(fRes==='APROVADO') return st==='APROVADO_PARA_ADMISSAO' || (r&&r.decisao==='APROVADO_PARA_ADMISSAO'&&st!=='ENCAMINHADO_ADMISSAO'&&st!=='NAO_SELECIONADO');
      if(fRes==='NAO') return st==='NAO_SELECIONADO' || (r&&r.decisao==='NAO_SELECIONADO');
      if(fRes==='ENC') return st==='ENCAMINHADO_ADMISSAO' || (r&&r.status==='ENCAMINHADO_ADMISSAO');
      return true;
    });
  }
  if(!rows.length){
    el.innerHTML='<div style="padding:12px;text-align:center;color:#aaa;border:1px dashed #ddd;border-radius:8px">'+(fInt||fRes?'Nenhum candidato neste filtro.':'Nenhum candidato convidado ainda.')+'</div>';
    return;
  }
  var pode=rhSelPodeEditar();
  el.innerHTML='<div style="overflow-x:auto"><table class="tbl"><thead><tr>'
    +'<th>Candidato</th><th>Telefone</th><th>E-mail</th><th>CPF</th><th>Status</th><th>ID</th><th>Testes</th><th>Entrevista</th><th>Integridade</th><th>Resultado</th><th>Último acesso</th><th></th>'
    +'</tr></thead><tbody>'
    +rows.map(function(c){
      var id=String(c.id||'').replace(/'/g,'');
      var temSec=_rhSelCandSecretMem[id];
      var idOk=!!c.identificacao_concluida_em;
      var tstLab='—';
      if(c.status==='TESTES_CONCLUIDOS'||c.testes_concluidos_em||c.status==='ENTREVISTA_AGENDADA'||c.status==='ENTREVISTAS_EM_ANDAMENTO'||c.status==='ENTREVISTAS_CONCLUIDAS'||c.status==='INTEGRIDADE_EM_ANALISE'||c.status==='INTEGRIDADE_CONCLUIDA'||c.status==='EM_DECISAO_FINAL'||c.status==='APROVADO_PARA_ADMISSAO'||c.status==='NAO_SELECIONADO'||c.status==='ENCAMINHADO_ADMISSAO') tstLab='Concluídos';
      else if(c.status==='TESTES_EM_ANDAMENTO'||c.testes_iniciados_em) tstLab='Em andamento';
      else if(idOk) tstLab='Pendentes';
      var elegivel=typeof rhSelEntElegivel==='function' && rhSelEntElegivel(c).ok;
      var acoes='<button class="btn btn-sm" onclick="rhSelCandDetalhe(\''+id+'\')">Detalhe</button> ';
      if(pode && elegivel) acoes+='<button class="btn btn-sm btn-pri" onclick="rhSelEntAbrirAgendar(\''+id+'\')">Agendar entrevista</button> ';
      if(rhSelResPodeDecidir() && (c.status==='INTEGRIDADE_CONCLUIDA'||c.status==='EM_DECISAO_FINAL'||c.status==='APROVADO_PARA_ADMISSAO'||c.status==='NAO_SELECIONADO'||c.status==='ENCAMINHADO_ADMISSAO'))
        acoes+='<button class="btn btn-sm" onclick="rhSelCandDetalhe(\''+id+'\')">Resultado</button> ';
      if(pode){
        if(temSec) acoes+='<button class="btn btn-sm" onclick="rhSelConviteVerQr(\''+id+'\')">Ver QR</button> ';
        if(c.status!=='REVOGADO'){
          acoes+='<button class="btn btn-sm" onclick="rhSelConviteReemitir(\''+id+'\')">Reemitir</button> ';
          acoes+='<button class="btn btn-sm" onclick="rhSelConviteRevogar(\''+id+'\')">Revogar</button>';
        } else {
          acoes+='<button class="btn btn-sm" onclick="rhSelConviteReemitir(\''+id+'\')">Reemitir</button>';
        }
      }
      return '<tr><td><b>'+rhEsc(c.nome)+'</b></td><td>'+rhEsc(c.telefone||'—')+'</td><td>'+rhEsc(c.email||'—')+'</td>'
        +'<td style="font-size:11px">'+rhEsc(rhSelCpfMascarado(c.cpf))+'</td>'
        +'<td>'+rhEsc(rhSelCandStatusLabel(c.status))+'</td>'
        +'<td>'+(idOk?'✓':'—')+'</td>'
        +'<td style="font-size:11px">'+rhEsc(tstLab)+'</td>'
        +'<td style="font-size:11px">'+rhEsc(rhSelEntResumoCand(id))+'</td>'
        +'<td style="font-size:11px">'+rhEsc(rhSelIntResumoCand(id))+'</td>'
        +'<td style="font-size:11px">'+rhEsc(rhSelResResumoCand(id,c))+'</td>'
        +'<td style="font-size:11px">'+rhEsc(rhSelFmtDt(c.convite_ultimo_acesso_em))+'</td>'
        +'<td style="white-space:nowrap">'+acoes+'</td></tr>';
    }).join('')
    +'</tbody></table></div>';
}
function rhSelCandDetalhe(id){
  var c=(_rhSelCand.lista||[]).filter(function(x){ return String(x.id)===String(id); })[0];
  if(!c){ progShowToast('Candidato não encontrado.','erro'); return; }
  var box=document.getElementById('rh-sel-cand-detalhe'); if(!box) return;
  var v=_rhSel.atual||{};
  box.classList.remove('hidden');
  box.innerHTML='<div style="position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:9000;display:flex;align-items:center;justify-content:center;padding:1rem" onclick="if(event.target===this)rhSelCandDetalheFechar()">'
    +'<div style="background:#fff;border-radius:12px;padding:1.1rem;max-width:720px;width:100%;max-height:92vh;overflow:auto" onclick="event.stopPropagation()">'
    +'<div style="font-weight:800;margin-bottom:6px">'+rhEsc(c.nome)+'</div>'
    +'<div id="rh-sel-cand-status-line" style="font-size:12px;color:#666;margin-bottom:10px">Vaga '+rhEsc(v.codigo||'—')+' · '+rhEsc(v.cargo_nome||'—')
    +'<br>Status: <b>'+rhEsc(rhSelCandStatusLabel(c.status))+'</b></div>'
    +'<div style="font-size:13px;line-height:1.55;border-top:1px solid #eee;padding-top:10px">'
    +'<b>Identificação</b><br>'
    +'Telefone: '+rhEsc(c.telefone||'—')+' · E-mail: '+rhEsc(c.email||'—')+'<br>'
    +'CPF: '+rhEsc(rhSelPodeEditar()?(String(c.cpf||'').replace(/\D/g,'')||'—'):rhSelCpfMascarado(c.cpf))
    +(rhSelPodeEditar()?' <button class="btn btn-sm" type="button" onclick="rhSelCandCorrigirCpfPrompt(\'04416606818\',\''+String(id).replace(/'/g,'')+'\')">Corrigir CPF</button>':'')
    +'</div>'
    +'<div id="rh-sel-cand-hist" style="margin-top:12px;font-size:12px;color:#555"></div>'
    +'<div id="rh-sel-cand-avals" style="margin-top:12px;font-size:13px;color:#888">Carregando avaliações…</div>'
    +'<div id="rh-sel-cand-ents" style="margin-top:12px;font-size:13px">Carregando entrevistas…</div>'
    +'<div id="rh-sel-cand-int" style="margin-top:12px;font-size:13px">Carregando integridade…</div>'
    +'<div id="rh-sel-cand-res" style="margin-top:12px;font-size:13px">Carregando resultado…</div>'
    +'<div id="rh-sel-cand-acoes" style="display:flex;flex-wrap:wrap;gap:8px;justify-content:flex-end;margin-top:14px">'
    +'<button class="btn" type="button" onclick="rhSelCandDetalheFechar()">Fechar</button></div>'
    +'<div id="rh-sel-cand-elig-msg" style="font-size:11px;color:#854F0B;margin-top:8px"></div>'
    +'</div></div>';
  rhSelCandDetalheCarregarExtras(id, c);
}
function rhSelCandDetalheAtualizarAcoes(id, c, evidTestesOk){
  var pode=rhSelPodeEditar();
  var podeInt=rhSelIntPodeEditar();
  var elig=rhSelEntElegivel(c, { testesTodosConcluidos: !!evidTestesOk });
  var elA=document.getElementById('rh-sel-cand-acoes');
  var elM=document.getElementById('rh-sel-cand-elig-msg');
  var elS=document.getElementById('rh-sel-cand-status-line');
  var v=_rhSel.atual||{};
  if(elS){
    elS.innerHTML='Vaga '+rhEsc(v.codigo||'—')+' · '+rhEsc(v.cargo_nome||'—')
      +'<br>Status: <b>'+rhEsc(rhSelCandStatusLabel(c.status))+'</b>';
  }
  if(elA){
    var cid=String(id).replace(/'/g,'');
    var podeEncerrar=pode && elig.ok && !c.entrevistas_encerradas_em && c.status!=='ENTREVISTAS_CONCLUIDAS'
      && c.status!=='INTEGRIDADE_EM_ANALISE' && c.status!=='INTEGRIDADE_CONCLUIDA';
    var podeIniciarInt=podeInt && rhSelIntElegivelIniciar(c);
    elA.innerHTML=(pode && elig.ok?'<button class="btn btn-pri" type="button" onclick="rhSelEntAbrirAgendar(\''+cid+'\')">Agendar entrevista</button>':'')
      +(podeEncerrar?'<button class="btn" type="button" onclick="rhSelEntEncerrarEtapa(\''+cid+'\')">Encerrar etapa de entrevistas</button>':'')
      +(podeIniciarInt?'<button class="btn btn-pri" type="button" onclick="rhSelIntIniciar(\''+cid+'\')">Iniciar análise de integridade</button>':'')
      +'<button class="btn" type="button" onclick="rhSelCandDetalheFechar()">Fechar</button>';
  }
  if(elM) elM.textContent=(!elig.ok && elig.motivo)?elig.motivo:'';
}
function rhSelDimLabel(k){
  var m={PERCEPCAO_RISCO:'Percepção de risco',COMUNICACAO:'Comunicação',TOMADA_DECISAO:'Tomada de decisão',
    TRABALHO_EQUIPE:'Trabalho em equipe',FLEXIBILIDADE_COGNITIVA:'Flexibilidade diante de imprevistos',
    DISCIPLINA_OPERACIONAL:'Disciplina operacional',REACAO_PRESSAO:'Reação sob pressão',RESPONSABILIDADE:'Responsabilidade'};
  return m[k]||String(k||'').replace(/_/g,' ').toLowerCase().replace(/\b\w/g,function(c){return c.toUpperCase();});
}
/** Evidência real: tentativas CONCLUIDAS (aceita mesmo se cargo_id do teste ≠ vaga — ex. Linha Viva / LVII). */
function rhSelEntEvidenciaTestesOk(latestByTeste, testesById, cargoId){
  var tids=Object.keys(latestByTeste||{});
  if(!tids.length) return false;
  if(tids.some(function(tid){ return latestByTeste[tid].status==='EM_ANDAMENTO'; })) return false;
  var concluidos=tids.filter(function(tid){ return latestByTeste[tid].status==='CONCLUIDO'; });
  if(!concluidos.length) return false;

  var perfis={};
  concluidos.forEach(function(tid){
    var t=testesById[tid];
    if(t) perfis[String(t.perfil||'').toUpperCase()]=1;
  });

  var snap=(_rhSel.vagaTestes||[]).filter(function(t){ return t && t.ativo!==false && t.obrigatorio!==false; });
  if(snap.length){
    return snap.every(function(t){
      var tent=latestByTeste[String(t.teste_id)];
      return tent && tent.status==='CONCLUIDO';
    });
  }

  var cat=(_rhSel.catalogoTestes||[]).filter(function(t){ return t && t.ativo!==false; });
  if(cat.length && cat.every(function(t){
    var tent=latestByTeste[String(t.id)];
    return tent && tent.status==='CONCLUIDO';
  })) return true;

  var reqs=((_rhSel.matrizItens&&_rhSel.matrizItens.testes)||[]).filter(function(r){ return r && r.ativo!==false; });
  if(reqs.length && reqs.every(function(r){ return !!perfis[String(r.perfil||'').toUpperCase()]; })) return true;

  // Já há avaliações concluídas nesta candidatura e nenhuma pendente
  if(Object.keys(perfis).length>=1) return true;
  void cargoId;
  return concluidos.length>=1;
}
function rhSelEntRepararStatusTestes(c){
  if(!c || !c.id) return Promise.resolve(c);
  if(c.testes_concluidos_em || c.status==='TESTES_CONCLUIDOS' ||
     c.status==='ENTREVISTA_AGENDADA' || c.status==='ENTREVISTAS_EM_ANDAMENTO' ||
     c.status==='ENTREVISTAS_CONCLUIDAS'){
    return Promise.resolve(c);
  }
  var agora=new Date().toISOString();
  return sbUpdate('rh_vaga_candidatos',{
    status:'TESTES_CONCLUIDOS',
    testes_concluidos_em:agora,
    testes_iniciados_em:c.testes_iniciados_em||agora,
    updated_at:agora
  },'id=eq.'+c.id).then(function(){
    c.status='TESTES_CONCLUIDOS';
    c.testes_concluidos_em=agora;
    if(!c.testes_iniciados_em) c.testes_iniciados_em=agora;
    return c;
  }).catch(function(){ return c; });
}
function rhSelCandDetalheCarregarExtras(id, c){
  var hist=[];
  function pintarHist(){
    var elH=document.getElementById('rh-sel-cand-hist');
    if(elH) elH.innerHTML='<b>Histórico da etapa</b><ul style="margin:6px 0 0 18px;padding:0">'+(hist.map(function(h){return '<li>'+rhEsc(h)+'</li>';}).join('')||'<li style="color:#aaa">Sem eventos ainda</li>')+'</ul>';
  }
  if(c.convite_criado_em) hist.push('Convite criado — '+rhSelFmtDt(c.convite_criado_em));
  if(c.identificacao_concluida_em) hist.push('Identificação concluída — '+rhSelFmtDt(c.identificacao_concluida_em));
  if(c.testes_iniciados_em) hist.push('Testes iniciados — '+rhSelFmtDt(c.testes_iniciados_em));
  if(c.testes_concluidos_em) hist.push('Testes concluídos — '+rhSelFmtDt(c.testes_concluidos_em));
  if(c.entrevistas_encerradas_em) hist.push('Etapa de entrevistas encerrada — '+rhSelFmtDt(c.entrevistas_encerradas_em));
  pintarHist();

  var v=_rhSel.atual||{};
  Promise.all([
    sbFetch('rh_teste_tentativas',{filters:['or=(candidatura_id.eq.'+id+',candidato_id.eq.'+id+')'],order:'created_at.desc',limit:40}),
    sbFetch('rh_testes',{filters:['ativo=eq.true'],limit:100}),
    sbFetch('rh_candidato_entrevistas',{filters:['candidatura_id=eq.'+id],order:'agendada_para.asc',limit:50}).catch(function(){return [];})
  ]).then(function(arr){
    var tents=arr[0]||[];
    var testes=arr[1]||[];
    var ents=arr[2]||[];
    _rhSelCandEntByCand[String(id)]=ents;
    var byId={}; testes.forEach(function(t){ byId[t.id]=t; });
    var latest={};
    tents.forEach(function(t){ var k=String(t.teste_id); if(!latest[k]) latest[k]=t; });
    var ids=Object.keys(latest).map(function(k){ return latest[k].id; });
    var evid=rhSelEntEvidenciaTestesOk(latest, byId, v.cargo_id);

    function aposElegibilidade(){
      rhSelCandDetalheAtualizarAcoes(id, c, evid);
      if(evid && c.testes_concluidos_em && hist.indexOf('Testes concluídos — '+rhSelFmtDt(c.testes_concluidos_em))<0){
        hist.push('Testes concluídos — '+rhSelFmtDt(c.testes_concluidos_em));
        pintarHist();
      }
    }
    var pRepair=evid?rhSelEntRepararStatusTestes(c):Promise.resolve(c);
    pRepair.then(function(){
      aposElegibilidade();
      if(evid && c.testes_concluidos_em){
        // atualiza histórico se reparou agora
        var ja=hist.some(function(h){ return h.indexOf('Testes concluídos')===0; });
        if(!ja){ hist.push('Testes concluídos — '+rhSelFmtDt(c.testes_concluidos_em)); pintarHist(); }
      }
    });

    function pintarAvals(ress){
      var byTent={}; (ress||[]).forEach(function(r){ byTent[r.tentativa_id]=r; });
      var html='<b>Avaliações desta vaga</b> <span style="font-size:11px;color:#888">(snapshot — não libera testes de outro cargo)</span>';
      var snapA=(_rhSel.vagaTestes||[]).filter(function(x){ return x && x.ativo!==false; });
      if(snapA.length){
        html+='<ul style="margin:8px 0 0 18px;padding:0">';
        snapA.forEach(function(s){
          var tent=latest[String(s.teste_id)];
          html+='<li>'+rhEsc(s.teste_nome||s.teste_codigo||s.teste_id)
            +(s.teste_versao?' <span style="font-size:10px;color:#888">v'+rhEsc(s.teste_versao)+'</span>':'')
            +' · '+rhEsc(s.origem==='ADICIONADO_NA_VAGA'?'complementar':'herdado')
            +' · '+(tent?rhEsc(tent.status):'não iniciado')+'</li>';
        });
        html+='</ul>';
      }
      if(!ids.length){ html+='<div style="color:#aaa;margin-top:6px">'+(snapA.length?'Aguardando execução no portal.':'Nenhuma tentativa ainda.')+'</div>'; }
      else {
        html+='<ul style="margin:8px 0 0 18px;padding:0">';
        Object.keys(latest).forEach(function(tid){
          var tent=latest[tid], t=byId[tid]||{}, r=byTent[tent.id], nome=t.nome||t.perfil||tid;
          if(tent.status==='CONCLUIDO' && r){
            if(String(t.perfil||'').toUpperCase()==='SITUACIONAL'){
              html+='<li><b>'+rhEsc(nome)+'</b>: '+rhEsc(r.parecer||'Concluído');
              if(r.dimensoes && typeof r.dimensoes==='object'){
                html+='<ul style="margin:4px 0 0 14px;font-size:12px;color:#555">';
                Object.keys(r.dimensoes).forEach(function(dk){
                  html+='<li>'+rhEsc(rhSelDimLabel(dk))+': <b>'+rhEsc(r.dimensoes[dk])+'</b></li>';
                });
                html+='</ul>';
              }
              html+='</li>';
            } else {
              html+='<li><b>'+rhEsc(nome)+'</b>: '+rhEsc(r.acertos)+'/'+rhEsc(r.total)+' — '+rhEsc(r.percentual)+'%</li>';
            }
          } else html+='<li><b>'+rhEsc(nome)+'</b>: '+rhEsc(tent.status||'—')+'</li>';
        });
        html+='</ul>';
      }
      var el=document.getElementById('rh-sel-cand-avals');
      if(el) el.innerHTML=html;
    }
    if(!ids.length) pintarAvals([]);
    else sbFetch('rh_teste_resultados',{filters:['tentativa_id=in.('+ids.join(',')+')'],limit:40}).then(pintarAvals).catch(function(){ pintarAvals([]); });

    var elE=document.getElementById('rh-sel-cand-ents');
    if(elE){
      var pode=rhSelPodeEditar();
      var html='<b>Entrevistas</b>';
      if(!ents.length) html+='<div style="color:#aaa;margin-top:6px">Nenhuma entrevista agendada.</div>';
      else {
        html+='<div style="margin-top:8px">'+ents.map(function(e){
          var eid=String(e.id||'').replace(/'/g,'');
          var ac='';
          if(pode){
            if(e.status==='AGENDADA'){
              ac+='<button class="btn btn-sm btn-pri" onclick="rhSelEntIniciar(\''+eid+'\')">Iniciar</button> ';
              ac+='<button class="btn btn-sm" onclick="rhSelEntAbrirAgendar(\''+id+'\',\''+eid+'\')">Reagendar</button> ';
              ac+='<button class="btn btn-sm" onclick="rhSelEntNaoCompareceu(\''+eid+'\')">Não compareceu</button> ';
              ac+='<button class="btn btn-sm" onclick="rhSelEntCancelar(\''+eid+'\')">Cancelar</button> ';
              ac+='<button class="btn btn-sm" onclick="rhSelEntShare(\''+eid+'\')">WhatsApp/E-mail</button>';
            } else if(e.status==='EM_ANDAMENTO'){
              ac+='<button class="btn btn-sm btn-pri" onclick="rhSelEntAbrirPainel(\''+eid+'\')">Continuar</button>';
            } else if(e.status==='CONCLUIDA'){
              ac+='<button class="btn btn-sm" onclick="rhSelEntAbrirPainel(\''+eid+'\')">Ver</button> ';
              ac+='<button class="btn btn-sm" onclick="rhSelEntReabrir(\''+eid+'\')">Reabrir</button>';
            } else if(e.status==='NAO_COMPARECEU'||e.status==='CANCELADA'){
              ac+='<button class="btn btn-sm" onclick="rhSelEntAbrirAgendar(\''+id+'\')">Nova entrevista</button>';
            }
          }
          return '<div style="border:1px solid #eee;border-radius:8px;padding:8px;margin-bottom:8px">'
            +'<div><b>'+rhEsc(rhSelEntTipoLabel(e.tipo))+'</b> · rodada '+(e.rodada||1)
            +' · '+rhEsc(rhSelEntStatusLabel(e.status))+'</div>'
            +'<div style="font-size:12px;color:#666">'+rhEsc(rhSelFmtDt(e.agendada_para))
            +' · '+rhEsc(e.entrevistador_nome_snapshot||'—')
            +' · '+rhEsc(rhSelEntModLabel(e.modalidade))+'</div>'
            +(e.recomendacao?'<div style="font-size:12px;margin-top:4px">Recomendação humana: <b>'+rhEsc(e.recomendacao)+'</b> (não é aprovação)</div>':'')
            +'<div style="margin-top:6px">'+ac+'</div></div>';
        }).join('')+'</div>';
      }
      ents.forEach(function(e){
        if(e.agendada_para && e.status!=='CANCELADA') hist.push(rhSelEntTipoLabel(e.tipo)+' agendada — '+rhSelFmtDt(e.agendada_para));
        if(e.concluida_em) hist.push(rhSelEntTipoLabel(e.tipo)+' concluída — '+rhSelFmtDt(e.concluida_em));
      });
      pintarHist();
      elE.innerHTML=html;
    }
    rhSelIntRenderPainel(id, c);
    rhSelResRenderPainel(id, c);
  }).catch(function(){
    var el=document.getElementById('rh-sel-cand-avals');
    if(el) el.innerHTML='Não foi possível carregar. Confirme SQL 1C/1D/1E.';
    var elE=document.getElementById('rh-sel-cand-ents');
    if(elE) elE.innerHTML='Aplique <code>sql_rh_selecao_entrevistas_fase_sel1e.sql</code> se a tabela ainda não existir.';
    rhSelIntRenderPainel(id, c);
    rhSelResRenderPainel(id, c);
    rhSelCandDetalheAtualizarAcoes(id, c, false);
  });
}
function rhSelCandDetalheFechar(){
  var box=document.getElementById('rh-sel-cand-detalhe');
  if(box){ box.classList.add('hidden'); box.innerHTML=''; }
}

// =============================================================================
// RH-SEL-1E — Entrevistas humanas (agenda + parecer). Sem aprovação automática.
// =============================================================================
function rhSelEntTipoLabel(t){ return ({RH:'Entrevista RH',TECNICA_GESTOR:'Técnica / Gestor'})[t]||t||'—'; }
function rhSelEntStatusLabel(s){ return ({AGENDADA:'Agendada',EM_ANDAMENTO:'Em andamento',CONCLUIDA:'Concluída',CANCELADA:'Cancelada',NAO_COMPARECEU:'Não compareceu'})[s]||s||'—'; }
function rhSelEntModLabel(m){ return ({PRESENCIAL:'Presencial',VIDEO:'Vídeo',TELEFONE:'Telefone',OUTRA:'Outra'})[m]||m||'—'; }
function rhSelEntUserNome(){ return (usuarioLogado&&usuarioLogado.nome)||''; }
function rhSelEntUserId(){ return (usuarioLogado&&usuarioLogado.id)||''; }
function rhSelEntRoteiro(tipo){
  if(tipo==='TECNICA_GESTOR'){
    return [
      {k:'exp_pratica',l:'Experiência prática relacionada ao cargo'},
      {k:'conhec_tecnico',l:'Conhecimento técnico aplicado'},
      {k:'procedimentos',l:'Compreensão dos procedimentos da atividade'},
      {k:'seguranca',l:'Segurança operacional'},
      {k:'imprevistos',l:'Resposta a situações imprevistas'},
      {k:'organizacao',l:'Organização do trabalho'},
      {k:'comunicacao',l:'Comunicação com equipe/liderança'},
      {k:'limites',l:'Limites de conhecimento / necessidade de orientação'},
      {k:'pontos_fortes_obs',l:'Pontos fortes observados'},
      {k:'aprofundar_obs',l:'Pontos a aprofundar'},
      {k:'obs_gestor',l:'Observações do gestor'}
    ];
  }
  return [
    {k:'trajetoria',l:'Trajetória profissional'},
    {k:'interesse',l:'Interesse pela oportunidade'},
    {k:'dispon_inicio',l:'Disponibilidade de início'},
    {k:'dispon_jornada',l:'Disponibilidade para jornada/escala da vaga'},
    {k:'dispon_local',l:'Disponibilidade para viagens/localidade'},
    {k:'experiencia',l:'Experiência relacionada à função'},
    {k:'comunicacao',l:'Comunicação e clareza das respostas'},
    {k:'esclarecer',l:'Pontos a esclarecer'},
    {k:'perguntas_cand',l:'Perguntas do candidato'},
    {k:'obs_rh',l:'Observações do RH'}
  ];
}
function rhSelEntCritLabel(v){
  return ({ATENDE:'Atende',ATENDE_PARCIALMENTE:'Atende parcialmente',NAO_EVIDENCIADO:'Não evidenciado',NAO_AVALIADO:'Não avaliado'})[v]||v||'NAO_AVALIADO';
}
function rhSelEntElegivel(c, opts){
  opts=opts||{};
  if(!c) return {ok:false, motivo:'Candidato inválido.'};
  if(c.status==='REVOGADO'||c.status==='EXPIRADO'||c.status==='DESISTENTE'||c.status==='DESCARTADO')
    return {ok:false, motivo:'Candidatura não está elegível para entrevista.'};
  if(c.entrevistas_encerradas_em || c.status==='ENTREVISTAS_CONCLUIDAS' ||
     c.status==='INTEGRIDADE_EM_ANALISE' || c.status==='INTEGRIDADE_CONCLUIDA' ||
     c.status==='EM_DECISAO_FINAL' || c.status==='APROVADO_PARA_ADMISSAO' ||
     c.status==='NAO_SELECIONADO' || c.status==='ENCAMINHADO_ADMISSAO' ||
     c.integridade_iniciada_em || c.integridade_concluida_em || c.decisao_em)
    return {ok:false, motivo:'Etapa de entrevistas já encerrada (ou decisão/integridade em curso). Pode consultar o histórico.'};
  // Evidência real dos testes (detalhe carregou tentativas CONCLUIDAS) OU status oficial
  if(opts.testesTodosConcluidos || c.testes_concluidos_em || c.status==='TESTES_CONCLUIDOS' ||
     c.status==='ENTREVISTA_AGENDADA' || c.status==='ENTREVISTAS_EM_ANDAMENTO')
    return {ok:true};
  var snapObr=(_rhSel.vagaTestes||[]).filter(function(r){ return r && r.ativo!==false && r.obrigatorio!==false; });
  var reqs=((_rhSel.matrizItens&&_rhSel.matrizItens.testes)||[]).filter(function(r){ return r.ativo!==false; });
  var cat=(_rhSel.catalogoTestes||[]).filter(function(t){ return t && t.ativo!==false; });
  if(c.status==='TESTES_EM_ANDAMENTO' || (c.testes_iniciados_em && !c.testes_concluidos_em)){
    return {ok:false, motivo:'Aguarde a conclusão de todos os testes online (ou reabra o Detalhe para sincronizar).'};
  }
  if(c.identificacao_concluida_em || c.status==='IDENTIFICADO'){
    // Snapshot da vaga / matriz / catálogo exige teste, mas ainda sem evidência de conclusão
    if(snapObr.length || reqs.length || cat.length){
      return {ok:false, motivo:'Há teste obrigatório pendente nesta vaga. Conclua as avaliações do snapshot antes de avançar a etapa.'};
    }
    return {ok:true};
  }
  return {ok:false, motivo:'Conclua identificação/testes antes de agendar entrevista.'};
}
function rhSelEntSyncStatusCand(cid){
  var ents=_rhSelCandEntByCand[String(cid)]||[];
  var c=(_rhSelCand.lista||[]).filter(function(x){ return String(x.id)===String(cid); })[0];
  if(!c || c.entrevistas_encerradas_em) return Promise.resolve();
  var abertas=ents.filter(function(e){ return e.status==='AGENDADA'||e.status==='EM_ANDAMENTO'; });
  var novas=ents.filter(function(e){ return e.status!=='CANCELADA'; });
  var st=c.status;
  if(abertas.length) st= abertas.some(function(e){return e.status==='EM_ANDAMENTO';}) ? 'ENTREVISTAS_EM_ANDAMENTO' : 'ENTREVISTA_AGENDADA';
  else if(novas.some(function(e){ return e.status==='CONCLUIDA'||e.status==='NAO_COMPARECEU'; })) {
    if(st!=='ENTREVISTAS_CONCLUIDAS') st='ENTREVISTAS_EM_ANDAMENTO';
  }
  if(st===c.status) return Promise.resolve();
  return sbUpdate('rh_vaga_candidatos',{status:st,updated_at:new Date().toISOString()},'id=eq.'+cid).then(function(){
    c.status=st;
  });
}
function rhSelEntAbrirAgendar(candId, entIdReagendar){
  if(!rhSelPodeEditar()){ progShowToast('Sem permissão.','erro'); return; }
  var c=(_rhSelCand.lista||[]).filter(function(x){ return String(x.id)===String(candId); })[0];
  if(!c){ progShowToast('Candidato não encontrado.','erro'); return; }
  var elig=rhSelEntElegivel(c);
  if(!elig.ok && !entIdReagendar){ progShowToast(elig.motivo||'Não elegível.','erro'); return; }
  var v=_rhSel.atual||{};
  var ent=null;
  if(entIdReagendar){
    ent=(_rhSelCandEntByCand[String(candId)]||[]).filter(function(e){ return String(e.id)===String(entIdReagendar); })[0];
  }
  var box=document.getElementById('rh-sel-ent-modal'); if(!box) return;
  var tipo=ent?ent.tipo:'RH';
  var sugId=tipo==='TECNICA_GESTOR'?(v.gestor_id||''):(v.responsavel_rh_id||'');
  if(ent&&ent.entrevistador_id) sugId=ent.entrevistador_id;
  var dt='';
  if(ent&&ent.agendada_para){
    try{
      var d=new Date(ent.agendada_para);
      dt=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
    }catch(e){}
  }
  box.classList.remove('hidden');
  box.innerHTML='<div style="position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:9100;display:flex;align-items:center;justify-content:center;padding:1rem" onclick="if(event.target===this)rhSelEntFecharModal()">'
    +'<div style="background:#fff;border-radius:12px;padding:1.1rem;max-width:460px;width:100%;max-height:92vh;overflow:auto" onclick="event.stopPropagation()">'
    +'<div style="font-weight:800;margin-bottom:10px">'+(ent?'Reagendar':'Agendar')+' entrevista — '+rhEsc(c.nome)+'</div>'
    +'<div class="fg"><label>Tipo *</label><select class="inp" id="rh-ent-tipo" onchange="rhSelEntTipoChange()">'
    +'<option value="RH"'+(tipo==='RH'?' selected':'')+'>RH</option>'
    +'<option value="TECNICA_GESTOR"'+(tipo==='TECNICA_GESTOR'?' selected':'')+'>Técnica / Gestor</option></select></div>'
    +'<div class="fg"><label>Entrevistador *</label><select class="inp" id="rh-ent-entrevistador">'+rhSelOptGestores(sugId)+'</select></div>'
    +'<div class="fg"><label>Data e hora *</label><input class="inp" id="rh-ent-quando" type="datetime-local" value="'+rhEsc(dt)+'"/></div>'
    +'<div class="fg"><label>Duração (min)</label><input class="inp" id="rh-ent-dur" type="number" min="15" value="'+(ent&&ent.duracao_minutos?ent.duracao_minutos:60)+'"/></div>'
    +'<div class="fg"><label>Modalidade *</label><select class="inp" id="rh-ent-mod">'
    +[['PRESENCIAL','Presencial'],['VIDEO','Vídeo'],['TELEFONE','Telefone'],['OUTRA','Outra']].map(function(p){
      return '<option value="'+p[0]+'"'+(ent&&ent.modalidade===p[0]?' selected':'')+'>'+p[1]+'</option>';
    }).join('')+'</select></div>'
    +'<div class="fg"><label>Local</label><input class="inp" id="rh-ent-local" value="'+rhEsc(ent&&ent.local_texto||'')+'"/></div>'
    +'<div class="fg"><label>Link da reunião</label><input class="inp" id="rh-ent-link" value="'+rhEsc(ent&&ent.link_reuniao||'')+'"/></div>'
    +'<div class="fg"><label>Observação'+(ent?' / motivo do reagendamento':'')+'</label><textarea class="inp" id="rh-ent-obs" rows="2">'+(ent?'':'')+'</textarea></div>'
    +'<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px">'
    +'<button class="btn" type="button" onclick="rhSelEntFecharModal()">Cancelar</button>'
    +'<button class="btn btn-pri" type="button" onclick="rhSelEntSalvarAgendar(\''+String(candId).replace(/'/g,'')+'\','+(ent?'\''+String(ent.id).replace(/'/g,'')+'\'':'null')+')">'+(ent?'Salvar reagendamento':'Agendar')+'</button></div>'
    +'</div></div>';
}
function rhSelEntTipoChange(){
  var tipo=(document.getElementById('rh-ent-tipo')||{}).value;
  var v=_rhSel.atual||{};
  var sug=tipo==='TECNICA_GESTOR'?(v.gestor_id||''):(v.responsavel_rh_id||'');
  var sel=document.getElementById('rh-ent-entrevistador');
  if(sel && sug) sel.value=String(sug);
}
function rhSelEntFecharModal(){
  var box=document.getElementById('rh-sel-ent-modal');
  if(box){ box.classList.add('hidden'); box.innerHTML=''; }
}
function rhSelEntSalvarAgendar(candId, entId){
  var v=_rhSel.atual||{};
  var tipo=(document.getElementById('rh-ent-tipo')||{}).value;
  var entSel=document.getElementById('rh-ent-entrevistador');
  var entIdCol=entSel?entSel.value:'';
  var entNome=entSel&&entSel.selectedIndex>=0?entSel.options[entSel.selectedIndex].text:'';
  var quando=(document.getElementById('rh-ent-quando')||{}).value;
  var dur=parseInt((document.getElementById('rh-ent-dur')||{}).value,10)||60;
  var mod=(document.getElementById('rh-ent-mod')||{}).value;
  var local=(document.getElementById('rh-ent-local')||{}).value||'';
  var link=(document.getElementById('rh-ent-link')||{}).value||'';
  var obs=(document.getElementById('rh-ent-obs')||{}).value||'';
  if(!tipo||!entIdCol||!quando||!mod){ progShowToast('Preencha tipo, entrevistador, data/hora e modalidade.','erro'); return; }
  var iso=new Date(quando).toISOString();
  var agora=new Date().toISOString();
  if(entId){
    var prev=(_rhSelCandEntByCand[String(candId)]||[]).filter(function(e){return String(e.id)===String(entId);})[0]||{};
    sbUpdate('rh_candidato_entrevistas',{
      tipo:tipo, agendada_para:iso, duracao_minutos:dur, modalidade:mod,
      local_texto:local||null, link_reuniao:link||null,
      entrevistador_id:entIdCol, entrevistador_nome_snapshot:entNome,
      reagendada_de:prev.agendada_para||null, reagendada_em:agora,
      reagendada_por:rhSelEntUserNome(), reagendamento_motivo:obs||null,
      observacoes_agendamento:obs||prev.observacoes_agendamento||null,
      status:'AGENDADA', updated_at:agora
    },'id=eq.'+entId).then(function(){
      try{ auditLog('REAGENDOU_ENTREVISTA','rh_selecao','Reagendou entrevista',{candidatura_id:candId,vaga_id:v.id,entrevista_id:entId,tipo:tipo}); }catch(e){}
      progShowToast('Entrevista reagendada.','ok');
      rhSelEntFecharModal();
      rhSelCandidatosCarregar(v.id);
      setTimeout(function(){ rhSelCandDetalhe(candId); }, 400);
    }).catch(function(e){ progShowToast((e&&e.message)||'Falha ao reagendar. Aplique SQL 1E.','erro'); });
    return;
  }
  var ents=_rhSelCandEntByCand[String(candId)]||[];
  var rodada=1+(ents.filter(function(e){ return e.tipo===tipo; }).length);
  sbInsert('rh_candidato_entrevistas',{
    candidatura_id:candId, vaga_id:v.id, tipo:tipo, rodada:rodada, status:'AGENDADA',
    agendada_para:iso, duracao_minutos:dur, modalidade:mod,
    local_texto:local||null, link_reuniao:link||null,
    entrevistador_id:entIdCol, entrevistador_nome_snapshot:entNome,
    observacoes_agendamento:obs||null,
    created_by:rhSelEntUserNome(), updated_at:agora
  }).then(function(rows){
    var row=Array.isArray(rows)?rows[0]:rows;
    try{ auditLog('AGENDOU_ENTREVISTA','rh_selecao','Agendou entrevista',{candidatura_id:candId,vaga_id:v.id,entrevista_id:row&&row.id,tipo:tipo}); }catch(e){}
    return rhSelEntSyncStatusCand(candId).then(function(){ return row; });
  }).then(function(){
    progShowToast('Entrevista agendada.','ok');
    rhSelEntFecharModal();
    rhSelCandidatosCarregar(v.id);
    setTimeout(function(){ rhSelCandDetalhe(candId); }, 400);
  }).catch(function(e){ progShowToast((e&&e.message)||'Falha ao agendar. Aplique sql_rh_selecao_entrevistas_fase_sel1e.sql.','erro'); });
}
function rhSelEntShare(entId){
  var flat=[];
  Object.keys(_rhSelCandEntByCand).forEach(function(k){ flat=flat.concat(_rhSelCandEntByCand[k]||[]); });
  var e=flat.filter(function(x){ return String(x.id)===String(entId); })[0];
  if(!e){ progShowToast('Entrevista não encontrada.','erro'); return; }
  var c=(_rhSelCand.lista||[]).filter(function(x){ return String(x.id)===String(e.candidatura_id); })[0]||{};
  var v=_rhSel.atual||{};
  var msg='CENA — Processo Seletivo\n\nOlá, '+(c.nome||'')+'.\n\nSua entrevista para o processo seletivo da CENA foi agendada.\n\nCargo:\n'+(v.cargo_nome||'')+'\n\nData/Hora:\n'+rhSelFmtDt(e.agendada_para)+'\n\nModalidade:\n'+rhSelEntModLabel(e.modalidade)+'\n\n'
    +(e.local_texto?'Local:\n'+e.local_texto+'\n\n':'')
    +(e.link_reuniao?'Link:\n'+e.link_reuniao+'\n\n':'')
    +'Em caso de dúvida, entre em contato com o RH.';
  var tel=String(c.telefone||'').replace(/\D/g,'');
  if(tel && tel.length>=10 && tel.length<=11) tel='55'+tel;
  var wa=tel?'https://wa.me/'+tel+'?text='+encodeURIComponent(msg):'';
  var mail=c.email?'mailto:'+encodeURIComponent(c.email)+'?subject='+encodeURIComponent('CENA — Entrevista agendada')+'&body='+encodeURIComponent(msg):'';
  var box=document.getElementById('rh-sel-ent-modal'); if(!box) return;
  box.classList.remove('hidden');
  box.innerHTML='<div style="position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:9100;display:flex;align-items:center;justify-content:center;padding:1rem" onclick="if(event.target===this)rhSelEntFecharModal()">'
    +'<div style="background:#fff;border-radius:12px;padding:1.1rem;max-width:440px;width:100%" onclick="event.stopPropagation()">'
    +'<div style="font-weight:800;margin-bottom:8px">Comunicar agendamento</div>'
    +'<textarea class="inp" id="rh-ent-share-txt" rows="12" readonly>'+rhEsc(msg)+'</textarea>'
    +'<div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:10px">'
    +(wa?'<a class="btn btn-pri" href="'+wa+'" target="_blank" rel="noopener">WhatsApp</a>':'')
    +(mail?'<a class="btn" href="'+mail+'">E-mail</a>':'')
    +'<button class="btn" type="button" onclick="navigator.clipboard.writeText(document.getElementById(\'rh-ent-share-txt\').value);progShowToast(\'Mensagem copiada.\',\'ok\')">Copiar mensagem</button>'
    +'<button class="btn" type="button" onclick="rhSelEntFecharModal()">Fechar</button></div>'
    +'<div style="font-size:11px;color:#888;margin-top:8px">Sem CPF, scores ou pareceres na mensagem.</div></div></div>';
}
function rhSelEntCancelar(entId){
  if(!rhSelPodeEditar()) return;
  var motivo=prompt('Motivo do cancelamento (obrigatório):');
  if(motivo==null) return;
  if(!String(motivo).trim()){ progShowToast('Informe o motivo.','erro'); return; }
  var agora=new Date().toISOString();
  sbUpdate('rh_candidato_entrevistas',{
    status:'CANCELADA', cancelada_em:agora, cancelada_por:rhSelEntUserNome(),
    cancelamento_motivo:String(motivo).trim(), updated_at:agora
  },'id=eq.'+entId).then(function(){
    try{ auditLog('CANCELOU_ENTREVISTA','rh_selecao','Cancelou entrevista',{entrevista_id:entId,vaga_id:_rhSel.atual&&_rhSel.atual.id}); }catch(e){}
    progShowToast('Entrevista cancelada.','ok');
    var v=_rhSel.atual; if(v&&v.id) rhSelCandidatosCarregar(v.id);
  });
}
function rhSelEntNaoCompareceu(entId){
  if(!rhSelPodeEditar()) return;
  if(!confirm('Confirmar não comparecimento? O candidato NÃO será reprovado automaticamente.')) return;
  var obs=prompt('Observação (opcional):')||'';
  var agora=new Date().toISOString();
  sbUpdate('rh_candidato_entrevistas',{
    status:'NAO_COMPARECEU', nao_compareceu_em:agora,
    observacoes_agendamento:obs||null, updated_at:agora
  },'id=eq.'+entId).then(function(){
    try{ auditLog('MARCOU_NAO_COMPARECIMENTO','rh_selecao','Não comparecimento',{entrevista_id:entId}); }catch(e){}
    progShowToast('Registrado. Pode reagendar nova entrevista.','ok');
    var v=_rhSel.atual; if(v&&v.id) rhSelCandidatosCarregar(v.id);
  });
}
function rhSelEntIniciar(entId){
  if(!rhSelPodeEditar()) return;
  var agora=new Date().toISOString();
  var roteiro=null;
  sbFetch('rh_candidato_entrevistas',{filters:['id=eq.'+entId],limit:1}).then(function(rows){
    var e=(rows||[])[0]; if(!e) throw new Error('Entrevista não encontrada');
    roteiro=rhSelEntRoteiro(e.tipo).map(function(r){ return {k:r.k,l:r.l,valor:'NAO_AVALIADO',obs:''}; });
    return sbUpdate('rh_candidato_entrevistas',{
      status:'EM_ANDAMENTO', iniciada_em:e.iniciada_em||agora,
      criterios_json:e.criterios_json||roteiro,
      realizada_por_id:rhSelEntUserId(), realizada_por_nome:rhSelEntUserNome(),
      updated_at:agora
    },'id=eq.'+entId).then(function(){ return e; });
  }).then(function(e){
    try{ auditLog('INICIOU_ENTREVISTA','rh_selecao','Iniciou entrevista',{entrevista_id:entId,candidatura_id:e.candidatura_id,tipo:e.tipo}); }catch(err){}
    rhSelEntSyncStatusCand(e.candidatura_id);
    rhSelEntAbrirPainel(entId);
  }).catch(function(err){ progShowToast((err&&err.message)||'Falha ao iniciar.','erro'); });
}
function rhSelEntAbrirPainel(entId){
  sbFetch('rh_candidato_entrevistas',{filters:['id=eq.'+entId],limit:1}).then(function(rows){
    var e=(rows||[])[0];
    if(!e){ progShowToast('Entrevista não encontrada.','erro'); return; }
    _rhSelEnt.atual=e;
    _rhSel.view='entrevista_painel';
    rhSelCandDetalheFechar();
    rhSelEntRenderPainel();
  });
}
function rhSelEntRenderPainel(){
  var wrap=document.getElementById('rh-vagas-wrap'); if(!wrap) return;
  var e=_rhSelEnt.atual; if(!e){ _rhSel.view='ficha'; rhSelRender(); return; }
  var c=(_rhSelCand.lista||[]).filter(function(x){ return String(x.id)===String(e.candidatura_id); })[0]||{};
  var v=_rhSel.atual||{};
  var ro=e.status==='CONCLUIDA'||e.status==='CANCELADA'||e.status==='NAO_COMPARECEU';
  var crit=Array.isArray(e.criterios_json)?e.criterios_json:rhSelEntRoteiro(e.tipo).map(function(r){return {k:r.k,l:r.l,valor:'NAO_AVALIADO',obs:''};});
  _rhSelEnt.criterios={};
  crit.forEach(function(r){ _rhSelEnt.criterios[r.k]=r; });

  wrap.innerHTML='<div class="card"><div class="ch"><span class="ct">'+rhEsc(rhSelEntTipoLabel(e.tipo))+'</span>'
    +'<button class="btn" onclick="_rhSel.view=\'ficha\';rhSelRender();setTimeout(function(){rhSelCandDetalhe(\''+String(e.candidatura_id).replace(/'/g,'')+'\')},200)">← Voltar</button></div>'
    +'<div style="padding:1rem;font-size:13px">'
    +'<div style="margin-bottom:10px"><b>'+rhEsc(c.nome||'Candidato')+'</b> · '+rhEsc(v.codigo||'')+' · '+rhEsc(v.cargo_nome||'')+'<br>'
    +rhEsc(rhSelFmtDt(e.agendada_para))+' · '+rhEsc(e.entrevistador_nome_snapshot||'')+' · '+rhEsc(rhSelEntStatusLabel(e.status))+'</div>'
    +'<div id="rh-ent-painel-avals" style="background:#F8F8F6;border-radius:8px;padding:10px;margin-bottom:12px;font-size:12px">Carregando resultados dos testes…</div>'
    +'<div style="font-weight:700;margin-bottom:8px">Roteiro estruturado</div>'
    +crit.map(function(r){
      return '<div style="border:1px solid #eee;border-radius:8px;padding:8px;margin-bottom:8px">'
        +'<div style="font-weight:600;margin-bottom:4px">'+rhEsc(r.l)+'</div>'
        +'<select class="inp" '+(ro?'disabled':'')+' onchange="rhSelEntCritSet(\''+rhEsc(r.k)+'\',this.value)">'
        +['NAO_AVALIADO','ATENDE','ATENDE_PARCIALMENTE','NAO_EVIDENCIADO'].map(function(o){
          return '<option value="'+o+'"'+(r.valor===o?' selected':'')+'>'+rhSelEntCritLabel(o)+'</option>';
        }).join('')+'</select>'
        +'<input class="inp" style="margin-top:6px" placeholder="Observação" '+(ro?'disabled':'')+' value="'+rhEsc(r.obs||'')+'" onchange="rhSelEntCritObs(\''+rhEsc(r.k)+'\',this.value)"/>'
        +'</div>';
    }).join('')
    +'<div class="fg"><label>Pontos fortes</label><textarea class="inp" id="rh-ent-pf" rows="2" '+(ro?'disabled':'')+'>'+rhEsc(e.pontos_fortes||'')+'</textarea></div>'
    +'<div class="fg"><label>Pontos a aprofundar</label><textarea class="inp" id="rh-ent-pa" rows="2" '+(ro?'disabled':'')+'>'+rhEsc(e.pontos_aprofundar||'')+'</textarea></div>'
    +'<div class="fg"><label>Parecer da entrevista *</label><textarea class="inp" id="rh-ent-parecer" rows="3" '+(ro?'disabled':'')+'>'+rhEsc(e.parecer||'')+'</textarea></div>'
    +'<div class="fg"><label>Recomendação humana *</label><select class="inp" id="rh-ent-rec" '+(ro?'disabled':'')+'>'
    +[['','—'],['AVANCAR','Avançar'],['REVISAR','Revisar'],['NAO_RECOMENDAR','Não recomendar']].map(function(p){
      return '<option value="'+p[0]+'"'+(e.recomendacao===p[0]?' selected':'')+'>'+p[1]+'</option>';
    }).join('')+'</select>'
    +'<div style="font-size:11px;color:#888;margin-top:4px">Manifestação humana. Não aprova nem reprova contratação.</div></div>'
    +(!ro?'<button class="btn btn-pri" type="button" onclick="rhSelEntConcluir(\''+String(e.id).replace(/'/g,'')+'\')">Concluir entrevista</button>':'')
    +(ro && e.status==='CONCLUIDA'?'<button class="btn" type="button" onclick="rhSelEntReabrir(\''+String(e.id).replace(/'/g,'')+'\')">Reabrir</button>':'')
    +'</div></div>';
  // carregar testes como contexto
  var cid=e.candidatura_id;
  Promise.all([
    sbFetch('rh_teste_tentativas',{filters:['or=(candidatura_id.eq.'+cid+',candidato_id.eq.'+cid+')'],order:'created_at.desc',limit:40}),
    sbFetch('rh_testes',{filters:['ativo=eq.true'],limit:100})
  ]).then(function(arr){
    var tents=arr[0]||[], testes=arr[1]||[], byId={}; testes.forEach(function(t){byId[t.id]=t;});
    var latest={}; tents.forEach(function(t){ if(!latest[t.teste_id]) latest[t.teste_id]=t; });
    var ids=Object.keys(latest).map(function(k){return latest[k].id;});
    var box=document.getElementById('rh-ent-painel-avals');
    if(!ids.length){ if(box) box.innerHTML='<b>Resultados dos testes (contexto)</b><div style="color:#888">Sem resultados.</div>'; return; }
    sbFetch('rh_teste_resultados',{filters:['tentativa_id=in.('+ids.join(',')+')'],limit:40}).then(function(ress){
      var byTent={}; (ress||[]).forEach(function(r){byTent[r.tentativa_id]=r;});
      var html='<b>Resultados dos testes (contexto — sem gabarito)</b><ul style="margin:6px 0 0 16px">';
      Object.keys(latest).forEach(function(tid){
        var tent=latest[tid], t=byId[tid]||{}, r=byTent[tent.id];
        if(r){
          if(String(t.perfil||'').toUpperCase()==='SITUACIONAL') html+='<li>'+rhEsc(t.nome||t.perfil)+': '+rhEsc(r.parecer||'Concluído')+'</li>';
          else html+='<li>'+rhEsc(t.nome||t.perfil)+': '+rhEsc(r.percentual)+'% ('+rhEsc(r.acertos)+'/'+rhEsc(r.total)+')</li>';
        }
      });
      html+='</ul><div style="margin-top:6px;color:#666">Pontos para aprofundar na entrevista — sem interpretação automática.</div>';
      if(box) box.innerHTML=html;
    });
  });
}
function rhSelEntCritSet(k,v){ if(!_rhSelEnt.criterios[k]) _rhSelEnt.criterios[k]={k:k}; _rhSelEnt.criterios[k].valor=v; }
function rhSelEntCritObs(k,v){ if(!_rhSelEnt.criterios[k]) _rhSelEnt.criterios[k]={k:k}; _rhSelEnt.criterios[k].obs=v; }
function rhSelEntConcluir(entId){
  var parecer=(document.getElementById('rh-ent-parecer')||{}).value||'';
  var rec=(document.getElementById('rh-ent-rec')||{}).value||'';
  if(!String(parecer).trim()||!rec){ progShowToast('Preencha parecer e recomendação humana.','erro'); return; }
  var crit=Object.keys(_rhSelEnt.criterios||{}).map(function(k){ return _rhSelEnt.criterios[k]; });
  var agora=new Date().toISOString();
  sbUpdate('rh_candidato_entrevistas',{
    status:'CONCLUIDA', concluida_em:agora,
    parecer:String(parecer).trim(), recomendacao:rec,
    pontos_fortes:(document.getElementById('rh-ent-pf')||{}).value||null,
    pontos_aprofundar:(document.getElementById('rh-ent-pa')||{}).value||null,
    criterios_json:crit,
    realizada_por_id:rhSelEntUserId(), realizada_por_nome:rhSelEntUserNome(),
    updated_at:agora
  },'id=eq.'+entId).then(function(){
    try{ auditLog('CONCLUIU_ENTREVISTA','rh_selecao','Concluiu entrevista',{entrevista_id:entId,recomendacao:rec}); }catch(e){}
    progShowToast('Entrevista concluída (somente leitura).','ok');
    var cid=_rhSelEnt.atual&&_rhSelEnt.atual.candidatura_id;
    if(cid) rhSelEntSyncStatusCand(cid);
    _rhSel.view='ficha'; rhSelRender();
    if(cid) setTimeout(function(){ rhSelCandidatosCarregar(_rhSel.atual&&_rhSel.atual.id); setTimeout(function(){ rhSelCandDetalhe(cid); },500); },200);
  }).catch(function(e){ progShowToast((e&&e.message)||'Falha ao concluir.','erro'); });
}
function rhSelEntReabrir(entId){
  if(!rhSelPodeEditar()) return;
  var just=prompt('Justificativa para reabrir (obrigatória):');
  if(just==null) return;
  if(!String(just).trim()){ progShowToast('Informe a justificativa.','erro'); return; }
  var agora=new Date().toISOString();
  sbUpdate('rh_candidato_entrevistas',{
    status:'EM_ANDAMENTO', concluida_em:null,
    reaberta_em:agora, reaberta_por:rhSelEntUserNome(), reabertura_motivo:String(just).trim(),
    updated_at:agora
  },'id=eq.'+entId).then(function(){
    try{ auditLog('REABRIU_ENTREVISTA','rh_selecao','Reabriu entrevista',{entrevista_id:entId}); }catch(e){}
    progShowToast('Entrevista reaberta.','ok');
    rhSelEntAbrirPainel(entId);
  });
}
function rhSelEntEncerrarEtapa(candId){
  if(!rhSelPodeEditar()) return;
  var ents=_rhSelCandEntByCand[String(candId)]||[];
  var pend=ents.filter(function(e){ return e.status==='AGENDADA'||e.status==='EM_ANDAMENTO'; });
  if(pend.length){ progShowToast('Existem entrevistas agendadas ou em andamento. Resolva-as antes.','erro'); return; }
  var conc=ents.filter(function(e){ return e.status==='CONCLUIDA'; });
  if(!conc.length){ progShowToast('É necessário ao menos uma entrevista concluída.','erro'); return; }
  var resumo=conc.map(function(e){ return rhSelEntTipoLabel(e.tipo)+': '+(e.recomendacao||'—'); }).join('\n');
  if(!confirm('Encerrar etapa de entrevistas?\n\n'+resumo+'\n\nIsso NÃO aprova nem reprova o candidato.')) return;
  var agora=new Date().toISOString();
  sbUpdate('rh_vaga_candidatos',{
    status:'ENTREVISTAS_CONCLUIDAS', entrevistas_encerradas_em:agora, updated_at:agora
  },'id=eq.'+candId).then(function(){
    try{ auditLog('ENCERROU_ETAPA_ENTREVISTAS','rh_selecao','Encerrou etapa de entrevistas',{candidatura_id:candId,vaga_id:_rhSel.atual&&_rhSel.atual.id}); }catch(e){}
    progShowToast('Etapa de entrevistas encerrada. Pode iniciar a análise de integridade.','ok');
    rhSelCandDetalheFechar();
    if(_rhSel.atual&&_rhSel.atual.id) rhSelCandidatosCarregar(_rhSel.atual.id);
  });
}

// =============================================================================
// RH-SEL-1F — Integridade / Histórico / Conflitos (HC · PC · AC · PT)
// Indicadores de análise humana. Sem score, scraping, aprovação ou admissão.
// =============================================================================
function rhSelIntUserNome(){ return (usuarioLogado&&usuarioLogado.nome)||''; }
function rhSelIntNormCpf(v){
  if(typeof rhSynNormCpf==='function') return rhSynNormCpf(v);
  return String(v||'').replace(/\D/g,'');
}
function rhSelIntNormProc(v){
  var d=String(v||'').replace(/\D/g,'');
  return d||'';
}
function rhSelIntNormTel(v){ return String(v||'').replace(/\D/g,''); }
function rhSelIntElegivelIniciar(c){
  if(!c) return false;
  if(c.status==='REVOGADO'||c.status==='EXPIRADO'||c.status==='DESISTENTE'||c.status==='DESCARTADO') return false;
  if(c.status==='INTEGRIDADE_EM_ANALISE'||c.status==='INTEGRIDADE_CONCLUIDA') return false;
  if(c.status==='EM_DECISAO_FINAL'||c.status==='APROVADO_PARA_ADMISSAO'||c.status==='NAO_SELECIONADO'||c.status==='ENCAMINHADO_ADMISSAO') return false;
  var a=_rhSelIntByCand[String(c.id)];
  if(a && a.status_analise==='EM_ANALISE') return false;
  if(a && a.status_analise==='CONCLUIDA') return false;
  return !!(c.entrevistas_encerradas_em || c.status==='ENTREVISTAS_CONCLUIDAS');
}
function rhSelIntResumoCand(cid){
  var a=_rhSelIntByCand[String(cid)];
  if(!a) return '— Não iniciada';
  if(a.status_analise==='CONCLUIDA') return '✓ Concluída';
  if(a.status_analise==='PENDENTE_REVISAO') return '⚠ Pendente revisão';
  if(a.status_analise==='EM_ANALISE'){
    var pend=0;
    var itens=_rhSelIntItens[String(a.id)]||[];
    itens.forEach(function(it){
      if(it.ativo!==false && (it.status_confirmacao==='POSSIVEL_HOMONIMO'||it.status_confirmacao==='INCONCLUSIVO') && !it.revisado_em) pend++;
    });
    if(pend) return '⚠ '+pend+' item(ns) p/ revisar';
    return '🔎 Em análise';
  }
  return '— Não iniciada';
}
function rhSelIntIndCor(status){
  // Cores = estado da análise, não "qualidade moral"
  if(status==='NAO_CONSULTADO') return {bg:'#F3F4F6',bd:'#D1D5DB',fg:'#4B5563'};
  if(status==='EM_ANALISE') return {bg:'#EFF6FF',bd:'#93C5FD',fg:'#1D4ED8'};
  if(status==='SEM_OCORRENCIA'||status==='REVISADO') return {bg:'#ECFDF5',bd:'#6EE7B7',fg:'#047857'};
  if(status==='COM_OCORRENCIA'||status==='INCONCLUSIVO') return {bg:'#FFFBEB',bd:'#FCD34D',fg:'#92400E'};
  if(status==='ERRO_FONTE') return {bg:'#FEF2F2',bd:'#FECACA',fg:'#B91C1C'};
  return {bg:'#F9FAFB',bd:'#E5E7EB',fg:'#374151'};
}
function rhSelIntIndLabel(st){
  return ({NAO_CONSULTADO:'Não consultado',EM_ANALISE:'Em análise',SEM_OCORRENCIA:'Sem ocorrência',
    COM_OCORRENCIA:'Com ocorrência',REVISADO:'Revisado',INCONCLUSIVO:'Inconclusivo',ERRO_FONTE:'Erro de fonte'})[st]||st||'—';
}
function rhSelIntAnaliseLabel(st){
  return ({NAO_INICIADA:'Não iniciada',EM_ANALISE:'Em análise',PENDENTE_REVISAO:'Pendente revisão',CONCLUIDA:'Concluída'})[st]||st||'—';
}
function rhSelIntCatTitulo(cat){
  return ({HC:'Histórico CENA',PC:'Possíveis conflitos',AC:'Antecedentes / ocorrências (fonte autorizada)',PT:'Ocorrências trabalhistas (fonte autorizada)'})[cat]||cat;
}
function rhSelIntCardValor(cat, analise, itens){
  if(!analise) return {num:'—', sub:'Análise não iniciada', st:'NAO_CONSULTADO'};
  var st=analise[cat.toLowerCase()+'_status']||'NAO_CONSULTADO';
  var q=analise[cat.toLowerCase()+'_quantidade'];
  if(cat==='AC'||cat==='PT'){
    if(st==='NAO_CONSULTADO') return {num:'—', sub:'Consulta externa não configurada', st:st};
  }
  var hom=0;
  (itens||[]).forEach(function(it){
    if(it.ativo!==false && it.categoria===cat && it.status_confirmacao==='POSSIVEL_HOMONIMO' && !it.revisado_em) hom++;
  });
  var num=(q==null?'—':String(q));
  var sub=rhSelIntIndLabel(st);
  if(q!=null && st!=='NAO_CONSULTADO'){
    if(q===0 && (st==='SEM_OCORRENCIA'||st==='REVISADO')) sub=(cat==='HC'?'Nenhum vínculo CENA localizado':(cat==='PC'?'Nenhuma ocorrência revisada':'Nenhuma ocorrência retornada na fonte consultada'));
    else if(q>0) sub=q+' ocorrência(s)'+(hom?' · +'+hom+' pendente(s) de validação':'');
  }
  return {num:num, sub:sub, st:st, hom:hom};
}
function rhSelIntRenderPainel(candId, c){
  var el=document.getElementById('rh-sel-cand-int'); if(!el) return;
  var podeVer=rhSelIntPodeVerDetalhe();
  var podeEd=rhSelIntPodeEditar();
  el.innerHTML='<b>Integridade / Histórico</b> <span style="font-size:11px;color:#888">(RH-SEL-1F — indicadores de análise; não decide contratação)</span>'
    +'<div style="color:#888;margin-top:6px">Carregando…</div>';
  var cached=_rhSelIntByCand[String(candId)];
  function pintar(analise, itens){
    _rhSelIntByCand[String(candId)]=analise||null;
    if(analise) _rhSelIntItens[String(analise.id)]=itens||[];
    var ents=_rhSelCandEntByCand[String(candId)]||[];
    var concEnt=ents.filter(function(e){ return e.status==='CONCLUIDA'; });
    var html='<b>Integridade / Histórico</b> <span style="font-size:11px;color:#888">(indicadores HC/PC/AC/PT — decisão humana)</span>';
    if(concEnt.length){
      html+='<div style="margin-top:8px;padding:8px;background:#F8FAFC;border-radius:8px;font-size:12px;color:#475569">'
        +'<div style="font-weight:600;margin-bottom:4px">Resumo entrevistas (somente leitura)</div>'
        +concEnt.map(function(e){
          return '<div>'+rhEsc(rhSelEntTipoLabel(e.tipo))+': <b>'+rhEsc(rhSelEntStatusLabel(e.status))+'</b>'
            +(e.recomendacao?' · Recomendação humana: <b>'+rhEsc(e.recomendacao)+'</b>':'')+'</div>';
        }).join('')+'</div>';
    }
    if(!analise){
      html+='<div style="margin-top:8px;color:#666;font-size:12px">Análise ainda não iniciada.'
        +(rhSelIntElegivelIniciar(c)?' Use <b>Iniciar análise de integridade</b> após entrevistas concluídas.':' Aguarde o encerramento das entrevistas.')+'</div>';
      el.innerHTML=html;
      rhSelCandDetalheAtualizarAcoes(candId, c, true);
      return;
    }
    var cats=['HC','PC','AC','PT'];
    html+='<div style="margin-top:8px;font-size:12px">Status da análise: <b>'+rhEsc(rhSelIntAnaliseLabel(analise.status_analise))+'</b>'
      +(analise.iniciada_em?' · Iniciada: '+rhEsc(rhSelFmtDt(analise.iniciada_em)):'')
      +(analise.concluida_em?' · Concluída: '+rhEsc(rhSelFmtDt(analise.concluida_em)):'')+'</div>';
    html+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin-top:10px">';
    cats.forEach(function(cat){
      var card=rhSelIntCardValor(cat, analise, itens);
      var cor=rhSelIntIndCor(card.st);
      var showDet=podeVer || cat==='HC' || cat==='PC';
      var numShow=card.num, subShow=card.sub;
      if((cat==='AC'||cat==='PT') && !podeVer){
        numShow='·';
        subShow=analise.status_analise==='CONCLUIDA'?'Análise concluída (detalhe restrito)':'Em análise (detalhe restrito)';
        cor=rhSelIntIndCor(analise.status_analise==='CONCLUIDA'?'REVISADO':'EM_ANALISE');
      }
      html+='<div style="border:1px solid '+cor.bd+';background:'+cor.bg+';color:'+cor.fg+';border-radius:10px;padding:10px">'
        +'<div style="font-size:20px;font-weight:800">'+rhEsc(cat)+' '+rhEsc(numShow)+'</div>'
        +'<div style="font-size:11px;font-weight:600;margin-top:2px">'+rhEsc(rhSelIntCatTitulo(cat))+'</div>'
        +'<div style="font-size:11px;margin-top:4px;opacity:.9">'+rhEsc(subShow)+'</div>';
      if(cat==='AC'||cat==='PT'){
        if(podeVer) html+='<div style="font-size:10px;margin-top:6px;opacity:.85">Processo ≠ condenação. Consulta só com fonte autorizada.</div>';
      }
      if(showDet && !((cat==='AC'||cat==='PT') && !podeVer)){
        html+='<button type="button" class="btn btn-sm" style="margin-top:8px" onclick="rhSelIntToggleDetalhe(\''+String(candId).replace(/'/g,'')+'\',\''+cat+'\')">Ver detalhes</button>';
      } else if((cat==='AC'||cat==='PT') && !podeVer){
        html+='<div style="font-size:10px;margin-top:6px">Detalhe restrito (RH/DP/admin).</div>';
      }
      html+='</div>';
    });
    html+='</div>';
    html+='<div id="rh-sel-int-det" style="margin-top:10px"></div>';
    if(analise.parecer_geral){
      html+='<div style="margin-top:8px;font-size:12px;color:#555"><b>Parecer interno:</b> '+rhEsc(analise.parecer_geral)+'</div>';
    }
    if(podeEd && analise.status_analise!=='CONCLUIDA'){
      html+='<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:10px">'
        +'<button class="btn btn-sm" type="button" onclick="rhSelIntAtualizarInterno(\''+String(candId).replace(/'/g,'')+'\')">Atualizar histórico interno</button>'
        +'<button class="btn btn-sm" type="button" onclick="rhSelIntAbrirRegistro(\''+String(candId).replace(/'/g,'')+'\',\'PC\')">Registrar possível conflito</button>'
        +(podeVer?'<button class="btn btn-sm" type="button" onclick="rhSelIntAbrirRegistro(\''+String(candId).replace(/'/g,'')+'\',\'AC\')">Registrar AC</button>':'')
        +(podeVer?'<button class="btn btn-sm" type="button" onclick="rhSelIntAbrirRegistro(\''+String(candId).replace(/'/g,'')+'\',\'PT\')">Registrar PT</button>':'')
        +'<button class="btn btn-sm btn-pri" type="button" onclick="rhSelIntConcluir(\''+String(candId).replace(/'/g,'')+'\')">Concluir análise</button>'
        +'</div>';
    }
    if(podeEd && analise.status_analise==='CONCLUIDA'){
      html+='<div style="margin-top:10px"><button class="btn btn-sm" type="button" onclick="rhSelIntReabrir(\''+String(candId).replace(/'/g,'')+'\')">Reabrir análise</button></div>';
    }
    if(!podeVer){
      html+='<div style="margin-top:8px;font-size:11px;color:#854F0B;background:#FEF3E2;padding:8px;border-radius:8px">Seu perfil vê o status da análise. Detalhes AC/PT ficam restritos a RH/DP/admin/diretoria.</div>';
    }
    el.innerHTML=html;
    rhSelCandDetalheAtualizarAcoes(candId, c, true);
  }
  if(DEMO){ pintar(null,[]); return; }
  sbFetch('rh_candidato_integridade',{filters:['candidatura_id=eq.'+encodeURIComponent(candId)],limit:1})
    .then(function(rows){
      var a=(rows&&rows[0])||cached||null;
      if(!a){ pintar(null,[]); return; }
      return sbFetch('rh_candidato_integridade_itens',{filters:['integridade_id=eq.'+a.id,'ativo=eq.true'],order:'created_at.asc',limit:200})
        .then(function(itens){ pintar(a, itens||[]); })
        .catch(function(){ pintar(a,[]); });
    })
    .catch(function(){
      el.innerHTML='<b>Integridade / Histórico</b><div style="color:#854F0B;background:#FEF3E2;padding:8px;border-radius:8px;margin-top:6px">Aplique <code>SQLS/sql_rh_selecao_integridade_fase_sel1f.sql</code> no SQL Editor.</div>';
    });
}
function rhSelIntToggleDetalhe(candId, cat){
  var box=document.getElementById('rh-sel-int-det'); if(!box) return;
  if(box.getAttribute('data-cat')===cat && box.innerHTML){ box.innerHTML=''; box.removeAttribute('data-cat'); return; }
  var a=_rhSelIntByCand[String(candId)]; if(!a) return;
  if((cat==='AC'||cat==='PT') && !rhSelIntPodeVerDetalhe()){ progShowToast('Sem permissão para detalhe AC/PT.','erro'); return; }
  var itens=(_rhSelIntItens[String(a.id)]||[]).filter(function(it){ return it.categoria===cat && it.ativo!==false; });
  box.setAttribute('data-cat',cat);
  var html='<div style="border:1px solid #e5e7eb;border-radius:8px;padding:10px;background:#fff">'
    +'<div style="font-weight:700;margin-bottom:6px">Detalhes '+rhEsc(cat)+' — '+rhEsc(rhSelIntCatTitulo(cat))+'</div>';
  if(cat==='AC'||cat==='PT'){
    html+='<div style="font-size:11px;color:#92400E;margin-bottom:8px">Atenção: registro localizado ≠ condenação/culpa. Homônimo exige revisão.</div>';
  }
  if(!itens.length){
    html+='<div style="color:#888;font-size:12px">'+(cat==='AC'||cat==='PT'?'Nenhuma consulta registrada. Use registro manual / certidão.':'Nenhum item.')+'</div>';
  } else {
    html+=itens.map(function(it){
      var iid=String(it.id||'').replace(/'/g,'');
      var ac='';
      if(rhSelIntPodeEditar() && a.status_analise!=='CONCLUIDA' && !it.revisado_em){
        ac='<div style="margin-top:6px;display:flex;flex-wrap:wrap;gap:4px">'
          +'<button class="btn btn-sm" onclick="rhSelIntRevisarItem(\''+iid+'\',\'CONFIRMADO\')">Confirmar</button>'
          +'<button class="btn btn-sm" onclick="rhSelIntRevisarItem(\''+iid+'\',\'POSSIVEL_HOMONIMO\')">Possível homônimo</button>'
          +'<button class="btn btn-sm" onclick="rhSelIntRevisarItem(\''+iid+'\',\'DESCARTADO\')">Descartar</button>'
          +'<button class="btn btn-sm" onclick="rhSelIntRevisarItem(\''+iid+'\',\'ESCLARECIMENTO\')">Solicitar esclarecimento</button></div>';
      }
      return '<div style="border-top:1px solid #f0f0f0;padding:8px 0;font-size:12px">'
        +'<div><b>'+rhEsc(it.titulo||it.categoria)+'</b> · '+rhEsc(it.status_confirmacao||'')
        +(it.identificacao_metodo?' · '+rhEsc(it.identificacao_metodo):'')+'</div>'
        +(it.descricao_resumida?'<div style="color:#555">'+rhEsc(it.descricao_resumida)+'</div>':'')
        +'<div style="color:#666;font-size:11px">Fonte: '+rhEsc(it.fonte||'—')
        +(it.fonte_tipo?' ('+rhEsc(it.fonte_tipo)+')':'')
        +(it.consultado_em?' · Consulta: '+rhEsc(rhSelFmtDt(it.consultado_em)):'')+'</div>'
        +(it.numero_processo?'<div style="font-size:11px">Processo: '+rhEsc(it.numero_processo)
          +(it.tribunal?' · '+rhEsc(it.tribunal):'')
          +(it.polo?' · Polo: '+rhEsc(it.polo):'')
          +(it.situacao?' · '+rhEsc(it.situacao):'')+'</div>':'')
        +(it.revisado_em?'<div style="font-size:11px;color:#047857">Revisão: '+rhEsc(it.decisao_revisao||'')+' por '+rhEsc(it.revisado_por||'')+' em '+rhEsc(rhSelFmtDt(it.revisado_em))+'</div>':'')
        +(it.observacao_revisao?'<div style="font-size:11px">Obs.: '+rhEsc(it.observacao_revisao)+'</div>':'')
        +ac+'</div>';
    }).join('');
  }
  html+='</div>';
  box.innerHTML=html;
}
function rhSelIntRecalc(analise, itens){
  function countCat(cat){
    var n=0, hom=0, has=false, conf=0, semConsultaMarc=false;
    (itens||[]).forEach(function(it){
      if(it.ativo===false || it.categoria!==cat) return;
      if(it.status_confirmacao==='DESCARTADO') return;
      if(it.dados_json && it.dados_json.marcador_sem_ocorrencia){ has=true; semConsultaMarc=true; return; }
      has=true;
      if(it.status_confirmacao==='POSSIVEL_HOMONIMO' && !it.revisado_em){ hom++; return; }
      if(cat==='HC'){
        if(it.identificacao_metodo==='CPF_EXATO' || it.status_confirmacao==='CONFIRMADO'){ n++; conf++; }
        return;
      }
      if(cat==='PC'){
        if(it.status_confirmacao!=='DESCARTADO') n++;
        return;
      }
      // AC / PT: só confirmados (homônimo separado)
      if(it.status_confirmacao==='CONFIRMADO'){ n++; conf++; }
    });
    return {n:n, hom:hom, has:has, conf:conf, semConsultaMarc:semConsultaMarc};
  }
  var hc=countCat('HC'), pc=countCat('PC'), ac=countCat('AC'), pt=countCat('PT');
  function stFor(cat, x, cur){
    if(cat==='AC'||cat==='PT'){
      if(!x.has && (cur==='NAO_CONSULTADO'||!cur)) return 'NAO_CONSULTADO';
      if(x.has && x.n===0 && x.hom===0) return 'SEM_OCORRENCIA';
      if(x.hom && x.n===0) return 'INCONCLUSIVO';
      if(x.n>0) return 'COM_OCORRENCIA';
      return cur||'NAO_CONSULTADO';
    }
    if(cat==='HC'){
      if(!x.has) return 'SEM_OCORRENCIA';
      return x.n>0?'COM_OCORRENCIA':'SEM_OCORRENCIA';
    }
    if(!x.has) return 'SEM_OCORRENCIA';
    if(x.n>0 || x.hom>0) return 'COM_OCORRENCIA';
    return 'SEM_OCORRENCIA';
  }
  return {
    hc_quantidade:hc.n, pc_quantidade:pc.n, ac_quantidade:ac.n, pt_quantidade:pt.n,
    hc_status:stFor('HC',hc,analise.hc_status),
    pc_status:stFor('PC',pc,analise.pc_status),
    ac_status:stFor('AC',ac,analise.ac_status),
    pt_status:stFor('PT',pt,analise.pt_status)
  };
}
function rhSelIntPersistRecalc(analiseId, candidaturaId){
  return sbFetch('rh_candidato_integridade_itens',{filters:['integridade_id=eq.'+analiseId,'ativo=eq.true'],limit:300})
    .then(function(itens){
      _rhSelIntItens[String(analiseId)]=itens||[];
      var a=_rhSelIntByCand[String(candidaturaId)]||{id:analiseId};
      var patch=rhSelIntRecalc(a, itens||[]);
      var pend=(itens||[]).some(function(it){
        return it.ativo!==false && it.status_confirmacao==='POSSIVEL_HOMONIMO' && !it.revisado_em;
      }) || (itens||[]).some(function(it){
        return it.ativo!==false && it.categoria==='PC' && it.status_confirmacao==='INCONCLUSIVO' && !it.revisado_em;
      });
      if(a.status_analise!=='CONCLUIDA') patch.status_analise=pend?'PENDENTE_REVISAO':'EM_ANALISE';
      patch.updated_at=new Date().toISOString();
      return sbUpdate('rh_candidato_integridade', patch, 'id=eq.'+analiseId).then(function(){
        Object.assign(a, patch); _rhSelIntByCand[String(candidaturaId)]=a;
        return a;
      });
    });
}
function rhSelIntIniciar(candId){
  if(!rhSelIntPodeEditar()){ progShowToast('Sem permissão para integridade.','erro'); return; }
  var c=(_rhSelCand.lista||[]).filter(function(x){ return String(x.id)===String(candId); })[0];
  if(!c || !rhSelIntElegivelIniciar(c)){ progShowToast('Encerrar entrevistas antes de iniciar a integridade.','erro'); return; }
  if(!confirm('Iniciar análise de integridade?\n\nSerá executada apenas a verificação interna (HC/PC).\nAC/PT exigem registro manual ou provider autorizado.\nIsso NÃO aprova nem reprova o candidato.')) return;
  var v=_rhSel.atual||{};
  var agora=new Date().toISOString();
  var existente=_rhSelIntByCand[String(candId)];
  function aposCriar(a){
    _rhSelIntByCand[String(candId)]=a;
    return sbUpdate('rh_vaga_candidatos',{
      status:'INTEGRIDADE_EM_ANALISE', integridade_iniciada_em:agora, updated_at:agora
    },'id=eq.'+candId).then(function(){
      c.status='INTEGRIDADE_EM_ANALISE'; c.integridade_iniciada_em=agora;
      try{ auditLog('INICIOU_ANALISE_INTEGRIDADE','rh_selecao','Iniciou análise de integridade',{candidatura_id:candId,vaga_id:v.id,integridade_id:a.id}); }catch(e){}
      return rhSelIntRodarInterno(candId, a, false);
    });
  }
  var pCreate;
  if(existente && existente.id){
    pCreate=sbUpdate('rh_candidato_integridade',{
      status_analise:'EM_ANALISE', hc_status:'EM_ANALISE', pc_status:'EM_ANALISE',
      iniciada_em:existente.iniciada_em||agora, iniciada_por:existente.iniciada_por||rhSelIntUserNome(),
      updated_at:agora
    },'id=eq.'+existente.id).then(function(){
      Object.assign(existente,{status_analise:'EM_ANALISE',hc_status:'EM_ANALISE',pc_status:'EM_ANALISE'});
      return existente;
    });
  } else {
    pCreate=sbInsert('rh_candidato_integridade', {
      candidatura_id:candId, vaga_id:v.id,
      status_analise:'EM_ANALISE',
      hc_status:'EM_ANALISE', pc_status:'EM_ANALISE',
      ac_status:'NAO_CONSULTADO', pt_status:'NAO_CONSULTADO',
      hc_quantidade:0, pc_quantidade:0, ac_quantidade:0, pt_quantidade:0,
      iniciada_em:agora, iniciada_por:rhSelIntUserNome(), updated_at:agora
    }).then(function(rows){
      var a=Array.isArray(rows)?rows[0]:rows;
      if(!a||!a.id) throw new Error('Falha ao criar análise');
      return a;
    });
  }
  pCreate.then(aposCriar).then(function(){
    progShowToast('Análise de integridade iniciada.','ok');
    rhSelCandDetalhe(candId);
    if(v.id) rhSelCandidatosCarregar(v.id);
  }).catch(function(err){
    progShowToast('Não foi possível iniciar. Confira SQL 1F e permissões.','erro');
    console.warn(err);
  });
}
function rhSelIntAtualizarInterno(candId){
  if(!rhSelIntPodeEditar()) return;
  var a=_rhSelIntByCand[String(candId)];
  if(!a||a.status_analise==='CONCLUIDA'){ progShowToast('Análise inexistente ou concluída.','erro'); return; }
  rhSelIntRodarInterno(candId, a, true).then(function(){
    try{ auditLog('ATUALIZOU_HISTORICO_CENA','rh_selecao','Atualizou histórico interno HC/PC',{candidatura_id:candId,integridade_id:a.id}); }catch(e){}
    progShowToast('Histórico interno atualizado (itens anteriores preservados).','ok');
    var c=(_rhSelCand.lista||[]).filter(function(x){ return String(x.id)===String(candId); })[0];
    rhSelIntRenderPainel(candId, c||{});
  }).catch(function(e){ progShowToast('Falha ao atualizar histórico.','erro'); console.warn(e); });
}
function rhSelIntRodarInterno(candId, analise, soUpdate){
  var c=(_rhSelCand.lista||[]).filter(function(x){ return String(x.id)===String(candId); })[0]||{};
  var cpf=rhSelIntNormCpf(c.cpf);
  var agora=new Date().toISOString();
  var pColabs=(typeof rhSynCarregarColabs==='function')?rhSynCarregarColabs(false):Promise.resolve([]);
  return Promise.all([
    pColabs,
    sbFetch('rh_candidato_integridade_itens',{filters:['integridade_id=eq.'+analise.id],limit:300}).catch(function(){return [];})
  ]).then(function(arr){
    var colabs=arr[0]||[];
    var existentes=arr[1]||[];
    var jaHc={}; // colaborador_id já registrado
    existentes.forEach(function(it){
      if(it.categoria==='HC' && it.dados_json && it.dados_json.colaborador_id) jaHc[String(it.dados_json.colaborador_id)]=1;
    });
    var novos=[];
    if(cpf && cpf.length===11){
      colabs.forEach(function(col){
        var ok=false;
        if(typeof rhSynCenaTemCpf==='function') ok=rhSynCenaTemCpf(col, cpf);
        else ok=rhSelIntNormCpf(col.cpf)===cpf || rhSelIntNormCpf(col.bro)===cpf;
        if(!ok) return;
        var cid=String(col.id);
        if(jaHc[cid]) return;
        jaHc[cid]=1;
        var adm=col.admissao||col.data_admissao||null;
        var desl=col.data_dispensa||null;
        var desc='Vínculo interno por CPF exato. Cargo: '+(col.cargo||'—')
          +(adm?' · Admissão: '+String(adm).slice(0,10):'')
          +(desl?' · Desligamento: '+String(desl).slice(0,10):'')
          +(col.dispensado?' · Situação: desligado':' · Situação: '+(col.ativo===false?'inativo':'ativo'));
        novos.push({
          integridade_id:analise.id, candidatura_id:candId, categoria:'HC',
          fonte:'INTERNA_CENA', fonte_tipo:'INTERNA', fonte_referencia:'colaboradores',
          identificacao_metodo:'CPF_EXATO', status_confirmacao:'CONFIRMADO',
          titulo:'Histórico CENA — '+(col.nome||'colaborador'),
          descricao_resumida:desc,
          situacao:col.dispensado?'DESLIGADO':(col.ativo===false?'INATIVO':'ATIVO'),
          data_referencia:adm?String(adm).slice(0,10):null,
          dados_json:{colaborador_id:col.id, re:col.re||null, cargo:col.cargo||null, vinculo_ref:col.vinculo_ref||null, fonte_dp:col.fonte_dp||null},
          consultado_em:agora, consultado_por:rhSelIntUserNome(), ativo:true, updated_at:agora
        });
      });
    }
    // PC interno suave: mesmo telefone que colaborador com CPF diferente (possível vínculo — revisar)
    var tel=rhSelIntNormTel(c.telefone);
    var jaPcTel=existentes.some(function(it){ return it.categoria==='PC' && it.fonte_referencia==='mesmo_telefone'; });
    if(tel && tel.length>=10 && !jaPcTel){
      var hit=null;
      colabs.some(function(col){
        var tcol=rhSelIntNormTel(col.telefone||col.celular||'');
        if(!tcol || tcol.slice(-8)!==tel.slice(-8)) return false;
        var cpfCol=typeof rhSynCenaCpf==='function'?rhSynCenaCpf(col):rhSelIntNormCpf(col.cpf||col.bro);
        if(cpf && cpfCol && cpfCol===cpf) return false; // mesmo CPF = HC
        hit=col; return true;
      });
      if(hit){
        novos.push({
          integridade_id:analise.id, candidatura_id:candId, categoria:'PC',
          fonte:'INTERNA_CENA', fonte_tipo:'INTERNA', fonte_referencia:'mesmo_telefone',
          identificacao_metodo:'OUTRO', status_confirmacao:'INCONCLUSIVO',
          titulo:'Possível vínculo — mesmo contato',
          descricao_resumida:'Possível correspondência de telefone com colaborador interno "'+(hit.nome||'')+'". POSSÍVEL VÍNCULO — REQUER REVISÃO. Não confirma parentesco.',
          dados_json:{colaborador_id:hit.id, regra:'mesmo_telefone'},
          consultado_em:agora, consultado_por:rhSelIntUserNome(), ativo:true, updated_at:agora
        });
      }
    }
    var chain=Promise.resolve();
    if(novos.length){
      chain=sbInsert('rh_candidato_integridade_itens', novos).then(function(){
        if(novos.some(function(n){return n.categoria==='HC';})){
          try{ auditLog('LOCALIZOU_HISTORICO_CENA','rh_selecao','Localizou histórico CENA (HC)',{candidatura_id:candId,qtd:novos.filter(function(n){return n.categoria==='HC';}).length}); }catch(e){}
        }
        if(novos.some(function(n){return n.categoria==='PC';})){
          try{ auditLog('REGISTROU_POSSIVEL_CONFLITO','rh_selecao','Registrou possível conflito interno',{candidatura_id:candId}); }catch(e){}
        }
      });
    }
    return chain.then(function(){ return rhSelIntPersistRecalc(analise.id, candId); });
  });
}
function rhSelIntAbrirRegistro(candId, cat){
  if(!rhSelIntPodeEditar()) return;
  if((cat==='AC'||cat==='PT') && !rhSelIntPodeVerDetalhe()){ progShowToast('Sem permissão.','erro'); return; }
  var a=_rhSelIntByCand[String(candId)];
  if(!a||a.status_analise==='CONCLUIDA'){ progShowToast('Inicie a análise antes.','erro'); return; }
  var box=document.getElementById('rh-sel-int-modal'); if(!box) return;
  var tit=({PC:'Registrar possível conflito',AC:'Registrar consulta criminal (AC)',PT:'Registrar consulta trabalhista (PT)'})[cat]||'Registrar';
  box.classList.remove('hidden');
  box.innerHTML='<div style="position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:9200;display:flex;align-items:center;justify-content:center;padding:1rem" onclick="if(event.target===this)rhSelIntFecharModal()">'
    +'<div style="background:#fff;border-radius:12px;padding:1.1rem;max-width:480px;width:100%;max-height:92vh;overflow:auto" onclick="event.stopPropagation()">'
    +'<div style="font-weight:800;margin-bottom:8px">'+rhEsc(tit)+'</div>'
    +'<div style="font-size:11px;color:#666;margin-bottom:10px">Somente fonte autorizada / certidão / registro manual. Sem scraping. CPF mascarado na tela.</div>'
    +'<div class="fg"><label>Fonte *</label><input class="inp" id="rh-int-fonte" placeholder="Ex.: Certidão X / consulta manual"/></div>'
    +'<div class="fg"><label>Tipo de fonte</label><select class="inp" id="rh-int-fonte-tipo">'
    +'<option value="MANUAL">MANUAL</option><option value="CERTIDAO">CERTIDAO</option>'
    +'<option value="API_OFICIAL">API_OFICIAL</option><option value="PROVEDOR">PROVEDOR_CONTRATADO</option></select></div>'
    +'<div class="fg"><label>Data da consulta *</label><input class="inp" id="rh-int-data" type="datetime-local"/></div>'
    +'<div class="fg"><label>Resultado *</label><select class="inp" id="rh-int-resultado">'
    +'<option value="SEM_OCORRENCIA">SEM_OCORRENCIA</option>'
    +'<option value="COM_OCORRENCIA">COM_OCORRENCIA</option>'
    +'<option value="INCONCLUSIVO">INCONCLUSIVO</option></select></div>'
    +(cat!=='PC'?'<div class="fg"><label>Identificação</label><select class="inp" id="rh-int-metodo">'
      +'<option value="CPF_EXATO">CPF_EXATO</option><option value="NOME">NOME (possível homônimo)</option><option value="OUTRO">OUTRO</option></select></div>':'')
    +(cat!=='PC'?'<div class="fg"><label>Nº processo (CNJ)</label><input class="inp" id="rh-int-proc"/></div>'
      +'<div class="fg"><label>Tribunal</label><input class="inp" id="rh-int-tribunal"/></div>'
      +'<div class="fg"><label>Classe</label><input class="inp" id="rh-int-classe"/></div>'
      +'<div class="fg"><label>Polo</label><select class="inp" id="rh-int-polo">'
      +'<option value="">—</option><option>RECLAMANTE</option><option>RECLAMADO</option><option>TERCEIRO</option><option>OUTRO</option><option>INDETERMINADO</option></select></div>'
      +'<div class="fg"><label>Situação</label><input class="inp" id="rh-int-sit" placeholder="Ex.: Processo / Certidão / Sem registro"/></div>':'')
    +'<div class="fg"><label>Título</label><input class="inp" id="rh-int-titulo" value="'+(cat==='PC'?'Possível conflito — revisão':'Ocorrência '+cat)+'"/></div>'
    +'<div class="fg"><label>Descrição / observação</label><textarea class="inp" id="rh-int-obs" rows="3"></textarea></div>'
    +'<div class="fg"><label>Referência / anexo (texto)</label><input class="inp" id="rh-int-ref" placeholder="Ref. interna ou nome do arquivo (storage privado futuro)"/></div>'
    +'<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px">'
    +'<button class="btn" type="button" onclick="rhSelIntFecharModal()">Cancelar</button>'
    +'<button class="btn btn-pri" type="button" onclick="rhSelIntSalvarRegistro(\''+String(candId).replace(/'/g,'')+'\',\''+cat+'\')">Salvar</button></div>'
    +'</div></div>';
}
function rhSelIntFecharModal(){
  var box=document.getElementById('rh-sel-int-modal');
  if(box){ box.classList.add('hidden'); box.innerHTML=''; }
}
function rhSelIntSalvarRegistro(candId, cat){
  var a=_rhSelIntByCand[String(candId)]; if(!a) return;
  var fonte=(document.getElementById('rh-int-fonte')||{}).value||'';
  var fonteTipo=(document.getElementById('rh-int-fonte-tipo')||{}).value||'MANUAL';
  var dataEl=(document.getElementById('rh-int-data')||{}).value;
  var resultado=(document.getElementById('rh-int-resultado')||{}).value;
  var metodo=(document.getElementById('rh-int-metodo')||{}).value||(cat==='PC'?'OUTRO':'CPF_EXATO');
  var proc=(document.getElementById('rh-int-proc')||{}).value||'';
  var tribunal=(document.getElementById('rh-int-tribunal')||{}).value||'';
  var classe=(document.getElementById('rh-int-classe')||{}).value||'';
  var polo=(document.getElementById('rh-int-polo')||{}).value||'';
  var sit=(document.getElementById('rh-int-sit')||{}).value||'';
  var titulo=(document.getElementById('rh-int-titulo')||{}).value||('Registro '+cat);
  var obs=(document.getElementById('rh-int-obs')||{}).value||'';
  var ref=(document.getElementById('rh-int-ref')||{}).value||'';
  if(!fonte || !dataEl || !resultado){ progShowToast('Preencha fonte, data e resultado.','erro'); return; }
  var agora=new Date(dataEl).toISOString();
  var procNorm=rhSelIntNormProc(proc);
  // Dedup por CNJ
  var existentes=_rhSelIntItens[String(a.id)]||[];
  if(procNorm && (cat==='AC'||cat==='PT')){
    var dup=existentes.filter(function(it){
      return it.ativo!==false && it.categoria===cat && it.numero_processo_norm===procNorm && it.status_confirmacao!=='DESCARTADO';
    })[0];
    if(dup){
      // Mesma ocorrência: acrescenta fonte na observação, não incrementa contador
      var dj=dup.dados_json||{};
      var fontes=dj.fontes||[];
      fontes.push({fonte:fonte, fonte_tipo:fonteTipo, em:agora, por:rhSelIntUserNome()});
      sbUpdate('rh_candidato_integridade_itens',{
        dados_json:Object.assign({}, dj, {fontes:fontes}),
        observacao_revisao:(dup.observacao_revisao?dup.observacao_revisao+'\n':'')+'Fonte adicional: '+fonte,
        updated_at:new Date().toISOString()
      },'id=eq.'+dup.id).then(function(){
        progShowToast('Mesmo processo CNJ — fonte adicional registrada (sem duplicar contagem).','ok');
        rhSelIntFecharModal();
        rhSelIntPersistRecalc(a.id, candId).then(function(){
          var c=(_rhSelCand.lista||[]).filter(function(x){ return String(x.id)===String(candId); })[0];
          rhSelIntRenderPainel(candId, c||{});
        });
      });
      return;
    }
  }
  var conf='CONFIRMADO';
  if(resultado==='SEM_OCORRENCIA'){
    // Item marcador de consulta sem ocorrência
    conf='CONFIRMADO';
  } else if(metodo==='NOME'){
    conf='POSSIVEL_HOMONIMO';
  } else if(resultado==='INCONCLUSIVO'){
    conf='INCONCLUSIVO';
  }
  var item={
    integridade_id:a.id, candidatura_id:candId, categoria:cat,
    fonte:fonte, fonte_tipo:fonteTipo, fonte_referencia:ref||null,
    identificacao_metodo:metodo, status_confirmacao:conf,
    titulo:titulo,
    descricao_resumida:(resultado==='SEM_OCORRENCIA'
      ?('Consulta registrada: nenhuma ocorrência retornada na fonte consultada. '+(obs||''))
      :(obs||('Ocorrência registrada — '+resultado))),
    numero_processo:proc||null, numero_processo_norm:procNorm||null,
    tribunal:tribunal||null, classe_processual:classe||null, polo:polo||null,
    situacao:sit||resultado, consultado_em:agora, consultado_por:rhSelIntUserNome(),
    dados_json:{resultado:resultado, anexo_ref:ref||null, aviso:'processo_nao_e_condenacao'},
    ativo:true, updated_at:new Date().toISOString()
  };
  // SEM_OCORRENCIA: item especial que zera contagem mas marca consultado
  if(resultado==='SEM_OCORRENCIA'){
    item.titulo='Consulta '+cat+' — sem ocorrência';
    item.status_confirmacao='CONFIRMADO';
    item.dados_json.marcador_sem_ocorrencia=true;
  }
  sbInsert('rh_candidato_integridade_itens', item).then(function(){
    var ev=cat==='AC'?'REGISTROU_CONSULTA_CRIMINAL':(cat==='PT'?'REGISTROU_CONSULTA_TRABALHISTA':'REGISTROU_POSSIVEL_CONFLITO');
    try{ auditLog(ev,'rh_selecao','Registrou '+cat+' (manual/fonte autorizada)',{candidatura_id:candId,integridade_id:a.id,categoria:cat,resultado:resultado}); }catch(e){}
    // Atualiza status do indicador
    var patch={updated_at:new Date().toISOString()};
    if(resultado==='SEM_OCORRENCIA'){
      patch[cat.toLowerCase()+'_status']='SEM_OCORRENCIA';
      patch[cat.toLowerCase()+'_quantidade']=0;
    } else {
      patch[cat.toLowerCase()+'_status']='COM_OCORRENCIA';
    }
    return sbUpdate('rh_candidato_integridade', patch, 'id=eq.'+a.id).then(function(){
      return rhSelIntPersistRecalc(a.id, candId);
    });
  }).then(function(){
    rhSelIntFecharModal();
    progShowToast('Registro salvo.','ok');
    var c=(_rhSelCand.lista||[]).filter(function(x){ return String(x.id)===String(candId); })[0];
    rhSelIntRenderPainel(candId, c||{});
  }).catch(function(e){ progShowToast('Falha ao salvar registro.','erro'); console.warn(e); });
}
function rhSelIntRevisarItem(itemId, decisao){
  if(!rhSelIntPodeEditar()) return;
  var obs='';
  if(decisao==='ESCLARECIMENTO'||decisao==='DESCARTADO'||decisao==='POSSIVEL_HOMONIMO'){
    obs=prompt('Observação / justificativa'+(decisao==='ESCLARECIMENTO'?' (obrigatória)':'')+':','')||'';
    if(decisao==='ESCLARECIMENTO' && !obs){ progShowToast('Justificativa obrigatória.','erro'); return; }
  }
  var agora=new Date().toISOString();
  var conf=decisao==='ESCLARECIMENTO'?'INCONCLUSIVO':decisao;
  var patch={
    status_confirmacao:conf,
    revisado_em:agora, revisado_por:rhSelIntUserNome(),
    decisao_revisao:decisao, observacao_revisao:obs||null, updated_at:agora
  };
  sbUpdate('rh_candidato_integridade_itens', patch, 'id=eq.'+itemId).then(function(){
    var ev=decisao==='CONFIRMADO'?'CONFIRMOU_CORRESPONDENCIA':(decisao==='POSSIVEL_HOMONIMO'?'MARCOU_POSSIVEL_HOMONIMO':(decisao==='DESCARTADO'?'DESCARTOU_CORRESPONDENCIA':'REVISOU_CONFLITO'));
    try{ auditLog(ev,'rh_selecao','Revisou item de integridade',{item_id:itemId,decisao:decisao}); }catch(e){}
    // achar candidatura
    var candId=null, intId=null;
    Object.keys(_rhSelIntItens).forEach(function(iid){
      (_rhSelIntItens[iid]||[]).forEach(function(it){ if(String(it.id)===String(itemId)){ intId=iid; candId=it.candidatura_id; } });
    });
    if(!candId){
      Object.keys(_rhSelIntByCand).forEach(function(cid){
        var a=_rhSelIntByCand[cid]; if(a && String(a.id)===String(intId)) candId=cid;
      });
    }
    // reload item list from cache update
    Object.keys(_rhSelIntItens).forEach(function(iid){
      (_rhSelIntItens[iid]||[]).forEach(function(it){ if(String(it.id)===String(itemId)) Object.assign(it, patch); });
    });
    var p=intId?rhSelIntPersistRecalc(intId, candId):Promise.resolve();
    return p.then(function(){
      if(candId){
        var c=(_rhSelCand.lista||[]).filter(function(x){ return String(x.id)===String(candId); })[0];
        rhSelIntRenderPainel(candId, c||{});
        rhSelIntToggleDetalhe(candId, (Object.keys(_rhSelIntItens).length?(function(){
          var cat='HC';
          Object.keys(_rhSelIntItens).forEach(function(iid){
            (_rhSelIntItens[iid]||[]).forEach(function(it){ if(String(it.id)===String(itemId)) cat=it.categoria; });
          });
          return cat;
        })():'HC'));
      }
      progShowToast('Revisão registrada.','ok');
    });
  }).catch(function(e){ progShowToast('Falha na revisão.','erro'); console.warn(e); });
}
function rhSelIntConcluir(candId){
  if(!rhSelIntPodeEditar()) return;
  var a=_rhSelIntByCand[String(candId)]; if(!a) return;
  var itens=_rhSelIntItens[String(a.id)]||[];
  var pend=itens.filter(function(it){
    return it.ativo!==false && ((it.status_confirmacao==='POSSIVEL_HOMONIMO'&&!it.revisado_em)||(it.categoria==='PC'&&it.status_confirmacao==='INCONCLUSIVO'&&!it.revisado_em));
  });
  var msg='Concluir análise de integridade?\n\n'
    +'HC '+a.hc_quantidade+' · PC '+a.pc_quantidade+' · AC '+(a.ac_status==='NAO_CONSULTADO'?'—':a.ac_quantidade)+' · PT '+(a.pt_status==='NAO_CONSULTADO'?'—':a.pt_quantidade)+'\n'
    +(pend.length?'⚠ '+pend.length+' item(ns) pendente(s) de revisão.\n':'')
    +'\nIsso NÃO aprova nem reprova. Segue para decisão humana (RH-SEL-1G futura).';
  if(!confirm(msg)) return;
  var just='';
  if(pend.length){
    just=prompt('Há pendências. Informe justificativa para concluir mesmo assim:','')||'';
    if(!just){ progShowToast('Justificativa obrigatória com pendências.','erro'); return; }
  }
  var parecer=prompt('Parecer interno / observações (opcional):','')||'';
  var agora=new Date().toISOString();
  var snap={
    em:agora, por:rhSelIntUserNome(),
    hc:a.hc_quantidade, pc:a.pc_quantidade, ac:a.ac_quantidade, pt:a.pt_quantidade,
    hc_status:a.hc_status, pc_status:a.pc_status, ac_status:a.ac_status, pt_status:a.pt_status,
    itens:(itens||[]).map(function(it){
      return {id:it.id,categoria:it.categoria,status_confirmacao:it.status_confirmacao,titulo:it.titulo,
        fonte:it.fonte,numero_processo:it.numero_processo,identificacao_metodo:it.identificacao_metodo,
        revisado_em:it.revisado_em,decisao_revisao:it.decisao_revisao};
    }),
    pendencias:pend.length, justificativa_pendencia:just||null
  };
  var patch={
    status_analise:'CONCLUIDA', concluida_em:agora, concluida_por:rhSelIntUserNome(),
    parecer_geral:parecer||null, snapshot_json:snap, updated_at:agora,
    hc_status:a.hc_status==='NAO_CONSULTADO'?'NAO_CONSULTADO':(a.hc_status==='COM_OCORRENCIA'?'REVISADO':a.hc_status),
    pc_status:a.pc_status==='NAO_CONSULTADO'?'NAO_CONSULTADO':(a.pc_status==='COM_OCORRENCIA'||a.pc_status==='INCONCLUSIVO'?'REVISADO':a.pc_status)
  };
  sbUpdate('rh_candidato_integridade', patch, 'id=eq.'+a.id).then(function(){
    return sbUpdate('rh_vaga_candidatos',{
      status:'INTEGRIDADE_CONCLUIDA', integridade_concluida_em:agora, updated_at:agora
    },'id=eq.'+candId);
  }).then(function(){
    Object.assign(a, patch); _rhSelIntByCand[String(candId)]=a;
    var c=(_rhSelCand.lista||[]).filter(function(x){ return String(x.id)===String(candId); })[0];
    if(c){ c.status='INTEGRIDADE_CONCLUIDA'; c.integridade_concluida_em=agora; }
    try{ auditLog('CONCLUIU_ANALISE_INTEGRIDADE','rh_selecao','Concluiu análise de integridade',{candidatura_id:candId,integridade_id:a.id,pendencias:pend.length}); }catch(e){}
    progShowToast('Análise concluída. Sem aprovação automática. Pode seguir para o Resultado (RH-SEL-1G).','ok');
    rhSelCandDetalhe(candId);
    if(_rhSel.atual&&_rhSel.atual.id) rhSelCandidatosCarregar(_rhSel.atual.id);
  }).catch(function(e){ progShowToast('Falha ao concluir.','erro'); console.warn(e); });
}
function rhSelIntReabrir(candId){
  if(!rhSelIntPodeEditar()) return;
  var a=_rhSelIntByCand[String(candId)]; if(!a||a.status_analise!=='CONCLUIDA') return;
  var motivo=prompt('Justificativa para reabrir a análise:','')||'';
  if(!motivo){ progShowToast('Justificativa obrigatória.','erro'); return; }
  var agora=new Date().toISOString();
  // Mantém snapshot_json e concluida_em anteriores (auditoria); status volta a EM_ANALISE.
  sbUpdate('rh_candidato_integridade',{
    status_analise:'EM_ANALISE',
    reaberta_em:agora, reaberta_por:rhSelIntUserNome(), reabertura_motivo:motivo,
    updated_at:agora
  },'id=eq.'+a.id).then(function(){
    return sbUpdate('rh_vaga_candidatos',{
      status:'INTEGRIDADE_EM_ANALISE', updated_at:agora
    },'id=eq.'+candId);
  }).then(function(){
    a.status_analise='EM_ANALISE'; a.reabertura_motivo=motivo; a.reaberta_em=agora;
    var c=(_rhSelCand.lista||[]).filter(function(x){ return String(x.id)===String(candId); })[0];
    if(c){ c.status='INTEGRIDADE_EM_ANALISE'; }
    try{ auditLog('REABRIU_ANALISE_INTEGRIDADE','rh_selecao','Reabriu análise de integridade',{candidatura_id:candId,integridade_id:a.id}); }catch(e){}
    progShowToast('Análise reaberta. Snapshot anterior preservado.','ok');
    rhSelCandDetalhe(candId);
  }).catch(function(e){ progShowToast('Falha ao reabrir.','erro'); console.warn(e); });
}

// =============================================================================
// RH-SEL-1G — Resultado / Aprovação → Encaminhamento Contratação (sem RH-2A)
// Decisão humana. Sem score. Sem criar/ativar colaborador.
// =============================================================================
function rhSelResUserNome(){ return (usuarioLogado&&usuarioLogado.nome)||''; }
function rhSelResUserId(){ return (usuarioLogado&&usuarioLogado.id)||''; }
function rhSelResMotivos(){
  return [
    ['OUTRO_CANDIDATO_SELECIONADO','Outro candidato selecionado'],
    ['REQUISITO_TECNICO_NAO_ATENDIDO','Requisito técnico não atendido'],
    ['EXPERIENCIA_INSUFICIENTE_PARA_A_VAGA','Experiência insuficiente para a vaga'],
    ['DISPONIBILIDADE_INCOMPATIVEL','Disponibilidade incompatível'],
    ['PRETENSAO_INCOMPATIVEL','Pretensão incompatível'],
    ['CANDIDATO_DESISTIU','Candidato desistiu'],
    ['CANDIDATO_NAO_COMPARECEU','Candidato não compareceu'],
    ['VAGA_CANCELADA','Vaga cancelada'],
    ['VAGA_SUSPENSA','Vaga suspensa'],
    ['PROCESSO_ENCERRADO_SEM_CONTRATACAO','Processo encerrado sem contratação'],
    ['OUTRO','Outro']
  ];
}
function rhSelResResumoCand(cid, c){
  c=c||{};
  var r=_rhSelResByCand[String(cid)];
  var st=c.status||'';
  if(st==='ENCAMINHADO_ADMISSAO' || (r&&r.status==='ENCAMINHADO_ADMISSAO')) return '↗ Encaminhado';
  if(st==='APROVADO_PARA_ADMISSAO' || (r&&r.decisao==='APROVADO_PARA_ADMISSAO')) return '✓ Aprovado p/ admissão';
  if(st==='NAO_SELECIONADO' || (r&&r.decisao==='NAO_SELECIONADO')) return '✕ Não selecionado';
  if(st==='EM_DECISAO_FINAL' || (r&&r.decisao==='EM_ANALISE')) return 'Em decisão';
  if(st==='INTEGRIDADE_CONCLUIDA' || c.integridade_concluida_em) return '— Aguardando decisão';
  return '— Aguardando etapas';
}
function rhSelResElegivelDecidir(c){
  if(!c) return {ok:false, motivo:'Candidato inválido.'};
  if(c.status==='REVOGADO'||c.status==='EXPIRADO'||c.status==='DESISTENTE'||c.status==='DESCARTADO')
    return {ok:false, motivo:'Candidatura não elegível.'};
  if(c.status==='APROVADO_PARA_ADMISSAO'||c.status==='NAO_SELECIONADO'||c.status==='ENCAMINHADO_ADMISSAO')
    return {ok:false, motivo:'Decisão já registrada. Use Reabrir se autorizado.'};
  var r=_rhSelResByCand[String(c.id)];
  if(r && (r.decisao==='APROVADO_PARA_ADMISSAO'||r.decisao==='NAO_SELECIONADO') && r.status!=='REABERTO' && c.status!=='EM_DECISAO_FINAL')
    return {ok:false, motivo:'Decisão já registrada.'};
  var entOk=!!(c.entrevistas_encerradas_em || c.status==='ENTREVISTAS_CONCLUIDAS' || c.status==='INTEGRIDADE_EM_ANALISE' || c.status==='INTEGRIDADE_CONCLUIDA' || c.status==='EM_DECISAO_FINAL' || c.integridade_concluida_em);
  var intOk=!!(c.integridade_concluida_em || c.status==='INTEGRIDADE_CONCLUIDA' || c.status==='EM_DECISAO_FINAL');
  var a=_rhSelIntByCand[String(c.id)];
  if(a && a.status_analise==='CONCLUIDA') intOk=true;
  if(!entOk) return {ok:false, motivo:'Entrevistas ainda não concluídas.'};
  if(!intOk) return {ok:false, motivo:'Análise de integridade ainda não concluída.'};
  return {ok:true};
}
function rhSelResSnapshot(candId, c){
  var v=_rhSel.atual||{};
  var ents=(_rhSelCandEntByCand[String(candId)]||[]).filter(function(e){return e.status==='CONCLUIDA';});
  var a=_rhSelIntByCand[String(candId)]||{};
  return {
    vaga_id:v.id||null, cargo_id:v.cargo_id||null, cargo_nome:v.cargo_nome||null,
    candidato_nome:c.nome||null,
    testes_concluidos:!!(c.testes_concluidos_em||c.status==='TESTES_CONCLUIDOS'||c.integridade_concluida_em),
    entrevistas:ents.map(function(e){ return {tipo:e.tipo, recomendacao:e.recomendacao||null, concluida_em:e.concluida_em}; }),
    integridade:{
      status_analise:a.status_analise||null,
      hc_status:a.hc_status||null, pc_status:a.pc_status||null,
      ac_status:a.ac_status||null, pt_status:a.pt_status||null,
      hc_quantidade:a.hc_quantidade, pc_quantidade:a.pc_quantidade
      // AC/PT: só status — sem detalhe sensível
    },
    em:new Date().toISOString(), por:rhSelResUserNome()
  };
}
function rhSelResRenderPainel(candId, c){
  var el=document.getElementById('rh-sel-cand-res'); if(!el) return;
  var pode=rhSelResPodeDecidir();
  var podeInt=rhSelIntPodeVerDetalhe();
  el.innerHTML='<b>Resultado do processo seletivo</b> <span style="font-size:11px;color:#888">(RH-SEL-1G — decisão humana)</span><div style="color:#888;margin-top:6px">Carregando…</div>';
  function pintar(res){
    if(res) _rhSelResByCand[String(candId)]=res;
    var a=_rhSelIntByCand[String(candId)];
    var ents=_rhSelCandEntByCand[String(candId)]||[];
    var conc=ents.filter(function(e){return e.status==='CONCLUIDA';});
    var elig=rhSelResElegivelDecidir(c);
    var html='<b>Resultado do processo seletivo</b> <span style="font-size:11px;color:#888">(sem score / sem aprovação automática)</span>';
    html+='<div style="margin-top:8px;padding:8px;background:#F8FAFC;border-radius:8px;font-size:12px;line-height:1.5">'
      +'<div>✓ Identificação: '+(c.identificacao_concluida_em?'Concluída':'Pendente')+'</div>'
      +'<div>✓ Testes: '+(c.testes_concluidos_em||c.status==='TESTES_CONCLUIDOS'||c.integridade_concluida_em?'Concluídos':'Pendentes')+'</div>';
    if(conc.length){
      conc.forEach(function(e){
        html+='<div>✓ '+rhEsc(rhSelEntTipoLabel(e.tipo))+': Concluída'
          +(e.recomendacao?' · Recomendação humana: <b>'+rhEsc(e.recomendacao)+'</b>':'')+'</div>';
      });
    } else html+='<div>Entrevistas: '+(c.entrevistas_encerradas_em?'Encerradas':'Pendentes')+'</div>';
    if(a && a.status_analise==='CONCLUIDA'){
      html+='<div>✓ Integridade: Concluída</div>';
      html+='<div style="margin-left:8px;color:#555">HC '+(a.hc_quantidade!=null?a.hc_quantidade:'—')
        +' · PC '+(a.pc_quantidade!=null?a.pc_quantidade:'—');
      if(podeInt) html+=' · AC '+(a.ac_status==='NAO_CONSULTADO'?'—':(a.ac_quantidade!=null?a.ac_quantidade:'—'))
        +' · PT '+(a.pt_status==='NAO_CONSULTADO'?'—':(a.pt_quantidade!=null?a.pt_quantidade:'—'));
      else html+=' · AC/PT: análise concluída (detalhe restrito)';
      html+='</div>';
    } else {
      html+='<div>Integridade: '+(c.integridade_concluida_em?'Concluída':'Não concluída')+'</div>';
    }
    html+='</div>';

    var stLab=rhSelResResumoCand(candId, c);
    html+='<div style="margin-top:8px;font-size:12px">Status atual: <b>'+rhEsc(stLab)+'</b></div>';

    if(res && res.decisao && res.decisao!=='EM_ANALISE'){
      html+='<div style="margin-top:8px;font-size:12px;padding:8px;border:1px solid #e5e7eb;border-radius:8px">'
        +'<div>Decisão: <b>'+rhEsc(res.decisao)+'</b></div>'
        +(res.decidido_por_nome?'<div>Por: '+rhEsc(res.decidido_por_nome)+' · '+rhEsc(rhSelFmtDt(res.decidido_em))+'</div>':'')
        +(res.motivo_codigo?'<div>Motivo: '+rhEsc(res.motivo_codigo)+(res.motivo_descricao?' — '+rhEsc(res.motivo_descricao):'')+'</div>':'')
        +(res.observacao?'<div>Obs.: '+rhEsc(res.observacao)+'</div>':'')
        +(res.processo_contratacao_id?'<div>Processo contratação: <code>'+rhEsc(String(res.processo_contratacao_id).slice(0,8))+'…</code></div>':'')
        +'</div>';
    }

    if(pode){
      html+='<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:10px">';
      if(elig.ok){
        html+='<button class="btn btn-sm btn-pri" type="button" onclick="rhSelResAbrirAprovar(\''+String(candId).replace(/'/g,'')+'\')">Aprovar para admissão</button>'
          +'<button class="btn btn-sm" type="button" onclick="rhSelResAbrirNaoSelecionar(\''+String(candId).replace(/'/g,'')+'\')">Não selecionar</button>'
          +'<button class="btn btn-sm" type="button" onclick="rhSelResManterAnalise(\''+String(candId).replace(/'/g,'')+'\')">Manter em análise</button>';
      } else if(elig.motivo){
        html+='<div style="font-size:11px;color:#854F0B;width:100%">'+rhEsc(elig.motivo)+'</div>';
      }
      if(c.status==='APROVADO_PARA_ADMISSAO' || (res&&res.decisao==='APROVADO_PARA_ADMISSAO'&&c.status!=='ENCAMINHADO_ADMISSAO'&&c.status!=='NAO_SELECIONADO')){
        html+='<button class="btn btn-sm btn-pri" type="button" onclick="rhSelResEncaminhar(\''+String(candId).replace(/'/g,'')+'\')">Encaminhar para admissão</button>';
      }
      if(c.status==='ENCAMINHADO_ADMISSAO' || (res&&res.processo_contratacao_id)){
        html+='<button class="btn btn-sm" type="button" onclick="rhSelResAbrirContratacao(\''+String((res&&res.processo_contratacao_id)||'').replace(/'/g,'')+'\')">Abrir Contratação / Promoção</button>';
      }
      if(res && (res.decisao==='APROVADO_PARA_ADMISSAO'||res.decisao==='NAO_SELECIONADO') && c.status!=='ENCAMINHADO_ADMISSAO'){
        html+='<button class="btn btn-sm" type="button" onclick="rhSelResReabrir(\''+String(candId).replace(/'/g,'')+'\')">Reabrir decisão</button>';
      }
      if(c.status==='APROVADO_PARA_ADMISSAO'||c.status==='ENCAMINHADO_ADMISSAO'){
        html+='<button class="btn btn-sm" type="button" onclick="rhSelResCopiarMsg(\''+String(candId).replace(/'/g,'')+'\')">Copiar mensagem interna</button>';
      }
      html+='</div>';
    } else {
      html+='<div style="margin-top:8px;font-size:11px;color:#854F0B;background:#FEF3E2;padding:8px;border-radius:8px">Decisão final restrita a RH/DP/admin/diretoria.</div>';
    }
    el.innerHTML=html;
  }
  if(DEMO){ pintar(_rhSelResByCand[String(candId)]||null); return; }
  sbFetch('rh_candidato_resultado_selecao',{filters:['candidatura_id=eq.'+encodeURIComponent(candId)],limit:1})
    .then(function(rows){ pintar((rows&&rows[0])||_rhSelResByCand[String(candId)]||null); })
    .catch(function(){
      el.innerHTML='<b>Resultado do processo seletivo</b><div style="color:#854F0B;background:#FEF3E2;padding:8px;border-radius:8px;margin-top:6px">Aplique <code>SQLS/sql_rh_selecao_resultado_fase_sel1g.sql</code>.</div>';
    });
}
function rhSelResFecharModal(){
  var box=document.getElementById('rh-sel-res-modal');
  if(box){ box.classList.add('hidden'); box.innerHTML=''; }
}
function rhSelResAbrirAprovar(candId){
  if(!rhSelResPodeDecidir()) return;
  var c=(_rhSelCand.lista||[]).filter(function(x){return String(x.id)===String(candId);})[0];
  if(!c) return;
  var elig=rhSelResElegivelDecidir(c);
  if(!elig.ok){ progShowToast(elig.motivo||'Não elegível.','erro'); return; }
  var v=_rhSel.atual||{};
  var box=document.getElementById('rh-sel-res-modal'); if(!box) return;
  box.classList.remove('hidden');
  box.innerHTML='<div style="position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:9300;display:flex;align-items:center;justify-content:center;padding:1rem" onclick="if(event.target===this)rhSelResFecharModal()">'
    +'<div style="background:#fff;border-radius:12px;padding:1.1rem;max-width:460px;width:100%;max-height:92vh;overflow:auto" onclick="event.stopPropagation()">'
    +'<div style="font-weight:800;margin-bottom:8px">Aprovar para admissão</div>'
    +'<div style="font-size:12px;line-height:1.5;margin-bottom:10px">'
    +'<div>Candidato: <b>'+rhEsc(c.nome)+'</b></div>'
    +'<div>Cargo: '+rhEsc(v.cargo_nome||'—')+'</div>'
    +'<div>Vaga: '+rhEsc(v.codigo||'—')+'</div>'
    +'<div>CPF: '+rhEsc(rhSelCpfMascarado(c.cpf))+'</div>'
    +'</div>'
    +'<div style="font-size:11px;color:#854F0B;background:#FEF3E2;padding:8px;border-radius:8px;margin-bottom:10px">'
    +'Esta ação aprova o candidato <b>apenas para iniciar o processo de admissão</b>. O colaborador ainda <b>não</b> será criado/ativado.</div>'
    +'<div class="fg"><label>Observação (opcional)</label><textarea class="inp" id="rh-res-obs" rows="2"></textarea></div>'
    +'<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px">'
    +'<button class="btn" type="button" onclick="rhSelResFecharModal()">Cancelar</button>'
    +'<button class="btn btn-pri" type="button" onclick="rhSelResConfirmarAprovar(\''+String(candId).replace(/'/g,'')+'\')">Confirmar aprovação</button></div>'
    +'</div></div>';
}
function rhSelResConfirmarAprovar(candId){
  var c=(_rhSelCand.lista||[]).filter(function(x){return String(x.id)===String(candId);})[0];
  if(!c) return;
  var v=_rhSel.atual||{};
  var obs=((document.getElementById('rh-res-obs')||{}).value||'').trim();
  var agora=new Date().toISOString();
  var snap=rhSelResSnapshot(candId, c);
  var existente=_rhSelResByCand[String(candId)];
  var payload={
    candidatura_id:candId, vaga_id:v.id,
    status:'APROVADO_PARA_ADMISSAO', decisao:'APROVADO_PARA_ADMISSAO',
    observacao:obs||null, motivo_codigo:null, motivo_descricao:null,
    decidido_em:agora, decidido_por:rhSelResUserId(), decidido_por_nome:rhSelResUserNome(),
    snapshot_json:snap, updated_at:agora, updated_by:rhSelResUserNome()
  };
  var p;
  if(existente&&existente.id){
    p=sbUpdate('rh_candidato_resultado_selecao', payload, 'id=eq.'+existente.id).then(function(){
      Object.assign(existente, payload); return existente;
    });
  } else {
    payload.created_by=rhSelResUserNome();
    p=sbInsert('rh_candidato_resultado_selecao', payload).then(function(rows){
      var r=Array.isArray(rows)?rows[0]:rows;
      if(!r||!r.id) throw new Error('Falha ao gravar resultado');
      return r;
    });
  }
  p.then(function(r){
    _rhSelResByCand[String(candId)]=r;
    return sbUpdate('rh_vaga_candidatos',{
      status:'APROVADO_PARA_ADMISSAO', decisao_em:agora, updated_at:agora
    },'id=eq.'+candId);
  }).then(function(){
    c.status='APROVADO_PARA_ADMISSAO'; c.decisao_em=agora;
    try{ auditLog('APROVOU_PARA_ADMISSAO','rh_selecao','Aprovou candidato para admissão',{candidatura_id:candId,vaga_id:v.id}); }catch(e){}
    rhSelResFecharModal();
    progShowToast('Aprovado para admissão. Colaborador NÃO foi criado.','ok');
    rhSelCandDetalhe(candId);
    if(v.id) rhSelCandidatosCarregar(v.id);
  }).catch(function(e){ progShowToast('Falha ao aprovar. Confira SQL 1G.','erro'); console.warn(e); });
}
function rhSelResAbrirNaoSelecionar(candId){
  if(!rhSelResPodeDecidir()) return;
  var c=(_rhSelCand.lista||[]).filter(function(x){return String(x.id)===String(candId);})[0];
  if(!c) return;
  var elig=rhSelResElegivelDecidir(c);
  if(!elig.ok){ progShowToast(elig.motivo||'Não elegível.','erro'); return; }
  var box=document.getElementById('rh-sel-res-modal'); if(!box) return;
  box.classList.remove('hidden');
  box.innerHTML='<div style="position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:9300;display:flex;align-items:center;justify-content:center;padding:1rem" onclick="if(event.target===this)rhSelResFecharModal()">'
    +'<div style="background:#fff;border-radius:12px;padding:1.1rem;max-width:460px;width:100%;max-height:92vh;overflow:auto" onclick="event.stopPropagation()">'
    +'<div style="font-weight:800;margin-bottom:8px">Não selecionar — '+rhEsc(c.nome)+'</div>'
    +'<div style="font-size:11px;color:#666;margin-bottom:8px">Encerra a participação nesta vaga. Não apaga testes/entrevistas/integridade. Não cria contratação.</div>'
    +'<div class="fg"><label>Motivo *</label><select class="inp" id="rh-res-motivo">'
    +'<option value="">Selecione…</option>'
    +rhSelResMotivos().map(function(m){return '<option value="'+m[0]+'">'+rhEsc(m[1])+'</option>';}).join('')
    +'</select></div>'
    +'<div class="fg"><label>Justificativa (obrigatória se OUTRO)</label><textarea class="inp" id="rh-res-just" rows="2"></textarea></div>'
    +'<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px">'
    +'<button class="btn" type="button" onclick="rhSelResFecharModal()">Cancelar</button>'
    +'<button class="btn btn-pri" type="button" onclick="rhSelResConfirmarNaoSelecionar(\''+String(candId).replace(/'/g,'')+'\')">Confirmar</button></div>'
    +'</div></div>';
}
function rhSelResConfirmarNaoSelecionar(candId){
  var c=(_rhSelCand.lista||[]).filter(function(x){return String(x.id)===String(candId);})[0];
  if(!c) return;
  var v=_rhSel.atual||{};
  var motivo=((document.getElementById('rh-res-motivo')||{}).value||'').trim();
  var just=((document.getElementById('rh-res-just')||{}).value||'').trim();
  if(!motivo){ progShowToast('Selecione o motivo.','erro'); return; }
  if(motivo==='OUTRO' && !just){ progShowToast('Justificativa obrigatória para OUTRO.','erro'); return; }
  var lab=(rhSelResMotivos().filter(function(m){return m[0]===motivo;})[0]||[])[1]||motivo;
  var agora=new Date().toISOString();
  var snap=rhSelResSnapshot(candId, c);
  var existente=_rhSelResByCand[String(candId)];
  var payload={
    candidatura_id:candId, vaga_id:v.id,
    status:'NAO_SELECIONADO', decisao:'NAO_SELECIONADO',
    motivo_codigo:motivo, motivo_descricao:lab+(just?' — '+just:''),
    observacao:just||null,
    decidido_em:agora, decidido_por:rhSelResUserId(), decidido_por_nome:rhSelResUserNome(),
    snapshot_json:snap, updated_at:agora, updated_by:rhSelResUserNome()
  };
  var p=existente&&existente.id
    ? sbUpdate('rh_candidato_resultado_selecao', payload, 'id=eq.'+existente.id).then(function(){ Object.assign(existente,payload); return existente; })
    : sbInsert('rh_candidato_resultado_selecao', Object.assign({created_by:rhSelResUserNome()}, payload)).then(function(rows){
        var r=Array.isArray(rows)?rows[0]:rows; if(!r||!r.id) throw new Error('falha'); return r;
      });
  p.then(function(r){
    _rhSelResByCand[String(candId)]=r;
    return sbUpdate('rh_vaga_candidatos',{status:'NAO_SELECIONADO', decisao_em:agora, updated_at:agora},'id=eq.'+candId);
  }).then(function(){
    c.status='NAO_SELECIONADO'; c.decisao_em=agora;
    try{ auditLog('NAO_SELECIONOU_CANDIDATO','rh_selecao','Não selecionou candidato',{candidatura_id:candId,vaga_id:v.id,motivo:motivo}); }catch(e){}
    rhSelResFecharModal();
    progShowToast('Candidato marcado como não selecionado.','ok');
    rhSelCandDetalhe(candId);
    if(v.id) rhSelCandidatosCarregar(v.id);
  }).catch(function(e){ progShowToast('Falha ao registrar.','erro'); console.warn(e); });
}
function rhSelResManterAnalise(candId){
  if(!rhSelResPodeDecidir()) return;
  var c=(_rhSelCand.lista||[]).filter(function(x){return String(x.id)===String(candId);})[0];
  if(!c) return;
  var elig=rhSelResElegivelDecidir(c);
  if(!elig.ok){ progShowToast(elig.motivo||'Não elegível.','erro'); return; }
  var obs=prompt('Observação interna (opcional):','')||'';
  var resp=prompt('Responsável pela revisão (opcional):', rhSelResUserNome())||'';
  var v=_rhSel.atual||{};
  var agora=new Date().toISOString();
  var existente=_rhSelResByCand[String(candId)];
  var payload={
    candidatura_id:candId, vaga_id:v.id,
    status:'EM_ANALISE', decisao:'EM_ANALISE',
    observacao:obs||null, revisao_responsavel:resp||null,
    updated_at:agora, updated_by:rhSelResUserNome()
  };
  var p=existente&&existente.id
    ? sbUpdate('rh_candidato_resultado_selecao', payload, 'id=eq.'+existente.id).then(function(){ Object.assign(existente,payload); return existente; })
    : sbInsert('rh_candidato_resultado_selecao', Object.assign({created_by:rhSelResUserNome(), snapshot_json:rhSelResSnapshot(candId,c)}, payload)).then(function(rows){
        return Array.isArray(rows)?rows[0]:rows;
      });
  p.then(function(r){
    if(r) _rhSelResByCand[String(candId)]=r;
    return sbUpdate('rh_vaga_candidatos',{status:'EM_DECISAO_FINAL', updated_at:agora},'id=eq.'+candId);
  }).then(function(){
    c.status='EM_DECISAO_FINAL';
    try{ auditLog('MANTEVE_CANDIDATO_EM_ANALISE','rh_selecao','Manteve candidato em análise',{candidatura_id:candId}); }catch(e){}
    progShowToast('Mantido em análise. Sem contratação.','ok');
    rhSelCandDetalhe(candId);
    if(v.id) rhSelCandidatosCarregar(v.id);
  }).catch(function(e){ progShowToast('Falha ao gravar.','erro'); console.warn(e); });
}
function rhSelResReabrir(candId){
  if(!rhSelResPodeDecidir()) return;
  var r=_rhSelResByCand[String(candId)];
  if(!r||!r.id) return;
  if(r.status==='ENCAMINHADO_ADMISSAO'||r.processo_contratacao_id){
    if(!confirm('Já existe encaminhamento para Contratação. Reabrir NÃO apaga o processo de contratação. Continuar?')) return;
  }
  var motivo=prompt('Justificativa para reabrir a decisão:','')||'';
  if(!motivo){ progShowToast('Justificativa obrigatória.','erro'); return; }
  var agora=new Date().toISOString();
  sbUpdate('rh_candidato_resultado_selecao',{
    status:'REABERTO', decisao:'EM_ANALISE',
    reaberto_em:agora, reaberto_por:rhSelResUserNome(), reabertura_motivo:motivo,
    updated_at:agora, updated_by:rhSelResUserNome()
  },'id=eq.'+r.id).then(function(){
    return sbUpdate('rh_vaga_candidatos',{status:'EM_DECISAO_FINAL', updated_at:agora},'id=eq.'+candId);
  }).then(function(){
    r.status='REABERTO'; r.decisao='EM_ANALISE'; r.reabertura_motivo=motivo;
    var c=(_rhSelCand.lista||[]).filter(function(x){return String(x.id)===String(candId);})[0];
    if(c) c.status='EM_DECISAO_FINAL';
    try{ auditLog('REABRIU_DECISAO_SELECAO','rh_selecao','Reabriu decisão de seleção',{candidatura_id:candId,resultado_id:r.id}); }catch(e){}
    progShowToast('Decisão reaberta. Snapshot/histórico preservados.','ok');
    rhSelCandDetalhe(candId);
  }).catch(function(e){ progShowToast('Falha ao reabrir.','erro'); console.warn(e); });
}
function rhSelResLookupCpfColab(cpf){
  cpf=String(cpf||'').replace(/\D/g,'');
  if(cpf.length!==11) return Promise.resolve({tipo:'SEM_CPF', colab:null});
  var pColabs=(typeof rhSynCarregarColabs==='function')?rhSynCarregarColabs(false):Promise.resolve([]);
  return pColabs.then(function(colabs){
    var hit=null;
    (colabs||[]).some(function(col){
      var ok=typeof rhSynCenaTemCpf==='function'?rhSynCenaTemCpf(col,cpf):(String(col.cpf||'').replace(/\D/g,'')===cpf||String(col.bro||'').replace(/\D/g,'')===cpf);
      if(ok){ hit=col; return true; }
      return false;
    });
    if(!hit) return {tipo:'NOVO', colab:null};
    if(hit.dispensado || hit.ativo===false) return {tipo:'EX_COLABORADOR', colab:hit};
    return {tipo:'ATIVO', colab:hit};
  });
}
function rhSelResEncaminhar(candId){
  if(!rhSelResPodeDecidir()) return;
  var c=(_rhSelCand.lista||[]).filter(function(x){return String(x.id)===String(candId);})[0];
  if(!c) return;
  var r=_rhSelResByCand[String(candId)];
  if(!r || r.decisao!=='APROVADO_PARA_ADMISSAO'){ progShowToast('Aprove para admissão antes de encaminhar.','erro'); return; }
  if(c.status==='ENCAMINHADO_ADMISSAO' && r.processo_contratacao_id){
    progShowToast('Já encaminhado. Abrindo processo existente.','ok');
    rhSelResAbrirContratacao(r.processo_contratacao_id);
    return;
  }
  var v=_rhSel.atual||{};
  if(!v.cargo_id && !v.cargo_nome){ progShowToast('Vaga sem cargo definido. Corrija a vaga antes.','erro'); return; }
  if(!confirm('Encaminhar para o módulo Contratação / Promoção?\n\nSerá criado (ou reutilizado) um processo de Contratação.\nO colaborador NÃO será criado/ativado nesta etapa.')) return;

  // Idempotência: processo já ligado à candidatura
  var pExist=sbFetch('rh_contratacoes',{filters:['candidatura_id=eq.'+encodeURIComponent(candId)],limit:5}).catch(function(){return [];});
  Promise.all([pExist, rhSelResLookupCpfColab(c.cpf)]).then(function(arr){
    var existentes=(arr[0]||[]).filter(function(x){ return x.status!=='Cancelado'; });
    if(existentes.length){
      var ct=existentes[0];
      return rhSelResVincularProcesso(candId, c, r, ct, true);
    }
    var lookup=arr[1];
    if(lookup.tipo==='ATIVO'){
      progShowToast('CPF já possui vínculo ativo. Não abrir contratação externa automaticamente. Analise no RH (possível promoção/duplicidade).','erro');
      try{ auditLog('BLOQUEOU_ENCAMINHAMENTO_COLAB_ATIVO','rh_selecao','Bloqueou encaminhamento — CPF ativo',{candidatura_id:candId}); }catch(e){}
      return null;
    }
    var agora=new Date().toISOString();
    var cargoNome=v.cargo_nome||'';
    if(!cargoNome && v.cargo_id && typeof rhSelCargoNome==='function') cargoNome=rhSelCargoNome(v.cargo_id);
    var payload={
      status:'Rascunho',
      tipo_processo:'Contratação',
      questionario_versao:1,
      criado_por:rhSelResUserNome(),
      nome_pretendido:c.nome||null,
      cpf_pretendido:c.cpf||null,
      cargo:cargoNome||null,
      cargo_id:v.cargo_id||null,
      funcao:cargoNome||null,
      contrato_id:v.contrato_id||null,
      contrato_nome:v.contrato_nome||null,
      base_id:v.filial_id||v.base_id||null,
      base_nome:v.filial_nome||v.base_nome||null,
      origem:'SELECAO',
      candidatura_id:candId,
      vaga_id:v.id||null,
      resultado_selecao_id:r.id||null
    };
    // Novo: sugere RE; ex-colaborador: não reativa — deixa Vincular no módulo
    if(lookup.tipo==='NOVO' && typeof rhSugerirProximaRe==='function'){
      try{ payload.re_pretendido=rhSugerirProximaRe(); }catch(e){}
    }
    if(lookup.tipo==='EX_COLABORADOR' && lookup.colab){
      // Não seta colaborador_id (não vincula/reativa). Só referencia no fluxo existente.
      payload.re_pretendido=lookup.colab.re||null;
    }
    return sbInsert('rh_contratacoes', payload).then(function(rows){
      var ct=Array.isArray(rows)?rows[0]:rows;
      if(!ct||!ct.id) throw new Error('Falha ao criar processo');
      return rhSelResVincularProcesso(candId, c, r, ct, false);
    });
  }).catch(function(e){
    progShowToast('Falha no encaminhamento. Confira SQL 1G (colunas em rh_contratacoes).','erro');
    console.warn(e);
  });
}
function rhSelResVincularProcesso(candId, c, r, ct, jaExistia){
  var agora=new Date().toISOString();
  var v=_rhSel.atual||{};
  return sbUpdate('rh_candidato_resultado_selecao',{
    status:'ENCAMINHADO_ADMISSAO',
    processo_contratacao_id:ct.id,
    encaminhado_admissao_em:agora,
    encaminhado_admissao_por:rhSelResUserNome(),
    updated_at:agora, updated_by:rhSelResUserNome()
  },'id=eq.'+r.id).then(function(){
    return sbUpdate('rh_vaga_candidatos',{
      status:'ENCAMINHADO_ADMISSAO', encaminhado_admissao_em:agora, updated_at:agora
    },'id=eq.'+candId);
  }).then(function(){
    r.status='ENCAMINHADO_ADMISSAO'; r.processo_contratacao_id=ct.id;
    c.status='ENCAMINHADO_ADMISSAO'; c.encaminhado_admissao_em=agora;
    try{
      auditLog(jaExistia?'VINCULOU_PROCESSO_CONTRATACAO':'ENCAMINHOU_PARA_ADMISSAO','rh_selecao',
        jaExistia?'Vinculou processo de contratação existente':'Encaminhou para admissão',
        {candidatura_id:candId,vaga_id:v.id,processo_contratacao_id:ct.id});
    }catch(e){}
    // NÃO incrementa quantidade_preenchida
    progShowToast(jaExistia?'Processo existente vinculado.':'Encaminhado para Contratação / Promoção.','ok');
    rhSelCandDetalhe(candId);
    if(v.id) rhSelCandidatosCarregar(v.id);
    return ct;
  });
}
function rhSelResAbrirContratacao(procId){
  if(!procId){ progShowToast('Processo não informado.','erro'); return; }
  try{ auditLog('ABRIU_PROCESSO_CONTRATACAO_EXISTENTE','rh_selecao','Abriu processo de contratação',{processo_contratacao_id:procId}); }catch(e){}
  if(typeof showPage==='function') showPage('rh-contratacao');
  else if(typeof showMain==='function'){ showMain('rh'); if(typeof showSub==='function') showSub('rh-contratacao'); }
  setTimeout(function(){
    if(typeof rhAbrirContratacao==='function') rhAbrirContratacao(procId);
    else progShowToast('Abra RH → Contratação / Promoção e localize o processo.','ok');
  }, 400);
}
function rhSelResCopiarMsg(candId){
  var c=(_rhSelCand.lista||[]).filter(function(x){return String(x.id)===String(candId);})[0]||{};
  var v=_rhSel.atual||{};
  var msg='Candidato '+(c.nome||'')+' aprovado para início do processo de admissão para o cargo '+(v.cargo_nome||'')+'.';
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(msg).then(function(){ progShowToast('Mensagem copiada (sem CPF/AC/PT).','ok'); })
      .catch(function(){ prompt('Copie a mensagem:', msg); });
  } else prompt('Copie a mensagem:', msg);
}
function rhSelEntRender(){
  var wrap=document.getElementById('rh-vagas-wrap'); if(!wrap) return;
  if(_rhSel.view==='entrevista_painel'){ rhSelEntRenderPainel(); return; }
  wrap.innerHTML='<div class="card"><div class="ch"><span class="ct">📣 Agenda de Entrevistas</span></div>'
    +'<div style="padding:.4rem 1rem 0;display:flex;gap:8px;flex-wrap:wrap">'
    +'<button type="button" class="btn btn-sm" onclick="_rhSel.view=\'lista\';rhSelRender()">Vagas</button>'
    +'<button type="button" class="btn btn-sm btn-pri" onclick="_rhSel.view=\'entrevistas\';rhSelEntRender()">Entrevistas</button>'
    +'</div>'
    +'<div style="padding:.6rem 1rem;font-size:12px;color:#666">Agenda consolidada RH-SEL-1E. Recomendação humana ≠ contratação.</div>'
    +'<div style="padding:0 1rem 8px;display:flex;flex-wrap:wrap;gap:8px">'
    +'<button class="btn btn-sm" onclick="_rhSelEnt.atalho=\'hoje\';rhSelEntCarregarAgenda()">Hoje</button>'
    +'<button class="btn btn-sm" onclick="_rhSelEnt.atalho=\'proximas\';rhSelEntCarregarAgenda()">Próximas</button>'
    +'<button class="btn btn-sm" onclick="_rhSelEnt.atalho=\'parecer\';rhSelEntCarregarAgenda()">Pendentes de parecer</button>'
    +'<input class="inp" style="width:160px" type="date" id="rh-ent-f-ini" onchange="rhSelEntCarregarAgenda()"/>'
    +'<input class="inp" style="width:160px" type="date" id="rh-ent-f-fim" onchange="rhSelEntCarregarAgenda()"/>'
    +'<select class="inp" style="width:auto" id="rh-ent-f-st" onchange="rhSelEntCarregarAgenda()"><option value="">Status</option>'
    +['AGENDADA','EM_ANDAMENTO','CONCLUIDA','CANCELADA','NAO_COMPARECEU'].map(function(s){return '<option value="'+s+'">'+rhSelEntStatusLabel(s)+'</option>';}).join('')
    +'</select>'
    +'<select class="inp" style="width:auto" id="rh-ent-f-tp" onchange="rhSelEntCarregarAgenda()"><option value="">Tipo</option><option value="RH">RH</option><option value="TECNICA_GESTOR">Técnica/Gestor</option></select>'
    +'<input class="inp" style="width:min(100%,200px)" id="rh-ent-f-q" placeholder="Buscar candidato…" oninput="rhSelEntFiltrarLocal()"/>'
    +'</div>'
    +'<div id="rh-ent-agenda" style="padding:0 1rem 1rem;color:#888">Carregando…</div></div>';
  rhSelEntCarregarAgenda();
}
function rhSelEntCarregarAgenda(){
  var el=document.getElementById('rh-ent-agenda'); if(!el) return;
  el.textContent='Carregando…';
  var filters=[];
  var st=(document.getElementById('rh-ent-f-st')||{}).value;
  var tp=(document.getElementById('rh-ent-f-tp')||{}).value;
  var ini=(document.getElementById('rh-ent-f-ini')||{}).value;
  var fim=(document.getElementById('rh-ent-f-fim')||{}).value;
  var at=_rhSelEnt.atalho||'proximas';
  var hoje=new Date(); hoje.setHours(0,0,0,0);
  var hojeIso=hoje.toISOString();
  if(at==='hoje'){
    var amanha=new Date(hoje); amanha.setDate(amanha.getDate()+1);
    filters.push('agendada_para=gte.'+hojeIso);
    filters.push('agendada_para=lt.'+amanha.toISOString());
  } else if(at==='proximas'){
    filters.push('agendada_para=gte.'+hojeIso);
    filters.push('status=in.(AGENDADA,EM_ANDAMENTO)');
  } else if(at==='parecer'){
    filters.push('status=eq.EM_ANDAMENTO');
  }
  if(st) filters.push('status=eq.'+st);
  if(tp) filters.push('tipo=eq.'+tp);
  if(ini) filters.push('agendada_para=gte.'+new Date(ini+'T00:00:00').toISOString());
  if(fim) filters.push('agendada_para=lte.'+new Date(fim+'T23:59:59').toISOString());
  sbFetch('rh_candidato_entrevistas',{filters:filters,order:'agendada_para.asc',limit:300}).then(function(rows){
    _rhSelEnt.lista=rows||[];
    // enriquecer com candidato/vaga
    var cids={}, vids={};
    _rhSelEnt.lista.forEach(function(e){ cids[e.candidatura_id]=1; vids[e.vaga_id]=1; });
    var cidList=Object.keys(cids), vidList=Object.keys(vids);
    return Promise.all([
      cidList.length?sbFetch('rh_vaga_candidatos',{filters:['id=in.('+cidList.join(',')+')'],limit:300}):Promise.resolve([]),
      vidList.length?sbFetch('rh_vagas',{filters:['id=in.('+vidList.join(',')+')'],limit:200}):Promise.resolve([])
    ]).then(function(arr){
      var cmap={}, vmap={};
      (arr[0]||[]).forEach(function(c){ cmap[c.id]=c; });
      (arr[1]||[]).forEach(function(v){ vmap[v.id]=v; });
      _rhSelEnt._cmap=cmap; _rhSelEnt._vmap=vmap;
      rhSelEntFiltrarLocal();
    });
  }).catch(function(){
    el.innerHTML='<div style="color:#854F0B;background:#FEF3E2;padding:8px;border-radius:8px">Não foi possível carregar a agenda. Aplique <code>sql_rh_selecao_entrevistas_fase_sel1e.sql</code>.</div>';
  });
}
function rhSelEntFiltrarLocal(){
  var el=document.getElementById('rh-ent-agenda'); if(!el) return;
  var q=String((document.getElementById('rh-ent-f-q')||{}).value||'').toLowerCase();
  var cmap=_rhSelEnt._cmap||{}, vmap=_rhSelEnt._vmap||{};
  var rows=(_rhSelEnt.lista||[]).filter(function(e){
    if(!q) return true;
    var c=cmap[e.candidatura_id]||{};
    var v=vmap[e.vaga_id]||{};
    return [c.nome,v.codigo,v.cargo_nome,e.entrevistador_nome_snapshot].join(' ').toLowerCase().indexOf(q)>=0;
  });
  if(!rows.length){
    el.innerHTML='<div style="padding:16px;text-align:center;color:#aaa">Nenhuma entrevista neste filtro.</div>';
    return;
  }
  el.innerHTML='<div style="overflow-x:auto"><table class="tbl"><thead><tr>'
    +'<th>Data/Hora</th><th>Candidato</th><th>Cargo</th><th>Vaga</th><th>Tipo</th><th>Entrevistador</th><th>Modalidade</th><th>Status</th><th></th>'
    +'</tr></thead><tbody>'
    +rows.map(function(e){
      var c=cmap[e.candidatura_id]||{}, v=vmap[e.vaga_id]||{};
      var eid=String(e.id||'').replace(/'/g,'');
      var vid=String(e.vaga_id||'').replace(/'/g,'');
      return '<tr><td style="font-size:12px">'+rhEsc(rhSelFmtDt(e.agendada_para))+'</td>'
        +'<td><b>'+rhEsc(c.nome||'—')+'</b></td>'
        +'<td>'+rhEsc(v.cargo_nome||'—')+'</td><td>'+rhEsc(v.codigo||'—')+'</td>'
        +'<td>'+rhEsc(rhSelEntTipoLabel(e.tipo))+'</td>'
        +'<td>'+rhEsc(e.entrevistador_nome_snapshot||'—')+'</td>'
        +'<td>'+rhEsc(rhSelEntModLabel(e.modalidade))+'</td>'
        +'<td>'+rhEsc(rhSelEntStatusLabel(e.status))+'</td>'
        +'<td><button class="btn btn-sm" onclick="rhSelEntAbrirDaAgenda(\''+vid+'\',\''+String(e.candidatura_id).replace(/'/g,'')+'\',\''+eid+'\')">Abrir</button></td></tr>';
    }).join('')+'</tbody></table></div>';
}
function rhSelEntAbrirDaAgenda(vagaId, candId, entId){
  var v=(_rhSel.lista||[]).filter(function(x){ return String(x.id)===String(vagaId); })[0];
  if(!v){ progShowToast('Vaga não encontrada na lista.','erro'); return; }
  _rhSel.atual=v;
  _rhSel.view='ficha';
  rhSelRender();
  setTimeout(function(){
    rhSelCandidatosCarregar(vagaId);
    setTimeout(function(){
      var eSt=(_rhSelEnt.lista||[]).filter(function(x){return String(x.id)===String(entId);})[0];
      if(eSt && (eSt.status==='EM_ANDAMENTO'||eSt.status==='CONCLUIDA')) rhSelEntAbrirPainel(entId);
      else rhSelCandDetalhe(candId);
    }, 500);
  }, 200);
}

function rhSelConviteAbrirModal(pre){
  if(!rhSelPodeEditar()) return;
  var v=_rhSel.atual||{};
  if(!v.id){ progShowToast('Salve a vaga antes.','erro'); return; }
  if((v.status==='SUSPENSA'?'PAUSADA':v.status)!=='ABERTA'){ progShowToast('Convite só para vaga ABERTA.','erro'); return; }
  pre=pre||{};
  var box=document.getElementById('rh-sel-convite-modal'); if(!box) return;
  var defExp=new Date(Date.now()+7*24*3600*1000);
  var defVal=defExp.getFullYear()+'-'+String(defExp.getMonth()+1).padStart(2,'0')+'-'+String(defExp.getDate()).padStart(2,'0')+'T23:59';
  box.classList.remove('hidden');
  box.innerHTML='<div style="position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:9000;display:flex;align-items:center;justify-content:center;padding:1rem" onclick="if(event.target===this)rhSelConviteFecharModal()">'
    +'<div style="background:#fff;border-radius:12px;padding:1.1rem;max-width:420px;width:100%;max-height:90vh;overflow:auto" onclick="event.stopPropagation()">'
    +'<div style="font-weight:800;margin-bottom:10px">Convidar candidato</div>'
    +'<div class="fg"><label>Nome *</label><input class="inp" id="rh-sel-inv-nome" value="'+rhEsc(pre.nome||'')+'"/></div>'
    +'<div class="fg"><label>Telefone</label><input class="inp" id="rh-sel-inv-tel" value="'+rhEsc(pre.telefone||'')+'" placeholder="(11) 99999-9999"/></div>'
    +'<div class="fg"><label>E-mail</label><input class="inp" id="rh-sel-inv-email" type="email" value="'+rhEsc(pre.email||'')+'"/></div>'
    +'<div class="fg"><label>Validade do convite *</label><input class="inp" id="rh-sel-inv-exp" type="datetime-local" value="'+rhEsc(defVal)+'"/></div>'
    +'<div style="font-size:11px;color:#888;margin:.5rem 0">Informe telefone ou e-mail. CPF não é exigido nesta fase.</div>'
    +'<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px">'
    +'<button class="btn" type="button" onclick="rhSelConviteFecharModal()">Cancelar</button>'
    +'<button class="btn btn-pri" type="button" onclick="rhSelConviteCriar()">Gerar convite</button></div>'
    +'</div></div>';
}
function rhSelConviteFecharModal(){
  var box=document.getElementById('rh-sel-convite-modal');
  if(box){ box.classList.add('hidden'); box.innerHTML=''; }
}
function rhSelConviteCriar(){
  if(!rhSelConviteExigeAuth()) return;
  var v=_rhSel.atual||{};
  var nome=(document.getElementById('rh-sel-inv-nome')||{}).value||'';
  var tel=(document.getElementById('rh-sel-inv-tel')||{}).value||'';
  var email=(document.getElementById('rh-sel-inv-email')||{}).value||'';
  var exp=(document.getElementById('rh-sel-inv-exp')||{}).value||'';
  nome=String(nome).trim();
  if(!nome){ progShowToast('Informe o nome.','erro'); return; }
  if(!String(tel).trim() && !String(email).trim()){ progShowToast('Informe telefone ou e-mail.','erro'); return; }
  if(!exp){ progShowToast('Informe a validade.','erro'); return; }
  var expIso=new Date(exp).toISOString();
  progShowToast('Gerando convite…','ok');
  chamarEdgeFunction('rh-candidato-convite-admin',{
    acao:'CRIAR', vaga_id:v.id, nome:nome, telefone:String(tel).trim(), email:String(email).trim(), expira_em:expIso
  }).then(function(res){
    if(res && res.error==='duplicado'){
      var cid=res.candidatura_id||(res.candidato&&res.candidato.id);
      if(confirm((res.message||'Já existe candidatura com o mesmo telefone/e-mail.')+'\n\nAbrir existente?')){
        rhSelConviteFecharModal();
        // lista já tem o registro — apenas destacar via toast
        progShowToast('Candidatura existente: '+(res.candidato&&res.candidato.nome||cid),'ok');
        rhSelCandidatosCarregar(v.id);
      }
      return;
    }
    if(!res || !res.ok){ progShowToast((res&&res.message)||'Falha ao criar convite.','erro'); return; }
    var cid=String(res.candidatura&&res.candidatura.id||'');
    if(cid && res.token && res.token.fragment){
      _rhSelCandSecretMem[cid]={ fragment:res.token.fragment, public_id:res.token.public_id };
    }
    try{
      auditLog('GEROU_CONVITE_CANDIDATO','rh_selecao','Convite gerado',{
        vaga_id:v.id, candidatura_id:cid, validade:expIso
      });
    }catch(e){}
    rhSelConviteFecharModal();
    rhSelCandidatosCarregar(v.id);
    rhSelConviteMostrarQrModal(res);
  }).catch(function(e){
    var p=e && e.payload;
    if(p && p.error==='duplicado'){
      if(confirm((p.message||'Duplicado.')+'\n\nAbrir existente na lista?')){
        rhSelConviteFecharModal();
        rhSelCandidatosCarregar(v.id);
      }
      return;
    }
    progShowToast((e&&e.message)||'Erro ao gerar convite.','erro');
  });
}
function rhSelConviteShareText(nome, cargo, link, validadeTxt){
  return 'CENA — Processo Seletivo\n\nOlá, '+nome+'.\n\nVocê recebeu um convite para participar do processo seletivo da CENA para a vaga de '+cargo+'.\n\nAcesse pelo link abaixo (sem login no sistema):\n'+link+'\n\nConfirme seus dados, informe o CPF e faça as avaliações no celular.\n\nEste link é pessoal. Não compartilhe com terceiros.\n\nValidade: '+validadeTxt+'.';
}
/** Mensagem de e-mail pré-formatada (candidatura / boas-vindas). */
function rhSelConviteEmailBody(nome, cargo, link, validadeTxt){
  var cargoTxt=cargo||'nossa vaga';
  return 'Olá, '+(nome||'')+',\n\n'
    +'É com prazer que recebemos sua candidatura para nossa vaga de "'+cargoTxt+'". '
    +'Esperamos que seja aprovado(a) e que venhamos a firmar essa parceria. '
    +'Em breve você receberá mensagem por e-mail e WhatsApp sobre o status da sua candidatura.\n\n'
    +'Acesse seu convite (link pessoal):\n'+link+'\n\n'
    +(validadeTxt?'Validade do convite: '+validadeTxt+'.\n\n':'')
    +'Boa sorte!\n\n'
    +'CENA — Recrutamento e Seleção';
}
/** Mensagem WhatsApp com link do portal (ficha/testes nas próximas fases). */
function rhSelConviteWhatsAppText(nome, cargo, link, validadeTxt){
  var cargoTxt=cargo||'nossa vaga';
  return 'Olá, '+(nome||'')+'!\n\n'
    +'É com prazer que recebemos sua candidatura para nossa vaga de "'+cargoTxt+'". '
    +'Esperamos que seja aprovado(a) e que venhamos a firmar essa parceria.\n\n'
    +'Acesse seu convite pelo link abaixo (pessoal — não compartilhe):\n'+link+'\n\n'
    +'Pelo link você acompanha o processo seletivo. Nas próximas etapas serão liberadas a ficha digital e as avaliações neste mesmo acesso.\n\n'
    +(validadeTxt?'Validade: '+validadeTxt+'.\n\n':'')
    +'Em breve você receberá mensagem por e-mail e WhatsApp sobre o status da sua candidatura.\n\n'
    +'Boa sorte!\nCENA';
}
function rhSelConviteTelWa(tel){
  var d=String(tel||'').replace(/\D/g,'');
  if(!d) return '';
  if(d.length<=11 && d.charAt(0)!=='5') d='55'+d;
  return d;
}
function rhSelConviteAbrirWhatsApp(tel, texto){
  var num=rhSelConviteTelWa(tel);
  if(!num){ progShowToast('Informe o telefone do candidato para abrir o WhatsApp.','erro'); return; }
  var url='https://wa.me/'+num+'?text='+encodeURIComponent(texto||'');
  window.open(url,'_blank','noopener,noreferrer');
}
function rhSelConviteAbrirEmail(email, cargo, body){
  var em=String(email||'').trim();
  if(!em){ progShowToast('Informe o e-mail do candidato para abrir o e-mail.','erro'); return; }
  var subj='CENA — Candidatura: '+(cargo||'Processo Seletivo');
  var url='mailto:'+encodeURIComponent(em)
    +'?subject='+encodeURIComponent(subj)
    +'&body='+encodeURIComponent(body||'');
  window.location.href=url;
}
function rhSelConviteMostrarQrModal(res){
  var cand=res.candidatura||{};
  var vg=res.vaga||(_rhSel.atual||{});
  var frag=(res.token&&res.token.fragment)||'';
  var link=rhSelConviteLink(frag);
  var local=rhSelIsLinkLocal();
  var nome=cand.nome||'';
  var cargo=vg.cargo_nome||'';
  var codigo=vg.codigo||'';
  var tel=cand.telefone||'';
  var email=cand.email||'';
  var valTxt=rhSelFmtDt(cand.convite_expira_em);
  var waTxt=rhSelConviteWhatsAppText(nome, cargo||'vaga', link, valTxt);
  var mailBody=rhSelConviteEmailBody(nome, cargo||'vaga', link, valTxt);
  var overlay=document.createElement('div');
  overlay.id='rh-sel-qr-overlay';
  overlay.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9500;display:flex;align-items:flex-start;justify-content:center;padding:1rem;overflow:auto';
  overlay.onclick=function(ev){ if(ev.target===overlay){ rhSelConviteFecharQr(); } };
  overlay.innerHTML='<div style="background:#fff;border-radius:14px;padding:1.2rem;max-width:440px;width:100%;margin:1rem 0" onclick="event.stopPropagation()">'
    +'<div style="font-weight:800;font-size:16px;margin-bottom:8px">Convite gerado</div>'
    +(local?'<div style="background:#FAEEDA;color:#854F0B;padding:8px;border-radius:8px;font-size:12px;margin-bottom:10px;font-weight:600">Link local — somente para homologação. Não envie ao candidato.</div>':'')
    +'<div style="font-size:13px;line-height:1.5;margin-bottom:10px">'
    +'<div><b>Candidato:</b> '+rhEsc(nome)+'</div>'
    +'<div><b>Vaga:</b> '+rhEsc(codigo)+'</div>'
    +'<div><b>Cargo:</b> '+rhEsc(cargo)+'</div>'
    +'<div><b>Telefone:</b> '+rhEsc(tel||'—')+'</div>'
    +'<div><b>E-mail:</b> '+rhEsc(email||'—')+'</div>'
    +'<div><b>Validade:</b> '+rhEsc(valTxt)+'</div></div>'
    +'<div id="rh-sel-qr-box" style="display:flex;justify-content:center;padding:10px;background:#fafafa;border-radius:10px;min-height:200px"></div>'
    +'<div style="font-size:10px;color:#888;word-break:break-all;margin:8px 0">'+rhEsc(link)+'</div>'
    +'<div style="font-size:11px;color:#666;margin:6px 0 4px">Envio assistido (abre WhatsApp / e-mail do RH — sem API automática):</div>'
    +'<div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:6px">'
    +'<button class="btn btn-pri" type="button" id="rh-sel-qr-copiar">Copiar link</button>'
    +'<button class="btn" type="button" id="rh-sel-qr-wa"'+(tel?'':' disabled title="Sem telefone"')+'>WhatsApp</button>'
    +'<button class="btn" type="button" id="rh-sel-qr-email"'+(email?'':' disabled title="Sem e-mail"')+'>E-mail</button>'
    +'<button class="btn" type="button" id="rh-sel-qr-share">Compartilhar</button>'
    +'<button class="btn" type="button" id="rh-sel-qr-print">Imprimir QR</button>'
    +'<button class="btn" type="button" onclick="rhSelConviteFecharQr()">Fechar</button>'
    +'</div></div>';
  document.body.appendChild(overlay);
  var box=document.getElementById('rh-sel-qr-box');
  try{
    if(!box){ /* ignore */ }
    else if(typeof QRCode==='function'){
      box.innerHTML='';
      new QRCode(box, { text:link, width:200, height:200, correctLevel: (QRCode.CorrectLevel && QRCode.CorrectLevel.M!=null) ? QRCode.CorrectLevel.M : 0 });
    } else if(window.CenaQR && typeof CenaQR.toCanvas==='function'){
      box.innerHTML='';
      var cv=document.createElement('canvas');
      CenaQR.toCanvas(cv, link, { width:200 });
      box.appendChild(cv);
    } else {
      box.innerHTML='<div style="color:#A32D2D;font-size:12px">Não foi possível gerar o QR local. Use Copiar link / WhatsApp / E-mail.</div>';
    }
  }catch(err){
    if(box){
      try{
        if(window.CenaQR && CenaQR.toCanvas){
          box.innerHTML='';
          var cv2=document.createElement('canvas');
          CenaQR.toCanvas(cv2, link, { width:200 });
          box.appendChild(cv2);
        } else {
          box.innerHTML='<div style="color:#A32D2D;font-size:12px">Falha ao gerar QR. Use Copiar link.</div>';
        }
      }catch(e2){
        box.innerHTML='<div style="color:#A32D2D;font-size:12px">Falha ao gerar QR. Use Copiar link.</div>';
      }
    }
  }
  var btnC=document.getElementById('rh-sel-qr-copiar');
  if(btnC) btnC.onclick=function(){
    if(navigator.clipboard&&navigator.clipboard.writeText){
      navigator.clipboard.writeText(link).then(function(){ progShowToast('Link copiado.','ok'); }).catch(function(){ prompt('Copie o link:', link); });
    } else prompt('Copie o link:', link);
  };
  var btnWa=document.getElementById('rh-sel-qr-wa');
  if(btnWa) btnWa.onclick=function(){
    if(local){ progShowToast('Link local — não envie ao candidato real.','erro'); return; }
    rhSelConviteAbrirWhatsApp(tel, waTxt);
  };
  var btnEm=document.getElementById('rh-sel-qr-email');
  if(btnEm) btnEm.onclick=function(){
    if(local){ progShowToast('Link local — não envie ao candidato real.','erro'); return; }
    rhSelConviteAbrirEmail(email, cargo||codigo, mailBody);
  };
  var btnS=document.getElementById('rh-sel-qr-share');
  if(btnS) btnS.onclick=function(){
    var txt=rhSelConviteWhatsAppText(nome, cargo||'vaga', link, valTxt);
    if(navigator.share){
      navigator.share({ title:'CENA — Processo Seletivo', text:txt }).catch(function(){});
    } else if(navigator.clipboard&&navigator.clipboard.writeText){
      navigator.clipboard.writeText(txt).then(function(){ progShowToast('Mensagem copiada.','ok'); });
    } else prompt('Copie a mensagem:', txt);
  };
  var btnP=document.getElementById('rh-sel-qr-print');
  if(btnP) btnP.onclick=function(){
    var w=window.open('','_blank','width=480,height=640');
    if(!w){ progShowToast('Pop-up bloqueado.','erro'); return; }
    var qrHtml=box?box.innerHTML:'';
    w.document.write('<html><head><title>QR Convite</title></head><body style="font-family:sans-serif;text-align:center;padding:24px">'
      +'<h2>CENA — Processo Seletivo</h2><p>'+rhEsc(nome)+'<br>'+rhEsc(cargo)+'<br>'+rhEsc(codigo)+'</p>'
      +'<div style="display:inline-block">'+qrHtml+'</div>'
      +'<p style="font-size:11px">Validade: '+rhEsc(valTxt)+'</p></body></html>');
    w.document.close();
    setTimeout(function(){ try{ w.print(); }catch(e){} }, 300);
  };
}
function rhSelConviteFecharQr(){
  var ov=document.getElementById('rh-sel-qr-overlay');
  if(ov) ov.remove();
  // segredo permanece só em _rhSelCandSecretMem até fechar a página
}
function rhSelConviteVerQr(id){
  var mem=_rhSelCandSecretMem[id];
  if(!mem || !mem.fragment){
    progShowToast('Segredo não disponível nesta sessão. Use Reemitir para gerar novo QR.','erro');
    return;
  }
  var c=(_rhSelCand.lista||[]).filter(function(x){ return String(x.id)===String(id); })[0]||{};
  var v=_rhSel.atual||{};
  rhSelConviteMostrarQrModal({
    candidatura: Object.assign({}, c, { id:id }),
    vaga: { codigo:v.codigo, cargo_nome:v.cargo_nome, empresa:v.empresa, local_trabalho:v.local_trabalho },
    token: { fragment:mem.fragment, public_id:mem.public_id }
  });
}
function rhSelConviteReemitir(id){
  if(!rhSelConviteExigeAuth()) return;
  if(!confirm('Reemitir invalida o link/QR anterior e gera um novo acesso. Continuar?')) return;
  var exp=new Date(Date.now()+7*24*3600*1000).toISOString();
  chamarEdgeFunction('rh-candidato-convite-admin',{
    acao:'REEMITIR', candidatura_id:id, expira_em:exp
  }).then(function(res){
    if(!res||!res.ok){ progShowToast((res&&res.message)||'Falha ao reemitir.','erro'); return; }
    var cid=String(res.candidatura&&res.candidatura.id||id);
    if(res.token&&res.token.fragment){
      _rhSelCandSecretMem[cid]={ fragment:res.token.fragment, public_id:res.token.public_id };
    }
    try{ auditLog('REEMITIU_CONVITE_CANDIDATO','rh_selecao','Convite reemitido',{ vaga_id:_rhSel.atual&&_rhSel.atual.id, candidatura_id:cid, validade:exp }); }catch(e){}
    rhSelCandidatosCarregar(_rhSel.atual&&_rhSel.atual.id);
    rhSelConviteMostrarQrModal(res);
  }).catch(function(e){ progShowToast((e&&e.message)||'Erro ao reemitir.','erro'); });
}
function rhSelConviteRevogar(id){
  if(!rhSelConviteExigeAuth()) return;
  if(!confirm('Revogar este convite? O link deixará de funcionar. O histórico permanece.')) return;
  var motivo=prompt('Motivo (opcional):','Revogado pelo RH')||'Revogado pelo RH';
  chamarEdgeFunction('rh-candidato-convite-admin',{
    acao:'REVOGAR', candidatura_id:id, motivo:motivo
  }).then(function(res){
    if(!res||!res.ok){ progShowToast((res&&res.message)||'Falha ao revogar.','erro'); return; }
    delete _rhSelCandSecretMem[id];
    try{ auditLog('REVOGOU_CONVITE_CANDIDATO','rh_selecao','Convite revogado',{ vaga_id:_rhSel.atual&&_rhSel.atual.id, candidatura_id:id }); }catch(e){}
    progShowToast('Convite revogado.','ok');
    rhSelCandidatosCarregar(_rhSel.atual&&_rhSel.atual.id);
  }).catch(function(e){ progShowToast((e&&e.message)||'Erro ao revogar.','erro'); });
}

// =============================================================================
// RH-SEL-1D — Banco de testes (catálogo). Gabarito só via RPC.
// =============================================================================
var _rhTeste = {lista:[], atual:null, view:'lista', aba:'trilha', aplicacao:null, resultado:null, respostas:{}, aval:null, trilhas:[], hist:[], blocoAtual:null};
function rhTesteSqlHint(){ return 'Aplique sql_rh_selecao_testes_fase_sel1d.sql, sql_rh_trilha_testes_eletricista_fase_sel1h.sql e sql_rh_seed_trilha_testes_eletricista_i_ii_iii.sql no SQL Editor.'; }
function rhTestePerfilLabel(p){
  var x=(RH_MATRIZ_TESTES||[]).filter(function(t){ return t.v===p; })[0];
  return x?x.l:p;
}
function rhTesteAba(k){ _rhTeste.aba=k; _rhTeste.view='lista'; _rhTeste.aval=null; rhTesteRender(); }
function rhTesteRender(){
  var wrap=document.getElementById('rh-testes-wrap'); if(!wrap) return;
  if(_rhTeste.view==='aplicar'){ rhTesteRenderAplicar(); return; }
  if(_rhTeste.view==='aval'){ rhTrilhaRenderAval(); return; }
  if(_rhTeste.view==='nova'){ rhTrilhaRenderNova(); return; }
  var abas=[{k:'trilha',l:'Trilha Eletricista'},{k:'catalogo',l:'Catálogo 1D'},{k:'hist',l:'Histórico'}];
  wrap.innerHTML='<div class="card"><div class="ch"><span class="ct">📝 Banco de Testes</span></div>'
    +'<div style="padding:.55rem 1rem 0;display:flex;gap:6px;flex-wrap:wrap">'
    +abas.map(function(a){ return '<button type="button" class="btn btn-sm'+(_rhTeste.aba===a.k?' btn-pri':'')+'" onclick="rhTesteAba(\''+a.k+'\')">'+a.l+'</button>'; }).join('')
    +'</div>'
    +'<div id="rh-teste-lista" style="padding:.7rem 1rem 1rem;color:#888">Carregando…</div></div>';
  if(_rhTeste.aba==='catalogo') rhTesteRenderCatalogo();
  else if(_rhTeste.aba==='hist') rhTrilhaRenderHist();
  else rhTrilhaRenderLista();
}
function rhTesteRenderCatalogo(){
  sbFetch('rh_testes',{filters:['ativo=eq.true'],order:'codigo.asc'}).then(function(rows){
    if(rows===null){
      document.getElementById('rh-teste-lista').innerHTML='<div style="color:#854F0B;background:#FEF3E2;padding:8px;border-radius:8px">'+rhEsc(rhTesteSqlHint())+'</div>';
      return;
    }
    _rhTeste.lista=rows||[];
    var el=document.getElementById('rh-teste-lista'); if(!el) return;
    el.innerHTML='<div style="font-size:12px;color:#666;margin-bottom:8px">Catálogo versionado (RH-SEL-1D). Gabarito não carrega nesta tela. Correção por RPC. Não contrata sozinho.</div>'
      +'<div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Código</th><th>Nome</th><th>Perfil</th><th>Versão</th><th>Peso</th><th>Cargo</th><th></th></tr></thead><tbody>'
      +(_rhTeste.lista.map(function(t){
        var id=String(t.id||'').replace(/'/g,'');
        return '<tr><td>'+rhEsc(t.codigo)+'</td><td>'+rhEsc(t.nome)+'</td><td>'+rhEsc(rhTestePerfilLabel(t.perfil))+'</td>'
          +'<td>'+rhEsc(t.versao||1)+'</td><td>'+rhEsc(t.peso!=null?t.peso+'%':'—')+'</td>'
          +'<td style="font-size:11px">'+rhEsc(t.cargo_id?rhSelCargoNome(t.cargo_id):'—')+'</td>'
          +'<td style="white-space:nowrap"><button class="btn btn-sm" onclick="rhTesteVer(\''+id+'\')">Questões</button> '
          +'<button class="btn btn-sm btn-pri" onclick="rhTesteIniciar(\''+id+'\')">Simular (RH)</button></td></tr>';
      }).join('')||'<tr><td colspan="7" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum teste.</td></tr>')
      +'</tbody></table></div>'
      +'<div id="rh-teste-qs"></div>';
  }).catch(function(){
    var el=document.getElementById('rh-teste-lista');
    if(el) el.innerHTML='<div style="color:#854F0B">'+rhEsc(rhTesteSqlHint())+'</div>';
  });
}
function rhTrilhaResLabel(v){
  return ({
    APROVADO_ELETRICISTA_I:'Aprovado para Eletricista I',
    APROVADO_ELETRICISTA_II:'Aprovado para Eletricista II',
    APROVADO_ELETRICISTA_III:'Aprovado para Eletricista III',
    APROVADO_RESSALVA:'Aprovado com ressalva',
    REPROVADO:'Reprovado',
    RECLASSIFICAR_INFERIOR:'Reclassificar para nível inferior',
    ENCAMINHAR_TREINAMENTO:'Encaminhar para treinamento'
  })[v]||(v||'—');
}
function rhTrilhaRenderLista(){
  var el=document.getElementById('rh-teste-lista'); if(!el) return;
  Promise.all([
    sbFetch('rh_teste_trilhas',{filters:['ativo=eq.true'],order:'codigo.asc'}),
    sbFetch('rh_teste_trilha_blocos',{filters:['ativo=eq.true']})
  ]).then(function(arr){
    if(arr[0]===null){
      el.innerHTML='<div style="color:#854F0B;background:#FEF3E2;padding:8px;border-radius:8px">'+rhEsc(rhTesteSqlHint())+'</div>';
      return;
    }
    _rhTeste.trilhas=arr[0]||[];
    var blocos=arr[1]||[];
    el.innerHTML='<div style="font-size:12px;color:#666;margin-bottom:8px">Trilha de seleção e promoção interna (RH-SEL-1H). Quatro blocos: técnico, <b>segurança eliminatória</b> (&lt;70% não aprova), prático do avaliador e comportamental. Não cria colaborador. ELETRICISTA IIII não entra nesta fase.</div>'
      +'<div style="margin-bottom:8px"><button class="btn btn-pri" onclick="_rhTeste.view=\'nova\';rhTesteRender()">+ Nova avaliação</button></div>'
      +'<div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Trilha</th><th>Cargo</th><th>Nota mín.</th><th>Segurança</th><th>Blocos</th></tr></thead><tbody>'
      +(_rhTeste.trilhas.map(function(t){
        var n=blocos.filter(function(b){ return String(b.trilha_id)===String(t.id); }).length;
        return '<tr><td>'+rhEsc(t.nome)+'</td><td>'+rhEsc(t.cargo_alvo_nome)+'</td><td>'+rhEsc(t.nota_minima)+'%</td><td>'+rhEsc(t.nota_seguranca_minima)+'% eliminatória</td><td>'+n+'/4</td></tr>';
      }).join('')||'<tr><td colspan="5" style="padding:1.2rem;text-align:center;color:#aaa">Nenhuma trilha. Rode o seed 1H.</td></tr>')
      +'</tbody></table></div>';
  }).catch(function(){
    el.innerHTML='<div style="color:#854F0B">'+rhEsc(rhTesteSqlHint())+'</div>';
  });
}
function rhTrilhaRenderNova(){
  var wrap=document.getElementById('rh-testes-wrap'); if(!wrap) return;
  wrap.innerHTML='<div class="card"><div class="ch"><span class="ct">Nova avaliação de trilha</span>'
    +'<button class="btn" onclick="_rhTeste.view=\'lista\';rhTesteRender()">← Voltar</button></div>'
    +'<div style="padding:1rem;max-width:640px">'
    +'<div class="fg"><label>Origem</label><select class="inp" id="tr-origem" onchange="rhTrilhaOrigemUi()">'
    +'<option value="SELECAO">Candidato (recrutamento)</option><option value="PROMOCAO">Colaborador (promoção interna)</option></select></div>'
    +'<div class="fg"><label>Trilha / cargo alvo</label><select class="inp" id="tr-trilha">'
    +(_rhTeste.trilhas||[]).map(function(t){ return '<option value="'+rhEsc(String(t.id))+'">'+rhEsc(t.nome)+' (mín. '+t.nota_minima+'%)</option>'; }).join('')
    +'</select></div>'
    +'<div id="tr-pessoa-box"></div>'
    +'<div style="margin-top:12px"><button class="btn btn-pri" onclick="rhTrilhaCriar()">Criar avaliação</button></div>'
    +'<div style="font-size:11px;color:#888;margin-top:8px">Candidato permanece em rh_vaga_candidatos. Colaborador usa o cadastro existente. Nada é admitido automaticamente.</div>'
    +'</div></div>';
  if(!(_rhTeste.trilhas||[]).length){
    sbFetch('rh_teste_trilhas',{filters:['ativo=eq.true'],order:'codigo.asc'}).then(function(r){
      _rhTeste.trilhas=r||[];
      rhTrilhaRenderNova();
    });
    return;
  }
  rhTrilhaOrigemUi();
}
function rhTrilhaOrigemUi(){
  var orig=((document.getElementById('tr-origem')||{}).value)||'SELECAO';
  var box=document.getElementById('tr-pessoa-box'); if(!box) return;
  if(orig==='PROMOCAO'){
    box.innerHTML='<div class="fg"><label>Buscar colaborador (nome ou RE)</label><input class="inp" id="tr-q" oninput="rhTrilhaBuscaPessoa()" placeholder="Nome ou RE"/></div><div id="tr-hits"></div><input type="hidden" id="tr-pessoa-id"/>';
  } else {
    box.innerHTML='<div class="fg"><label>Buscar candidato da vaga (nome)</label><input class="inp" id="tr-q" oninput="rhTrilhaBuscaPessoa()" placeholder="Nome do candidato"/></div><div id="tr-hits"></div><input type="hidden" id="tr-pessoa-id"/><input type="hidden" id="tr-vaga-id"/>';
  }
}
function rhTrilhaBuscaPessoa(){
  var orig=((document.getElementById('tr-origem')||{}).value)||'SELECAO';
  var q=((document.getElementById('tr-q')||{}).value||'').trim().toLowerCase();
  var hits=document.getElementById('tr-hits'); if(!hits) return;
  if(q.length<2){ hits.innerHTML=''; return; }
  if(orig==='PROMOCAO'){
    var list=(typeof colaboradores!=='undefined'?colaboradores:[]).filter(function(c){
      if(c.ativo===false) return false;
      return String(c.nome||'').toLowerCase().indexOf(q)>=0 || String(c.re||c.matricula||'').toLowerCase().indexOf(q)>=0;
    }).slice(0,12);
    hits.innerHTML=list.map(function(c){
      var id=String(c.id||'').replace(/'/g,'');
      return '<button type="button" class="btn btn-sm" style="display:block;margin:4px 0" onclick="rhTrilhaPick(\''+id+'\',\''+rhEsc(c.nome||'')+'\',null)">'+rhEsc((c.re||'')+' — '+(c.nome||''))+' · '+rhEsc(c.cargo||'')+'</button>';
    }).join('')||'<div style="font-size:11px;color:#888">Nenhum colaborador local. Carregue o cadastro ou busque outro termo.</div>';
  } else {
    sbFetch('rh_vaga_candidatos',{filters:['ativo=eq.true','nome=ilike.*'+q+'*'],limit:12}).then(function(rows){
      hits.innerHTML=(rows||[]).map(function(c){
        var id=String(c.id||'').replace(/'/g,'');
        var vid=String(c.vaga_id||'').replace(/'/g,'');
        return '<button type="button" class="btn btn-sm" style="display:block;margin:4px 0" onclick="rhTrilhaPick(\''+id+'\',\''+rhEsc(c.nome||'')+'\',\''+vid+'\')">'+rhEsc(c.nome)+' · '+rhEsc(c.status||'')+'</button>';
      }).join('')||'<div style="font-size:11px;color:#888">Nenhum candidato encontrado.</div>';
    });
  }
}
function rhTrilhaPick(id, nome, vagaId){
  var hid=document.getElementById('tr-pessoa-id'); if(hid) hid.value=id;
  var v=document.getElementById('tr-vaga-id'); if(v) v.value=vagaId||'';
  var q=document.getElementById('tr-q'); if(q) q.value=nome;
  var hits=document.getElementById('tr-hits'); if(hits) hits.innerHTML='<div style="font-size:12px;color:#3B6D11">Selecionado: '+rhEsc(nome)+'</div>';
}
function rhTrilhaCriar(){
  var orig=((document.getElementById('tr-origem')||{}).value)||'SELECAO';
  var trilhaId=((document.getElementById('tr-trilha')||{}).value||'').trim();
  var pessoa=((document.getElementById('tr-pessoa-id')||{}).value||'').trim();
  var vaga=((document.getElementById('tr-vaga-id')||{}).value||'').trim()||null;
  if(!trilhaId||!pessoa){ progShowToast('Selecione a trilha e a pessoa.','erro'); return; }
  var tr=(_rhTeste.trilhas||[]).filter(function(t){ return String(t.id)===trilhaId; })[0];
  if(!tr){ progShowToast('Trilha não encontrada.','erro'); return; }
  var user=(typeof usuarioLogado!=='undefined'&&usuarioLogado)?(usuarioLogado.nome||usuarioLogado.email||''):'';
  var payload={trilha_id:trilhaId, origem:orig, cargo_alvo_id:tr.cargo_id, status:'RASCUNHO', created_by:user};
  if(orig==='PROMOCAO') payload.colaborador_id=pessoa;
  else { payload.candidato_id=pessoa; if(vaga) payload.vaga_id=vaga; }
  sbInsert('rh_teste_avaliacoes', payload).then(function(r){
    if(!r||!r[0]){ progShowToast('Não gravou a avaliação. Rode o SQL 1H.','erro'); return; }
    _rhTeste.aval=r[0];
    _rhTeste.view='aval';
    rhTesteRender();
  });
}
function rhTrilhaAbrir(id){
  sbFetch('rh_teste_avaliacoes',{filters:['id=eq.'+id]}).then(function(r){
    if(!r||!r[0]){ progShowToast('Avaliação não encontrada.','erro'); return; }
    _rhTeste.aval=r[0];
    _rhTeste.view='aval';
    rhTesteRender();
  });
}
function rhTrilhaRenderAval(){
  var wrap=document.getElementById('rh-testes-wrap'); if(!wrap) return;
  var av=_rhTeste.aval; if(!av){ _rhTeste.view='lista'; rhTesteRender(); return; }
  var tr=(_rhTeste.trilhas||[]).filter(function(t){ return String(t.id)===String(av.trilha_id); })[0];
  function bloco(titulo, pct, btn, extra){
    return '<div style="border:.5px solid #e8e8e4;border-radius:8px;padding:.65rem;margin-bottom:.5rem"><div style="font-weight:700;font-size:12px;color:#185FA5">'+titulo+'</div>'
      +'<div style="font-size:13px;margin:4px 0">'+(pct!=null?('<b>'+rhEsc(pct)+'%</b>'):'<span style="color:#aaa">Pendente</span>')+'</div>'
      +(extra||'')+btn+'</div>';
  }
  var dis=av.status==='CONCLUIDA'||av.status==='CANCELADA';
  wrap.innerHTML='<div class="card"><div class="ch"><span class="ct">Avaliação · '+(tr?rhEsc(tr.nome):'Trilha')+'</span>'
    +'<button class="btn" onclick="_rhTeste.view=\'lista\';_rhTeste.aba=\'hist\';rhTesteRender()">← Histórico</button></div>'
    +'<div style="padding:1rem">'
    +'<div style="font-size:12px;color:#666;margin-bottom:8px">Origem <b>'+rhEsc(av.origem)+'</b> · status '+rhEsc(av.status)
    +(av.colaborador_id?' · colaborador':' · candidato')
    +'. Segurança &lt; '+(tr?tr.nota_seguranca_minima:70)+'% é eliminatória. Não cria colaborador.</div>'
    +bloco('1. Técnico teórico', av.pct_tecnico, dis?'':'<button class="btn btn-sm btn-pri" onclick="rhTrilhaIniciarBloco(\'TECNICO\')">Aplicar teórico</button>')
    +bloco('2. Segurança / NR (eliminatório)', av.pct_seguranca, dis?'':'<button class="btn btn-sm btn-pri" onclick="rhTrilhaIniciarBloco(\'SEGURANCA\')">Aplicar segurança</button>',
      (av.pct_seguranca!=null && tr && av.pct_seguranca<tr.nota_seguranca_minima)?'<div style="color:#A32D2D;font-size:12px">Abaixo do corte. Não pode ser aprovado neste nível.</div>':'')
    +bloco('3. Prático operacional (avaliador)', av.pct_pratico, '', rhTrilhaPraticoHtml(tr, av, dis))
    +bloco('4. Comportamental / entrevista técnica', av.pct_comportamental, dis?'':'<button class="btn btn-sm btn-pri" onclick="rhTrilhaIniciarBloco(\'COMPORTAMENTAL\')">Aplicar comportamental</button>')
    +'<div style="background:#F4F8EE;border:1px solid #C8D9B0;border-radius:8px;padding:10px;margin:10px 0">'
    +'<div>Geral: <b>'+(av.pct_geral!=null?rhEsc(av.pct_geral)+'%':'—')+'</b> · mínimo da trilha '+(tr?tr.nota_minima:'—')+'%</div>'
    +'<div>Sugerido: <b>'+rhEsc(rhTrilhaResLabel(av.resultado_sugerido))+'</b></div>'
    +(av.resultado?'<div>Confirmado: <b>'+rhEsc(rhTrilhaResLabel(av.resultado))+'</b></div>':'')
    +'</div>'
    +'<div class="fg"><label>Observação do avaliador</label><textarea class="inp" id="tr-obs" rows="3">'+(av.observacao_avaliador||'')+'</textarea></div>'
    +(dis?'':'<div class="fg"><label>Resultado (decisão humana)</label><select class="inp" id="tr-res">'
      +['','APROVADO_ELETRICISTA_I','APROVADO_ELETRICISTA_II','APROVADO_ELETRICISTA_III','APROVADO_RESSALVA','REPROVADO','RECLASSIFICAR_INFERIOR','ENCAMINHAR_TREINAMENTO'].map(function(v){
        return '<option value="'+v+'"'+(av.resultado===v||(!av.resultado&&av.resultado_sugerido===v)?' selected':'')+'>'+(v?rhTrilhaResLabel(v):'— usar sugerido —')+'</option>';
      }).join('')+'</select></div>'
      +'<div class="fg" id="tr-reclass-wrap"><label>Se reclassificar, cargo inferior</label><select class="inp" id="tr-reclass">'
      +'<option value="">—</option>'
      +(_rhTeste.trilhas||[]).map(function(t){ return '<option value="'+rhEsc(String(t.cargo_id))+'"'+(String(av.cargo_reclassificado_id||'')===String(t.cargo_id)?' selected':'')+'>'+rhEsc(t.cargo_alvo_nome)+'</option>'; }).join('')
      +'</select></div>'
      +'<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">'
      +'<button class="btn" onclick="rhTrilhaRecalc()">Recalcular</button>'
      +'<button class="btn btn-pri" onclick="rhTrilhaConfirmar()">Confirmar resultado</button>'
      +'</div>')
    +(av.status==='CONCLUIDA'?'<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:10px">'
      +(av.origem==='SELECAO'?'<button class="btn" onclick="rhTrilhaEncaminhar(\'contratacao\')">Encaminhar para Contratação</button>':'')
      +(av.origem==='PROMOCAO'?'<button class="btn" onclick="rhTrilhaEncaminhar(\'promocao\')">Encaminhar para Promoção</button>':'')
      +'</div>':'')
    +'</div></div>';
}
function rhTrilhaPraticoHtml(tr, av, dis){
  var rub=(tr&&tr.pratico_rubrica)||[];
  if(typeof rub==='string'){ try{ rub=JSON.parse(rub); }catch(e){ rub=[]; } }
  var itens=(av.pratico_json&&av.pratico_json.itens)||rub.map(function(x){ return {codigo:x.codigo,label:x.label,peso:x.peso,nota:''}; });
  return '<div style="font-size:11px;color:#888;margin:4px 0">Nota 0–100 por item. O avaliador registra a prática (não é prova do portal).</div>'
    +itens.map(function(it,i){
      return '<div class="fg"><label>'+rhEsc(it.label||it.codigo)+' (peso '+rhEsc(it.peso)+')</label>'
        +'<input class="inp tr-pratico-nota" data-i="'+i+'" data-cod="'+rhEsc(it.codigo)+'" data-label="'+rhEsc(it.label||'')+'" data-peso="'+rhEsc(it.peso)+'" type="number" min="0" max="100" '+(dis?'disabled':'')+' value="'+(it.nota!=null&&it.nota!==''?it.nota:'')+'"/></div>';
    }).join('')
    +'<div class="fg"><label>Anexo / evidência prática (nome do arquivo)</label><input class="inp" id="tr-anexo" '+(dis?'disabled':'')+' value="'+rhEsc(av.anexo_pratico_nome||'')+'" placeholder="Ex.: avaliacao_pratica.pdf"/>'
    +(!dis?'<input type="file" id="tr-anexo-file" style="margin-top:4px" onchange="(function(el){ var a=document.getElementById(\'tr-anexo\'); if(a&&el.files&&el.files[0]) a.value=el.files[0].name; })(this)"/>':'')
    +'</div>'
    +(dis?'':'<button class="btn btn-sm" onclick="rhTrilhaSalvarPratico()">Salvar prático</button>');
}
function rhTrilhaSalvarPratico(){
  var av=_rhTeste.aval; if(!av) return;
  var itens=[];
  document.querySelectorAll('.tr-pratico-nota').forEach(function(el){
    var n=el.value===''?null:Number(el.value);
    itens.push({codigo:el.getAttribute('data-cod'), label:el.getAttribute('data-label'), peso:Number(el.getAttribute('data-peso')||0), nota:n});
  });
  var anexo=((document.getElementById('tr-anexo')||{}).value||'').trim()||null;
  sbUpdate('rh_teste_avaliacoes',{pratico_json:{itens:itens}, anexo_pratico_nome:anexo, updated_at:new Date().toISOString()},'id=eq.'+av.id).then(function(ok){
    if(ok===false){ progShowToast('Não salvou o prático.','erro'); return; }
    av.pratico_json={itens:itens}; av.anexo_pratico_nome=anexo;
    rhTrilhaRecalc();
  });
}
function rhTrilhaIniciarBloco(bloco){
  var av=_rhTeste.aval; if(!av) return;
  sbFetch('rh_teste_trilha_blocos',{filters:['trilha_id=eq.'+av.trilha_id,'bloco=eq.'+bloco,'ativo=eq.true']}).then(function(rows){
    var b=(rows||[])[0];
    if(!b||!b.teste_id){ progShowToast('Bloco sem teste teórico. Use o prático no formulário.','erro'); return; }
    _rhTeste.blocoAtual=bloco;
    rhTesteIniciar(b.teste_id, true);
  });
}
function rhTrilhaRecalc(){
  var av=_rhTeste.aval; if(!av) return;
  sbRpc('rh_sel_trilha_recalcular',{p_avaliacao_id:av.id}).then(function(r){
    if(!r){ progShowToast('Falha ao recalcular. Aplique o SQL 1H.','erro'); return; }
    Object.assign(av, {
      pct_tecnico:r.pct_tecnico, pct_seguranca:r.pct_seguranca, pct_pratico:r.pct_pratico,
      pct_comportamental:r.pct_comportamental, pct_geral:r.pct_geral,
      resultado_sugerido:r.resultado_sugerido
    });
    if(r.seguranca_eliminatoria) progShowToast('Segurança abaixo do corte: aprovação do nível bloqueada.');
    sbFetch('rh_teste_avaliacoes',{filters:['id=eq.'+av.id]}).then(function(rows){
      if(rows&&rows[0]) _rhTeste.aval=rows[0];
      rhTrilhaRenderAval();
    });
  });
}
function rhTrilhaConfirmar(){
  var av=_rhTeste.aval; if(!av) return;
  var res=((document.getElementById('tr-res')||{}).value||av.resultado_sugerido||'').trim();
  var obs=((document.getElementById('tr-obs')||{}).value||'').trim()||null;
  var rec=((document.getElementById('tr-reclass')||{}).value||'').trim()||null;
  if(!res){ progShowToast('Informe o resultado. Recalcule se ainda não houver sugestão.','erro'); return; }
  if(av.pct_seguranca!=null){
    var tr=(_rhTeste.trilhas||[]).filter(function(t){ return String(t.id)===String(av.trilha_id); })[0];
    var corte=tr?Number(tr.nota_seguranca_minima||70):70;
    if(av.pct_seguranca<corte && String(res).indexOf('APROVADO_ELETRICISTA')===0){
      progShowToast('Segurança eliminatória: não é possível aprovar o nível alvo. Use reprovação, ressalva, reclassificação ou treinamento.','erro');
      return;
    }
  }
  if(res==='RECLASSIFICAR_INFERIOR' && !rec){ progShowToast('Escolha o cargo inferior.','erro'); return; }
  sbUpdate('rh_teste_avaliacoes',{
    resultado:res, observacao_avaliador:obs, cargo_reclassificado_id:rec,
    status:'CONCLUIDA', updated_at:new Date().toISOString()
  },'id=eq.'+av.id).then(function(ok){
    if(ok===false){ progShowToast('Não confirmou.','erro'); return; }
    av.resultado=res; av.observacao_avaliador=obs; av.cargo_reclassificado_id=rec; av.status='CONCLUIDA';
    progShowToast('Resultado registrado no histórico. Contratação/promoção continua humana.');
    rhTrilhaRenderAval();
  });
}
function rhTrilhaEncaminhar(tipo){
  var av=_rhTeste.aval;
  if(tipo==='contratacao'){
    if(typeof showSub==='function') showSub('rh-contratacao');
    progShowToast('Abra o processo em Contratação. A trilha não cria colaborador nem admite.');
    return;
  }
  if(tipo==='promocao'){
    if(av&&av.colaborador_id&&typeof rhIrPara==='function') rhIrPara('avaliacao', av.colaborador_id);
    else if(typeof showSub==='function') showSub('rh-contratacao');
    progShowToast('Encaminhado ao fluxo existente de promoção. Sem alteração automática de cargo.');
  }
}
function rhTrilhaRenderHist(){
  var el=document.getElementById('rh-teste-lista'); if(!el) return;
  sbFetch('rh_teste_avaliacoes',{order:'created_at.desc',limit:80}).then(function(rows){
    if(rows===null){
      el.innerHTML='<div style="color:#854F0B;background:#FEF3E2;padding:8px;border-radius:8px">'+rhEsc(rhTesteSqlHint())+'</div>';
      return;
    }
    _rhTeste.hist=rows||[];
    el.innerHTML='<div style="font-size:12px;color:#666;margin-bottom:8px">Histórico de avaliações da trilha (candidato ou colaborador). Resultado por pessoa nesta lista.</div>'
      +'<div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Data</th><th>Origem</th><th>Pessoa</th><th>Status</th><th>Geral</th><th>Segurança</th><th>Resultado</th><th></th></tr></thead><tbody>'
      +(_rhTeste.hist.map(function(a){
        var id=String(a.id||'').replace(/'/g,'');
        var pes=a.colaborador_id?'Colab. '+String(a.colaborador_id).slice(0,8):('Cand. '+String(a.candidato_id||'').slice(0,8));
        return '<tr><td>'+rhEsc(String(a.created_at||'').slice(0,16).replace('T',' '))+'</td><td>'+rhEsc(a.origem)+'</td><td style="font-size:11px">'+rhEsc(pes)+'</td>'
          +'<td>'+rhEsc(a.status)+'</td><td>'+(a.pct_geral!=null?rhEsc(a.pct_geral)+'%':'—')+'</td>'
          +'<td>'+(a.pct_seguranca!=null?rhEsc(a.pct_seguranca)+'%':'—')+'</td>'
          +'<td>'+rhEsc(rhTrilhaResLabel(a.resultado||a.resultado_sugerido))+'</td>'
          +'<td><button class="btn btn-sm" onclick="rhTrilhaAbrir(\''+id+'\')">Abrir</button></td></tr>';
      }).join('')||'<tr><td colspan="8" style="padding:1.2rem;text-align:center;color:#aaa">Nenhuma avaliação ainda.</td></tr>')
      +'</tbody></table></div>';
  });
}
function rhTesteVer(id){
  var box=document.getElementById('rh-teste-qs'); if(!box) return;
  box.innerHTML='<div style="padding:8px 0;color:#888">Carregando questões (sem gabarito)…</div>';
  Promise.all([
    sbFetch('rh_teste_questoes',{filters:['teste_id=eq.'+id,'ativo=eq.true'],order:'ordem.asc'}),
    sbFetch('rh_teste_alternativas',{filters:['ativo=eq.true'],limit:400})
  ]).then(function(arr){
    var qs=arr[0]||[];
    var alts=arr[1]||[];
    box.innerHTML='<div style="font-weight:700;margin:10px 0 6px">Questões (alternativas sem marcar gabarito)</div>'
      +qs.map(function(q){
        var op=alts.filter(function(a){ return String(a.questao_id)===String(q.id); }).sort(function(a,b){ return (a.ordem||0)-(b.ordem||0); });
        return '<div style="border:.5px solid #eee;border-radius:8px;padding:8px;margin-bottom:8px"><div>'+q.ordem+'. '+rhEsc(q.enunciado)+'</div>'
          +(q.dimensao?'<div style="font-size:10px;color:#888">Dimensão (apoio à entrevista): '+rhEsc(q.dimensao)+'</div>':'')
          +'<ul style="margin:6px 0 0 18px;font-size:12px">'+op.map(function(a){ return '<li>'+rhEsc(a.texto)+'</li>'; }).join('')+'</ul></div>';
      }).join('')
      +'<div style="font-size:11px;color:#888">A letra A/B/C/D na aplicação é só apresentação. Correção usa o ID da alternativa.</div>';
  });
}
function rhTesteIniciar(id, fromTrilha){
  if(typeof sbRpc!=='function'){ progShowToast('RPC indisponível.','erro'); return; }
  var av=_rhTeste.aval;
  var params={p_teste_id:id, p_vaga_id:null, p_candidato_id:null, p_origem:fromTrilha?'TRILHA_RH':'HOMOLOG_RH'};
  if(fromTrilha&&av){
    params.p_vaga_id=av.vaga_id||null;
    params.p_candidato_id=av.candidato_id||null;
    params.p_colaborador_id=av.colaborador_id||null;
    params.p_avaliacao_id=av.id;
  }
  sbRpc('rh_sel_teste_iniciar', params).then(function(p){
    if(!p || p.tentativa_id==null && !(p.questoes)){
      progShowToast('Não foi possível iniciar. Aplique o SQL SEL-1D/1H e rode o seed.','erro');
      return;
    }
    _rhTeste.aplicacao=p;
    _rhTeste.respostas={};
    _rhTeste.resultado=null;
    _rhTeste.view='aplicar';
    rhTesteRender();
  });
}
function rhTesteMarcar(qid, aid){ _rhTeste.respostas[qid]=aid; }
function rhTesteEnviar(){
  var p=_rhTeste.aplicacao; if(!p||!p.tentativa_id) return;
  var resp=[];
  (p.questoes||[]).forEach(function(q){
    if(_rhTeste.respostas[q.id]) resp.push({questao_id:q.id, alternativa_id:_rhTeste.respostas[q.id]});
  });
  if(resp.length!==(p.questoes||[]).length){ progShowToast('Responda todas as questões.','erro'); return; }
  sbRpc('rh_sel_teste_corrigir',{p_tentativa_id:p.tentativa_id, p_respostas:resp}).then(function(r){
    if(!r){ progShowToast('Falha na correção (RPC).','erro'); return; }
    _rhTeste.resultado=r;
    if(_rhTeste.aval&&_rhTeste.blocoAtual){
      sbRpc('rh_sel_trilha_recalcular',{p_avaliacao_id:_rhTeste.aval.id}).then(function(){
        sbFetch('rh_teste_avaliacoes',{filters:['id=eq.'+_rhTeste.aval.id]}).then(function(rows){
          if(rows&&rows[0]) _rhTeste.aval=rows[0];
        });
      });
    }
    rhTesteRender();
  });
}
function rhTesteRenderAplicar(){
  var wrap=document.getElementById('rh-testes-wrap'); if(!wrap) return;
  var p=_rhTeste.aplicacao||{};
  var r=_rhTeste.resultado;
  var qs=p.questoes||[];
  wrap.innerHTML='<div class="card"><div class="ch"><span class="ct">'+rhEsc(p.nome||'Teste')+' · v'+rhEsc(p.versao||1)+'</span>'
    +'<button class="btn" onclick="'+( _rhTeste.aval ? '_rhTeste.view=\'aval\';rhTrilhaRecalc()' : '_rhTeste.view=\'lista\';rhTesteRender()' )+'">← Voltar</button></div>'
    +'<div style="padding:1rem">'
    +'<div style="font-size:12px;color:#666;margin-bottom:10px">'+( _rhTeste.aval?'Bloco da trilha. ':'Simulação RH (não é portal). ')+'Alternativas embaralhadas. Gabarito não vem neste JSON.</div>'
    +(r?('<div style="background:#F4F8EE;border:1px solid #C8D9B0;border-radius:8px;padding:10px;margin-bottom:12px">'
      +'<div style="font-weight:700">Resultado para o RH</div>'
      +'<div>'+rhEsc(r.acertos)+'/'+rhEsc(r.total)+' — '+rhEsc(r.percentual)+'%</div>'
      +(r.parecer?'<div>Situacional: <b>'+rhEsc(r.parecer)+'</b> (não é diagnóstico psicológico)</div>':'')
      +(r.dimensoes?('<div style="font-size:12px;margin-top:6px">'+Object.keys(r.dimensoes).map(function(k){
        return rhEsc(k)+': <b>'+rhEsc(r.dimensoes[k])+'</b>';
      }).join('<br>')+'</div>'):'')
      +'<div style="font-size:11px;color:#3B6D11;margin-top:6px">'+rhEsc(r.mensagem||'Não aprova nem reprova contratação.')+'</div></div>')
      : qs.map(function(q,i){
        var letras=['A','B','C','D','E'];
        return '<div style="margin-bottom:14px"><div style="font-weight:600">'+(i+1)+'. '+rhEsc(q.enunciado)+'</div>'
          +(q.alternativas||[]).map(function(a,j){
            var sel=_rhTeste.respostas[q.id]===a.id;
            return '<label style="display:block;font-size:13px;margin:4px 0;padding:6px 8px;border:.5px solid '+(sel?'#1F4E79':'#eee')+';border-radius:6px">'
              +'<input type="radio" name="tq'+q.id+'" '+(sel?'checked':'')+' onchange="rhTesteMarcar(\''+q.id+'\',\''+a.id+'\')"> '
              +'<b>'+letras[j]+')</b> '+rhEsc(a.texto)+'</label>';
          }).join('')+'</div>';
      }).join('')
    )
    +(!r?'<button class="btn btn-pri" onclick="rhTesteEnviar()">Enviar para correção protegida</button>':'')
    +'</div></div>';
}

function rhIrPara(acao,colId){
  if(acao==='rh-docs'&&colId){ _rhColabAtual=colId; _rhAbaDossie='documentos'; showSub('rh-dossie'); return; }
  if(acao==='rh-mob'&&colId){ _rhColabAtual=colId; _rhAbaDossie='mobilizacao'; showSub('rh-dossie'); return; }
  if(acao==='regras'){ showSub('rh-regras'); return; }
  if(acao==='prontidao'){ showSub('rh-prontidao'); return; }
  if(acao==='conformidade'){ showSub('rh-conformidade'); return; }
  if(acao==='cadastros'){ showMain('cadastros'); return; }
  if(acao==='cargos'){ if(typeof rhAbrirCadastroCargos==='function') rhAbrirCadastroCargos(); return; }
  if(acao==='avaliacao'){ showMain('gestao-pessoas'); setTimeout(function(){ showSub('av-colaborador'); if(colId&&typeof avColSelecionar==='function') avColSelecionar(colId); },120); return; }
  if(acao==='ponto'){ showMain('operacional'); setTimeout(function(){ showSub('gestao-ponto'); },120); return; }
  if(acao==='evolucao'){ showMain('sesmt'); setTimeout(function(){ showSub('sesmt-evolucao'); },120); return; }
  if(acao==='treinamentos'){ showMain('sesmt'); setTimeout(function(){ showSub('sesmt-treinamentos'); },120); return; }
  if(acao==='nr6'){ showMain('sesmt'); setTimeout(function(){ showSub('sesmt-nr6'); if(colId&&typeof verNR6==='function') verNR6(colId); },120); return; }
  if(acao==='frotas'){ showMain('frotas'); return; }
  if(acao==='desmobilizacao'){ showMain('almoxarifado'); setTimeout(function(){ showSub('alm-desmobilizacao'); if(colId&&typeof desmobSelecionarColaborador==='function') setTimeout(function(){ desmobSelecionarColaborador(colId); },180); },120); }
}
function rhClassificarPontoLinha(p, prog){
  var td=(p.tipo_dia||'').toLowerCase();
  var st=(p.status||'').toLowerCase();
  if(pontoEhAbonoCurso(p)) return 'Abono Curso';
  if(p.ausencia_motivada || (p.ausencia_tipo||'').toLowerCase().indexOf('atestado')>=0) return 'Atestado';
  if(td==='falta' || st==='falta' || st==='faltou') return 'Falta';
  if(td==='ferias' || st==='ferias') return 'Férias';
  if(td==='afastado' || st==='afastado' || p.suspensao) return 'Afastado';
  return '';
}
function rhCarregarPontoColab(c){
  var el=document.getElementById('rh-ponto-body'); if(!el||!c) return;
  var fim=rhHoje();
  var iniD=new Date(fim+'T12:00:00'); iniD.setDate(iniD.getDate()-90);
  var ini=iniD.toISOString().slice(0,10);
  function pintar(data){
    var body=document.getElementById('rh-ponto-body'); if(!body) return;
    var linhas=(data.linhas||[]).slice(0,20).map(function(l){
      return '<tr><td>'+rhFmtD(l.data)+'</td><td>'+rhEsc(l.tipo)+'</td></tr>';
    }).join('');
    body.innerHTML='<div style="font-size:12px;color:#888;margin-bottom:10px">Últimos 90 dias · '+rhFmtD(ini)+' a '+rhFmtD(fim)+'. Contagem apenas — sem CID, diagnóstico ou motivo médico.</div>'
      +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;margin-bottom:12px">'
      +rhCard('Faltas',data.faltas,data.faltas?'#A32D2D':'#3B6D11')
      +rhCard('Atestados (qtd.)',data.atest,data.atest?'#854F0B':'#3B6D11')
      +rhCard('Abono Curso',data.abono||0,(data.abono)?'#533AB7':'#555')
      +rhCard('Afastados',data.afast,'#555')
      +rhCard('Férias',data.ferias,'#555')+'</div>'
      +'<table class="tbl" style="font-size:12px"><thead><tr><th>Data</th><th>Tipo</th></tr></thead><tbody>'
      +(linhas||'<tr><td colspan="2" style="padding:1rem;text-align:center;color:#aaa">Sem faltas/atestados no período (ou ponto ainda não sincronizado).</td></tr>')
      +'</tbody></table>';
  }
  var cacheKey=String(c.id)+'|'+ini+'|'+fim;
  if(_rhPontoCache[cacheKey]){ pintar(_rhPontoCache[cacheKey]); return; }
  if(DEMO){ var demo={faltas:0,atest:0,afast:0,ferias:0,abono:0,linhas:[]}; _rhPontoCache[cacheKey]=demo; pintar(demo); return; }
  var re=String(c.re||'').trim();
  var reNorm=typeof pontoReNorm==='function'?pontoReNorm(re):re;
  var jobs=[
    re?sbFetch('ponto_registros',{filters:['re=eq.'+encodeURIComponent(re),'data=gte.'+ini,'data=lte.'+fim],order:'data.desc',limit:500}):Promise.resolve([]),
    sbFetch('prog_status_diario',{filters:['colaborador_id=eq.'+c.id,'data=gte.'+ini,'data=lte.'+fim],order:'data.desc',limit:500}).catch(function(){return[];})
  ];
  if(reNorm && reNorm!==re){
    jobs[0]=Promise.all([
      sbFetch('ponto_registros',{filters:['re=eq.'+encodeURIComponent(re),'data=gte.'+ini,'data=lte.'+fim],order:'data.desc',limit:500}),
      sbFetch('ponto_registros',{filters:['re=eq.'+encodeURIComponent(reNorm),'data=gte.'+ini,'data=lte.'+fim],order:'data.desc',limit:500})
    ]).then(function(rr){ return (rr[0]||[]).concat(rr[1]||[]); });
  }
  Promise.all(jobs).then(function(res){
    var visto={}, ponto=[], prog=res[1]||[];
    (res[0]||[]).forEach(function(p){ var k=String(p.id||p.re)+'|'+String(p.data||''); if(!visto[k]){ visto[k]=1; ponto.push(p); } });
    var faltas=0, atest=0, afast=0, ferias=0, abono=0, linhas=[], dias={};
    ponto.forEach(function(p){
      var tipo=rhClassificarPontoLinha(p);
      if(!tipo) return;
      if(tipo==='Falta') faltas++;
      else if(tipo==='Atestado') atest++;
      else if(tipo==='Abono Curso') abono++;
      else if(tipo==='Afastado') afast++;
      else if(tipo==='Férias') ferias++;
      var d=String(p.data||'').slice(0,10);
      if(d && !dias[d+'|'+tipo]){ dias[d+'|'+tipo]=1; linhas.push({data:d,tipo:tipo}); }
    });
    (prog||[]).forEach(function(r){
      var st=(r.status||'').toLowerCase();
      var d=String(r.data||'').slice(0,10);
      var tipo='';
      if(r.com_atestado || st==='atestado') tipo='Atestado';
      else if(st==='abono_curso' || (st.indexOf('abono')>=0 && st.indexOf('curso')>=0)) tipo='Abono Curso';
      else if(st==='falta'||st==='faltou') tipo='Falta';
      else if(st==='afastado') tipo='Afastado';
      else if(st==='ferias') tipo='Férias';
      if(!tipo||!d||dias[d+'|'+tipo]) return;
      dias[d+'|'+tipo]=1;
      if(tipo==='Falta') faltas++;
      else if(tipo==='Atestado') atest++;
      else if(tipo==='Abono Curso') abono++;
      else if(tipo==='Afastado') afast++;
      else if(tipo==='Férias') ferias++;
      linhas.push({data:d,tipo:tipo});
    });
    linhas.sort(function(a,b){return String(b.data).localeCompare(String(a.data));});
    var data={faltas:faltas,atest:atest,afast:afast,ferias:ferias,abono:abono,linhas:linhas};
    _rhPontoCache[cacheKey]=data;
    pintar(data);
  }).catch(function(){
    var body=document.getElementById('rh-ponto-body');
    if(body) body.innerHTML='<div style="color:#854F0B">Não foi possível ler o ponto. A regra de ponto não foi alterada — use Gestão de Ponto.</div>';
  });
}
function rhConformidadePorContrato(){
  var by={};
  rhColabsAtivos().forEach(function(c){
    var key=c.contrato_id||'__sem__';
    if(!by[key]){
      var cont=rhContrato(c);
      by[key]={id:key,nome:rhContratoLabel(cont),colabs:0,emDia:0,pend:0,venc:0,avencer:0,itens:0};
    }
    var row=by[key];
    row.colabs++;
    var crit=rhPendenciasCriticas(c);
    var alertas=rhPendenciasAlertas(c);
    row.itens+=crit.length;
    if(!crit.length) row.emDia++;
    else if(crit.some(function(p){return p.status==='Vencido';})) row.venc++;
    else row.pend++;
    if(alertas.length) row.avencer++;
  });
  return Object.keys(by).map(function(k){ return by[k]; }).sort(function(a,b){ return (a.nome||'').localeCompare(b.nome||'','pt-BR'); });
}
function rhRenderConformidade(){
  var wrap=document.getElementById('rh-conformidade-wrap'); if(!wrap) return;
  var rows=rhConformidadePorContrato();
  var tot=rows.reduce(function(a,r){a.colabs+=r.colabs;a.emDia+=r.emDia;a.pend+=r.pend;a.venc+=r.venc;a.avencer+=r.avencer;a.itens+=r.itens;return a;},{colabs:0,emDia:0,pend:0,venc:0,avencer:0,itens:0});
  var pct=tot.colabs?Math.round(tot.emDia/tot.colabs*100):0;
  wrap.innerHTML='<div class="card"><div class="ch"><span class="ct">📊 Conformidade Documental por contrato</span><div style="display:flex;gap:6px"><button class="btn btn-sm" onclick="rhExportConformidadeCSV()">CSV</button><button class="btn btn-sm" onclick="rhPrintConformidade()">Imprimir</button></div></div>'
    +'<div style="padding:.6rem 1rem;font-size:12px;color:#888">Colaborador em dia = sem pendência crítica (pendente, vencido, sem arquivo ou recusado). A vencer é conforme com alerta preventivo e não derruba o %.</div>'
    +rhBannerFonte()
    +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;padding:0 1rem 1rem">'
    +rhCard('Colaboradores',tot.colabs,'#185FA5')+rhCard('Em dia',tot.emDia,'#3B6D11')+rhCard('Conformidade',pct+'%','#185FA5')
    +rhCard('Com vencido',tot.venc,tot.venc?'#A32D2D':'#3B6D11')+rhCard('Com a vencer',tot.avencer,tot.avencer?'#854F0B':'#3B6D11')
    +rhCard('Pendências (itens)',tot.itens,tot.itens?'#A32D2D':'#3B6D11')+'</div>'
    +'<div id="rh-conf-tabela" style="overflow-x:auto"><table class="tbl"><thead><tr><th>Contrato</th><th>Colaboradores</th><th>Em dia</th><th>Pendente</th><th>A vencer</th><th>Vencido</th><th>Itens</th><th>%</th></tr></thead><tbody>'
    +(rows.map(function(r){
      var p=r.colabs?Math.round(r.emDia/r.colabs*100):0;
      return '<tr><td>'+rhEsc(r.nome)+'</td><td>'+r.colabs+'</td><td>'+r.emDia+'</td><td>'+r.pend+'</td><td>'+r.avencer+'</td><td>'+r.venc+'</td><td>'+r.itens+'</td><td style="font-weight:700">'+(p)+'%</td></tr>';
    }).join('')||'<tr><td colspan="8" style="padding:1.5rem;text-align:center;color:#aaa">Sem colaboradores ativos para calcular.</td></tr>')
    +'</tbody></table></div></div>';
}
function rhExportConformidadeCSV(){
  var rows=rhConformidadePorContrato();
  var csv='Contrato;Colaboradores;Em dia;Pendente;A vencer;Vencido;Itens;% conformidade\n';
  rows.forEach(function(r){
    var p=r.colabs?Math.round(r.emDia/r.colabs*100):0;
    csv+=[r.nome,r.colabs,r.emDia,r.pend,r.avencer,r.venc,r.itens,p+'%'].join(';')+'\n';
  });
  var a=document.createElement('a'); a.href='data:text/csv;charset=utf-8,'+encodeURIComponent(csv);
  a.download='rh_conformidade_'+rhHoje()+'.csv'; a.click();
  if(typeof progShowToast==='function') progShowToast('CSV de conformidade exportado.');
}
function rhPrintConformidade(){
  var tab=document.getElementById('rh-conf-tabela');
  var html='<html><head><meta charset="UTF-8"><title>Conformidade Documental RH</title><style>body{font-family:Arial,sans-serif;padding:24px;color:#1a1a18}h2{margin:0 0 8px}p{font-size:12px;color:#666}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border:1px solid #ddd;padding:6px 8px;text-align:left}th{background:#f5f5f3}</style></head><body>'
    +'<h2>Conformidade Documental por contrato</h2><p>ERP CENA · '+rhHoje()+' · Relatório de apoio à gestão.</p>'
    +(tab?tab.innerHTML:'<p>Sem dados.</p>')+'</body></html>';
  var w=window.open('','_blank','width=900,height=700');
  if(w){ w.document.write(html); w.document.close(); setTimeout(function(){ w.print(); },400); }
}
function rhOnFiltroProntidaoInativos(el){
  _rhProntoInativos=!!(el&&el.checked);
  if(_rhProntoInativos && !_rhProntidaoInativosLoaded && !DEMO && typeof rhProntidaoGarantirInativos==='function'){
    rhProntidaoGarantirInativos().then(function(){ rhRenderProntidao(); });
    return;
  }
  rhRenderProntidao();
}
function rhRenderProntidao(){
  var wrap=document.getElementById('rh-prontidao-wrap'); if(!wrap) return;
  var cid=_rhProntoContrato, bid=_rhProntoBase, st=_rhProntoStatus;
  var rows=rhListaProntidao(cid, bid, st);
  var fila=rhFilaConferencia();
  var nPronto=rows.filter(function(r){return r.st==='pronto';}).length;
  var nBloq=rows.filter(function(r){return r.st==='bloqueado';}).length;
  var nAt=rows.filter(function(r){return r.st==='atencao';}).length;
  var nMx=rows.filter(function(r){return r.st==='sem_matriz';}).length;
  var nCg=rows.filter(function(r){return r.st==='sem_cargo';}).length;
  var nIn=rows.filter(function(r){return r.st==='inativo';}).length;
  wrap.innerHTML='<div class="card"><div class="ch"><span class="ct">🚀 Prontidão para mobilizar</span><div style="display:flex;gap:6px"><button class="btn btn-sm" onclick="rhExportProntidaoCSV()">CSV</button><button class="btn btn-sm" onclick="rhPrintProntidao()">Imprimir</button></div></div>'
    +'<div style="padding:.6rem 1rem;font-size:12px;color:#888">Consolidação de requisitos do colaborador conforme cargo, matriz RH, documentos e fontes operacionais. Não substitui SESMT nem libera o colaborador automaticamente para campo.</div>'
    +(_rhProntidaoCatalogo&&_rhProntidaoCatalogo.erro?'<div style="padding:.5rem 1rem;background:#FEF3E2;color:#854F0B;font-size:12px">'+rhEsc(_rhProntidaoCatalogo.erro)+'</div>':'')
    +'<div style="padding:.5rem 1rem;display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;border-bottom:.5px solid #eee">'
    +'<div><label style="font-size:11px;color:#888">Contrato</label><select class="inp" id="rh-pronto-contrato" onchange="_rhProntoContrato=this.value;rhRenderProntidao()">'+rhContratoOpts(cid)+'</select></div>'
    +'<div><label style="font-size:11px;color:#888">Base</label><select class="inp" id="rh-pronto-base" onchange="_rhProntoBase=this.value;rhRenderProntidao()">'+rhBaseOpts(bid)+'</select></div>'
    +'<div><label style="font-size:11px;color:#888">Cargo</label><select class="inp" id="rh-pronto-cargo" onchange="_rhProntoCargo=this.value;rhRenderProntidao()">'+rhProntidaoCargoOpts(_rhProntoCargo)+'</select></div>'
    +'<div><label style="font-size:11px;color:#888">Situação</label><select class="inp" id="rh-pronto-st" onchange="_rhProntoStatus=this.value;rhRenderProntidao()">'
    +'<option value="">Todas</option>'
    +[['pronto','Pronto'],['bloqueado','Bloqueado'],['atencao','Atenção'],['sem_matriz','Sem matriz'],['sem_cargo','Sem cargo'],['inativo','Inativo']].map(function(o){ return '<option value="'+o[0]+'"'+(st===o[0]?' selected':'')+'>'+o[1]+'</option>'; }).join('')
    +'</select></div>'
    +'<div><label style="font-size:11px;color:#888">Categoria</label><select class="inp" id="rh-pronto-cat" onchange="_rhProntoCat=this.value;rhRenderProntidao()">'
    +'<option value="">Todas</option>'
    +[['CNH','CNH'],['ASO','ASO'],['NR','NR'],['DOCUMENTO','Documento'],['TREINAMENTO','Treinamento'],['VINCULO','Vínculo'],['CARGO','Cargo']].map(function(o){ return '<option value="'+o[0]+'"'+(_rhProntoCat===o[0]?' selected':'')+'>'+o[1]+'</option>'; }).join('')
    +'</select></div>'
    +'<label style="font-size:12px;padding-bottom:6px"><input type="checkbox" '+(_rhProntoInativos?'checked ':'')+'onchange="rhOnFiltroProntidaoInativos(this)"/> Incluir inativos</label></div>'
    +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px;padding:1rem">'
    +rhCard('Na lista',rows.length,'#185FA5')+rhCard('Prontos',nPronto,'#3B6D11')+rhCard('Bloqueados',nBloq,nBloq?'#A32D2D':'#3B6D11')
    +rhCard('Atenção',nAt,nAt?'#854F0B':'#3B6D11')+rhCard('Sem matriz',nMx,nMx?'#185FA5':'#555')+rhCard('Sem cargo',nCg,nCg?'#854F0B':'#555')
    +(_rhProntoInativos?rhCard('Inativos',nIn,'#555'):'')+'</div>'
    +'<div id="rh-pronto-tabela" style="overflow-x:auto"><table class="tbl"><thead><tr><th>Colaborador</th><th>RE</th><th>Cargo</th><th>Contrato</th><th>Base</th><th>Matriz</th><th>Situação</th><th>Bloqueios</th><th>Alertas</th><th></th></tr></thead><tbody>'
    +(rows.map(function(r){
      var p=r.p||{};
      var idJs=String(r.c.id).replace(/'/g,'');
      var mx=p.matriz_aprovada?'Aprovada':(p.matriz_status==='EM_CONFIGURACAO'?'Pendente':(p.cargo_id?'Sem matriz':'—'));
      return '<tr><td>'+rhEsc(r.c.nome)+'</td><td>'+rhEsc(r.c.re||'—')+'</td><td>'+rhEsc(p.cargo_nome||r.c.cargo||'—')+'</td><td>'+rhEsc(rhContratoLabel(rhContrato(r.c)))+'</td><td>'+rhEsc(rhProntidaoBaseLabel(r.c))+'</td><td style="font-size:11px">'+rhEsc(mx)+'</td><td>'+rhSeloProntidao(p)+'</td><td>'+(p.contagens&&p.contagens.bloqueios!=null?p.contagens.bloqueios:(p.crit||[]).length)+'</td><td>'+(p.contagens&&p.contagens.alertas!=null?p.contagens.alertas:(p.alertas||[]).length)+'</td><td style="white-space:nowrap">'
        +'<button class="btn btn-sm" onclick="rhAbrirDetalheProntidao(\''+idJs+'\')">Ver requisitos</button> '
        +'<button class="btn btn-sm" onclick="rhAbrirDossie(\''+idJs+'\')">Dossiê</button></td></tr>';
    }).join('')||'<tr><td colspan="10" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum colaborador no filtro.</td></tr>')
    +'</tbody></table></div></div>'
    +'<div class="card" style="margin-top:1rem"><div class="ch"><span class="ct">Fila de conferência documental</span><button class="btn btn-sm" onclick="rhValidarFilaSelecionados()" style="color:#3B6D11;border-color:#3B6D11">Validar selecionados</button></div>'
    +'<div style="padding:.6rem 1rem;font-size:12px;color:#888">Documentos entregues sem validação, recusados ou sem arquivo. Recusados não entram no lote — precisam de nova versão.</div>'
    +'<div style="overflow-x:auto"><table class="tbl"><thead><tr><th></th><th>Colaborador</th><th>Documento</th><th>Status</th><th>Ação</th><th></th></tr></thead><tbody>'
    +(fila.map(function(d){
      var c=(colaboradores||[]).find(function(x){return String(x.id)===String(d.colaborador_id);})||{};
      var st=rhStatusDocumento(d);
      var id=String(d.id).replace(/'/g,'');
      var ck=rhFilaPodeValidar(d)?'<input type="checkbox" class="rh-fila-ck" value="'+id+'"/>':'';
      return '<tr><td>'+ck+'</td><td>'+rhEsc(c.nome||'—')+'</td><td>'+rhEsc(d.tipo_documento||'—')+'</td><td>'+rhBadge(st)+'</td><td>'+rhEsc(rhFilaMotivo(d))+'</td><td style="white-space:nowrap">'
        +(rhFilaPodeValidar(d)?'<button class="btn btn-sm" onclick="rhValidarDocumento(\''+id+'\')" style="font-size:10px;color:#3B6D11;border-color:#3B6D11">Validar</button> ':'')
        +(st==='Recusado'?'':'<button class="btn btn-sm" onclick="rhAbrirRecusarDocumento(\''+id+'\')" style="font-size:10px;color:#A32D2D;border-color:#A32D2D">Recusar</button> ')
        +'<button class="btn btn-sm" onclick="rhAbrirDossie(\''+String(c.id||'').replace(/'/g,'')+'\')" style="font-size:10px">Dossiê</button></td></tr>';
    }).join('')||'<tr><td colspan="6" style="padding:1.5rem;text-align:center;color:#3B6D11">Fila vazia — nada aguardando conferência do RH.</td></tr>')
    +'</tbody></table></div></div>';
}
function rhExportProntidaoCSV(){
  var rows=rhListaProntidao(_rhProntoContrato,_rhProntoBase,_rhProntoStatus);
  var csv='Colaborador;RE;Cargo;Contrato;Base;Matriz;Status;Bloqueios;Alertas;Motivos\n';
  rows.forEach(function(r){
    var p=r.p||{};
    var sit=rhProntidaoGlobalLabel(p.status)||r.st;
    var mx=p.matriz_aprovada?'Aprovada':(p.matriz_status||'');
    var bloq=(p.crit||[]).map(function(x){return x.titulo||x.documento;}).join(', ');
    csv+=[r.c.nome||'',r.c.re||'',p.cargo_nome||r.c.cargo||'',rhContratoLabel(rhContrato(r.c)),rhProntidaoBaseLabel(r.c),mx,sit,(p.contagens&&p.contagens.bloqueios)||0,(p.contagens&&p.contagens.alertas)||0,bloq].join(';')+'\n';
  });
  var a=document.createElement('a'); a.href='data:text/csv;charset=utf-8,'+encodeURIComponent(csv);
  a.download='rh_prontidao_'+rhHoje()+'.csv'; a.click();
  if(typeof auditLog==='function'){ try{ auditLog('exportar','rh','EXPORTOU_PRONTIDAO',{qtd:rows.length}); }catch(e){} }
  if(typeof progShowToast==='function') progShowToast('CSV de prontidão exportado.');
}
