function rhIa4LabelCampo(chave, tipo){
  if(chave==='numero_documento' && tipo==='CNH') return 'Nº registro CNH';
  if(chave==='data_validade' && tipo==='CNH') return 'Validade CNH';
  if(chave==='data_emissao' && tipo==='CNH') return 'Emissão CNH';
  if(chave==='data_validade' && (tipo==='ASO'||/^NR/.test(String(tipo||''))||/Certificado|Capacitação|Vacinação|Integração|Operador|Direção|Lider|HAR|CRSC|RAS|Acesso/i.test(String(tipo||'')))) return 'Validade';
  return RH_IA4_LABELS[chave] || String(chave||'').replace(/_/g,' ');
}
function rhIa4HintTipoNome(nome){
  var n = String(nome||'').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  if(/ANTECEDENTE/.test(n)) return 'Atestado de antecedentes';
  if(/\bASO\b|ADMISSIONAL|OCUPACIONAL|ATESTADO.*SAUDE/.test(n)) return 'ASO';
  if(/ATESTADO/.test(n)) return 'Atestado';
  if(/SEGURO.*VIDA|SEGURO.*VIA/.test(n)) return 'Seguro de Vida';
  if(/ARMARIO/.test(n)) return 'Termo de Uso de Armário';
  if(/USO.*IMAGEM|DIREITO.*IMAGEM/.test(n)) return 'Termo de Uso de Imagem';
  if(/PROTOCOLO|RECIBO/.test(n)) return 'Protocolos / Recibos';
  if(/REGULAMENTO|MANUAL.*INTERNO/.test(n)) return 'Regulamento Interno / Manual';
  if(/ALCOOL|ETIL/.test(n)) return 'Termo de Ciência Álcool';
  if(/DISPENSA/.test(n)) return 'Certificado de Dispensa';
  if(/NR[\s_-]*10/.test(n)) return 'NR-10';
  if(/NR[\s_-]*35|TRABALHO.*ALTURA/.test(n)) return 'NR-35';
  if(/NR[\s_-]*33|ESPACO.*CONFIN/.test(n)) return 'NR-33';
  if(/NR[\s_-]*12/.test(n)) return 'NR-12';
  if(/NR[\s_-]*18/.test(n)) return 'NR-18';
  if(/NR[\s_-]*20/.test(n)) return 'NR-20';
  if(/NR[\s_-]*1\b/.test(n)) return 'NR-1';
  if(/NR[\s_-]*6\b/.test(n)) return 'NR-6';
  if(/COMPROVANTE|RESIDENC|ENDERECO|CONTA.*LUZ|CONTA.*AGUA/.test(n)) return 'Comprovante de Residência';
  if(/CTPS.*REG|REG\s*ANTERIORES/.test(n)) return 'CTPS Reg Anteriores';
  if(/CTPS|CARTEIRA.*TRAB/.test(n)) return 'CTPS';
  if(/VACIN/.test(n)) return 'Vacinação';
  if(/\bPIS\b|\bNIT\b|\bPASEP\b/.test(n)) return 'PIS / NIT / PASEP';
  if(/PRORROGACAO|EXPERIENCIA/.test(n)) return 'Termos de Prorrogação de Experiência';
  if(/ADITIVO/.test(n)) return 'Aditivo';
  if(/CONTRATO.*TRAB|CONTRATO/.test(n)) return 'Contrato de Trabalho';
  if(/FICHA.*EPI|DOCUMENTOS.*CLIENTE/.test(n)) return 'Ficha de EPI';
  if(/PSICOSSOCIAL/.test(n)) return 'Avaliação Psicossocial';
  if(/MUDANCA.*FUNCAO/.test(n)) return 'Mudança de Função';
  if(/INTEGRACAO/.test(n)) return 'Integração';
  if(/SUSPENSAO/.test(n)) return 'Suspensão';
  if(/ADVERTENC/.test(n)) return 'Advertência';
  if(/DIRECAO.*DEFENS/.test(n)) return 'Direção Defensiva';
  if(/LIDER.*ACAO/.test(n)) return 'Lider em Ação';
  if(/\bHAR\b/.test(n)) return 'HAR';
  if(/\bCRSC\b/.test(n)) return 'CRSC';
  if(/GUINDAUTO/.test(n)) return 'Operador de Guindauto';
  if(/EMPILHADEIRA/.test(n)) return 'Operador de Empilhadeira';
  if(/OPERADOR.*MAQUIN/.test(n)) return 'Operador de Maquinas';
  if(/RAS[\s-]*CAS[\s-]*SAS/.test(n)) return 'RAS-CAS-SAS';
  if(/SUBESTACAO/.test(n)) return 'Acesso a Subestação';
  if(/CERTIFIC.*CAPACIT|CAPACITACAO|TREINAM|DIPLOMA/.test(n)) return 'Certificado de Capacitação';
  if(/CERTIDAO.*NASC/.test(n)) return 'Certidão de Nascimento';
  if(/FOTO\s*3|3X4|RETRATO/.test(n)) return 'Foto 3x4';
  if(/\bCIN\b|\bRG\b|IDENTIDADE/.test(n) && !/CNH|HABILITACAO|DRIVING/.test(n)) return 'RG / Identidade';
  if(/\bCPF\b/.test(n) && !/CNH|HABILITACAO/.test(n)) return 'CPF';
  if(/\bCNH\b|CARTEIRA\s*NACIONAL\s*DE\s*HABILIT|DRIVING\s*LICENSE/.test(n)) return 'CNH';
  return '';
}
function rhIa4EhTreinamentoTipo(t){
  t = String(t||'');
  if(/^NR-/.test(t)) return true;
  return /Certificado de Capacitação|Certificado|Integração|Direção Defensiva|Lider em Ação|HAR|CRSC|Operador|RAS-CAS-SAS|Acesso a Subestação/i.test(t);
}
function rhIa4CamposDoTipo(tipo){
  var map = rhIaMapearTipoDocumento(tipo);
  var t = (map.ok && map.tipo) ? map.tipo : tipo;
  var base = RH_IA4_SCHEMAS[t] ? RH_IA4_SCHEMAS[t].slice() : RH_IA4_CAMPOS_COMUNS.slice();
  if(rhIaEhAso(t) && !RH_IA4_SCHEMAS[t]) base = RH_IA4_SCHEMAS.ASO.slice();
  if(rhIa4EhTreinamentoTipo(t) && !RH_IA4_SCHEMAS[t]) base = RH_IA4_SCHEMAS['Certificado de Capacitação'].slice();
  if(t==='Foto 3x4') return ['nome'];
  var seen = {}, out = [];
  base.concat(RH_IA4_CAMPOS_CADASTRO_EXTRA).forEach(function(k){
    if(!k || seen[k]) return;
    seen[k]=1; out.push(k);
  });
  return out;
}
/* Guia CNH — modelo oficial CONTRAN 886/2021 (Detran-RS / SENATRAN).
   Fonte: https://www.detran.rs.gov.br/modelo-de-cnh + Res. CONTRAN 886/2021 Anexo. */
var RH_IA4_GUIA_CNH =
  'LAYOUT CNH (anverso/frente — modelo 2022+):\n'
  +'- Cabeçalho: REPÚBLICA FEDERATIVA DO BRASIL / SECRETARIA NACIONAL DE TRÂNSITO / DRIVING LICENSE.\n'
  +'- Foto à esquerda; NOME em destaque à direita da foto.\n'
  +'- DOC. IDENTIDADE / ÓRG. EMISSOR / UF → campo rg (não é o Nº REGISTRO).\n'
  +'- CPF → identificadores.cpf e campos.cpf (11 dígitos; NÃO confundir com Nº REGISTRO).\n'
  +'- DATA NASCIMENTO → data_nascimento.\n'
  +'- FILIAÇÃO → filiacao.\n'
  +'- ACC → só se houver caixeta ACC (ciclomotor); NÃO misturar com categoria A.\n'
  +'- CATEGORIA (impressa em vermelho) → categoria_cnh: letras A–E ou combinações (AB, AD, AE…). Sem inventar.\n'
  +'- Nº REGISTRO (vermelho) → numero_documento: registro nacional BINCO (~11 dígitos). NÃO é CPF, NÃO é espelho, NÃO é formulário RENACH (UF+dígitos).\n'
  +'- VALIDADE (vermelho) → data_validade: vencimento do exame. NÃO use a data da 1ª habilitação.\n'
  +'- 1ª HABILITAÇÃO → primeira_habilitacao (data distinta da validade).\n'
  +'- Ícone P = Permissão; D = Definitiva (não confundir com categoria D).\n'
  +'VERSO: tabela de categorias/pictogramas; OBSERVAÇÕES/restrições (EAR, lentes A, etc.) → restricoes_cnh; QR Code; local/data emissão → data_emissao se legível.\n'
  +'Se ilegível: valor vazio e confianca baixa. Nunca invente.\n';

function rhIa4GuiaDoTipo(tipo){
  var t = String(tipo||'');
  if(t==='CNH') return RH_IA4_GUIA_CNH;
  if(t==='RG / Identidade') return 'RG/CIN: número do registro geral, órgão/UF, nascimento, filiação, naturalidade, sexo. NÃO trate como CNH (sem CATEGORIA A–E de habilitação).\n';
  if(t==='CPF') return 'Cartão/Comprovante CPF: nome + CPF (11 dígitos). Não extrair categoria de habilitação.\n';
  if(t==='Comprovante de Residência') return 'Comprovante: endereço completo (logradouro, nº, bairro, cidade, UF, CEP) + titular + data. Confira se o nome é do colaborador.\n';
  if(t==='CTPS') return 'CTPS (carteira): PIS/NIT, número/série, admissão, cargo, empregador se impressos. Não invente.\n';
  if(t==='CTPS Reg Anteriores') return 'CTPS Reg Anteriores: empregos/registros anteriores (empregador, admissão/demissão, cargo). Só o impresso.\n';
  if(t==='Vacinação') return 'Cartão/comprovante de vacinação: nome, CPF se houver, datas, doses, validade se impressa.\n';
  if(t==='PIS / NIT') return 'Documento PIS/NIT: número PIS ou NIT + nome/CPF se houver.\n';
  if(t==='Foto 3x4') return 'Apenas fotografia. Sem extrair dados cadastrais inventados.\n';
  if(t==='Certidão de Nascimento') return 'Certidão de nascimento: nome, filiação, data de nascimento, cartório/número se legível.\n';
  if(t==='Certificado de Dispensa') return 'Certificado de dispensa: datas, autoridade/emissor, nome/CPF, validade se houver.\n';
  if(t==='Avaliação Psicossocial') return 'Avaliação psicossocial: data, resultado/conclusão, profissional, validade.\n';
  if(t==='Mudança de Função') return 'Mudança de função: cargo/função anteriores e novos, data, empresa.\n';
  if(t==='Advertência') return 'Advertência: data, motivo/observações, colaborador.\n';
  if(t==='Suspensão') return 'Suspensão: data início/fim ou validade, motivo, colaborador, empresa.\n';
  if(t==='Ficha de EPI') return 'Ficha de EPI: colaborador, data, itens se legíveis.\n';
  if(rhIaEhAso(t)) return 'ASO: tipo (admissional/periódico/demissional/retorno/mudança de risco), data exame, validade, resultado apto/inapto/apto com restrição, médico, CRM, clínica, riscos. Extraia CPF/nome se legíveis.\n';
  if(rhIa4EhTreinamentoTipo(t) || /^NR/.test(t)) return 'Certificado/treinamento/NR: curso/NR, instituição, instrutor, carga horária, data realização, validade, nº certificado. Extraia CPF/nome se legíveis.\n';
  if(/Contrato|Aditivo|Prorrogação|Experiência/.test(t)) return 'Contrato/termo/aditivo: empresa, cargo, função, salário, data início, jornada, filial — só o impresso/assinado.\n';
  return 'Extraia o máximo de texto legível útil a cadastro RH (nome, CPF, RG, endereço, datas, cargos). Não force campos de CNH se o documento não for CNH.\n';
}
function rhIa4MontarPromptClassificar(catalogo){
  var tipos = catalogo || rhIaCatalogoTipos().map(function(c){ return c.tipo; });
  return 'PASSAGEM 1 — SÓ CLASSIFICAÇÃO. Não extraia campos cadastrais.\n'
    + 'Documento brasileiro de RH / SESMT / identificação. Escolha UMA classe EXATA da lista (ou null se incerto):\n'
    + JSON.stringify(tipos)+'\n'
    + 'SINAIS (use o mais específico; NÃO classifique tudo como CNH):\n'
    + '- CNH: título "CARTEIRA NACIONAL DE HABILITAÇÃO" ou "DRIVING LICENSE"; layout DETRAN/SENATRAN; CATEGORIA + Nº REGISTRO + VALIDADE em destaque.\n'
    + '- RG/CIN: identidade civil / Carteira de Identidade Nacional; órgão emissor; SEM categoria de habilitação A–E.\n'
    + '- CPF: cartão ou comprovante de situação cadastral CPF.\n'
    + '- ASO: Atestado de Saúde Ocupacional; apto/inapto; médico/CRM.\n'
    + '- NR-10 / NR-35 / NR-33 / NR-6 / Certificado: certificado de treinamento ou NR; carga horária; instituição.\n'
    + '- CTPS: Carteira de Trabalho e Previdência Social (capa/dados gerais).\n'
    + '- CTPS Reg Anteriores: páginas de registros/empregos anteriores na CTPS.\n'
    + '- Suspensão: comunicado/termo disciplinar de suspensão (não confundir com Advertência).\n'
    + '- Advertência: advertência disciplinar escrita.\n'
    + '- Comprovante de Residência: conta de consumo, aluguel ou declaração com endereço.\n'
    + '- Contrato / Aditivo: contrato de trabalho ou aditivo assinado.\n'
    + '- Foto 3x4: só fotografia de rosto, sem formulário.\n'
    + '- Seguro de Vida: apólice/inclusão/certificado de seguro de vida.\n'
    + '- Atestado: atestado médico de afastamento (CID/CRM). Não é ASO.\n'
    + '- Termo de Uso de Armário / Imagem / Ciência Álcool: termos assinados.\n'
    + '- Protocolos / Recibos: protocolo ou recibo de entrega.\n'
    + '- Regulamento Interno / Manual: regulamento ou manual interno assinado.\n'
    + 'Se houver dúvida entre CNH e outro tipo, prefira null ou o tipo com mais evidência textual no documento — nunca assuma CNH por padrão.\n'
    + 'Não invente. Responda SOMENTE JSON sem markdown:\n'
    + '{"tipo_documento":null,"confianca_tipo":0.0,"paginas":1,"observacoes":""}';
}
function rhIa4MontarPromptExtrair(tipoConfirmado, catalogo){
  var tipos = catalogo || rhIaCatalogoTipos().map(function(c){ return c.tipo; });
  var tipo = tipoConfirmado || null;
  var campos = rhIa4CamposDoTipo(tipo);
  var guia = rhIa4GuiaDoTipo(tipo);
  return 'PASSAGEM 2 — EXTRAÇÃO COMPLETA E MÁXIMA. O tipo já foi classificado como: '
    + (tipo ? JSON.stringify(tipo) : 'null (não classificado — extraia tudo o que for legível sem forçar tipo).')+'\n'
    + 'Mantenha tipo_documento igual a essa classificação (ou null). Classes válidas: '+JSON.stringify(tipos)+'\n'
    + 'Objetivo: maximizar dados úteis para cadastro do colaborador, contratação, SESMT/treinamentos e dossiê.\n'
    + 'Extraia TODOS estes campos se legíveis (omita só o que não existir no documento): '+JSON.stringify(campos)+'\n'
    + 'Também pode incluir outras chaves legíveis em "campos" (ex.: telefone, email, observações).\n'
    + 'NÃO invente. NÃO preencha campos de CNH (categoria_cnh, primeira_habilitacao) se o documento NÃO for CNH.\n'
    + guia
    + 'Cada campo: {"valor":"","confianca":0.0,"pagina":1,"origem_visual":"impresso|manuscrito|carimbo|qr|ilegivel"}.\n'
    + 'Responda SOMENTE JSON sem markdown:\n'
    + '{"tipo_documento":'+(tipo?JSON.stringify(tipo):'null')+',"confianca_tipo":0.0,'
    + '"identificadores":{"cpf":{"valor":"","confianca":0.0,"pagina":1},"re":{"valor":"","confianca":0.0,"pagina":1},"synergy_matricula":{"valor":"","confianca":0.0,"pagina":1},"nome":{"valor":"","confianca":0.0,"pagina":1}},'
    + '"campos":{},"paginas":1,"observacoes":""}';
}
/** @deprecated use rhIa4MontarPromptClassificar + rhIa4MontarPromptExtrair */
function rhIa4MontarPrompt(hintTipo, catalogo){
  return rhIa4MontarPromptExtrair(hintTipo||null, catalogo);
}
/** Pós-checagem CNH: evita trocas clássicas CPF↔Registro e Validade↔1ª habilitação. */
/** Remove alucinações de CNH quando o documento não é CNH. */
function rhIa4LimparCamposForaDoTipo(out){
  if(!out) return out;
  var tipo = out.tipo_documento;
  if(!tipo || tipo==='CNH') return out;
  out.campos = out.campos || {};
  ['categoria_cnh','primeira_habilitacao','restricoes_cnh','orgao_emissor_cnh','uf_cnh'].forEach(function(k){
    if(out.campos[k]) delete out.campos[k];
  });
  return out;
}
function rhIa4PosValidarCnh(out){
  if(!out || out.tipo_documento!=='CNH') return rhIa4LimparCamposForaDoTipo(out);
  out.campos = out.campos || {};
  out.identificadores = out.identificadores || {};
  var avisos = [];
  function packVal(p){ return p && p.valor != null ? String(p.valor).trim() : ''; }
  var cpfId = packVal(out.identificadores.cpf);
  var cpfC = packVal(out.campos.cpf);
  var cpf = rhIaCpfDigits(cpfId || cpfC);
  var num = rhIa4NormCnhNum(packVal(out.campos.numero_documento));
  if(cpf && num && cpf===num){
    avisos.push('CPF_IGUAL_REGISTRO');
    if(out.campos.numero_documento){
      out.campos.numero_documento.confianca = Math.min(Number(out.campos.numero_documento.confianca||0.5), 0.35);
    }
  }
  if(cpf && !rhIa4CpfValido(cpf)){
    avisos.push('CPF_INVALIDO');
    if(out.identificadores.cpf) out.identificadores.cpf.confianca = Math.min(Number(out.identificadores.cpf.confianca||0.5), 0.3);
    if(out.campos.cpf) out.campos.cpf.confianca = Math.min(Number(out.campos.cpf.confianca||0.5), 0.3);
  }
  var val = packVal(out.campos.data_validade);
  var prim = packVal(out.campos.primeira_habilitacao);
  var valN = rhIa4NormData(val), primN = rhIa4NormData(prim);
  if(valN && primN && valN===primN){
    avisos.push('VALIDADE_IGUAL_1A_HAB');
    if(out.campos.data_validade) out.campos.data_validade.confianca = Math.min(Number(out.campos.data_validade.confianca||0.5), 0.4);
  }
  if(avisos.length){
    out.observacoes = (out.observacoes?out.observacoes+' | ':'')+'alerta_cnh:'+avisos.join(',');
  }
  return out;
}
function rhIa4CpfValido(d){
  d = String(d||'').replace(/\D/g,'');
  if(d.length!==11 || /^(\d)\1{10}$/.test(d)) return false;
  var i,s,r;
  for(s=0,i=0;i<9;i++) s+= +d[i]*(10-i);
  r=(s*10)%11; if(r===10) r=0; if(r!==+d[9]) return false;
  for(s=0,i=0;i<10;i++) s+= +d[i]*(11-i);
  r=(s*10)%11; if(r===10) r=0; return r===+d[10];
}
function rhIa4NormCpf(s){
  var d = rhIaCpfDigits(s);
  if(d.length<11) d = d.padStart(11,'0');
  d = d.slice(-11);
  if(!rhIa4CpfValido(d)) return '';
  return d;
}
function rhIa4NormData(s){
  if(typeof rhIaDataCampo==='function') return rhIaDataCampo(s) || '';
  return '';
}
function rhIa4NormCep(s){ var d=String(s||'').replace(/\D/g,''); return d.length===8?d:''; }
function rhIa4NormCnhNum(s){ return String(s||'').replace(/\D/g,''); }
function rhIa4NormCatCnh(s){
  var t=String(s||'').toUpperCase().replace(/[^A-E]/g,'');
  if(!t) return '';
  var seen={}, out='';
  for(var i=0;i<t.length;i++){ if(!seen[t[i]]){ seen[t[i]]=1; out+=t[i]; } }
  var order='ABCDE', sorted='';
  for(i=0;i<order.length;i++) if(seen[order[i]]) sorted+=order[i];
  return sorted;
}
function rhIa4NormRe(s){ return typeof rhNormRe==='function'?rhNormRe(s):String(s||'').replace(/\D/g,'').replace(/^0+/,''); }
function rhIa4NormUf(s){ var t=String(s||'').toUpperCase().replace(/[^A-Z]/g,''); return t.length===2?t:''; }
function rhIa4NormNome(s){ return String(s||'').replace(/\s+/g,' ').trim(); }
function rhIa4NormNum(s){ var n=parseFloat(String(s||'').replace(/\./g,'').replace(',','.').replace(/[^\d.-]/g,'')); return isFinite(n)?String(n):''; }
function rhIa4Pack(obj){
  if(!obj || typeof obj!=='object') return {valor:'',valor_normalizado:'',confianca:null,pagina:null,origem_visual:''};
  return {
    valor: obj.valor!=null?String(obj.valor):'',
    valor_normalizado: '',
    confianca: obj.confianca!=null?Number(obj.confianca):null,
    pagina: obj.pagina!=null?obj.pagina:null,
    origem_visual: obj.origem_visual||''
  };
}
function rhIa4AplicarNorm(chave, pack){
  var v = pack.valor;
  var n = v;
  if(chave==='cpf') n = rhIa4NormCpf(v);
  else if(/data_|validade|emissao|nascimento|admissao|exame|realizacao|comprovante|inicio/.test(chave)) n = rhIa4NormData(v)||v;
  else if(chave==='cep') n = rhIa4NormCep(v);
  else if(chave==='categoria_cnh') n = rhIa4NormCatCnh(v);
  else if(chave==='numero_documento' && /cnh/i.test(chave)) n = rhIa4NormCnhNum(v);
  else if(chave==='re') n = rhIa4NormRe(v);
  else if(chave==='uf'||chave==='uf_rg') n = rhIa4NormUf(v);
  else if(chave==='nome'||chave==='titular_residencia'||chave==='filiacao') n = rhIa4NormNome(v);
  else if(chave==='carga_horaria'||chave==='salario') n = rhIa4NormNum(v);
  else if(chave==='numero_documento') n = String(v||'').replace(/\s+/g,'').trim();
  pack.valor_normalizado = n;
  return pack;
}
function rhIa4NormalizarResultado(parsed){
  parsed = parsed || {};
  var idents = parsed.identificadores || {};
  var camposIn = parsed.campos || {};
  var pessoa = {
    nome: rhIa4AplicarNorm('nome', rhIa4Pack(idents.nome||camposIn.nome)),
    cpf: rhIa4AplicarNorm('cpf', rhIa4Pack(idents.cpf||camposIn.cpf)),
    re: rhIa4AplicarNorm('re', rhIa4Pack(idents.re||camposIn.re)),
    matricula: rhIa4AplicarNorm('re', rhIa4Pack(idents.synergy_matricula||camposIn.matricula))
  };
  var campos = {};
  Object.keys(camposIn).forEach(function(k){
    campos[k] = rhIa4AplicarNorm(k, rhIa4Pack(camposIn[k]));
  });
  ['nome','cpf','re','matricula'].forEach(function(k){
    if(!campos[k] && pessoa[k] && pessoa[k].valor) campos[k] = pessoa[k];
  });
  return {pessoa:pessoa, campos:campos, tipo:parsed.tipo_documento||null, confianca_tipo:parsed.confianca_tipo, paginas:parsed.paginas, observacoes:parsed.observacoes||''};
}
function rhIa4ValPack(pack){
  if(!pack) return '';
  return String(pack.valor_normalizado||pack.valor||'').trim();
}
function rhIa4Vazio(v){ return v==null || String(v).trim()==='' || String(v)==='—'; }
function rhIa4Eq(a,b,chave){
  var x=String(a||'').trim(), y=String(b||'').trim();
  if(chave==='cpf'){ x=rhIa4NormCpf(x); y=rhIa4NormCpf(y); return !!(x&&y&&x===y); }
  if(chave==='categoria_cnh'){ return rhIa4NormCatCnh(x)===rhIa4NormCatCnh(y) && !!rhIa4NormCatCnh(x); }
  if(/data_|validade|emissao|nascimento/.test(chave)){
    x=rhIa4NormData(x)||x.slice(0,10); y=rhIa4NormData(y)||y.slice(0,10);
    return !!(x&&y&&x===y);
  }
  if(chave==='nome'){
    var nx=rhIa4NormNome(x).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    var ny=rhIa4NormNome(y).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    return !!(nx&&ny&&nx===ny);
  }
  if(chave==='re'||chave==='matricula') return rhIa4NormRe(x)===rhIa4NormRe(y) && !!rhIa4NormRe(x);
  return x.toLowerCase()===y.toLowerCase() && !!x;
}
function rhIa4FmdCnh(col){
  if(!col) return null;
  return (typeof frt_motorista_docs!=='undefined'?frt_motorista_docs:[]).find(function(d){
    return String(d.colaborador_id)===String(col.id) && d.tipo_documento==='CNH' && d.status!=='Cancelada';
  })||null;
}
function rhIa4AsoCena(col){
  if(!col || typeof treinamentos==='undefined') return null;
  var meus = (typeof treinDoColaborador==='function'?treinDoColaborador(col.id):(treinamentos||[]).filter(function(t){return String(t.funcionario_id)===String(col.id);}));
  var asos = meus.filter(function(t){ var nr=String(t.nr||'').toUpperCase(), tt=String(t.titulo||'').toUpperCase(); return nr==='ASO'||tt.indexOf('ASO')>=0; })
    .sort(function(a,b){ return String(b.validade||b.val||'').localeCompare(String(a.validade||a.val||'')); });
  return asos[0]||null;
}
function rhIa4DocRh(col, tipo){
  if(!col || typeof _rhDocs==='undefined') return null;
  return (_rhDocs||[]).find(function(d){
    return String(d.colaborador_id)===String(col.id) && d.ativo!==false
      && String(d.tipo_documento||'').toLowerCase()===String(tipo||'').toLowerCase();
  })||null;
}

