      if(datasFb.validade) sintetico.push({chave:'data_validade', label:'Validade', treinCampo:'validade', docVal:String(datasFb.validade).slice(0,10), docDataMeta:null, confianca:1, cenaAtual:'', status:'NOVO_DADO'});
