    if(c.status==='CONFERE') decisoes[c.chave]='confere';
    else if(c.status==='INFORME' || c.status==='VAZIO') decisoes[c.chave]='';
    else if(c.status==='NOVO_DADO') decisoes[c.chave]='documento';
    else decisoes[c.chave]='documento';
