function rhIa5bValoresDeCampos(campos, decisoes, modo){
  var out = {titulo:'', data:'', validade:'', resultado:'', medico:'', clinica:'', instituicao:'', nr:'', obsParts:[]};
  (campos||[]).forEach(function(c){
    var dec = (decisoes&&decisoes[c.chave]) || '';
    if(dec!=='documento' && c.status!=='CONFERE') return;
    var v = c.docVal;
    if(dec==='cena'||dec==='manter'||dec==='skip') return;
    if(c.status==='CONFERE' && dec!=='documento') return;
    if(c.chave==='tipo_exame') out.titulo = 'ASO '+v;
    if(c.chave==='titulo') out.titulo = v;
    if(c.chave==='nr_curso'){ out.nr = rhIa5bNormNr(v)||v; if(!out.titulo) out.titulo = out.nr; }
    if(c.chave==='data_exame'||c.chave==='data_realizacao'){
      out.data = (c.docDataMeta && c.docDataMeta.original) ? c.docDataMeta.original : v;
    }
    if(c.chave==='data_validade'){
      out.validade = (c.docDataMeta && c.docDataMeta.original) ? c.docDataMeta.original : v;
    }
    if(c.chave==='resultado') out.resultado = v;
    if(c.chave==='medico') out.medico = v;
    if(c.chave==='clinica') out.clinica = v;
    if(c.chave==='instituicao') out.instituicao = v;
    if(c.chave==='crm'||c.chave==='carga_horaria'||c.chave==='instrutor'||c.chave==='certificado'){
      out.obsParts.push(c.label+': '+v);
    }
  });
  var md = modo || (_rhIa5b && _rhIa5b.modo) || 'NR';
  return rhIa5bNormalizarValoresDatas(out, md, campos);
}
