function evolAbrirDocs(colabId){
  var c = colaboradores.find(function(x){return x.id===colabId;})||{};
  docCarregarColab(colabId, function(){
    var docs = _colabDocs[colabId]||{};
    var stat = docPct(colabId);
    var corPct = stat.pct===100?'#3B6D11':stat.pct>=60?'#185FA5':stat.pct>0?'#854F0B':'#A32D2D';

    var itens = DOCS_OBRIGATORIOS.map(function(d, i){
      var entry = docs[d.id]||{};
      var checked = !!entry.entregue;
      return '<div style="display:flex;align-items:center;gap:10px;padding:7px 0;border-bottom:.5px solid #f5f5f3">'
        +'<label style="display:flex;align-items:center;gap:10px;cursor:pointer;flex:1">'
        +'<input type="checkbox" id="doc-ck-'+d.id+'" '+(checked?'checked':'')+' onchange="evolToggleDoc(\''+colabId+'\',\''+d.id+'\')" style="width:16px;height:16px;cursor:pointer">'
        +'<span style="font-size:14px">'+d.icone+'</span>'
        +'<div style="flex:1">'
        +'<div style="font-size:12px;font-weight:'+(d.obrigatorio?'600':'400')+'">'
          +d.label+(d.obrigatorio?'<span style="color:#A32D2D;margin-left:4px">*</span>':'')
        +'</div>'
        +(entry.data?'<div style="font-size:10px;color:#3B6D11">Entregue em '+fmtD(entry.data)+'</div>':'')
        +'</div>'
        +'</label>'
        +'<span style="font-size:11px;font-weight:600;color:'+(checked?'#3B6D11':'#ccc')+'">'+(checked?'✓':'—')+'</span>'
        +'</div>';
    }).join('');

    setModal('<div class="modal-bg"><div class="modal" style="max-width:480px;max-height:90vh;overflow-y:auto">'
      // Header
      +'<div style="display:flex;align-items:center;gap:10px;margin-bottom:1rem;position:sticky;top:0;background:#fff;padding-bottom:.5rem;border-bottom:.5px solid #e0dfd8">'
      +'<div><div style="font-size:15px;font-weight:700">📄 Documentos — '+escHtml(c.nome||'')+'</div>'
      +'<div style="font-size:11px;color:#888">'+escHtml(c.cargo||'')+(c.re?' · RE '+c.re:'')+'</div></div>'
      +'<button class="btn" onclick="closeModal()" style="margin-left:auto;padding:3px 9px">✕</button>'
      +'</div>'
      // Barra de progresso
      +'<div style="background:#f9f9f7;border-radius:10px;padding:12px 14px;margin-bottom:1rem">'
      +'<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:6px">'
      +'<span style="font-weight:600">Documentação obrigatória</span>'
      +'<span style="font-weight:700;color:'+corPct+'">'+stat.pct+'% ('+stat.entregues+'/'+stat.total+')</span>'
      +'</div>'
      +'<div style="background:#e0dfd8;border-radius:20px;height:8px;overflow:hidden">'
      +'<div id="doc-prog-bar" style="background:'+corPct+';width:'+stat.pct+'%;height:100%;border-radius:20px;transition:width .4s"></div>'
      +'</div>'
      +'<div style="font-size:10px;color:#aaa;margin-top:4px">* Itens obrigatórios</div>'
      +'</div>'
      // Lista de documentos
      +'<div id="doc-lista-inner">'+itens+'</div>'
      // Botão fechar
      +'<div style="margin-top:1rem;position:sticky;bottom:0;background:#fff;padding-top:.5rem;border-top:.5px solid #e0dfd8">'
      +'<button class="btn btn-pri" onclick="closeModal()" style="width:100%">Fechar</button>'
      +'</div>'
      +'</div></div>');
  });
}

function evolToggleDoc(colabId, docId){
  if(!_colabDocs[colabId]) _colabDocs[colabId]={};
  var ck = document.getElementById('doc-ck-'+docId);
  var entregue = ck ? ck.checked : false;
  var hoje = dataHojeLocal();

  // Preservar sempre o id no cache (nunca apagar)
  var entry = _colabDocs[colabId][docId] || {};
  var idExistente = entry.id || null;

  // Atualizar cache local preservando id
  _colabDocs[colabId][docId] = {
    entregue: entregue,
    data: entregue ? hoje : (entry.data||''),
    obs: entry.obs||'',
    id: idExistente
  };

  if(!DEMO){
    if(idExistente){
      // Registro já existe no banco — apenas atualizar
      sbUpdate('sesmt_documentos_colab',
        {entregue:entregue, data_entrega: entregue ? hoje : null},
        'id=eq.'+idExistente
      );
    } else {
      // Primeiro registro — usar upsert para evitar conflito de unique constraint
      sbUpsert('sesmt_documentos_colab',
        {colaborador_id:colabId, doc_id:docId, entregue:entregue,
         data_entrega: entregue ? hoje : null,
         criado_em:new Date().toISOString()},
        'colaborador_id,doc_id'
      ).then(function(res){
        if(res&&res[0]&&res[0].id) _colabDocs[colabId][docId].id=res[0].id;
      });
    }
  }

  // Atualizar barra de progresso no modal sem fechar
  var stat = docPct(colabId);
  var corPct = stat.pct===100?'#3B6D11':stat.pct>=60?'#185FA5':stat.pct>0?'#854F0B':'#A32D2D';
  var bar = document.getElementById('doc-prog-bar');
  if(bar){ bar.style.width=stat.pct+'%'; bar.style.background=corPct; }
  var label = bar&&bar.parentElement&&bar.parentElement.previousElementSibling;

  // Atualizar o ✓ ao lado do item
  var span = ck&&ck.closest('div.flex, div[style]');
  // Atualizar label de %
  var pctEl = document.querySelector('[id^="doc-pct-"]');

  // Re-renderizar só o card fora do modal (debounced)
  clearTimeout(window._docRenderTimer);
  window._docRenderTimer = setTimeout(function(){ renderEvolucao(); },300);
}

function evolDocBloco(c){
  var docs = _colabDocs[c.id]||{};
  var stat = docPct(c.id);
  var corPct = stat.pct===100?'#3B6D11':stat.pct>=60?'#185FA5':stat.pct>0?'#854F0B':'#A32D2D';
  var faltam = DOCS_OBRIGATORIOS.filter(function(d){return d.obrigatorio&&!(docs[d.id]&&docs[d.id].entregue);});
  return '<div style="background:#f9f9f7;border-radius:8px;padding:8px 10px;margin-bottom:.75rem">'
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">'
    +'<span style="font-size:12px;font-weight:600;color:#555">📄 Documentação</span>'
    +'<span style="font-size:11px;font-weight:700;color:'+corPct+';margin-left:auto">'+stat.pct+'%</span>'
    +'<span style="font-size:10px;color:#888">('+stat.entregues+'/'+stat.total+' obrigatórios)</span>'
    +'</div>'
    +'<div style="background:#e0dfd8;border-radius:20px;height:5px;overflow:hidden;margin-bottom:6px">'
    +'<div style="background:'+corPct+';width:'+stat.pct+'%;height:100%;border-radius:20px;transition:width .4s"></div>'
    +'</div>'
    +(faltam.length&&stat.pct<100
      ?'<div style="font-size:10px;color:#854F0B">Pendentes: '+faltam.map(function(d){return d.label;}).slice(0,3).join(', ')+(faltam.length>3?' +mais '+(faltam.length-3):'')+'</div>'
      :'<div style="font-size:10px;color:#3B6D11">✓ Todos os documentos obrigatórios entregues</div>'
    )
    +evolDocDossieResumoHtml(c, docs)
    +'</div>';
}
function evolDocDossieResumoHtml(c, checklist){
  var dossie = evolDocsDossieDoColab(c);
  if(!dossie.length){
    return '<div style="font-size:10px;color:#888;margin-top:6px">Nenhum arquivo no Dossiê Digital para este colaborador.</div>';
  }
  dossie.forEach(function(d){
    var sid = d.doc_id_sesmt;
    if(!sid && typeof rhIaDocIdSesmt==='function') sid = rhIaDocIdSesmt(d.tipo_documento);
    if(sid && checklist && !(checklist[sid]&&checklist[sid].entregue)){
      checklist[sid] = {entregue:true, data:(d.data_emissao||'').toString().slice(0,10), obs:'Dossiê', id:null};
    }
  });
  return '<div style="font-size:10px;color:#185FA5;margin-top:6px"><b>Dossiê:</b> '
    +dossie.slice(0,12).map(function(d){
      var lab = rhEsc(d.tipo_documento||'Documento');
      if(rhDocEhAssinaturaDigital(d)) return rhDocLinkArquivoHtml(d, d.tipo_documento||'Documento');
      return d.arquivo_url
        ? '<a href="'+rhEsc(d.arquivo_url)+'" target="_blank" rel="noopener" style="color:#185FA5">'+lab+'</a>'
        : lab;
    }).join(' · ')
    +(dossie.length>12?' +'+(dossie.length-12):'')
    +'</div>';
}


// === SESMT Evolução sob demanda (substitui bloco renderSesmtEvolucao…evolDocDossieResumoHtml) ===
var _evolUi = {
  view: 'busca', // busca | lista | ficha
  q: '',
  contratoId: '',
  situacao: 'ativo',
  page: 1,
  pageSize: 50,
  maxBusca: 50,
  colabId: null
};

if(typeof window.CENA_PERF_DEBUG==='undefined') window.CENA_PERF_DEBUG = false;
function cenaPerfStart(label){
  if(!window.CENA_PERF_DEBUG) return;
  try{ performance.mark('cena:'+label+':start'); console.time('CENA '+label); }catch(e){}
}
function cenaPerfEnd(label, extra){
  if(!window.CENA_PERF_DEBUG) return;
  try{
    performance.mark('cena:'+label+':end');
    performance.measure('cena:'+label, 'cena:'+label+':start', 'cena:'+label+':end');
    console.timeEnd('CENA '+label);
    if(extra) console.log('CENA '+label, extra);
  }catch(e){}
}
function cenaPerfDomCount(elOrId){
  if(!window.CENA_PERF_DEBUG) return 0;
  var el = typeof elOrId==='string' ? document.getElementById(elOrId) : elOrId;
  if(!el) return 0;
  return el.querySelectorAll('*').length;
}

function desmontarSesmtEvolucao(){
  var lista = document.getElementById('evol-lista');
  if(lista) lista.innerHTML = '';
  if(_evolUi && _evolUi.view==='ficha'){
    _evolUi.view = (_evolUi.q || _evolUi.contratoId) ? 'lista' : 'busca';
    _evolUi.colabId = null;
  }
}
function desmontarSesmtTreinamentos(){
  var tbody = document.getElementById('tbody-trein');
  if(tbody) tbody.innerHTML = '';
  var pager = document.getElementById('tr-pager');
  if(pager) pager.innerHTML = '';
  var cont = document.getElementById('tr-fil-cont');
  if(cont) cont.textContent = '';
  if(typeof _trUi!=='undefined') _trUi.montado = false;
}

function evolEscId(id){ return String(id||'').replace(/'/g,"\\'"); }

function evolInvalidateAposIa(colabId){
  if(colabId){
    try{ delete _colabDocs[colabId]; }catch(e){}
  }
  if(_evolUi && _evolUi.view==='ficha' && colabId && String(_evolUi.colabId)===String(colabId)){
    evolAbrirColab(colabId);
  }
}

function renderSesmtEvolucao(){
  var pg = document.getElementById('pg-sesmt-evolucao'); if(!pg) return;
  cenaPerfStart('sesmt-evolucao-open');
  var sel = document.getElementById('evol-fil-contrato');
  if(sel){
    var cur = _evolUi.contratoId || sel.value || '';
    sel.innerHTML = '<option value="">Todos os contratos (só com busca)</option>'
      + (contratos||[]).map(function(c){ return '<option value="'+c.id+'"'+(String(cur)===String(c.id)?' selected':'')+'>'+escHtml(c.nome||c.codigo||c.id)+'</option>'; }).join('');
    _evolUi.contratoId = sel.value || '';
  }
  var busca = document.getElementById('evol-fil-busca');
  if(busca && _evolUi.q) busca.value = _evolUi.q;
  var sit = document.getElementById('evol-fil-situacao');
  if(sit) sit.value = _evolUi.situacao || 'ativo';
  // NÃO montar evolução de todos — só shell / lista / ficha sob demanda
  if(_evolUi.view==='ficha' && _evolUi.colabId){
    evolAbrirColab(_evolUi.colabId);
    cenaPerfEnd('sesmt-evolucao-open',{view:'ficha',domNodes:cenaPerfDomCount(pg)});
    return;
  }
  _evolUi.view = (_evolUi.q || _evolUi.contratoId) ? 'lista' : 'busca';
  evolRenderShell();
  cenaPerfEnd('sesmt-evolucao-open',{view:_evolUi.view,domNodes:cenaPerfDomCount(pg)});
}

/** Compat: chamadas legadas passam a respeitar o modo sob demanda. */
function renderEvolucao(){
  if(_evolUi.view==='ficha' && _evolUi.colabId){
    evolRenderFicha();
    return;
  }
  if(_evolUi.view==='lista' || _evolUi.q || _evolUi.contratoId){
    evolRenderLista();
    return;
  }
  evolRenderShell();
}

function evolOnFiltroChange(){
  var busca = document.getElementById('evol-fil-busca');
  var cont = document.getElementById('evol-fil-contrato');
  var sit = document.getElementById('evol-fil-situacao');
  _evolUi.q = ((busca&&busca.value)||'').trim();
  _evolUi.contratoId = (cont&&cont.value)||'';
  _evolUi.situacao = (sit&&sit.value)||'ativo';
  _evolUi.page = 1;
  _evolUi.colabId = null;
  if(!_evolUi.q && !_evolUi.contratoId){
    _evolUi.view = 'busca';
    evolRenderShell();
    return;
  }
  _evolUi.view = 'lista';
  evolRenderLista();
}

function evolVoltarBusca(){
  _evolUi.view = (_evolUi.q || _evolUi.contratoId) ? 'lista' : 'busca';
  _evolUi.colabId = null;
  var lista = document.getElementById('evol-lista');
  if(lista) lista.innerHTML = '';
  if(_evolUi.view==='lista') evolRenderLista();
  else evolRenderShell();
}

function evolRenderShell(){
  var lista = document.getElementById('evol-lista'); if(!lista) return;
  lista.innerHTML =
    '<div class="card" style="padding:1.5rem;text-align:center">'
    +'<div style="font-size:15px;font-weight:700;margin-bottom:8px">Evolução de Colaboradores</div>'
    +'<div style="font-size:13px;color:#666;max-width:420px;margin:0 auto 12px;line-height:1.45">'
    +'Consulta sob demanda. Pesquise por <b>nome</b> ou <b>RE</b>, ou filtre por contrato — a evolução completa só abre após selecionar um colaborador.'
    +'</div>'
    +'<div style="font-size:12px;color:#888">Nenhum histórico montado até a seleção. Isso evita dezenas de milhares de elementos no DOM.</div>'
    +'</div>';
}

function evolNormReBusca(v){
  var s = String(v||'').replace(/\D/g,'');
  return s.replace(/^0+/,'') || (s ? '0' : '');
}

function evolColabsFiltrados(){
  var q = String(_evolUi.q||'').trim().toLowerCase();
  var qDig = evolNormReBusca(q);
  var cont = _evolUi.contratoId;
  var sit = _evolUi.situacao || 'ativo';
  return (colaboradores||[]).filter(function(c){
    if(sit==='ativo' && c.ativo===false) return false;
    if(sit==='inativo' && c.ativo!==false) return false;
    if(cont && String(c.contrato_id)!==String(cont)) return false;
    if(!q) return !!cont; // lista só com contrato (ou com busca)
    var nome = String(c.nome||'').toLowerCase();
    var re = String(c.re||c.matricula||'');
    var reNorm = evolNormReBusca(re);
    if(nome.indexOf(q)>=0) return true;
    if(qDig && (reNorm===qDig || reNorm.indexOf(qDig)>=0 || String(re).toLowerCase().indexOf(q)>=0)) return true;
    return false;
  }).sort(function(a,b){ return String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR'); });
}

function evolProntidaoResumo(c){
  try{
    if(typeof calcularAptidao==='function'){
      var apt = calcularAptidao(c);
      return {pct:apt.pct, status:apt.status};
    }
  }catch(e){}
  return {pct:'—', status:'—'};
}

function evolRenderLista(){
  var lista = document.getElementById('evol-lista'); if(!lista) return;
  cenaPerfStart('sesmt-evolucao-lista');
  var cols = evolColabsFiltrados();
  var isBusca = !!String(_evolUi.q||'').trim();
  var pageSize = isBusca ? (_evolUi.maxBusca||50) : (_evolUi.pageSize||50);
  var total = cols.length;
  var pages = Math.max(1, Math.ceil(total / pageSize));
  if(_evolUi.page > pages) _evolUi.page = pages;
  var start = (_evolUi.page - 1) * pageSize;
  var slice = cols.slice(start, start + pageSize);

  if(!total){
    lista.innerHTML = '<div class="card" style="padding:1.5rem;text-align:center;color:#888">'
      +(isBusca?'Nenhum colaborador encontrado para a busca.':'Selecione um contrato ou pesquise por nome/RE.')
      +'</div>';
    cenaPerfEnd('sesmt-evolucao-lista',{total:0,domNodes:cenaPerfDomCount('pg-sesmt-evolucao')});
    return;
  }

  var html = '<div class="card" style="margin-bottom:.75rem;padding:.75rem 1rem">'
    +'<div style="display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:space-between">'
    +'<div style="font-size:13px;font-weight:600">'+(isBusca?'Resultados da busca':'Colaboradores do contrato')
    +' <span style="font-weight:400;color:#888">· '+(start+1)+'–'+(start+slice.length)+' de '+total+'</span></div>'
    +'<div style="display:flex;gap:6px;align-items:center">'
    +'<select class="inp" style="width:100px;font-size:11px" onchange="_evolUi.pageSize=parseInt(this.value,10)||50;_evolUi.maxBusca=_evolUi.pageSize;_evolUi.page=1;evolRenderLista()">'
    +'<option value="25"'+(pageSize===25?' selected':'')+'>25 / pág</option>'
    +'<option value="50"'+(pageSize===50?' selected':'')+'>50 / pág</option>'
    +'<option value="100"'+(pageSize===100?' selected':'')+'>100 / pág</option>'
    +'</select>'
    +(_evolUi.page>1?'<button class="btn btn-sm" type="button" onclick="_evolUi.page--;evolRenderLista()">Anterior</button>':'')
    +'<span style="font-size:11px;color:#888">pág. '+_evolUi.page+'/'+pages+'</span>'
    +(_evolUi.page<pages?'<button class="btn btn-sm" type="button" onclick="_evolUi.page++;evolRenderLista()">Próximo</button>':'')
    +'</div></div>'
    +'<div style="font-size:11px;color:#854F0B;margin-top:6px">Lista leve — a evolução completa só abre ao clicar em Abrir evolução.</div>'
    +'</div>';

  html += '<div class="card" style="overflow-x:auto"><table class="tbl" style="font-size:12px"><thead><tr>'
    +'<th>RE</th><th>Nome</th><th>Cargo</th><th>Contrato</th><th>Situação</th><th>Prontidão</th><th></th>'
    +'</tr></thead><tbody>';
  slice.forEach(function(c){
    var cont = (contratos||[]).find(function(x){ return String(x.id)===String(c.contrato_id); });
    var apt = evolProntidaoResumo(c);
    var cor = {'Apto':'#3B6D11','Bloqueado':'#A32D2D','Pendente':'#854F0B','Em mobilização':'#185FA5'}[apt.status]||'#888';
    html += '<tr>'
      +'<td>'+escHtml(c.re||'—')+'</td>'
      +'<td><b>'+escHtml(c.nome||'')+'</b></td>'
      +'<td>'+escHtml(c.cargo||'—')+'</td>'
      +'<td>'+escHtml(cont?(cont.codigo||cont.nome):'—')+'</td>'
      +'<td>'+(c.ativo===false?'Inativo':'Ativo')+'</td>'
      +'<td style="color:'+cor+';font-weight:700">'+(apt.pct!=null?apt.pct+'%':'—')+' <span style="font-weight:400;font-size:10px">'+escHtml(apt.status||'')+'</span></td>'
      +'<td><button class="btn btn-sm btn-pri" type="button" onclick="evolAbrirColab(\''+evolEscId(c.id)+'\')">Abrir evolução</button></td>'
      +'</tr>';
  });
  html += '</tbody></table></div>';
  lista.innerHTML = html;
  cenaPerfEnd('sesmt-evolucao-lista',{total:total,rendered:slice.length,page:_evolUi.page,domNodes:cenaPerfDomCount('pg-sesmt-evolucao')});
}

async function evolCarregarDadosColab(colabId){
  try{ delete _colabDocs[colabId]; }catch(e){}
  if(DEMO){
    return new Promise(function(resolve){ docCarregarColab(colabId, resolve); });
  }
  var idsMap = typeof _colabIdsRelacionados==='function' ? (_colabIdsRelacionados(colabId)||{}) : {};
  var ids = Object.keys(idsMap);
  if(!ids.length) ids = [String(colabId)];
  var inList = ids.map(function(i){ return i; }).join(',');
  try{
    var tren = await sbFetch('treinamentos',{
      filters:['funcionario_id=in.('+inList+')','deleted_at=is.null'],
      order:'validade.desc',
      limit:800
    });
    if(!treinamentos) treinamentos = [];
    (tren||[]).forEach(function(t){
      var ix = treinamentos.findIndex(function(x){ return String(x.id)===String(t.id); });
      if(ix>=0) treinamentos[ix] = Object.assign({}, treinamentos[ix], t);
      else treinamentos.push(t);
    });
  }catch(eT){ console.warn('evolCarregarDadosColab treinamentos', eT); }
  try{
    var docs = await sbFetch('rh_colaborador_documentos',{
      filters:['colaborador_id=eq.'+colabId,'ativo=eq.true'],
      order:'atualizado_em.desc',
      limit:500
    });
    if(!_rhDocs) _rhDocs = [];
    (docs||[]).forEach(function(d){
      var ix = _rhDocs.findIndex(function(x){ return String(x.id)===String(d.id); });
      if(ix>=0) _rhDocs[ix] = Object.assign({}, _rhDocs[ix], d);
      else _rhDocs.unshift(d);
    });
    _rhDocsCarregado = true;
    _rhDocsDisponivel = true;
  }catch(eD){ console.warn('evolCarregarDadosColab docs', eD); }
  try{
    if(typeof rhSesmtCarregarVinculosColab==='function') await rhSesmtCarregarVinculosColab(colabId);
  }catch(eV){}
  return new Promise(function(resolve){ docCarregarColab(colabId, resolve); });
}

async function evolAbrirColab(colabId){
  _evolUi.view = 'ficha';
  _evolUi.colabId = colabId;
  var lista = document.getElementById('evol-lista');
  if(lista) lista.innerHTML = '<div class="card" style="padding:2rem;text-align:center;color:#888">Carregando evolução do colaborador…</div>';
  await evolCarregarDadosColab(colabId);
  evolRenderFicha();
}

async function evolAtualizarColab(){
  if(!_evolUi.colabId) return;
  progShowToast('Atualizando dados deste colaborador…');
  await evolCarregarDadosColab(_evolUi.colabId);
  evolRenderFicha();
  progShowToast('Evolução atualizada.');
}

function evolRenderFicha(){
  var lista = document.getElementById('evol-lista'); if(!lista) return;
  var c = (colaboradores||[]).find(function(x){ return String(x.id)===String(_evolUi.colabId); });
  if(!c){
    lista.innerHTML = '<div class="card" style="padding:1.5rem;text-align:center;color:#A32D2D">Colaborador não encontrado.</div>';
    return;
  }
  lista.innerHTML =
    '<div style="margin-bottom:.75rem;display:flex;gap:8px;flex-wrap:wrap;align-items:center">'
    +'<button class="btn btn-sm" type="button" onclick="evolVoltarBusca()">← Voltar para pesquisa</button>'
    +'<button class="btn btn-sm" type="button" onclick="evolAtualizarColab()">↻ Atualizar</button>'
    +'<span style="font-size:12px;color:#888">Somente este colaborador (consulta sob demanda)</span>'
    +'</div>'
    + evolMontarCardHtml(c);
}

function evolMontarCardHtml(c){
  var apt = calcularAptidao(c);
  var cont = (contratos||[]).find(function(x){ return x.id===c.contrato_id; });
  var hoje = dataHoje();
  var em30 = _diasAdiante(30);
  var meusTreinAll = typeof treinDoColaborador==='function'?treinDoColaborador(c.id):treinamentos.filter(function(t){ return String(t.funcionario_id)===String(c.id) && !t.deleted_at; });
  var meusTrein = typeof treinDedupPorFamilia==='function'?treinDedupPorFamilia(meusTreinAll, hoje):meusTreinAll;
  var meusEpis  = (epis||[]).filter(function(e){ return e.responsavel_id===c.id; });
  var nrs  = evolNrObrigatorioLista(c);
  var asos = meusTrein.filter(function(t){
    var nr=(t.nr||'').toUpperCase(); var tt=(t.titulo||'').toUpperCase();
    return nr==='ASO'||tt.includes('ASO')||tt.includes('ADMISSIONAL')||tt.includes('PERI\u00d3DICO')||tt.includes('PERIODICO');
  }).sort(function(a,b){return (b.val||b.validade||'')>(a.val||a.validade||'')?1:-1;});
  var aso = asos[0];
  var asoVal = aso ? (aso.val||aso.validade||'') : '';
  var asoSt  = !aso?'sem_aso':asoVal<hoje?'vencido':asoVal<=em30?'proximo':'valido';
  var ASO_COR = {
    sem_aso:{bg:'#FCEBEB',cor:'#A32D2D',icone:'🚫',label:'ASO ausente'},
    vencido: {bg:'#FCEBEB',cor:'#A32D2D',icone:'🔴',label:'ASO vencido'},
    proximo: {bg:'#FEF3E2',cor:'#854F0B',icone:'🟡',label:'Vence em breve'},
    valido:  {bg:'#EAF3DE',cor:'#3B6D11',icone:'🟢',label:'ASO v\u00e1lido'},
  };
  var asoC = ASO_COR[asoSt];
  var diasAso = asoVal ? Math.floor((new Date(asoVal)-new Date(hoje))/86400000) : null;
  var meusTreinLista = meusTrein.filter(function(t){ return !evolTreinEhAso(t); });
  var treinVencendo = meusTreinLista.filter(function(t){var v=t.val||t.validade;return v&&v>=hoje&&v<=em30;});
  var treinVencidos = meusTreinLista.filter(function(t){var v=t.val||t.validade;return v&&v<hoje;});
  var corStatus = {'Apto':'#3B6D11','Bloqueado':'#A32D2D','Pendente':'#854F0B','Em mobiliza\u00e7\u00e3o':'#185FA5'}[apt.status]||'#888';

  return '<div class="card" style="margin-bottom:.75rem">'
    +'<div style="display:flex;align-items:center;gap:10px;padding:.75rem 1rem;border-bottom:.5px solid #f5f5f3">'
    +'<div style="width:38px;height:38px;border-radius:50%;background:#1a1a18;color:#fff;display:flex;align-items:center;justify-content:center;font-size:15px;font-weight:700">'+(c.nome||'?').charAt(0)+'</div>'
    +'<div style="flex:1">'
    +'<div style="font-weight:700;font-size:14px">'+escHtml(c.nome||'')+'</div>'
    +'<div style="font-size:11px;color:#888">'+escHtml(c.cargo||'')+(cont?' \u00b7 '+escHtml(cont.codigo||cont.nome||''):'')+(c.re?' \u00b7 RE '+escHtml(c.re):'')+(c.admissao?' \u00b7 Desde '+fmtD(c.admissao):'')+'</div>'
    +'</div>'
    +'<div style="text-align:right">'
    +'<div style="font-size:18px;font-weight:700;color:'+corStatus+'">'+apt.pct+'%</div>'
    +'<div style="font-size:10px;color:#888">aptid\u00e3o</div>'
    +'</div></div>'
    +'<div style="padding:.75rem 1rem">'
    +'<div style="display:flex;align-items:center;gap:8px;padding:7px 10px;border-radius:8px;background:'+asoC.bg+';margin-bottom:.75rem">'
    +'<span style="font-size:16px">'+asoC.icone+'</span>'
    +'<div style="flex:1">'
    +'<div style="font-size:11px;font-weight:600;color:'+asoC.cor+'">🩺 ASO / Exame Ocupacional \u2014 '+asoC.label+'</div>'
    +(aso
      ? '<div style="font-size:11px;color:#555;margin-top:1px">'+escHtml(aso.titulo||'ASO')
        +(asoVal?' \u00b7 V\u00e1lido at\u00e9: <b>'+fmtD(asoVal)+'</b>':'')
        +(diasAso!==null?' \u00b7 <b style="color:'+asoC.cor+'">'+(diasAso<0?Math.abs(diasAso)+'d vencido':diasAso===0?'Vence HOJE':diasAso+'d restantes')+'</b>':'')
        +evolAsoArquivoHtml(c, aso)
        +'</div>'
      : '<div style="font-size:11px;color:#A32D2D;margin-top:1px">Nenhum ASO registrado. Necess\u00e1rio para aptid\u00e3o.</div>'
    )
    +'</div>'
    +'<button class="btn btn-sm" onclick="evolRegistrarASO(\''+evolEscId(c.id)+'\')" style="font-size:10px;white-space:nowrap;background:'+asoC.cor+';color:#fff;border-color:'+asoC.cor+'">+ ASO</button>'
    +(aso&&aso.id?'<button class="btn btn-sm" onclick="evolExcluirTreinamento(\''+evolEscId(aso.id)+'\')" style="font-size:10px;color:#A32D2D;border-color:#E8A0A0" title="Remover ASO desta lista">🗑</button>':'')
    +'</div>'
    + evolDocBloco(c)
    +'<div style="font-size:11px;font-weight:600;color:#555;margin-bottom:.5rem">🎓 Treinamentos ('+meusTreinLista.length+')'
    +(treinVencendo.length?'<span style="margin-left:6px;background:#FEF3E2;color:#854F0B;border-radius:10px;padding:0 6px;font-size:10px">\u26a0 '+treinVencendo.length+' vencendo</span>':'')
    +(treinVencidos.length?'<span style="margin-left:4px;background:#FCEBEB;color:#A32D2D;border-radius:10px;padding:0 6px;font-size:10px">🔴 '+treinVencidos.length+' vencidos</span>':'')
    +'</div>'
    +evolTreinLista(meusTreinAll, nrs, hoje, em30, c.id)
    +'<div style="font-size:11px;font-weight:600;color:#555;margin:.75rem 0 .5rem">🦺 EPIs ('+meusEpis.length+')</div>'
    +(meusEpis.length
      ? '<div style="display:flex;flex-wrap:wrap;gap:5px">'
        +meusEpis.map(function(e){
          var ok=e.status==='Ativo'&&(!e.validade||e.validade>=hoje);
          var prox=e.validade&&e.validade<=em30&&e.validade>=hoje;
          var bg=prox?'#FEF3E2':ok?'#EAF3DE':'#FCEBEB';
          var cor=prox?'#854F0B':ok?'#3B6D11':'#A32D2D';
          return '<span style="font-size:11px;padding:2px 7px;border-radius:99px;background:'+bg+';color:'+cor+';border:.5px solid '+cor+'">'+escHtml(e.nome)+(ok?'':' \u26a0')+'</span>';
        }).join('')+'</div>'
      : '<div style="font-size:11px;color:#aaa">Nenhum EPI registrado</div>'
    )
    +'</div>'
    +'<div style="padding:.4rem 1rem .6rem;display:flex;gap:6px;border-top:.5px solid #f5f5f3;flex-wrap:wrap">'
    +'<button class="btn btn-sm" onclick="openMobilizacaoDetalhe(\''+evolEscId(c.id)+'\')">📋 Detalhes</button>'
    +'<button class="btn btn-sm" onclick="evolVerTodosDocumentos(\''+evolEscId(c.id)+'\')" style="color:#185FA5;border-color:#185FA5">📄 Ver todos os documentos</button>'
    +'<button class="btn btn-sm" onclick="evolAbrirDocs(\''+evolEscId(c.id)+'\')">☑ Checklist SESMT</button>'
    +'<button class="btn btn-sm" onclick="evolRegistrarASO(\''+evolEscId(c.id)+'\')">🩺 + ASO</button>'
    +'<button class="btn btn-sm" onclick="openLancarTreinamento(\''+evolEscId(c.id)+'\')">🎓 + Treinamento</button>'
    +'<button class="btn btn-sm" onclick="openLancarTreinamento(\''+evolEscId(c.id)+'\',\'INTEGRA\')" style="color:#533AB7;border-color:#533AB7">🧭 + Integração</button>'
    +'<button class="btn btn-sm" onclick="evolAbrirDiagnosticoIntegracao(\''+evolEscId(c.id)+'\')" style="color:#854F0B;border-color:#854F0B">🔍 Verificar integração SESMT'
    +(function(){
      try{
        var dg = typeof evolDiagnosticarIntegracao==='function' ? evolDiagnosticarIntegracao(c.id) : null;
        var n = dg ? ((dg.docSemSesmt||[]).length+(dg.sesmtSemDoc||[]).length+(dg.divergente||[]).length) : 0;
        return n ? ' <span style="background:#FEF3E2;color:#854F0B;border-radius:8px;padding:0 5px;font-weight:700">⚠ '+n+'</span>' : '';
      }catch(e){ return ''; }
    })()
    +'</button>'
    +'<button class="btn btn-sm" onclick="sesmtSetAba(\'nr6\')">📋 Ficha NR-6</button>'
    +'</div>'
    +'</div>';
}

function evolAbrirDocs(colabId){
  var c = colaboradores.find(function(x){return String(x.id)===String(colabId);})||{};
  docCarregarColab(colabId, function(){
    var docs = _colabDocs[colabId]||{};
    var stat = docPct(colabId);
    var corPct = stat.pct===100?'#3B6D11':stat.pct>=60?'#185FA5':stat.pct>0?'#854F0B':'#A32D2D';

    var itens = DOCS_OBRIGATORIOS.map(function(d){
      var entry = docs[d.id]||{};
      var checked = !!entry.entregue;
      return '<div style="display:flex;align-items:center;gap:10px;padding:7px 0;border-bottom:.5px solid #f5f5f3">'
        +'<label style="display:flex;align-items:center;gap:10px;cursor:pointer;flex:1">'
        +'<input type="checkbox" id="doc-ck-'+d.id+'" '+(checked?'checked':'')+' onchange="evolToggleDoc(\''+evolEscId(colabId)+'\',\''+d.id+'\')" style="width:16px;height:16px;cursor:pointer">'
        +'<span style="font-size:14px">'+d.icone+'</span>'
        +'<div style="flex:1">'
        +'<div style="font-size:12px;font-weight:'+(d.obrigatorio?'600':'400')+'">'
          +d.label+(d.obrigatorio?'<span style="color:#A32D2D;margin-left:4px">*</span>':'')
        +'</div>'
        +(entry.data?'<div style="font-size:10px;color:#3B6D11">Entregue em '+fmtD(entry.data)+'</div>':'')
        +'</div>'
        +'</label>'
        +'<span style="font-size:11px;font-weight:600;color:'+(checked?'#3B6D11':'#ccc')+'">'+(checked?'✓':'—')+'</span>'
        +'</div>';
    }).join('');

    setModal('<div class="modal-bg"><div class="modal" style="max-width:480px;max-height:90vh;overflow-y:auto">'
      +'<div style="display:flex;align-items:center;gap:10px;margin-bottom:1rem;position:sticky;top:0;background:#fff;padding-bottom:.5rem;border-bottom:.5px solid #e0dfd8">'
      +'<div><div style="font-size:15px;font-weight:700">☑ Checklist SESMT — '+escHtml(c.nome||'')+'</div>'
      +'<div style="font-size:11px;color:#888">'+escHtml(c.cargo||'')+(c.re?' · RE '+c.re:'')+'</div></div>'
      +'<button class="btn" onclick="closeModal()" style="margin-left:auto;padding:3px 9px">✕</button>'
      +'</div>'
      +'<div style="background:#f9f9f7;border-radius:10px;padding:12px 14px;margin-bottom:1rem">'
      +'<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:6px">'
      +'<span style="font-weight:600">Documentação obrigatória (checklist)</span>'
      +'<span style="font-weight:700;color:'+corPct+'">'+stat.pct+'% ('+stat.entregues+'/'+stat.total+')</span>'
      +'</div>'
      +'<div style="background:#e0dfd8;border-radius:20px;height:8px;overflow:hidden">'
      +'<div id="doc-prog-bar" style="background:'+corPct+';width:'+stat.pct+'%;height:100%;border-radius:20px;transition:width .4s"></div>'
      +'</div>'
      +'<div style="font-size:10px;color:#aaa;margin-top:4px">Arquivos do Dossiê: use “Ver todos os documentos”.</div>'
      +'</div>'
      +'<div id="doc-lista-inner">'+itens+'</div>'
      +'<div style="margin-top:1rem;position:sticky;bottom:0;background:#fff;padding-top:.5rem;border-top:.5px solid #e0dfd8;display:flex;gap:8px">'
      +'<button class="btn" onclick="evolVerTodosDocumentos(\''+evolEscId(colabId)+'\')" style="flex:1">Ver todos os documentos</button>'
      +'<button class="btn btn-pri" onclick="closeModal()" style="flex:1">Fechar</button>'
      +'</div>'
      +'</div></div>');
  });
}

function evolToggleDoc(colabId, docId){
  if(!_colabDocs[colabId]) _colabDocs[colabId]={};
  var ck = document.getElementById('doc-ck-'+docId);
  var entregue = ck ? ck.checked : false;
  var hoje = dataHojeLocal();
  var entry = _colabDocs[colabId][docId] || {};
  var idExistente = entry.id || null;
  _colabDocs[colabId][docId] = {
    entregue: entregue,
    data: entregue ? hoje : (entry.data||''),
    obs: entry.obs||'',
    id: idExistente
  };
  if(!DEMO){
    if(idExistente){
      sbUpdate('sesmt_documentos_colab',
        {entregue:entregue, data_entrega: entregue ? hoje : null},
        'id=eq.'+idExistente
      );
    } else {
      sbUpsert('sesmt_documentos_colab',
        {colaborador_id:colabId, doc_id:docId, entregue:entregue,
         data_entrega: entregue ? hoje : null,
         criado_em:new Date().toISOString()},
        'colaborador_id,doc_id'
      ).then(function(res){
        if(res&&res[0]&&res[0].id) _colabDocs[colabId][docId].id=res[0].id;
      });
    }
  }
  var stat = docPct(colabId);
  var corPct = stat.pct===100?'#3B6D11':stat.pct>=60?'#185FA5':stat.pct>0?'#854F0B':'#A32D2D';
  var bar = document.getElementById('doc-prog-bar');
  if(bar){ bar.style.width=stat.pct+'%'; bar.style.background=corPct; }
  clearTimeout(window._docRenderTimer);
  window._docRenderTimer = setTimeout(function(){
    if(_evolUi.view==='ficha' && String(_evolUi.colabId)===String(colabId)) evolRenderFicha();
  },300);
}

function evolDocBloco(c){
  var docs = _colabDocs[c.id]||{};
  var stat = docPct(c.id);
  var corPct = stat.pct===100?'#3B6D11':stat.pct>=60?'#185FA5':stat.pct>0?'#854F0B':'#A32D2D';
  var faltam = DOCS_OBRIGATORIOS.filter(function(d){return d.obrigatorio&&!(docs[d.id]&&docs[d.id].entregue);});
  var dossie = evolDocsDossieDoColab(c);
  var totalDocs = dossie.length;
  var destaque = dossie.slice(0,3);
  return '<div style="background:#f9f9f7;border-radius:8px;padding:8px 10px;margin-bottom:.75rem">'
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;flex-wrap:wrap">'
    +'<span style="font-size:12px;font-weight:600;color:#555">📄 Documentação</span>'
    +'<span style="font-size:11px;font-weight:700;color:'+corPct+';margin-left:auto">'+stat.pct+'%</span>'
    +'<span style="font-size:10px;color:#888">checklist '+stat.entregues+'/'+stat.total+'</span>'
    +'</div>'
    +'<div style="background:#e0dfd8;border-radius:20px;height:5px;overflow:hidden;margin-bottom:6px">'
    +'<div style="background:'+corPct+';width:'+stat.pct+'%;height:100%;border-radius:20px;transition:width .4s"></div>'
    +'</div>'
    +(faltam.length&&stat.pct<100
      ?'<div style="font-size:10px;color:#854F0B">Pendentes checklist: '+faltam.map(function(d){return d.label;}).slice(0,3).join(', ')+(faltam.length>3?' +'+(faltam.length-3):'')+'</div>'
      :'<div style="font-size:10px;color:#3B6D11">✓ Checklist obrigatório completo</div>'
    )
    +'<div style="font-size:12px;margin-top:8px;font-weight:600;color:#185FA5">'+totalDocs+' documento'+(totalDocs===1?'':'s')+' no Dossiê</div>'
    +(function(){
      try{
        var dg = typeof evolDiagnosticarIntegracao==='function' ? evolDiagnosticarIntegracao(c.id) : null;
        var nPend = dg ? (dg.docSemSesmt||[]).length : 0;
        if(!nPend) return '';
        return '<div style="font-size:10px;color:#854F0B;margin-top:4px;font-weight:600">⚠ '+nPend+' doc. SESMT pendente(s) de integração · '
          +'<a href="#" onclick="event.preventDefault();evolAbrirDiagnosticoIntegracao(\''+evolEscId(c.id)+'\')" style="color:#854F0B">Verificar</a></div>';
      }catch(e){ return ''; }
    })()
    +(destaque.length
      ? '<div style="font-size:10px;color:#555;margin-top:4px">Recentes/relevantes: '
        +destaque.map(function(d){ return escHtml(d.tipo_documento||'Documento'); }).join(' · ')
        +'</div>'
      : '<div style="font-size:10px;color:#888;margin-top:4px">Nenhum arquivo no Dossiê Digital.</div>'
    )
    +'<div style="margin-top:8px">'
    +'<button class="btn btn-sm btn-pri" type="button" onclick="evolVerTodosDocumentos(\''+evolEscId(c.id)+'\')">Ver todos os documentos ('+totalDocs+')</button>'
    +'</div>'
    +'</div>';
}

function evolDocOrigemLabel(d){
  var o = String(d.origem||'');
  var ref = String(d.referencia_modulo||'');
  if(/ia_importacao|entrada.?inteligente/i.test(o) || /entrada_ia|rh_entrada/i.test(ref)) return 'Entrada Inteligente';
  if(/RH-2D|DOCUSIGN|RH-ASSINATURA/i.test(o+' '+ref)) return 'Assinatura / Dossiê';
  if(o) return o;
  if(ref) return ref;
  return 'Dossiê';
}

function evolDocsDedup(lista){
  var seen = {}, out = [];
  (lista||[]).forEach(function(d){
    var key = d.id || d.documento_final_id || (d.hash_sha256?('h:'+d.hash_sha256):null) || (d.referencia_id?('r:'+d.referencia_modulo+':'+d.referencia_id):null);
    if(!key) key = 't:'+String(d.tipo_documento||'')+':'+String(d.arquivo_nome||'')+':'+String(d.arquivo_url||'');
    if(seen[key]) return;
    seen[key] = true;
    out.push(d);
  });
  return out;
}

function evolVerTodosDocumentos(colabId){
  var c = (colaboradores||[]).find(function(x){ return String(x.id)===String(colabId); })||{};
  var dossie = evolDocsDedup(evolDocsDossieDoColab(c));
  var rows = dossie.map(function(d){
    var st = d.status || (d.validado_em?'Validado':'—');
    var dt = (d.data_emissao||d.criado_em||d.atualizado_em||'');
    if(dt) dt = String(dt).slice(0,10);
    var abrir = '';
    if(typeof rhDocEhAssinaturaDigital==='function' && rhDocEhAssinaturaDigital(d)){
      abrir = rhDocLinkArquivoHtml(d, 'Abrir');
    } else if(d.arquivo_url){
      abrir = '<a class="btn btn-sm" href="'+escHtml(d.arquivo_url)+'" target="_blank" rel="noopener">Abrir</a>';
    } else {
      abrir = '<span style="color:#aaa;font-size:11px">Sem arquivo</span>';
    }
    return '<tr>'
      +'<td>'+escHtml(d.tipo_documento||'—')+'</td>'
      +'<td>'+escHtml(d.arquivo_nome||d.tipo_documento||'—')+'</td>'
      +'<td>'+(dt?fmtD(dt):'—')+'</td>'
      +'<td>'+escHtml(st)+'</td>'
      +'<td>'+escHtml(evolDocOrigemLabel(d))+'</td>'
      +'<td>'+abrir+'</td>'
      +'</tr>';
  }).join('') || '<tr><td colspan="6" style="padding:1rem;text-align:center;color:#888">Nenhum documento no Dossiê.</td></tr>';

  setModal('<div class="modal-bg"><div class="modal" style="max-width:860px;max-height:90vh;overflow:auto">'
    +'<div style="display:flex;align-items:center;gap:10px;margin-bottom:12px">'
    +'<div><div style="font-size:15px;font-weight:700">DOCUMENTOS — '+escHtml(c.nome||'')+(c.re?' — RE '+escHtml(c.re):'')+'</div>'
    +'<div style="font-size:11px;color:#888">'+dossie.length+' documento(s) · fonte: rh_colaborador_documentos</div></div>'
    +'<button class="btn" onclick="closeModal()" style="margin-left:auto">✕</button></div>'
    +'<div style="overflow-x:auto"><table class="tbl" style="font-size:12px"><thead><tr>'
    +'<th>Tipo</th><th>Documento</th><th>Data</th><th>Situação</th><th>Origem</th><th>Ação</th>'
    +'</tr></thead><tbody>'+rows+'</tbody></table></div>'
    +'<div style="margin-top:12px;text-align:right"><button class="btn btn-pri" onclick="closeModal()">Fechar</button></div>'
    +'</div></div>');
}

function evolDocDossieResumoHtml(c, checklist){
  // Mantido por compatibilidade; o bloco principal usa resumo + modal.
  // Reflete no checklist só documento ativo/validado do colaborador com doc_id_sesmt correto.
  var dossie = evolDocsDossieDoColab(c);
  if(!dossie.length) return '';
  dossie.forEach(function(d){
    if(d.ativo===false) return;
    var st = String(d.status||'').toLowerCase();
    if(/recus|rejeit|inativ|cancel|substitu/.test(st)) return;
    var okStatus = !st || /valid|entreg|aceit|aprov/.test(st) || !!d.validado_em;
    if(!okStatus) return;
    var sid = d.doc_id_sesmt;
    if(!sid && typeof rhIaDocIdSesmt==='function') sid = rhIaDocIdSesmt(d.tipo_documento);
    if(sid && checklist && !(checklist[sid]&&checklist[sid].entregue)){
      checklist[sid] = {entregue:true, data:(d.data_emissao||'').toString().slice(0,10), obs:'Dossiê validado', id:null};
    }
  });
  return '';
}

function evolRegistrarASO(colabId){
  var c=colaboradores.find(function(x){return x.id===colabId;})||{};
  var hoje=dataHojeLocal();
  var d1=new Date(); d1.setFullYear(d1.getFullYear()+1);
  var prox=d1.getFullYear()+'-'+String(d1.getMonth()+1).padStart(2,'0')+'-'+String(d1.getDate()).padStart(2,'0');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:420px">'
    +'<h3 style="margin-bottom:1rem">🩺 Registrar ASO / Exame Ocupacional</h3>'
    +'<div style="font-size:12px;font-weight:500;color:#185FA5;background:#E6F1FB;border-radius:7px;padding:7px 12px;margin-bottom:.85rem">'
    +escHtml(c.nome||'')+(c.cargo?' \u00b7 '+escHtml(c.cargo):'')+'</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:1rem">'
    +'<div class="fg" style="grid-column:span 2"><label style="font-size:11px">Tipo do exame</label>'
    +'<select class="inp" id="aso-tipo" style="width:100%">'
    +'<option>Peri\u00f3dico</option><option>Admissional</option><option>Demissional</option>'
    +'<option>Retorno ao trabalho</option><option>Mudan\u00e7a de fun\u00e7\u00e3o</option><option>Monitora\u00e7\u00e3o pontual</option>'
    +'</select></div>'
    +'<div class="fg"><label style="font-size:11px">Data do exame *</label>'
    +'<input class="inp" type="date" id="aso-data" value="'+hoje+'" style="width:100%"/></div>'
    +'<div class="fg"><label style="font-size:11px">Pr\u00f3ximo exame (validade)</label>'
    +'<input class="inp" type="date" id="aso-val" value="'+prox+'" style="width:100%"/></div>'
    +'<div class="fg"><label style="font-size:11px">Resultado</label>'
    +'<select class="inp" id="aso-resultado" style="width:100%">'
    +'<option>Apto</option><option>Apto com restri\u00e7\u00e3o</option><option>Inapto tempor\u00e1rio</option><option>Inapto definitivo</option>'
    +'</select></div>'
    +'<div class="fg"><label style="font-size:11px">M\u00e9dico</label>'
    +'<input class="inp" id="aso-medico" style="width:100%" placeholder="Nome do m\u00e9dico"/></div>'
    +'<div class="fg" style="grid-column:span 2"><label style="font-size:11px">Cl\u00ednica / Hospital</label>'
    +'<input class="inp" id="aso-clinica" style="width:100%" placeholder="Nome da cl\u00ednica"/></div>'
    +'<div class="fg" style="grid-column:span 2"><label style="font-size:11px">Observa\u00e7\u00f5es</label>'
    +'<textarea class="inp" id="aso-obs" style="width:100%;height:50px;resize:vertical" placeholder="Restri\u00e7\u00f5es, encaminhamentos..."></textarea></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="aso-salvar" style="flex:2">Registrar ASO</button>'
    +'</div></div></div>');
  setTimeout(function(){
    var btn=document.getElementById('aso-salvar');
    if(!btn)return;
    btn.onclick=function(){
      var tipo=(document.getElementById('aso-tipo')||{}).value||'Peri\u00f3dico';
      var data=(document.getElementById('aso-data')||{}).value||hoje;
      var val =(document.getElementById('aso-val')||{}).value||prox;
      var res =(document.getElementById('aso-resultado')||{}).value||'Apto';
      var med =(document.getElementById('aso-medico')||{}).value||'';
      var cli =(document.getElementById('aso-clinica')||{}).value||'';
      var obs =(document.getElementById('aso-obs')||{}).value||'';
      if(!data){progShowToast('\u26a0 Informe a data do exame.');return;}
      var colId=sesmtTreinamentoColabId(colabId);
      if(!colId){progShowToast('\u26a0 Colaborador n\u00e3o encontrado no cadastro.','erro');return;}
      var novo={id:'aso'+Date.now(),funcionario_id:colId,
        nr:'ASO',titulo:'ASO '+tipo,val:val,validade:val,
        data_emissao:data,resultado:res,medico:med,clinica:cli,
        observacoes:obs,tipo_aso:tipo,criado_em:new Date().toISOString()};
      treinamentos.push(novo);
      if(!DEMO)sbInsert('treinamentos',Object.assign({},novo,{id:undefined}));
      closeModal(); renderEvolucao();
      progShowToast('\u2705 ASO registrado \u2014 '+escHtml(c.nome||'')+' \u00b7 '+tipo+' \u00b7 '+res);
    };
  },50);
}

// ── APTIDÃO AO TRABALHO ──────────────────────────────────────────────

function renderSesmtAptidao(){
  var pg = document.getElementById('pg-sesmt-aptidao'); if(!pg) return;
  var sel = document.getElementById('apt-fil-contrato');
  if(sel){
    sel.innerHTML = '<option value="">Todos os contratos</option>'
      + contratos.map(function(c){ return '<option value="'+c.id+'">'+c.nome+'</option>'; }).join('');
  }
  var go = function(){ renderAptidao(); };
  if(!DEMO){
    Promise.all([
      !_cad_cursos.length ? sbFetch('sesmt_cursos',{filters:['status=eq.Ativo'],order:'sigla.asc'}).catch(function(){ return []; }) : Promise.resolve(null),
      !_trilhasCarregado ? sbFetch('sesmt_trilha_cargo',{filters:['ativo=eq.true']}).catch(function(){ return []; }) : Promise.resolve(null),
      !_cad_cargos.length ? sbFetch('cargos',{filters:['ativo=eq.true'],order:'nome.asc'}).catch(function(){ return []; }) : Promise.resolve(null)
    ]).then(function(r){
      if(r[0]&&r[0].length) _cad_cursos=r[0];
      if(r[1]&&r[1].length){ _trilhas=r[1]; _trilhasCarregado=true; }
      if(r[2]&&r[2].length) _cad_cargos=r[2];
      go();
    }).catch(go);
  } else go();
}

function renderAptidao(){
  var lista = document.getElementById('apt-lista'); if(!lista) return;
  var filtCont  = (document.getElementById('apt-fil-contrato')||{}).value||'';
  var filtStatus= (document.getElementById('apt-fil-status')||{}).value||'';
  var filtBusca = ((document.getElementById('apt-fil-busca')||{}).value||'').toLowerCase();

  var cols = colaboradores.filter(function(c){
    if(c.ativo===false) return false;
    if(filtCont && c.contrato_id!==filtCont) return false;
    if(filtBusca && !(c.nome||'').toLowerCase().includes(filtBusca)) return false;
    return true;
  });

  var dados = cols.map(function(c){ return calcularAptidao(c); });
  if(filtStatus) dados = dados.filter(function(d){ return d.status===filtStatus; });

  var metr = document.getElementById('apt-metricas');
  if(metr){
    var aptos = dados.filter(function(d){ return d.status==='Apto'; }).length;
    var bloq  = dados.filter(function(d){ return d.status==='Bloqueado'; }).length;
    var pend  = dados.filter(function(d){ return d.status!=='Apto'&&d.status!=='Bloqueado'; }).length;
    metr.innerHTML = [
      {l:'✅ Aptos para trabalho', v:aptos, c:'#3B6D11', bg:'#EAF3DE'},
      {l:'⏳ Com pendências',      v:pend,  c:'#854F0B', bg:'#FFF3E0'},
      {l:'🚫 Bloqueados',          v:bloq,  c:'#A32D2D', bg:'#FEE8E8'},
    ].map(function(m){
      return '<div style="background:'+m.bg+';border:.5px solid '+m.c+'44;border-radius:10px;padding:1rem;text-align:center">'
        +'<div style="font-size:12px;color:'+m.c+';font-weight:600;margin-bottom:4px">'+m.l+'</div>'
        +'<div style="font-size:28px;font-weight:700;color:'+m.c+'">'+m.v+'</div></div>';
    }).join('');
  }

  if(!dados.length){
    lista.innerHTML='<div style="padding:2rem;text-align:center;color:#aaa">Nenhum resultado.</div>';
    return;
  }

  var thFixas = MOB_ETAPAS.map(function(e){
    return '<th style="text-align:center;font-size:10px;white-space:nowrap">'+e.icon+'<br>'+e.label+'</th>';
  }).join('');
  var thCursos = APT_CURSOS_COLUNAS.map(function(c){
    return '<th style="text-align:center;font-size:10px;white-space:nowrap" title="'+escHtml(c.label)+'">🎓<br>'+escHtml(c.short)+'</th>';
  }).join('');

  lista.innerHTML = '<div style="font-size:11px;color:#666;margin-bottom:6px;padding:0 4px">'
    +'<span style="margin-right:12px">✓ OK</span><span style="margin-right:12px">✗ Pendente</span>'
    +'<span style="margin-right:12px">⚠ Vencido</span><span style="margin-right:12px">N/A Não se aplica ao cargo</span>'
    +'<span style="color:#888">— Aptidão % considera só itens aplicáveis (N/A não bloqueia)</span></div>'
    +'<div class="card"><div class="tbl-sticky-wrap"><table class="tbl tbl-sticky"><thead><tr>'
    +'<th style="min-width:140px">Colaborador</th><th>Cargo</th><th>Contrato</th>'
    +thFixas+thCursos
    +'<th>Status</th><th>Aptidão</th></tr></thead><tbody>'
    +dados.map(function(d){
      var c = d.colaborador;
      var cont = contratos.find(function(x){ return x.id===c.contrato_id; });
      var corStatus = {Apto:'#3B6D11','Em mobilização':'#185FA5',Pendente:'#854F0B',Bloqueado:'#A32D2D'}[d.status]||'#888';
      return '<tr>'
        +'<td style="font-weight:600;color:#1a1a18">'+escHtml(c.nome)+'</td>'
        +'<td style="font-size:11px;font-weight:500;color:#333">'+escHtml(c.cargo||'—')+'</td>'
        +'<td style="font-size:11px;font-weight:500;color:#333">'+(cont?escHtml(cont.codigo||cont.nome):'—')+'</td>'
        +MOB_ETAPAS.map(function(e){ return '<td style="text-align:center">'+aptCelulaEtapaHtml(d.etapas[e.id])+'</td>'; }).join('')
        +APT_CURSOS_COLUNAS.map(function(col){ return '<td style="text-align:center">'+aptCelulaCursoHtml(d.cursos[col.id])+'</td>'; }).join('')
        +'<td><span style="background:'+corStatus+'20;color:'+corStatus+';border:.5px solid '+corStatus+'55;border-radius:5px;padding:2px 8px;font-size:11px;font-weight:600;white-space:nowrap">'+d.status+'</span></td>'
        +'<td style="text-align:center;font-weight:600;color:'+corStatus+'">'+d.pct+'%</td>'
        +'</tr>';
    }).join('')
    +'</tbody></table></div></div>';
}

// ── MOBILIZAÇÃO (visão por contrato) ─────────────────────────────────
function renderMobilizacao(){
  // Popular select de contratos (uma vez), preservando seleção
  var selC=document.getElementById('mob-fil-contrato');
  if(selC){
    var comColab={};
    colaboradores.forEach(function(c){ if(c.ativo!==false && c.contrato_id) comColab[c.contrato_id]=true; });
    var listaCont=(contratos||[]).filter(function(ct){ return comColab[ct.id]; })
      .sort(function(a,b){ return (a.nome||'').localeCompare(b.nome||'','pt-BR'); });
    if(selC.options.length-1 !== listaCont.length){
      var cur=selC.value;
      selC.innerHTML='<option value="">Todos os contratos</option>'
        +listaCont.map(function(ct){ return '<option value="'+ct.id+'">'+escHtml(ct.nome||ct.codigo||ct.id)+'</option>'; }).join('');
      selC.value=cur;
    }
  }
  var filtCont=(document.getElementById('mob-fil-contrato')||{}).value||'';
  var filtStatus=(document.getElementById('mob-fil-status')||{}).value||'';
  var filtBusca=((document.getElementById('mob-fil-busca')||{}).value||'').toLowerCase();

  var cols=colaboradores.filter(function(c){
    if(c.ativo===false) return false;
    if(filtCont && c.contrato_id!==filtCont) return false;
    if(filtBusca && !((c.nome||'').toLowerCase().includes(filtBusca) || String(c.re||'').indexOf(filtBusca)>=0)) return false;
    return true;
  });
  var dados=cols.map(function(c){ return calcularAptidao(c); });
  if(filtStatus) dados=dados.filter(function(d){ return d.status===filtStatus; });

  // Métricas
  var metr=document.getElementById('mob-metricas');
  if(metr){
    var total=dados.length;
    var aptos=dados.filter(function(d){return d.status==='Apto';}).length;
    var emMob=dados.filter(function(d){return d.status==='Em mobilização';}).length;
    var pend =dados.filter(function(d){return d.status==='Pendente';}).length;
    var bloq =dados.filter(function(d){return d.status==='Bloqueado';}).length;
    metr.innerHTML=[
      {l:'👥 Total',v:total,c:'#185FA5',bg:'#EBF4FD'},
      {l:'✅ Aptos',v:aptos,c:'#3B6D11',bg:'#EAF3DE'},
      {l:'🚀 Em mobilização',v:emMob,c:'#185FA5',bg:'#EBF4FD'},
      {l:'⏳ Pendentes',v:pend,c:'#854F0B',bg:'#FFF3E0'},
      {l:'🚫 Bloqueados',v:bloq,c:'#A32D2D',bg:'#FEE8E8'}
    ].map(function(m){
      return '<div style="background:'+m.bg+';border:.5px solid '+m.c+'44;border-radius:10px;padding:.6rem;text-align:center">'
        +'<div style="font-size:11px;color:'+m.c+';font-weight:600;margin-bottom:2px">'+m.l+'</div>'
        +'<div style="font-size:22px;font-weight:700;color:'+m.c+'">'+m.v+'</div></div>';
    }).join('');
  }

  var lista=document.getElementById('mob-lista'); if(!lista) return;
  if(!dados.length){ lista.innerHTML='<div style="padding:2rem;text-align:center;color:#aaa">Nenhum colaborador para o filtro.</div>'; return; }

  // Agrupar por contrato (contrato como eixo principal)
  var grupos={};
  dados.forEach(function(d){ var k=d.colaborador.contrato_id||'(sem)'; (grupos[k]||(grupos[k]=[])).push(d); });
  var corMap={Apto:'#3B6D11','Em mobilização':'#185FA5',Pendente:'#854F0B',Bloqueado:'#A32D2D'};
  lista.innerHTML=Object.keys(grupos).sort(function(a,b){
    var na=(contratos.find(function(x){return x.id===a;})||{}).nome||'zzz';
    var nb=(contratos.find(function(x){return x.id===b;})||{}).nome||'zzz';
    return na.localeCompare(nb,'pt-BR');
  }).map(function(k){
    var cont=contratos.find(function(x){return x.id===k;});
    var nome=cont?(cont.nome||cont.codigo):'Sem contrato';
    var arr=grupos[k].sort(function(a,b){ return a.pct-b.pct; }); // menos prontos primeiro
    var aptosG=arr.filter(function(d){return d.status==='Apto';}).length;
    var linhas=arr.map(function(d){
      var c=d.colaborador; var cor=corMap[d.status]||'#888';
      return '<tr>'
        +'<td style="font-weight:600;color:#1a1a18">'+escHtml(c.nome)+(c.re?' <span style="color:#888;font-weight:400;font-size:11px">RE '+escHtml(String(c.re))+'</span>':'')+'</td>'
        +'<td style="font-weight:500;color:#333">'+escHtml(c.cargo||'—')+'</td>'
        +'<td><span style="background:'+cor+'20;color:'+cor+';border:.5px solid '+cor+'55;border-radius:5px;padding:2px 8px;font-size:11px;font-weight:600;white-space:nowrap">'+d.status+'</span></td>'
        +'<td style="min-width:120px"><div style="background:#eee;border-radius:6px;height:8px;overflow:hidden"><div style="width:'+d.pct+'%;height:100%;background:'+cor+'"></div></div><div style="font-size:10px;color:'+cor+';font-weight:700;margin-top:2px">'+d.pct+'%</div></td>'
        +'<td style="font-size:11px">'+(d.pendencias.length?'<span style="color:#A32D2D">'+escHtml(d.pendencias.slice(0,2).join('; '))+(d.pendencias.length>2?' +'+(d.pendencias.length-2):'')+'</span>':'<span style="color:#3B6D11;font-weight:600">OK</span>')+'</td>'
        +'<td><button class="btn btn-sm" onclick="openMobilizacaoDetalhe(\''+c.id+'\')">📋 Detalhes</button></td>'
        +'</tr>';
    }).join('');
    return '<div class="card" style="margin-bottom:1rem">'
      +'<div class="ch"><span class="ct">🏢 '+escHtml(nome)+' <span style="color:#888;font-weight:400;font-size:12px">('+arr.length+' colab · '+aptosG+' aptos)</span></span></div>'
      +'<div class="tbl-sticky-wrap"><table class="tbl tbl-sticky" style="font-size:12px"><thead><tr>'
      +'<th>Colaborador</th><th>Cargo</th><th>Status</th><th>Progresso</th><th>Pendências</th><th></th></tr></thead><tbody>'
      +linhas+'</tbody></table></div></div>';
  }).join('');
}

// ── MODAIS ───────────────────────────────────────────────────────────

function openMobilizacaoDetalhe(colabId){
  var c = colaboradores.find(function(x){ return x.id===colabId; }); if(!c) return;
  var apt = calcularAptidao(c);
  var cont = contratos.find(function(x){ return x.id===c.contrato_id; });
  var hoje = dataHoje();
  var meusTreinAll = typeof treinDoColaborador==='function'?treinDoColaborador(colabId):treinamentos.filter(function(t){ return String(t.funcionario_id)===String(colabId) && !t.deleted_at; });
  var meusTrein = typeof treinDedupPorFamilia==='function'?treinDedupPorFamilia(meusTreinAll, hoje):meusTreinAll;
  var meusEpis  = epis.filter(function(e){ return e.responsavel_id===colabId; });

  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:560px;max-height:90vh;overflow-y:auto">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">'
    +'<h3 style="margin:0">📋 '+c.nome+'</h3>'
    +'<button onclick="closeModal()" style="background:none;border:none;font-size:20px;cursor:pointer">✕</button>'
    +'</div>'
    +'<div style="font-size:12px;color:#888;margin-bottom:1rem">'+c.cargo+(cont?' · '+cont.codigo:'')+'</div>'

    // Status geral
    +'<div style="background:'+({'Apto':'#EAF3DE','Bloqueado':'#FEE8E8'}[apt.status]||'#FFF3E0')+';border-radius:8px;padding:.75rem 1rem;margin-bottom:1rem;display:flex;align-items:center;gap:10px">'
    +'<span style="font-size:28px">'+({'Apto':'✅','Bloqueado':'🚫','Pendente':'⏳','Em mobilização':'🚀'}[apt.status]||'⏳')+'</span>'
    +'<div><div style="font-size:14px;font-weight:700">'+apt.status+'</div>'
    +'<div style="font-size:12px;color:#555">'+apt.etapasConcluidas+'/'+apt.totalAplicaveis+' itens aplicáveis · '+apt.pct+'% concluído</div></div>'
    +'</div>'

    // Checklist de etapas
    +'<div style="margin-bottom:1rem">'
    +'<div style="font-size:12px;font-weight:700;margin-bottom:.5rem">Checklist de aptidão</div>'
    +'<div style="font-size:10px;color:#888;margin-bottom:.5rem">Use <b>N/A</b> quando a etapa não se aplica (ex.: EPI/Uniforme). Isso reflete na Aptidão e não bloqueia o status Apto.</div>'
    +MOB_ETAPAS.map(function(e){
      var st = apt.etapas[e.id];
      var isNa = st==='na';
      var ok = st===true;
      var cid=String(colabId).replace(/'/g,"\\'");
      var eid=String(e.id).replace(/'/g,"\\'");
      return '<div style="display:flex;align-items:center;gap:8px;padding:.4rem 0;border-bottom:.5px solid #f5f5f3">'
        +'<span style="font-size:20px">'+(isNa?'➖':(ok?'✅':'⭕'))+'</span>'
        +'<div style="flex:1"><div style="font-size:13px;font-weight:500">'+e.icon+' '+e.label+'</div>'
        +'<div style="font-size:11px;color:#aaa">'+e.desc+'</div></div>'
        +'<span style="font-size:11px;font-weight:600;color:'+(isNa?'#888':(ok?'#3B6D11':'#A32D2D'))+'">'+(isNa?'N/A':(ok?'Concluído':'Pendente'))+'</span>'
        +'<button class="btn btn-sm" onclick="event.stopPropagation();aptToggleEtapaNa(\''+cid+'\',\''+eid+'\')" style="font-size:10px;padding:2px 8px;'+(isNa?'color:#185FA5;border-color:#185FA5':'color:#888')+'" title="'+(isNa?'Voltar a exigir esta etapa':'Marcar como não se aplica')+'">'+(isNa?'↩ Exigir':'N/A')+'</button>'
        +'</div>';
    }).join('')
    +(function(){
      var lista=(typeof aptCursosDaTrilha==='function'?aptCursosDaTrilha(c):[]);
      if(!lista.length) return '';
      var cid=String(colabId).replace(/'/g,"\\'");
      return '<div style="font-size:12px;font-weight:700;margin:.75rem 0 .35rem">Cursos da trilha do cargo</div>'
        +'<div style="font-size:10px;color:#888;margin-bottom:.4rem">N/A libera este colaborador daquele curso (exceção da trilha). Não altera a trilha dos demais.</div>'
        +lista.map(function(cur){
          var isNa=typeof aptCursoEhNa==='function' && aptCursoEhNa(c, cur.id);
          var st=isNa?'na':(typeof aptStatusCurso==='function'?aptStatusCurso(c.id,{match:[cur.sigla,cur.nome],label:cur.nome},true):'pendente');
          var lbl=isNa?'N/A':st==='ok'?'Concluído':st==='vencido'?'Vencido':'Pendente';
          var cor=isNa?'#888':st==='ok'?'#3B6D11':st==='vencido'?'#854F0B':'#A32D2D';
          var kid=String(cur.id||'').replace(/'/g,"\\'");
          return '<div style="display:flex;align-items:center;gap:8px;padding:.35rem 0;border-bottom:.5px solid #f5f5f3">'
            +'<span style="font-size:16px">'+(isNa?'➖':st==='ok'?'✅':st==='vencido'?'⚠️':'⭕')+'</span>'
            +'<div style="flex:1;font-size:12px;font-weight:500">🎓 '+escHtml((cur.sigla?cur.sigla+' — ':'')+(cur.nome||''))+'</div>'
            +'<span style="font-size:11px;font-weight:600;color:'+cor+'">'+lbl+'</span>'
            +(cur.id?'<button class="btn btn-sm" onclick="event.stopPropagation();aptToggleCursoNa(\''+cid+'\',\''+kid+'\')" style="font-size:10px;padding:2px 8px;'+(isNa?'color:#185FA5;border-color:#185FA5':'color:#888')+'" title="'+(isNa?'Voltar a exigir este curso':'Não se aplica a este colaborador')+'">'+(isNa?'↩ Exigir':'N/A')+'</button>':'')
            +'</div>';
        }).join('');
    })()
    +'</div>'

    // Treinamentos
    +(meusTrein.length?'<div style="margin-bottom:1rem"><div style="font-size:12px;font-weight:700;margin-bottom:.5rem">🎓 Treinamentos</div>'
      +meusTrein.map(function(t){
        var v = t.val||t.validade; var ok = !v || (v&&v>=hoje);
        return '<div style="display:flex;justify-content:space-between;padding:4px 0;font-size:12px;border-bottom:.5px solid #f5f5f3">'
          +'<span>'+t.nr+' — '+t.titulo+'</span>'
          +'<span style="color:'+(ok?'#3B6D11':'#A32D2D')+'">'+(ok?'✓ Válido':'✗ Vencido')+(v?' ('+fmtD(v)+')':'')+'</span></div>';
      }).join('')+'</div>':'')

    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Fechar</button>'
    +'<button class="btn btn-pri" onclick="closeModal();openLancarTreinamento(\''+colabId+'\',\'INTEGRA\')" style="flex:1">🧭 Integração</button>'
    +'<button class="btn" onclick="closeModal();openLancarEtapa(\''+colabId+'\')" style="flex:1">+ Etapa</button>'
    +'</div>'
    +'</div></div>');
}

function openLancarEtapa(colabId){
  var c = colaboradores.find(function(x){ return x.id===colabId; }); if(!c) return;
  var etapaOpts = MOB_ETAPAS.map(function(e){
    return '<option value="'+e.id+'">'+e.icon+' '+e.label+'</option>';
  }).join('');

  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:420px">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">'
    +'<h3 style="margin:0">🚀 Lançar etapa</h3>'
    +'<button onclick="closeModal()" style="background:none;border:none;font-size:20px;cursor:pointer">✕</button>'
    +'</div>'
    +'<div style="font-size:13px;color:#555;margin-bottom:1rem">Colaborador: <strong>'+c.nome+'</strong></div>'
    +'<div style="display:flex;flex-direction:column;gap:.75rem;margin-bottom:1rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Etapa *</label>'
    +'<select class="inp" id="etapa-tipo" style="width:100%">'+etapaOpts+'</select></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Data</label>'
    +'<input class="inp" id="etapa-data" type="date" value="'+dataHoje()+'" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Observação</label>'
    +'<textarea class="inp" id="etapa-obs" style="width:100%;height:60px" placeholder="Opcional..."></textarea></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="salvarEtapaMobilizacao(\''+colabId+'\')" style="flex:1">💾 Salvar</button>'
    +'</div></div></div>');
}

function salvarEtapaMobilizacao(colabId){
  var etapa = (document.getElementById('etapa-tipo')||{}).value||'';
  var data  = (document.getElementById('etapa-data')||{}).value||'';
  var obs   = (document.getElementById('etapa-obs')||{}).value||'';
  if(!etapa) return;

  // Etapas fixas (docs, aso, epi, uniforme) — integração é curso INTEGRA na trilha
  var c = colaboradores.find(function(x){ return x.id===colabId; });
  if(!c) return;

  var etapaLbl = (MOB_ETAPAS.find(function(e){ return e.id===etapa; })||{}).label||etapa;
  closeModal();
  progShowToast('ℹ️ Para registrar integração use Evolução → 🧭 + Integração ou + Treinamento (curso INTEGRA). Etapa "'+etapaLbl+'" registrada localmente.');
  renderMobilizacao();
  if(typeof renderAptidao==='function') renderAptidao();
}

function _treinCalcValidade(dataReal, meses){
  if(!dataReal||!meses) return '';
  var d = new Date(dataReal); d.setMonth(d.getMonth()+parseInt(meses));
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
function _treinOnCursoChange(){
  var sel = document.getElementById('trein-curso-id'); if(!sel) return;
  var cur = (_cad_cursos||[]).find(function(x){return x.id===sel.value;});
  if(!cur) return;
  var nr = document.getElementById('trein-nr');
  var titulo = document.getElementById('trein-titulo');
  var data = document.getElementById('trein-data');
  var val = document.getElementById('trein-validade');
  if(nr) nr.value = cur.sigla||'';
  if(titulo) titulo.value = cur.nome||'';
  var naoVence=typeof cadCursoNaoVence==='function' && cadCursoNaoVence(cur);
  if(val){
    val.disabled=!!naoVence;
    if(naoVence){ val.value=''; val.title='Este curso não vence'; }
    else {
      val.title='';
      if((cur.validade_controlada||cur.periodicidade) && data && data.value && !val.value){
        val.value = _treinCalcValidade(data.value, cur.periodicidade);
      }
    }
  }
}
function openLancarTreinamento(colabId, preSigla){
  var c = colaboradores.find(function(x){ return x.id===colabId; }); if(!c) return;
  if(!_cad_cursos.length && !DEMO && !_cursosTentouCarregar){
    _cursosTentouCarregar=true;
    sbFetch('sesmt_cursos',{order:'nome.asc'}).then(function(rows){
      if(rows&&rows.length) _cad_cursos=rows;
      openLancarTreinamento(colabId, preSigla);
    }).catch(function(){ openLancarTreinamento(colabId, preSigla); });
    return;
  }
  var nrs = (MOB_NRS_CARGO[c.cargo]||MOB_NRS_CARGO['_default']);
  var cursos = (_cad_cursos||[]).filter(function(x){return x.status!=='Inativo';});
  var preId = '';
  if(preSigla){
    var pc = cursos.find(function(x){ return aptNormSig(x.sigla)===aptNormSig(preSigla); });
    if(pc) preId = pc.id;
  }
  var aptCursos = aptCursosAplicaveis(c);
  var cursoOpts = '<option value="">— Selecione um curso —</option>'
    + cursos.map(function(cur){
        var obrig = nrs.some(function(n){return (cur.sigla||'').toUpperCase().startsWith(n.replace('-','').toUpperCase())||cur.sigla===n;});
        var naTrilha = aptCursos.some(function(ac){ return ac.id && ac.id===cur.id || aptNormSig(ac.sigla)===aptNormSig(cur.sigla); });
        var isIntegra = aptNormSig(cur.sigla)===aptNormSig(APT_SIGLA_INTEGRA);
        var sel = cur.id===preId ? ' selected' : '';
        return '<option value="'+cur.id+'"'+sel+(obrig||isIntegra?' style="font-weight:700;color:#185FA5"':'')+'>'
          +escHtml(cur.sigla||'')+(obrig||isIntegra?' ★':'')+(naTrilha&&!isIntegra?'':'')+' — '+escHtml(cur.nome)+'</option>';
      }).join('');
  var hintIntegra = preSigla && aptNormSig(preSigla)===aptNormSig(APT_SIGLA_INTEGRA)
    ? '<div style="background:#F0EBF8;border-radius:8px;padding:.5rem .75rem;font-size:11px;color:#533AB7;margin-bottom:.75rem">🧭 Registro de <b>Integração ao contrato</b> — curso obrigatório na trilha do cargo (última etapa).</div>'
    : '<div style="background:#EBF4FD;border-radius:8px;padding:.5rem .75rem;font-size:11px;color:#185FA5;margin-bottom:.75rem">★ = obrigatório para o cargo · 🧭 Integração = curso <b>INTEGRA</b></div>';
  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:440px">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">'
    +'<h3 style="margin:0">🎓 Registrar treinamento</h3>'
    +'<button onclick="closeModal()" style="background:none;border:none;font-size:20px;cursor:pointer">✕</button>'
    +'</div>'
    +'<div style="font-size:13px;color:#555;margin-bottom:1rem">'+c.nome+' · '+c.cargo+'</div>'
    +hintIntegra
    +'<div style="display:flex;flex-direction:column;gap:.75rem;margin-bottom:1rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Curso *</label>'
    +'<select class="inp" id="trein-curso-id" style="width:100%" onchange="_treinOnCursoChange()">'+cursoOpts+'</select></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.75rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Sigla / NR</label>'
    +'<input class="inp" id="trein-nr" style="width:100%" placeholder="Ex: NR-10"/></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Título</label>'
    +'<input class="inp" id="trein-titulo" style="width:100%" placeholder="Preenchido ao selecionar"/></div>'
    +'</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.75rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Data realização</label>'
    +'<input class="inp" id="trein-data" type="date" value="'+dataHoje()+'" style="width:100%" onchange="_treinOnCursoChange()"/></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Validade</label>'
    +'<input class="inp" id="trein-validade" type="date" style="width:100%"/></div>'
    +'</div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Instituição</label>'
    +'<input class="inp" id="trein-inst" style="width:100%" placeholder="Nome da empresa/instrutor"/></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="salvarTreinamentoMob(\''+colabId+'\')" style="flex:1">💾 Salvar</button>'
    +'</div></div></div>');
  if(preId) setTimeout(function(){ _treinOnCursoChange(); }, 40);
}

function salvarTreinamentoMob(colabId){
  var g = function(id){ return (document.getElementById(id)||{}).value||''; };
  var nr = g('trein-nr'); var titulo = g('trein-titulo').trim();
  if(!titulo){ alert('Informe o título.'); return; }
  var colId = sesmtTreinamentoColabId(colabId);
  if(!colId){ progShowToast('⚠ Colaborador não encontrado no cadastro.','erro'); return; }
  var novo = {
    funcionario_id: colId,
    nr: nr, titulo: titulo,
    val: g('trein-validade'), validade: g('trein-validade'),
    data: g('trein-data'),
    instituicao: g('trein-inst')
  };
  treinamentos.push(Object.assign({id:'t'+Date.now()}, novo));
  if(!DEMO) sbInsert('treinamentos', novo).catch(function(){});
  closeModal();
  progShowToast('✅ Treinamento registrado');
  renderEvolucao();
  if(typeof renderAptidao==='function') renderAptidao();
  if(typeof renderMobilizacao==='function') renderMobilizacao();
}

