  almoxarife:{label:'Almoxarife',cor:'teal',abas:['entradas','alm','uniformes','lavagem','nr6','epis','ferramentas','locacoes','estoque','treinamentos','ocorrencias'],podeEditar:true,podeAprovar:false},
