async function sesmtCarregarDados(){
  if(DEMO){
    funcs=DD.funcionarios.slice();epis=DD.epis.slice();ferramentas=DD.ferramentas.slice();
    ocorrencias=DD.ocorrencias.slice();vales=DD.vales.slice();estoque=DD.estoque.slice();
    treinamentos=DD.treinamentos.slice();aprovacoes=DD.aprovacoes.slice();
    uniformesCat=DD.uniformes_catalogo.slice();uniformesEnt=DD.uniformes_colaborador.slice();
    uniformesMov=DD.uniformes_movimentacoes.slice();estoqueUni=DD.estoque_uniformes.slice();
    filiais=DD.filiais.slice();depositos=DD.depositos.slice();locacoes=DD.locacoes.slice();
  }else{
    var res=await Promise.all([
      sbFetch('funcionarios',{filters:['ativo=eq.true'],order:'nome'}),
      sbFetch('epis',{order:'nome'}),
      sbFetch('ferramentas',{order:'nome'}),
      sbFetch('ocorrencias',{order:'data_ocorrencia.desc'}),
      sbFetch('vales',{order:'data_emissao.desc'}),
    sbFetchAll('estoque',{order:'nome.asc',maxPages:20}),
    sbFetchAll('itens_catalogo',{order:'nome.asc',maxPages:20}),
    sbFetchAll('treinamentos',{filters:['deleted_at=is.null'],order:'validade'}),
      sbFetch('aprovacoes',{filters:['status=eq.pendente']}),
      sbFetch('uniformes_catalogo',{order:'tipo'}),
      sbFetch('uniformes_colaborador',{filters:['ativo=eq.true']}),
      sbFetch('uniformes_movimentacoes',{order:'criado_em.desc'}),
      sbFetch('estoque_uniformes'),
      sbFetch('filiais',{filters:['ativa=eq.true'],order:'nome'}),
      sbFetch('depositos',{filters:['ativo=eq.true'],order:'nome'}),
      sbFetch('locacoes',{order:'termino'})
    ]);
    funcs=res[0]||[];epis=res[1]||[];ferramentas=res[2]||[];
    ocorrencias=res[3]||[];vales=res[4]||[];
    if(res[5]&&res[5].length) estoque=res[5];
    if(res[6]&&res[6].length) itens_catalogo=res[6];
    treinamentos=res[7]||[];aprovacoes=res[8]||[];
    uniformesCat=res[9]||[];uniformesEnt=res[10]||[];uniformesMov=res[11]||[];estoqueUni=res[12]||[];
    filiais=res[13]||[];depositos=res[14]||[];locacoes=res[15]||[];
  }
  try{ await almTiposItemLoad(); }catch(e){ console.warn('Tipos materiais:', e); }
  window._almEstoqueConsolidado = false;
  try{
    await almConsolidarEstoqueTodos();
    window._almEstoqueConsolidado = true;
  }catch(e){ console.warn('Consolidação estoque:', e); }
  try{ if(typeof atualizarMetricas==='function') atualizarMetricas(); }catch(e){ console.warn('atualizarMetricas erro:',e); }
  try{ if(typeof popularSelectFuncs==='function') popularSelectFuncs(); }catch(e){}
  try{ if(typeof renderSeletorFilial==='function') renderSeletorFilial(); }catch(e){}
  try{ if(typeof popularFiltrosAlm==='function') popularFiltrosAlm(); }catch(e){}
  try{ if(typeof atualizarDepositos==='function') atualizarDepositos(); }catch(e){}
  // Re-renderizar telas VISÍVEIS que dependem de dados async (não montar hidden)
  setTimeout(function(){
    try{
      var pgE=document.getElementById('pg-sesmt-evolucao');
      if(pgE && !pgE.classList.contains('hidden') && typeof renderEvolucao==='function') renderEvolucao();
    }catch(e){}
    try{
      var pgT=document.getElementById('pg-sesmt-treinamentos');
      if(pgT && !pgT.classList.contains('hidden') && typeof renderTreinamentos==='function') renderTreinamentos();
    }catch(e){}
    try{ if(typeof renderDashboardSesmt==='function') renderDashboardSesmt(); }catch(e){}
    try{ if(typeof progCarregarBadgesPonto==='function' && Object.keys(_pontoCache).length>0) progCarregarBadgesPonto(); }catch(e){}
  }, 200);
}
function atualizarMetricas(){
  function se(id,v){var el=document.getElementById(id);if(el)el.textContent=v;}
  se('m-func',filtrarFilial(funcs).length);
  se('m-epis',filtrarFilial(epis).length);
  se('m-fer',filtrarFilial(ferramentas).length);
  se('m-uni',uniformesEnt.filter(function(u){return u.ativo;}).length);
  se('m-loc',filtrarFilial(locacoes).filter(function(l){return l.disponibilidade==='Em uso';}).length);
  se('m-aprov',aprovacoes.filter(function(a){return a.status==='pendente';}).length);
  var n=0;
  epis.forEach(function(e){if(stV(e.validade)&&stV(e.validade).cls!=='ok')n++;if(e.ca_validade&&stV(e.ca_validade)&&stV(e.ca_validade).cls!=='ok')n++;});
  estoque.forEach(function(e){if(e.saldo<e.saldo_minimo)n++;});
  treinamentos.forEach(function(t){var v=t.val||t.validade;if(v&&stV(v)&&stV(v).cls!=='ok')n++;});
  var el=document.getElementById('alert-badge');if(el)el.textContent=n;
}
