var sigCtx=null,sigDrawing=false;
function initSig(id){
  var c=document.getElementById(id);if(!c)return;
  c.width=c.parentElement.offsetWidth||400;c.height=78;
  sigCtx=c.getContext('2d');sigDrawing=false;
  function pos(e){var r=c.getBoundingClientRect();var src=e.touches?e.touches[0]:e;return{x:src.clientX-r.left,y:src.clientY-r.top};}
  c.onmousedown=function(e){sigDrawing=true;var p=pos(e);sigCtx.beginPath();sigCtx.moveTo(p.x,p.y);};
  c.onmousemove=function(e){if(!sigDrawing)return;var p=pos(e);sigCtx.lineTo(p.x,p.y);sigCtx.strokeStyle='#185FA5';sigCtx.lineWidth=2;sigCtx.stroke();var h=document.getElementById('sig-hint');if(h)h.style.display='none';};
  c.onmouseup=function(){sigDrawing=false;};
  c.addEventListener('touchstart',function(e){e.preventDefault();sigDrawing=true;var p=pos(e);sigCtx.beginPath();sigCtx.moveTo(p.x,p.y);},{passive:false});
  c.addEventListener('touchmove',function(e){e.preventDefault();if(!sigDrawing)return;var p=pos(e);sigCtx.lineTo(p.x,p.y);sigCtx.strokeStyle='#185FA5';sigCtx.lineWidth=2;sigCtx.stroke();},{passive:false});
  c.addEventListener('touchend',function(){sigDrawing=false;});
}
function clearSig(){if(sigCtx){sigCtx.clearRect(0,0,9999,9999);var h=document.getElementById('sig-hint');if(h)h.style.display='flex';}}

// ── Timeline diário — SESMT Almoxarifado ─────────────────────────
var _almTimelineSugTimer = null;

function almTimelineNormData(v){
  if(!v) return '';
  var s=String(v).trim();
  if(/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0,10);
  var p=s.split(/[T\s]/)[0];
  if(/^\d{2}\/\d{2}\/\d{4}$/.test(p)){
    var x=p.split('/');
    return x[2]+'-'+x[1]+'-'+x[0];
  }
  return p.slice(0,10);
}

function almTimelineMatchNomeItem(a,b){
  if(!a||!b) return false;
  var na=String(a).trim().toLowerCase();
  var nb=String(b).trim().toLowerCase();
  if(!na||!nb) return false;
  return na===nb || na.indexOf(nb)>=0 || nb.indexOf(na)>=0;
}

function almTimelineResolverRef(){
  var itemId=(document.getElementById('alm-fil-item-id')||{}).value||'';
  var q=((document.getElementById('alm-fil-q')||{}).value||'').trim();
  if(itemId){
    var cat=(itens_catalogo||[]).find(function(x){ return String(x.id)===String(itemId); });
    if(cat) return {id:cat.id,nome:cat.nome,codigo:cat.codigo,sku:cat.sku,tipo:cat.tipo_item||cat.tipo,ref:cat};
  }
  if(!q) return null;
  var ql=q.toLowerCase();
  var cats=(itens_catalogo||[]).filter(function(c){
    if(c.ativo===false) return false;
    return (c.nome||'').toLowerCase().indexOf(ql)>=0
      || (c.codigo||'').toLowerCase().indexOf(ql)>=0
      || (c.sku||'').toLowerCase().indexOf(ql)>=0;
  });
  if(cats.length===1) return {id:cats[0].id,nome:cats[0].nome,codigo:cats[0].codigo,sku:cats[0].sku,tipo:cats[0].tipo_item||cats[0].tipo,ref:cats[0]};
  var est=(estoque||[]).filter(function(e){
    return (e.nome||'').toLowerCase().indexOf(ql)>=0
      || (e.codigo||'').toLowerCase().indexOf(ql)>=0;
  });
  if(est.length===1){
    var ec=(itens_catalogo||[]).find(function(c){ return almMatchEstoqueRef(est[0],c); });
    if(ec) return {id:ec.id,nome:ec.nome,codigo:ec.codigo,sku:ec.sku,tipo:ec.tipo_item||ec.tipo,ref:ec};
    return {id:null,nome:est[0].nome,codigo:est[0].codigo,sku:est[0].sku,tipo:est[0].tipo,ref:est[0]};
  }
  return null;
}

function almTimelineMatchMovItem(m, ref){
  if(!m||!ref) return false;
  if(ref.id && String(m.item_id||'')===String(ref.id)) return true;
  var cat=(itens_catalogo||[]).find(function(c){ return String(c.id)===String(m.item_id||''); });
  var refCod=String(ref.codigo||'').trim();
  var refSku=String(ref.sku||'').trim();
  var refNome=String(ref.nome||'').trim();
  if(cat){
    if(refCod && String(cat.codigo||'').trim()===refCod) return true;
    if(refSku && String(cat.sku||'').trim()===refSku) return true;
    if(refNome && String(cat.nome||'').trim().toLowerCase()===refNome.toLowerCase()) return true;
  }
  var mCod=String(m.item_codigo||m.codigo||'').trim();
  if(refCod && mCod && mCod===refCod) return true;
  if(!ref.id && refNome){
    if(cat && String(cat.nome||'').trim().toLowerCase()===refNome.toLowerCase()) return true;
    var est=(estoque||[]).find(function(e){ return String(e.id)===String(m.estoque_id); });
    if(est && String(est.nome||'').trim().toLowerCase()===refNome.toLowerCase()) return true;
  }
  return false;
}

function almTimelineMovDestinoDep(m){
  if(typeof almMovDestinoId==='function') return almMovDestinoId(m);
  return m.destino_id||null;
}

function almTimelineAfetaDeposito(m, depId){
  if(!depId) return true;
  var d=String(depId);
  if(m.tipo_mov==='transferencia'){
    var dest=almTimelineMovDestinoDep(m);
    return String(m.deposito_id||'')===d || String(dest||'')===d;
  }
  return String(m.deposito_id||'')===d;
}

function almTimelineDeltaDeposito(m, depId){
  var q=Number(m.quantidade)||1;
  if(m.tipo_mov==='entrada'){
    if(depId&&String(m.deposito_id||'')!==String(depId)) return 0;
    return q;
  }
  if(m.tipo_mov==='devolucao'){
    if(typeof almDevolucaoRetornaEstoque==='function'&&!almDevolucaoRetornaEstoque(m.condicao||'')) return 0;
    if(depId&&String(m.deposito_id||'')!==String(depId)) return 0;
    return q;
  }
  if(m.tipo_mov==='transferencia'){
    if(!depId) return 0;
    var dest=almTimelineMovDestinoDep(m);
    if(String(m.deposito_id||'')===String(depId)) return -q;
    if(String(dest||'')===String(depId)) return q;
    return 0;
  }
  if(['entrega','ajuste','perda','quebra','baixa','descarte'].indexOf(m.tipo_mov)>=0){
    if(m.status==='Devolvido') return 0;
    if(depId&&String(m.deposito_id||'')!==String(depId)) return 0;
    return -q;
  }
  return 0;
}

function almTimelineNomeDetentor(colabId, mov, epi){
  if(colabId&&typeof almNomeColaboradorEntrega==='function'){
    var n=almNomeColaboradorEntrega(colabId);
    if(n) return n;
  }
  if(mov&&typeof almColaboradorIdFromMov==='function'){
    var cid=almColaboradorIdFromMov(mov);
    if(cid){
      var n2=almNomeColaboradorEntrega(cid);
      if(n2) return n2;
    }
  }
  if(epi&&epi.responsavel_id){
    var f=(typeof funcs!=='undefined'?funcs:[]).find(function(x){ return String(x.id)===String(epi.responsavel_id); })
      ||(typeof colaboradores!=='undefined'?colaboradores:[]).find(function(x){ return String(x.id)===String(epi.responsavel_id); });
    if(f) return f.nome||'';
  }
  return '—';
}

function almTimelineFormatDetalheMov(m){
  var q=Number(m.quantidade)||1;
  var cid=m.colaborador_id||null;
  if(typeof almColaboradorIdFromMov==='function') cid=cid||almColaboradorIdFromMov(m);
  var quem=almTimelineNomeDetentor(cid,m,null);
  var dep=typeof almDepositoLabel==='function'?almDepositoLabel(m.deposito_id):'';
  var lbl=m.tipo_mov==='entrega'?(quem+' · '+q+' un.'+(dep?' · '+dep:''))
    :(q+' un.'+(m.motivo?' · '+m.motivo:'')+(dep?' · '+dep:''));
  return lbl;
}

function almTimelineDataDevolucaoEpi(e){
  var obs=String(e.observacoes||'');
  var mt=obs.match(/Devolu(?:ç|c)(?:ão|ao)\s*(\d{2}\/\d{2}\/\d{4}|\d{4}-\d{2}-\d{2})/i);
  if(mt) return almTimelineNormData(mt[1]);
  return null;
}

function almTimelineColetarEventos(ref, opts){
  opts=opts||{};
  var depId=opts.depId||'';
  var filialId=opts.filialId||'';
  var eventos=[];
  (movimentacoes_itens||[]).forEach(function(m){
    if(!almTimelineMatchMovItem(m,ref)) return;
    if(filialId&&m.filial_id&&String(m.filial_id)!==String(filialId)&&m.tipo_mov!=='transferencia') return;
    if(depId&&!almTimelineAfetaDeposito(m,depId)) return;
    var dt=almTimelineNormData(m.data_mov);
    if(!dt) return;
    var delta=almTimelineDeltaDeposito(m,depId);
    var afetaSaldo=!(depId&&delta===0&&m.tipo_mov!=='entrega');
    eventos.push({
      data:dt, qtd:Number(m.quantidade)||1, delta:delta, afetaSaldo:afetaSaldo,
      tipo:m.tipo_mov, status:m.status||'', origem:'patrimonial', mov:m,
      detalhe:almTimelineFormatDetalheMov(m),
      colabId:m.colaborador_id||(typeof almColaboradorIdFromMov==='function'?almColaboradorIdFromMov(m):null)
    });
  });
  var nomeRef=(ref.nome||'').trim();
  if(nomeRef){
    (epis||[]).forEach(function(e){
      if(!almTimelineMatchNomeItem(e.nome,nomeRef)) return;
      var dtEnt=almTimelineNormData(e.data_entrega);
      if(dtEnt&&['Devolvido','Substituído','Cancelado','Baixado'].indexOf(e.status||'')<0){
        eventos.push({
          data:dtEnt, qtd:Number(e.quantidade)||1, delta:0, afetaSaldo:false,
          tipo:'entrega_epi', status:e.status||'Ativo', origem:'epi', epi:e,
          detalhe:'NR-6 · '+almTimelineNomeDetentor(e.responsavel_id,null,e)+' · '+(Number(e.quantidade)||1)+' un.',
          colabId:e.responsavel_id
        });
      }
      if(['Devolvido','Substituído'].indexOf(e.status||'')>=0){
        var dtDev=almTimelineDataDevolucaoEpi(e)||dtEnt;
        if(dtDev){
          eventos.push({
            data:dtDev, qtd:Number(e.quantidade)||1, delta:0, afetaSaldo:false,
            tipo:'devolucao_epi', status:e.status, origem:'epi', epi:e,
            detalhe:'Devolução NR-6 · '+almTimelineNomeDetentor(e.responsavel_id,null,e)+' · '+(Number(e.quantidade)||1)+' un.',
            colabId:e.responsavel_id
          });
        }
      }
    });
  }
  eventos.sort(function(a,b){
    if(a.data!==b.data) return a.data<b.data?-1:1;
    return (a.mov&&a.mov.id?String(a.mov.id):a.tipo).localeCompare(b.mov&&b.mov.id?String(b.mov.id):b.tipo);
  });
  return eventos;
}

function almTimelineMontarDiario(eventos, ini, fim){
  var preSaldo=0;
  eventos.forEach(function(ev){
    if(ini&&ev.data>=ini) return;
    if(!ev.afetaSaldo) return;
    preSaldo+=ev.delta;
  });
  var saldo=preSaldo;
  var byDay={};
  eventos.forEach(function(ev){
    if(ini&&ev.data<ini) return;
    if(fim&&ev.data>fim) return;
    if(!byDay[ev.data]) byDay[ev.data]={entradas:0,saidas:0,devolucoes:0,entregas:[],devolucoesDet:[]};
    var d=byDay[ev.data];
    var q=ev.qtd;
    if(ev.origem==='epi'){
      if(ev.tipo==='entrega_epi') d.entregas.push(ev.detalhe);
      else if(ev.tipo==='devolucao_epi') d.devolucoesDet.push(ev.detalhe);
      return;
    }
    if(ev.tipo==='entrada'||(ev.tipo==='transferencia'&&ev.delta>0)) d.entradas+=q;
    else if(ev.tipo==='devolucao'){ d.devolucoes+=q; d.devolucoesDet.push(ev.detalhe); }
    else if(ev.tipo==='entrega'&&ev.status==='Em uso') d.entregas.push(ev.detalhe);
    else if(ev.delta<0) d.saidas+=q;
  });
  var dias=Object.keys(byDay).sort();
  var rows=[];
  dias.forEach(function(diaKey){
    var dia=byDay[diaKey];
    var saldoAnt=saldo;
    var entregasQtd=0;
    eventos.forEach(function(ev){
      if(ev.data!==diaKey||!ev.afetaSaldo) return;
      if(ev.tipo==='entrega'&&ev.status==='Em uso') entregasQtd+=ev.qtd;
    });
    var deltaDia=dia.entradas+dia.devolucoes-dia.saidas-entregasQtd;
    saldo=saldoAnt+deltaDia;
    rows.push({
      data:diaKey, saldoAnterior:saldoAnt, entradas:dia.entradas, saidas:dia.saidas,
      devolucoes:dia.devolucoes, entregas:dia.entregas, devolucoesDet:dia.devolucoesDet,
      saldoAtual:saldo, deltaDia:deltaDia
    });
  });
  rows.reverse();
  return {rows:rows, saldoFinal:saldo, saldoInicial:preSaldo};
}

function almTimelineResumoPeriodo(ref, depId, filialId, ini, fim){
  if(!ini&&!fim) return {saldoAnterior:0,entradas:0,saidas:0,devolucoes:0,saldoAtual:0};
  var evs=almTimelineColetarEventos(ref,{depId:depId,filialId:filialId});
  var saldoAnt=0;
  evs.forEach(function(ev){
    if(ini&&ev.data<ini&&ev.afetaSaldo) saldoAnt+=ev.delta;
  });
  var ent=0,sai=0,dev=0;
  evs.forEach(function(ev){
    if(ini&&ev.data<ini) return;
    if(fim&&ev.data>fim) return;
    if(!ev.afetaSaldo) return;
    if(ev.tipo==='entrada'||(ev.tipo==='transferencia'&&ev.delta>0)) ent+=ev.qtd;
    else if(ev.tipo==='devolucao') dev+=ev.qtd;
    else if(ev.tipo==='entrega'&&ev.status==='Em uso') sai+=ev.qtd;
    else if(ev.delta<0) sai+=ev.qtd;
  });
  return {saldoAnterior:saldoAnt,entradas:ent,saidas:sai,devolucoes:dev,saldoAtual:saldoAnt+ent+dev-sai};
}

function almTimelineRenderPosse(ref, depId, filialId){
  var wrap=document.getElementById('alm-posse-wrap');
  var tbody=document.getElementById('tbody-alm-posse');
  var tit=document.getElementById('alm-posse-titulo');
  if(!wrap||!tbody) return;
  var linhas=[];
  (movimentacoes_itens||[]).forEach(function(m){
    if(!almTimelineMatchMovItem(m,ref)) return;
    if(m.tipo_mov!=='entrega'||m.status!=='Em uso') return;
    if(depId&&String(m.deposito_id||'')!==String(depId)) return;
    if(filialId&&m.filial_id&&String(m.filial_id)!==String(filialId)) return;
    linhas.push({
      detentor:almTimelineNomeDetentor(m.colaborador_id,m,null),
      qtd:Number(m.quantidade)||1,
      origem:'Patrimonial',
      data:almTimelineNormData(m.data_mov),
      prev:m.previsao_devolucao||'—',
      dep:typeof almDepositoLabel==='function'?almDepositoLabel(m.deposito_id):'—',
      status:m.status
    });
  });
  if(ref.nome){
    (epis||[]).forEach(function(e){
      if(!almTimelineMatchNomeItem(e.nome,ref.nome)) return;
      if(['Devolvido','Substituído','Cancelado','Baixado'].indexOf(e.status||'')>=0) return;
      linhas.push({
        detentor:almTimelineNomeDetentor(e.responsavel_id,null,e),
        qtd:Number(e.quantidade)||1,
        origem:'NR-6 (EPI)',
        data:almTimelineNormData(e.data_entrega),
        prev:e.data_prevista_substituicao||'—',
        dep:'—',
        status:e.status||'Ativo'
      });
    });
  }
  if(tit) tit.textContent='Em posse — '+ref.nome+(depId?' · '+almDepositoLabel(depId):'');
  if(!linhas.length){
    wrap.classList.add('hidden');
    return;
  }
  wrap.classList.remove('hidden');
  tbody.innerHTML=linhas.map(function(l){
    return '<tr>'
      +'<td>'+escHtml(l.detentor)+'</td>'
      +'<td style="text-align:center">'+l.qtd+'</td>'
      +'<td><span class="bdg '+(l.origem.indexOf('NR')>=0?'purple':'info')+'">'+escHtml(l.origem)+'</span></td>'
      +'<td>'+(l.data?fmtD(l.data):'—')+'</td>'
      +'<td>'+(l.prev&&l.prev!=='—'?fmtD(l.prev):'—')+'</td>'
      +'<td style="font-size:11px;color:#888">'+escHtml(l.dep)+'</td>'
      +'<td><span class="bdg warn">'+escHtml(l.status)+'</span></td>'
      +'</tr>';
  }).join('');
}

function almTimelineSetThead(modo){
  var th=document.getElementById('thead-alm-mov');
  if(!th) return;
  if(modo==='timeline'){
    th.innerHTML='<tr><th>Data</th><th style="text-align:right">Saldo anterior</th><th style="text-align:right">Entradas</th>'
      +'<th style="text-align:right">Saídas</th><th>Entregas / detentor</th><th>Devoluções</th><th style="text-align:right">Saldo atual</th></tr>';
  } else {
    th.innerHTML='<tr><th>Produto</th><th>Categoria</th><th>Filial/Depósito</th>'
      +'<th style="text-align:right">Saldo anterior</th><th style="text-align:right">Entradas</th>'
      +'<th style="text-align:right">Saídas</th><th style="text-align:right">Saldo atual</th><th>Status</th></tr>';
  }
}

function almTimelineInputBusca(){
  clearTimeout(_almTimelineSugTimer);
  _almTimelineSugTimer=setTimeout(almTimelineMostrarSugestoes,180);
}

function almTimelineMostrarSugestoes(){
  var inp=document.getElementById('alm-fil-q');
  var box=document.getElementById('alm-fil-sug');
  if(!inp||!box) return;
  var q=(inp.value||'').trim();
  if(!q){ box.innerHTML=''; box.style.display='none'; return; }
  if(q.length<2){ box.innerHTML=''; box.style.display='none'; return; }
  var ql=q.toLowerCase();
  var seen={}, items=[];
  (itens_catalogo||[]).forEach(function(c){
    if(c.ativo===false) return;
    if((c.nome||'').toLowerCase().indexOf(ql)<0&&(c.codigo||'').toLowerCase().indexOf(ql)<0&&(c.sku||'').toLowerCase().indexOf(ql)<0) return;
    var k=String(c.id||c.nome);
    if(seen[k]) return;
    seen[k]=1;
    items.push({id:c.id,nome:c.nome,codigo:c.codigo||'',tipo:c.tipo_item||c.tipo||''});
  });
  (estoque||[]).forEach(function(e){
    if((e.nome||'').toLowerCase().indexOf(ql)<0) return;
    var ec=(itens_catalogo||[]).find(function(c){ return almMatchEstoqueRef(e,c); });
    if(ec&&seen[String(ec.id)]) return;
    var k=ec?String(ec.id):('est:'+e.nome);
    if(seen[k]) return;
    seen[k]=1;
    items.push({id:ec?ec.id:'',nome:e.nome,codigo:e.codigo||'',tipo:e.tipo||''});
  });
  if(!items.length){ box.innerHTML=''; box.style.display='none'; return; }
  box.innerHTML=items.slice(0,14).map(function(it){
    var sub=(it.codigo?it.codigo+' · ':'')+(it.tipo||'');
    var nid=JSON.stringify(String(it.id||''));
    var nn=JSON.stringify(String(it.nome||''));
    return '<div style="padding:8px 12px;cursor:pointer;border-bottom:1px solid #f0efe8;font-size:12px" '
      +'onmousedown="event.preventDefault();almTimelineSelecionarItem('+nid+','+nn+')">'
      +'<div style="font-weight:500">'+escHtml(it.nome)+'</div>'
      +'<div style="font-size:10px;color:#888">'+escHtml(sub)+'</div></div>';
  }).join('');
  box.style.display='block';
}

function almTimelineSelecionarItem(id,nome){
  var inp=document.getElementById('alm-fil-q');
  var hid=document.getElementById('alm-fil-item-id');
  var box=document.getElementById('alm-fil-sug');
  if(inp) inp.value=nome;
  if(hid) hid.value=id||'';
  if(box){ box.innerHTML=''; box.style.display='none'; }
  aplicarFiltroAlm();
}

function almTimelineBuscaKey(ev){
  if(!ev||ev.key!=='Enter') return;
  ev.preventDefault();
  var ref=almTimelineResolverRef();
  if(ref&&ref.id){
    var hid=document.getElementById('alm-fil-item-id');
    if(hid) hid.value=ref.id;
  }
  aplicarFiltroAlm();
}

function almTimelineLimparItem(){
  var inp=document.getElementById('alm-fil-q');
  var hid=document.getElementById('alm-fil-item-id');
  if(inp) inp.value='';
  if(hid) hid.value='';
  aplicarFiltroAlm();
}

function aplicarFiltroAlm(){
  var filial=(document.getElementById('alm-fil-filial')||{}).value||'';
  var dep    =(document.getElementById('alm-fil-dep')||{}).value||'';
  var cat    =(document.getElementById('alm-fil-cat')||{}).value||'';
  var q      =((document.getElementById('alm-fil-q')||{}).value||'').toLowerCase();
  var ini    =(document.getElementById('alm-fil-ini')||{}).value||'';
  var fim    =(document.getElementById('alm-fil-fim')||{}).value||'';

  var ref=almTimelineResolverRef();
  var tbody=document.getElementById('tbody-alm-mov');
  var info=document.getElementById('alm-timeline-info');
  var titulo=document.getElementById('alm-titulo');
  var posseWrap=document.getElementById('alm-posse-wrap');
  if(!tbody) return;

  if(ref&&ref.nome){
    almTimelineSetThead('timeline');
    almTimelineRenderPosse(ref,dep,filial);
    var evs=almTimelineColetarEventos(ref,{depId:dep,filialId:filial});
    var diario=almTimelineMontarDiario(evs,ini,fim);
    var depLbl=dep?(typeof almDepositoLabel==='function'?almDepositoLabel(dep):dep):'todos os depósitos';
    if(titulo) titulo.textContent='Timeline diária — '+ref.nome;
    if(info){
      info.style.display='block';
      info.innerHTML='Item: <strong>'+escHtml(ref.nome)+'</strong>'
        +(ref.codigo?' · Cód. '+escHtml(ref.codigo):'')
        +' · Depósito: <strong>'+escHtml(depLbl)+'</strong>'
        +(ini||fim?' · Período: '+(ini?fmtD(ini):'…')+' a '+(fim?fmtD(fim):'…'):'')
        +' · Saldo calculado no fechamento: <strong>'+diario.saldoFinal+'</strong>'
        +(dep?' (movimentações patrimoniais neste depósito)':'');
    }
    if(!diario.rows.length){
      tbody.innerHTML='<tr><td colspan="7" style="text-align:center;color:#aaa;padding:1rem">Nenhuma movimentação no período para este item.</td></tr>';
    } else {
      tbody.innerHTML=diario.rows.map(function(r){
        var entHtml=r.entregas.length
          ? r.entregas.map(function(x){ return '<div style="font-size:11px;color:#854F0B">↗ '+escHtml(x)+'</div>'; }).join('')
          : '<span style="color:#ccc">—</span>';
        var devHtml=r.devolucoesDet.length
          ? r.devolucoesDet.map(function(x){ return '<div style="font-size:11px;color:#3B6D11">↩ '+escHtml(x)+'</div>'; }).join('')
          : (r.devolucoes>0?('<span style="color:#3B6D11;font-weight:600">+'+r.devolucoes+'</span>'):'<span style="color:#ccc">—</span>');
        return '<tr>'
          +'<td style="white-space:nowrap;font-weight:500">'+fmtD(r.data)+'</td>'
          +'<td style="text-align:right;color:#888">'+r.saldoAnterior+'</td>'
          +'<td style="text-align:right;color:#3B6D11">'+(r.entradas>0?'+'+r.entradas:'—')+'</td>'
          +'<td style="text-align:right;color:#A32D2D">'+(r.saidas>0?'−'+r.saidas:'—')+'</td>'
          +'<td style="max-width:280px">'+entHtml+'</td>'
          +'<td>'+devHtml+'</td>'
          +'<td style="text-align:right;font-weight:600">'+r.saldoAtual+'</td>'
          +'</tr>';
      }).join('');
    }
    var saldoAtual=dep
      ? (ref.id?almCalcularSaldoMovimentacoesDeposito(ref.id,dep):almSaldoEstoqueItem(ref.ref||ref,dep))
      : almSaldoEstoqueItem(ref.ref||ref,null);
    var metr=document.getElementById('alm-metricas');
    if(metr){
      var emPosse=(document.getElementById('tbody-alm-posse')||{}).querySelectorAll('tr').length;
      metr.innerHTML=[
        {l:'Saldo atual'+(dep?' (dep.)':''), v:saldoAtual, c:'#185FA5'},
        {l:'Dias c/ mov.', v:diario.rows.length, c:'#3B6D11'},
        {l:'Em posse agora', v:emPosse, c:'#854F0B'},
        {l:'Devol. no período', v:diario.rows.reduce(function(s,r){ return s+r.devolucoes; },0), c:'#A32D2D'},
      ].map(function(m){
        return '<div class="card" style="padding:.75rem;text-align:center">'
          +'<div style="font-size:11px;color:#888">'+m.l+'</div>'
          +'<div style="font-size:22px;font-weight:700;color:'+m.c+'">'+m.v+'</div></div>';
      }).join('');
    }
    return;
  }

  almTimelineSetThead('lista');
  if(info) info.style.display='none';
  if(posseWrap) posseWrap.classList.add('hidden');

  var lista=(typeof estoque!=='undefined'?estoque:[]).filter(function(e){
    if(filial && e.filial_id !== filial) return false;
    if(dep    && e.deposito_id !== dep)  return false;
    if(cat    && !eeCatEstoqueMatch(e.tipo||'', cat) && !((cat==='Uniforme'||cat==='Uniformes') && eePareceUniformePorNome(e.nome))) return false;
    if(q      && !(e.nome||'').toLowerCase().includes(q)
              && !(e.codigo||'').toLowerCase().includes(q)) return false;
    return true;
  });

  if(titulo) titulo.textContent='Movimentação de estoque'+(filial?' — filial filtrada':' — todas as filiais');

  if(!lista.length){
    tbody.innerHTML='<tr><td colspan="8" style="text-align:center;color:#aaa;padding:1rem">Nenhum item encontrado.</td></tr>';
  } else {
    tbody.innerHTML=lista.map(function(e){
      var fil=filiais.find(function(f){ return f.id===e.filial_id; });
      var depObj=depositos.find(function(d){ return d.id===e.deposito_id; });
      var local=(fil?fil.nome:'—')+(depObj?' / '+depObj.nome:'');
      var catItem=(itens_catalogo||[]).find(function(c){ return almMatchEstoqueRef(e,c); });
      var refRow=catItem?{id:catItem.id,nome:catItem.nome,ref:catItem}:{id:null,nome:e.nome,ref:e};
      var res=almTimelineResumoPeriodo(refRow,dep||e.deposito_id||'',filial,ini,fim);
      var saldoShow=ini||fim?res.saldoAtual:(e.saldo||0);
      var stCor=saldoShow<=(e.saldo_minimo||5)?'#A32D2D':'#3B6D11';
      var stLabel=saldoShow<=0?'Zerado':saldoShow<=(e.saldo_minimo||5)?'Crítico':'Normal';
      return '<tr style="cursor:pointer" onclick="almTimelineSelecionarItem('+JSON.stringify(catItem?String(catItem.id):'')+','+JSON.stringify(String(e.nome||''))+')" title="Clique para ver timeline diária">'
        +'<td>'+escHtml(e.nome)+'</td>'
        +'<td>'+escHtml(e.tipo||'—')+'</td>'
        +'<td style="font-size:11px;color:#888">'+escHtml(local)+'</td>'
        +'<td style="text-align:right;color:#888">'+(ini||fim?res.saldoAnterior:'—')+'</td>'
        +'<td style="text-align:right;color:#3B6D11">'+(res.entradas>0?res.entradas:'—')+'</td>'
        +'<td style="text-align:right;color:#A32D2D">'+(res.saidas>0?res.saidas:'—')+'</td>'
        +'<td style="text-align:right;font-weight:600">'+saldoShow+'</td>'
        +'<td><span style="color:'+stCor+';font-size:11px;font-weight:600">'+stLabel+'</span></td>'
        +'</tr>';
    }).join('');
  }

  var metr=document.getElementById('alm-metricas');
  if(metr){
    var total=lista.length;
    var critico=lista.filter(function(e){ return (e.saldo||0)<=(e.saldo_minimo||5); }).length;
    var zerando=lista.filter(function(e){ return (e.saldo||0)<=0; }).length;
    metr.innerHTML=[
      {l:'Total de itens', v:total,   c:'#185FA5'},
      {l:'Estoque crítico',v:critico, c:'#854F0B'},
      {l:'Zerados',        v:zerando, c:'#A32D2D'},
      {l:'Colaboradores',  v:(typeof funcs!=='undefined'?funcs.length:0), c:'#3B6D11'},
    ].map(function(m){
      return '<div class="card" style="padding:.75rem;text-align:center">'
        +'<div style="font-size:11px;color:#888">'+m.l+'</div>'
        +'<div style="font-size:22px;font-weight:700;color:'+m.c+'">'+m.v+'</div></div>';
    }).join('');
  }
}

function renderAlmList(sel){
  // Delegar para aplicarFiltroAlm que usa a estrutura real do HTML
  aplicarFiltroAlm();
}

function popularFiltrosAlm(){
  var sf = document.getElementById('alm-fil-filial');
  if(sf) sf.innerHTML = '<option value="">Todas as filiais</option>'
    +(typeof filiais!=='undefined' ? filiais.map(function(f){ return '<option value="'+f.id+'">'+f.nome+'</option>'; }).join('') : '');
}

function atualizarDepositos(){
  var filId = (document.getElementById('alm-fil-filial')||{}).value||'';
  var sd = document.getElementById('alm-fil-dep');
  if(!sd) return;
  var prev = sd.value;
  var lista = (typeof depositos!=='undefined')
    ? depositos.filter(function(d){ return !filId || d.filial_id===filId; })
    : [];
  sd.innerHTML = '<option value="">Todos os depósitos</option>'
    + lista.map(function(d){ return '<option value="'+d.id+'">'+d.nome+'</option>'; }).join('');
  if(prev && lista.some(function(d){ return String(d.id)===String(prev); })) sd.value = prev;
}
function showAlm(fid){
  var f=funcs.find(function(x){return x.id===fid;});
  if(!f)return;
  renderAlmList(fid);
  var myE=epis.filter(function(e){return e.responsavel_id===fid;});
  var myF=ferramentas.filter(function(t){return t.responsavel_id===fid;});
  var myU=uniformesEnt.filter(function(u){return u.funcionario_id===fid&&u.ativo;});
  var myO=ocorrencias.filter(function(o){return o.funcionario_id===fid;});
  var myT=treinamentos.filter(function(t){return t.funcionario_id===fid;});
  var tv=myT.filter(function(t){var v=t.val||t.validade;return v&&stV(v)&&stV(v).cls!=='ok';});
  var idx=funcs.indexOf(f);
  var ec={Bom:'ok',Regular:'warn',Danificado:'danger'};
  var html='<div class="det">';
  if(tv.length)html+='<div class="alert-bar red">Treinamento(s) vencido(s): '+tv.map(function(t){return t.nr;}).join(', ')+'</div>';
  html+='<div style="display:flex;align-items:center;gap:10px;padding:.85rem 1rem;border-bottom:0.5px solid #f0efe8">'
    +av(f.nome,idx)+'<div><div style="font-size:14px;font-weight:500">'+f.nome+'</div>'
    +'<div style="font-size:11px;color:#888">'+f.cargo+' — '+f.setor+' — Mat. '+f.matricula+'</div></div>'
    +'<div style="margin-left:auto;display:flex;gap:5px;flex-wrap:wrap">'
    +'<button class="btn btn-sm btn-pri" onclick="openEntrega(\''+fid+'\')">+ EPI</button>'
    +'<button class="btn btn-sm btn-teal" onclick="openEntregaUniforme()">+ Uniforme</button>'
    +'<button class="btn btn-sm" onclick="verNR6(\''+fid+'\')">NR-6</button>'
    +'</div></div>';
  html+='<div class="sec-tag">EPIs ('+myE.length+')</div>';
  if(myE.length){
    html+='<table class="tbl tbl-r"><thead><tr><th>Item</th><th>Tipo</th><th>CA</th><th>Validade</th><th>Status</th></tr></thead><tbody>';
    myE.forEach(function(e){var s=stV(e.validade);html+='<tr><td>'+e.nome+'</td><td><span class="bdg '+(e.tipo==='EPI'?'info':'purple')+'">'+e.tipo+'</span></td><td style="color:#888">'+e.ca+'</td><td>'+fmtD(e.validade)+'</td><td>'+(s?'<span class="bdg '+s.cls+'">'+s.lbl+'</span>':'—')+'</td></tr>';});
    html+='</tbody></table>';
  }else html+='<div style="padding:.75rem 1rem;font-size:12px;color:#aaa">Nenhum EPI</div>';
  html+='<div class="sec-tag">Ferramentas ('+myF.length+')</div>';
  if(myF.length){
    html+='<table class="tbl tbl-r"><thead><tr><th>Ferramenta</th><th>Patrimônio</th><th>Estado</th></tr></thead><tbody>';
    myF.forEach(function(t){html+='<tr><td>'+t.nome+'</td><td style="color:#888">'+t.patrimonio+'</td><td><span class="bdg '+(ec[t.estado]||'gray')+'">'+t.estado+'</span></td></tr>';});
    html+='</tbody></table>';
  }else html+='<div style="padding:.75rem 1rem;font-size:12px;color:#aaa">Nenhuma ferramenta</div>';
  if(myO.length){
    html+='<div class="sec-tag">Ocorrências ('+myO.length+')</div>';
    html+='<table class="tbl tbl-r"><thead><tr><th>Data</th><th>Item</th><th>Tipo</th><th>Status</th></tr></thead><tbody>';
    myO.forEach(function(o){html+='<tr><td>'+fmtD(o.data_ocorrencia)+'</td><td>'+o.item+'</td><td><span class="bdg warn">'+o.tipo+'</span></td><td><span class="bdg '+(o.status.indexOf('Assinado')>=0?'ok':'warn')+'">'+o.status+'</span></td></tr>';});
    html+='</tbody></table>';
  }
  html+='</div>';
  document.getElementById('alm-det').innerHTML=html;
  sesmtShowTab('alm');
}
function renderEpis(){
  var q=(document.getElementById('fil-epi-q')||{}).value||'';
  var t=(document.getElementById('fil-epi-tipo')||{}).value||'';
  var tbody=document.getElementById('tbody-epis'); if(!tbody) return;
  var rows=filtrarFilial(epis).filter(function(e){return(!q||e.nome.toLowerCase().indexOf(q.toLowerCase())>=0||fNome(e.responsavel_id).toLowerCase().indexOf(q.toLowerCase())>=0)&&(!t||e.tipo===t);});
  tbody.innerHTML=rows.length?rows.map(function(e){
    var valCa=_epiValCa(e);
    var sc=valCa?stV(valCa):null;
    var stCa=_epiStatusCa(e);
    var caDisp=String(e.ca_numero_entregue||e.ca||'').trim()||'—';
    var cont=(typeof contratos!=='undefined'&&e.contrato_id)?contratos.find(function(c){return c.id===e.contrato_id;}):null;
    var ativo=epiEmPoderFicha(e);
    var btnDev=ativo?('<button class="btn btn-sm" style="font-size:10px;color:#854F0B;border-color:#854F0B;margin-right:3px" onclick="openDevolucaoEpi(null,\''+e.id+'\')">📤 Devolver</button>'):'';
    return '<tr><td style="font-weight:500">'+e.nome+'</td><td><span class="bdg '+(e.tipo==='EPI'?'info':'purple')+'">'+e.tipo+'</span></td>'
      +'<td style="color:#888">'+escHtml(caDisp)+'</td><td>'+(sc?'<span class="bdg '+sc.cls+'">'+fmtD(valCa)+'</span>':'—')+'</td>'
      +'<td>'+fNome(e.responsavel_id)+'</td><td style="font-size:11px">'+(cont?escHtml(almContratoLabel(cont,false)):'—')+'</td>'
      +'<td><span class="bdg '+stCa.cls+'">'+escHtml(stCa.lbl)+'</span></td>'
      +'<td style="white-space:nowrap">'+btnDev
      +(ativo?'<button class="btn btn-sm btn-pri" onclick="openNovaEntregaEpi(\''+e.responsavel_id+'\')">+ Entregar</button>':'<span style="font-size:10px;color:#888">'+(e.status||'—')+'</span>')
      +'</td></tr>';
  }).join(''):'<tr><td colspan="8" style="padding:2rem;text-align:center;color:#aaa">Nenhuma entrega registrada. Use a aba <b>Entregar colaborador</b>.</td></tr>';
}
