var itens_catalogo = []; // {id,codigo,nome,descricao,tipo_item,categoria,unidade_medida,
                         //  controla_estoque,controla_numero_serie,controla_validade,
                         //  controla_ca,controla_calibracao,controla_devolucao,ativo,observacoes}
var movimentacoes_itens = []; // {id,item_id,tipo_mov,quantidade,deposito_id,filial_id,
                              //  contrato_id,fornecedor,nota_fiscal,valor_unitario,
                              //  data_mov,responsavel_id,registrado_por_id,destino_tipo,destino_id,
                              //  colaborador_id,equipe_id,veiculo_id,projeto_id,previsao_devolucao,
                              //  numeros_serie,condicao,motivo,obs,status}

var TIPOS_ITEM_DEFAULT = [
  {codigo:'MATERIAL', nome_exibicao:'MATERIAL', ordem:10},
  {codigo:'FERRAMENTA', nome_exibicao:'FERRAMENTA', ordem:20},
  {codigo:'EPI', nome_exibicao:'EPI', ordem:30},
  {codigo:'EPC', nome_exibicao:'EPC', ordem:40},
  {codigo:'VESTIMENTA', nome_exibicao:'UNIFORME', ordem:50},
  {codigo:'EQUIPAMENTO', nome_exibicao:'EQUIPAMENTO', ordem:60},
  {codigo:'CONSUMIVEL', nome_exibicao:'CONSUMÍVEL', ordem:70},
  {codigo:'PECA', nome_exibicao:'PEÇA', ordem:80},
  {codigo:'KIT', nome_exibicao:'KIT', ordem:90},
  {codigo:'PNEU', nome_exibicao:'PNEU', ordem:95},
  {codigo:'OUTRO', nome_exibicao:'OUTRO', ordem:100}
];
var alm_tipos_item = TIPOS_ITEM_DEFAULT.map(function(t){ return Object.assign({ativo:true}, t); });
var TIPOS_ITEM = alm_tipos_item.map(function(t){ return t.codigo; });
var UNIDADES_MEDIDA = ['UN','Par','m','m²','m³','kg','g','L','mL','Rolo','Caixa','Pacote','Conjunto','Kit','Hora','Mês','Serviço'];
var TIPOS_MOV  = ['entrada','saida','entrega','devolucao','transferencia','ajuste','perda','quebra','manutencao','retorno_manutencao','baixa','descarte'];
var STATUS_ITEM_UNIT = ['Disponível','Em uso','Em manutenção','Danificado','Perdido','Baixado','Fora de uso','Reservado'];

function patrimonioItemAtivo(it){ return !it || it.ativo !== false; }
function patrimonioFiltrarAtivo(lista, filtro){
  if(!filtro || filtro==='todos' || filtro==='') return lista||[];
  if(filtro==='ativos' || filtro==='true') return (lista||[]).filter(patrimonioItemAtivo);
  if(filtro==='inativos' || filtro==='false') return (lista||[]).filter(function(it){ return !patrimonioItemAtivo(it); });
  return lista||[];
}
function patrimonioToggleAtivo(opts){
  opts=opts||{};
  var it=(opts.arr||[]).find(function(x){ return String(x.id)===String(opts.id); });
  if(!it) return;
  var reativar=it.ativo===false;
  if(!reativar && !confirm('Inativar "'+(it.nome||'item')+'"?\n\nNão aparecerá em novas entregas/entradas. Histórico, fichas e movimentações anteriores permanecem intactos.')) return;
  it.ativo=reativar;
  if(!DEMO) sbUpdate(opts.tabela||'itens_catalogo',{ativo:reativar},'id=eq.'+opts.id);
  progShowToast(reativar?'✅ '+(opts.label||'Item')+' reativado':'⏸ '+(opts.label||'Item')+' inativado');
  if(opts.onDone) opts.onDone();
}
function patrimonioBtnToggleAtivo(id, ativo, fnName){
  if(ativo!==false){
    return '<button class="btn btn-sm" style="font-size:10px;color:#854F0B;border-color:#854F0B" onclick="'+fnName+'(\''+id+'\')" title="Ocultar de novas entregas">Inativar</button>';
  }
  return '<button class="btn btn-sm" style="font-size:10px;color:#3B6D11;border-color:#3B6D11" onclick="'+fnName+'(\''+id+'\')" title="Voltar a aparecer nas seleções">Reativar</button>';
}

/** Código canônico do tipo: sempre CAIXA ALTA (ex.: PNEU, MATERIAL, VESTIMENTA). */
function almTipoCodigo(t){
  if(!t) return '';
  var n = eeNormalizaTipo(t);
  if(!n) return '';
  return String(n).toUpperCase().replace(/[^A-Z0-9_]/g,'');
}
function almTiposItemSyncLista(){
  TIPOS_ITEM = (alm_tipos_item||[])
    .filter(function(t){ return t && t.ativo!==false && t.codigo; })
    .sort(function(a,b){ return (a.ordem||100)-(b.ordem||100) || String(a.codigo).localeCompare(String(b.codigo)); })
    .map(function(t){ return almTipoCodigo(t.codigo); })
    .filter(function(c,i,arr){ return c && arr.indexOf(c)===i; });
  if(TIPOS_ITEM.indexOf('PNEU')<0) TIPOS_ITEM.push('PNEU');
}
function almTiposItemAplicarLista(lista){
  var byCod = {};
  TIPOS_ITEM_DEFAULT.forEach(function(t){
    byCod[t.codigo] = Object.assign({ativo:true}, t);
  });
  (lista||[]).forEach(function(t){
    var cod = almTipoCodigo(t.codigo||t.nome_exibicao||'');
    if(!cod) return;
    byCod[cod] = {
      id: t.id,
      codigo: cod,
      nome_exibicao: String(t.nome_exibicao||cod).toUpperCase(),
      ativo: t.ativo!==false,
      ordem: t.ordem!=null ? Number(t.ordem) : 200,
      observacao: t.observacao||''
    };
  });
  if(!byCod.PNEU) byCod.PNEU = {codigo:'PNEU', nome_exibicao:'PNEU', ativo:true, ordem:95};
  alm_tipos_item = Object.keys(byCod).map(function(k){ return byCod[k]; });
  almTiposItemSyncLista();
  popularFiltroTiposItens();
}
async function almTiposItemLoad(){
  if(DEMO){
    almTiposItemAplicarLista(TIPOS_ITEM_DEFAULT);
    return alm_tipos_item;
  }
  try{
    var rows = await sbFetch('alm_tipos_item',{order:'ordem,codigo'});
    if(rows && rows.length) almTiposItemAplicarLista(rows);
    else almTiposItemAplicarLista(TIPOS_ITEM_DEFAULT);
  }catch(e){
    console.warn('alm_tipos_item:', e);
    almTiposItemAplicarLista(TIPOS_ITEM_DEFAULT);
  }
  return alm_tipos_item;
}
function popularFiltroTiposItens(){
  var sel = document.getElementById('itens-fil-tipo');
  if(!sel) return;
  var ant = sel.value||'';
  sel.innerHTML = '<option value="">TODOS OS TIPOS</option>'
    + TIPOS_ITEM.map(function(t){
        return '<option value="'+escHtml(t)+'">'+escHtml(tipoItemLabel(t))+'</option>';
      }).join('');
  if(ant && TIPOS_ITEM.some(function(t){ return eeTipoItemMatch(t, ant); })){
    var match = TIPOS_ITEM.find(function(t){ return eeTipoItemMatch(t, ant); });
    sel.value = match || '';
  } else {
    sel.value = '';
  }
}
function tipoItemLabel(t){
  if(!t) return '—';
  var cod = almTipoCodigo(t);
  var row = (alm_tipos_item||[]).find(function(x){ return almTipoCodigo(x.codigo)===cod; });
  if(row && row.nome_exibicao) return String(row.nome_exibicao).toUpperCase();
  var m={material:'MATERIAL',ferramenta:'FERRAMENTA',epi:'EPI',epc:'EPC',
    vestimenta:'UNIFORME',uniforme:'UNIFORME',equipamento:'EQUIPAMENTO',consumivel:'CONSUMÍVEL',
    peca:'PEÇA',kit:'KIT',outro:'OUTRO',pneu:'PNEU'};
  return m[eeNormalizaTipo(t)] || cod || String(t).toUpperCase() || '—';
}
function eeTipoItemMatch(itemTipo, filtroTipo){
  if(!filtroTipo) return true;
  return eeNormalizaTipo(itemTipo)===eeNormalizaTipo(filtroTipo);
}
function eeCatEstoqueMatch(estoqueTipo, filtroCat){
  if(!filtroCat) return true;
  var map={EPI:'epi',EPC:'epc',Material:'material',Uniforme:'vestimenta',Uniformes:'vestimenta',
    Ferramenta:'ferramenta','Consumível':'consumivel',Consumivel:'consumivel',Outros:'outro',PNEU:'pneu',Pneu:'pneu'};
  var ft=map[filtroCat]||String(filtroCat).toLowerCase();
  return eeTipoItemMatch(estoqueTipo, ft);
}

function openGerirTiposMateriais(){
  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:560px;max-height:90vh;overflow-y:auto">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">'
    +'<h3 style="margin:0">Tipos de Materiais</h3>'
    +'<button onclick="closeModal()" style="background:none;border:none;font-size:20px;cursor:pointer">✕</button>'
    +'</div>'
    +'<div style="background:#EBF4FD;border-radius:8px;padding:.5rem .75rem;margin-bottom:.75rem;font-size:11px;color:#185FA5">'
    +'Códigos e nomes são gravados em <b>CAIXA ALTA</b>. Use este cadastro para incluir (ex.: PNEU) ou atualizar tipos do Almoxarifado/Patrimônio.'
    +'</div>'
    +'<div id="lista-tipos-materiais" style="margin-bottom:1rem"></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1.2fr auto;gap:8px;align-items:end">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Código *</label>'
    +'<input class="inp" id="atm-codigo" placeholder="EX: PNEU" style="width:100%;text-transform:uppercase" '
    +'oninput="this.value=this.value.toUpperCase().replace(/[^A-Z0-9_]/g,\'\')"/></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Nome exibição *</label>'
    +'<input class="inp" id="atm-nome" placeholder="EX: PNEU" style="width:100%;text-transform:uppercase" '
    +'oninput="this.value=this.value.toUpperCase()"/></div>'
    +'<button class="btn btn-pri" onclick="almTiposItemSalvarNovo()">+ Adicionar</button>'
    +'</div>'
    +'<div class="ma" style="margin-top:1rem"><button class="btn" onclick="closeModal();popularFiltroTiposItens();renderItens();">Fechar</button></div>'
    +'</div></div>');
  renderListaTiposMateriais();
}
function renderListaTiposMateriais(){
  var el=document.getElementById('lista-tipos-materiais'); if(!el) return;
  var lista=(alm_tipos_item||[]).slice().sort(function(a,b){
    return (a.ordem||100)-(b.ordem||100) || String(a.codigo).localeCompare(String(b.codigo));
  });
  if(!lista.length){
    el.innerHTML='<div style="color:#888;font-size:12px;padding:8px">Nenhum tipo cadastrado.</div>';
    return;
  }
  el.innerHTML=lista.map(function(t){
    var cod=escHtml(t.codigo||'');
    var nome=escHtml(String(t.nome_exibicao||t.codigo||'').toUpperCase());
    var inativo=t.ativo===false;
    return '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 10px;background:'+(inativo?'#f3f3f1':'#f9f9f7')+';border-radius:8px;margin-bottom:5px;font-size:13px'+(inativo?';opacity:.65':'')+'">'
      +'<div style="min-width:0">'
      +'<div style="font-weight:700;letter-spacing:.02em">'+cod+'</div>'
      +'<div style="font-size:11px;color:#666">'+nome+(inativo?' · inativo':'')+'</div>'
      +'</div>'
      +'<div style="display:flex;gap:6px;flex-shrink:0">'
      +'<button class="btn btn-sm" onclick="almTiposItemEditar(\''+cod+'\')">Editar</button>'
      +'<button class="btn btn-sm" style="color:'+(inativo?'#3B6D11':'#854F0B')+';border-color:'+(inativo?'#3B6D11':'#854F0B')+'" '
      +'onclick="almTiposItemToggleAtivo(\''+cod+'\')">'+(inativo?'Reativar':'Inativar')+'</button>'
      +'</div></div>';
  }).join('');
}
async function almTiposItemSalvarNovo(){
  var cod = almTipoCodigo((document.getElementById('atm-codigo')||{}).value||'');
  var nome = String((document.getElementById('atm-nome')||{}).value||'').trim().toUpperCase() || cod;
  if(!cod){ alert('Informe o código do tipo (somente letras/números, CAIXA ALTA).'); return; }
  var existente = (alm_tipos_item||[]).find(function(t){ return almTipoCodigo(t.codigo)===cod; });
  if(existente){
    existente.nome_exibicao = nome;
    existente.ativo = true;
    if(!DEMO && existente.id){
      try{ await sbUpdate('alm_tipos_item',{nome_exibicao:nome,ativo:true,atualizado_em:new Date().toISOString()},'id=eq.'+existente.id); }
      catch(e){ progShowToast('Erro ao atualizar tipo: '+e.message,'erro'); return; }
    }
    almTiposItemSyncLista();
    renderListaTiposMateriais();
    popularFiltroTiposItens();
    progShowToast('✅ Tipo '+cod+' atualizado.');
    return;
  }
  var payload = {codigo:cod, nome_exibicao:nome, ativo:true, ordem:200};
  var row = Object.assign({}, payload);
  if(!DEMO){
    try{
      var r = await sbInsert('alm_tipos_item', payload);
      if(r&&r[0]) row = Object.assign(row, r[0], {codigo:cod, nome_exibicao:nome});
    }catch(e){
      progShowToast('Erro ao salvar tipo (rode sql_alm_tipos_item.sql?): '+e.message,'erro');
      return;
    }
  }
  alm_tipos_item.push(row);
  almTiposItemSyncLista();
  var cEl=document.getElementById('atm-codigo'); if(cEl) cEl.value='';
  var nEl=document.getElementById('atm-nome'); if(nEl) nEl.value='';
  renderListaTiposMateriais();
  popularFiltroTiposItens();
  progShowToast('✅ Tipo '+cod+' cadastrado.');
}
async function almTiposItemEditar(codigo){
  var cod = almTipoCodigo(codigo);
  var t = (alm_tipos_item||[]).find(function(x){ return almTipoCodigo(x.codigo)===cod; });
  if(!t) return;
  var novoNome = prompt('Nome de exibição (CAIXA ALTA):', String(t.nome_exibicao||t.codigo||'').toUpperCase());
  if(novoNome==null) return;
  novoNome = String(novoNome).trim().toUpperCase();
  if(!novoNome){ alert('Nome inválido.'); return; }
  t.nome_exibicao = novoNome;
  if(!DEMO && t.id){
    try{ await sbUpdate('alm_tipos_item',{nome_exibicao:novoNome,atualizado_em:new Date().toISOString()},'id=eq.'+t.id); }
    catch(e){ progShowToast('Erro ao editar: '+e.message,'erro'); return; }
  }
  renderListaTiposMateriais();
  popularFiltroTiposItens();
  if(typeof renderItens==='function') renderItens();
  progShowToast('✅ Tipo atualizado.');
}
async function almTiposItemToggleAtivo(codigo){
  var cod = almTipoCodigo(codigo);
  var t = (alm_tipos_item||[]).find(function(x){ return almTipoCodigo(x.codigo)===cod; });
  if(!t) return;
  var reativar = t.ativo===false;
  if(!reativar && !confirm('Inativar o tipo "'+cod+'"?\nItens já cadastrados permanecem; o tipo some das novas seleções.')) return;
  t.ativo = reativar;
  if(!DEMO && t.id){
    try{ await sbUpdate('alm_tipos_item',{ativo:reativar,atualizado_em:new Date().toISOString()},'id=eq.'+t.id); }
    catch(e){ t.ativo=!reativar; progShowToast('Erro: '+e.message,'erro'); return; }
  }
  almTiposItemSyncLista();
  renderListaTiposMateriais();
  popularFiltroTiposItens();
  progShowToast(reativar?'✅ Tipo reativado':'⏸ Tipo inativado');
}

function renderItens(){
  var tbody=document.getElementById('tbody-itens'); if(!tbody) return;
  var filtTipo  = (document.getElementById('itens-fil-tipo')||{}).value||'';
  var filtBusca = ((document.getElementById('itens-fil-busca')||{}).value||'').toLowerCase();
  var filtSt    = (document.getElementById('itens-fil-status')||{}).value;

  var lista = patrimonioFiltrarAtivo(itens_catalogo, filtSt).filter(function(i){
    if(filtTipo   && !eeTipoItemMatch(i.tipo_item, filtTipo) && !(eeNormalizaTipo(filtTipo)==='vestimenta' && eePareceUniformePorNome(i.nome))) return false;
    if(filtBusca  && !(i.nome||'').toLowerCase().includes(filtBusca)&&
                     !(i.codigo||'').toLowerCase().includes(filtBusca)) return false;
    return true;
  });

  if(!lista.length){
    tbody.innerHTML='<tr><td colspan="11" style="padding:2rem;text-align:center;color:#aaa">'
      +(itens_catalogo.length?'Nenhum item para os filtros.':'Nenhum item cadastrado. Use + Novo item.')
      +'</td></tr>';
    return;
  }

  function ic(v,sim,nao){ return v?'<span class="bdg ok" style="font-size:10px">'+(sim||'Sim')+'</span>':'<span class="bdg gray" style="font-size:10px">'+(nao||'Não')+'</span>'; }

  tbody.innerHTML = lista.map(function(it){
    return '<tr'+(it.ativo===false?' style="opacity:.55"':'')+'>'
      +'<td style="font-size:11px;color:#888">'+(it.codigo||'—')+'</td>'
      +'<td style="font-size:11px;color:#888">'+(it.sku||'—')+'</td>'
      +'<td style="font-weight:600">'+it.nome+'</td>'
      +'<td><span class="bdg info" style="font-size:10px">'+tipoItemLabel(it.tipo_item)+'</span></td>'
      +'<td style="font-size:11px;color:#888">'+(it.unidade_medida||'—')+'</td>'
      +'<td style="text-align:center">'+ic(it.controla_numero_serie)+'</td>'
      +'<td style="text-align:center">'+ic(it.controla_ca)+'</td>'
      +'<td style="text-align:center">'+ic(it.controla_validade)+'</td>'
      +'<td style="text-align:center">'+ic(it.controla_calibracao)+'</td>'
      +'<td style="text-align:center">'+ic(it.controla_devolucao)+'</td>'
      +'<td><span class="bdg '+(it.ativo!==false?'ok':'gray')+'" style="font-size:10px">'+(it.ativo!==false?'Ativo':'Inativo')+'</span></td>'
      +'<td style="display:flex;gap:3px;flex-wrap:wrap">'
      +'<button class="btn btn-sm" onclick="openCadastroItem(\''+it.id+'\')">Editar</button>'
      +patrimonioBtnToggleAtivo(it.id, it.ativo, 'catalogoToggleAtivo')
      +'<button class="btn btn-sm btn-pri" onclick="openEntradaItem(\''+it.id+'\')">+ Entrada</button>'
      +'</td>'
      +'</tr>';
  }).join('');
}
function catalogoToggleAtivo(id){
  patrimonioToggleAtivo({
    arr:itens_catalogo, id:id, tabela:'itens_catalogo', label:'Item',
    onDone:function(){ renderItens(); if(typeof renderFer==='function') renderFer(); if(typeof renderEstoque==='function') renderEstoque(); }
  });
}

function openCadastroItem(idOuTipo){
  var isEdit = idOuTipo && idOuTipo.length > 20;
  var it = isEdit ? itens_catalogo.find(function(x){return x.id===idOuTipo;}) : null;
  var tipoPresel = (!isEdit && idOuTipo) ? idOuTipo : '';

  function tipoOpts(){
    var atual = it?it.tipo_item:tipoPresel;
    return TIPOS_ITEM.map(function(t){
      var sel=eeTipoItemMatch(atual,t)?' selected':'';
      return '<option value="'+t+'"'+sel+'>'+tipoItemLabel(t)+'</option>';
    }).join('');
  }
  function unOpts(){
    var val=it?it.unidade_medida||'':'';
    var lista=UNIDADES_MEDIDA.slice();
    if(val && lista.indexOf(val)<0) lista.push(val);
    return lista.map(function(u){
      return '<option'+(u===val?' selected':'')+'>'+u+'</option>';
    }).join('');
  }
  function ck(campo){ return it&&it[campo]?' checked':''; }

  var html = '<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:560px">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">'
    +'<h3 style="margin:0">'+(isEdit?'✏️ Editar item':'🗂 Novo item — Cadastro único')+'</h3>'
    +'<button onclick="closeModal()" style="background:none;border:none;font-size:20px;cursor:pointer">✕</button>'
    +'</div>'
    +'<div style="display:flex;flex-direction:column;gap:.6rem">'

    // Código + SKU + Nome
    +'<div style="display:grid;grid-template-columns:120px 130px 1fr;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Código</label>'
    +'<input class="inp" id="ci-cod" style="width:100%" value="'+(it?it.codigo||'':'')+'" placeholder="Ex: FERR-001"/></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">SKU</label>'
    +'<input class="inp" id="ci-sku" style="width:100%" value="'+(it?it.sku||'':'')+'" placeholder="Ex: SKU-00123"/></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Nome *</label>'
    +'<input class="inp" id="ci-nome" style="width:100%" value="'+(it?it.nome||'':'')+'" placeholder="Ex: Alicate universal"/></div>'
    +'</div>'

    // Tipo + Unidade (com botão "Novo")
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Tipo *</label>'
    +'<div style="display:flex;gap:4px">'
    +'<select class="inp" id="ci-tipo" style="flex:1"><option value="">Selecione...</option>'+tipoOpts()+'</select>'
    +'<button class="btn btn-sm" onclick="ciAdicionarTipo()" title="Novo tipo" style="padding:0 8px;white-space:nowrap">+</button>'
    +'</div></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Unidade</label>'
    +'<div style="display:flex;gap:4px">'
    +'<select class="inp" id="ci-un" style="flex:1">'+unOpts()+'</select>'
    +'<button class="btn btn-sm" onclick="ciAdicionarUnidade()" title="Nova unidade" style="padding:0 8px;white-space:nowrap">+</button>'
    +'</div></div>'
    +'</div>'

    // Preço + Descrição
    +'<div style="display:grid;grid-template-columns:160px 1fr;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Preço unitário (R$)</label>'
    +'<input class="inp" id="ci-preco" type="number" step="0.01" min="0" style="width:100%" '
    +'value="'+(it&&it.preco_unitario?Number(it.preco_unitario).toFixed(2):'0.00')+'" '
    +'placeholder="0,00" title="Atualizado automaticamente na entrada de estoque"/></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Descrição / Observações</label>'
    +'<textarea class="inp" id="ci-desc" style="width:100%;height:36px">'+(it?it.descricao||'':'')+'</textarea></div>'
    +'</div>'
    +'<div style="font-size:10px;color:#888;margin-top:-4px">💡 O preço é atualizado automaticamente a cada nova entrada de estoque com pedido de compra.</div>'

    // Controles
    +'<div style="background:#f9f9f7;border-radius:8px;padding:.75rem">'
    +'<div style="font-size:11px;font-weight:700;color:#555;margin-bottom:.5rem">Controles do item</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.4rem">'
    +'<label style="display:flex;align-items:center;gap:6px;font-size:12px;cursor:pointer"><input type="checkbox" id="ci-estoque"'+ck('controla_estoque')+'/> Controla estoque</label>'
    +'<label style="display:flex;align-items:center;gap:6px;font-size:12px;cursor:pointer"><input type="checkbox" id="ci-serie"'+ck('controla_numero_serie')+'/> Controla nº de série</label>'
    +'<label style="display:flex;align-items:center;gap:6px;font-size:12px;cursor:pointer"><input type="checkbox" id="ci-validade"'+ck('controla_validade')+'/> Controla validade</label>'
    +'<label style="display:flex;align-items:center;gap:6px;font-size:12px;cursor:pointer"><input type="checkbox" id="ci-ca"'+ck('controla_ca')+'/> Controla CA</label>'
    +'<label style="display:flex;align-items:center;gap:6px;font-size:12px;cursor:pointer"><input type="checkbox" id="ci-calib"'+ck('controla_calibracao')+'/> Controla calibração</label>'
    +'<label style="display:flex;align-items:center;gap:6px;font-size:12px;cursor:pointer"><input type="checkbox" id="ci-devol"'+ck('controla_devolucao')+'/> Controla devolução</label>'
    +'<label style="display:flex;align-items:center;gap:6px;font-size:12px;cursor:pointer"><input type="checkbox" id="ci-manut"'+ck('controla_manutencao')+'/> Controla manutenção</label>'
    +'<label style="display:flex;align-items:center;gap:6px;font-size:12px;cursor:pointer"><input type="checkbox" id="ci-ativo"'+(it?(!it.ativo?'':' checked'):' checked')+'/> Item ativo</label>'
    +'</div></div>'

    +'</div>'
    +'<div style="display:flex;gap:8px;margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="ci-btn-salvar" style="flex:1">💾 '+(isEdit?'Salvar alterações':'Cadastrar item')+'</button>'
    +'</div></div></div>';

  setModal(html);

  // Funções de adicionar tipo/unidade dinamicamente
  window.ciAdicionarTipo = async function(){
    var novo = prompt('Novo tipo de material (CAIXA ALTA, ex: PNEU):');
    if(!novo || !novo.trim()) return;
    var cod = almTipoCodigo(novo);
    var nome = String(novo).trim().toUpperCase() || cod;
    if(!cod){ alert('Código inválido. Use apenas letras/números.'); return; }
    var existente = (alm_tipos_item||[]).find(function(t){ return almTipoCodigo(t.codigo)===cod; });
    if(!existente){
      var payload = {codigo:cod, nome_exibicao:nome, ativo:true, ordem:200};
      var row = Object.assign({}, payload);
      if(!DEMO){
        try{
          var r = await sbInsert('alm_tipos_item', payload);
          if(r&&r[0]) row = Object.assign(row, r[0], {codigo:cod, nome_exibicao:nome});
        }catch(e){
          progShowToast('Erro ao salvar tipo (rode sql_alm_tipos_item.sql?): '+e.message,'erro');
          return;
        }
      }
      alm_tipos_item.push(row);
    } else {
      existente.ativo = true;
      existente.nome_exibicao = nome;
    }
    almTiposItemSyncLista();
    popularFiltroTiposItens();
    var sel = document.getElementById('ci-tipo'); if(!sel) return;
    sel.innerHTML = '<option value="">Selecione...</option>'
      + TIPOS_ITEM.map(function(t){
          return '<option value="'+t+'"'+(t===cod?' selected':'')+'>'+tipoItemLabel(t)+'</option>';
        }).join('');
    sel.value = cod;
    progShowToast('✅ Tipo '+cod+' disponível.');
  };
  window.ciAdicionarUnidade = function(){
    var nova = prompt('Nova unidade de medida (ex: Peça, dz, pct):');
    if(!nova || !nova.trim()) return;
    nova = nova.trim();
    if(UNIDADES_MEDIDA.indexOf(nova)<0) UNIDADES_MEDIDA.push(nova);
    var sel = document.getElementById('ci-un'); if(!sel) return;
    var opt = document.createElement('option');
    opt.textContent = nova; opt.selected = true;
    sel.appendChild(opt);
  };

  var btn = document.getElementById('ci-btn-salvar');
  if(btn) btn.onclick = function(){
    var g  = function(id){ return (document.getElementById(id)||{}).value||''; };
    var gc = function(id){ return !!(document.getElementById(id)||{}).checked; };
    var nome = g('ci-nome').trim();
    var tipo = almTipoCodigo(g('ci-tipo'));
    if(!nome){ alert('Informe o nome do item.'); return; }
    if(!tipo){ alert('Selecione o tipo do item.'); return; }

    var payload = {
      codigo:                g('ci-cod'),
      sku:                   g('ci-sku'),
      nome:                  nome,
      tipo_item:             tipo,
      unidade_medida:        g('ci-un'),
      preco_unitario:        parseFloat(g('ci-preco'))||0,
      descricao:             g('ci-desc'),
      controla_estoque:      gc('ci-estoque'),
      controla_numero_serie: gc('ci-serie'),
      controla_validade:     gc('ci-validade'),
      controla_ca:           gc('ci-ca'),
      controla_calibracao:   gc('ci-calib'),
      controla_devolucao:    gc('ci-devol'),
      controla_manutencao:   gc('ci-manut'),
      ativo:                 gc('ci-ativo'),
      eh_pneu:               eeNormalizaTipo(tipo)==='pneu'
    };
    if(payload.eh_pneu) payload.controla_estoque = true;

    if(isEdit){
      var idx = itens_catalogo.findIndex(function(x){return x.id===idOuTipo;});
      if(idx>=0) Object.assign(itens_catalogo[idx], payload);
      if(!DEMO) sbUpdate('itens_catalogo', payload, 'id=eq.'+idOuTipo);
      progShowToast('✅ Item atualizado.');
    } else {
      var novo = Object.assign({id:'itm'+Date.now()}, payload);
      itens_catalogo.push(novo);
      if(!DEMO) sbInsert('itens_catalogo', payload).then(function(r){
        if(r&&r[0]&&r[0].id) novo.id=r[0].id;
      });
      progShowToast('✅ Item cadastrado.');
    }
    closeModal();
    renderItens(); renderFer(); renderEstoque();
  };
}

function openEntradaItem(itemId){
  var it = itens_catalogo.find(function(x){return x.id===itemId;});
  if(!it){ alert('Item não encontrado.'); return; }

  var depOpts = almBuildDepositoOpts('', 'Selecione o depósito de entrada...');
  var depOrigOpts = almBuildDepositoOpts('', 'Selecione o depósito de saída...');
  var contOrigOpts = '<option value="">Selecione o contrato de origem...</option>'
    + contratos.map(function(c){ return '<option value="'+c.id+'">'+escHtml(almContratoLabel(c,true))+'</option>'; }).join('');
  var contSapOpts = '<option value="">Selecione o contrato...</option>'
    + contratos.map(function(c){ return '<option value="'+c.id+'">'+escHtml(almContratoLabel(c,true))+'</option>'; }).join('');
  var pareceSapItem = eeLinhaPareceSap({nome:it.nome, codigo:it.codigo, sku:it.sku, tipo:it.tipo_item});
  var isPneuItem = pneusEhItemPneu(it);

  var html = '<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:520px">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">'
    +'<h3 style="margin:0">📥 Nova entrada — '+it.nome+'</h3>'
    +'<button onclick="closeModal()" style="background:none;border:none;font-size:20px;cursor:pointer">✕</button>'
    +'</div>'
    +'<div style="background:#EBF4FD;border-radius:8px;padding:.5rem .75rem;margin-bottom:.75rem;font-size:12px">'
    +'<span style="color:#888">Tipo:</span> <strong>'+tipoItemLabel(it.tipo_item)+'</strong>'
    +(isPneuItem?' &nbsp;·&nbsp; <span style="color:#3B6D11">Pneu — exige nº de fogo</span>':'')
    +(it.controla_numero_serie&&!isPneuItem?' &nbsp;·&nbsp; <span style="color:#185FA5">Controla nº de série</span>':'')
    +'</div>'
    +'<div style="background:#EBF4FD;border-radius:8px;padding:.45rem .75rem;margin-bottom:.6rem;font-size:11px;color:#185FA5">'
    +'ℹ️ <b>Compra / fornecedor externo:</b> origem = Externo (sem depósito de saída). Informe só o <b>depósito de entrada (destino)</b>.'
    +' Para material enviado pela concessionária (ENEL, Equatorial, Comgás), use o motivo <b>Remessa …</b>.</div>'
    +'<div style="background:#f9f9f7;border-radius:8px;padding:.55rem .65rem;border:.5px solid #e8e7e0;margin-bottom:.6rem">'
    +'<div style="font-size:11px;font-weight:700;margin-bottom:6px">Destino da entrada *</div>'
    +'<label style="display:flex;gap:8px;margin-bottom:4px;cursor:pointer;font-size:11px">'
    +'<input type="radio" name="ei-destino" value="patrimonial"'+(pareceSapItem?'':' checked')+' onchange="eiToggleDestinoEntrada()"/>'
    +'<span><b>📦 Patrimonial</b> — saldo por depósito</span></label>'
    +'<label style="display:flex;gap:8px;cursor:pointer;font-size:11px">'
    +'<input type="radio" name="ei-destino" value="sap"'+(pareceSapItem?' checked':'')+' onchange="eiToggleDestinoEntrada()"/>'
    +'<span><b>🏭 Materiais SAP</b> — saldo por contrato</span></label>'
    +(pareceSapItem?'<div style="font-size:10px;color:#854F0B;margin-top:4px">Código SAP detectado — destino SAP sugerido.</div>':'')
    +'</div>'
    +'<div style="display:flex;flex-direction:column;gap:.6rem">'

    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Quantidade *</label>'
    +'<input class="inp" id="ei-qtd" type="number" min="1" value="1" style="width:100%"'
    +(isPneuItem?' oninput="eiAtualizarFogos()"':(it.controla_numero_serie?' oninput="eiAtualizarSeries()"':''))+'/></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Data entrada *</label>'
    +'<input class="inp" id="ei-data" type="date" style="width:100%" value="'+dataHoje()+'"/></div>'
    +'</div>'

    +(isPneuItem
      ? '<div id="ei-fogos-wrap"><label style="font-size:11px;font-weight:600;display:block;margin-bottom:4px">Números de fogo * <span style="font-weight:400;color:#888">(1 por unidade)</span></label>'
        +'<div id="ei-fogos-campos"><input class="inp" style="width:100%;margin-bottom:4px;font-family:monospace;font-weight:700" placeholder="Fogo 1"/></div>'
        +'<div style="font-size:10px;color:#666;margin-top:2px">Cada fogo cria/vincula 1 ficha em Frotas · Pneus. Saldo fica no Almox.</div></div>'
        +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Valor unitário</label>'
        +'<input class="inp" id="ei-valor" type="number" step="0.01" value="0" style="width:100%"/></div>'
      : (it.controla_numero_serie
      ? '<div id="ei-series-wrap"><label style="font-size:11px;font-weight:600;display:block;margin-bottom:4px">Números de série *</label>'
        +'<div id="ei-series-campos"><input class="inp" style="width:100%;margin-bottom:4px" placeholder="Série 1"/></div></div>'
      : '<div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem">'
        +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Nº Série</label>'
        +'<div style="display:flex;align-items:center;gap:6px">'
        +'<input class="inp" id="ei-serie" style="flex:1" placeholder="Opcional"/>'
        +'<label style="display:flex;align-items:center;gap:4px;font-size:11px;white-space:nowrap;cursor:pointer">'
        +'<input type="checkbox" id="ei-na" onchange="document.getElementById(\'ei-serie\').disabled=this.checked;if(this.checked)document.getElementById(\'ei-serie\').value=\'N/A\'"/> N/A'
        +'</label></div></div>'
        +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Valor unitário</label>'
        +'<input class="inp" id="ei-valor" type="number" step="0.01" value="0" style="width:100%"/></div>'
        +'</div>'))

    +'<div id="ei-locais-wrap" style="background:#f9f9f7;border-radius:8px;padding:.55rem .65rem;border:.5px solid #e8e7e0;margin-bottom:.15rem">'
    +'<div style="font-size:11px;font-weight:700;color:#534AB7;margin-bottom:6px">Locais da movimentação</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem;margin-bottom:.6rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Origem do material</label>'
    +'<select class="inp" id="ei-orig-tipo" style="width:100%" data-nosort="1" onchange="eiToggleOrigDep()">'
    +'<option value="externo" selected>Externo / Fornecedor (sem depósito nosso)</option>'
    +'<option value="deposito">Transferência de outro depósito (interno)</option>'
    +'<option value="contrato">Retorno de contrato / obra</option>'
    +'</select></div>'
    +'<div id="ei-orig-dep-wrap" style="display:none"><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Depósito de origem (interno) *</label>'
    +'<select class="inp" id="ei-dep-orig" style="width:100%" data-nosort="1">'+depOrigOpts+'</select></div>'
    +'<div id="ei-orig-cont-wrap" style="display:none"><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Contrato de origem</label>'
    +'<select class="inp" id="ei-cont-orig" style="width:100%" data-nosort="1">'+contOrigOpts+'</select></div>'
    +'</div>'
    +'<div id="ei-wrap-pat-dep"><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Local de entrada (depósito destino) *</label>'
    +'<select class="inp" id="ei-dep" style="width:100%" data-nosort="1">'+depOpts+'</select></div>'
    +'<div id="ei-wrap-sap-cont" style="display:none"><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Contrato (destino SAP) *</label>'
    +'<select class="inp" id="ei-cont-sap" style="width:100%" data-nosort="1">'+contSapOpts+'</select></div>'
    +'</div>'

    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Fornecedor / origem externa</label>'
    +'<input class="inp" id="ei-forn" style="width:100%" placeholder="Opcional"/></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Nota fiscal</label>'
    +'<input class="inp" id="ei-nf" style="width:100%" placeholder="Opcional"/></div>'
    +'</div>'

    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Motivo</label>'
    +'<select class="inp" id="ei-motivo" style="width:100%" data-nosort="1" onchange="eiMotivoEntradaChange()">'
    + almMotivosEntradaHtml('Compra')
    +'</select></div>'

    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Observações</label>'
    +'<input class="inp" id="ei-obs" style="width:100%" placeholder="Opcional"/></div>'

    +'</div>'
    +'<div style="display:flex;gap:8px;margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="ei-btn-salvar" style="flex:1">💾 Registrar entrada</button>'
    +'</div></div></div>';

  setModal(html);

  window.eiMotivoEntradaChange = function(){
    var m = (document.getElementById('ei-motivo')||{}).value||'';
    var sug = almMotivoEntradaSugereFornecedor(m);
    var inp = document.getElementById('ei-forn');
    if(sug && inp && !inp.value.trim()) inp.value = sug;
  };

  window.eiToggleOrigDep = function(){
    var t = (document.getElementById('ei-orig-tipo')||{}).value||'externo';
    var dw = document.getElementById('ei-orig-dep-wrap');
    var cw = document.getElementById('ei-orig-cont-wrap');
    if(dw) dw.style.display = (t==='deposito'?'block':'none');
    if(cw) cw.style.display = (t==='contrato'?'block':'none');
  };
  window.eiToggleDestinoEntrada = function(){
    var dest = (document.querySelector('input[name="ei-destino"]:checked')||{}).value||'patrimonial';
    var wp = document.getElementById('ei-wrap-pat-dep');
    var ws = document.getElementById('ei-wrap-sap-cont');
    var locWrap = document.getElementById('ei-locais-wrap');
    if(wp) wp.style.display = dest==='sap' ? 'none' : '';
    if(ws) ws.style.display = dest==='sap' ? '' : 'none';
    if(locWrap && dest==='sap') locWrap.style.display = 'none';
    else if(locWrap) locWrap.style.display = '';
  };
  eiToggleOrigDep();
  eiToggleDestinoEntrada();

  // Fogos (pneu) ou séries dinâmicos
  if(isPneuItem){
    window.eiAtualizarFogos = function(){
      var qtd = parseInt((document.getElementById('ei-qtd')||{}).value)||1;
      var wrap = document.getElementById('ei-fogos-campos'); if(!wrap) return;
      while(wrap.querySelectorAll('input').length < qtd){
        var n = wrap.querySelectorAll('input').length+1;
        var inp = document.createElement('input');
        inp.className='inp'; inp.style.cssText='width:100%;margin-bottom:4px;font-family:monospace;font-weight:700';
        inp.placeholder='Fogo '+n; inp.dataset.idx=n-1;
        wrap.appendChild(inp);
      }
      while(wrap.querySelectorAll('input').length > qtd && wrap.querySelectorAll('input').length>1){
        wrap.removeChild(wrap.lastChild);
      }
    };
  } else if(it.controla_numero_serie){
    window.eiAtualizarSeries = function(){
      var qtd = parseInt((document.getElementById('ei-qtd')||{}).value)||1;
      var wrap = document.getElementById('ei-series-campos'); if(!wrap) return;
      var atual = wrap.querySelectorAll('input').length;
      while(wrap.querySelectorAll('input').length < qtd){
        var n = wrap.querySelectorAll('input').length+1;
        var inp = document.createElement('input');
        inp.className='inp'; inp.style.cssText='width:100%;margin-bottom:4px';
        inp.placeholder='Série '+n; inp.dataset.idx=n-1;
        wrap.appendChild(inp);
      }
      while(wrap.querySelectorAll('input').length > qtd && wrap.querySelectorAll('input').length>1){
        wrap.removeChild(wrap.lastChild);
      }
    };
  }

  var btnE = document.getElementById('ei-btn-salvar');
  if(btnE) btnE.onclick = async function(){
    var g  = function(id){ return (document.getElementById(id)||{}).value||''; };
    var qtd = parseInt(g('ei-qtd'))||1;
    var dest = (document.querySelector('input[name="ei-destino"]:checked')||{}).value||'patrimonial';
    var dep = g('ei-dep');
    var contSap = g('ei-cont-sap');
    var origTipo = g('ei-orig-tipo')||'externo';
    var depOrig = g('ei-dep-orig');
    var contOrig = g('ei-cont-orig');
    var motivo = g('ei-motivo');

    if(dest==='sap'){
      if(!contSap){ alert('Selecione o contrato para entrada SAP.'); return; }
      if(origTipo==='deposito'){ alert('Transferência interna só no estoque patrimonial.'); return; }
    } else {
      if(!dep){ alert('Selecione o local de entrada (depósito destino).'); return; }
      if(origTipo==='deposito'){
        if(!depOrig){ alert('Selecione o depósito de origem (transferência interna).'); return; }
        if(String(depOrig)===String(dep)){ alert('Depósito de origem e destino devem ser diferentes.'); return; }
      }
      if(origTipo==='contrato' && !contOrig){ alert('Selecione o contrato de origem.'); return; }
    }

    var linhaTest = {nome:it.nome, codigo:it.codigo, sku:it.sku, tipo:it.tipo_item};
    if(dest==='patrimonial' && eeLinhaPareceSap(linhaTest)){
      if(!confirm('Este item parece material SAP. Confirmar entrada no estoque PATRIMONIAL?')) return;
    }
    if(dest==='sap' && ['epi','epc','ferramenta','vestimenta'].indexOf(it.tipo_item)>=0 && !eeLinhaPareceSap(linhaTest)){
      if(!confirm('Item do catálogo SESMT — confirmar entrada como MATERIAIS SAP?')) return;
    }

    var fogosEntrada = [];
    if(isPneuItem && dest==='patrimonial' && origTipo!=='deposito'){
      var camposF = document.querySelectorAll('#ei-fogos-campos input');
      camposF.forEach(function(inp){ if(inp.value.trim()) fogosEntrada.push(inp.value.trim()); });
      var valF = pneusValidarListaFogosEntrada(fogosEntrada, qtd);
      if(!valF.ok){ alert(valF.msg); return; }
      fogosEntrada = valF.fogos;
      await pneusGarantirDadosCarregados();
    }

    var series = [];
    if(!isPneuItem && it.controla_numero_serie){
      var campos = document.querySelectorAll('#ei-series-campos input');
      campos.forEach(function(inp){ if(inp.value.trim()) series.push(inp.value.trim()); });
      if(series.length < qtd){ alert('Preencha todos os números de série.'); return; }
    }

    var depObj = (typeof depositos!=='undefined'?depositos:[]).find(function(d){ return String(d.id)===String(dep); });
    var filId = depObj ? depObj.filial_id : null;
    btnE.disabled = true;
    btnE.textContent = 'Salvando...';

    var r;
    if(dest==='sap'){
      r = await eeProcessarEntradaLinhaSap({
        nome: it.nome, codigo: it.codigo, sku: it.sku, qtd: qtd,
        custo: parseFloat(g('ei-valor'))||0, unidade: it.unidade_medida||'UN', tipo: it.tipo_item
      }, {
        contrato_id: contSap,
        lote: g('ei-nf'),
        forn: g('ei-forn'),
        motivo: motivo,
        obs: g('ei-obs'),
        data_mov: g('ei-data')||dataHoje()
      }, 0);
    } else if(origTipo==='deposito'){
      r = await almRegistrarTransferenciaPatrimonio({
        item_id: it.id,
        quantidade: qtd,
        deposito_origem_id: depOrig,
        deposito_destino_id: dep,
        data_mov: g('ei-data')||dataHoje(),
        obs: almJuntarObs(g('ei-obs'), motivo!=='Transferência interna'?('motivo:'+motivo):'')
      });
    } else {
      r = await almRegistrarEntradaPatrimonio({
        item_id: it.id,
        quantidade: qtd,
        deposito_id: dep,
        filial_id: filId,
        fornecedor: g('ei-forn'),
        nota_fiscal: g('ei-nf'),
        valor_unitario: parseFloat(g('ei-valor'))||0,
        data_mov: g('ei-data')||dataHoje(),
        motivo: motivo,
        obs: g('ei-obs'),
        numeros_serie: series.length ? JSON.stringify(series) : null,
        origem_tipo: origTipo,
        contrato_origem_id: contOrig||null
      });
      if(r.ok && isPneuItem && fogosEntrada.length){
        var rPn = await pneusCriarDaEntradaAlmox({
          fogos: fogosEntrada,
          itemCat: it,
          estoqueId: r.estoque_id||null,
          depositoId: dep,
          filialId: filId,
          custo: parseFloat(g('ei-valor'))||0
        });
        if(!rPn.ok){
          progShowToast('⚠ Entrada Almox OK, mas falha ao criar/vincular pneus: '+(rPn.msg||''), 'erro');
          console.warn('pneusCriarDaEntradaAlmox', rPn);
        } else if(rPn.erros && rPn.erros.length){
          progShowToast('⚠ Parcial: '+(rPn.criados||0)+' criados, '+(rPn.vinculados||0)+' vinculados. '+rPn.erros.join('; '), 'erro');
        }
      }
    }

    btnE.disabled = false;
    btnE.textContent = '💾 Registrar entrada';
    if(!r.ok){ progShowToast('❌ '+(r.msg||'Erro ao registrar'), 'erro'); return; }

    closeModal();
    progShowToast('✅ '+(dest==='sap'?'Entrada SAP':'Entrada')+' registrada: '+qtd+'x '+it.nome
      +(isPneuItem&&fogosEntrada.length?' · fogos: '+fogosEntrada.join(', '):''));
    if(dest==='sap'){
      if(typeof almCalcularSaldo==='function') almCalcularSaldo();
      if(typeof almRender==='function') almRender();
    } else {
      renderEstoque();
      renderFer();
      renderItens();
    }
  };
}

function openEntregaItem(tipoFiltro, itemIdPre){
  var itsFiltro = tipoFiltro
    ? itens_catalogo.filter(function(i){return i.tipo_item===tipoFiltro&&i.ativo!==false;})
    : itens_catalogo.filter(function(i){return i.ativo!==false;});
  var itemOpts = '<option value="">Selecione o item...</option>'
    + itsFiltro.map(function(i){
        return '<option value="'+i.id+'"'+(itemIdPre&&String(i.id)===String(itemIdPre)?' selected':'')+'>'+escHtml(i.nome)+'</option>';
      }).join('');
  var eqOpts = '<option value="">Sem equipe</option>'
    + (typeof equipes!=='undefined' ? equipes.map(function(e){
        return '<option value="'+e.id+'">'+(e.nome_equipe||e.nome||e.codigo)+'</option>';
      }).join('') : '');
  var depOpts = '<option value="">Selecione o depósito...</option>'
    + (typeof depositos!=='undefined' ? depositos.filter(function(d){ return d.ativo!==false && !d.deleted_at; }).map(function(d){
        var fil = (typeof filiais!=='undefined'?filiais:[]).find(function(f){ return f.id===d.filial_id; });
        return '<option value="'+d.id+'">'+escHtml(d.nome+(fil?' ('+(fil.codigo||fil.nome)+')':''))+'</option>';
      }).join('') : '');
  var contOpts = '<option value="">Selecione o contrato...</option>'
    + contratos.map(function(c){ return '<option value="'+c.id+'">'+escHtml(almContratoLabel(c,true))+'</option>'; }).join('');

  var html = '<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:540px">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">'
    +'<h3 style="margin:0">📤 Entrega de '+(tipoFiltro?tipoItemLabel(tipoFiltro):'item')+'</h3>'
    +'<button onclick="closeModal()" style="background:none;border:none;font-size:20px;cursor:pointer">✕</button>'
    +'</div>'
    +'<div style="background:#EBF4FD;border-radius:8px;padding:.5rem .75rem;margin-bottom:.6rem;font-size:11px;color:#185FA5">'
    +'ℹ️ Informe o <b>local de saída (depósito)</b> e o <b>local de destino (contrato)</b> da entrega.</div>'
    +'<div style="display:flex;flex-direction:column;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Item *</label>'
    +'<select class="inp" id="ent-item" style="width:100%" onchange="entAtualizarSaldoEntrega()">'+itemOpts+'</select></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Local de saída (depósito) *</label>'
    +'<select class="inp" id="ent-dep" style="width:100%" onchange="entAtualizarSaldoEntrega()">'+depOpts+'</select></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Local de destino (contrato) *</label>'
    +'<select class="inp" id="ent-cont" style="width:100%">'+contOpts+'</select></div>'
    +'</div>'
    +'<div id="ent-saldo-panel" style="font-size:11px;color:#555;background:#f9f9f7;border-radius:8px;padding:.55rem .65rem;border:.5px solid #e8e7e0"></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Quantidade *</label>'
    +'<input class="inp" id="ent-qtd" type="number" min="1" value="1" style="width:100%" oninput="entAtualizarSaldoEntrega()"/></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Data entrega</label>'
    +'<input class="inp" id="ent-data" type="date" value="'+dataHoje()+'" style="width:100%"/></div>'
    +'</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Colaborador</label>'
    +'<input type="hidden" id="ent-colab-id" value=""/>'
    +'<input class="inp" id="ent-colab-q" style="width:100%" placeholder="Digite nome ou RE..." autocomplete="off"'
    +' oninput="entFiltrarColaboradores()" onfocus="entFiltrarColaboradores()"'
    +' onkeydown="if(event.key===\'Enter\'){event.preventDefault();var m=almFiltrarColaboradoresEntrega(this.value,1)[0];if(m)entSelecionarColaborador(m.id,m.nome,m.contrato_id);}"/>'
    +'<div id="ent-colab-sug" style="display:none;border:.5px solid #D4D0F0;border-radius:6px;margin-top:2px;max-height:150px;overflow-y:auto;background:#fff"></div>'
    +'<div id="ent-colab-hint" style="font-size:10px;color:#888;margin-top:2px">Digite nome ou RE — clique na sugestão</div></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Equipe</label>'
    +'<select class="inp" id="ent-eq" style="width:100%">'+eqOpts+'</select></div>'
    +'</div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Previsão devolução</label>'
    +'<input class="inp" id="ent-prev" type="date" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Observações</label>'
    +'<input class="inp" id="ent-obs" style="width:100%" placeholder="Opcional"/></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px;margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="ent-btn-salvar" style="flex:1">📤 Confirmar entrega</button>'
    +'</div></div></div>';

  setModal(html);
  if(itemIdPre){
    var selItem = document.getElementById('ent-item');
    if(selItem) selItem.value = itemIdPre;
  }
  entAtualizarSaldoEntrega();

  var btn = document.getElementById('ent-btn-salvar');
  if(btn) btn.onclick = async function(){
    var g = function(id){ return (document.getElementById(id)||{}).value||''; };
    var itemId = g('ent-item'); var qtd = parseInt(g('ent-qtd'))||1;
    var depId = g('ent-dep'); var contId = g('ent-cont');
    if(!itemId){ alert('Selecione o item.'); return; }
    if(!depId){ alert('Selecione o depósito de origem.'); return; }
    if(!contId){ alert('Selecione o contrato da saída.'); return; }
    var colabId = entObterColaboradorEntrega();
    var colabTxt = ((document.getElementById('ent-colab-q')||{}).value||'').trim();
    if(colabTxt && !colabId){
      alert('Colaborador não identificado. Selecione na lista ou digite RE/nome mais específico.');
      entFiltrarColaboradores();
      return;
    }
    var depObj = (typeof depositos!=='undefined'?depositos:[]).find(function(d){ return String(d.id)===String(depId); });
    btn.disabled = true;
    btn.textContent = 'Salvando...';
    var r = await almRegistrarEntregaPatrimonio({
      item_id: itemId,
      quantidade: qtd,
      deposito_id: depId,
      filial_id: depObj ? depObj.filial_id : null,
      colaborador_id: colabId||null,
      equipe_id: g('ent-eq')||null,
      contrato_id: contId,
      previsao_devolucao: g('ent-prev')||null,
      data_mov: g('ent-data')||dataHoje(),
      obs: g('ent-obs')
    });
    btn.disabled = false;
    btn.textContent = '📤 Confirmar entrega';
    if(!r.ok){ progShowToast('❌ '+(r.msg||'Erro na entrega'), 'erro'); return; }
    closeModal();
    progShowToast('✅ Entrega registrada: '+r.qtd+'x '+r.nome);
    renderEstoque(); renderFer();
  };
}

function openDevolucaoItem(tipoFiltro){
  var entregues = movimentacoes_itens.filter(function(m){
    return m.tipo_mov==='entrega' && m.status==='Em uso';
  });
  var opts = '<option value="">Selecione a entrega...</option>'
    + entregues.map(function(m){
      var it = itens_catalogo.find(function(x){return x.id===m.item_id;});
      if(tipoFiltro && it && it.tipo_item!==tipoFiltro) return '';
      var colab = funcs.find(function(f){return f.id===m.colaborador_id;});
      if(!colab) colab = (colaboradores||[]).find(function(f){ return String(f.id)===String(almColaboradorIdFromMov(m)); });
      if(!colab && m.obs){
        var mt = (m.obs||'').match(/Colaborador:\s*([^|]+)/);
        if(mt) colab = {nome: mt[1].trim()};
      }
      return '<option value="'+m.id+'">'+(it?it.nome:'Item')+' → '+(colab?colab.nome:m.equipe_id||'—')+' ('+fmtD(m.data_mov)+')</option>';
    }).join('');
  var depDestOpts = almBuildDepositoOpts('', 'Selecione o depósito de entrada...');

  var html = '<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:520px">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">'
    +'<h3 style="margin:0">📥 Registrar devolução</h3>'
    +'<button onclick="closeModal()" style="background:none;border:none;font-size:20px;cursor:pointer">✕</button>'
    +'</div>'
    +'<div style="background:#EBF4FD;border-radius:8px;padding:.45rem .75rem;margin-bottom:.6rem;font-size:11px;color:#185FA5">'
    +'ℹ️ Informe de <b>onde sai</b> o material (origem da entrega) e para <b>qual depósito volta</b> (entrada).</div>'
    +'<div style="display:flex;flex-direction:column;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Entrega de origem *</label>'
    +'<select class="inp" id="dev-mov" style="width:100%" onchange="devAtualizarLocais()">'+opts+'</select></div>'
    +'<div id="dev-orig-panel" style="font-size:11px;background:#f9f9f7;border-radius:8px;padding:.55rem .65rem;border:.5px solid #e8e7e0;color:#555">'
    +'<span style="color:#888">Selecione a entrega para ver o local de saída.</span></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Local de entrada (depósito destino) *</label>'
    +'<select class="inp" id="dev-dep-dest" style="width:100%">'+depDestOpts+'</select></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Data devolução</label>'
    +'<input class="inp" id="dev-data" type="date" value="'+dataHoje()+'" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Condição *</label>'
    +'<select class="inp" id="dev-cond" style="width:100%">'
    +'<option>Bom estado</option><option>Com desgaste</option><option>Danificado</option>'
    +'<option>Quebrado</option><option>Perdido</option><option>Necessita manutenção</option>'
    +'<option>Fora de uso</option></select></div>'
    +'</div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Observações</label>'
    +'<input class="inp" id="dev-obs" style="width:100%" placeholder="Opcional"/></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px;margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="dev-btn" style="flex:1">💾 Confirmar devolução</button>'
    +'</div></div></div>';

  setModal(html);

  window.devAtualizarLocais = function(){
    var movId = (document.getElementById('dev-mov')||{}).value||'';
    var panel = document.getElementById('dev-orig-panel');
    var depSel = document.getElementById('dev-dep-dest');
    if(!panel) return;
    if(!movId){
      panel.innerHTML = '<span style="color:#888">Selecione a entrega para ver o local de saída.</span>';
      return;
    }
    var mov = (movimentacoes_itens||[]).find(function(m){ return String(m.id)===String(movId); });
    panel.innerHTML = '<div style="font-weight:600;color:#534AB7;margin-bottom:3px">Local de saída</div>'
      +'<div>'+escHtml(almLocalDevolucaoOrigem(mov))+'</div>';
    if(depSel && mov && mov.deposito_id && !depSel.value) depSel.value = mov.deposito_id;
  };

  var btn = document.getElementById('dev-btn');
  if(btn) btn.onclick = async function(){
    var g = function(id){ return (document.getElementById(id)||{}).value||''; };
    var movId = g('dev-mov'); if(!movId){ alert('Selecione a entrega.'); return; }
    var depDest = g('dev-dep-dest'); if(!depDest){ alert('Selecione o depósito de entrada (destino).'); return; }
    var cond = g('dev-cond');
    btn.disabled = true;
    btn.textContent = 'Salvando...';
    var r = await almRegistrarDevolucaoPatrimonio({
      movimentacao_origem_id: movId,
      deposito_destino_id: depDest,
      condicao: cond,
      data_mov: g('dev-data')||dataHoje(),
      obs: g('dev-obs')
    });
    btn.disabled = false;
    btn.textContent = '💾 Confirmar devolução';
    if(!r.ok){ progShowToast('❌ '+(r.msg||'Erro na devolução'), 'erro'); return; }
    closeModal();
    progShowToast('✅ Devolução registrada · entrada: '+almDepositoLabel(r.deposito_destino)+(almDevolucaoRetornaEstoque(cond)?' (estoque reposto)':''));
    renderEstoque(); renderFer();
  };
}

function openTransferenciaItem(tipoFiltro){
  var itsFiltro = tipoFiltro
    ? itens_catalogo.filter(function(i){return i.tipo_item===tipoFiltro&&i.ativo!==false;})
    : itens_catalogo.filter(function(i){return i.ativo!==false;});
  var itemOpts = '<option value="">Selecione o item...</option>'
    + itsFiltro.map(function(i){ return '<option value="'+i.id+'">'+escHtml(i.nome)+'</option>'; }).join('');
  var depOpts = almBuildDepositoOpts('', 'Selecione...');

  var html = '<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:520px">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">'
    +'<h3 style="margin:0">🔀 Transferência entre depósitos</h3>'
    +'<button onclick="closeModal()" style="background:none;border:none;font-size:20px;cursor:pointer">✕</button>'
    +'</div>'
    +'<div style="background:#EBF4FD;border-radius:8px;padding:.45rem .75rem;margin-bottom:.6rem;font-size:11px;color:#185FA5">'
    +'ℹ️ Informe o <b>local de saída</b> e o <b>local de entrada</b> (depósitos diferentes).</div>'
    +'<div style="display:flex;flex-direction:column;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Item *</label>'
    +'<select class="inp" id="trf-item" style="width:100%">'+itemOpts+'</select></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Local de saída (depósito origem) *</label>'
    +'<select class="inp" id="trf-dep-orig" style="width:100%">'+depOpts+'</select></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Local de entrada (depósito destino) *</label>'
    +'<select class="inp" id="trf-dep-dest" style="width:100%">'+depOpts+'</select></div>'
    +'</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Quantidade *</label>'
    +'<input class="inp" id="trf-qtd" type="number" min="1" value="1" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Data</label>'
    +'<input class="inp" id="trf-data" type="date" value="'+dataHoje()+'" style="width:100%"/></div>'
    +'</div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Observações</label>'
    +'<input class="inp" id="trf-obs" style="width:100%" placeholder="Opcional"/></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px;margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="trf-btn" style="flex:1">🔀 Confirmar transferência</button>'
    +'</div></div></div>';

  setModal(html);

  var btn = document.getElementById('trf-btn');
  if(btn) btn.onclick = async function(){
    var g = function(id){ return (document.getElementById(id)||{}).value||''; };
    var itemId = g('trf-item');
    var depOrig = g('trf-dep-orig');
    var depDest = g('trf-dep-dest');
    var qtd = parseInt(g('trf-qtd'))||0;
    if(!itemId){ alert('Selecione o item.'); return; }
    if(!depOrig){ alert('Selecione o local de saída.'); return; }
    if(!depDest){ alert('Selecione o local de entrada.'); return; }
    if(String(depOrig)===String(depDest)){ alert('Depósitos de saída e entrada devem ser diferentes.'); return; }
    if(qtd<=0){ alert('Quantidade inválida.'); return; }
    btn.disabled = true;
    btn.textContent = 'Salvando...';
    var r = await almRegistrarTransferenciaPatrimonio({
      item_id: itemId,
      quantidade: qtd,
      deposito_origem_id: depOrig,
      deposito_destino_id: depDest,
      data_mov: g('trf-data')||dataHoje(),
      obs: g('trf-obs')
    });
    btn.disabled = false;
    btn.textContent = '🔀 Confirmar transferência';
    if(!r.ok){ progShowToast('❌ '+(r.msg||'Erro na transferência'), 'erro'); return; }
    closeModal();
    progShowToast('✅ Transferência: '+r.qtd+'x '+r.nome+' · '+almDepositoLabel(depOrig)+' → '+almDepositoLabel(depDest));
    renderEstoque(); renderFer();
  };
}

