function renderFer(){
  var tbody=document.getElementById('tbody-fer'); if(!tbody) return;
  var q  = ((document.getElementById('fil-fer-q')||{}).value||'').toLowerCase();
  var st = (document.getElementById('fil-fer-status')||{}).value||'';

  // Filtrar itens do tipo ferramenta
  var ferramentasCat = itens_catalogo.filter(function(i){
    return i.tipo_item==='ferramenta' && i.ativo!==false
      && (!q || (i.nome||'').toLowerCase().includes(q) || (i.codigo||'').toLowerCase().includes(q) || (i.sku||'').toLowerCase().includes(q));
  });

  // Calcular saldos por item
  function saldo(itemId, tipoSt){
    return movimentacoes_itens.filter(function(m){
      return m.item_id===itemId && m.status===tipoSt;
    }).reduce(function(s,m){ return s+(m.quantidade||1); }, 0);
  }
  function saldoTotal(itemId){
    var it = itens_catalogo.find(function(x){ return x.id===itemId; });
    return it ? almSaldoEstoqueItem(it, null) : almCalcularSaldoMovimentacoes(itemId);
  }

  var lista = ferramentasCat.filter(function(i){
    if(!st) return true;
    var disp = saldoTotal(i.id); var emUso = saldo(i.id,'Em uso'); var manut = saldo(i.id,'Em manutenção');
    if(st==='Disponível') return disp > 0;
    if(st==='Em uso') return emUso > 0;
    if(st==='Em manutenção') return manut > 0;
    return true;
  });

  // Métricas
  var totalItens = ferramentasCat.length;
  var totalDisp  = ferramentasCat.filter(function(i){return saldoTotal(i.id)>0;}).length;
  var totalUso   = ferramentasCat.filter(function(i){return saldo(i.id,'Em uso')>0;}).length;
  var totalManut = ferramentasCat.filter(function(i){return saldo(i.id,'Em manutenção')>0;}).length;
  ['fer-total','fer-disp','fer-uso','fer-manut'].forEach(function(id,i){
    var el=document.getElementById(id);
    if(el) el.textContent=[totalItens,totalDisp,totalUso,totalManut][i];
  });

  if(!lista.length){
    tbody.innerHTML='<tr><td colspan="9" style="padding:2rem;text-align:center;color:#aaa">'
      +(itens_catalogo.filter(function(i){return i.tipo_item==='ferramenta';}).length
        ?'Nenhuma ferramenta para os filtros.':'Nenhuma ferramenta cadastrada. Use + Nova ferramenta.')
      +'</td></tr>';
    return;
  }

  tbody.innerHTML = lista.map(function(i){
    var disp = saldoTotal(i.id); var uso = saldo(i.id,'Em uso'); var manut = saldo(i.id,'Em manutenção');
    var stCor = disp>0?'#3B6D11':uso>0?'#185FA5':'#854F0B';
    var stLabel = disp>0?'Disponível':uso>0?'Em uso':'S/ saldo';
    return '<tr>'
      +'<td style="font-weight:600">'+i.nome+'<div style="font-size:10px;color:#888">'+(i.codigo||'')+'</div></td>'
      +'<td style="font-size:11px;color:#888;font-family:monospace">'+(i.codigo||'—')+'</td>'
      +'<td style="font-size:11px;color:#888;font-family:monospace">'+(i.sku||'—')+'</td>'
      +'<td style="font-size:11px;color:#888">'+(i.controla_numero_serie?'<span class="bdg info" style="font-size:10px">Com série</span>':'N/A')+'</td>'
      +'<td style="text-align:right;font-weight:700;color:'+stCor+'">'+disp+'</td>'
      +'<td style="text-align:right;color:#185FA5">'+uso+'</td>'
      +'<td style="text-align:right;color:#854F0B">'+manut+'</td>'
      +'<td><span style="font-size:11px;font-weight:600;color:'+stCor+'">'+stLabel+'</span></td>'
      +'<td style="display:flex;gap:3px">'
      +'<button class="btn btn-sm btn-pri" onclick="openEntradaItem(\''+i.id+'\')">+ Entrada</button>'
      +'<button class="btn btn-sm" onclick="openEntregaItemDireto(\''+i.id+'\')">Entregar</button>'
      +'</td></tr>';
  }).join('');
}

function openEntregaItemDireto(itemId){
  var it = itens_catalogo.find(function(x){return x.id===itemId;});
  if(!it){ progShowToast('Item não encontrado no catálogo.','erro'); return; }
  openEntregaItem(it.tipo_item||'ferramenta', itemId);
}

function saldoItem(itemId){
  var ent = movimentacoes_itens.filter(function(m){return m.item_id===itemId&&m.tipo_mov==='entrada';})
              .reduce(function(s,m){return s+(m.quantidade||1);},0);
  var sai = movimentacoes_itens.filter(function(m){
              return m.item_id===itemId
                &&['entrega','ajuste','perda','quebra','baixa','descarte'].includes(m.tipo_mov)
                &&m.status!=='Devolvido';
            }).reduce(function(s,m){return s+(m.quantidade||1);},0);
  var dev = movimentacoes_itens.filter(function(m){
              return m.item_id===itemId&&m.tipo_mov==='devolucao'&&m.status==='Disponível';
            }).reduce(function(s,m){return s+(m.quantidade||1);},0);
  return Math.max(0, ent - sai + dev);
}

function iniciarAbaItens(){
  var carregar = DEMO
    ? Promise.resolve(almTiposItemAplicarLista(TIPOS_ITEM_DEFAULT))
    : almTiposItemLoad();
  carregar.then(function(){
    if(!DEMO){
      return Promise.all([
        sbFetchAll('itens_catalogo',{order:'nome.asc',maxPages:20}),
        typeof almCarregarMovimentacoesEstoque==='function'
          ? almCarregarMovimentacoesEstoque()
          : sbFetchAll('movimentacoes_itens',{order:'data_mov.desc',maxPages:30})
      ]).then(function(res){
        if(res[0]&&res[0].length) itens_catalogo=res[0];
        if(res[1]&&res[1].length){
          movimentacoes_itens=typeof almMergeMovimentacoes==='function'
            ? almMergeMovimentacoes([movimentacoes_itens, res[1]])
            : res[1];
        }
      });
    }
  }).then(function(){ renderItens(); }).catch(function(){ popularFiltroTiposItens(); renderItens(); });
}

