function adicionarTipo(){
  var inp=document.getElementById('novo-tipo');
  var val=inp?inp.value.trim():'';
  if(!val)return;
  if(tiposLocacao.indexOf(val)>=0){alert('Tipo já existe!');return;}
  tiposLocacao.push(val);if(inp)inp.value='';renderListaTipos();
}
function removerTipo(i){
  if(!confirm('Remover este tipo?'))return;
  tiposLocacao.splice(i,1);renderListaTipos();
}
function lcDispHasStatus(d, s){
  if(!d) return false;
  var p=null; try{p=JSON.parse(d);}catch(e){}
  if(p&&typeof p==='object'){
    // Formato aninhado {cid:{status:qty}}
    var fv=p[Object.keys(p)[0]];
    if(fv&&typeof fv==='object') return Object.values(p).some(function(o){return o&&(Number(o[s])||0)>0;});
    return (Number(p[s])||0)>0;
  }
  return d===s;
}
function lcDispBadges(d, dc){
  if(!d) return '<span class="bdg gray" style="font-size:10px">—</span>';
  var p=null; try{p=JSON.parse(d);}catch(e){}
  if(p&&typeof p==='object'){
    // Formato aninhado {cid:{status:qty}} → agregar
    var fv=p[Object.keys(p)[0]];
    if(fv&&typeof fv==='object'){
      var agg={};
      Object.values(p).forEach(function(o){Object.keys(o).forEach(function(k){agg[k]=(agg[k]||0)+Number(o[k]||0);});});
      p=agg;
    }
    var parts=Object.keys(p).filter(function(k){return Number(p[k])>0;});
    if(!parts.length) return '<span class="bdg gray" style="font-size:10px">—</span>';
    return parts.map(function(k){return '<span class="bdg '+(dc[k]||'gray')+'" style="font-size:9px">'+p[k]+' '+k+'</span>';}).join(' ');
  }
  return '<span class="bdg '+(dc[d]||'gray')+'" style="font-size:10px">'+d+'</span>';
}

function _lcFornOptsHtml(q, selectedId){
  q=(q||'').toLowerCase().trim();
  var sid=selectedId?String(selectedId):'';
  var lst=frtFornecedoresLista();
  var shown={};
  function match(f){
    if(!q) return true;
    var rs=(f.razao_social||'').toLowerCase();
    var qd=q.replace(/\D/g,'');
    var cnpj=(f.cnpj_cpf||'').replace(/\D/g,'');
    return rs.indexOf(q)>=0 || (qd.length>=3 && cnpj.indexOf(qd)>=0);
  }
  function opt(f, erp, force){
    if(!f||!f.id) return '';
    if(!force && !match(f)) return '';
    if(shown[f.id]) return '';
    shown[f.id]=1;
    var rs=f.razao_social||'';
    var lbl=rs+(f.cnpj_cpf?' — '+f.cnpj_cpf:'')+(erp?' [ERP]':'');
    var sel=(sid&&String(f.id)===sid)?' selected':'';
    return '<option value="'+f.id+'" data-razao="'+escHtml(rs)+'"'+sel+'>'+escHtml(lbl)+'</option>';
  }
  var html='<option value="">— Selecione a locadora —</option>';
  lst.db.forEach(function(f){ html+=opt(f,false,false); });
  if(lst.erp.length){
    html+='<optgroup label="ERP CenaBR (cadastra ao salvar)">';
    lst.erp.forEach(function(f){ html+=opt(f,true,false); });
    html+='</optgroup>';
  }
  if(sid&&!shown[sid]){
    var fSel=_fornFindById(sid);
    if(fSel) html+=opt(fSel, String(sid).indexOf('_erp_')===0, true);
  }
  return html;
}
function _lcFornCampoHtml(selectedId, locadoraText, colSpan){
  var qVal='';
  if(selectedId){
    var f=_fornFindById(selectedId);
    if(f) qVal=f.razao_social||'';
  } else if(locadoraText) qVal=locadoraText;
  var span=colSpan?' style="grid-column:span '+colSpan+'"':'';
  return '<div class="fg"'+span+'>'
    +'<label style="font-size:11px">Locadora * <span style="font-weight:400;color:#888">(cadastro fornecedores)</span></label>'
    +'<input class="inp" id="lc-forn-q" placeholder="Buscar razão social ou CNPJ..." style="width:100%;font-size:11px;margin-bottom:4px" value="'+escHtml(qVal)+'" oninput="lcFiltrarFornOpts()"/>'
    +'<select class="inp" id="lc-forn-sel" size="5" style="width:100%;font-size:11px" onchange="lcFornSelSync()">'
    +_lcFornOptsHtml(qVal, selectedId)
    +'</select></div>';
}
function lcFiltrarFornOpts(){
  var q=(document.getElementById('lc-forn-q')||{}).value||'';
  var sel=document.getElementById('lc-forn-sel'); if(!sel) return;
  var prev=sel.value;
  sel.innerHTML=_lcFornOptsHtml(q, prev||null);
  if(prev && Array.prototype.some.call(sel.options,function(o){return o.value===prev;})) sel.value=prev;
}
function lcFornSelSync(){
  var sel=document.getElementById('lc-forn-sel');
  var q=document.getElementById('lc-forn-q');
  if(!sel||!q||!sel.value) return;
  var opt=sel.options[sel.selectedIndex];
  if(opt) q.value=opt.getAttribute('data-razao')||'';
}
function _lcPreencherFornSelect(fornecedorId, locadoraText){
  var sel=document.getElementById('lc-forn-sel');
  var q=document.getElementById('lc-forn-q');
  if(!sel) return;
  var fid=fornecedorId||null;
  var qText=String(locadoraText||'').trim();
  if(!fid&&qText){
    var r=_fornResolverPorTexto(qText);
    if(r.id&&(r.motivo==='Nome exato'||r.motivo==='CNPJ')) fid=r.id;
  }
  if(q){
    if(fid){
      var f=_fornFindById(fid);
      q.value=f?(f.razao_social||qText):qText;
    } else {
      q.value=qText;
    }
  }
  lcFiltrarFornOpts();
  if(fid&&Array.prototype.some.call(sel.options,function(o){ return String(o.value)===String(fid); })){
    sel.value=fid;
    lcFornSelSync();
  }
}
function _lcDateInput(v){
  if(v==null||v==='') return '';
  var s=String(v).trim();
  if(/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0,10);
  var m=s.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
  if(m) return m[3]+'-'+m[2]+'-'+m[1];
  return s.slice(0,10);
}
function _lcBool(v){ return v===true||v==='true'||v===1||v==='1'; }
function _lcObsLimpa(l){
  var obs=(l&&l.observacoes)||'';
  if(l&&l.numero_contrato) return obs.replace(/^Contrato:\s*[^|]+\|\s*/i,'').trim();
  var m=obs.match(/^Contrato:\s*[^|]+\|\s*(.*)/is);
  return m?m[1].trim():obs;
}
function _lcNumContrato(l){
  if(!l) return '';
  if(l.numero_contrato) return String(l.numero_contrato).trim();
  var m=(l.observacoes||'').match(/Contrato:\s*([^|]+)/i);
  return m?m[1].trim():'';
}
function _lcFindLoc(id){
  return (locacoes||[]).find(function(x){ return String(x.id)===String(id); });
}
function _lcResolveRespId(l){
  if(!l) return null;
  if(l.responsavel_id) return l.responsavel_id;
  // Só busca por nome em funcionarios (funcs) — colaboradores têm FK diferente
  var t=String(l.responsavel||'').trim().toLowerCase();
  if(!t) return null;
  var c=(funcs||[]).find(function(x){ return (x.nome||'').trim().toLowerCase()===t; });
  return (c && !c.re) ? c.id : null;
}
function _lcPickCampoGrupo(itens, campo){
  var counts={}, best=null, bestN=0;
  (itens||[]).forEach(function(i){
    var v=i[campo];
    if(v==null||v==='') return;
    var k=String(v);
    counts[k]=(counts[k]||0)+1;
    if(counts[k]>bestN){ bestN=counts[k]; best=k; }
  });
  return best;
}
function _lcFilialNome(fid){
  if(!fid) return '';
  var f=(filiais||[]).find(function(x){ return String(x.id)===String(fid); });
  if(!f) return '';
  return (f.codigo?f.codigo+' — ':'')+(f.nome||'');
}
function _lcDepositoNome(did){
  if(!did) return '';
  var d=(depositos||[]).find(function(x){ return String(x.id)===String(did); });
  return d?(d.nome||''):'';
}
function _lcSincronizarFilialDep(filialId, depositoId){
  var filEl=document.getElementById('lc-fil');
  var depEl=document.getElementById('lc-dep');
  if(filEl){
    if(filialId){
      filEl.value=String(filialId);
      if(filEl.value!==String(filialId)){
        var fn=_lcFilialNome(filialId)||('Filial '+filialId);
        var o=document.createElement('option');
        o.value=String(filialId); o.textContent=fn;
        filEl.appendChild(o);
        filEl.value=String(filialId);
      }
    } else {
      filEl.value='';
    }
  }
  lcAtualizarDepositos('lc-dep', depositoId||'');
}
function _lcGrupoCabecalho(itens){
  var g=Object.assign({}, itens[0]);
  g.inicio=_lcDateInput(g.inicio);
  g.termino=_lcDateInput(g.termino);
  g.tem_seguro=_lcBool(g.tem_seguro);
  g.numero_contrato=_lcNumContrato(g);
  itens.forEach(function(i){
    if(!g.numero_contrato) g.numero_contrato=_lcNumContrato(i);
    if(!g.fornecedor_id&&i.fornecedor_id) g.fornecedor_id=i.fornecedor_id;
    if(!g.responsavel&&i.responsavel) g.responsavel=i.responsavel;
    else if(!g.responsavel&&i.responsavel_id){
      var _rn=_lcRespNomeById(i.responsavel_id);
      if(_rn) g.responsavel=_rn;
    }
    if(!g.locadora&&i.locadora) g.locadora=i.locadora;
  });
  g.filial_id=_lcPickCampoGrupo(itens,'filial_id')||g.filial_id||null;
  g.deposito_id=_lcPickCampoGrupo(itens,'deposito_id')||g.deposito_id||null;
  g.observacoes=_lcObsLimpa(g);
  return g;
}
var _lcModalGen=0;
function _lcFetchLoc(id){
  var sid=String(id||'').trim();
  if(!sid) return Promise.resolve(null);
  var mem=_lcFindLoc(sid);
  if(DEMO) return Promise.resolve(mem);
  return sbFetch('locacoes',{filters:['id=eq.'+sid]}).then(function(rows){
    var row=rows&&rows[0];
    if(!row) return mem||null;
    var idx=(locacoes||[]).findIndex(function(x){ return String(x.id)===sid; });
    if(idx>=0) Object.assign(locacoes[idx], row);
    else locacoes.push(row);
    return locacoes[idx>=0?idx:locacoes.length-1];
  }).catch(function(){ return mem||null; });
}
function _lcSnapFromLoc(l){
  if(!l) return null;
  return {
    id:l.id, nome:l.nome||'', locadora:l.locadora||'', fornecedor_id:l.fornecedor_id||null,
    filial_id:l.filial_id||null, deposito_id:l.deposito_id||null,
    responsavel_id:null,
    responsavel:(function(){ var t=_lcRespTexto(l); return t==='—'?'':t; })(),
    inicio:_lcDateInput(l.inicio), termino:_lcDateInput(l.termino),
    quantidade:Number(l.quantidade||1),
    valor_unitario:Number(l.valor_unitario||0)||(Number(l.quantidade||1)?Number(l.valor_locacao||0)/Number(l.quantidade||1):Number(l.valor_locacao||0)),
    valor_locacao:Number(l.valor_locacao||0),
    numero_contrato:_lcNumContrato(l),
    tem_seguro:_lcBool(l.tem_seguro), valor_seguro:l.valor_seguro,
    status:l.status||'', disponibilidade:l.disponibilidade,
    observacoes:_lcObsLimpa(l), documentos:l.documentos,
    contrato_id:l.contrato_id||null, contrato_qtds:l.contrato_qtds, tipo:l.tipo
  };
}
function _lcDispQtdsFromLoc(l){
  var opts=['Disponível','Em uso','Em manutenção','Devolvido','Extraviado'];
  var qtds={}; opts.forEach(function(s){ qtds[s]=0; });
  var raw=l&&l.disponibilidade;
  if(!raw) return qtds;
  var p=null;
  try{ p=(typeof raw==='object')?raw:JSON.parse(raw); }catch(e){ p=null; }
  if(p&&typeof p==='object'&&!Array.isArray(p)){
    var fv=p[Object.keys(p)[0]];
    if(fv&&typeof fv==='object'&&!Array.isArray(fv)){
      var agg={};
      Object.values(p).forEach(function(o){
        if(o&&typeof o==='object') Object.keys(o).forEach(function(k){ agg[k]=(agg[k]||0)+Number(o[k]||0); });
      });
      p=agg;
    }
    Object.keys(p).forEach(function(k){ if(qtds.hasOwnProperty(k)) qtds[k]=Number(p[k])||0; });
  } else if(typeof raw==='string'&&qtds.hasOwnProperty(raw)) {
    qtds[raw]=Number(l&&l.quantidade)||1;
  }
  return qtds;
}
function _lcLerFornecedorForm(){
  var sel=document.getElementById('lc-forn-sel');
  var fid=(sel&&sel.value)||'';
  if(!fid){
    var q=((document.getElementById('lc-forn-q')||{}).value||'').trim();
    if(!q){ progShowToast('⚠ Selecione a locadora no cadastro de fornecedores.'); return Promise.reject(new Error('locadora')); }
    var r=_fornResolverPorTexto(q);
    if(r.id) return Promise.resolve({ fornecedor_id:r.id, locadora:r.razao_social });
    progShowToast('⚠ Locadora não encontrada no cadastro. Cadastre em Fornecedores ou selecione na lista.');
    return Promise.reject(new Error('locadora'));
  }
  var opt=sel.options[sel.selectedIndex];
  var loc=(opt&&opt.getAttribute('data-razao'))||'';
  if(String(fid).indexOf('_erp_')===0){
    return frtResolverFornecedorId(fid).then(function(realId){
      return { fornecedor_id:realId, locadora:loc };
    });
  }
  return Promise.resolve({ fornecedor_id:fid, locadora:loc });
}
var _LC_CARGO_RESP=/gestor|coordenador|supervisor|gerente|ger[eê]ncia|diretor|administr/i;
var _LC_CAT_RESP=/gest[aã]o|supervis[aã]o|coordena[cç][aã]o|ger[eê]ncia|administr/i;
var _LC_CARGO_CAMPO=/pedreiro|eletricist|auxiliar de|mec[aâ]nic|operador de|montador|servente|soldador|encanador|t[eé]cnic[oa] de campo|oper[aá]ri|ajudante|carregador|motorista|pintor|gesseiro|armador|carpinteiro|top[oó]graf|serralheiro|padeiro|jardineiro|faxineir|zelador|office boy|office-boy|estagi[aá]ri[oa]/i;
function _lcCargoCategoria(cargoNome){
  var c=(_cad_cargos||[]).find(function(x){ return x.nome===(cargoNome||''); });
  return c?(c.categoria||''):'';
}
function _lcEhResponsavelValido(f){
  if(!f||f.ativo===false) return false;
  var cargo=String(f.cargo||'').trim();
  var cat=_lcCargoCategoria(cargo);
  if(_LC_CARGO_RESP.test(cargo)||_LC_CAT_RESP.test(cat)) return true;
  if((f.vinculo||'campo')==='campo') return false;
  if(f.vinculo==='escritorio') return true;
  if(cargo&&_LC_CARGO_CAMPO.test(cargo)) return false;
  return false;
}
function _lcListaResponsaveis(selectedId){
  var base=(typeof funcs!=='undefined'&&funcs&&funcs.length)
    ? funcs.filter(function(f){ return f.ativo!==false; })
    : (colaboradores||[]).filter(function(c){ return c.ativo!==false; });
  var lista=base.filter(_lcEhResponsavelValido);
  if(selectedId){
    var sid=String(selectedId);
    if(!lista.some(function(f){ return String(f.id)===sid; })){
      var cur=base.find(function(f){ return String(f.id)===sid; });
      if(cur) lista.push(cur);
    }
  }
  return lista.sort(function(a,b){ return (a.nome||'').localeCompare(b.nome||'','pt-BR'); });
}
function _lcRespIdValido(v){
  if(!v) return null;
  // Só aceita IDs de funcionarios — colaboradores têm campo re (matricula), funcionarios não
  var lista = funcs||[];
  var match = lista.find(function(f){ return String(f.id)===String(v); });
  if(!match) return null;
  // Se o match veio de colaboradores (tem campo re), não é funcionario válido
  if(match.re!==undefined && match.re!==null) return null;
  return v;
}
function _lcRespNomeById(id){
  if(!id) return '';
  var sid=String(id);
  var f=(funcs||[]).find(function(x){ return String(x.id)===sid; });
  if(!f) f=(colaboradores||[]).find(function(x){ return String(x.id)===sid; });
  return f?(f.nome||''):'';
}
function _lcRespTexto(l){
  if(!l) return '—';
  var t=String(l.responsavel||'').trim();
  if(t) return t;
  if(l.responsavel_id){
    var n=_lcRespNomeById(l.responsavel_id);
    if(n) return n;
  }
  return '—';
}
function _lcNomesResponsaveisSugestao(){
  var seen={}, nomes=[];
  (colaboradores||[]).filter(function(c){ return c.ativo!==false; })
    .filter(_lcEhResponsavelValido)
    .forEach(function(f){
      var n=(f.nome||'').trim();
      if(n&&!seen[n.toLowerCase()]){ seen[n.toLowerCase()]=1; nomes.push(n); }
    });
  (locacoes||[]).forEach(function(l){
    var n=String(l.responsavel||'').trim();
    if(n&&!seen[n.toLowerCase()]){ seen[n.toLowerCase()]=1; nomes.push(n); }
  });
  return nomes.sort(function(a,b){ return a.localeCompare(b,'pt-BR'); });
}
function _lcRespCampoHtml(valor, labelInner){
  labelInner=labelInner||'<label style="font-size:11px">Responsável</label>';
  var v=escHtml(String(valor||'').trim());
  var opts=_lcNomesResponsaveisSugestao().map(function(n){ return '<option value="'+escHtml(n)+'">'; }).join('');
  return '<div class="fg">'+labelInner
    +'<input class="inp" id="lc-resp" list="lc-resp-list" value="'+v+'" placeholder="Gestor, coordenador ou supervisor" style="width:100%" title="Digite ou escolha da lista"/>'
    +'<datalist id="lc-resp-list">'+opts+'</datalist></div>';
}
