function _lcNormPlaca(p){
  if(typeof frtNormPlaca==='function') return frtNormPlaca(p);
  return String(p||'').toUpperCase().replace(/[-\s.]/g,'');
}
function _lcEsc(s){
  return String(s==null?'':s)
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
function _lcTextoContemPlaca(texto, placaNorm){
  if(!placaNorm || placaNorm.length < 5) return false;
  var raw=String(texto||'');
  if(_lcNormPlaca(raw).indexOf(placaNorm)>=0) return true;
  var up=raw.toUpperCase().replace(/\s/g,'');
  if(up.indexOf(placaNorm)>=0) return true;
  if(placaNorm.length>=7){
    var hy=placaNorm.slice(0,3)+'-'+placaNorm.slice(3);
    if(up.indexOf(hy)>=0) return true;
  }
  return false;
}
function _lcLocacaoTemPlaca(l, placaNorm){
  if(!l||!placaNorm||placaNorm.length<5) return false;
  if(l.placa && _lcNormPlaca(l.placa)===placaNorm) return true;
  if(_lcTextoContemPlaca(l.nome, placaNorm)) return true;
  if(_lcTextoContemPlaca(l.observacoes, placaNorm)) return true;
  return false;
}
function _lcVeiculoJaEmLocacao(v){
  var pn=_lcNormPlaca(v&&v.placa);
  if(!pn||pn.length<5) return false;
  return (locacoes||[]).some(function(l){ return _lcLocacaoTemPlaca(l, pn); });
}
function _lcLocadoraNomeVeiculo(v){
  if(!v) return '';
  try{
    if(v.fornecedor_id && typeof _fornFindById==='function'){
      var f=_fornFindById(v.fornecedor_id);
      if(f&&(f.razao_social||f.nome_fantasia)) return String(f.razao_social||f.nome_fantasia);
    }
  }catch(e){}
  return String(v.locadora||'');
}
function _lcVeiculosAlugadosSemContrato(){
  try{
    var hoje=(typeof dataHojeLocal==='function'?dataHojeLocal():(typeof dataHoje==='function'?dataHoje():new Date().toISOString().slice(0,10)));
    return (frt_veiculos||[]).filter(function(v){
      if(!v||!v.placa) return false;
      if(v.ativo===false) return false;
      var st=String(v.status||'').toLowerCase();
      if(st==='inativo'||st==='baixado'||st.indexOf('devolvid')>=0) return false;
      if(v.posse!=='Alugado') return false;
      // Locação encerrada / devolvida (fim já passou)
      var fim=String(v.fim_locacao||v.data_fim_locacao||'').slice(0,10);
      if(fim && fim<hoje) return false;
      return !_lcVeiculoJaEmLocacao(v);
    }).sort(function(a,b){
      return String(a.placa||'').localeCompare(String(b.placa||''),'pt-BR');
    });
  }catch(e){
    console.warn('Locações: falha ao listar veículos Frotas', e);
    return [];
  }
}
function lcCarregarVeiculosFrotas(cb){
  if(DEMO){ if(cb) cb(); return Promise.resolve(); }
  return sbFetch('frotas_veiculos',{filters:['status=neq.Inativo'],order:'placa',limit:3000})
    .then(function(rows){ if(rows&&rows.length) frt_veiculos=rows; if(cb) cb(); })
    .catch(function(){ if(cb) cb(); });
}
function _lcHtmlVeiculosSemContrato(){
  try{
    var veics=_lcVeiculosAlugadosSemContrato();
    if(!veics.length) return '';
    var rows=veics.map(function(v){
      var placa=String(v.placa||'').toUpperCase();
      var modelo=[v.marca,v.modelo].filter(Boolean).join(' ')||(v.tipo||'—');
      var loc=_lcLocadoraNomeVeiculo(v)||'—';
      var valor=Number(v.valor_mensal||0);
      var valorTxt=valor?('R$ '+valor.toLocaleString('pt-BR',{minimumFractionDigits:2})):'—';
      var term=_lcDateInput(v.fim_locacao)||'—';
      var cont='—';
      if(v.contrato_id){
        var c=(contratos||[]).find(function(x){ return String(x.id)===String(v.contrato_id); });
        cont=c?String(c.nome||c.codigo||'—'):'—';
      }
      var vid=String(v.id||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'");
      return '<tr style="cursor:pointer" title="Clique para inserir no contrato de locação" onclick="lcInserirVeiculoFrotas(\''+vid+'\')">'
        +'<td style="font-weight:700;color:#185FA5;white-space:nowrap">'+_lcEsc(placa)+'</td>'
        +'<td>'+_lcEsc(modelo)+'</td>'
        +'<td style="font-size:11px">'+_lcEsc(loc)+'</td>'
        +'<td style="font-size:11px">'+_lcEsc(cont)+'</td>'
        +'<td style="text-align:right;white-space:nowrap">'+_lcEsc(valorTxt)+'</td>'
        +'<td style="font-size:11px;white-space:nowrap">'+(term==='—'?'—':_lcEsc(fmtD(term)))+'</td>'
        +'<td><span class="bdg info" style="font-size:10px">'+_lcEsc(v.status||'—')+'</span></td>'
        +'<td style="text-align:center"><button type="button" class="btn btn-sm btn-pri" style="font-size:10px" onclick="event.stopPropagation();lcInserirVeiculoFrotas(\''+vid+'\')">+ Inserir</button></td>'
        +'</tr>';
    }).join('');
    return '<div id="loc-veic-sem-contrato" class="card" style="margin-bottom:1rem;border-left:4px solid #185FA5">'
      +'<div class="ch" style="flex-wrap:wrap;gap:8px;align-items:center">'
      +'<span class="ct">🚗 Veículos alugados (Frotas) sem contrato de Locações</span>'
      +'<span class="bdg info" style="font-size:11px">'+veics.length+' pendente(s)</span>'
      +'<button type="button" class="btn btn-sm" style="margin-left:auto" onclick="lcCarregarVeiculosFrotas(function(){renderLocacoes();})" title="Recarregar cadastro de veículos">↻ Atualizar</button>'
      +'</div>'
      +'<div style="font-size:11px;color:#666;padding:0 .85rem .5rem">Comparação por <b>placa</b> com os contratos já cadastrados. Clique na linha para abrir o contrato pré-preenchido (editável).</div>'
      +'<div style="overflow:auto;padding:0 .5rem .75rem">'
      +'<table class="tbl" style="width:100%;font-size:12px"><thead><tr>'
      +'<th>Placa</th><th>Veículo</th><th>Locadora</th><th>Contrato CENA</th><th style="text-align:right">R$/mês</th><th>Fim locação</th><th>Status</th><th></th>'
      +'</tr></thead><tbody>'+rows+'</tbody></table></div></div>';
  }catch(e){
    console.warn('Locações: painel veículos Frotas ignorado', e);
    return '';
  }
}
function lcInserirVeiculoFrotas(vid){
  var v=(frt_veiculos||[]).find(function(x){ return String(x.id)===String(vid); });
  if(!v){ progShowToast('⚠ Veículo não encontrado no cadastro de Frotas.'); return; }
  if(_lcVeiculoJaEmLocacao(v)){
    progShowToast('⚠ A placa '+String(v.placa||'').toUpperCase()+' já está em um contrato de Locações.');
    return;
  }
  var placa=_lcNormPlaca(v.placa);
  var locadora=_lcLocadoraNomeVeiculo(v);
  var nomeEq=[v.marca,v.modelo].filter(Boolean).join(' ');
  if(!nomeEq) nomeEq=v.tipo||'Veículo';
  nomeEq=nomeEq+' — '+String(v.placa||'').toUpperCase();
  var disp='Em uso';
  if(v.status==='Disponível') disp='Disponível';
  else if(v.status==='Em manutenção'||v.status==='Bloqueado') disp='Em manutenção';
  var stEq='Funcionando';
  if(v.status==='Em manutenção') stEq='Em manutenção';
  else if(v.status==='Bloqueado') stEq='Com defeito';
  var obsParts=['Placa: '+placa];
  if(v.tipo) obsParts.push('Tipo: '+v.tipo);
  if(v.tipo_operacional) obsParts.push('Tipo op.: '+v.tipo_operacional);
  if(v.combustivel) obsParts.push('Comb.: '+v.combustivel);
  if(v.ano) obsParts.push('Ano: '+v.ano);
  if(v.km_atual!=null&&v.km_atual!=='') obsParts.push('KM: '+v.km_atual);
  if(v.chassi) obsParts.push('Chassi: '+v.chassi);
  if(v.renavam) obsParts.push('RENAVAM: '+v.renavam);
  if(v.tem_seguro&&v.seguradora) obsParts.push('Seguradora: '+v.seguradora);
  if(v.observacoes) obsParts.push(String(v.observacoes).trim());
  var seed={
    fornecedor_id:v.fornecedor_id||null,
    locadora:locadora,
    contrato_id:v.contrato_id||null,
    inicio:v.inicio_locacao||v.data_inicio_locacao||null,
    termino:v.fim_locacao||null,
    tem_seguro:!!v.tem_seguro,
    valor_seguro:null,
    responsavel:v.responsavel||'',
    observacoes:obsParts.join(' | '),
    numero_contrato:v.numero_contrato||'',
    placa:placa,
    veiculo_id:v.id,
    equipamento:{
      nome:nomeEq,
      tipo:'Veículo',
      quantidade:1,
      valor_unitario:Number(v.valor_mensal||0)||'',
      status:stEq,
      disponibilidade:disp
    }
  };
  openNovaLocacao(seed);
}

function renderLocacoes(){
  var hoje = new Date();

  // Métricas gerais
  function se(id,v){ var el=document.getElementById(id); if(el) el.textContent=v; }
  se('loc-total', locacoes.length);
  se('loc-uso',   locacoes.filter(function(l){ return lcDispHasStatus(l.disponibilidade,'Em uso'); }).length);
  se('loc-manut', locacoes.filter(function(l){ return lcDispHasStatus(l.disponibilidade,'Em manutenção'); }).length);
  var venc = locacoes.filter(function(l){
    if(!l.termino) return false;
    var d = Math.round((new Date(l.termino+'T00:00:00') - hoje) / 86400000);
    return d >= 0 && d <= 30;
  }).length;
  var custo = locacoes.reduce(function(s,l){ return s + Number(l.valor_locacao||0); }, 0);
  se('loc-venc',  venc);
  se('loc-custo', 'R$ ' + custo.toLocaleString('pt-BR', {minimumFractionDigits:2}));

  // Popular filtros — sempre re-popula preservando o valor selecionado
  var selForn  = document.getElementById('fil-loc-fornecedor');
  var selResp  = document.getElementById('fil-loc-resp');
  var selContr = document.getElementById('fil-loc-contrato');
  if(selForn){
    var _pvF = selForn.value;
    var _forn = []; var _fset={};
    locacoes.forEach(function(l){ var v=l.locadora||''; if(v&&!_fset[v]){_fset[v]=1;_forn.push(v);} });
    _forn.sort();
    selForn.innerHTML = '<option value="">Todas</option>' + _forn.map(function(f){ return '<option value="'+escHtml(f)+'">'+escHtml(f)+'</option>'; }).join('');
    selForn.value = _pvF;
  }
  if(selResp){
    var _pvR = selResp.value;
    var _resps = []; var _rset={};
    locacoes.forEach(function(l){
      var v=_lcRespTexto(l);
      if(v&&v!=='—'&&!_rset[v.toLowerCase()]){_rset[v.toLowerCase()]=1;_resps.push(v);}
    });
    _lcListaResponsaveis().forEach(function(f){
      var v=(f.nome||'').trim();
      if(v&&!_rset[v.toLowerCase()]){_rset[v.toLowerCase()]=1;_resps.push(v);}
    });
    _resps.sort(function(a,b){return a.toLowerCase().localeCompare(b.toLowerCase());});
    selResp.innerHTML = '<option value="">Todos</option>' + _resps.map(function(r){ return '<option value="'+escHtml(r)+'">'+escHtml(r)+'</option>'; }).join('');
    selResp.value = _pvR;
  }
  if(selContr && selContr.options.length <= 1){
    var _cOpts = (contratos||[]).filter(function(c){return c.status!=='Cancelado';}).sort(function(a,b){return (a.nome||a.codigo||'').localeCompare(b.nome||b.codigo||'');});
    selContr.innerHTML = '<option value="">Todos os contratos</option>' + _cOpts.map(function(c){ return '<option value="'+c.id+'">'+escHtml(c.nome||c.codigo||c.id)+'</option>'; }).join('');
  }

  // Leitura dos filtros
  var qForn  = (selForn||{}).value||'';
  var qResp  = (selResp||{}).value||'';
  var qProd  = ((document.getElementById('fil-loc-q')||{}).value||'').toLowerCase();
  var qSt    = (document.getElementById('fil-loc-status')||{}).value||'';
  var qContr = (selContr||{}).value||'';

  // Filtrar e agrupar por contrato (locadora + obs_contrato + periodo)
  var rows = filtrarFilial(locacoes).filter(function(l){
    if(qForn && (l.locadora||'') !== qForn) return false;
    if(qResp && _lcRespTexto(l).toLowerCase() !== qResp.toLowerCase()) return false;
    if(qSt   && !lcDispHasStatus(l.disponibilidade, qSt)) return false;
    if(qContr){
      var _cq=null; try{_cq=l.contrato_qtds&&typeof l.contrato_qtds==='string'?JSON.parse(l.contrato_qtds):l.contrato_qtds;}catch(e){}
      if(l.contrato_id!==qContr && !(_cq&&_cq.hasOwnProperty(qContr))) return false;
    }
    return true;
  });

  // Agrupar itens pelo mesmo contrato: mesma locadora + início + fim + obs
  var grupos = {};
  rows.forEach(function(l){
    var key = (l.locadora||'') + '|' + (l.inicio||'') + '|' + (l.termino||'') + '|' + (l.observacoes||'').slice(0,40);
    if(!grupos[key]) grupos[key] = { locadora:l.locadora, inicio:l.inicio, termino:l.termino,
      responsavel:l.responsavel, filial_id:l.filial_id, deposito_id:l.deposito_id,
      observacoes:l.observacoes, itens:[], total:0 };
    else {
      if(!grupos[key].filial_id&&l.filial_id) grupos[key].filial_id=l.filial_id;
      if(!grupos[key].deposito_id&&l.deposito_id) grupos[key].deposito_id=l.deposito_id;
      if(!grupos[key].responsavel&&l.responsavel) grupos[key].responsavel=l.responsavel;
    }
    grupos[key].itens.push(l);
    grupos[key].total += Number(l.valor_locacao||0);
  });

  // Filtro de produto/equipamento aplicado no nível do grupo
  if(qProd){
    Object.keys(grupos).forEach(function(k){
      if(!grupos[k].itens.some(function(l){ return (l.nome||'').toLowerCase().indexOf(qProd)>=0; }))
        delete grupos[k];
    });
  }

  var lista = document.getElementById('loc-lista-cards');
  if(!lista) return;

  var _painelVeic = '';
  try{ _painelVeic = _lcHtmlVeiculosSemContrato(); }catch(e){ console.warn('Locações: painel Frotas', e); _painelVeic=''; }

  // Relatórios agregados (locadora e/ou contrato CENA)
  var _relHtml = '';
  var _resumoTodos = !!((document.getElementById('fil-loc-resumo-todos')||{}).checked);
  var _resumoEmpresa = !!((document.getElementById('fil-loc-resumo-empresa')||{}).checked);
  if(rows.length && _resumoEmpresa){
    if(qForn){
      _relHtml += _lcHtmlResumoEmpresa(qForn, rows);
    }else{
      var _empsResumo = _lcEmpresasEmRows(rows);
      if(_empsResumo.length){
        _relHtml += _empsResumo.map(function(emp){
          var _sub = rows.filter(function(l){ return _lcLocadoraKey(l)===emp; });
          return _lcHtmlResumoEmpresa(emp, _sub);
        }).join('');
      }
    }
  }
  if(rows.length){
    if(qContr){
      _relHtml += _lcHtmlResumoContrato(qContr, rows);
    }else if(_resumoTodos){
      var _cidsResumo = _lcContratosEmRows(rows);
      if(_cidsResumo.length){
        _relHtml += _cidsResumo.map(function(cid){ return _lcHtmlResumoContrato(cid, rows); }).join('');
      }else{
        _relHtml += '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:12px;padding:1rem;margin-bottom:.75rem;font-size:12px;color:#888;text-align:center">Nenhum item vinculado a contratos CENA nos filtros atuais.</div>';
      }
    }
  }

  if(!Object.keys(grupos).length){
    if(_relHtml){
      lista.innerHTML = _painelVeic + _relHtml;
    }else{
      lista.innerHTML = _painelVeic + '<div style="padding:2rem;text-align:center;color:#aaa;background:#fff;border-radius:10px;border:.5px solid #e0dfd8">Nenhum contrato encontrado.</div>';
    }
    return;
  }

  var dc = {Disponível:'ok','Em uso':'info','Em manutenção':'warn',Devolvido:'gray',Extraviado:'danger'};

  lista.innerHTML = _painelVeic + _relHtml + Object.keys(grupos).map(function(key, gi){
    var g = grupos[key];
    var diff = g.termino ? Math.round((new Date(g.termino+'T00:00:00') - hoje) / 86400000) : null;
    var prazoLabel = diff===null ? '—' : diff<0 ? 'Vencido '+Math.abs(diff)+'d' : diff===0 ? 'Hoje' : diff+' dias';
    var prazoCor   = diff===null ? 'gray' : diff<0 ? 'danger' : diff<=30 ? 'warn' : 'ok';
    var respNome   = _lcRespTexto(g);
    var filNome    = _lcFilialNome(g.filial_id);
    var depNome    = _lcDepositoNome(g.deposito_id);

    // Determinar status geral do contrato (suporta disponibilidade como JSON)
    var statusGeral = g.itens.some(function(l){ return lcDispHasStatus(l.disponibilidade,'Em uso'); }) ? 'Em uso'
      : g.itens.every(function(l){ return lcDispHasStatus(l.disponibilidade,'Devolvido'); }) ? 'Devolvido'
      : g.itens.every(function(l){ return lcDispHasStatus(l.disponibilidade,'Em manutenção'); }) ? 'Em manutenção'
      : 'Disponível';

    // Nº contrato do fornecedor e seguro do grupo
    var _hdrContratos=[]; var _hdrSeguro=false;
    g.itens.forEach(function(l){
      if(l.tem_seguro) _hdrSeguro=true;
      var num=(l.numero_contrato||'').toString().trim();
      if(num&&_hdrContratos.indexOf(num)<0) _hdrContratos.push(num);
    });

    // Card header (sempre visível)
    var hdr = '<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap">'
      + '<div style="flex:1;min-width:0">'
      + '<div style="font-weight:700;font-size:14px;margin-bottom:2px">'+escHtml(g.locadora||'—')+'</div>'
      + (_hdrContratos.length||_hdrSeguro
          ? '<div style="font-size:11px;color:#555;display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-bottom:2px">'
            +(_hdrContratos.length?'<span style="font-weight:600">📋 '+escHtml(_hdrContratos.join(' · '))+'</span>':'')
            +(_hdrSeguro?'<span class="bdg green" style="font-size:10px">🛡 Seguro</span>':'')
            +'</div>'
          : '')
      + '<div style="font-size:11px;color:#888;display:flex;gap:10px;flex-wrap:wrap">'
      + (respNome !== '—' ? '<span>👤 '+escHtml(respNome)+'</span>' : '')
      + (filNome ? '<span>🏢 '+escHtml(filNome)+'</span>' : '')
      + (depNome ? '<span>📦 '+escHtml(depNome)+'</span>' : '')
      + (g.inicio ? '<span>📅 '+fmtD(g.inicio)+' → '+fmtD(g.termino)+'</span>' : '')
      + '<span class="bdg '+prazoCor+'" style="font-size:10px">'+prazoLabel+'</span>'
      + '</div>'
      + '</div>'
      + '<div style="display:flex;gap:8px;align-items:center;flex-shrink:0">'
      + '<div style="text-align:right">'
      + '<div style="font-weight:700;font-size:15px;color:#185FA5">R$ '+g.total.toLocaleString('pt-BR',{minimumFractionDigits:2})+'</div>'
      + '<div style="font-size:10px;color:#888">'+g.itens.length+' item(ns)</div>'
      + '</div>'
      + '<span class="bdg '+(dc[statusGeral]||'gray')+'" style="white-space:nowrap">'+statusGeral+'</span>'
      + '<button type="button" data-ids="'+escHtml(g.itens.map(function(l){return l.id;}).join(','))+'" onclick="lcAbrirEditarGrupo(this.getAttribute(\'data-ids\'))" style="background:#EBF4FD;color:#185FA5;border:.5px solid #185FA544;border-radius:6px;padding:4px 10px;cursor:pointer;font-size:11px;font-weight:600" title="Editar contrato completo">✏ Editar</button>'
      + '<button onclick="locToggleCard(\'loc-body-'+gi+'\')" style="background:none;border:.5px solid #e0dfd8;border-radius:6px;padding:4px 8px;cursor:pointer;font-size:12px;color:#555" id="loc-arr-'+gi+'">▼</button>'
      + '</div>'
      + '</div>';

    // Card body — contratos únicos deste grupo (para filtro)
    var _cgMap = {};
    g.itens.forEach(function(l){
      var cq=null; try{cq=l.contrato_qtds&&typeof l.contrato_qtds==='string'?JSON.parse(l.contrato_qtds):l.contrato_qtds;}catch(e){}
      if(cq&&typeof cq==='object') Object.keys(cq).forEach(function(cid){
        if(!_cgMap[cid]){var c=(contratos||[]).find(function(x){return x.id===cid;});_cgMap[cid]=c?(c.nome||c.codigo||cid):cid;}
      });
      else if(l.contrato_id&&!_cgMap[l.contrato_id]){var c=(contratos||[]).find(function(x){return x.id===l.contrato_id;});_cgMap[l.contrato_id]=c?(c.nome||c.codigo||l.contrato_id):l.contrato_id;}
    });
    var _cids=Object.keys(_cgMap);

    var _filC = _cids.length
      ? '<div style="display:flex;align-items:center;gap:8px;margin-bottom:.6rem;flex-wrap:wrap">'
        +'<span style="font-size:11px;color:#888;white-space:nowrap">Filtrar por contrato:</span>'
        +'<select class="inp" style="font-size:11px;padding:2px 8px;min-width:150px" onchange="locFiltrarContrato('+gi+',this.value)">'
        +'<option value="">Todos</option>'
        +_cids.map(function(cid){return '<option value="'+cid+'">'+escHtml(_cgMap[cid])+'</option>';}).join('')
        +'</select>'
        +'<span id="loc-ctot-'+gi+'" style="font-size:12px;font-weight:700;color:#185FA5"></span>'
        +'</div>' : '';

    var _colHdr='<div style="display:grid;grid-template-columns:2.5fr 0.6fr 0.6fr 1fr 1.8fr 1fr auto;gap:6px;padding:.2rem 0;font-size:10px;font-weight:700;color:#888;text-transform:uppercase;border-bottom:.5px solid #e0dfd8">'
      +'<div>Item</div><div>Tipo</div><div style="text-align:center">Qtd</div><div style="text-align:right">V.Unit/Mês</div>'
      +'<div>Contratos</div><div style="text-align:right">Total</div><div></div></div>';

    var _bodyOpen = (qProd||qSt) ? '' : 'none';
    var body = '<div id="loc-body-'+gi+'" style="display:'+_bodyOpen+';margin-top:.75rem;border-top:.5px solid #f0efe8;padding-top:.75rem">'
      + _filC + _colHdr
      + g.itens.map(function(l){
          var cq=null; try{cq=l.contrato_qtds&&typeof l.contrato_qtds==='string'?JSON.parse(l.contrato_qtds):l.contrato_qtds;}catch(e){}
          var qtd=Number(l.quantidade||1), unit=Number(l.valor_unitario||0), tot=qtd*unit;
          var cHtml='';
          if(cq&&typeof cq==='object'&&Object.keys(cq).length){
            cHtml=Object.keys(cq).map(function(cid){
              var c=(contratos||[]).find(function(x){return x.id===cid;});
              return '<span style="font-size:10px;background:#EEF2FF;color:#533AB7;border-radius:4px;padding:1px 5px;display:inline-block;margin:1px">'+escHtml(c?(c.nome||c.codigo||cid):cid)+': '+cq[cid]+'</span>';
            }).join('');
          } else if(l.contrato_id){
            var c=(contratos||[]).find(function(x){return x.id===l.contrato_id;});
            cHtml='<span style="font-size:10px;background:#EEF2FF;color:#533AB7;border-radius:4px;padding:1px 5px">'+escHtml(c?(c.nome||c.codigo||l.contrato_id):l.contrato_id)+'</span>';
          }
          return '<div class="lc-item-r" data-cid="'+escHtml(l.contrato_id||'')+'" data-cqtds="'+escHtml(JSON.stringify(cq||null))+'" data-qtd="'+qtd+'" data-unit="'+unit+'" style="display:grid;grid-template-columns:2.5fr 0.6fr 0.6fr 1fr 1.8fr 1fr auto;gap:6px;align-items:center;padding:.3rem 0;border-bottom:.5px solid #f5f5f3;font-size:12px">'
            +'<div><span style="font-weight:500">'+escHtml(l.nome)+'</span>'+(l.tem_seguro?'<span style="font-size:9px;color:#3B6D11;margin-left:4px">🛡</span>':'')+( l.disponibilidade?'<div style="margin-top:2px">'+lcDispBadges(l.disponibilidade,dc)+'</div>':'' )+'</div>'
            +'<div><span class="bdg gray" style="font-size:10px">'+(l.tipo||'—')+'</span></div>'
            +'<div style="text-align:center;font-weight:600" class="lc-qtd-c">'+qtd+'</div>'
            +'<div style="text-align:right;color:#555">'+unit.toLocaleString('pt-BR',{minimumFractionDigits:2})+'</div>'
            +'<div>'+cHtml+'</div>'
            +'<div style="text-align:right;font-weight:600;color:#185FA5" class="lc-tot-c">R$ '+tot.toLocaleString('pt-BR',{minimumFractionDigits:2})+'</div>'
            +'<div style="display:flex;gap:3px">'
            +'<button class="btn btn-sm" type="button" data-lid="'+escHtml(l.id)+'" onclick="openEditarLocacao(this.getAttribute(\'data-lid\'))" title="Editar">✏</button>'
            +'<button class="btn btn-sm" onclick="openOcLocacao(\''+l.id+'\')" title="Ocorrência">!</button>'
            +'<button class="btn btn-sm" onclick="lcExcluirLocacao(\''+l.id+'\')" title="Excluir" style="color:#c0392b">🗑</button>'
            +'</div></div>';
        }).join('')
      + '</div>';

    return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:12px;padding:1rem;margin-bottom:.5rem">'
      + hdr + body + '</div>';
  }).join('');
}

function _lcContratosEmRows(rows){
  var map={};
  (rows||[]).forEach(function(l){
    var cq=_lcParseContratoQtds(l.contrato_qtds);
    if(cq&&typeof cq==='object'){
      Object.keys(cq).forEach(function(cid){ if(Number(cq[cid])>0) map[cid]=1; });
    }else if(l.contrato_id) map[l.contrato_id]=1;
  });
  return Object.keys(map).sort(function(a,b){
    var ca=(contratos||[]).find(function(c){ return c.id===a; });
    var cb=(contratos||[]).find(function(c){ return c.id===b; });
    return (ca?(ca.nome||ca.codigo||a):a).localeCompare(cb?(cb.nome||cb.codigo||b):b,'pt-BR',{sensitivity:'base'});
  });
}

function _lcAgregarResumoContrato(cId, rows){
  var _agr={};
  (rows||[]).forEach(function(l){
    var _cq=_lcParseContratoQtds(l.contrato_qtds);
    var _qtd=_cq&&_cq.hasOwnProperty(cId)?Number(_cq[cId]||0):(l.contrato_id===cId?Number(l.quantidade||1):0);
    if(!_qtd) return;
    var _k=(l.nome||'').toLowerCase().trim();
    if(!_agr[_k]) _agr[_k]={nome:l.nome, tipo:l.tipo||'—', qtd:0, valorTotal:0, units:[]};
    _agr[_k].qtd+=_qtd;
    var _u=Number(l.valor_unitario||0);
    _agr[_k].valorTotal+=_qtd*_u;
    if(_u) _agr[_k].units.push(_u);
  });
  var _iArr=Object.values(_agr).sort(function(a,b){ return (a.nome||'').localeCompare(b.nome||'','pt-BR',{sensitivity:'base'}); });
  var _totGeral=_iArr.reduce(function(s,i){ return s+i.valorTotal; },0);
  return {itens:_iArr, total:_totGeral};
}

function _lcLocadoraKey(l){
  var v=(l&&l.locadora||'').trim();
  return v||'(Sem locadora)';
}

function _lcEmpresasEmRows(rows){
  var map={};
  (rows||[]).forEach(function(l){ map[_lcLocadoraKey(l)]=1; });
  return Object.keys(map).sort(function(a,b){ return a.localeCompare(b,'pt-BR',{sensitivity:'base'}); });
}

function _lcAgregarResumoEmpresa(rows){
  var _agr={};
  (rows||[]).forEach(function(l){
    var _qtd=Number(l.quantidade||1);
    if(!_qtd) return;
    var _k=((l.nome||'').toLowerCase().trim())+'|'+(l.tipo||'').toLowerCase().trim();
    if(!_agr[_k]) _agr[_k]={nome:l.nome, tipo:l.tipo||'—', qtd:0, valorTotal:0, units:[]};
    _agr[_k].qtd+=_qtd;
    var _u=Number(l.valor_unitario||0);
    _agr[_k].valorTotal+=_qtd*_u;
    if(_u) _agr[_k].units.push(_u);
  });
  var _iArr=Object.values(_agr).sort(function(a,b){ return (a.nome||'').localeCompare(b.nome||'','pt-BR',{sensitivity:'base'}); });
  var _totGeral=_iArr.reduce(function(s,i){ return s+i.valorTotal; },0);
  var _totQtd=_iArr.reduce(function(s,i){ return s+i.qtd; },0);
  return {itens:_iArr, total:_totGeral, totalQtd:_totQtd};
}

function _lcHtmlResumoEmpresa(empNome, rows){
  var agg=_lcAgregarResumoEmpresa(rows);
  if(!agg.itens.length) return '';
  var _titulo=empNome;
  return '<div style="background:#fff;border:.5px solid #BBDEFB;border-radius:12px;padding:1rem;margin-bottom:.75rem">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:.6rem">'
    +'<div style="font-weight:700;font-size:13px;color:#0D47A1">📊 Resumo por locadora — '+escHtml(_titulo)+'</div>'
    +'<div style="font-size:11px;color:#555">'+agg.itens.length+' produto(s) · '+agg.totalQtd+' unidade(s) · '
    +'<button type="button" class="btn btn-sm" onclick="lcExportarResumoEmpresa()" style="margin-left:4px;font-size:10px;padding:2px 8px">⬇ CSV</button>'
    +'</div></div>'
    +'<table style="width:100%;border-collapse:collapse;font-size:12px">'
    +'<thead><tr style="background:#E3F2FD;text-align:left">'
    +'<th style="padding:5px 8px;border-bottom:1px solid #BBDEFB">Produto / Equipamento</th>'
    +'<th style="padding:5px 8px;border-bottom:1px solid #BBDEFB;text-align:center">Tipo</th>'
    +'<th style="padding:5px 8px;border-bottom:1px solid #BBDEFB;text-align:center">Qtd total</th>'
    +'<th style="padding:5px 8px;border-bottom:1px solid #BBDEFB;text-align:right">Valor Unit. (méd.)</th>'
    +'<th style="padding:5px 8px;border-bottom:1px solid #BBDEFB;text-align:right">Total</th>'
    +'</tr></thead><tbody>'
    +agg.itens.map(function(it){
      var _med=it.units.length?(it.units.reduce(function(s,v){ return s+v; },0)/it.units.length):0;
      return '<tr style="border-bottom:.5px solid #f0f0ee">'
        +'<td style="padding:4px 8px;font-weight:500">'+escHtml(it.nome)+'</td>'
        +'<td style="padding:4px 8px;text-align:center"><span class="bdg gray" style="font-size:10px">'+escHtml(it.tipo)+'</span></td>'
        +'<td style="padding:4px 8px;text-align:center;font-weight:600">'+it.qtd+'</td>'
        +'<td style="padding:4px 8px;text-align:right;color:#555">R$ '+_med.toLocaleString('pt-BR',{minimumFractionDigits:2})+'</td>'
        +'<td style="padding:4px 8px;text-align:right;font-weight:600;color:#185FA5">R$ '+it.valorTotal.toLocaleString('pt-BR',{minimumFractionDigits:2})+'</td>'
        +'</tr>';
    }).join('')
    +'</tbody><tfoot><tr style="background:#E8F4FD;font-weight:700">'
    +'<td colspan="2" style="padding:5px 8px;text-align:right;color:#555">Totais:</td>'
    +'<td style="padding:5px 8px;text-align:center;color:#0D47A1">'+agg.totalQtd+'</td>'
    +'<td style="padding:5px 8px"></td>'
    +'<td style="padding:5px 8px;text-align:right;color:#0D47A1">R$ '+agg.total.toLocaleString('pt-BR',{minimumFractionDigits:2})+'</td>'
    +'</tr></tfoot></table>'
    +'<div style="font-size:10px;color:#888;margin-top:.4rem">Quantidades somadas de todos os contratos da locadora, sem rateio por contrato CENA.</div>'
    +'</div>';
}

function lcExportarResumoEmpresa(){
  var selForn=document.getElementById('fil-loc-fornecedor');
  var selResp=document.getElementById('fil-loc-resp');
  var selContr=document.getElementById('fil-loc-contrato');
  var qForn=(selForn||{}).value||'';
  var qResp=(selResp||{}).value||'';
  var qProd=((document.getElementById('fil-loc-q')||{}).value||'').toLowerCase();
  var qSt=(document.getElementById('fil-loc-status')||{}).value||'';
  var qContr=(selContr||{}).value||'';
  var rows=filtrarFilial(locacoes||[]).filter(function(l){
    if(qForn&&(l.locadora||'')!==qForn) return false;
    if(qResp&&_lcRespTexto(l).toLowerCase()!==qResp.toLowerCase()) return false;
    if(qSt&&!lcDispHasStatus(l.disponibilidade,qSt)) return false;
    if(qContr){
      var _cq=_lcParseContratoQtds(l.contrato_qtds);
      if(l.contrato_id!==qContr&&!(_cq&&_cq.hasOwnProperty(qContr))) return false;
    }
    return true;
  });
  if(qProd){
    rows=rows.filter(function(l){ return (l.nome||'').toLowerCase().indexOf(qProd)>=0; });
  }
  if(!rows.length){ progShowToast('Nenhum item nos filtros atuais.'); return; }
  var _csvCell=function(v){ return '"'+String(v==null?'':v).replace(/"/g,'""')+'"'; };
  var linhas=['Locadora;Produto;Tipo;Quantidade;Valor unit. (méd.);Total'];
  var emps=qForn?[_lcLocadoraKey({locadora:qForn})]:_lcEmpresasEmRows(rows);
  emps.forEach(function(emp){
    var sub=rows.filter(function(l){ return _lcLocadoraKey(l)===emp; });
    var agg=_lcAgregarResumoEmpresa(sub);
    agg.itens.forEach(function(it){
      var med=it.units.length?(it.units.reduce(function(s,v){ return s+v; },0)/it.units.length):0;
      linhas.push([emp,it.nome,it.tipo,it.qtd,med.toFixed(2),it.valorTotal.toFixed(2)].map(_csvCell).join(';'));
    });
  });
  var blob=new Blob(['\ufeff'+linhas.join('\n')],{type:'text/csv;charset=utf-8'});
  var a=document.createElement('a'); a.href=URL.createObjectURL(blob);
  var _suf=qForn?qForn.replace(/[^\w\-]+/g,'_'):'todas';
  a.download='locacoes_resumo_'+_suf+'_'+dataHojeLocal()+'.csv';
  a.click(); URL.revokeObjectURL(a.href);
  progShowToast('CSV exportado ('+rows.length+' linha(s) de locação).');
}

function _lcHtmlResumoContrato(cId, rows){
  var agg=_lcAgregarResumoContrato(cId, rows);
  if(!agg.itens.length) return '';
  var _cObj=(contratos||[]).find(function(c){ return c.id===cId; });
  var _cNome=_cObj?(_cObj.nome||_cObj.codigo||cId):cId;
  return '<div style="background:#fff;border:.5px solid #c8e6c9;border-radius:12px;padding:1rem;margin-bottom:.75rem">'
    +'<div style="font-weight:700;font-size:13px;margin-bottom:.6rem;color:#1B5E20">📊 Resumo — '+escHtml(_cNome)+'</div>'
    +'<table style="width:100%;border-collapse:collapse;font-size:12px">'
    +'<thead><tr style="background:#F1F8E9;text-align:left">'
    +'<th style="padding:5px 8px;border-bottom:1px solid #C8E6C9">Produto / Equipamento</th>'
    +'<th style="padding:5px 8px;border-bottom:1px solid #C8E6C9;text-align:center">Tipo</th>'
    +'<th style="padding:5px 8px;border-bottom:1px solid #C8E6C9;text-align:center">Qtd</th>'
    +'<th style="padding:5px 8px;border-bottom:1px solid #C8E6C9;text-align:right">Valor Unit. (méd.)</th>'
    +'<th style="padding:5px 8px;border-bottom:1px solid #C8E6C9;text-align:right">Total</th>'
    +'</tr></thead><tbody>'
    +agg.itens.map(function(it){
      var _med=it.units.length?(it.units.reduce(function(s,v){ return s+v; },0)/it.units.length):0;
      return '<tr style="border-bottom:.5px solid #f0f0ee">'
        +'<td style="padding:4px 8px;font-weight:500">'+escHtml(it.nome)+'</td>'
        +'<td style="padding:4px 8px;text-align:center"><span class="bdg gray" style="font-size:10px">'+escHtml(it.tipo)+'</span></td>'
        +'<td style="padding:4px 8px;text-align:center;font-weight:600">'+it.qtd+'</td>'
        +'<td style="padding:4px 8px;text-align:right;color:#555">R$ '+_med.toLocaleString('pt-BR',{minimumFractionDigits:2})+'</td>'
        +'<td style="padding:4px 8px;text-align:right;font-weight:600;color:#185FA5">R$ '+it.valorTotal.toLocaleString('pt-BR',{minimumFractionDigits:2})+'</td>'
        +'</tr>';
    }).join('')
    +'</tbody><tfoot><tr style="background:#F9FBE7;font-weight:700">'
    +'<td colspan="4" style="padding:5px 8px;text-align:right;color:#555">Total geral:</td>'
    +'<td style="padding:5px 8px;text-align:right;color:#1B5E20">R$ '+agg.total.toLocaleString('pt-BR',{minimumFractionDigits:2})+'</td>'
    +'</tr></tfoot></table>'
    +'</div>';
}

function locFiltrarContrato(gi, cid){
  var body = document.getElementById('loc-body-'+gi);
  if(!body) return;
  var totalC = 0;
  body.querySelectorAll('.lc-item-r').forEach(function(row){
    var itemCid = row.getAttribute('data-cid')||'';
    var cqtdsStr = row.getAttribute('data-cqtds')||'null';
    var origQtd = parseFloat(row.getAttribute('data-qtd'))||1;
    var unit = parseFloat(row.getAttribute('data-unit'))||0;
    if(!cid){
      row.style.display='';
      row.querySelector('.lc-qtd-c').textContent=origQtd;
      row.querySelector('.lc-tot-c').textContent='R$ '+(origQtd*unit).toLocaleString('pt-BR',{minimumFractionDigits:2});
      return;
    }
    var qtdC=0, cqtds=null;
    try{cqtds=JSON.parse(cqtdsStr);}catch(e){}
    if(cqtds&&typeof cqtds==='object') qtdC=Number(cqtds[cid]||0);
    else if(itemCid===cid) qtdC=origQtd;
    if(qtdC>0){
      row.style.display='';
      row.querySelector('.lc-qtd-c').textContent=qtdC;
      var tot=qtdC*unit;
      row.querySelector('.lc-tot-c').textContent='R$ '+tot.toLocaleString('pt-BR',{minimumFractionDigits:2});
      totalC+=tot;
    } else { row.style.display='none'; }
  });
  var sp=document.getElementById('loc-ctot-'+gi);
  if(sp) sp.textContent=cid&&totalC>0?'→ R$ '+totalC.toLocaleString('pt-BR',{minimumFractionDigits:2}):'';
}

function locToggleCard(id){
  var el  = document.getElementById(id);
  var idx = id.replace('loc-body-','');
  var arr = document.getElementById('loc-arr-'+idx);
  if(!el) return;
  var open = el.style.display === 'none';
  el.style.display  = open ? '' : 'none';
  if(arr) arr.textContent = open ? '▲' : '▼';
}

function locLimparFiltros(){
  ['fil-loc-fornecedor','fil-loc-resp','fil-loc-q','fil-loc-status','fil-loc-contrato'].forEach(function(id){
    var el = document.getElementById(id);
    if(el) el.value = '';
  });
  var chk=document.getElementById('fil-loc-resumo-todos');
  if(chk) chk.checked=false;
  var chkEmp=document.getElementById('fil-loc-resumo-empresa');
  if(chkEmp) chkEmp.checked=false;
  renderLocacoes();
}


function lcAtualizarDepositos(selectId, valorPreservar){
  var filSel  = document.getElementById('lc-fil');
  var depSel  = document.getElementById(selectId);
  if(!depSel) return;
  var curVal  = valorPreservar !== undefined ? valorPreservar : depSel.value;
  var filId   = filSel ? filSel.value : '';
  var depsFil = filId
    ? (depositos||[]).filter(function(d){ return String(d.filial_id)===String(filId); })
    : (depositos||[]);
  depSel.innerHTML = '<option value="">Sem depósito</option>'
    + depsFil.map(function(d){
        return '<option value="'+d.id+'">'+escHtml(d.nome)+'</option>';
      }).join('');
  if(curVal){
    depSel.value=String(curVal);
    if(depSel.value!==String(curVal)){
      var dn=_lcDepositoNome(curVal)||('Depósito salvo');
      var opt=document.createElement('option');
      opt.value=String(curVal); opt.textContent=dn;
      depSel.appendChild(opt);
      depSel.value=String(curVal);
    }
  }
}


function openNovaLocacao(seed){
  _lcPrepFornModal().then(function(){ _openNovaLocacaoModal(seed||null); });
}

function _lcParseContratoQtds(raw){
  if(!raw) return null;
  if(typeof raw==='object'&&!Array.isArray(raw)) return raw;
  try{ var p=JSON.parse(raw); return (p&&typeof p==='object'&&!Array.isArray(p))?p:null; }catch(e){ return null; }
}
function _lcContratosFromLoc(l){
  if(!l) return [];
  var cq=_lcParseContratoQtds(l.contrato_qtds);
  if(cq) return Object.keys(cq);
  return l.contrato_id?[String(l.contrato_id)]:[];
}
function _lcContratosLista(){
  return (contratos||[]).filter(function(c){ return c.status!=='Cancelado'; })
    .sort(function(a,b){ return (a.nome||a.codigo||'').localeCompare(b.nome||b.codigo||'','pt-BR'); });
}
function _lcContratosCksHtml(selectedIds){
  var set={};
  (selectedIds||[]).forEach(function(id){ if(id) set[String(id)]=true; });
  var lista=_lcContratosLista();
  if(!lista.length) return '<span style="font-size:11px;color:#aaa">Sem contratos cadastrados — cadastre em Contratos</span>';
  return lista.map(function(c){
    var _nm=c.nome||c.codigo||c.id;
    var chk=set[String(c.id)]?' checked':'';
    return '<label style="display:inline-flex;align-items:center;gap:4px;font-size:11px;background:#fff;border:.5px solid #e0dfd8;border-radius:6px;padding:2px 8px;cursor:pointer;margin:2px">'
      +'<input type="checkbox" class="lc-contrato-ck" value="'+c.id+'" data-cod="'+escHtml(_nm)+'" onchange="lcAtualizarRateio()" style="width:13px;height:13px;margin:0"'+chk+'/>'
      +escHtml(_nm)+'</label>';
  }).join('');
}
function _lcHtmlSecaoContratos(selectedIds){
  return '<div class="fg" style="grid-column:1/-1;margin-top:8px"><label style="font-size:11px;font-weight:600">Contratos CENA que compartilham esta locação</label>'
    +'<div id="lc-contratos-cks" style="display:flex;flex-wrap:wrap;gap:5px;max-height:100px;overflow-y:auto;background:#fff;border:.5px solid #e0dfd8;border-radius:8px;padding:6px">'
    + _lcContratosCksHtml(selectedIds) +'</div>'
    +'<div style="font-size:10px;color:#888;margin-top:3px">Marque 1 contrato (a quantidade da linha vai toda para ele) ou 2+ (informe a quantidade por contrato em cada equipamento).</div></div>';
}
function _lcContratosSel(){
  return Array.prototype.map.call(document.querySelectorAll('.lc-contrato-ck:checked'),
    function(ck){ return { id:ck.value, cod:ck.getAttribute('data-cod')||'' }; });
}
function _lcLerRateioEl(container){
  if(!container) return { quantidade:1, contrato_qtds:null };
  var rats=container.querySelectorAll('.lc-rat');
  var qtdEl=container.querySelector('.lc-eq-qtd')||container.querySelector('#lc-qtd');
  if(rats.length){
    var _qtdMap={}, _qtd=0;
    rats.forEach(function(i){ var v=parseFloat(i.value)||0; if(v>0){ _qtdMap[i.getAttribute('data-cid')]=v; _qtd+=v; } });
    return { quantidade:_qtd||1, contrato_qtds:Object.keys(_qtdMap).length?_qtdMap:null };
  }
  return { quantidade:parseFloat((qtdEl||{}).value)||1, contrato_qtds:null };
}
function lcAtualizarRateio(){
  var sel=_lcContratosSel();
  function renderRat(ratEl, qtdEl, prevMap){
    if(!ratEl||!qtdEl) return;
    if(sel.length>=2){
      ratEl.innerHTML='<div style="font-size:10px;color:#185FA5;font-weight:600;margin-bottom:3px">Quantidade por contrato:</div>'
        +'<div style="display:flex;flex-wrap:wrap;gap:10px">'
        +sel.map(function(c){ return '<label style="display:inline-flex;align-items:center;gap:4px;font-size:11px;color:#555">'+escHtml(c.cod)
          +': <input class="lc-rat" data-cid="'+c.id+'" type="number" min="0" step="1" style="width:64px;font-size:11px" value="'+((prevMap&&prevMap[c.id])||'')+'" oninput="lcAtualizarTotal()"/></label>'; }).join('')
        +'</div>';
      ratEl.style.display='';
      qtdEl.readOnly=true; qtdEl.style.background='#f5f5f3'; qtdEl.title='Soma das quantidades por contrato';
    } else {
      ratEl.innerHTML=''; ratEl.style.display='none';
      qtdEl.readOnly=false; qtdEl.style.background=''; qtdEl.title='';
    }
  }
  document.querySelectorAll('#lc-eq-lista > div').forEach(function(row){
    var prev={};
    var rat=row.querySelector('.lc-eq-rateio');
    if(rat) rat.querySelectorAll('.lc-rat').forEach(function(i){ prev[i.getAttribute('data-cid')]=i.value; });
    renderRat(rat, row.querySelector('.lc-eq-qtd'), prev);
  });
  var editRat=document.getElementById('lc-edit-rateio');
  var editQtd=document.getElementById('lc-qtd');
  if(editRat&&editQtd){
    var prevE={};
    editRat.querySelectorAll('.lc-rat').forEach(function(i){ prevE[i.getAttribute('data-cid')]=i.value; });
    renderRat(editRat, editQtd, prevE);
  }
  lcAtualizarTotal();
}

function _lcLerRateioEdit(){
  var editRat=document.getElementById('lc-edit-rateio');
  var editQ=document.getElementById('lc-qtd');
  if(!editRat||!editRat.querySelectorAll('.lc-rat').length){
    return { quantidade:parseFloat((editQ||{}).value)||1, contrato_qtds:null };
  }
  var _qtdMap={}, _qtd=0;
  editRat.querySelectorAll('.lc-rat').forEach(function(i){
    var v=parseFloat(i.value)||0;
    if(v>0){ _qtdMap[i.getAttribute('data-cid')]=v; _qtd+=v; }
  });
  return { quantidade:_qtd||1, contrato_qtds:Object.keys(_qtdMap).length?_qtdMap:null };
}

function _openNovaLocacaoModal(seed){
  seed = seed || null;
  var filOpts='<option value="">Sem filial</option>'+filiais.map(function(f){return '<option value="'+f.id+'">'+f.codigo+' — '+f.nome+'</option>';}).join('');
  var depOpts='<option value="">Selecione a filial primeiro</option>';
  var titulo=seed&&seed.placa ? 'Novo contrato de locação — veículo Frotas' : 'Novo contrato de locação';

  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" id="modal-loc-inner" style="max-width:760px;padding:1.25rem">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem">'
    +'<h3 style="margin:0">'+titulo+'</h3>'
    +'<button class="btn btn-sm" onclick="closeModal()">✕</button>'
    +'</div>'
    +'<input type="hidden" id="lc-placa-seed" value="'+escHtml(seed&&seed.placa?seed.placa:'')+'"/>'
    +'<input type="hidden" id="lc-veiculo-id-seed" value="'+escHtml(seed&&seed.veiculo_id?String(seed.veiculo_id):'')+'"/>'

    // ── Cabeçalho do contrato ──
    +'<div style="background:#f9f9f7;border:.5px solid #e0dfd8;border-radius:10px;padding:.85rem;margin-bottom:1rem">'
    +'<div style="font-size:11px;font-weight:700;color:#533AB7;margin-bottom:.6rem">📋 DADOS DO CONTRATO</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px">'
    +_lcFornCampoHtml(seed&&seed.fornecedor_id?seed.fornecedor_id:null, seed&&seed.locadora?seed.locadora:'', 2)
    +'<div class="fg"><label style="font-size:11px">Nº Contrato</label><input class="inp" id="lc-num" placeholder="Ex: 8543" style="width:100%" value="'+escHtml(seed&&seed.numero_contrato?seed.numero_contrato:'')+'"/></div>'
    +_lcRespCampoHtml(seed&&seed.responsavel?seed.responsavel:'')
    +'<div class="fg"><label style="font-size:11px">Filial</label><select class="inp" id="lc-fil" style="width:100%" onchange="lcAtualizarDepositos(\'lc-dep\')">'+filOpts+'</select></div>'
    +'<div class="fg"><label style="font-size:11px">Depósito</label><select class="inp" id="lc-dep" style="width:100%">'+depOpts+'</select></div>'
    +'<div class="fg" style="display:flex;gap:6px">'
    +'<div class="fg" style="flex:1"><label style="font-size:11px">Início</label><input class="inp" id="lc-ini" type="date" style="width:100%" value="'+escHtml(_lcDateInput(seed&&seed.inicio)||'')+'" onchange="var f=document.getElementById(\'lc-fim\');if(f){f.min=this.value;if(f.value&&f.value<this.value)f.value=\'\';}"/></div>'
    +'<div class="fg" style="flex:1"><label style="font-size:11px">Término</label><input class="inp" id="lc-fim" type="date" style="width:100%" value="'+escHtml(_lcDateInput(seed&&seed.termino)||'')+'"/></div>'
    +'</div>'
    +'</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-top:8px">'
    +'<div class="fg"><label style="font-size:11px">Tem seguro?</label>'
    +'<select class="inp" id="lc-seg" onchange="toggleSeg()" style="width:100%"><option value="false"'+(seed&&seed.tem_seguro?'':' selected')+'>Não</option><option value="true"'+(seed&&seed.tem_seguro?' selected':'')+'>Sim</option></select></div>'
    +'<div class="fg" id="fg-seg" style="display:'+(seed&&seed.tem_seguro?'':'none')+'"><label style="font-size:11px">Valor seguro/mês</label><input class="inp" id="lc-vseg" type="number" step="0.01" style="width:100%" value="'+(seed&&seed.valor_seguro!=null?seed.valor_seguro:'')+'"/></div>'
    +'<div class="fg" style="grid-column:2/-1"><label style="font-size:11px">Observações</label><input class="inp" id="lc-obs" placeholder="Cliente, NF, remessa..." style="width:100%" value="'+escHtml(seed&&seed.observacoes?seed.observacoes:'')+'"/></div>'
    +'</div>'
    +_lcHtmlSecaoContratos(seed&&seed.contrato_id?[seed.contrato_id]:[])
    +'</div>'

    // ── Lista de equipamentos ──
    +'<div style="margin-bottom:1rem">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.5rem">'
    +'<div style="font-size:11px;font-weight:700;color:#185FA5">🔧 EQUIPAMENTOS</div>'
    +'<button class="btn btn-sm btn-pri" onclick="lcAddLinha()" style="font-size:11px">+ Adicionar equipamento</button>'
    +'</div>'
    +'<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:8px;overflow:hidden">'
    +'<div style="display:grid;grid-template-columns:2.4fr 1fr .6fr 1fr 1fr 1fr 1fr 28px;gap:0;background:#1a1a18;padding:5px 8px;font-size:10px;font-weight:700;color:#aaa">'
    +'<div>NOME / DESCRIÇÃO</div><div>TIPO</div><div>QTD</div><div>V.UNIT/MÊS</div><div>V.TOTAL</div><div>STATUS</div><div>DISPONIB.</div><div></div>'
    +'</div>'
    +'<div id="lc-eq-lista"></div>'
    +'</div>'
    +'<div style="text-align:right;font-size:12px;color:#185FA5;font-weight:600;margin-top:6px">Total: <span id="lc-total">R$ 0,00</span></div>'
    +'</div>'

    // ── Documentos + IA ──
    +'<div style="background:#f9f9f7;border:.5px solid #e0dfd8;border-radius:10px;padding:.85rem;margin-bottom:1rem">'
    +'<div style="font-size:11px;font-weight:700;color:#854F0B;margin-bottom:.5rem">📎 DOCUMENTOS</div>'
    +'<input type="file" id="lc-docs" multiple accept=".pdf,.jpg,.jpeg,.png,.doc,.docx,.xls,.xlsx" style="font-size:12px;width:100%"/>'
    +'<div style="font-size:10px;color:#888;margin-top:4px">PDF, imagens, Word, Excel — ao selecionar o contrato a IA pode preencher tudo automaticamente</div>'
    +'<div style="margin-top:.6rem;display:flex;align-items:center;gap:8px">'
    +'<button type="button" class="btn btn-sm" id="lc-btn-ia" onclick="lcAnalisarContrato()" style="background:#533AB7;color:#fff;border-color:#533AB7;display:none">🤖 Preencher com IA</button>'
    +'<span id="lc-ia-status" style="font-size:11px;color:#888"></span>'
    +'</div>'
    +'<div id="lc-docs-lista" style="margin-top:.5rem;display:flex;flex-wrap:wrap;gap:4px"></div>'
    +'</div>'

    +'<div class="ma">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="lc-btn-salvar">💾 Salvar contrato</button>'
    +'</div>'
    +'</div></div>');

  if(seed&&seed.placa){
    var inner=document.getElementById('modal-loc-inner');
    if(inner){
      var ban=document.createElement('div');
      ban.style.cssText='background:#E6F1FB;border:.5px solid #185FA5;border-radius:8px;padding:.6rem .75rem;margin-bottom:.85rem;font-size:12px;color:#185FA5';
      ban.innerHTML='🚗 Importado do cadastro de <b>Frotas</b> — placa <b>'+escHtml(String(seed.placa).toUpperCase())+'</b>. Revise e edite os dados antes de salvar.';
      var h3=inner.querySelector('h3');
      if(h3&&h3.parentNode) h3.parentNode.insertAdjacentElement('afterend', ban);
      else inner.insertBefore(ban, inner.firstChild);
    }
  }

  // Adicionar primeira linha (pré-preenchida se veio do Frotas)
  if(seed&&seed.equipamento) lcAddLinha(seed.equipamento);
  else lcAddLinha();

  if(seed&&seed.fornecedor_id){
    setTimeout(function(){ _lcPreencherFornSelect(seed.fornecedor_id, seed.locadora||''); },0);
  } else if(seed&&seed.locadora){
    setTimeout(function(){ _lcPreencherFornSelect(null, seed.locadora); },0);
  }

  // Listener arquivo
  var fileInp = document.getElementById('lc-docs');
  if(fileInp) fileInp.onchange = function(){
    var lista = document.getElementById('lc-docs-lista'); if(!lista) return;
    lista.innerHTML = Array.from(this.files).map(function(f){
      return '<span style="background:#EBF4FD;color:#185FA5;border-radius:4px;padding:1px 6px;font-size:11px">📄 '+f.name+'</span>';
    }).join('');
    var btnIA = document.getElementById('lc-btn-ia');
    var stIA  = document.getElementById('lc-ia-status');
    if(btnIA) btnIA.style.display = this.files.length ? '' : 'none';
    if(stIA)  stIA.textContent = this.files.length ? 'Clique para extrair dados do contrato automaticamente' : '';
  };

  var btn = document.getElementById('lc-btn-salvar');
  if(btn) btn.onclick = function(){ salvarLocacao(); };
  if(typeof lcAtualizarTotal==='function') lcAtualizarTotal();
}  // end _openNovaLocacaoModal

var _lcLinhaIdx = 0;

function lcAddLinha(eq){
  eq = eq || {};
  var idx = _lcLinhaIdx++;
  var lista = document.getElementById('lc-eq-lista'); if(!lista) return;
  var wrap = document.createElement('div');
  wrap.id  = 'lc-eq-row-'+idx;
  var tiposOpts = ['Equipamento','Gerador','Compressor','Andaime','Veículo','Ferramenta','EPI','EPC','Outro']
    .map(function(t){ return '<option'+(t===(eq.tipo||'Equipamento')?' selected':'')+'>'+t+'</option>'; }).join('');
  var statusOpts = ['Funcionando','Em manutenção','Com defeito']
    .map(function(s){ return '<option'+(s===(eq.status||'Funcionando')?' selected':'')+'>'+s+'</option>'; }).join('');
  var dispOpts = ['Disponível','Em uso','Em manutenção']
    .map(function(d){ return '<option'+(d===(eq.disponibilidade||'Em uso')?' selected':'')+'>'+d+'</option>'; }).join('');
  var _qtd=eq.quantidade||1;
  var _unit=eq.valor_unitario||eq.valor_locacao||'';
  wrap.innerHTML =
    '<div style="display:grid;grid-template-columns:2.4fr 1fr .6fr 1fr 1fr 1fr 1fr 28px;gap:0;border-bottom:.5px solid #f0efe8;align-items:center">'
    +'<div style="padding:4px 6px"><input class="inp lc-eq-nome" placeholder="Descrição do equipamento *" style="width:100%;font-size:11px" value="'+escHtml(eq.nome||'')+'" oninput="lcAtualizarTotal()"/>'
    +(eq.codigo?'<div style="font-size:10px;color:#aaa;margin-top:1px">Cód: '+escHtml(eq.codigo)+'</div>':'')
    +'</div>'
    +'<div style="padding:4px 4px"><select class="inp lc-eq-tipo" style="width:100%;font-size:11px;padding:5px 4px">'+tiposOpts+'</select></div>'
    +'<div style="padding:4px 4px"><input class="inp lc-eq-qtd" type="number" step="1" min="1" style="width:100%;font-size:11px" value="'+_qtd+'" oninput="lcAtualizarTotal()"/></div>'
    +'<div style="padding:4px 4px"><input class="inp lc-eq-valor" type="number" step="0.01" min="0" placeholder="0,00" style="width:100%;font-size:11px" value="'+_unit+'" oninput="lcAtualizarTotal()"/></div>'
    +'<div style="padding:4px 4px"><input class="inp lc-eq-total" readonly tabindex="-1" placeholder="0,00" style="width:100%;font-size:11px;background:#f5f5f3" value=""/></div>'
    +'<div style="padding:4px 4px"><select class="inp lc-eq-status" style="width:100%;font-size:11px;padding:5px 4px">'+statusOpts+'</select></div>'
    +'<div style="padding:4px 4px"><select class="inp lc-eq-disp" style="width:100%;font-size:11px;padding:5px 4px">'+dispOpts+'</select></div>'
    +'<div style="padding:4px;text-align:center"><button onclick="lcRemoveLinha(\'lc-eq-row-'+idx+'\')" style="background:none;border:none;color:#A32D2D;cursor:pointer;font-size:14px;line-height:1" title="Remover">✕</button></div>'
    +'</div>'
    +'<div class="lc-eq-rateio" style="display:none;padding:5px 8px 8px;background:#f9f9f7;border-bottom:.5px solid #f0efe8"></div>';
  lista.appendChild(wrap);
  if(eq.contrato_qtds&&typeof eq.contrato_qtds==='object'){
    var cq=eq.contrato_qtds;
    setTimeout(function(){
      lcAtualizarRateio();
      Object.keys(cq).forEach(function(cid){
        var inp=wrap.querySelector('.lc-rat[data-cid="'+cid+'"]');
        if(inp) inp.value=cq[cid];
      });
      lcAtualizarTotal();
    },0);
  } else {
    lcAtualizarRateio();
  }
}

function lcRemoveLinha(rowId){
  var el = document.getElementById(rowId); if(!el) return;
  // Não remover se for a última linha
  var lista = document.getElementById('lc-eq-lista');
  if(lista && lista.children.length <= 1){ progShowToast('⚠ O contrato precisa de ao menos um equipamento.'); return; }
  el.remove();
  lcAtualizarTotal();
}

function lcAtualizarTotal(){
  var total = 0;
  document.querySelectorAll('#lc-eq-lista > div').forEach(function(row){
    var qtdEl=row.querySelector('.lc-eq-qtd');
    var rats=row.querySelectorAll('.lc-rat');
    var q;
    if(rats.length){ q=0; rats.forEach(function(i){ q+=parseFloat(i.value)||0; }); if(qtdEl) qtdEl.value=q||qtdEl.value; }
    else { q=parseFloat((qtdEl||{}).value)||0; }
    var u=parseFloat((row.querySelector('.lc-eq-valor')||{}).value)||0;
    var t=q*u;
    var tEl=row.querySelector('.lc-eq-total');
    if(tEl) tEl.value=t?t.toFixed(2).replace('.',','):'';
    total+=t;
  });
  var editQ=document.getElementById('lc-qtd');
  var editU=document.getElementById('lc-vunit');
  var editT=document.getElementById('lc-vloc');
  if(editQ&&editU&&editT){
    var rats=document.querySelectorAll('#lc-edit-rateio .lc-rat');
    var q2;
    if(rats.length){ q2=0; rats.forEach(function(i){ q2+=parseFloat(i.value)||0; }); if(editQ.readOnly) editQ.value=q2; }
    else q2=parseFloat(editQ.value)||0;
    editT.value=+(q2*(parseFloat(editU.value)||0)).toFixed(2);
  }
  var el=document.getElementById('lc-total');
  if(el) el.textContent='R$ '+total.toFixed(2).replace('.',',');
}


function salvarLocacao(){
  _lcLerFornecedorForm().then(function(forn){
    var locadora=forn.locadora;
    if(!locadora.trim()){ progShowToast('⚠ Informe a locadora.'); return; }

  // Coletar linhas de equipamentos
  var rows = document.querySelectorAll('#lc-eq-lista > div');
  var equipamentos = [];
  var ok = true;
  rows.forEach(function(row){
    var nome = (row.querySelector('.lc-eq-nome')||{}).value||'';
    if(!nome.trim()){ ok = false; return; }
    var _unit = parseFloat((row.querySelector('.lc-eq-valor')||{}).value)||0;
    var rateio=_lcLerRateioEl(row);
    var _qtd=rateio.quantidade;
    equipamentos.push({
      nome:           nome.trim(),
      tipo:           (row.querySelector('.lc-eq-tipo')||{}).value||'Equipamento',
      quantidade:     _qtd,
      contrato_qtds:  rateio.contrato_qtds,
      valor_unitario: _unit,
      valor_total:    +(_qtd*_unit).toFixed(2),
      valor_locacao:  +(_qtd*_unit).toFixed(2),
      status:         (row.querySelector('.lc-eq-status')||{}).value||'Funcionando',
      disponibilidade:(row.querySelector('.lc-eq-disp')||{}).value||'Em uso',
    });
  });
  if(!ok || !equipamentos.length){ progShowToast('⚠ Preencha o nome de todos os equipamentos.'); return; }

  // Dados compartilhados do contrato
  var docs = [];
  var fileInp = document.getElementById('lc-docs');
  if(fileInp && fileInp.files.length)
    docs = Array.from(fileInp.files).map(function(f){return {nome:f.name,tamanho:f.size,tipo:f.type};});

  var numContrato = (document.getElementById('lc-num')||{}).value||'';
  var obsBase     = (document.getElementById('lc-obs')||{}).value||'';
  var placaSeed   = ((document.getElementById('lc-placa-seed')||{}).value||'').trim();
  var obsContrato = (numContrato ? 'Contrato: '+numContrato+' | ' : '') + obsBase;
  if(placaSeed && !_lcTextoContemPlaca(obsContrato, _lcNormPlaca(placaSeed))){
    obsContrato = 'Placa: '+_lcNormPlaca(placaSeed)+' | ' + obsContrato;
  }
  var _iniVal=(document.getElementById('lc-ini')||{}).value||'';
  var _fimVal=(document.getElementById('lc-fim')||{}).value||'';

  // Verificar duplicata: mesma locadora + mesmo período
  var _numCtRef = ((document.getElementById('lc-num')||{}).value||'').trim();
  var _dupExiste = locacoes.some(function(x){
    if((x.locadora||'').toLowerCase().trim() !== locadora.toLowerCase().trim()) return false;
    var _numX = (x.numero_contrato||'').trim() || ((x.observacoes||'').match(/Contrato:\s*([^|]+)/i)||[])[1]||'';
    if(_numCtRef && _numX) return _numX.trim().toLowerCase() === _numCtRef.toLowerCase();
    return (x.inicio||'') === _iniVal && (x.termino||'') === _fimVal;
  });
  if(_dupExiste){ progShowToast('⚠ Já existe um contrato cadastrado com esta locadora e mesmo período/número. Verifique antes de duplicar.'); return; }

  var contratosSel=_lcContratosSel();
  var _fd=_lcLerFilialDepForm();
  var base = {
    locadora:      locadora,
    fornecedor_id: forn.fornecedor_id||null,
    filial_id:     _fd.filial_id,
    deposito_id:   _fd.deposito_id,
    responsavel_id:null,
    responsavel:   _lcLerRespForm()||null,
    contrato_id:   contratosSel.length===1?contratosSel[0].id:null,
    inicio:        _iniVal||null,
    termino:       _fimVal||null,
    tem_seguro:    (document.getElementById('lc-seg')||{}).value==='true',
    valor_seguro:  parseFloat((document.getElementById('lc-vseg')||{}).value)||null,
    documentos:    docs.length ? JSON.stringify(docs) : null,
  };

  // Salvar um registro por equipamento
  equipamentos.forEach(function(eq, i){
    var novo = Object.assign({}, base, {
      id:              'lc'+Date.now()+i,
      nome:            eq.nome,
      tipo:            eq.tipo,
      quantidade:      eq.quantidade,
      contrato_qtds:   eq.contrato_qtds ? JSON.stringify(eq.contrato_qtds) : null,
      valor_unitario:  eq.valor_unitario,
      valor_total:     eq.valor_total,
      valor_locacao:   eq.valor_locacao,
      valor_aquisicao: null,
      status:          eq.status,
      disponibilidade: eq.disponibilidade,
      observacoes:     obsContrato,
      numero_contrato: numContrato||null,
    });
    locacoes.push(novo);
    if(!DEMO){
      var payload = Object.assign({}, novo); delete payload.id;
      // Capturar ID real para usar como chave dedup no estoque
      (function(_eq, _novo){
        sbInsert('locacoes', payload).then(function(r){
          var realId=r&&r[0]&&r[0].id;
          if(realId){var _i=locacoes.findIndex(function(x){return x.id===_novo.id;});if(_i>=0)locacoes[_i].id=realId;}
          if(_eq.tipo==='EPI'||_eq.tipo==='EPC'){
            var _cat=((typeof _epiCatalogo!=='undefined'?_epiCatalogo:[])||[]).find(function(c){return c.id===_eq.equipamento_ref_id;});
            sbInsert('estoque',{
              nome:          _eq.nome,
              tipo:          _eq.tipo,
              ca:            _cat?(_cat.ca||null):null,
              saldo:         _eq.quantidade,
              saldo_minimo:  0,
              custo_unitario:_eq.valor_unitario||null,
              fornecedor:    locadora,
              lote:          realId?'locid.'+realId:(numContrato?'Locação '+numContrato:'Locação '+locadora),
              filial_id:     base.filial_id,
              deposito_id:   base.deposito_id,
              contrato_id:   base.contrato_id,
              unidade_medida:'UN',
            }).then(function(r2){if(r2&&r2[0])(estoque=estoque||[]).push(r2[0]);}).catch(function(){});
          }
        }).catch(function(){});
      })(eq, novo);
    }
  });

  var _epiCount=equipamentos.filter(function(e){return e.tipo==='EPI'||e.tipo==='EPC';}).length;
  closeModal();
  renderLocacoes();
  progShowToast('✅ '+equipamentos.length+' equipamento(s) salvo(s)'+(docs.length?' com '+docs.length+' documento(s)':'')
    +(_epiCount?' · '+_epiCount+' EPI(s) registrado(s) no estoque':''));
  }).catch(function(){});
}

function lcAbrirEditarGrupo(idsCsv){
  var gen=++_lcModalGen;
  var ids=String(idsCsv||'').split(',').filter(Boolean);
  if(!ids.length) return;
  var itens=ids.map(function(id){ return _lcFindLoc(id); }).filter(Boolean);
  if(!itens.length){ progShowToast('⚠ Contrato não encontrado.'); return; }
  var g=_lcGrupoCabecalho(itens);
  var idsKey=ids.join(',');
  var selContr=[]; var cset={};
  itens.forEach(function(l){ _lcContratosFromLoc(l).forEach(function(cid){ if(!cset[cid]){ cset[cid]=1; selContr.push(cid); } }); });
  Promise.all([_lcPrepFornModal()].concat(ids.map(_lcFetchLoc))).then(function(){
    if(gen!==_lcModalGen) return;
    var itensAtual=ids.map(function(id){ return _lcFindLoc(id); }).filter(Boolean);
    if(itensAtual.length) g=_lcGrupoCabecalho(itensAtual);
    selContr=[]; cset={};
    itensAtual.forEach(function(l){ _lcContratosFromLoc(l).forEach(function(cid){ if(!cset[cid]){ cset[cid]=1; selContr.push(cid); } }); });
    var fornId=g.fornecedor_id||null;
    var filOpts='<option value="">Sem filial</option>'+filiais.map(function(f){
      return '<option value="'+f.id+'"'+(String(f.id)===String(g.filial_id)?' selected':'')+'>'+escHtml(f.codigo+' — '+f.nome)+'</option>';
    }).join('');
    var depOpts='<option value="">Sem depósito</option>'
      +(typeof depositos!=='undefined'?depositos.filter(function(d){ return !g.filial_id||String(d.filial_id)===String(g.filial_id); })
          .map(function(d){ return '<option value="'+d.id+'"'+(String(d.id)===String(g.deposito_id)?' selected':'')+'>'+escHtml(d.nome)+'</option>'; }).join(''):'');
    setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
      +'<div class="modal" style="max-width:720px;max-height:90vh;overflow-y:auto">'
      +'<h3 style="margin:0 0 .75rem">Editar contrato — '+escHtml(g.locadora||'—')+'</h3>'
      +'<div style="font-size:11px;color:#888;margin-bottom:.75rem">'+itensAtual.length+' equipamento(s) neste contrato</div>'
      +'<div style="background:#f9f9f7;border:.5px solid #e0dfd8;border-radius:10px;padding:.85rem;margin-bottom:1rem">'
      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">'
      +_lcFornCampoHtml(fornId, g.locadora||'', 2)
      +'<div class="fg"><label style="font-size:11px">Nº Contrato</label><input class="inp" id="lc-num" value="'+escHtml(g.numero_contrato||'')+'" style="width:100%"/></div>'
      +_lcRespCampoHtml(g.responsavel||'')
      +'<div class="fg"><label style="font-size:11px">Filial</label><select class="inp" id="lc-fil" style="width:100%" onchange="lcAtualizarDepositos(\'lc-dep\')">'+filOpts+'</select></div>'
      +'<div class="fg"><label style="font-size:11px">Depósito</label><select class="inp" id="lc-dep" style="width:100%">'+depOpts+'</select></div>'
      +'<div class="fg"><label style="font-size:11px">Início</label><input class="inp" id="lc-ini" type="date" value="'+g.inicio+'" style="width:100%"/></div>'
      +'<div class="fg"><label style="font-size:11px">Término</label><input class="inp" id="lc-fim" type="date" value="'+g.termino+'" min="'+g.inicio+'" style="width:100%"/></div>'
      +'<div class="fg"><label style="font-size:11px">Tem seguro?</label>'
      +'<select class="inp" id="lc-seg" style="width:100%"><option value="false"'+(g.tem_seguro?'':' selected')+'>Não</option><option value="true"'+(g.tem_seguro?' selected':'')+'>Sim</option></select></div>'
      +'<div class="fg"><label style="font-size:11px">Valor seguro/mês</label><input class="inp" id="lc-vseg" type="number" step="0.01" value="'+(g.valor_seguro!=null?g.valor_seguro:'')+'" style="width:100%"/></div>'
      +'<div class="fg" style="grid-column:1/-1"><label style="font-size:11px">Observações</label><textarea class="inp" id="lc-obs" style="width:100%;height:50px">'+escHtml(g.observacoes||'')+'</textarea></div>'
      +_lcHtmlSecaoContratos(selContr)
      +'</div></div>'
      +'<input type="hidden" id="lc-dep-original" value="">'
      +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'
      +'<button class="btn btn-pri" onclick="lcSalvarEditarGrupo(\''+idsKey+'\')">Salvar contrato ('+itensAtual.length+' itens)</button></div>'
      +'</div></div>');
    setTimeout(function(){
      _lcPreencherFornSelect(fornId, g.locadora||'');
      _lcSincronizarFilialDep(g.filial_id, g.deposito_id);
      var _depEl=document.getElementById('lc-dep');
      var _depOrig=document.getElementById('lc-dep-original');
      if(_depEl&&_depOrig) _depOrig.value=_depEl.value;
    }, 0);
  }).catch(function(){ progShowToast('⚠ Erro ao carregar contrato.'); });
}
function lcSalvarEditarGrupo(idsCsv){
  var ids=String(idsCsv||'').split(',').filter(Boolean);
  _lcLerFornecedorForm().then(function(forn){
    var ini=(document.getElementById('lc-ini')||{}).value||null;
    var fim=(document.getElementById('lc-fim')||{}).value||null;
    if(ini&&fim&&fim<ini){ progShowToast('⚠ A data de término não pode ser anterior à data de início.'); return; }
    var contratosSel=_lcContratosSel();
    var _fd=_lcLerFilialDepForm();
    var _depOrigEl=document.getElementById('lc-dep-original');
    var _depOrig=_depOrigEl?_depOrigEl.value:'__unset__';
    var _depSel=(document.getElementById('lc-dep')||{}).value||'';
    var patch={
      locadora:forn.locadora,
      fornecedor_id:forn.fornecedor_id||null,
      numero_contrato:(document.getElementById('lc-num')||{}).value||null,
      filial_id:_fd.filial_id,
      inicio:ini,
      termino:fim,
      tem_seguro:(document.getElementById('lc-seg')||{}).value==='true',
      valor_seguro:parseFloat((document.getElementById('lc-vseg')||{}).value)||null,
      observacoes:(document.getElementById('lc-obs')||{}).value||'',
    };
    // Só atualiza depósito se o usuário explicitamente mudou o valor no formulário
    if(_depOrig==='__unset__'||_depSel!==_depOrig){
      patch.deposito_id=_depSel||null;
    }
    _lcPatchResponsavel(patch);
    if(contratosSel.length===1){
      patch.contrato_id=contratosSel[0].id;
      patch.contrato_qtds=null;
    } else if(!contratosSel.length){
      patch.contrato_id=null;
      patch.contrato_qtds=null;
    } else {
      patch.contrato_id=null;
      progShowToast('ℹ Com 2+ contratos, o rateio por equipamento é editado item a item.');
    }
    var prom=[];
    ids.forEach(function(lid){
      var l=_lcFindLoc(lid);
      if(!l) return;
      Object.assign(l, patch);
      if(!DEMO) prom.push(sbUpdate('locacoes', patch, 'id=eq.'+lid));
    });
    Promise.all(prom).then(function(){
      closeModal();
      renderLocacoes();
      progShowToast('✅ Contrato atualizado ('+ids.length+' item(ns))');
    }).catch(function(e){
      progShowToast('❌ Erro ao salvar: '+(e&&e.message||e), 'erro');
    });
  }).catch(function(){});
}

function openEditarLocacao(lid){
  var gen=++_lcModalGen;
  var lidNorm=String(lid||'').trim();
  if(!lidNorm){ progShowToast('⚠ Locação inválida.'); return; }
  Promise.all([_lcPrepFornModal(), _lcFetchLoc(lidNorm)]).then(function(res){
    if(gen!==_lcModalGen) return;
    var l=res[1];
    if(!l){ progShowToast('⚠ Locação não encontrada.'); return; }
    var snap=_lcSnapFromLoc(l);
    if(!snap) return;
  var filOpts='<option value="">Sem filial</option>'+filiais.map(function(f){return '<option value="'+f.id+'"'+(String(f.id)===String(snap.filial_id)?' selected':'')+'>'+escHtml(f.codigo+' — '+f.nome)+'</option>';}).join('');
  var depOpts='<option value="">Sem depósito</option>'
    +(typeof depositos!=='undefined' ? depositos.filter(function(d){return !snap.filial_id||String(d.filial_id)===String(snap.filial_id);})
        .map(function(d){return '<option value="'+d.id+'"'+(String(d.id)===String(snap.deposito_id)?' selected':'')+'>'+escHtml(d.nome)+'</option>';}).join('') : '');
  var _dispOpts=['Disponível','Em uso','Em manutenção','Devolvido','Extraviado'];
  var _dispQtds=_lcDispQtdsFromLoc(snap);
  var docsAtual=[];
  try{ if(snap.documentos) docsAtual=JSON.parse(snap.documentos); }catch(e){}
  var fornId=snap.fornecedor_id||null;
  var selContr=_lcContratosFromLoc(snap);
  var cqMap=_lcParseContratoQtds(snap.contrato_qtds);

  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:680px;max-height:90vh;overflow-y:auto"><h3>Editar — '+escHtml(snap.nome)+'</h3>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">'
    +'<div class="fg" style="grid-column:1/-1"><label>Nome</label><input class="inp" id="lc-nome" value="'+escHtml(snap.nome)+'" style="width:100%"/></div>'
    +_lcFornCampoHtml(fornId, snap.locadora, 2)
    +_lcRespCampoHtml(snap.responsavel||'', '<label>Responsável</label>')
    +'<div class="fg"><label>Filial</label><select class="inp" id="lc-fil" style="width:100%" onchange="lcAtualizarDepositos(\'lc-dep\')">'+filOpts+'</select></div>'
    +'<div class="fg"><label>Depósito</label><select class="inp" id="lc-dep" style="width:100%">'+depOpts+'</select></div>'
    +'<div class="fg"><label>Início</label><input class="inp" id="lc-ini" type="date" value="'+snap.inicio+'" style="width:100%" onchange="var f=document.getElementById(\'lc-fim\');if(f){f.min=this.value;if(f.value&&f.value<this.value)f.value=\'\';}"/></div>'
    +'<div class="fg"><label>Término</label><input class="inp" id="lc-fim" type="date" value="'+snap.termino+'" min="'+snap.inicio+'" style="width:100%"/></div>'
    +'<div class="fg"><label>Quantidade</label><input class="inp" id="lc-qtd" type="number" min="1" step="1" value="'+snap.quantidade+'" style="width:100%" oninput="lcAtualizarTotal()"/></div>'
    +'<div class="fg"><label>Valor unit./mês (R$)</label><input class="inp" id="lc-vunit" type="number" step="0.01" value="'+snap.valor_unitario.toFixed(2)+'" style="width:100%" oninput="lcAtualizarTotal()"/></div>'
    +'<div class="fg"><label>Valor total/mês (R$)</label><input class="inp" id="lc-vloc" type="number" value="'+snap.valor_locacao+'" style="width:100%" readonly tabindex="-1"/></div>'
    +'<div class="fg"><label>Nº Contrato (fornecedor)</label><input class="inp" id="lc-num" value="'+escHtml(snap.numero_contrato)+'" placeholder="Ex.: CT-2026-001" style="width:100%"/></div>'
    +_lcHtmlSecaoContratos(selContr)
    +'<div id="lc-edit-rateio" style="grid-column:1/-1;display:none;padding:5px 8px;background:#f9f9f7;border-radius:8px;border:.5px solid #e0dfd8"></div>'
    +'<div class="fg" style="display:flex;align-items:center;gap:10px;padding-top:20px"><label style="display:flex;align-items:center;gap:6px;cursor:pointer;font-size:13px"><input type="checkbox" id="lc-seg"'+(snap.tem_seguro?' checked':'')+' style="width:16px;height:16px"> Tem seguro</label></div>'
    +'<div class="fg"><label>Valor do seguro (R$/mês)</label><input class="inp" id="lc-vseg" type="number" value="'+(snap.valor_seguro!=null?snap.valor_seguro:'')+'" style="width:100%"/></div>'
    +'<div class="fg"><label>Status</label><select class="inp" id="lc-status" style="width:100%"><option value=""></option>'+['Funcionando','Em manutenção','Com defeito'].map(function(s){return '<option value="'+s+'"'+(snap.status===s?' selected':'')+'>'+s+'</option>';}).join('')+'</select></div>'
    +'<div class="fg" style="grid-column:1/-1"><label>Disponibilidade — quantos em cada status</label>'
    +'<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin-top:4px">'
    +_dispOpts.map(function(s,i){return '<div style="text-align:center"><div style="font-size:10px;color:#555;margin-bottom:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="'+s+'">'+s+'</div><input class="inp" id="lc-disp-'+i+'" type="number" min="0" value="'+(_dispQtds[s]||0)+'" style="width:100%;text-align:center"/></div>';}).join('')
    +'</div></div>'
    +'<div class="fg" style="grid-column:1/-1"><label>Observações</label><textarea class="inp" id="lc-obs" style="width:100%;height:50px">'+escHtml(snap.observacoes)+'</textarea></div>'
    // Documentos existentes
    +(docsAtual.length?'<div class="fg" style="grid-column:1/-1"><label>📎 Documentos anexados</label>'
      +'<div style="display:flex;flex-wrap:wrap;gap:4px;margin-bottom:.4rem">'
      +docsAtual.map(function(d){return '<span style="background:#EBF4FD;color:#185FA5;border-radius:4px;padding:1px 6px;font-size:11px">📄 '+escHtml(d.nome||'doc')+'</span>';}).join('')
      +'</div></div>':'')
    // Novos documentos
    +'<div class="fg" style="grid-column:1/-1"><label>📎 Adicionar documentos</label>'
    +'<input type="file" id="lc-docs" multiple accept=".pdf,.jpg,.jpeg,.png,.doc,.docx,.xls,.xlsx" style="font-size:12px;width:100%"/>'
    +'<div id="lc-docs-lista" style="margin-top:4px;display:flex;flex-wrap:wrap;gap:4px"></div>'
    +'</div>'
    +'</div>'
    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="salvarEditarLocacao(\''+String(snap.id).replace(/'/g,"\\'")+'\')">Salvar</button></div></div></div>');

  setTimeout(function(){
    _lcPreencherFornSelect(fornId, snap.locadora);
    _lcSincronizarFilialDep(snap.filial_id, snap.deposito_id);
    lcAtualizarRateio();
    if(cqMap){
      Object.keys(cqMap).forEach(function(cid){
        var inp=document.querySelector('#lc-edit-rateio .lc-rat[data-cid="'+cid+'"]');
        if(inp) inp.value=cqMap[cid];
      });
    }
    lcAtualizarTotal();
  }, 0);

  var fileInp=document.getElementById('lc-docs');
  if(fileInp) fileInp.onchange=function(){
    var lista=document.getElementById('lc-docs-lista');if(!lista)return;
    lista.innerHTML=Array.from(this.files).map(function(f){
      return '<span style="background:#EBF4FD;color:#185FA5;border-radius:4px;padding:1px 6px;font-size:11px">📄 '+escHtml(f.name)+'</span>';
    }).join('');
  };
  }).catch(function(){ progShowToast('⚠ Erro ao carregar locação.'); });
}

function salvarEditarLocacao(lid){
  var l=_lcFindLoc(lid);if(!l)return;
  _lcLerFornecedorForm().then(function(forn){
  l.nome=(document.getElementById('lc-nome')||{}).value||l.nome;
  l.locadora=forn.locadora;
  l.fornecedor_id=forn.fornecedor_id||null;
  var _fdEdit=_lcLerFilialDepForm();
  l.filial_id=_fdEdit.filial_id;
  l.deposito_id=_fdEdit.deposito_id;
  var _lceRespVal=_lcLerRespForm();
  l.responsavel_id=null;
  l.responsavel=_lceRespVal||null;
  l.inicio=(document.getElementById('lc-ini')||{}).value||null;
  l.termino=(document.getElementById('lc-fim')||{}).value||null;
  if(l.inicio && l.termino && l.termino < l.inicio){ progShowToast('⚠ A data de término não pode ser anterior à data de início.'); return; }
  var rateio=_lcLerRateioEdit();
  var unit=parseFloat((document.getElementById('lc-vunit')||{}).value)||0;
  l.quantidade=rateio.quantidade;
  l.valor_unitario=unit;
  l.valor_locacao=+(rateio.quantidade*unit).toFixed(2);
  l.valor_total=l.valor_locacao;
  var contratosSel=_lcContratosSel();
  if(contratosSel.length===1){
    l.contrato_id=contratosSel[0].id;
    l.contrato_qtds=null;
  } else if(contratosSel.length>=2){
    l.contrato_id=null;
    l.contrato_qtds=rateio.contrato_qtds?JSON.stringify(rateio.contrato_qtds):null;
  } else {
    l.contrato_id=null;
    l.contrato_qtds=null;
  }
  l.numero_contrato=(document.getElementById('lc-num')||{}).value||null;
  l.tem_seguro=!!(document.getElementById('lc-seg')||{}).checked;
  l.valor_seguro=parseFloat((document.getElementById('lc-vseg')||{}).value)||null;
  var _stV=(document.getElementById('lc-status')||{}).value; if(_stV) l.status=_stV;
  var _dispOpts2=['Disponível','Em uso','Em manutenção','Devolvido','Extraviado'];
  var _dispMap={}; _dispOpts2.forEach(function(s,i){var v=parseInt((document.getElementById('lc-disp-'+i)||{}).value)||0; if(v>0)_dispMap[s]=v;});
  var _dk=Object.keys(_dispMap);
  if(_dk.length===1) l.disponibilidade=_dk[0];
  else if(_dk.length>1) l.disponibilidade=JSON.stringify(_dispMap);
  l.observacoes=(document.getElementById('lc-obs')||{}).value||'';
  // Novos documentos
  var fileInp=document.getElementById('lc-docs');
  if(fileInp&&fileInp.files.length){
    var docsAtual=[];try{if(l.documentos)docsAtual=JSON.parse(l.documentos);}catch(e){}
    var novosArqs=Array.from(fileInp.files).map(function(f){return{nome:f.name,tamanho:f.size,tipo:f.type};});
    l.documentos=JSON.stringify([...docsAtual,...novosArqs]);
  }
  if(!DEMO){
    var patch={
      nome:l.nome, locadora:l.locadora, fornecedor_id:l.fornecedor_id,
      filial_id:l.filial_id, deposito_id:l.deposito_id,
      responsavel:l.responsavel, responsavel_id:null,
      inicio:l.inicio, termino:l.termino,
      quantidade:l.quantidade, valor_unitario:l.valor_unitario,
      valor_locacao:l.valor_locacao, valor_total:l.valor_total,
      contrato_id:l.contrato_id, contrato_qtds:l.contrato_qtds,
      numero_contrato:l.numero_contrato,
      tem_seguro:l.tem_seguro, valor_seguro:l.valor_seguro,
      status:l.status, disponibilidade:l.disponibilidade,
      observacoes:l.observacoes, documentos:l.documentos
    };
    sbUpdate('locacoes', patch, 'id=eq.'+lid);
    // EPI/EPC → registrar no estoque SE ainda não foi (dedup por lote = 'locid.'+lid)
    if(l.tipo==='EPI'||l.tipo==='EPC'){
      sbFetch('estoque',{filters:['lote=eq.locid.'+lid]}).then(function(ex){
        if(ex&&ex.length) return; // já existe — não duplicar
        var _cat=((typeof _epiCatalogo!=='undefined'?_epiCatalogo:[])||[]).find(function(c){return c.id===l.equipamento_ref_id;});
        sbInsert('estoque',{
          nome:          l.nome,
          tipo:          l.tipo,
          ca:            _cat?(_cat.ca||null):null,
          saldo:         l.quantidade,
          saldo_minimo:  0,
          custo_unitario:l.valor_unitario||null,
          fornecedor:    l.locadora,
          lote:          'locid.'+lid,
          filial_id:     l.filial_id,
          deposito_id:   l.deposito_id,
          contrato_id:   l.contrato_id,
          unidade_medida:'UN',
        }).then(function(r){
          if(r&&r[0])(estoque=estoque||[]).push(r[0]);
          progShowToast('✅ Locação atualizada · EPI registrado no estoque');
        }).catch(function(){});
      }).catch(function(){});
    }
  }
  closeModal();renderLocacoes();
  if(!(l.tipo==='EPI'||l.tipo==='EPC')||DEMO) progShowToast('✅ Locação atualizada');
  }).catch(function(){});
}
function openOcLocacao(lid){
  var l=locacoes.find(function(x){return x.id===lid;});if(!l)return;
  setModal('<div class="modal-bg"><div class="modal"><h3>Ocorrência — '+l.nome+'</h3>'
    +'<div style="background:#f9f9f7;border-radius:8px;padding:.65rem;margin-bottom:.75rem;font-size:12px">Locadora: <b>'+l.locadora+'</b> | Até: <b>'+fmtD(l.termino)+'</b></div>'
    +'<div class="fg"><label>Tipo</label><select id="ocloc-tipo"><option>Defeito/mau funcionamento</option><option>Acidente/dano</option><option>Extravio</option><option>Manutencao solicitada</option><option>Devolucao antecipada</option></select></div>'
    +'<div class="fg"><label>Novo status</label><select id="ocloc-disp"><option>Em manutenção</option><option>Disponível</option><option>Devolvido</option><option>Extraviado</option></select></div>'
    +'<div class="fg"><label>Descrição</label><textarea id="ocloc-desc"></textarea></div>'
    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="salvarOcLocacao(\''+lid+'\')">Registrar</button></div></div></div>');
}
function salvarOcLocacao(lid){
  var l=locacoes.find(function(x){return x.id===lid;});if(!l)return;
  l.disponibilidade=(document.getElementById('ocloc-disp')||{}).value||l.disponibilidade;
  if(!DEMO)sbUpdate('locacoes',{disponibilidade:l.disponibilidade},'id=eq.'+lid);
  closeModal();renderLocacoes();
}
function lcExcluirLocacao(lid){
  var l=locacoes.find(function(x){return x.id===lid;});if(!l)return;
  if(!confirm('Excluir "'+l.nome+'" da locação?\nEsta ação não pode ser desfeita.')) return;
  locacoes=locacoes.filter(function(x){return x.id!==lid;});
  if(!DEMO) sbDelete('locacoes','id=eq.'+lid).catch(function(){});
  renderLocacoes();
  progShowToast('🗑 Equipamento removido da locação');
}
function _estoqueCodigoSku(e){
  var cod = String(e.codigo||'').trim();
  var sku = String(e.sku||'').trim();
  if((!cod||!sku) && typeof itens_catalogo!=='undefined'){
    var ic = null;
    if(e.item_id) ic = itens_catalogo.find(function(i){ return i.id===e.item_id; });
    if(!ic && e.nome) ic = itens_catalogo.find(function(i){ return (i.nome||'').toLowerCase()===(e.nome||'').toLowerCase(); });
    if(ic){
      if(!cod) cod = String(ic.codigo||'').trim();
      if(!sku) sku = String(ic.sku||'').trim();
    }
  }
  return {codigo:cod||'—', sku:sku||'—', codigoRaw:cod, skuRaw:sku};
}

function estPeriodoPadrao(){
  var d=new Date();
  return {
    ini:d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-01',
    fim:typeof dataHoje==='function'?dataHoje():(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'))
  };
}
function estMotivoEhEstornoRetro(txt){
  var mot=String(txt||'').toLowerCase();
  if(mot.indexOf('estorno')<0) return false;
  return mot.indexOf('separ')>=0 || mot.indexOf('retroagir')>=0 || mot.indexOf('req-cena')>=0;
}
function estMovEhDoItemDep(m, ref, depId){
  if(!m) return false;
  if(depId && m.deposito_id && String(m.deposito_id)!==String(depId)) return false;
  if(ref && ref.id && String(m.item_id||'')===String(ref.id)) return true;
  if(typeof almTimelineMatchMovItem==='function' && almTimelineMatchMovItem(m, ref)) return true;
  var cat=(itens_catalogo||[]).find(function(c){ return String(c.id)===String(m.item_id||''); });
  if(cat && ref && ref.codigo && String(cat.codigo||'')===String(ref.codigo||'')) return true;
  return false;
}
function estQtdEstornoRetro(ref, depId, ini, fim){
  var tot=0;
  (movimentacoes_itens||[]).forEach(function(m){
    if(m.deleted_at) return;
    if(String(m.tipo_mov||'')!=='entrada') return;
    if(!estMotivoEhEstornoRetro((m.motivo||'')+' '+(m.obs||''))) return;
    if(!estMovEhDoItemDep(m, ref, depId)) return;
    var dt=typeof almTimelineNormData==='function'?almTimelineNormData(m.data_mov):String(m.data_mov||'').slice(0,10);
    if(ini && dt && dt<ini) return;
    if(fim && dt && dt>fim) return;
    tot += Number(m.quantidade)||0;
  });
  return tot;
}
function estTxtMovEstorno(ev, m){
  var partes=[];
  if(m){ partes.push(m.motivo||'', m.obs||''); }
  if(ev){
    if(ev.mov){ partes.push(ev.mov.motivo||'', ev.mov.obs||''); }
    partes.push(ev.detalhe||'');
  }
  return partes.join(' ');
}
function estResumoPeriodoEstoque(ref, depId, filialId, ini, fim){
  var evs = (typeof almTimelineColetarEventos==='function')
    ? almTimelineColetarEventos(ref,{depId:depId||'', filialId:filialId||''})
    : [];
  var saldoAnt=0, ent=0, sai=0, dev=0, ghostSkipped=0;
  evs.forEach(function(ev){
    if(!ev.afetaSaldo) return;
    if(ev.tipo==='entrada' && estMotivoEhEstornoRetro(estTxtMovEstorno(ev, ev.mov))){
      var qg=Number(ev.qtd)||0;
      if(!(ini && ev.data<ini) && !(fim && ev.data>fim)) ghostSkipped += qg;
      return;
    }
    var q=Number(ev.qtd)||0;
    if(ini && ev.data<ini){
      saldoAnt += Number(ev.delta)||0;
      return;
    }
    if(fim && ev.data>fim) return;
    if(ev.tipo==='entrada'||(ev.tipo==='transferencia'&&ev.delta>0)) ent+=q;
    else if(ev.tipo==='devolucao') dev+=q;
    else if(ev.tipo==='entrega'||ev.tipo==='baixa'||ev.tipo==='saida'||ev.tipo==='ajuste'||ev.tipo==='perda'||ev.tipo==='quebra'||ev.tipo==='descarte'){
      if(ev.delta<0) sai+=q;
    }
    else if(ev.tipo==='transferencia'&&ev.delta<0) sai+=q;
  });
  var ghostDirect = estQtdEstornoRetro(ref, depId, ini, fim);
  var extra = Math.max(0, ghostDirect - ghostSkipped);
  if(extra>0) ent = Math.max(0, ent - extra);
  var ghost = ghostSkipped + extra;
  return {
    saldoAnterior:saldoAnt,
    entradas:ent,
    saidas:sai,
    devolucoes:dev,
    saldoAtual:saldoAnt+ent+dev-sai,
    ghost:ghost
  };
}
function estAbrirDetalheMov(elOrCodigo, depId, campo){
  var codigo, dep, camp;
  if(elOrCodigo && elOrCodigo.getAttribute){
    codigo=elOrCodigo.getAttribute('data-codigo')||'';
    dep=elOrCodigo.getAttribute('data-depid')||'';
    camp=elOrCodigo.getAttribute('data-campo')||'entrada';
  } else {
    codigo=elOrCodigo; dep=depId; camp=campo||'entrada';
  }
  var e=(estoque||[]).find(function(x){
    return String(x.codigo||'')===String(codigo||'') && String(x.deposito_id||'')===String(dep||'');
  }) || (estoque||[]).find(function(x){ return String(x.codigo||'')===String(codigo||''); });
  if(!e){ if(typeof progShowToast==='function') progShowToast('Item não encontrado.','erro'); return; }
  var ref=estRefTimeline(e);
  var ini=(document.getElementById('est-fil-ini')||{}).value||'';
  var fim=(document.getElementById('est-fil-fim')||{}).value||'';
  var linhas=[];
  (movimentacoes_itens||[]).forEach(function(m){
    if(m.deleted_at) return;
    if(!estMovEhDoItemDep(m, ref, e.deposito_id||dep)) return;
    var dt=typeof almTimelineNormData==='function'?almTimelineNormData(m.data_mov):String(m.data_mov||'').slice(0,10);
    if(ini && dt && dt<ini) return;
    if(fim && dt && dt>fim) return;
    var tipo=String(m.tipo_mov||'');
    var ghost=tipo==='entrada' && estMotivoEhEstornoRetro((m.motivo||'')+' '+(m.obs||''));
    if(camp==='entrada' && tipo!=='entrada' && tipo!=='devolucao' && !(tipo==='transferencia')) return;
    if(camp==='saida' && tipo!=='entrega' && tipo!=='baixa' && tipo!=='saida' && tipo!=='ajuste' && tipo!=='perda' && tipo!=='quebra' && tipo!=='descarte' && tipo!=='transferencia') return;
    linhas.push({
      data:dt, tipo:tipo, qtd:Number(m.quantidade)||0,
      motivo:m.motivo||m.obs||'—', ghost:ghost, status:m.status||'',
      id:m.id, item_id:m.item_id, deposito_id:m.deposito_id||dep,
      estornada:(typeof estEntradaJaEstornada==='function'?estEntradaJaEstornada(m.id):false)
    });
  });
  if(camp==='entrada') linhas=linhas.filter(function(l){ return l.tipo==='entrada'||l.tipo==='devolucao'; });
  var html='<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:560px">'
    +'<h3 style="font-size:15px;margin:0 0 .4rem">Origem — '+(camp==='entrada'?'Entradas no período':'Saídas no período')+'</h3>'
    +'<div style="font-size:12px;color:#555;margin-bottom:.75rem">'+escHtml(e.nome||'')+' · '+escHtml(e.codigo||'')+'</div>';
  if(!linhas.length){
    html+='<div style="padding:1rem;color:#888;font-size:13px">Nenhum lançamento no período.</div>';
  } else {
    var _podeEstornar = camp==='entrada' && typeof almCorrPodeSolicitar==='function' && almCorrPodeSolicitar();
    html+='<div style="overflow-x:auto"><table class="tbl tbl-r" style="font-size:12px"><thead><tr>'
      +'<th>Data</th><th>Tipo</th><th style="text-align:right">Qtd</th><th>Motivo</th>'+(camp==='entrada'?'<th></th>':'')+'</tr></thead><tbody>'
      +linhas.map(function(l){
        var acao='';
        if(camp==='entrada'){
          if(l.ghost || l.tipo!=='entrada') acao='';
          else if(l.estornada){ acao='<span style="font-size:10px;color:#854F0B;font-weight:700">ESTORNADA</span>'; if(_podeEstornar && l.id) acao+=' <button class="btn btn-sm" style="font-size:10px;margin-left:5px" onclick="estReverterEstornoEntrada(\''+String(l.id).replace(/[^a-zA-Z0-9_-]/g,'')+'\')">↩ Reverter</button>'; }
          else if(_podeEstornar && l.id) acao='<button class="btn btn-sm" style="color:#A32D2D;border-color:#A32D2D;font-size:10px" onclick="estAbrirEstornoEntrada(\''+String(l.id).replace(/[^a-zA-Z0-9_-]/g,'')+'\')">↩ Estornar</button>';
        }
        return '<tr'+(l.ghost||l.estornada?' style="opacity:.55"':'')+'>'
          +'<td>'+(typeof fmtD==='function'?fmtD(l.data):l.data)+'</td>'
          +'<td>'+escHtml(l.tipo)+(l.ghost?' <span style="color:#854F0B;font-size:10px">não soma no saldo</span>':'')+'</td>'
          +'<td style="text-align:right;font-weight:600">'+l.qtd+'</td>'
          +'<td style="font-size:11px">'+escHtml(l.motivo)+'</td>'
          +(camp==='entrada'?'<td style="text-align:right">'+acao+'</td>':'')+'</tr>';
      }).join('')+'</tbody></table></div>'
      +'<div style="font-size:11px;color:#888;margin-top:.6rem">'+(camp==='saida'
        ?'Só movimentação real de saída/entrega/baixa. Aprovação e reserva não aparecem aqui.'
        :'Estorno de separação/retroagir aparece riscado e não entra na coluna Entradas nem no saldo físico.')+'</div>';
  }
  html+='<div class="ma" style="margin-top:.85rem"><button class="btn btn-pri" onclick="closeModal()">Fechar</button></div></div></div>';
  setModal(html);
}

// ── Estorno de ENTRADA patrimonial SEM NF (entradas legadas / duplicadas) ──
// Reutiliza almBaixarSaldoEstoquePatrimonio (retira do saldo físico) e o padrão
// de ajuste inverso do estorno por NF. Só gestor (almCorrPodeSolicitar).
var _estEstornoEntrada=null, _estEstornando=false;
function estEntradaJaEstornada(movId){
  if(!movId) return false;
  return (movimentacoes_itens||[]).some(function(m){
    if(!m || m.deleted_at) return false;
    if(String(m.movimentacao_origem_id||'')!==String(movId)) return false;
    var tag=String(m.tipo_ajuste||'')+' '+String(m.motivo||'')+' '+String(m.obs||'');
    return /ESTORNO_ENTRADA/i.test(tag);
  });
}
function estEstornoLinhaEstoque(mov){
  if(!mov) return {cat:null,row:null};
  var cat=(itens_catalogo||[]).find(function(c){ return String(c.id)===String(mov.item_id); })
    ||{id:mov.item_id, nome:mov.nome||mov.item_nome||'Item'};
  var lista=(typeof almListarLinhasEstoqueItem==='function')?almListarLinhasEstoqueItem(cat):[];
  var row=(lista||[]).find(function(e){ return String(e.deposito_id||'')===String(mov.deposito_id||''); });
  if(!row && mov.estoque_id) row=(estoque||[]).find(function(e){ return String(e.id)===String(mov.estoque_id); });
  return {cat:cat, row:row};
}
async function estAbrirEstornoEntrada(movId){
  if(_estEstornando) return;
  if(typeof almCorrPodeSolicitar==='function' && !almCorrPodeSolicitar()){
    alert('Sem permissão para estornar entradas. Fale com o gestor do almoxarifado.'); return;
  }
  var mov=(movimentacoes_itens||[]).find(function(m){ return String(m.id)===String(movId); });
  if(!mov){ alert('Entrada não encontrada.'); return; }
  if(String(mov.tipo_mov||'')!=='entrada'){ alert('Só é possível estornar movimentos de entrada.'); return; }
  if(estEntradaJaEstornada(movId)){ alert('Esta entrada já foi estornada.'); return; }
  var qtd=Number(mov.quantidade)||0;
  if(qtd<=0){ alert('Quantidade da entrada inválida.'); return; }
  var loc=estEstornoLinhaEstoque(mov);
  if(!loc.row){ alert('Linha de estoque do depósito da entrada não encontrada — não é possível estornar com segurança.'); return; }
  var saldoAtual=Number(loc.row.saldo)||0;
  var apos=saldoAtual-qtd;
  var nome=(loc.cat&&loc.cat.nome)||mov.nome||'Item';
  var dep=(typeof depositos!=='undefined'?depositos:[]).find(function(d){ return String(d.id)===String(mov.deposito_id||''); });
  if(apos<-1e-9){
    almNfOverlay('<div class="modal" style="max-width:520px" onclick="event.stopPropagation()">'
      +'<h3 style="margin:0 0 .5rem">Não é possível estornar esta entrada</h3>'
      +'<p style="font-size:13px"><b>'+escHtml(nome)+'</b><br>Entrada: +'+qtd+' · Saldo disponível agora: '+saldoAtual+'.<br>Parte já foi movimentada após a entrada. Não gera estoque negativo.</p>'
      +'<div class="ma" style="margin-top:.8rem"><button class="btn btn-pri" onclick="almNfFecharOverlay()">Fechar</button></div></div>');
    return;
  }
  _estEstornoEntrada={mov:mov, row:loc.row, cat:loc.cat, qtd:qtd, atual:saldoAtual, apos:apos, nome:nome};
  almNfOverlay('<div class="modal" style="max-width:560px" onclick="event.stopPropagation()">'
    +'<h3 style="margin:0 0 .4rem">↩ Estornar entrada</h3>'
    +'<div style="font-size:12px;color:#555;margin-bottom:.6rem">'+escHtml(nome)+' · '+escHtml((dep&&dep.nome)||'depósito')+'</div>'
    +'<table class="tbl" style="font-size:12px"><thead><tr><th style="text-align:right">Saldo atual</th><th style="text-align:right">Entrada</th><th style="text-align:right">Estorno</th><th style="text-align:right">Saldo após</th></tr></thead>'
    +'<tbody><tr><td style="text-align:right">'+saldoAtual+'</td><td style="text-align:right">+'+qtd+'</td><td style="text-align:right;color:#A32D2D">−'+qtd+'</td><td style="text-align:right;font-weight:700">'+apos+'</td></tr></tbody></table>'
    +'<div style="margin-top:.75rem"><label style="font-size:11px;font-weight:600">Motivo *</label>'
    +'<select class="inp" id="est-ent-motivo" style="width:100%"><option value="">Selecione...</option>'
    +'<option>Entrada lançada em duplicidade</option><option>Entrada incorreta</option>'
    +'<option>Quantidade incorreta</option><option>Fornecedor incorreto</option>'
    +'<option>Entrada realizada por engano</option><option>Outro</option></select></div>'
    +'<div style="margin-top:.5rem"><label style="font-size:11px;font-weight:600">Justificativa *</label>'
    +'<textarea class="inp" id="est-ent-just" rows="3" style="width:100%" placeholder="Obrigatória para auditoria"></textarea></div>'
    +'<div style="margin-top:.7rem;background:#FEF3E2;color:#854F0B;padding:8px 10px;border-radius:8px;font-size:12px">'
    +'<b>CONFIRMAR ESTORNO?</b> Vai retirar '+qtd+' do saldo físico e registrar um ajuste inverso. Não apaga a entrada original.</div>'
    +'<div class="ma" style="margin-top:.85rem;display:flex;gap:8px">'
    +'<button class="btn" onclick="almNfFecharOverlay()">Cancelar</button>'
    +'<button class="btn btn-pri" id="est-ent-btn" style="background:#A32D2D;border-color:#A32D2D" onclick="estConfirmarEstornoEntrada()">Confirmar estorno</button>'
    +'</div></div>');
}
async function estConfirmarEstornoEntrada(){
  if(_estEstornando) return;
  var p=_estEstornoEntrada;
  if(!p||!p.mov){ return; }
  if(estEntradaJaEstornada(p.mov.id)){ alert('Esta entrada já foi estornada.'); almNfFecharOverlay(); return; }
  var mot=((document.getElementById('est-ent-motivo')||{}).value||'').trim();
  var just=((document.getElementById('est-ent-just')||{}).value||'').trim();
  if(!mot||!just){ alert('Informe motivo e justificativa.'); return; }
  var btn=document.getElementById('est-ent-btn');
  if(btn){ btn.disabled=true; btn.textContent='Estornando...'; }
  _estEstornando=true;
  try{
    var baixa=await almBaixarSaldoEstoquePatrimonio({row:p.row, qtd:p.qtd, itemCat:p.cat});
    if(!baixa.ok) throw new Error(baixa.msg||'Falha ao baixar o saldo.');
    var u={id:(usuarioLogado&&usuarioLogado.id)||null, nome:(usuarioLogado&&(usuarioLogado.nome||usuarioLogado.email))||''};
    var payload={
      item_id:p.mov.item_id,
      tipo_mov:'ajuste',
      quantidade:p.qtd,
      deposito_id:p.mov.deposito_id||null,
      filial_id:p.mov.filial_id||null,
      fornecedor:p.mov.fornecedor||null,
      nota_fiscal:p.mov.nota_fiscal||null,
      data_mov:dataHoje(),
      motivo:'ESTORNO_ENTRADA',
      tipo_ajuste:'ESTORNO_ENTRADA',
      movimentacao_origem_id:p.mov.id,
      obs:'ESTORNO_ENTRADA · '+mot+' · '+just+' · por '+u.nome,
      status:'Disponível',
      responsavel_id:u.id
    };
    var estId='movest'+Date.now();
    if(DEMO){
      movimentacoes_itens.push(Object.assign({id:estId}, payload));
    } else {
      var insE=await sbInsert('movimentacoes_itens', payload);
      if(!insE){
        // registro falhou: restaura o saldo baixado (não deixa saldo baixado sem histórico)
        p.row.saldo=(Number(p.row.saldo)||0)+p.qtd;
        await sbUpdate('estoque',{saldo:p.row.saldo},'id=eq.'+p.row.id);
        throw new Error('Falha ao registrar o movimento de estorno. Saldo restaurado.');
      }
      movimentacoes_itens.push(Object.assign({}, payload, insE[0]));
    }
    almNfFecharOverlay();
    _estEstornoEntrada=null;
    if(typeof progShowToast==='function') progShowToast('✅ Entrada estornada — '+p.qtd+' retirado do saldo de '+p.nome);
    try{ if(typeof renderEstoque==='function') renderEstoque(); }catch(e){}
    try{ if(typeof closeModal==='function') closeModal(); }catch(e){}
  }catch(e){
    alert('Não foi possível estornar: '+((e&&e.message)||e));
  }finally{
    _estEstornando=false;
    var b2=document.getElementById('est-ent-btn');
    if(b2){ b2.disabled=false; b2.textContent='Confirmar estorno'; }
  }
}
function estEstornoAjusteDe(origMovId){
  return (movimentacoes_itens||[]).find(function(m){
    if(!m || m.deleted_at) return false;
    if(String(m.movimentacao_origem_id||'')!==String(origMovId)) return false;
    var tag=String(m.tipo_ajuste||'')+' '+String(m.motivo||'')+' '+String(m.obs||'');
    return /ESTORNO_ENTRADA/i.test(tag);
  })||null;
}
var _estReverterEstorno=null;
async function estReverterEstornoEntrada(origMovId){
  if(_estEstornando) return;
  if(typeof almCorrPodeSolicitar==='function' && !almCorrPodeSolicitar()){ alert('Sem permissão para reverter estornos.'); return; }
  var aj=estEstornoAjusteDe(origMovId);
  if(!aj){ alert('Não há estorno ativo para reverter nesta entrada.'); return; }
  var orig=(movimentacoes_itens||[]).find(function(m){ return String(m.id)===String(origMovId); });
  var qtd=Number(aj.quantidade)||Number(orig&&orig.quantidade)||0;
  if(qtd<=0){ alert('Quantidade do estorno inválida.'); return; }
  var loc=estEstornoLinhaEstoque(aj);
  if(!loc.row){ alert('Linha de estoque não encontrada para reverter.'); return; }
  var nome=(loc.cat&&loc.cat.nome)||(orig&&orig.nome)||'Item';
  var atual=Number(loc.row.saldo)||0;
  _estReverterEstorno={aj:aj, orig:orig, row:loc.row, qtd:qtd, nome:nome};
  almNfOverlay('<div class="modal" style="max-width:540px" onclick="event.stopPropagation()">'
    +'<h3 style="margin:0 0 .4rem">↩ Reverter estorno</h3>'
    +'<div style="font-size:12px;color:#555;margin-bottom:.6rem">'+escHtml(nome)+'</div>'
    +'<p style="font-size:13px">Isto vai <b>devolver +'+qtd+'</b> ao saldo (de '+atual+' para '+(atual+qtd)+') e reativar a entrada. O estorno fica marcado como revertido (histórico preservado).</p>'
    +'<div style="margin-top:.5rem"><label style="font-size:11px;font-weight:600">Justificativa *</label>'
    +'<textarea class="inp" id="est-rev-just" rows="3" style="width:100%" placeholder="Ex.: estorno feito na entrada errada"></textarea></div>'
    +'<div class="ma" style="margin-top:.85rem;display:flex;gap:8px">'
    +'<button class="btn" onclick="almNfFecharOverlay()">Cancelar</button>'
    +'<button class="btn btn-pri" id="est-rev-btn" onclick="estConfirmarReverterEstorno()">Confirmar reversão</button>'
    +'</div></div>');
}
async function estConfirmarReverterEstorno(){
  if(_estEstornando) return;
  var p=_estReverterEstorno;
  if(!p||!p.aj){ return; }
  var just=((document.getElementById('est-rev-just')||{}).value||'').trim();
  if(!just){ alert('Informe a justificativa.'); return; }
  if(!estEstornoAjusteDe(p.orig?p.orig.id:p.aj.movimentacao_origem_id)){ alert('Este estorno já foi revertido.'); almNfFecharOverlay(); return; }
  var btn=document.getElementById('est-rev-btn');
  if(btn){ btn.disabled=true; btn.textContent='Revertendo...'; }
  _estEstornando=true;
  try{
    var novoSaldo=(Number(p.row.saldo)||0)+p.qtd;
    var u=(usuarioLogado&&(usuarioLogado.nome||usuarioLogado.email))||'';
    if(DEMO){
      p.row.saldo=novoSaldo;
      p.aj.deleted_at=new Date().toISOString();
      p.aj.obs=(p.aj.obs||'')+' | REVERTIDO: '+just+' · por '+u;
    } else {
      var okS=await sbUpdate('estoque',{saldo:novoSaldo},'id=eq.'+p.row.id);
      if(!okS) throw new Error('Falha ao restaurar o saldo.');
      p.row.saldo=novoSaldo;
      var okD=await sbUpdate('movimentacoes_itens',{deleted_at:new Date().toISOString(), obs:(p.aj.obs||'')+' | REVERTIDO: '+just+' · por '+u},'id=eq.'+p.aj.id);
      if(!okD){
        p.row.saldo=novoSaldo-p.qtd;
        await sbUpdate('estoque',{saldo:p.row.saldo},'id=eq.'+p.row.id);
        throw new Error('Falha ao marcar o estorno como revertido. Saldo restaurado ao estado anterior.');
      }
      p.aj.deleted_at=new Date().toISOString();
    }
    almNfFecharOverlay();
    _estReverterEstorno=null;
    if(typeof progShowToast==='function') progShowToast('✅ Estorno revertido — +'+p.qtd+' devolvido ao saldo de '+p.nome);
    try{ if(typeof renderEstoque==='function') renderEstoque(); }catch(e){}
    try{ if(typeof closeModal==='function') closeModal(); }catch(e){}
  }catch(e){
    alert('Não foi possível reverter: '+((e&&e.message)||e));
  }finally{
    _estEstornando=false;
    var b2=document.getElementById('est-rev-btn'); if(b2){ b2.disabled=false; b2.textContent='Confirmar reversão'; }
  }
}
function estAbrirDetalheReserva(el){
  var codigo=el&&el.getAttribute?el.getAttribute('data-codigo')||'':'';
  var dep=el&&el.getAttribute?el.getAttribute('data-depid')||'':'';
  var e=(estoque||[]).find(function(x){
    return String(x.codigo||'')===String(codigo||'') && String(x.deposito_id||'')===String(dep||'');
  }) || (estoque||[]).find(function(x){ return String(x.codigo||'')===String(codigo||''); });
  if(!e){ if(typeof progShowToast==='function') progShowToast('Item não encontrado.','erro'); return; }
  var cs=_estoqueCodigoSku(e);
  var linhas=[];
  (_almReq.lista||[]).forEach(function(r){
    if(!almReqStEhReservaAberta(r.status)) return;
    if(dep && String(r.deposito_id||'')!==String(dep)) return;
    (_almReq.itens[r.id]||[]).forEach(function(it){
      var ok=(e.item_id && String(it.item_id||'')===String(e.item_id))
        || (cs.codigoRaw && String(it.item_codigo||'').toLowerCase()===String(cs.codigoRaw).toLowerCase())
        || (e.nome && String(it.item_descricao||'').toLowerCase()===String(e.nome).toLowerCase());
      if(!ok) return;
      var q=almReqItemQtdReservada(it);
      if(!(q>0)) return;
      linhas.push({num:r.numero||'', st:almReqStLabel(r.status), qtd:q, apr:Number(it.quantidade_aprovada!=null?it.quantidade_aprovada:it.quantidade_solicitada)||0, atd:Number(it.quantidade_atendida)||0});
    });
  });
  var html='<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:560px">'
    +'<h3 style="font-size:15px;margin:0 0 .4rem">Reservado — não é saída</h3>'
    +'<div style="font-size:12px;color:#555;margin-bottom:.75rem">'+escHtml(e.nome||'')+' · '+escHtml(e.codigo||'')+'</div>'
    +'<div style="background:#FEF3E2;border-radius:8px;padding:8px 10px;font-size:11px;color:#854F0B;margin-bottom:.6rem">Reserva = quantidade aprovada − atendida, em requisições abertas. Não baixa o saldo físico.</div>';
  if(!linhas.length){
    html+='<div style="padding:1rem;color:#888;font-size:13px">Nenhuma reserva aberta neste item/depósito.</div>';
  } else {
    html+='<table class="tbl tbl-r" style="font-size:12px"><thead><tr><th>Requisição</th><th>Status</th><th style="text-align:right">Aprovada</th><th style="text-align:right">Atendida</th><th style="text-align:right">Reservado</th></tr></thead><tbody>'
      +linhas.map(function(l){
        return '<tr><td>'+escHtml(l.num)+'</td><td>'+escHtml(l.st)+'</td><td style="text-align:right">'+l.apr+'</td><td style="text-align:right">'+l.atd+'</td><td style="text-align:right;font-weight:700">'+l.qtd+'</td></tr>';
      }).join('')+'</tbody></table>';
  }
  html+='<div class="ma" style="margin-top:.85rem"><button class="btn btn-pri" onclick="closeModal()">Fechar</button></div></div></div>';
  setModal(html);
}
function estRefTimeline(e){
  var cat=(itens_catalogo||[]).find(function(c){
    return (typeof almMatchEstoqueRef==='function' && almMatchEstoqueRef(e,c))
      || (e.item_id && String(c.id)===String(e.item_id));
  });
  if(!cat && e.codigo){
    var cod=String(e.codigo||'').trim();
    if(cod) cat=(itens_catalogo||[]).find(function(c){ return String(c.codigo||'').trim()===cod; });
  }
  if(!cat && e.nome){
    var nl=String(e.nome||'').trim().toLowerCase();
    if(nl) cat=(itens_catalogo||[]).find(function(c){ return String(c.nome||'').trim().toLowerCase()===nl; });
  }
  return cat
    ? {id:cat.id, nome:cat.nome, codigo:cat.codigo||e.codigo, sku:cat.sku||e.sku, ref:cat}
    : {id:e.item_id||null, nome:e.nome, codigo:e.codigo, sku:e.sku, ref:e};
}
function estStatusLinha(saldoAtual, reservado, disponivel, minimo, temMov){
  if(saldoAtual<0) return {k:'negativo', label:'Saldo negativo', cor:'#A32D2D'};
  if(saldoAtual<=0) return {k:'sem-saldo', label:'Sem saldo', cor:'#A32D2D'};
  if(disponivel<=0) return {k:'reservado-total', label:'Reservado total', cor:'#854F0B'};
  if(disponivel<=minimo) return {k:'baixo', label:'Baixo estoque', cor:'#854F0B'};
  if(!temMov) return {k:'sem-mov', label:'Sem movimentação', cor:'#888'};
  return {k:'disponivel', label:'Disponível', cor:'#3B6D11'};
}
function estUltimaMovData(e){
  var best='';
  var ref=estRefTimeline(e);
  if(typeof almTimelineColetarEventos==='function'){
    (almTimelineColetarEventos(ref,{depId:e.deposito_id||'', filialId:e.filial_id||''})||[]).forEach(function(ev){
      if(ev.data && ev.data>best) best=ev.data;
    });
    if(best) return best;
  }
  (movimentacoes_itens||[]).forEach(function(m){
    var ok=(e.item_id && String(m.item_id)===String(e.item_id))
      || (ref.id && String(m.item_id)===String(ref.id))
      || (typeof almTimelineMatchMovItem==='function' && almTimelineMatchMovItem(m, ref))
      || (e.nome && String(m.item_nome||m.descricao||'').toLowerCase()===String(e.nome||'').toLowerCase());
    if(!ok) return;
    if(e.deposito_id && m.deposito_id && String(m.deposito_id)!==String(e.deposito_id)) return;
    var dt=typeof almTimelineNormData==='function'?almTimelineNormData(m.data_mov):String(m.data_mov||'').slice(0,10);
    if(dt && dt>best) best=dt;
  });
  return best;
}

function estFiltrosAtuais(){
  var pad = estPeriodoPadrao();
  var elIni = document.getElementById('est-fil-ini');
  var elFim = document.getElementById('est-fil-fim');
  if(elIni && !elIni.value) elIni.value = pad.ini;
  if(elFim && !elFim.value) elFim.value = pad.fim;
  return {
    tipo: (document.getElementById('est-fil-tipo')||{}).value||'',
    filial: (document.getElementById('est-fil-filial')||{}).value||'',
    deposito: (document.getElementById('est-fil-deposito')||{}).value||'',
    status: (document.getElementById('est-fil-status')||{}).value||'',
    busca: ((document.getElementById('est-fil-busca')||{}).value||'').toLowerCase(),
    ini: (elIni&&elIni.value)||pad.ini,
    fim: (elFim&&elFim.value)||pad.fim
  };
}
function estLinhaCalc(e, filtIni, filtFim){
  var dep = (typeof depositos!=='undefined'&&e.deposito_id)?depositos.find(function(d){return d.id===e.deposito_id;})||null:null;
  var filIdShow = e.filial_id || (dep && dep.filial_id) || null;
  var fil = (typeof filiais!=='undefined'&&filIdShow)?filiais.find(function(f){return f.id===filIdShow;})||null:null;
  var localLabel = (fil||dep)
    ? (fil ? ((fil.codigo?fil.codigo+' — ':'')+fil.nome) : '—')+(dep ? ' / '+dep.nome : '')
    : '—';
  var cs = _estoqueCodigoSku(e);
  var ref = estRefTimeline(e);
  var res = estResumoPeriodoEstoque(ref, e.deposito_id||'', filIdShow||'', filtIni, filtFim);
  var entradas = (Number(res.entradas)||0) + (Number(res.devolucoes)||0);
  var saidas = Number(res.saidas)||0;
  var saldoAnt = Number(res.saldoAnterior)||0;
  var saldoAtual = saldoAnt + entradas - saidas;
  var saldoTabela = Number(e.saldo)||0;
  var ledgerVazio = entradas===0 && saidas===0 && saldoAnt===0 && !(Number(res.ghost)||0);
  if(ledgerVazio && saldoTabela){
    saldoAtual = saldoTabela;
  }
  var sMin = Number(e.saldo_minimo!=null?e.saldo_minimo:5)||0;
  var reserva = (typeof almReqReservaEstoque==='function')
    ? almReqReservaEstoque(e.item_id, cs.codigoRaw||e.codigo, e.deposito_id, e.nome)
    : ((typeof almReqReserva==='function')?almReqReserva(e.item_id, cs.codigoRaw||e.codigo, e.deposito_id, e.nome):0);
  var disponivel = saldoAtual - reserva;
  var temMov = entradas>0 || saidas>0;
  var st = estStatusLinha(saldoAtual, reserva, disponivel, sMin, temMov);
  return {
    e:e, dep:dep, fil:fil, localLabel:localLabel, cs:cs,
    saldoAnt:saldoAnt, entradas:entradas, saidas:saidas, saldoAtual:saldoAtual,
    reserva:reserva, disponivel:disponivel, sMin:sMin, st:st, temMov:temMov,
    ghost:Number(res.ghost)||0,
    un:e.unidade_medida||e.unidade||'UN',
    ultima:estUltimaMovData(e)
  };
}
function estColetarLinhas(filtros){
  var f = filtros || estFiltrosAtuais();
  var brutos = (typeof estoque!=='undefined'?estoque:[]).filter(function(e){
    if(f.tipo && !eeTipoItemMatch(e.tipo, f.tipo)) return false;
    if(f.filial){
      if(e.filial_id){
        if(String(e.filial_id)!==String(f.filial)) return false;
      } else {
        var depFil = (typeof depositos!=='undefined'?depositos:[]).find(function(d){ return d.id===e.deposito_id; });
        if(!depFil || String(depFil.filial_id||'')!==String(f.filial)) return false;
      }
    }
    if(f.deposito && e.deposito_id!==f.deposito) return false;
    if(f.busca){
      var cs = _estoqueCodigoSku(e);
      if(!(e.nome||'').toLowerCase().includes(f.busca)
        && !cs.codigoRaw.toLowerCase().includes(f.busca)
        && !cs.skuRaw.toLowerCase().includes(f.busca)) return false;
    }
    return true;
  }).map(function(e){ return estLinhaCalc(e, f.ini, f.fim); });
  return brutos.filter(function(row){
    return !f.status || row.st.k===f.status;
  });
}

function renderEstoque(){
  var tbody = document.getElementById('tbody-est'); if(!tbody) return;
  if(!DEMO && typeof almGarantirLedgerEstoque==='function' && !window._estLedgerRendering && !window._almLedgerEstoqueOk){
    window._estLedgerRendering = true;
    almGarantirLedgerEstoque(function(){
      window._estLedgerRendering = false;
      renderEstoque();
    });
  }
  if(!DEMO && typeof _almReq!=='undefined' && typeof almReqGarantirListaSilent==='function' && !_almReq._estRendering){
    var precisaReq = !_almReq._estoqueReqOk || _almReq.filaStale;
    if(precisaReq){
      _almReq._estRendering = true;
      Promise.resolve(almReqGarantirListaSilent()).then(function(){
        _almReq._estoqueReqOk = true;
        _almReq._estRendering = false;
        renderEstoque();
      });
    }
  }

  // Popular filtro de filiais (só uma vez; preserva seleção)
  var selFil = document.getElementById('est-fil-filial');
  if(selFil && typeof filiais!=='undefined' && filiais.length && selFil.options.length<=1){
    var filAnt = selFil.value||'';
    selFil.innerHTML = '<option value="">Todas as filiais</option>'
      + filiais.map(function(f){ return '<option value="'+f.id+'">'+(f.codigo?f.codigo+' — ':'')+escHtml(f.nome||'')+'</option>'; }).join('');
    if(filAnt && filiais.some(function(f){ return f.id===filAnt; })) selFil.value = filAnt;
    else selFil.value = '';
  }

  // Popular depósitos só quando a filial muda (rebuild a cada renderEstoque
  // apagava a seleção do depósito no onchange / busca)
  var selDep = document.getElementById('est-fil-deposito');
  if(selDep && typeof depositos!=='undefined'){
    var filSelDep = (document.getElementById('est-fil-filial')||{}).value||'';
    var lastFilDep = selDep.getAttribute('data-filial-filtro');
    var precisaRebuildDep = (lastFilDep===null) || (lastFilDep!==filSelDep) || selDep.options.length<=1;
    if(precisaRebuildDep){
      var depAnt = selDep.value||'';
      var deps = depositos.filter(function(d){
        return !d.deleted_at && (!filSelDep || String(d.filial_id||'')===String(filSelDep));
      });
      selDep.innerHTML = '<option value="">Todos os depósitos</option>'
        + deps.map(function(d){ return '<option value="'+d.id+'">'+escHtml(d.nome||'')+'</option>'; }).join('');
      selDep.setAttribute('data-filial-filtro', filSelDep);
      if(depAnt && deps.some(function(d){ return d.id===depAnt; })) selDep.value = depAnt;
      else selDep.value = '';
    }
  }

  // Popular filtro de tipos a partir dos tipos realmente presentes no estoque
  // (garante que as opções batem com os dados — evita mismatch de maiúsc./minúsc. ou valores ausentes)
  var selTipo = document.getElementById('est-fil-tipo');
  if(selTipo){
    var tiposPresentes = {};
    (typeof estoque!=='undefined'?estoque:[]).forEach(function(e){
      var t=almTipoCodigo(e.tipo||'') || String(e.tipo||'').trim();
      if(t) tiposPresentes[t]=true;
    });
    TIPOS_ITEM.forEach(function(t){ if(t) tiposPresentes[t]=true; });
    var keysTipo = Object.keys(tiposPresentes).sort();
    if(keysTipo.length){
      var selAnterior = selTipo.value || '';
      selTipo.innerHTML = '<option value="">TODOS OS TIPOS</option>'
        + keysTipo.map(function(t){ return '<option value="'+escHtml(t)+'">'+escHtml(tipoItemLabel(t))+'</option>'; }).join('');
      // Importante: eeTipoItemMatch(x,'') é sempre true — não usar find com filtro vazio
      // senão "TODOS" cai no primeiro tipo da lista a cada onchange.
      if(selAnterior){
        var matchAnt = keysTipo.find(function(t){ return eeTipoItemMatch(t, selAnterior); });
        selTipo.value = matchAnt || '';
      } else {
        selTipo.value = '';
      }
    }
  }

  var lista = estColetarLinhas();

  var metr = document.getElementById('est-metricas');
  if(metr){
    var nDisp = lista.filter(function(r){ return r.st.k==='disponivel'; }).length;
    var nBaixo = lista.filter(function(r){ return r.st.k==='baixo'; }).length;
    var nSem = lista.filter(function(r){ return r.st.k==='sem-saldo'||r.st.k==='negativo'; }).length;
    var nRes = lista.filter(function(r){ return r.st.k==='reservado-total'; }).length;
    metr.innerHTML = [
      {l:'Itens',c:'#185FA5',v:lista.length},
      {l:'Disponível',c:'#3B6D11',v:nDisp},
      {l:'Baixo estoque',c:'#854F0B',v:nBaixo},
      {l:'Sem saldo',c:'#A32D2D',v:nSem},
      {l:'Reservado total',c:'#854F0B',v:nRes},
    ].map(function(m){
      return '<div class="card" style="padding:.6rem;text-align:center">'
        +'<div style="font-size:11px;color:#888">'+m.l+'</div>'
        +'<div style="font-size:18px;font-weight:700;color:'+m.c+'">'+m.v+'</div></div>';
    }).join('');
  }

  if(!lista.length){
    tbody.innerHTML = '<tr><td colspan="15" style="padding:2rem;text-align:center;color:#aaa">'
      +(typeof estoque!=='undefined'&&estoque.length?'Nenhum item para os filtros selecionados.':'Nenhum item no estoque. Use 📥 Nova entrada para cadastrar.')
      +'</td></tr>';
    return;
  }

  tbody.innerHTML = lista.map(function(row){
    var e=row.e;
    var corAnt='#888', corEnt=row.entradas>0?'#3B6D11':'#888', corSai=row.saidas>0?'#A32D2D':'#888';
    var corAtual=row.saldoAtual<0?'#A32D2D':row.saldoAtual<=0?'#A32D2D':'#1a1a18';
    var corRes=row.reserva>0?'#854F0B':'#888';
    var corDisp=row.disponivel<=0?'#A32D2D':(row.disponivel<=row.sMin?'#854F0B':'#3B6D11');
    return '<tr>'
      +'<td><span class="bdg info" style="font-size:10px">'+escHtml(tipoItemLabel?tipoItemLabel(e.tipo||''):(e.tipo||'—'))+'</span></td>'
      +'<td style="font-size:11px;color:#666;font-family:monospace">'+escHtml(row.cs.codigo)+'</td>'
      +'<td style="font-weight:600">'+escHtml(e.nome||'')+'</td>'
      +'<td style="font-size:11px;color:#888">'+escHtml(row.un)+'</td>'
      +'<td style="font-size:11px">'+escHtml(row.localLabel)+'</td>'
      +'<td style="text-align:right;color:'+corAnt+'">'+row.saldoAnt+'</td>'
      +'<td style="text-align:right;font-weight:600;color:'+corEnt+';cursor:pointer;text-decoration:underline dotted" '
      +'title="'+(row.ghost?row.ghost+' un. de estorno/retroagir não somam no saldo. Clique para ver.':'Ver origem das entradas')+'" '
      +'onclick="estAbrirDetalheMov(this)" data-codigo="'+escHtml(e.codigo||'')+'" data-depid="'+escHtml(e.deposito_id||'')+'" data-campo="entrada">'
      +(row.entradas||'—')+'</td>'
      +'<td style="text-align:right;font-weight:600;color:'+corSai+';cursor:pointer;text-decoration:underline dotted" '
      +'title="Saídas reais do período (movimentação). Clique para ver." '
      +'onclick="estAbrirDetalheMov(this)" data-codigo="'+escHtml(e.codigo||'')+'" data-depid="'+escHtml(e.deposito_id||'')+'" data-campo="saida">'
      +(row.saidas||'—')+'</td>'
      +'<td style="text-align:right;font-weight:700;color:'+corAtual+'" title="Saldo anterior + entradas − saídas">'+row.saldoAtual+'</td>'
      +'<td style="text-align:right;font-weight:600;color:'+corRes+';cursor:pointer;text-decoration:underline dotted" '
      +'title="Aprovada/separação ainda não atendida. Não é saída. Clique para ver." '
      +'onclick="estAbrirDetalheReserva(this)" data-codigo="'+escHtml(e.codigo||'')+'" data-depid="'+escHtml(e.deposito_id||'')+'">'
      +row.reserva+'</td>'
      +'<td style="text-align:right;font-weight:700;color:'+corDisp+'" title="Saldo físico atual − reservado">'+row.disponivel+'</td>'
      +'<td style="text-align:right;color:#888">'+row.sMin+'</td>'
      +'<td><span style="color:'+row.st.cor+';font-size:11px;font-weight:600">'+row.st.label+'</span></td>'
      +'<td style="font-size:11px;color:#888">'+(row.ultima?(typeof fmtD==='function'?fmtD(row.ultima):row.ultima):'—')+'</td>'
      +'<td><button class="btn btn-sm" onclick="openEntradaEstoque()">+ Entrada</button></td>'
      +'</tr>';
  }).join('');
}

function almRelEsc(v){
  return _escapeHtml(String(v==null?'':v));
}
function almRelEscAttr(v){
  return almRelEsc(v).replace(/"/g,'&quot;');
}
var _almRelFiltros={ini:'',fim:'',status:'',solicitante:'',contrato:'',itens:'',ordem:'data',dir:'desc'};
var _almRelOrigem='req';
function almRelFiltrosPadrao(n){
  var pad=estPeriodoPadrao();
  var f=_almRelFiltros||{};
  var elIni=document.getElementById(n===1?'alm-rel1-ini':'est-fil-ini');
  var elFim=document.getElementById(n===1?'alm-rel1-fim':'est-fil-fim');
  if(!f.ini) f.ini=(elIni&&elIni.value)||pad.ini;
  if(!f.fim) f.fim=(elFim&&elFim.value)||pad.fim;
  _almRelFiltros=f;
  return f;
}
function almRelatorioBarraFiltros(rf, opts){
  opts=opts||{};
  var stOpts='<option value="">Todos os status</option>'+(opts.statuses||[]).map(function(s){
    return '<option value="'+almRelEscAttr(s.v)+'"'+(String(rf.status||'')===String(s.v)?' selected':'')+'>'+almRelEsc(s.l)+'</option>';
  }).join('');
  var solOpts='<option value="">Todos</option>'+(opts.solicitantes||[]).map(function(s){
    return '<option value="'+almRelEscAttr(s)+'"'+(rf.solicitante===s?' selected':'')+'>'+almRelEsc(s)+'</option>';
  }).join('');
  var contOpts='<option value="">Todos</option>'+(opts.contratos||[]).map(function(c){
    return '<option value="'+almRelEscAttr(c)+'"'+(rf.contrato===c || String(rf.contratoNome||'')===c?' selected':'')+'>'+almRelEsc(c)+'</option>';
  }).join('');
  return '<div class="np rel-bar">'
    +'<div class="rel-bar-t">Filtrar e classificar</div>'
    +'<div class="rel-bar-g">'
    +'<label>Data início<input id="rel-f-ini" type="date" value="'+almRelEscAttr(rf.ini||'')+'"></label>'
    +'<label>Data fim<input id="rel-f-fim" type="date" value="'+almRelEscAttr(rf.fim||'')+'"></label>'
    +'<label>Status<select id="rel-f-status">'+stOpts+'</select></label>'
    +'<label>Solicitante<select id="rel-f-sol">'+solOpts+'</select></label>'
    +'<label>Contrato<select id="rel-f-cont">'+contOpts+'</select></label>'
    +'<label>Itens<input id="rel-f-itens" type="text" placeholder="Nome ou código" value="'+almRelEscAttr(rf.itens||'')+'"></label>'
    +'<label>Classificar por<select id="rel-f-ordem">'
    +'<option value="data"'+(rf.ordem==='data'?' selected':'')+'>Data</option>'
    +'<option value="status"'+(rf.ordem==='status'?' selected':'')+'>Status</option>'
    +'<option value="solicitante"'+(rf.ordem==='solicitante'?' selected':'')+'>Solicitante</option>'
    +'<option value="contrato"'+(rf.ordem==='contrato'?' selected':'')+'>Contrato</option>'
    +'<option value="itens"'+(rf.ordem==='itens'?' selected':'')+'>Itens</option>'
    +'</select></label>'
    +'<label>Ordem<select id="rel-f-dir">'
    +'<option value="desc"'+(rf.dir!=='asc'?' selected':'')+'>Decrescente</option>'
    +'<option value="asc"'+(rf.dir==='asc'?' selected':'')+'>Crescente</option>'
    +'</select></label>'
    +'</div></div>';
}
function almRelatorioScriptFiltro(){
  return '(function(){'
    +'function nrm(s){return String(s||"").toLowerCase();}'
    +'function apply(){'
    +'var ini=(document.getElementById("rel-f-ini")||{}).value||"";'
    +'var fim=(document.getElementById("rel-f-fim")||{}).value||"";'
    +'var st=nrm((document.getElementById("rel-f-status")||{}).value);'
    +'var sol=nrm((document.getElementById("rel-f-sol")||{}).value);'
    +'var cont=nrm((document.getElementById("rel-f-cont")||{}).value);'
    +'var it=nrm((document.getElementById("rel-f-itens")||{}).value);'
    +'var ord=(document.getElementById("rel-f-ordem")||{}).value||"data";'
    +'var dir=(document.getElementById("rel-f-dir")||{}).value==="asc"?1:-1;'
    +'var tb=document.getElementById("rel-tbody"); if(!tb) return;'
    +'var rows=[].slice.call(tb.querySelectorAll("tr[data-row]"));'
    +'var vis=0;'
    +'rows.forEach(function(tr){'
    +'var dt=tr.getAttribute("data-data")||"";'
    +'var ok=true;'
    +'if(ini&&dt&&dt<ini) ok=false;'
    +'if(fim&&dt&&dt>fim) ok=false;'
    +'if(st&&nrm(tr.getAttribute("data-status-k")||tr.getAttribute("data-status"))!==st) ok=false;'
    +'if(sol&&nrm(tr.getAttribute("data-solicitante")).indexOf(sol)<0) ok=false;'
    +'if(cont&&nrm(tr.getAttribute("data-contrato")).indexOf(cont)<0) ok=false;'
    +'if(it&&nrm(tr.getAttribute("data-itens")).indexOf(it)<0) ok=false;'
    +'tr.style.display=ok?"":"none";'
    +'if(ok) vis++;'
    +'});'
    +'rows.sort(function(a,b){'
    +'var va=nrm(a.getAttribute("data-"+ord)||"");'
    +'var vb=nrm(b.getAttribute("data-"+ord)||"");'
    +'if(va<vb) return -1*dir; if(va>vb) return 1*dir; return 0;'
    +'});'
    +'var tot=document.getElementById("rel-tot");'
    +'rows.forEach(function(tr){ tb.appendChild(tr); });'
    +'if(tot) tb.appendChild(tot);'
    +'var c=document.getElementById("rel-count"); if(c) c.textContent=vis;'
    +'if(tot){'
    +'var sums=[0,0,0,0,0,0];'
    +'rows.forEach(function(tr){ if(tr.style.display==="none") return; var nums=(tr.getAttribute("data-nums")||"").split(","); for(var i=0;i<6;i++) sums[i]+=Number(nums[i])||0; });'
    +'var tds=tot.querySelectorAll("td.num"); for(var i=0;i<tds.length&&i<6;i++) tds[i].textContent=sums[i];'
    +'}'
    +'}'
    +'["rel-f-ini","rel-f-fim","rel-f-status","rel-f-sol","rel-f-cont","rel-f-itens","rel-f-ordem","rel-f-dir"].forEach(function(id){'
    +'var el=document.getElementById(id); if(!el) return;'
    +'el.addEventListener("change",apply); el.addEventListener("input",apply);'
    +'});'
    +'apply();'
    +'})();';
}
function almRelatorioAbrirJanela(titulo, corpoHtml){
  var html='<!DOCTYPE html><html><head><meta charset="UTF-8"><title>'+almRelEsc(titulo)+'</title>'
    +'<style>'
    +'body{font-family:Arial,sans-serif;max-width:1180px;margin:0 auto;padding:20px;color:#1a1a18}'
    +'table{width:100%;border-collapse:collapse}'
    +'td,th{padding:6px 8px;border-bottom:1px solid #eee;font-size:11px;vertical-align:top}'
    +'th{font-size:10px;text-transform:uppercase;color:#888;background:#f5f5f3;text-align:left;cursor:default}'
    +'td.num,th.num{text-align:right}'
    +'.tot{background:#f0f7ff;font-weight:700}'
    +'.meta{font-size:12px;color:#555;margin-top:4px}'
    +'.rel-bar{background:#f7f7f4;border:1px solid #e8e8e4;border-radius:8px;padding:10px 12px;margin:0 0 16px}'
    +'.rel-bar-t{font-size:11px;font-weight:700;margin-bottom:8px;color:#555}'
    +'.rel-bar-g{display:flex;flex-wrap:wrap;gap:8px;align-items:end}'
    +'.rel-bar label{font-size:10px;color:#666;display:flex;flex-direction:column;gap:3px}'
    +'.rel-bar input,.rel-bar select{font-size:12px;padding:5px 8px;border:1px solid #ddd;border-radius:6px;min-width:120px}'
    +'@media print{.np{display:none}body{padding:0;max-width:none}}'
    +'</style></head><body>'
    +corpoHtml
    +'<div class="np" style="margin-top:20px;text-align:center">'
    +'<button onclick="window.print()" style="background:#1a1a18;color:#fff;border:none;padding:10px 24px;border-radius:8px;font-size:13px;cursor:pointer">🖨 Imprimir / PDF</button>'
    +'</div>'
    +'<script>'+almRelatorioScriptFiltro()+'<\/script>'
    +'</body></html>';
  var w=window.open('','_blank');
  if(!w){
    if(typeof progShowToast==='function') progShowToast('Permita pop-ups para abrir o relatório.','erro');
    return;
  }
  w.document.write(html);
  w.document.close();
}
function almRelatorioPedir(n, origem){
  _almRelOrigem=origem||(n===1?'req':'est');
  function abrir(){ almRelatorioModal(n); }
  if(typeof almReqGarantirListaSilent==='function') Promise.resolve(almReqGarantirListaSilent()).then(abrir);
  else abrir();
}
function almRelatorioModal(n){
  var f=almRelFiltrosPadrao(n);
  var titulo=n===1?'Relatório 1 — Status atual do estoque':'Relatório 2 — Movimentação do estoque';
  var stOpts;
  if(n===2){
    stOpts='<option value="">Todos os status</option>'+almReqStatusOpcoes().map(function(s){
      return '<option value="'+almRelEsc(s)+'"'+(f.status===s?' selected':'')+'>'+almRelEsc(almReqStLabel(s))+'</option>';
    }).join('');
  } else {
    stOpts=[['','Todos os status'],['disponivel','Disponível'],['baixo','Baixo estoque'],['sem-saldo','Sem saldo'],['reservado-total','Reservado total'],['negativo','Saldo negativo'],['sem-mov','Sem movimentação']].map(function(p){
      return '<option value="'+p[0]+'"'+(f.status===p[0]?' selected':'')+'>'+p[1]+'</option>';
    }).join('');
  }
  var sols={};
  (_almReq.lista||[]).forEach(function(r){ if(r.solicitante_nome) sols[r.solicitante_nome]=1; });
  var solKeys=Object.keys(sols).sort(function(a,b){ return a.localeCompare(b,'pt-BR'); });
  var contOpts='<option value="">Todos os contratos</option>'+(contratos||[]).map(function(c){
    return '<option value="'+almRelEsc(String(c.id))+'"'+(String(f.contrato)===String(c.id)?' selected':'')+'>'+almRelEsc(c.nome||c.codigo||'')+'</option>';
  }).join('');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:680px">'
    +'<h3>'+titulo+'</h3>'
    +'<p style="font-size:12px;color:#666;margin:0 0 12px">Filtre e classifique. Na janela do relatório dá para ajustar de novo antes de imprimir.</p>'
    +'<div class="g2">'
    +'<div class="fg"><label>Data início</label><input class="inp" id="alm-rf-ini" type="date" value="'+almRelEsc(f.ini||'')+'"></div>'
    +'<div class="fg"><label>Data fim</label><input class="inp" id="alm-rf-fim" type="date" value="'+almRelEsc(f.fim||'')+'"></div>'
    +'<div class="fg"><label>Status</label><select class="inp" id="alm-rf-status" data-nosort>'+stOpts+'</select></div>'
    +'<div class="fg"><label>Solicitante</label><input class="inp" id="alm-rf-sol" list="alm-rf-sol-dl" placeholder="Nome do solicitante" value="'+almRelEsc(f.solicitante||'')+'">'
    +'<datalist id="alm-rf-sol-dl">'+solKeys.map(function(s){ return '<option value="'+almRelEscAttr(s)+'">'; }).join('')+'</datalist></div>'
    +'<div class="fg"><label>Contrato</label><select class="inp" id="alm-rf-cont" data-nosort>'+contOpts+'</select></div>'
    +'<div class="fg"><label>Itens</label><input class="inp" id="alm-rf-itens" placeholder="Nome ou código do item" value="'+almRelEsc(f.itens||'')+'"></div>'
    +'<div class="fg"><label>Classificar por</label><select class="inp" id="alm-rf-ordem" data-nosort>'
    +'<option value="data"'+(f.ordem==='data'?' selected':'')+'>Data</option>'
    +'<option value="status"'+(f.ordem==='status'?' selected':'')+'>Status</option>'
    +'<option value="solicitante"'+(f.ordem==='solicitante'?' selected':'')+'>Solicitante</option>'
    +'<option value="contrato"'+(f.ordem==='contrato'?' selected':'')+'>Contrato</option>'
    +'<option value="itens"'+(f.ordem==='itens'?' selected':'')+'>Itens</option>'
    +'</select></div>'
    +'<div class="fg"><label>Ordem</label><select class="inp" id="alm-rf-dir" data-nosort>'
    +'<option value="desc"'+(f.dir!=='asc'?' selected':'')+'>Decrescente</option>'
    +'<option value="asc"'+(f.dir==='asc'?' selected':'')+'>Crescente</option>'
    +'</select></div></div>'
    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="almRelatorioGerar('+n+')">Gerar relatório</button></div>'
    +'</div></div>');
}
function almRelatorioLerModal(){
  var contEl=document.getElementById('alm-rf-cont');
  var contId=((contEl||{}).value)||'';
  var contNome='';
  if(contEl && contEl.selectedIndex>=0) contNome=contEl.options[contEl.selectedIndex].text||'';
  if(contNome==='Todos os contratos') contNome='';
  _almRelFiltros={
    ini:((document.getElementById('alm-rf-ini')||{}).value||''),
    fim:((document.getElementById('alm-rf-fim')||{}).value||''),
    status:((document.getElementById('alm-rf-status')||{}).value||''),
    solicitante:((document.getElementById('alm-rf-sol')||{}).value||'').trim(),
    contrato:contId,
    contratoNome:contNome==='Todos os contratos'?'':contNome,
    itens:((document.getElementById('alm-rf-itens')||{}).value||'').trim(),
    ordem:((document.getElementById('alm-rf-ordem')||{}).value)||'data',
    dir:((document.getElementById('alm-rf-dir')||{}).value)||'desc'
  };
  if(_almReq){ _almReq.rel1Ini=_almRelFiltros.ini; _almReq.rel1Fim=_almRelFiltros.fim; }
  return _almRelFiltros;
}
function almRelatorioGerar(n){
  var f=almRelatorioLerModal();
  closeModal();
  if(n===1) almRelatorio1Abrir(f);
  else almRelatorio2Abrir(f);
}
function almRelatorio1FiltrosReq(){
  var pad=estPeriodoPadrao();
  var elIni=document.getElementById('alm-rel1-ini');
  var elFim=document.getElementById('alm-rel1-fim');
  if(elIni && !elIni.value) elIni.value=pad.ini;
  if(elFim && !elFim.value) elFim.value=pad.fim;
  var fReq=(_almReq&&_almReq.filtros)||{};
  return {
    tipo:fReq.tipo||'',
    filial:fReq.base||'',
    deposito:fReq.deposito||'',
    status:'',
    busca:'',
    ini:(elIni&&elIni.value)||pad.ini,
    fim:(elFim&&elFim.value)||pad.fim
  };
}
function almRelatorio1StatusEstoque(origem){
  almRelatorioPedir(1, origem||'req');
}
function almRelItemCasaEstoque(it, row){
  if(!it||!row||!row.e) return false;
  var e=row.e;
  if(it.item_id && e.item_id && String(it.item_id)===String(e.item_id)) return true;
  var ic=String(it.item_codigo||'').toLowerCase();
  var cs=String((row.cs&&row.cs.codigoRaw)||e.codigo||'').toLowerCase();
  if(ic && cs && ic===cs) return true;
  var idesc=String(it.item_descricao||'').toLowerCase();
  var nome=String(e.nome||'').toLowerCase();
  if(idesc && nome && idesc===nome) return true;
  return false;
}
function almRelReqsDoItemEstoque(row, ini, fim){
  var sols=[], conts=[], contIds=[], seenS={}, seenC={};
  (_almReq.lista||[]).forEach(function(r){
    var dt=String(r.data||'').slice(0,10);
    if(ini && dt && dt<ini) return;
    if(fim && dt && dt>fim) return;
    var itens=_almReq.itens[r.id]||[];
    if(!itens.some(function(it){ return almRelItemCasaEstoque(it, row); })) return;
    var s=String(r.solicitante_nome||'').trim();
    var c=String(r.contrato_nome||'').trim();
    if(s && !seenS[s]){ seenS[s]=1; sols.push(s); }
    if(c && !seenC[c]){ seenC[c]=1; conts.push(c); }
    if(r.contrato_id) contIds.push(String(r.contrato_id));
  });
  return {solicitante:sols.join('; '), contrato:conts.join('; '), contratoIds:contIds};
}
function almRelatorioOrdenar(lista, rf, tipo){
  var dir=rf.dir==='asc'?1:-1;
  var k=rf.ordem||'data';
  return (lista||[]).slice().sort(function(a,b){
    var va='', vb='';
    if(tipo==='r1'){
      if(k==='data'){ va=a.ultima||''; vb=b.ultima||''; }
      else if(k==='status'){ va=(a.st&&a.st.label)||''; vb=(b.st&&b.st.label)||''; }
      else if(k==='solicitante'){ va=a._sol||''; vb=b._sol||''; }
      else if(k==='contrato'){ va=a._cont||''; vb=b._cont||''; }
      else { va=(a.e&&a.e.nome)||''; vb=(b.e&&b.e.nome)||''; }
    } else {
      if(k==='data'){ va=String(a.data||'').slice(0,10); vb=String(b.data||'').slice(0,10); }
      else if(k==='status'){ va=almReqStLabel(a.status); vb=almReqStLabel(b.status); }
      else if(k==='solicitante'){ va=a.solicitante_nome||''; vb=b.solicitante_nome||''; }
      else if(k==='contrato'){ va=a.contrato_nome||''; vb=b.contrato_nome||''; }
      else { va=almRelReqItensTexto(a); vb=almRelReqItensTexto(b); }
    }
    va=String(va).toLowerCase(); vb=String(vb).toLowerCase();
    if(va<vb) return -1*dir; if(va>vb) return 1*dir; return 0;
  });
}
function almRelatorioUnicos(lista, getter){
  var seen={}, out=[];
  (lista||[]).forEach(function(x){
    var v=getter(x); if(!v) return;
    String(v).split(';').forEach(function(p){
      p=p.trim(); if(!p||seen[p]) return; seen[p]=1; out.push(p);
    });
  });
  return out.sort(function(a,b){ return a.localeCompare(b,'pt-BR'); });
}
function almRelatorio1Abrir(rf){
  rf=rf||_almRelFiltros||{};
  var base=_almRelOrigem==='est' && typeof estFiltrosAtuais==='function'?estFiltrosAtuais():almRelatorio1FiltrosReq();
  base.ini=rf.ini||base.ini; base.fim=rf.fim||base.fim;
  var stEstoque=['disponivel','baixo','sem-saldo','reservado-total','negativo','sem-mov'];
  if(rf.status && stEstoque.indexOf(rf.status)>=0) base.status=rf.status;
  else base.status='';
  var lista=estColetarLinhas(base);
  var qIt=String(rf.itens||'').toLowerCase();
  var sol=String(rf.solicitante||'').toLowerCase();
  var cid=String(rf.contrato||'');
  lista.forEach(function(row){
    var info=almRelReqsDoItemEstoque(row, rf.ini, rf.fim);
    row._sol=info.solicitante; row._cont=info.contrato; row._contIds=info.contratoIds||[];
  });
  lista=lista.filter(function(row){
    if(qIt){
      var blob=((row.e.nome||'')+' '+((row.cs&&row.cs.codigo)||'')+' '+((row.cs&&row.cs.codigoRaw)||'')).toLowerCase();
      if(blob.indexOf(qIt)<0) return false;
    }
    if(sol && String(row._sol||'').toLowerCase().indexOf(sol)<0) return false;
    if(cid && (row._contIds||[]).indexOf(cid)<0) return false;
    return true;
  });
  lista=almRelatorioOrdenar(lista, rf, 'r1');
  var totAnt=0, totEnt=0, totSai=0, totFis=0, totRes=0, totDisp=0;
  lista.forEach(function(r){
    totAnt+=Number(r.saldoAnt)||0;
    totEnt+=Number(r.entradas)||0;
    totSai+=Number(r.saidas)||0;
    totFis+=Number(r.saldoAtual)||0;
    totRes+=Number(r.reserva)||0;
    totDisp+=Number(r.disponivel)||0;
  });
  var filLabel='Todas as filiais';
  var depLabel='Todos os depósitos';
  if(base.filial && typeof filiais!=='undefined'){
    var fil=(filiais||[]).find(function(x){ return String(x.id)===String(base.filial); });
    if(fil) filLabel=(fil.codigo?fil.codigo+' — ':'')+(fil.nome||'');
  }
  if(base.deposito && typeof depositos!=='undefined'){
    var dep=(depositos||[]).find(function(x){ return String(x.id)===String(base.deposito); });
    if(dep) depLabel=dep.nome||'';
  }
  var stList=[], stSeen={};
  lista.forEach(function(row){
    var k=(row.st&&row.st.k)||''; var l=(row.st&&row.st.label)||k;
    if(k && !stSeen[k]){ stSeen[k]=1; stList.push({v:k,l:l}); }
  });
  var barra=almRelatorioBarraFiltros(rf,{
    statuses:stList,
    solicitantes:almRelatorioUnicos(lista, function(r){ return r._sol; }),
    contratos:almRelatorioUnicos(lista, function(r){ return r._cont; })
  });
  var corpo=barra
    +'<div style="border-bottom:2px solid #1a1a18;padding-bottom:12px;margin-bottom:16px">'
    +'<div style="font-size:10px;color:#888;letter-spacing:2px">CENA — ALMOXARIFADO</div>'
    +'<div style="font-size:20px;font-weight:700;margin-top:4px">Relatório 1 — Status atual do estoque</div>'
    +'<div class="meta">Período: '+almRelEsc(fmtD(base.ini))+' a '+almRelEsc(fmtD(base.fim))
    +' · '+almRelEsc(filLabel)+' · '+almRelEsc(depLabel)
    +' · <span id="rel-count">'+lista.length+'</span> item(ns)</div>'
    +'<div class="meta">Saldo físico atual = saldo anterior + entradas no período − saídas no período. Disponível = físico − reservado.</div>'
    +'</div>'
    +'<table><thead><tr>'
    +'<th>Código</th><th>Itens</th><th>Un.</th><th>Depósito</th><th>Data</th><th>Status</th>'
    +'<th>Solicitante</th><th>Contrato</th>'
    +'<th class="num">Saldo anterior</th><th class="num">Entradas no período</th>'
    +'<th class="num">Saídas no período</th><th class="num">Saldo físico atual</th>'
    +'<th class="num">Reservado</th><th class="num">Disponível</th>'
    +'</tr></thead><tbody id="rel-tbody">'
    +(lista.length?lista.map(function(row){
      var dt=String(row.ultima||'').slice(0,10);
      var itensTxt=(row.e.nome||'')+' '+((row.cs&&row.cs.codigo)||'');
      var nums=[row.saldoAnt,row.entradas,row.saidas,row.saldoAtual,row.reserva,row.disponivel].join(',');
      return '<tr data-row="1" data-data="'+almRelEscAttr(dt)+'" data-status="'+almRelEscAttr((row.st&&row.st.label)||'')+'" data-status-k="'+almRelEscAttr((row.st&&row.st.k)||'')+'" data-solicitante="'+almRelEscAttr(row._sol||'')+'" data-contrato="'+almRelEscAttr(row._cont||'')+'" data-itens="'+almRelEscAttr(itensTxt)+'" data-nums="'+nums+'">'
        +'<td>'+almRelEsc(row.cs.codigo)+'</td>'
        +'<td>'+almRelEsc(row.e.nome||'')+'</td>'
        +'<td>'+almRelEsc(row.un)+'</td>'
        +'<td>'+almRelEsc(row.localLabel)+'</td>'
        +'<td>'+almRelEsc(dt?fmtD(dt):'—')+'</td>'
        +'<td>'+almRelEsc((row.st&&row.st.label)||'—')+'</td>'
        +'<td>'+almRelEsc(row._sol||'—')+'</td>'
        +'<td>'+almRelEsc(row._cont||'—')+'</td>'
        +'<td class="num">'+row.saldoAnt+'</td>'
        +'<td class="num">'+(row.entradas||'—')+'</td>'
        +'<td class="num">'+(row.saidas||'—')+'</td>'
        +'<td class="num">'+row.saldoAtual+'</td>'
        +'<td class="num">'+row.reserva+'</td>'
        +'<td class="num">'+row.disponivel+'</td>'
        +'</tr>';
    }).join(''):'<tr><td colspan="14" style="text-align:center;color:#888;padding:1.5rem">Nenhum item para os filtros.</td></tr>')
    +(lista.length?'<tr class="tot" id="rel-tot"><td colspan="8" style="text-align:right">TOTAIS</td>'
      +'<td class="num">'+totAnt+'</td><td class="num">'+totEnt+'</td><td class="num">'+totSai+'</td>'
      +'<td class="num">'+totFis+'</td><td class="num">'+totRes+'</td><td class="num">'+totDisp+'</td></tr>':'')
    +'</tbody></table>'
    +'<div style="margin-top:16px;font-size:10px;color:#aaa">Gerado em '+(new Date()).toLocaleString('pt-BR')+'</div>';
  almRelatorioAbrirJanela('Relatório 1 — Status do estoque', corpo);
}
function almRelReqItensTexto(r){
  var itens=(_almReq.itens[(r&&r.id)]||[]);
  if(!itens.length) return '—';
  return itens.map(function(it){
    var q=Number(it.quantidade_solicitada)||0;
    return (it.item_descricao||it.item_codigo||'Item')+' × '+q;
  }).join('; ');
}
function almRelReqColabsTexto(r){
  var itens=(_almReq.itens[(r&&r.id)]||[]);
  var nomes=[], seen={};
  itens.forEach(function(it){
    var n=String(it.colaborador_nome||'').trim();
    if(!n||seen[n]) return;
    seen[n]=1;
    nomes.push(n+(it.colaborador_re?' · RE '+it.colaborador_re:''));
  });
  return nomes.length?nomes.join('; '):'—';
}
function almRelatorio2FiltrarPorEstoque(){
  var f=estFiltrosAtuais();
  return (_almReq.lista||[]).filter(function(r){
    var dt=String(r.data||'').slice(0,10);
    if(f.ini && dt && dt<f.ini) return false;
    if(f.fim && dt && dt>f.fim) return false;
    if(f.filial && String(r.base_id||'')!==String(f.filial)) return false;
    if(f.deposito && String(r.deposito_id||'')!==String(f.deposito)) return false;
    return true;
  });
}
function almRelatorio2Coletar(rf){
  var filial='', deposito='';
  if(_almRelOrigem==='est' && typeof estFiltrosAtuais==='function'){
    var ef=estFiltrosAtuais(); filial=ef.filial||''; deposito=ef.deposito||'';
  } else {
    var fr=(_almReq&&_almReq.filtros)||{}; filial=fr.base||''; deposito=fr.deposito||'';
  }
  return (_almReq.lista||[]).filter(function(r){
    var dt=String(r.data||'').slice(0,10);
    if(rf.ini && dt && dt<rf.ini) return false;
    if(rf.fim && dt && dt>rf.fim) return false;
    if(rf.status){
      if(r.status!==rf.status && !(r.status==='atendida' && rf.status==='separada')) return false;
    }
    if(rf.solicitante && String(r.solicitante_nome||'').toLowerCase().indexOf(String(rf.solicitante).toLowerCase())<0) return false;
    if(rf.contrato && String(r.contrato_id||'')!==String(rf.contrato) && String(r.contrato_nome||'')!==String(rf.contratoNome||rf.contrato)) return false;
    if(rf.itens){
      var blob=almRelReqItensTexto(r).toLowerCase();
      if(blob.indexOf(String(rf.itens).toLowerCase())<0) return false;
    }
    if(filial && String(r.base_id||'')!==String(filial)) return false;
    if(deposito && String(r.deposito_id||'')!==String(deposito)) return false;
    return true;
  });
}
function almRelatorio2Movimentacao(origem){
  almRelatorioPedir(2, origem||'est');
}
function almRelatorio2Abrir(rf){
  rf=rf||_almRelFiltros||{};
  var rows=almRelatorioOrdenar(almRelatorio2Coletar(rf), rf, 'r2');
  var stList=[], stSeen={};
  rows.forEach(function(r){
    var k=r.status||''; if(k && !stSeen[k]){ stSeen[k]=1; stList.push({v:k,l:almReqStLabel(k)}); }
  });
  var barra=almRelatorioBarraFiltros(rf,{
    statuses:stList,
    solicitantes:almRelatorioUnicos(rows, function(r){ return r.solicitante_nome; }),
    contratos:almRelatorioUnicos(rows, function(r){ return r.contrato_nome; })
  });
  var corpo=barra
    +'<div style="border-bottom:2px solid #1a1a18;padding-bottom:12px;margin-bottom:16px">'
    +'<div style="font-size:10px;color:#888;letter-spacing:2px">CENA — ALMOXARIFADO</div>'
    +'<div style="font-size:20px;font-weight:700;margin-top:4px">Relatório 2 — Movimentação do estoque</div>'
    +'<div class="meta">'+almRelEsc(fmtD(rf.ini))+' a '+almRelEsc(fmtD(rf.fim))
    +' · <span id="rel-count">'+rows.length+'</span> requisição(ões)</div>'
    +'</div>'
    +'<table><thead><tr>'
    +'<th>Número requisição</th><th>Data</th><th>Solicitante</th><th>Contrato</th>'
    +'<th>Depósito</th><th>Itens</th><th>Colaborador</th><th>Status</th>'
    +'</tr></thead><tbody id="rel-tbody">'
    +(rows.length?rows.map(function(r){
      var dt=String(r.data||'').slice(0,10);
      var itens=almRelReqItensTexto(r);
      var stLab=almReqStLabel(r.status);
      return '<tr data-row="1" data-data="'+almRelEscAttr(dt)+'" data-status="'+almRelEscAttr(stLab)+'" data-status-k="'+almRelEscAttr(r.status||'')+'" data-solicitante="'+almRelEscAttr(r.solicitante_nome||'')+'" data-contrato="'+almRelEscAttr(r.contrato_nome||'')+'" data-itens="'+almRelEscAttr(itens)+'">'
        +'<td>'+almRelEsc(r.numero||'—')+'</td>'
        +'<td>'+almRelEsc(fmtD(r.data))+'</td>'
        +'<td>'+almRelEsc(r.solicitante_nome||'—')+'</td>'
        +'<td>'+almRelEsc(r.contrato_nome||'—')+'</td>'
        +'<td>'+almRelEsc(r.deposito_nome||'—')+'</td>'
        +'<td>'+almRelEsc(itens)+'</td>'
        +'<td>'+almRelEsc(almRelReqColabsTexto(r))+'</td>'
        +'<td>'+almRelEsc(stLab)+'</td>'
        +'</tr>';
    }).join(''):'<tr><td colspan="8" style="text-align:center;color:#888;padding:1.5rem">Nenhuma requisição no período/filtros.</td></tr>')
    +'</tbody></table>'
    +'<div style="margin-top:16px;font-size:10px;color:#aaa">Gerado em '+(new Date()).toLocaleString('pt-BR')+'</div>';
  almRelatorioAbrirJanela('Relatório 2 — Movimentação do estoque', corpo);
}

function estLedgerSaldoFisico(ref, depId){
  var r=estResumoPeriodoEstoque(ref, depId||'', '', '', '');
  return Number(r.saldoAtual)||0;
}
function estMovsDoItemDep(ref, depId){
  return (movimentacoes_itens||[]).filter(function(m){
    if(!m||m.deleted_at) return false;
    return estMovEhDoItemDep(m, ref, depId);
  });
}
function estSugestaoDivergencia(tipo){
  var m={
    'saldo_tabela_vs_ledger':'Conferir ledger e, se aprovado pelo gestor, ajuste de inventário controlado — nunca sync silencioso.',
    'retroagida_com_baixa':'Não retroagir de novo. Estorno de estoque é fluxo separado; use Corrigir informações para dados administrativos.',
    'atendida_zerada_com_saida':'Quantidade atendida foi zerada após baixa. Recompor quantidade_atendida ou estornar a movimentação em fluxo próprio.',
    'atendida_sem_saida':'Há atendimento sem movimentação de saída. Gerar movimentação de correção vinculada à requisição, se aprovado.',
    'reserva_de_item_atendido':'Item já atendido ainda aparece como reservado. Recalcular reserva (aprovada − atendida) sem mexer no físico.',
    'saida_duplicada':'Duas saídas com o mesmo item/requisição. Manter uma e estornar a duplicata com aprovação.',
    'reserva_duplicada':'Mais de uma reserva aberta para o mesmo item na mesma req. Conferir linhas duplicadas.',
    'devolucao_sem_saida':'Devolução sem saída original vinculada. Conferir o motivo e o depósito.',
    'reserva_removida_indevida':'Havia aprovação aberta e a reserva sumiu sem atendimento. Reabrir reserva ou confirmar cancelamento.'
  };
  return m[tipo]||'Listar para conferência. Nenhuma correção automática.';
}
async function estAuditarDivergenciasCena(){
  var wrap=document.getElementById('est-audit-wrap');
  if(wrap) wrap.innerHTML='<div class="card" style="padding:1.2rem;color:#888">⏳ Auditando divergências (somente leitura)...</div>';
  if(typeof almReqGarantirListaSilent==='function') await Promise.resolve(almReqGarantirListaSilent());
  var evRetro=[];
  if(!DEMO){
    try{
      evRetro=await sbFetch('alm_requisicao_eventos',{filters:['evento=in.(retroagida,retroagida_bloqueada)'],limit:5000})||[];
    }catch(e){ evRetro=[]; }
  } else {
    Object.keys(_almReq.eventos||{}).forEach(function(id){
      (_almReq.eventos[id]||[]).forEach(function(ev){ if(ev.evento==='retroagida'||ev.evento==='retroagida_bloqueada') evRetro.push(ev); });
    });
  }
  var retroPorReq={};
  evRetro.forEach(function(ev){
    var id=String(ev.requisicao_id||'');
    if(!retroPorReq[id]) retroPorReq[id]=[];
    retroPorReq[id].push(ev);
  });
  var rows=[];
  function addRow(o){
    rows.push(Object.assign({
      codigo:'', descricao:'', deposito:'', deposito_id:'',
      saldo_estoque:'', saldo_ledger:'', diferenca:'',
      reserva:'', disponivel:'',
      requisicao:'', item_req:'', qtd_aprovada:'', qtd_atendida:'',
      eventos_retro:'', movimentacoes:'', tipo:'', sugestao:''
    }, o));
  }
  (estoque||[]).forEach(function(e){
    var ref=estRefTimeline(e);
    var dep=(depositos||[]).find(function(d){ return String(d.id)===String(e.deposito_id||''); });
    var ledger=estLedgerSaldoFisico(ref, e.deposito_id||'');
    var sist=Number(e.saldo)||0;
    var dif=sist-ledger;
    var reserva=almReqReservaEstoque(e.item_id, e.codigo, e.deposito_id, e.nome);
    var disp=ledger-reserva;
    var movs=estMovsDoItemDep(ref, e.deposito_id||'');
    var saidas=movs.filter(function(m){ return almReqMovEhSaidaReal(m); });
    var chaves={};
    saidas.forEach(function(m){
      var k=String(m.item_id||'')+'|'+(m.motivo||'')+'|'+(m.quantidade||'')+'|'+(m.data_mov||'').slice(0,10);
      chaves[k]=(chaves[k]||0)+1;
    });
    Object.keys(chaves).forEach(function(k){
      if(chaves[k]<2) return;
      addRow({
        codigo:e.codigo||'', descricao:e.nome||'', deposito:dep?dep.nome:'', deposito_id:e.deposito_id||'',
        saldo_estoque:sist, saldo_ledger:ledger, diferenca:dif, reserva:reserva, disponivel:disp,
        movimentacoes:chaves[k]+' saídas iguais', tipo:'saida_duplicada', sugestao:estSugestaoDivergencia('saida_duplicada')
      });
    });
    var devs=movs.filter(function(m){ return String(m.tipo_mov||'')==='devolucao'; });
    if(devs.length && !saidas.length){
      addRow({
        codigo:e.codigo||'', descricao:e.nome||'', deposito:dep?dep.nome:'', deposito_id:e.deposito_id||'',
        saldo_estoque:sist, saldo_ledger:ledger, diferenca:dif, reserva:reserva, disponivel:disp,
        movimentacoes:devs.length+' devolução(ões)', tipo:'devolucao_sem_saida', sugestao:estSugestaoDivergencia('devolucao_sem_saida')
      });
    }
    if(Math.abs(dif)>0.0001){
      addRow({
        codigo:e.codigo||'', descricao:e.nome||'', deposito:dep?dep.nome:'', deposito_id:e.deposito_id||'',
        saldo_estoque:sist, saldo_ledger:ledger, diferenca:dif, reserva:reserva, disponivel:disp,
        movimentacoes:movs.length+' mov.', tipo:'saldo_tabela_vs_ledger', sugestao:estSugestaoDivergencia('saldo_tabela_vs_ledger')
      });
    }
  });
  (_almReq.lista||[]).forEach(function(r){
    var itens=_almReq.itens[r.id]||[];
    var movs=almReqMovsDaReq(r);
    var saidas=movs.filter(almReqMovEhSaidaReal);
    var evs=retroPorReq[String(r.id)]||[];
    var evTxt=evs.map(function(ev){ return (ev.evento||'')+' '+(ev.descricao||''); }).join(' | ');
    var temBaixaHist=almReqTemBaixaReal(Object.assign({}, r, {itens:itens})).temBaixa || saidas.length>0;
    if(evs.length && temBaixaHist){
      addRow({
        codigo:'', descricao:'', deposito:r.deposito_nome||'',
        requisicao:r.numero||r.id, eventos_retro:evTxt,
        movimentacoes:saidas.length+' saída(s)', tipo:'retroagida_com_baixa',
        sugestao:estSugestaoDivergencia('retroagida_com_baixa')
      });
    }
    itens.forEach(function(it){
      var atd=Number(it.quantidade_atendida)||0;
      var apr=Number(it.quantidade_aprovada!=null?it.quantidade_aprovada:it.quantidade_solicitada)||0;
      var movItem=movs.filter(function(m){ return String(m.item_id||'')===String(it.item_id||'') || String(m.motivo||'').indexOf(it.item_descricao||'')>=0; });
      var saiItem=movItem.filter(almReqMovEhSaidaReal);
      var qtdSai=saiItem.reduce(function(s,m){ return s+(Number(m.quantidade)||0); },0);
      if(atd<=0 && qtdSai>0){
        addRow({
          codigo:it.item_codigo||'', descricao:it.item_descricao||'', deposito:r.deposito_nome||'',
          requisicao:r.numero||'', item_req:it.item_descricao||'', qtd_aprovada:apr, qtd_atendida:atd,
          eventos_retro:evTxt, movimentacoes:qtdSai+' un. saída', tipo:'atendida_zerada_com_saida',
          sugestao:estSugestaoDivergencia('atendida_zerada_com_saida')
        });
      }
      if(atd>0 && qtdSai<=0){
        addRow({
          codigo:it.item_codigo||'', descricao:it.item_descricao||'', deposito:r.deposito_nome||'',
          requisicao:r.numero||'', item_req:it.item_descricao||'', qtd_aprovada:apr, qtd_atendida:atd,
          eventos_retro:evTxt, movimentacoes:'sem saída', tipo:'atendida_sem_saida',
          sugestao:estSugestaoDivergencia('atendida_sem_saida')
        });
      }
      var res=almReqItemQtdReservada(it);
      if(almReqItemTotalmenteAtendido(it) && res>0){
        addRow({
          codigo:it.item_codigo||'', descricao:it.item_descricao||'', deposito:r.deposito_nome||'',
          requisicao:r.numero||'', item_req:it.item_descricao||'', qtd_aprovada:apr, qtd_atendida:atd,
          reserva:res, tipo:'reserva_de_item_atendido', sugestao:estSugestaoDivergencia('reserva_de_item_atendido')
        });
      }
    });
  });
  window._estAuditRows=rows;
  estRenderAuditoriaCena(rows);
  if(typeof progShowToast==='function') progShowToast(rows.length?('Auditoria: '+rows.length+' divergência(s). Nada foi corrigido.'):'Auditoria: nenhuma divergência listada.');
}
function estRenderAuditoriaCena(rows){
  var wrap=document.getElementById('est-audit-wrap'); if(!wrap) return;
  if(!rows.length){
    wrap.innerHTML='<div class="card" style="padding:1rem;color:#3B6D11">✅ Nenhuma divergência listada. Nada foi alterado no saldo.</div>';
    return;
  }
  wrap.innerHTML='<div class="card" style="border-left:4px solid #854F0B">'
    +'<div class="ch"><span class="ct">🔍 Divergências de estoque ('+rows.length+')</span>'
    +'<span style="font-size:11px;color:#888">Somente leitura — nenhuma correção automática</span>'
    +'<button class="btn btn-sm" onclick="estExportarAuditoriaCena()">⬇ CSV</button></div>'
    +'<div style="padding:8px 12px;font-size:11px;color:#854F0B">Depois da conferência: ajuste de inventário, movimentação vinculada à requisição, reprocessar ledger ou correção manual com aprovação do gestor.</div>'
    +'<div style="overflow-x:auto"><table class="tbl tbl-r" style="font-size:11px"><thead><tr>'
    +'<th>Código</th><th>Descrição</th><th>Depósito</th>'
    +'<th style="text-align:right">Saldo estoque</th><th style="text-align:right">Saldo ledger</th><th style="text-align:right">Diferença</th>'
    +'<th style="text-align:right">Reservado</th><th style="text-align:right">Disponível</th>'
    +'<th>Requisição</th><th>Item req.</th><th style="text-align:right">Aprov.</th><th style="text-align:right">Atend.</th>'
    +'<th>Eventos retroação</th><th>Movimentações</th><th>Tipo</th><th>Sugestão</th>'
    +'</tr></thead><tbody>'
    +rows.map(function(r){
      return '<tr>'
        +'<td>'+escHtml(r.codigo||'—')+'</td><td>'+escHtml(r.descricao||'—')+'</td><td>'+escHtml(r.deposito||'—')+'</td>'
        +'<td style="text-align:right">'+(r.saldo_estoque===''?'—':r.saldo_estoque)+'</td>'
        +'<td style="text-align:right">'+(r.saldo_ledger===''?'—':r.saldo_ledger)+'</td>'
        +'<td style="text-align:right;font-weight:700;color:'+(Number(r.diferenca)?'#A32D2D':'#888')+'">'+(r.diferenca===''?'—':r.diferenca)+'</td>'
        +'<td style="text-align:right">'+(r.reserva===''?'—':r.reserva)+'</td>'
        +'<td style="text-align:right">'+(r.disponivel===''?'—':r.disponivel)+'</td>'
        +'<td>'+escHtml(r.requisicao||'—')+'</td><td>'+escHtml(r.item_req||'—')+'</td>'
        +'<td style="text-align:right">'+(r.qtd_aprovada===''?'—':r.qtd_aprovada)+'</td>'
        +'<td style="text-align:right">'+(r.qtd_atendida===''?'—':r.qtd_atendida)+'</td>'
        +'<td style="font-size:10px">'+escHtml(r.eventos_retro||'—')+'</td>'
        +'<td style="font-size:10px">'+escHtml(r.movimentacoes||'—')+'</td>'
        +'<td>'+escHtml(r.tipo||'')+'</td><td style="font-size:10px;max-width:260px">'+escHtml(r.sugestao||'')+'</td>'
        +'</tr>';
    }).join('')+'</tbody></table></div></div>';
}
function estExportarAuditoriaCena(){
  var rows=window._estAuditRows||[];
  if(!rows.length){ progShowToast('Nada para exportar.'); return; }
  var head=['codigo','descricao','deposito','saldo_estoque','saldo_ledger','diferenca','reserva','disponivel','requisicao','item_req','qtd_aprovada','qtd_atendida','eventos_retro','movimentacoes','tipo','sugestao'];
  function c(v){ return '"'+String(v==null?'':v).replace(/"/g,'""')+'"'; }
  var csv=[head.join(';')].concat(rows.map(function(r){ return head.map(function(k){ return c(r[k]); }).join(';'); })).join('\n');
  var blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});
  var a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='auditoria-estoque-cena.csv'; a.click();
}

// ── FICHA DE EPI ─────────────────────────────────────────────────────────────
function iniciarFichaEpi(){
  var selCont = document.getElementById('fepi-fil-contrato');
  if(selCont && selCont.options.length<=1 && typeof contratos!=='undefined'){
    selCont.innerHTML = '<option value="">Selecione o contrato...</option>'
      + contratos.map(function(c){ return '<option value="'+c.id+'">'+c.nome+'</option>'; }).join('');
  }
  renderFichaEpi();
}

function fepiAtualizarColabs(){
  var cid = (document.getElementById('fepi-fil-contrato')||{}).value||'';
  var sel = document.getElementById('fepi-fil-colab'); if(!sel) return;
  var cols = (typeof colaboradores!=='undefined')
    ? colaboradores.filter(function(c){ return c.ativo!==false&&(!cid||c.contrato_id===cid); }) : [];
  sel.innerHTML = '<option value="">Selecione o colaborador...</option>'
    + cols.map(function(c){ return '<option value="'+c.id+'">'+c.nome+(c.re?' (RE '+c.re+')':'')+'</option>'; }).join('');
  renderFichaEpi();
}

function renderFichaEpi(){
  var cont = document.getElementById('fepi-conteudo'); if(!cont) return;
  var fid  = (document.getElementById('fepi-fil-colab')||{}).value||'';
  var filtItem = ((document.getElementById('fepi-fil-item')||{}).value||'').toLowerCase();
  var btnImpr = document.getElementById('fepi-btn-imprimir');

  if(!fid){
    cont.innerHTML='<div style="padding:3rem;text-align:center;color:#aaa">Selecione um contrato e colaborador para visualizar a ficha de EPI.</div>';
    if(btnImpr) btnImpr.style.display='none'; return;
  }

  var colab = (typeof colaboradores!=='undefined')?colaboradores.find(function(x){return x.id===fid;}):null;
  if(!colab){ cont.innerHTML='<div style="padding:2rem;text-align:center;color:#aaa">Colaborador não encontrado.</div>'; return; }

  var contrato = (typeof contratos!=='undefined'&&colab.contrato_id)?contratos.find(function(x){return x.id===colab.contrato_id;})||null:null;
  var myEpis   = (typeof epis!=='undefined')?epis.filter(function(e){return e.responsavel_id===fid;}):[];
  var hoje     = dataHoje();
  if(btnImpr) btnImpr.style.display='';

  var epiFiltrados = (filtItem?myEpis.filter(function(e){return (e.nome||'').toLowerCase().includes(filtItem);}):myEpis).filter(function(e){ return !epiAguardandoAssinatura(e); });
  var ativos = epiFiltrados.filter(epiEmPoderFicha);
  var pendAssin = myEpis.filter(function(e){
    if(!epiAguardandoAssinatura(e)) return false;
    if(filtItem && !(e.nome||'').toLowerCase().includes(filtItem)) return false;
    return true;
  });

  // Cabeçalho
  var html = '<div class="card" style="margin-bottom:.75rem"><div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem 1.5rem;padding:.75rem 1rem;font-size:12px">'
    +'<div><span style="color:#888">Colaborador:</span> <strong>'+colab.nome+'</strong></div>'
    +'<div><span style="color:#888">RE/Matrícula:</span> '+(colab.re||colab.matricula||'—')+'</div>'
    +'<div><span style="color:#888">Contrato:</span> '+(contrato?escHtml(almContratoLabel(contrato,false)):'<span style="color:#A32D2D">Sem contrato</span>')+'</div>'
    +'<div><span style="color:#888">Cargo:</span> '+(colab.cargo||colab.funcao||'—')+'</div>'
    +'</div></div>';

  // Alertas
  var venc  = ativos.filter(function(e){return e.validade&&e.validade<hoje;});
  var semAs = ativos.filter(function(e){return !e.assinatura_url;});
  var caVen = ativos.filter(function(e){return e.ca_validade&&e.ca_validade<hoje;});
  if(venc.length||semAs.length||caVen.length){
    html+='<div style="background:#FEE8E8;border:.5px solid #A32D2D;border-radius:8px;padding:.5rem 1rem;margin-bottom:.6rem;font-size:12px;color:#A32D2D">'
      +'⚠'+( venc.length?' '+venc.length+' EPI(s) vencido(s)':'')+(caVen.length?' · '+caVen.length+' CA(s) vencido(s)':'')+(semAs.length?' · '+semAs.length+' sem assinatura':'')+'</div>';
  }

  // EPIs em poder atual
  html+='<div class="card" style="margin-bottom:.75rem"><div class="ch" style="background:#EBF4FD">'
    +'<span class="ct" style="color:#185FA5">🦺 EPIs em poder do colaborador ('+ativos.length+')</span>'
    +'<div style="display:flex;gap:6px"><button class="btn btn-sm" onclick="openEpiKits()" title="Kits modelo de EPI">📦 Kits modelo</button>'
    +(ativos.length?'<button class="btn btn-sm" style="color:#854F0B;border-color:#854F0B" onclick="openDevolucaoEpi(\''+fid+'\')">📤 Devolver</button>':'')
    +'<button class="btn btn-sm btn-pri" onclick="openNovaEntregaEpi(\''+fid+'\')">+ Entregar EPI</button></div></div>';
  if(ativos.length){
    html+='<div style="overflow-x:auto"><table class="tbl tbl-r"><thead><tr>'
      +'<th>EPI/EPC</th><th>Qtd</th><th>CA</th><th>Val. CA</th><th>Entrega</th><th>Troca prev.</th><th>Motivo</th><th>Assinatura</th><th>Status</th><th></th>'
      +'</tr></thead><tbody>'
      +ativos.map(function(e){
        var sCA=e.ca_validade?(e.ca_validade<hoje?'<span style="color:#A32D2D">'+fmtD(e.ca_validade)+' ⚠</span>':fmtD(e.ca_validade)):'—';
        var sT =e.data_prevista_substituicao?(e.data_prevista_substituicao<hoje?'<span style="color:#A32D2D">'+fmtD(e.data_prevista_substituicao)+' ⚠</span>':fmtD(e.data_prevista_substituicao)):'—';
        return '<tr><td><strong>'+e.nome+'</strong></td><td style="text-align:center">'+(e.quantidade||1)+'</td>'
          +'<td style="font-size:11px">'+(e.ca||'—')+'</td><td style="font-size:11px">'+sCA+'</td>'
          +'<td style="font-size:11px">'+fmtD(e.data_entrega)+'</td><td style="font-size:11px">'+sT+'</td>'
          +'<td style="font-size:10px;color:#888">'+(e.motivo_entrega||'—')+'</td>'
          +'<td style="text-align:center">'+(e.assinatura_url?'<span style="color:#3B6D11">✓</span> <a onclick="verAssinaturaEpi(\''+e.id+'\')" style="cursor:pointer;color:#185FA5;font-size:10px">ver</a>':'<button class="btn btn-sm" style="font-size:10px;padding:1px 6px;color:#854F0B;border-color:#854F0B" onclick="assinarEntregaFicha(\''+fid+'\',\''+(e.data_entrega||'')+'\')">✍ Assinar</button>')+'</td>'
          +'<td><span class="bdg '+(e.status==='Ativo'?'ok':'warn')+'" style="font-size:10px">'+(e.status||'Ativo')+'</span></td>'
          +'<td><button class="btn btn-sm" style="font-size:10px;padding:1px 6px;color:#854F0B;border-color:#854F0B" onclick="openDevolucaoEpi(\''+fid+'\',\''+e.id+'\')">📤</button></td></tr>';
      }).join('')+'</tbody></table></div>';
  } else {
    html+='<div style="padding:1rem;text-align:center;color:#aaa;font-size:12px">Nenhum EPI em poder deste colaborador.</div>';
  }
  html+='</div>';

  if(pendAssin.length){
    html+='<div class="card" style="margin-bottom:.75rem"><div class="ch" style="background:#FFF7E6">'
      +'<span class="ct" style="color:#854F0B">✍ Aguardando assinatura ('+pendAssin.length+')</span>'
      +'<button class="btn btn-sm" style="color:#854F0B;border-color:#854F0B" onclick="assinarEntregaFicha(\''+fid+'\',\''+(pendAssin[0].data_entrega||'')+'\')">Assinar</button></div>'
      +'<div style="padding:.45rem .75rem 0;font-size:11px;color:#854F0B">Ainda não entram em poder do colaborador.</div>'
      +'<div style="display:flex;flex-wrap:wrap;gap:4px;padding:.45rem .75rem .7rem">'
      +pendAssin.map(function(e){
        return '<span style="background:#fff;border:.5px solid #f0d088;border-radius:5px;padding:2px 8px;font-size:12px">'
          +escHtml(e.nome||'—')+' ('+(e.quantidade||1)+')</span>';
      }).join('')+'</div></div>';
  }

  // Histórico
  if(filtItem){
    html+='<div class="card"><div class="ch" style="background:#f9f9f7"><span class="ct" style="color:#555">📅 Histórico de "'+filtItem+'" ('+epiFiltrados.length+')</span></div>';
    if(epiFiltrados.length){
      html+='<div style="overflow-x:auto"><table class="tbl tbl-r"><thead><tr>'
        +'<th>EPI</th><th>Qtd</th><th>CA</th><th>Data entrega</th><th>Motivo</th><th>Status</th>'
        +'</tr></thead><tbody>'
        +epiFiltrados.map(function(e){
          return '<tr><td>'+e.nome+'</td><td style="text-align:center">'+(e.quantidade||1)+'</td>'
            +'<td style="font-size:11px">'+(e.ca||'—')+'</td><td>'+fmtD(e.data_entrega)+'</td>'
            +'<td style="font-size:11px;color:#888">'+(e.motivo_entrega||'—')+'</td>'
            +'<td><span class="bdg '+(e.status==='Ativo'?'ok':e.status==='Devolvido'?'gray':'warn')+'" style="font-size:10px">'+(e.status||'Ativo')+'</span></td></tr>';
        }).join('')+'</tbody></table></div>';
    } else {
      html+='<div style="padding:1rem;text-align:center;color:#aaa;font-size:12px">Nenhum registro encontrado.</div>';
    }
    html+='</div>';
  } else if(epiFiltrados.length){
    var datas = epiFiltrados.filter(function(e){return e.data_entrega;}).map(function(e){return e.data_entrega;}).sort().reverse();
    var uniq  = datas.filter(function(v,i,a){return a.indexOf(v)===i;});
    html+='<div class="card"><div class="ch" style="background:#f9f9f7">'
      +'<span class="ct" style="color:#555">📅 Histórico de entregas</span>'
      +'<span style="font-size:11px;color:#888">'+epiFiltrados.length+' entrega(s) total · busque um item acima para detalhes</span></div>'
      +'<div style="padding:.75rem 1rem;display:flex;flex-wrap:wrap;gap:8px">'
      +uniq.map(function(d){
        var q=epiFiltrados.filter(function(e){return e.data_entrega===d;}).length;
        return '<div style="background:#EBF4FD;border-radius:8px;padding:.35rem .7rem;font-size:12px">'
          +'<span style="color:#185FA5;font-weight:600">'+fmtD(d)+'</span>'
          +' <span style="color:#888">'+q+' item(ns)</span></div>';
      }).join('')+'</div></div>';
  }

  cont.innerHTML = html;
}
var _trUi = { page:1, pageSize:50, montado:false, _filKey:'' };
function trOnFiltroChange(){ _trUi.page = 1; renderTreinamentos(); }
function trSetPageSize(n){
  _trUi.pageSize = parseInt(n,10)||50;
  _trUi.page = 1;
  renderTreinamentos();
}
function trGotoPage(n){
  _trUi.page = Math.max(1, parseInt(n,10)||1);
  renderTreinamentos();
}
function renderTreinamentos(){
  var tbody=document.getElementById('tbody-trein'); if(!tbody) return;
  cenaPerfStart('sesmt-treinamentos-render');
  var card=tbody.closest?tbody.closest('.card'):null;
  // Barra de filtros (injetada uma vez)
  if(card && !document.getElementById('tr-filtros')){
    var bar=document.createElement('div');
    bar.id='tr-filtros';
    bar.style.cssText='display:flex;gap:8px;flex-wrap:wrap;align-items:center;padding:.6rem .75rem;border-bottom:.5px solid #f0efe8';
    bar.innerHTML='<select class="inp" id="tr-fil-colab" style="width:240px;font-size:12px" onchange="trOnFiltroChange()"><option value="">Todos os colaboradores</option></select>'
      +'<select class="inp" id="tr-fil-nr" style="width:230px;font-size:12px" onchange="trOnFiltroChange()"><option value="">Todos os treinamentos</option></select>'
      +'<select class="inp" id="tr-fil-status" style="width:150px;font-size:12px" onchange="trOnFiltroChange()"><option value="">Todos os status</option><option value="ok">Válido</option><option value="prox">A vencer</option><option value="venc">Vencido</option></select>'
      +'<select class="inp" id="tr-fil-situacao" style="width:170px;font-size:12px" onchange="trOnFiltroChange()" title="Quem aparece na lista">'
      +'<option value="ativos">Só ativos</option>'
      +'<option value="todos">Incluir demitidos</option>'
      +'<option value="orfaos">Só sem cadastro (—)</option>'
      +'</select>'
      +'<select class="inp" id="tr-fil-pagesize" style="width:110px;font-size:12px" onchange="trSetPageSize(this.value)" title="Registros por página">'
      +'<option value="25">25 / pág</option><option value="50" selected>50 / pág</option><option value="100">100 / pág</option>'
      +'</select>'
      +'<span id="tr-fil-cont" style="font-size:11px;color:#888"></span>'
      +'<button class="btn btn-sm" id="tr-btn-import" style="margin-left:auto" onclick="trAbrirImportacao()">⬆ Importar planilha</button>';
    var ch=card.querySelector('.ch');
    if(ch) card.insertBefore(bar, ch.nextSibling); else card.insertBefore(bar, card.firstChild);
  } else if(document.getElementById('tr-filtros') && !document.getElementById('tr-fil-pagesize')){
    var barOld=document.getElementById('tr-filtros');
    var selPs=document.createElement('select');
    selPs.className='inp'; selPs.id='tr-fil-pagesize';
    selPs.style.cssText='width:110px;font-size:12px';
    selPs.title='Registros por página';
    selPs.onchange=function(){ trSetPageSize(this.value); };
    selPs.innerHTML='<option value="25">25 / pág</option><option value="50" selected>50 / pág</option><option value="100">100 / pág</option>';
    var contSp0=document.getElementById('tr-fil-cont');
    if(contSp0) barOld.insertBefore(selPs, contSp0); else barOld.appendChild(selPs);
    ['tr-fil-colab','tr-fil-nr','tr-fil-status','tr-fil-situacao'].forEach(function(id){
      var el=document.getElementById(id); if(el) el.setAttribute('onchange','trOnFiltroChange()');
    });
  }
  if(document.getElementById('tr-filtros') && !document.getElementById('tr-fil-situacao')){
    var barOld2=document.getElementById('tr-filtros');
    var selSit=document.createElement('select');
    selSit.className='inp'; selSit.id='tr-fil-situacao';
    selSit.style.cssText='width:170px;font-size:12px';
    selSit.title='Quem aparece na lista';
    selSit.onchange=trOnFiltroChange;
    selSit.innerHTML='<option value="ativos">Só ativos</option><option value="todos">Incluir demitidos</option><option value="orfaos">Só sem cadastro (—)</option>';
    var contSp=document.getElementById('tr-fil-cont');
    if(contSp) barOld2.insertBefore(selSit, contSp); else barOld2.appendChild(selSit);
  }
  var selColab=document.getElementById('tr-fil-colab');
  if(selColab){
    var ativos=(colaboradores||[]).filter(function(c){ return c.ativo!==false && !c.dispensado; })
      .sort(function(a,b){ return (a.nome||'').localeCompare(b.nome||'','pt-BR'); });
    if(selColab.options.length-1 !== ativos.length){
      var curC=selColab.value;
      selColab.innerHTML='<option value="">Todos os colaboradores ('+ativos.length+')</option>'
        +ativos.map(function(c){ return '<option value="'+c.id+'">'+escHtml(c.nome||('RE '+(c.re||'')))+'</option>'; }).join('');
      selColab.value=curC;
    }
  }
  var selNr=document.getElementById('tr-fil-nr');
  if(selNr){
    var opcoes=[];
    if(typeof _cad_cursos!=='undefined' && _cad_cursos.length){
      opcoes=_cad_cursos.filter(function(c){ return c.sigla; })
        .map(function(c){ return {v:c.sigla, l:(c.sigla+' — '+(c.nome||'')) }; });
    } else {
      var chaves={}; treinamentos.forEach(function(t){ if(t.nr) chaves[t.nr]=(t.nr+' — '+(t.titulo||'')); });
      opcoes=Object.keys(chaves).map(function(k){ return {v:k, l:chaves[k]}; });
    }
    opcoes.sort(function(a,b){ return a.l.localeCompare(b.l,'pt-BR'); });
    if(selNr.options.length-1 !== opcoes.length){
      var cur=selNr.value;
      selNr.innerHTML='<option value="">Todos os treinamentos</option>'
        +opcoes.map(function(o){ return '<option value="'+escHtml(o.v)+'">'+escHtml(o.l)+'</option>'; }).join('');
      selNr.value=cur;
    }
  }
  var fColab=(document.getElementById('tr-fil-colab')||{}).value||'';
  var fNr=(document.getElementById('tr-fil-nr')||{}).value||'';
  var fSt=(document.getElementById('tr-fil-status')||{}).value||'';
  var fSit=(document.getElementById('tr-fil-situacao')||{}).value||'ativos';
  var psEl=document.getElementById('tr-fil-pagesize');
  if(psEl){ var psv=parseInt(psEl.value,10); if(psv===25||psv===50||psv===100) _trUi.pageSize=psv; }

  var filKey=fColab+'|'+fNr+'|'+fSt+'|'+fSit+'|'+_trUi.pageSize;
  if(_trUi._filKey && _trUi._filKey!==filKey) _trUi.page=1;
  _trUi._filKey=filKey;

  var linhas=treinamentos.filter(function(t){
    if(t.deleted_at) return false;
    var col=typeof trResolverColabDeFid==='function'?trResolverColabDeFid(t.funcionario_id):null;
    var ehOrfao=!col;
    var ehInativo=col && (col.dispensado===true || col.ativo===false);
    if(fSit==='ativos'){
      if(ehOrfao || ehInativo) return false;
    } else if(fSit==='orfaos'){
      if(!ehOrfao) return false;
    }
    if(fColab && String(t.funcionario_id)!==String(fColab)){
      var cid=typeof sesmtTreinamentoColabId==='function'?sesmtTreinamentoColabId(t.funcionario_id):null;
      if(String(cid||'')!==String(fColab) && String((col&&col.id)||'')!==String(fColab)) return false;
    }
    if(fNr && trNormSigla(t.nr)!==trNormSigla(fNr)) return false;
    if(fSt){ var s=stV(t.val||t.validade); if(!s || s.cls!==fSt) return false; }
    return true;
  });

  linhas=linhas.slice().sort(function(a,b){
    var na=trNomeColab(a.funcionario_id)||'', nb=trNomeColab(b.funcionario_id)||'';
    if(na!==nb) return na.localeCompare(nb,'pt-BR');
    var va=String(a.val||a.validade||''), vb=String(b.val||b.validade||'');
    return va<vb?1:va>vb?-1:0;
  });

  var total=linhas.length;
  var pageSize=_trUi.pageSize||50;
  var pages=Math.max(1, Math.ceil(total/pageSize)||1);
  if(_trUi.page>pages) _trUi.page=pages;
  if(_trUi.page<1) _trUi.page=1;
  var start=(_trUi.page-1)*pageSize;
  var slice=linhas.slice(start, start+pageSize);

  var prevNome='';
  tbody.innerHTML=slice.map(function(t){
    var val=t.val||t.validade;var s=stV(val);
    var abertura=t.data||t.data_inicio||(t.criado_em?String(t.criado_em):'');
    var nome=trNomeColab(t.funcionario_id);
    var nomeHtml;
    if(nome!=='—' && nome===prevNome) nomeHtml='<span style="color:#bbb">↳</span>';
    else { nomeHtml='<span style="font-weight:500">'+escHtml(nome)+'</span>'; prevNome=nome; }
    return '<tr><td title="ID: '+escHtml(String(t.funcionario_id||''))+'">'+nomeHtml+'</td>'
      +'<td><span class="bdg purple">'+escHtml(t.nr||'—')+'</span></td><td>'+escHtml(t.titulo||'—')+'</td>'
      +'<td style="font-size:11px;white-space:nowrap">'+fmtD(abertura)+'</td>'
      +'<td>'+fmtD(val)+'</td><td>'+(s?'<span class="bdg '+s.cls+'">'+s.lbl+'</span>':'—')+'</td>'
      +'<td style="color:#888">'+(t.epis_liberados||'—')+'</td>'
      +'<td><button class="btn btn-sm" onclick="renovarTrein(\''+t.id+'\')">Renovar</button></td></tr>';
  }).join('') || (fColab
    ? '<tr><td colspan="8" style="text-align:center;color:#854F0B;padding:1rem;background:#FFF7E6">⏳ <b>'+escHtml(fNomeColaborador(fColab))+'</b> ainda não tem treinamento registrado — status: <b>Em treinamento</b>. <button class="btn btn-sm btn-pri" style="margin-left:8px" onclick="openLancarTreinamento(\''+fColab+'\')">+ Registrar treinamento</button></td></tr>'
    : '<tr><td colspan="8" style="text-align:center;color:#aaa;padding:1rem">Nenhum treinamento para o filtro selecionado.</td></tr>');

  var cont=document.getElementById('tr-fil-cont');
  if(cont){
    var nOrf=treinamentos.filter(function(t){ return !t.deleted_at && !trResolverColabDeFid(t.funcionario_id); }).length;
    var de=total? (start+1) : 0;
    var ate=start+slice.length;
    cont.textContent=(total?('Mostrando '+de+'–'+ate+' de '+total):'0')+' filtrado(s) · '+treinamentos.length+' no total'
      +(fSit==='ativos' && nOrf?' · '+nOrf+' órfão(s) oculto(s)':'');
  }

  var pager=document.getElementById('tr-pager');
  if(!pager && card){
    pager=document.createElement('div');
    pager.id='tr-pager';
    pager.style.cssText='display:flex;gap:6px;flex-wrap:wrap;align-items:center;justify-content:flex-end;padding:.5rem .75rem;border-top:.5px solid #f0efe8;font-size:12px';
    card.appendChild(pager);
  }
  if(pager){
    if(pages<=1){ pager.innerHTML=''; }
    else {
      pager.innerHTML=
        (_trUi.page>1?'<button type="button" class="btn btn-sm" onclick="trGotoPage('+(_trUi.page-1)+')">Anterior</button>':'')
        +'<span style="color:#666">Página '+_trUi.page+' / '+pages+'</span>'
        +(_trUi.page<pages?'<button type="button" class="btn btn-sm" onclick="trGotoPage('+(_trUi.page+1)+')">Próximo</button>':'');
    }
  }
  _trUi.montado=true;
  cenaPerfEnd('sesmt-treinamentos-render', {
    filtrados: total,
    pagina: _trUi.page,
    pageSize: pageSize,
    rendered: slice.length,
    domNodes: cenaPerfDomCount('pg-sesmt-treinamentos')
  });
}
// ══════════════════════════════════════════════════════════════
// SESMT — TURMAS DE TREINAMENTO (turmas + sync automático c/ escalas)
// ══════════════════════════════════════════════════════════════
var TURMA_ST={ 'Programado':{c:'#854F0B',bg:'#FEF3E2'},'Em andamento':{c:'#534AB7',bg:'#EEEDFE'},'Concluído':{c:'#3B6D11',bg:'#EAF3DE'},'Cancelado':{c:'#A32D2D',bg:'#FCEBEB'} };
var _trilhas=[]; var _trilhasCarregado=false;          // trilhas de formação por cargo
var _turmaFiltroSt=''; var _turmaBusca='';             // filtros da lista de turmas
var _trilhaEditId=null; var _trilhaEditCursos=[]; var _trilhaEditCargo='';
var RECEM_DIAS=90;
var _admPorRe=null;
function _carregarAdmissoes(cb){
  if(_admPorRe || DEMO){ if(cb)cb(); return; }
  sbFetch('funcionarios',{select:'matricula,admissao',limit:5000}).then(function(rows){
    _admPorRe={}; (rows||[]).forEach(function(f){ if(f.matricula!=null && f.admissao) _admPorRe[String(f.matricula).trim()]=f.admissao; });
    if(cb)cb();
  }).catch(function(){ _admPorRe={}; if(cb)cb(); });
}
function _admissaoDe(c){ if(c.admissao) return c.admissao; if(_admPorRe && c.re!=null) return _admPorRe[String(c.re).trim()]||null; return null; }
function progSyncAdmissoesDiario(){
  try{
    var hoje=dataHojeLocal();
    if(localStorage.getItem('cena_sync_adm_dia')===hoje) return;
    if(typeof PONTO_API_URL==='undefined' || !PONTO_API_URL) return;
    localStorage.setItem('cena_sync_adm_dia',hoje);
    fetch(PONTO_API_URL+'/api/v1/sincronizar-admissoes',{method:'POST',headers:{'Content-Type':'application/json'}})
      .then(function(r){ return r.ok?r.json():null; })
      .then(function(res){ if(!res) localStorage.removeItem('cena_sync_adm_dia'); })
      .catch(function(){ localStorage.removeItem('cena_sync_adm_dia'); });
  }catch(e){}
}
function _turmaPartDe(tid){ return _sesmtTurmaPart.filter(function(p){return p.turma_id===tid;}); }
function _normTxt(s){ return (s||'').toString().trim().toLowerCase(); }
function _diasDesde(dStr){ if(!dStr) return null; var d=new Date(dStr+'T12:00:00'); if(isNaN(d)) return null; return Math.floor((new Date(dataHojeLocal()+'T12:00:00')-d)/86400000); }
function _recemContratado(c){ var n=_diasDesde(_admissaoDe(c)); return n!==null && n>=0 && n<=RECEM_DIAS; }
// Colaborador está em alguma turma não concluída/cancelada (independe de data)
function _colabTemTurmaAberta(colabId){
  return _sesmtTurmaPart.some(function(p){
    if(p.colaborador_id!==colabId) return false;
    if(['Desistiu','Demitido','Removido'].indexOf(p.status)>=0) return false;
    var t=_sesmtTurmas.find(function(x){return x.id===p.turma_id;});
    return t && t.status!=='Concluído' && t.status!=='Cancelado';
  });
}
// Trilha aplicável a um cargo (preferir match exato; fuzzy só com overlap forte)
function _trilhaDoCargo(cargo){
  var cg=_normTxt(cargo); if(!cg) return null;
  var exact=_trilhas.filter(function(t){
    if(t.ativo===false) return false;
    return _normTxt(t.cargo)===cg;
  });
  if(exact.length) return exact[0];
  var tokens=cg.split(/\s+/).filter(function(x){ return x.length>=4; });
  var cand=_trilhas.filter(function(t){
    if(t.ativo===false) return false;
    var tc=_normTxt(t.cargo);
    if(!tc||tc.length<5) return false;
    var tt=tc.split(/\s+/).filter(function(x){ return x.length>=4; });
    var shared=tokens.filter(function(x){ return tt.indexOf(x)>=0; }).length;
    // Evita "COORDENADORA DE PROJETOS" pegar trilha de outro coordenador só pela 1ª palavra
    if(shared<2) return false;
    return cg.indexOf(tc)>=0 || tc.indexOf(cg)>=0 || shared>=Math.min(3, tokens.length);
  });
  if(!cand.length) return null;
  cand.sort(function(a,b){ return _normTxt(b.cargo).length-_normTxt(a.cargo).length; });
  return cand[0];
}
function _trilhaCargoNorm(cargo){ return _normTxt(cargo||''); }
function _trilhaExisteCargo(cargo, exceptId){
  var k=_trilhaCargoNorm(cargo); if(!k) return false;
  return _trilhas.some(function(t){
    if(t.ativo===false) return false;
    if(exceptId && t.id===exceptId) return false;
    return _trilhaCargoNorm(t.cargo)===k;
  });
}
function _trilhaCargoSelectHtml(selected){
  selected=selected||'';
  var usados={};
  _trilhas.forEach(function(t){
    if(t.ativo===false) return;
    if(_trilhaEditId && t.id===_trilhaEditId) return;
    usados[_trilhaCargoNorm(t.cargo)]=true;
  });
  var ativos=_cargosParaSelect();
  var byCat={};
  ativos.forEach(function(c){
    if(usados[_trilhaCargoNorm(c.nome)] && _trilhaCargoNorm(c.nome)!==_trilhaCargoNorm(selected)) return;
    (byCat[c.categoria||'Outros']=byCat[c.categoria||'Outros']||[]).push(c.nome);
  });
  var existe=ativos.some(function(c){ return c.nome===selected; });
  var html='<select id="tr-cargo" class="inp" style="width:100%"><option value="">— Selecione o cargo —</option>';
  if(selected && !existe) html+='<optgroup label="Atual (fora do cadastro)"><option value="'+escHtml(selected)+'" selected>'+escHtml(selected)+'</option></optgroup>';
  Object.keys(byCat).sort().forEach(function(cat){
    html+='<optgroup label="'+escHtml(cat)+'">'+byCat[cat].map(function(n){
      return '<option value="'+escHtml(n)+'"'+(n===selected?' selected':'')+'>'+escHtml(n)+'</option>';
    }).join('')+'</optgroup>';
  });
  if(!Object.keys(byCat).length && !selected) html+='<option value="" disabled>(todos os cargos já têm trilha)</option>';
  return html+'</select>';
}
function _trilhaCursoIds(t){ try{ return Array.isArray(t.curso_ids)?t.curso_ids:JSON.parse(t.curso_ids||'[]'); }catch(e){ return []; } }
// IDs relacionados ao colaborador (colaboradores.id + funcionarios.id legado via RE)
function _colabIdsRelacionados(colabId){
  var ids={};
  if(colabId==null||colabId==='') return ids;
  function add(id){ if(id!=null&&id!=='') ids[String(id)]=true; }
  add(colabId);
  var col=(colaboradores||[]).find(function(c){ return String(c.id)===String(colabId); });
  if(!col && typeof sesmtTreinamentoColabId==='function'){
    var cid=sesmtTreinamentoColabId(colabId);
    if(cid) col=(colaboradores||[]).find(function(c){ return String(c.id)===String(cid); });
  }
  if(col){
    add(col.id);
    if(typeof extratoFuncionarioPorRe==='function'){
      var func=extratoFuncionarioPorRe(col.re);
      if(func) add(func.id);
    } else if(typeof trNormRe==='function'){
      var k=trNormRe(col.re||col.matricula||'');
      if(k) (typeof funcs!=='undefined'?funcs:[]).forEach(function(f){
        if(trNormRe(f.matricula||f.re||'')===k) add(f.id);
      });
    }
  }
  return ids;
}
function _colabTemTreinamentoId(t, colabId){
  return !!_colabIdsRelacionados(colabId)[String(t.funcionario_id)];
}
function _treinamentoBateCurso(t, curso){
  if(!curso||!t) return false;
  if(curso.id && t.curso_id && String(t.curso_id)===String(curso.id)) return true;
  var sig=typeof trNormSigla==='function'?trNormSigla(curso.sigla):String(curso.sigla||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
  var nome=typeof trNormSigla==='function'?trNormSigla(curso.nome):String(curso.nome||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
  if(!sig && !nome) return false;
  var nr=typeof trNormSigla==='function'?trNormSigla(t.nr):String(t.nr||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
  var tit=typeof trNormSigla==='function'?trNormSigla(t.titulo):String(t.titulo||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
  if(sig && (nr===sig || nr.indexOf(sig)>=0 || tit.indexOf(sig)>=0)) return true;
  if(nome && nome.length>=3 && (tit.indexOf(nome)>=0 || nr.indexOf(nome)>=0)) return true;
  return false;
}
// Colaborador já fez (e está válido) determinado curso?
function _colabFezCurso(colabId, curso){
  if(!curso) return false;
  var hoje=dataHojeLocal();
  // 1) registro em treinamentos (cadastro + banco), validade ok
  var fezTr=(typeof treinamentos!=='undefined'?treinamentos:[]).some(function(t){
    if(t.deleted_at) return false;
    if(!_colabTemTreinamentoId(t, colabId)) return false;
    if(!_treinamentoBateCurso(t, curso)) return false;
    var v=t.val||t.validade; return !v||v>=hoje;
  });
  if(fezTr) return true;
  // 2) concluiu turma deste curso
  return _sesmtTurmaPart.some(function(p){
    if(String(p.colaborador_id)!==String(colabId) || !p.concluiu) return false;
    var t=_sesmtTurmas.find(function(x){return x.id===p.turma_id;});
    return t && String(t.curso_id)===String(curso.id);
  });
}
// Próximo curso pendente do colaborador, conforme a trilha do seu cargo
function _colabProximoCurso(c){
  var tr=_trilhaDoCargo(c.cargo);
  if(!tr) return null;
  var ids=_trilhaCursoIds(tr); if(!ids.length) return null;
  for(var i=0;i<ids.length;i++){
    var cur=_cad_cursos.find(function(x){return x.id===ids[i];});
    if(!cur) continue;
    if(typeof aptCursoEhNa==='function' && aptCursoEhNa(c, cur.id)) continue;
    if(!_colabFezCurso(c.id, cur)) return { curso:cur, ordem:i+1, total:ids.length };
  }
  return { completo:true, total:ids.length };
}
function _turmaContIds(t){ try{ return Array.isArray(t.contrato_ids)?t.contrato_ids:JSON.parse(t.contrato_ids||'[]'); }catch(e){ return []; } }
function _dataMaisDias(dStr,n){ if(!dStr) return null; var d=new Date(dStr+'T12:00:00'); d.setDate(d.getDate()+n); return d.toISOString().slice(0,10); }
var _turmaCaches=null;
function _turmaInvalidateCaches(){ _turmaCaches=null; }
function _turmaBuildCaches(){
  if(_turmaCaches) return _turmaCaches;
  var hoje=dataHojeLocal();
  var colabById={}, fidToColabId={};
  (colaboradores||[]).forEach(function(c){
    colabById[String(c.id)]=c;
    if(typeof extratoFuncionarioPorRe==='function'){
      var f=extratoFuncionarioPorRe(c.re);
      if(f) fidToColabId[String(f.id)]=String(c.id);
    }
  });
  var treinPorColab={}, turmaConcl={}, turmaAberta={};
  (treinamentos||[]).forEach(function(t){
    if(t.deleted_at) return;
    var v=t.val||t.validade;
    if(v && v<hoje) return;
    var colabId=fidToColabId[String(t.funcionario_id)]||String(t.funcionario_id);
    var col=colabById[colabId];
    if(!col || col.ativo===false || col.dispensado) return;
    if(!treinPorColab[colabId]) treinPorColab[colabId]=[];
    treinPorColab[colabId].push({
      curso_id:t.curso_id,
      sig:typeof trNormSigla==='function'?trNormSigla(t.nr):String(t.nr||'').toUpperCase().replace(/[^A-Z0-9]/g,''),
      tit:typeof trNormSigla==='function'?trNormSigla(t.titulo):String(t.titulo||'').toUpperCase().replace(/[^A-Z0-9]/g,'')
    });
  });
  var turmaById={};
  (_sesmtTurmas||[]).forEach(function(t){ turmaById[t.id]=t; });
  (_sesmtTurmaPart||[]).forEach(function(p){
    var t=turmaById[p.turma_id];
    if(!t) return;
    if(p.concluiu && t.curso_id) turmaConcl[String(p.colaborador_id)+':'+String(t.curso_id)]=true;
    if(['Desistiu','Demitido','Removido'].indexOf(p.status)<0 && t.status!=='Concluído' && t.status!=='Cancelado')
      turmaAberta[String(p.colaborador_id)]=true;
  });
  _turmaCaches={ hoje:hoje, treinPorColab:treinPorColab, turmaConcl:turmaConcl, turmaAberta:turmaAberta };
  return _turmaCaches;
}
function _colabFezCursoIdx(colabId, curso, cache){
  if(!curso) return false;
  cache=cache||_turmaBuildCaches();
  if(cache.turmaConcl[String(colabId)+':'+String(curso.id)]) return true;
  var list=cache.treinPorColab[String(colabId)]||[];
  var sig=typeof trNormSigla==='function'?trNormSigla(curso.sigla):String(curso.sigla||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
  var nome=typeof trNormSigla==='function'?trNormSigla(curso.nome):String(curso.nome||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
  return list.some(function(e){
    if(curso.id && e.curso_id && String(e.curso_id)===String(curso.id)) return true;
    if(sig && (e.sig===sig || e.sig.indexOf(sig)>=0 || e.tit.indexOf(sig)>=0)) return true;
    if(nome && nome.length>=3 && e.tit.indexOf(nome)>=0) return true;
    return false;
  });
}
function _colabProximoCursoIdx(c, cache){
  var tr=_trilhaDoCargo(c.cargo);
  if(!tr) return null;
  var ids=_trilhaCursoIds(tr); if(!ids.length) return null;
  for(var i=0;i<ids.length;i++){
    var cur=_cad_cursos.find(function(x){return x.id===ids[i];});
    if(!cur) continue;
    if(typeof aptCursoEhNa==='function' && aptCursoEhNa(c, cur.id)) continue;
    if(!_colabFezCursoIdx(c.id, cur, cache)) return { curso:cur, ordem:i+1, total:ids.length };
  }
  return { completo:true, total:ids.length };
}

function sesmtCarregarTurmas(cb){
  if(DEMO){ _sesmtTurmasCarregado=true; _turmaInvalidateCaches(); if(cb)cb(); return; }
  _turmaInvalidateCaches();
  var promessas=[
    sbFetch('sesmt_turmas',{order:'data_inicio.desc'}),
    sbFetch('sesmt_turma_participantes',{limit:5000}),
    sbFetch('sesmt_trilha_cargo',{}).catch(function(){ return []; }),
    (!_cad_cursos.length ? sbFetch('sesmt_cursos',{filters:['status=eq.Ativo'],order:'nome.asc'}).catch(function(){ return []; }) : Promise.resolve(null))
  ];
  if(!treinamentos || !treinamentos.length){
    promessas.push(sbFetchAll('treinamentos',{
      filters:['deleted_at=is.null'],
      order:'validade.desc',
      select:'id,funcionario_id,curso_id,nr,titulo,validade,deleted_at'
    }));
  } else {
    promessas.push(Promise.resolve(null));
  }
  Promise.all(promessas).then(function(r){
    _sesmtTurmas=r[0]||[]; _sesmtTurmaPart=r[1]||[]; _trilhas=r[2]||[]; _trilhasCarregado=true; _sesmtTurmasCarregado=true;
    if(r[3] && r[3].length) _cad_cursos=r[3];
    if(r[4] && r[4].length) treinamentos=r[4];
    _turmaInvalidateCaches();
    if(cb) cb();
    _carregarAdmissoes(function(){ _turmaInvalidateCaches(); if(typeof renderTurmas==='function') renderTurmas(); });
  }).catch(function(e){ console.warn('turmas:',e); _sesmtTurmasCarregado=true; if(cb)cb(); });
}

function renderTurmas(){
  var box=document.getElementById('turmas-container'); if(!box) return;
  if(!_sesmtTurmasCarregado){ box.innerHTML='<div class="card" style="padding:2rem;text-align:center;color:#aaa">⏳ Carregando turmas...</div>'; return; }
  var bq=_normTxt(_turmaBusca);
  var turmasF=_sesmtTurmas.filter(function(t){
    if(_turmaFiltroSt && t.status!==_turmaFiltroSt) return false;
    if(bq){ var alvo=_normTxt(t.titulo)+' '+_normTxt(t.instituicao)+' '+_normTxt(t.observacoes); if(alvo.indexOf(bq)<0) return false; }
    return true;
  });
  var cards=turmasF.map(function(t){
    var parts=_turmaPartDe(t.id);
    var concl=parts.filter(function(p){return p.concluiu;}).length;
    var st=TURMA_ST[t.status]||TURMA_ST['Programado'];
    // Integrantes por contrato (chips)
    var contCount={};
    parts.forEach(function(p){ var cc=colaboradores.find(function(x){return x.id===p.colaborador_id;}); var cid=p.contrato_id||(cc&&cc.contrato_id)||'__sem__'; contCount[cid]=(contCount[cid]||0)+1; });
    var allC={}; _turmaContIds(t).forEach(function(id){if(id)allC[id]=true;}); Object.keys(contCount).forEach(function(id){allC[id]=true;});
    var contChips=Object.keys(allC).map(function(cid){
      var c=contratos.find(function(x){return x.id===cid;});
      return { nome:(c?(c.nome||c.codigo):(cid==='__sem__'?'Sem contrato':'—')), n:contCount[cid]||0 };
    }).sort(function(a,b){ return b.n-a.n || a.nome.localeCompare(b.nome,'pt-BR'); }).map(function(x){
      return '<span style="display:inline-flex;align-items:center;gap:6px;background:#EBF4FD;border:.5px solid #185FA533;border-radius:14px;padding:2px 4px 2px 10px;font-size:11px;color:#185FA5;font-weight:500">'+escHtml(x.nome)
        +'<span style="background:'+(x.n?'#185FA5':'#bbb')+';color:#fff;border-radius:10px;padding:0 7px;font-size:10px;font-weight:700;min-width:14px;text-align:center">'+x.n+'</span></span>';
    }).join('');
    return '<div class="card" style="margin-bottom:.75rem">'
      +'<div class="ch"><span class="ct">'+escHtml(t.titulo)+'</span>'
      +'<span style="background:'+st.bg+';color:'+st.c+';border-radius:6px;padding:2px 10px;font-size:11px;font-weight:600">'+escHtml(t.status)+'</span></div>'
      +'<div style="padding:.5rem .9rem;font-size:12px;color:#555;display:grid;grid-template-columns:1fr 1fr;gap:4px 16px">'
      +'<div>🏫 <b>'+escHtml(t.instituicao||'—')+'</b></div>'
      +'<div>📅 '+fmtD(t.data_inicio)+(t.data_fim?' — '+fmtD(t.data_fim):'')+'</div>'
      +'<div>👥 Início: <b>'+(parts.length||t.qtd_inicio||0)+'</b> · Concluíram: <b style="color:#3B6D11">'+concl+'</b></div>'
      +'<div style="grid-column:1/-1;display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin-top:2px"><span style="color:#888">📁 Contratos:</span>'+(contChips||'<span style="color:#aaa">sem contrato previsto</span>')+'</div>'
      +(t.observacoes?'<div style="grid-column:1/-1;color:#888;margin-top:2px">📝 '+escHtml(t.observacoes)+'</div>':'')
      +'</div>'
      +'<div style="padding:.4rem .9rem .7rem;display:flex;gap:6px;flex-wrap:wrap;border-top:.5px solid #f5f5f3">'
      +'<button class="btn btn-sm btn-pri" onclick="openTurmaDetalhe(\''+t.id+'\')">👥 Participantes ('+parts.length+')</button>'
      +'<button class="btn btn-sm" onclick="openTurmaModal(\''+t.id+'\')">✎ Editar</button>'
      +(t.status!=='Em andamento'&&t.status!=='Concluído'&&t.status!=='Cancelado'?'<button class="btn btn-sm" style="color:#534AB7;border-color:#534AB7" onclick="turmaIniciar(\''+t.id+'\')">▶ Iniciar (aplicar nas escalas)</button>':'')
      +(t.status!=='Concluído'&&t.status!=='Cancelado'?'<button class="btn btn-sm" style="color:#3B6D11;border-color:#3B6D11" onclick="turmaConcluir(\''+t.id+'\')">✅ Concluir turma</button>':'')
      +'</div></div>';
  }).join('');
  var stBtns=[['','Todas'],['Programado','Programado'],['Em andamento','Em andamento'],['Concluído','Concluído'],['Cancelado','Cancelado']].map(function(s){
    var on=_turmaFiltroSt===s[0]; var cor=TURMA_ST[s[0]];
    return '<button class="btn btn-sm" onclick="turmaFiltrarSt(\''+s[0]+'\')" style="'+(on?'background:'+(cor?cor.c:'#185FA5')+';color:#fff;border-color:'+(cor?cor.c:'#185FA5'):'')+'">'+escHtml(s[1])+'</button>';
  }).join('');
  box.innerHTML='<div class="card" style="margin-bottom:1rem"><div class="ch"><span class="ct">👥 Turmas de Treinamento ('+_sesmtTurmas.length+')</span>'
    +'<div style="display:flex;gap:6px"><button class="btn btn-sm" onclick="openTrilhas()" title="Sequência de cursos por cargo">🪜 Trilhas por cargo</button><button class="btn btn-pri" onclick="openTurmaModal()">+ Nova Turma</button></div></div>'
    +'<div style="padding:.4rem .9rem;font-size:11px;color:#888">Matricule colaboradores e clique em <b>▶ Iniciar</b> para marcá-los como <b>Em treinamento</b> nas escalas (somem dos Disponíveis). Ao <b>✅ Concluir</b>, voltam a ficar disponíveis e geram alerta de 7 dias na Programação.</div>'
    +'<div style="padding:.2rem .9rem .7rem;display:flex;flex-wrap:wrap;gap:6px;align-items:center"><span style="font-size:11px;color:#888">Filtrar:</span>'+stBtns
    +'<input class="inp" id="turma-busca" oninput="turmaBuscar(this.value)" value="'+escHtml(_turmaBusca)+'" placeholder="🔎 nome, instituição..." style="flex:1;min-width:160px;max-width:280px;font-size:12px;padding:4px 8px"/>'
    +'<span style="font-size:11px;color:#aaa">'+turmasF.length+' de '+_sesmtTurmas.length+'</span></div></div>'
    +'<div id="turma-aguardando-slot"><div class="card" style="margin-bottom:1rem;padding:1rem;text-align:center;color:#aaa;font-size:12px">⏳ Calculando aguardando formação...</div></div>'
    +(cards||'<div class="card" style="padding:2rem;text-align:center;color:#aaa">'+( _turmaFiltroSt||_turmaBusca?'Nenhuma turma com esse filtro.':'Nenhuma turma cadastrada. Clique em <b>+ Nova Turma</b>.')+'</div>');
  var bi=document.getElementById('turma-busca'); if(bi && bq){ bi.focus(); bi.setSelectionRange(bi.value.length,bi.value.length); }
  setTimeout(function(){ _turmaRenderAguardandoSlot(); }, 0);
}
function _turmaRenderAguardandoSlot(){
  var slot=document.getElementById('turma-aguardando-slot');
  if(!slot) return;
  try{ slot.outerHTML=_renderAguardandoFormacao(); }
  catch(e){ console.warn('aguardando formação:',e); slot.outerHTML='<div class="card" style="margin-bottom:1rem;padding:1rem;color:#A32D2D;font-size:12px">Erro ao calcular aguardando formação.</div>'; }
}
function turmaFiltrarSt(s){ _turmaFiltroSt=s; renderTurmas(); }
function turmaBuscar(v){ _turmaBusca=v; renderTurmas(); }

function _renderAguardandoFormacao(){
  var porCurso={}, semTrilha=[];
  var cache=_turmaBuildCaches();
  colaboradores.forEach(function(c){
    if(c.ativo===false || c.dispensado===true) return;
    if(cache.turmaAberta[String(c.id)]) return;
    var prox=_colabProximoCursoIdx(c, cache);
    if(prox && prox.curso){
      (porCurso[prox.curso.id]=porCurso[prox.curso.id]||{curso:prox.curso,colabs:[]}).colabs.push({c:c,ordem:prox.ordem,total:prox.total});
    } else if(!prox && _recemContratado(c)){
      semTrilha.push(c);
    }
  });
  var grupos=Object.keys(porCurso).map(function(k){return porCurso[k];})
    .sort(function(a,b){ return b.colabs.length-a.colabs.length; });
  var totalAg=grupos.reduce(function(s,g){return s+g.colabs.length;},0);
  var corpo=grupos.map(function(g){
    var rows=g.colabs.sort(function(a,b){ return (_diasDesde(_admissaoDe(a.c))||0)-(_diasDesde(_admissaoDe(b.c))||0); }).map(function(o){
      var c=o.c; var cont=contratos.find(function(x){return x.id===c.contrato_id;});
      var dias=_diasDesde(_admissaoDe(c));
      var recem=_recemContratado(c);
      return '<div style="display:flex;align-items:center;gap:8px;padding:3px 0;border-top:.5px solid #f5f5f3;font-size:12px">'
        +'<span style="flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+(recem?'🆕 ':'')+escHtml(c.nome)+(c.re?' <span style="color:#aaa;font-size:10px">RE '+escHtml(String(c.re))+'</span>':'')+'</span>'
        +'<span style="color:#888;font-size:11px;white-space:nowrap">'+escHtml(c.cargo||'—')+(cont?' · '+escHtml(cont.codigo||cont.nome):'')+'</span>'
        +(dias!==null?'<span style="color:#aaa;font-size:10px;white-space:nowrap">'+(recem?'há '+dias+'d':'')+'</span>':'')
        +'<span class="bdg" style="font-size:9px;white-space:nowrap">passo '+o.ordem+'/'+o.total+'</span></div>';
    }).join('');
    return '<div style="margin-bottom:.6rem;background:#fafafa;border:.5px solid #eee;border-radius:8px;padding:8px 10px">'
      +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:2px">'
      +'<b style="font-size:13px">'+escHtml((g.curso.sigla?g.curso.sigla+' — ':'')+g.curso.nome)+'</b>'
      +'<span style="background:#FEF3E2;color:#854F0B;border-radius:10px;padding:0 8px;font-size:11px;font-weight:700">'+g.colabs.length+' aguardando</span>'
      +'<button class="btn btn-sm btn-pri" style="margin-left:auto;font-size:11px" onclick="openTurmaModalCurso(\''+g.curso.id+'\')">➕ Criar turma</button></div>'
      +rows+'</div>';
  }).join('');
  var avisoSem = semTrilha.length? '<div style="margin-top:.4rem;font-size:11px;color:#A36A00;background:#FEF3E2;border-radius:6px;padding:6px 10px">⚠ '+semTrilha.length+' recém-contratado(s) em cargo(s) sem trilha definida. Configure em <b>🪜 Trilhas por cargo</b> para saber qual curso eles aguardam.</div>':'';
  var vazio='';
  if(!totalAg && !semTrilha.length){
    vazio = !_trilhas.length
      ? '<div style="font-size:12px;color:#777;background:#fafafa;border:.5px dashed #ddd;border-radius:8px;padding:10px 12px">Nenhuma <b>trilha por cargo</b> cadastrada ainda. Clique em <button class="btn btn-sm" onclick="openTrilhas()">🪜 Trilhas por cargo</button> e defina a sequência de cursos de cada cargo — aqui aparecerá quem está aguardando cada curso.</div>'
      : '<div style="font-size:12px;color:#aaa">Ninguém aguardando no momento: todos os colaboradores das trilhas atuais já estão em turma ou concluíram a sequência.</div>';
  }
  return '<div class="card" style="margin-bottom:1rem"><div class="ch"><span class="ct">⏳ Aguardando formação de turma ('+totalAg+')</span>'
    +'<span style="font-size:11px;color:#888">próximo curso da trilha por cargo</span></div>'
    +'<div style="padding:.6rem .9rem">'+(corpo||'')+vazio+avisoSem+'</div></div>';
}
function openTurmaModalCurso(cursoId){
  openTurmaModal();
  setTimeout(function(){ var s=document.getElementById('tm-curso'); if(s){ s.value=cursoId; var o=s.options[s.selectedIndex]; var ti=document.getElementById('tm-titulo'); if(o&&o.dataset.nome&&!ti.value) ti.value=o.dataset.nome; } },60);
}

function openTrilhas(){
  _trilhaEditId=null; _trilhaEditCursos=[]; _trilhaEditCargo='';
  if(!_cad_cargos.length && !DEMO){ cadCarregarCargos(openTrilhas); return; }
  if(!_cad_cursos.length && !DEMO){ sbFetch('sesmt_cursos',{filters:['status=eq.Ativo'],order:'nome.asc'}).then(function(r){ if(r&&r.length)_cad_cursos=r; _renderTrilhasModal(); }).catch(function(){ _renderTrilhasModal(); }); }
  else _renderTrilhasModal();
}
function openTrilhaExcecoes(cargo){
  _trilhaCaptura();
  cargo=String(cargo||_trilhaEditCargo||'').trim();
  if(!cargo){ progShowToast('Selecione o cargo da trilha para ver as exceções.','erro'); return; }
  var t=typeof _trilhaDoCargo==='function'?_trilhaDoCargo(cargo):(_trilhas||[]).find(function(x){ return x.ativo!==false && _normTxt(x.cargo)===_normTxt(cargo); });
  var ids=t?(typeof _trilhaCursoIds==='function'?_trilhaCursoIds(t):[]):(_trilhaEditCursos||[]);
  var cursos=ids.map(function(id){ return (_cad_cursos||[]).find(function(x){ return String(x.id)===String(id); }); }).filter(Boolean);
  if(!cursos.length){ progShowToast('Esta trilha ainda não tem cursos na sequência.','erro'); return; }
  var colabs=(colaboradores||[]).filter(function(c){ return c.ativo!==false && !c.dispensado && _normTxt(c.cargo)===_normTxt(cargo); })
    .sort(function(a,b){ return String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR'); });
  var rows=colabs.map(function(c){
    var cid=String(c.id||'').replace(/'/g,"\\'");
    var chips=cursos.map(function(cur){
      var isNa=typeof aptCursoEhNa==='function' && aptCursoEhNa(c, cur.id);
      var kid=String(cur.id||'').replace(/'/g,"\\'");
      return '<button class="btn btn-sm" type="button" onclick="aptToggleCursoNa(\''+cid+'\',\''+kid+'\')" style="font-size:10px;padding:2px 7px;'+(isNa?'background:#EBF4FD;color:#185FA5;border-color:#185FA5':'color:#888')+'" title="'+(isNa?'Voltar a exigir':'Não se aplica a este colaborador')+'">'
        +(isNa?'N/A · ':'')+escHtml(cur.sigla||cur.nome)+'</button>';
    }).join('');
    return '<div style="display:flex;align-items:flex-start;gap:8px;padding:6px 0;border-top:.5px solid #eee">'
      +'<div style="flex:1;min-width:0"><div style="font-size:12px;font-weight:600">'+escHtml(c.nome||'—')+'</div>'
      +'<div style="font-size:10px;color:#888">'+(c.re?'RE '+escHtml(String(c.re)):'')+'</div></div>'
      +'<div style="display:flex;flex-wrap:wrap;gap:4px;justify-content:flex-end">'+chips+'</div></div>';
  }).join('');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:640px;max-height:92vh;overflow-y:auto" id="trilha-exc-wrap">'
    +'<h3 style="margin:0 0 .4rem">Exceções da trilha — '+escHtml(cargo)+'</h3>'
    +'<div style="font-size:11px;color:#666;margin-bottom:.8rem">Toque no curso para marcar <b>N/A</b> (não se aplica) a esse colaborador. Ele deixa de aguardar o curso e não fica pendente na Evolução/Aptidão. A trilha dos demais permanece igual.</div>'
    +(rows||'<div style="color:#aaa;font-size:12px">Nenhum colaborador ativo neste cargo.</div>')
    +'<div class="ma" style="margin-top:1rem;display:flex;gap:8px;justify-content:flex-end">'
    +'<button class="btn" type="button" onclick="openTrilhas()">← Voltar às trilhas</button>'
    +'<button class="btn btn-pri" type="button" onclick="closeModal()">Fechar</button></div>'
    +'</div></div>');
}
function _trilhaCaptura(){ var ca=document.getElementById('tr-cargo'); if(ca)_trilhaEditCargo=ca.value; }
function trilhaNova(){ _trilhaCaptura(); _trilhaEditId=null; _trilhaEditCursos=[]; _trilhaEditCargo=''; _renderTrilhasModal(); }
function trilhaEditar(id){ var t=_trilhas.find(function(x){return x.id===id;}); if(!t)return; _trilhaEditId=id; _trilhaEditCursos=_trilhaCursoIds(t).slice(); _trilhaEditCargo=t.cargo||''; _renderTrilhasModal(); }
function trilhaAddCurso(){ _trilhaCaptura(); var s=document.getElementById('tr-add-curso'); if(!s||!s.value)return; if(_trilhaEditCursos.indexOf(s.value)<0)_trilhaEditCursos.push(s.value); _renderTrilhasModal(); }
function trilhaMoveCurso(i,dir){ _trilhaCaptura(); var j=i+dir; if(j<0||j>=_trilhaEditCursos.length)return; var tmp=_trilhaEditCursos[i]; _trilhaEditCursos[i]=_trilhaEditCursos[j]; _trilhaEditCursos[j]=tmp; _renderTrilhasModal(); }
function trilhaRemoveCurso(i){ _trilhaCaptura(); _trilhaEditCursos.splice(i,1); _renderTrilhasModal(); }
function _cargosDistintos(){ var set={}; colaboradores.forEach(function(c){ if(c.ativo!==false && c.cargo) set[c.cargo]=true; }); return Object.keys(set).sort(function(a,b){return a.localeCompare(b,'pt-BR');}); }
function _renderTrilhasModal(){
  var seq=_trilhaEditCursos.map(function(cid,i){
    var cur=_cad_cursos.find(function(x){return x.id===cid;});
    return '<div style="display:flex;align-items:center;gap:8px;background:#f9f9f7;border:.5px solid #e0dfd8;border-radius:6px;padding:5px 8px;margin-bottom:4px">'
      +'<span style="background:#185FA5;color:#fff;border-radius:50%;width:20px;height:20px;display:inline-flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;flex-shrink:0">'+(i+1)+'</span>'
      +'<span style="flex:1;min-width:0;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+escHtml(cur?((cur.sigla?cur.sigla+' — ':'')+cur.nome):'(curso removido)')+'</span>'
      +'<button class="btn btn-sm" style="padding:0 6px" onclick="trilhaMoveCurso('+i+',-1)" '+(i===0?'disabled':'')+'>↑</button>'
      +'<button class="btn btn-sm" style="padding:0 6px" onclick="trilhaMoveCurso('+i+',1)" '+(i===_trilhaEditCursos.length-1?'disabled':'')+'>↓</button>'
      +'<button class="btn btn-sm" style="padding:0 6px;color:#A32D2D;border-color:#A32D2D" onclick="trilhaRemoveCurso('+i+')">✕</button></div>';
  }).join('');
  var addOpts='<option value="">+ Adicionar curso à sequência...</option>'+_cad_cursos.filter(function(c){return c.status!=='Inativo' && _trilhaEditCursos.indexOf(c.id)<0;}).map(function(c){return '<option value="'+c.id+'">'+escHtml((c.sigla?c.sigla+' — ':'')+c.nome)+'</option>';}).join('');
  var seenCargo={}, duplicatas=0;
  var lista=_trilhas.slice().sort(function(a,b){
    var ca=_trilhaCargoNorm(a.cargo), cb=_trilhaCargoNorm(b.cargo);
    if(ca!==cb) return ca.localeCompare(cb,'pt-BR');
    return String(a.id||'').localeCompare(String(b.id||''));
  }).map(function(t){
    var ids=_trilhaCursoIds(t);
    var k=_trilhaCargoNorm(t.cargo);
    var isDup=!!seenCargo[k]; if(isDup) duplicatas++; else seenCargo[k]=true;
    var dupBadge=isDup?' <span style="font-size:10px;background:#FCEBEB;color:#A32D2D;border-radius:8px;padding:1px 6px;font-weight:600">duplicata — exclua</span>':'';
    var chips=ids.map(function(cid,i){ var cur=_cad_cursos.find(function(x){return x.id===cid;}); return '<span style="background:#EEF;border-radius:10px;padding:1px 8px;font-size:10px;color:#534AB7">'+(i+1)+'. '+escHtml(cur?(cur.sigla||cur.nome):'?')+'</span>'; }).join(' ');
    return '<div style="border-top:.5px solid #eee;padding:6px 0;display:flex;align-items:flex-start;gap:8px'+(isDup?';background:#fffafa':'')+'">'
      +'<div style="flex:1;min-width:0"><div style="font-weight:600;font-size:13px">'+escHtml(t.cargo)+dupBadge+'</div>'
      +'<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:3px">'+(chips||'<span style="color:#aaa;font-size:11px">sem cursos</span>')+'</div></div>'
      +'<button class="btn btn-sm" onclick="trilhaEditar(\''+t.id+'\')">✎</button>'
      +'<button class="btn btn-sm" onclick="openTrilhaExcecoes(\''+String(t.cargo||'').replace(/'/g,"\\'")+'\')" title="Exceções N/A">N/A</button>'
      +'<button class="btn btn-sm" style="color:#A32D2D;border-color:#A32D2D" onclick="trilhaDeletar(\''+t.id+'\')">🗑</button></div>';
  }).join('');
  var avisoDup=duplicatas? '<div style="font-size:11px;color:#A36A00;background:#FEF3E2;border-radius:6px;padding:6px 10px;margin-bottom:.6rem">⚠ Há <b>'+duplicatas+'</b> trilha(s) duplicada(s) (mesmo cargo). Exclua as marcadas como <b>duplicata</b> — deve existir só uma por cargo.</div>':'';
  var qtdUnica=Object.keys(seenCargo).length;
  setModal('<div class="modal-bg"><div class="modal" style="max-width:600px;max-height:92vh;overflow-y:auto">'
    +'<h3 style="margin-bottom:.5rem">🪜 Trilhas de formação por cargo</h3>'
    +'<div style="font-size:11px;color:#888;margin-bottom:.8rem">Uma trilha padrão por cargo. O contrato é definido na hora de montar a turma — não precisa repetir aqui.</div>'
    +'<div style="background:#fafafa;border:.5px solid #eee;border-radius:8px;padding:10px;margin-bottom:1rem">'
    +'<div style="font-weight:600;font-size:12px;margin-bottom:.5rem">'+(_trilhaEditId?'✎ Editando trilha':'➕ Nova trilha')+'</div>'
    +'<div class="fg" style="margin-bottom:.6rem"><label style="font-size:11px;font-weight:500">Cargo *</label>'+_trilhaCargoSelectHtml(_trilhaEditCargo)+'</div>'
    +'<label style="font-size:11px;font-weight:500">Sequência de cursos</label>'
    +'<div style="margin:.3rem 0">'+(seq||'<div style="color:#aaa;font-size:12px;padding:4px 0">Nenhum curso na sequência ainda.</div>')+'</div>'
    +'<select class="inp" id="tr-add-curso" style="width:100%;margin-bottom:.6rem" onchange="trilhaAddCurso()">'+addOpts+'</select>'
    +'<div style="font-size:11px;color:#666;background:#EBF4FD;border-radius:6px;padding:6px 8px;margin-bottom:.6rem">Exceção: um colaborador deste cargo pode <b>não precisar</b> de um curso da trilha. Marque <b>N/A</b> aqui ou em SESMT → Evolução → 📋 Detalhes.</div>'
    +'<div style="display:flex;gap:6px;justify-content:flex-end;flex-wrap:wrap">'+(_trilhaEditId?'<button class="btn btn-sm" onclick="trilhaNova()">Limpar / nova</button>':'')
    +'<button class="btn btn-sm" type="button" onclick="openTrilhaExcecoes()" title="Não exigir curso para determinados colaboradores">Exceções N/A</button>'
    +'<button class="btn btn-pri btn-sm" onclick="salvarTrilha()">💾 Salvar trilha</button></div>'
    +'</div>'
    +avisoDup
    +'<div style="font-weight:600;font-size:12px;margin-bottom:.3rem">Trilhas cadastradas ('+qtdUnica+' cargo'+(qtdUnica===1?'':'s')+')</div>'
    +(lista||'<div style="color:#aaa;font-size:12px">Nenhuma trilha cadastrada ainda.</div>')
    +'<div class="ma" style="margin-top:1rem"><button class="btn" onclick="closeModal()">Fechar</button></div>'
    +'</div></div>');
}
function salvarTrilha(){
  _trilhaCaptura();
  var cargo=(_trilhaEditCargo||'').trim();
  if(!cargo){ progShowToast('⚠ Informe o cargo.','erro'); return; }
  if(!_trilhaEditCursos.length){ progShowToast('⚠ Adicione ao menos um curso à sequência.','erro'); return; }
  if(_trilhaExisteCargo(cargo, _trilhaEditId)){ progShowToast('⚠ Já existe trilha para o cargo "'+cargo+'". Edite a existente.','erro'); return; }
  if(aptTrilhaPrecisaIntegracao(cargo)){
    var iidInt=aptCursoIntegraId();
    if(iidInt){
      _trilhaEditCursos=_trilhaEditCursos.filter(function(x){ return String(x)!==String(iidInt); });
      _trilhaEditCursos.push(iidInt);
    }
  }
  var payload={ cargo:cargo, contrato_id:null, curso_ids:_trilhaEditCursos.slice(), ativo:true, atualizado_em:new Date().toISOString(), atualizado_por:(usuarioLogado?usuarioLogado.nome:null) };
  if(_trilhaEditId){
    var t=_trilhas.find(function(x){return x.id===_trilhaEditId;}); if(t) Object.assign(t,payload);
    if(!DEMO) sbUpdate('sesmt_trilha_cargo',payload,'id=eq.'+_trilhaEditId);
    progShowToast('✅ Trilha atualizada.');
    _trilhaEditId=null; _trilhaEditCursos=[]; _trilhaEditCargo=''; _renderTrilhasModal(); renderTurmas();
  } else if(!DEMO){
    sbInsert('sesmt_trilha_cargo',payload).then(function(r){ if(r&&r[0])_trilhas.push(r[0]); progShowToast('✅ Trilha criada.'); _trilhaEditCursos=[]; _trilhaEditCargo=''; _renderTrilhasModal(); renderTurmas(); })
      .catch(function(){ progShowToast('❌ Erro ao salvar. Rodou o sql_trilha_cargo.sql no Supabase?','erro'); });
  } else { payload.id='trilha'+Date.now(); _trilhas.push(payload); _trilhaEditCursos=[]; _trilhaEditCargo=''; _renderTrilhasModal(); renderTurmas(); }
}
function trilhaDeletar(id){
  var t=_trilhas.find(function(x){return x.id===id;}); if(!t)return;
  if(!confirm('Excluir a trilha do cargo "'+t.cargo+'"?')) return;
  var i=_trilhas.findIndex(function(x){return x.id===id;}); if(i>=0)_trilhas.splice(i,1);
  if(!DEMO) sbDelete('sesmt_trilha_cargo','id=eq.'+id);
  if(_trilhaEditId===id){ _trilhaEditId=null; _trilhaEditCursos=[]; _trilhaEditCargo=''; }
  progShowToast('🗑 Trilha excluída.'); _renderTrilhasModal(); renderTurmas();
}

function openTurmaModal(id){
  var t=id?_sesmtTurmas.find(function(x){return x.id===id;}):null;
  if(!_cad_cursos.length && !DEMO){ sbFetch('sesmt_cursos',{filters:['status=eq.Ativo'],order:'nome.asc'}).then(function(r){ if(r&&r.length)_cad_cursos=r; _turmaModal(t); }).catch(function(){ _turmaModal(t); }); }
  else _turmaModal(t);
}
function _turmaModal(t){
  t=t||{};
  var curOpts='<option value="">Selecione o curso (opcional)...</option>'+_cad_cursos.filter(function(c){return c.status!=='Inativo';}).map(function(c){
    return '<option value="'+c.id+'" data-nome="'+escHtml(c.nome||'')+'"'+(t.curso_id===c.id?' selected':'')+'>'+escHtml((c.sigla?c.sigla+' — ':'')+c.nome)+'</option>'; }).join('');
  var stOpts=['Programado','Em andamento','Concluído','Cancelado'].map(function(s){return '<option'+(t.status===s?' selected':'')+'>'+s+'</option>';}).join('');
  var idsSel=_turmaContIds(t);
  var contCk=contratos.map(function(c){return '<label title="'+escHtml(c.nome)+'" style="display:flex;align-items:center;gap:6px;font-size:12px;padding:4px 6px;border-radius:5px;cursor:pointer;min-width:0"><input type="checkbox" class="turma-cont-ck" value="'+c.id+'"'+(idsSel.indexOf(c.id)>=0?' checked':'')+' style="width:14px;height:14px;flex-shrink:0;margin:0"/><span style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+escHtml(c.nome)+'</span></label>';}).join('');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:540px;max-height:90vh;overflow-y:auto">'
    +'<h3 style="margin-bottom:.75rem">'+(t.id?'✎ Editar Turma':'👥 Nova Turma')+'</h3>'
    +'<div class="fg" style="margin-bottom:.6rem"><label style="font-size:11px;font-weight:500">Nome da turma *</label><input class="inp" id="tm-titulo" style="width:100%" value="'+escHtml(t.titulo||'')+'" placeholder="Ex: Turma NR-35 Junho / Mobilização Linha 3"/></div>'
    +'<div class="fg" style="margin-bottom:.6rem"><label style="font-size:11px;font-weight:500">Tipo de treinamento (curso)</label><select class="inp" id="tm-curso" style="width:100%" onchange="var o=this.options[this.selectedIndex];var ti=document.getElementById(\'tm-titulo\');if(o.dataset.nome&&!ti.value)ti.value=o.dataset.nome;">'+curOpts+'</select></div>'
    +'<div class="fg" style="margin-bottom:.6rem"><label style="font-size:11px;font-weight:500">Instituição *</label><input class="inp" id="tm-inst" style="width:100%" value="'+escHtml(t.instituicao||'')+'" placeholder="Escola / empresa instrutora"/></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:.6rem">'
    +'<div class="fg"><label style="font-size:11px;font-weight:500">Início *</label><input class="inp" type="date" id="tm-ini" style="width:100%" value="'+(t.data_inicio||'')+'"/></div>'
    +'<div class="fg"><label style="font-size:11px;font-weight:500">Fim</label><input class="inp" type="date" id="tm-fim" style="width:100%" value="'+(t.data_fim||'')+'"/></div>'
    +'<div class="fg"><label style="font-size:11px;font-weight:500">Status</label><select class="inp" id="tm-status" style="width:100%">'+stOpts+'</select></div>'
    +'</div>'
    +'<div class="fg" style="margin-bottom:.6rem"><label style="font-size:11px;font-weight:500">Contratos previstos</label><div style="background:#f9f9f7;border:.5px solid #e0dfd8;border-radius:8px;padding:6px;max-height:150px;overflow-y:auto;display:grid;grid-template-columns:1fr 1fr;gap:2px 8px">'+(contCk||'<span style="font-size:11px;color:#aaa">Sem contratos</span>')+'</div></div>'
    +'<div class="fg" style="margin-bottom:.6rem"><label style="font-size:11px;font-weight:500">Observações</label><input class="inp" id="tm-obs" style="width:100%" value="'+escHtml(t.observacoes||'')+'"/></div>'
    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn btn-pri" onclick="salvarTurma('+(t.id?'\''+t.id+'\'':'')+')">💾 Salvar</button></div>'
    +'</div></div>');
}
function salvarTurma(id){
  var titulo=((document.getElementById('tm-titulo')||{}).value||'').trim();
  var inst=((document.getElementById('tm-inst')||{}).value||'').trim();
  var ini=(document.getElementById('tm-ini')||{}).value||'';
  if(!titulo||!inst||!ini){ progShowToast('⚠ Preencha título, instituição e data de início.','erro'); return; }
  var conts=[]; document.querySelectorAll('.turma-cont-ck:checked').forEach(function(ck){conts.push(ck.value);});
  var payload={ curso_id:(document.getElementById('tm-curso')||{}).value||null, titulo:titulo, instituicao:inst,
    data_inicio:ini, data_fim:(document.getElementById('tm-fim')||{}).value||null,
    status:(document.getElementById('tm-status')||{}).value||'Programado',
    contrato_ids:conts, observacoes:((document.getElementById('tm-obs')||{}).value||'').trim()||null };
  if(id){
    var t=_sesmtTurmas.find(function(x){return x.id===id;}); if(t) Object.assign(t,payload);
    if(!DEMO) sbUpdate('sesmt_turmas',payload,'id=eq.'+id);
    closeModal(); renderTurmas();
  } else if(!DEMO){
    sbInsert('sesmt_turmas',payload).then(function(r){ if(r&&r[0]) _sesmtTurmas.unshift(r[0]); closeModal(); renderTurmas(); })
      .catch(function(){ progShowToast('❌ Erro ao salvar. Você já rodou o sql_sesmt_turmas.sql no Supabase?','erro'); });
  } else { payload.id='turma'+Date.now(); _sesmtTurmas.unshift(payload); closeModal(); renderTurmas(); }
}

// ── Helpers de prontidão (Uniformes / EPIs / Treinamentos) ──────
function _turmaUnifOk(colabId, re){
  return (typeof uniformesEnt!=='undefined') && uniformesEnt.some(function(u){
    if(u.funcionario_id!==colabId || u.ativo===false) return false;
    var cat=(uniformesCat||[]).find(function(x){return x.id===u.uniforme_id;});
    return cat && re.test((cat.tipo||'').toLowerCase());
  });
}
function _turmaEpiStatus(colabId){
  var meus=(typeof epis!=='undefined'?epis:[]).filter(function(e){ return e.responsavel_id===colabId && ['Devolvido','Substituído','Cancelado'].indexOf(e.status)<0; });
  if(!meus.length) return 'Pendente';
  var hoje=dataHojeLocal();
  var ok=meus.every(function(e){ return (!e.validade||e.validade>=hoje) && (!e.ca_validade||e.ca_validade>=hoje); });
  return ok?'Entregue':'Parcial';
}
function _turmaHAR(colabId){
  var hoje=dataHojeLocal();
  return (typeof treinamentos!=='undefined'?treinamentos:[]).some(function(t){
    if(t.deleted_at || !_colabTemTreinamentoId(t, colabId)) return false;
    var s=((t.nr||'')+' '+(t.titulo||'')).toUpperCase(); var v=t.val||t.validade;
    return (/\bHAR\b/.test(s)||s.indexOf('AREA DE RISCO')>=0||s.indexOf('ÁREA DE RISCO')>=0||s.indexOf('ACESSO A AREA')>=0) && (!v||v>=hoje);
  })?'ok':'Fazer';
}
function _turmaIntegrado(colabId){
  return (typeof treinamentos!=='undefined'?treinamentos:[]).some(function(t){
    if(t.deleted_at || !_colabTemTreinamentoId(t, colabId)) return false;
    var s=((t.titulo||'')+' '+(t.nr||'')).toLowerCase();
    return s.indexOf('integra')>=0 || s.indexOf('indu')>=0;
  })?'Sim':'Não';
}
function _turmaTipoTreinoDefault(colabId, t){
  var curso=(_cad_cursos||[]).find(function(x){return x.id===t.curso_id;});
  var jaFez=(typeof treinamentos!=='undefined'?treinamentos:[]).some(function(x){
    if(x.deleted_at || !_colabTemTreinamentoId(x, colabId)) return false;
    if(curso && _treinamentoBateCurso(x, curso)) return true;
    return (t.titulo||'') && (x.titulo||'').toUpperCase()===(t.titulo||'').toUpperCase();
  });
  return jaFez?'reciclagem':'fazer';
}
function _okNao(ok){ return ok?'<span style="color:#3B6D11;font-weight:700">ok</span>':'<span style="color:#A32D2D;font-weight:700">não</span>'; }

function openTurmaDetalhe(id){
  var t=_sesmtTurmas.find(function(x){return x.id===id;}); if(!t) return;
  _turmaAbertaId=id;
  var parts=_turmaPartDe(id);
  var linhas=parts.map(function(p){
    var c=colaboradores.find(function(x){return x.id===p.colaborador_id;})||{};
    var cont=contratos.find(function(x){return x.id===(p.contrato_id||c.contrato_id);});
    var cid=p.colaborador_id;
    var tipo=p.tipo_treino||_turmaTipoTreinoDefault(cid,t);
    var epiSt=_turmaEpiStatus(cid); var epiCor={Entregue:'#3B6D11',Parcial:'#854F0B',Pendente:'#A32D2D'}[epiSt];
    var har=_turmaHAR(cid); var integ=_turmaIntegrado(cid);
    var saiu=['Desistiu','Demitido'].indexOf(p.status)>=0;
    var stBadge=p.status==='Desistiu'?' <span class="bdg warn" style="font-size:9px">🚪 Desistiu</span>':p.status==='Demitido'?' <span class="bdg danger" style="font-size:9px">❌ Demitido</span>':p.status==='Concluído'?' <span class="bdg ok" style="font-size:9px">✓ Concluiu</span>':'';
    return '<tr'+(saiu?' style="opacity:.5;background:#faf5f5"':'')+'>'
      +'<td style="font-weight:500;white-space:nowrap;position:sticky;left:0;background:#fff">'+escHtml(c.nome||'—')+(c.re?' <span style="color:#888;font-size:10px">RE '+escHtml(String(c.re))+'</span>':'')+stBadge+'</td>'
      +'<td style="font-size:11px;color:#555;white-space:nowrap">'+escHtml(c.cargo||'—')+'</td>'
      +'<td style="text-align:center"><select class="inp" style="font-size:10px;padding:1px 3px;width:92px" onchange="turmaSetPart(\''+p.id+'\',\'tipo_treino\',this.value)"><option value="fazer"'+(tipo==='fazer'?' selected':'')+'>Fazer</option><option value="reciclagem"'+(tipo==='reciclagem'?' selected':'')+'>Reciclagem</option></select></td>'
      +'<td style="text-align:center">'+_okNao(_turmaUnifOk(cid,/camisa/))+'</td>'
      +'<td style="text-align:center">'+_okNao(_turmaUnifOk(cid,/cal[çc]a/))+'</td>'
      +'<td style="text-align:center">'+_okNao(_turmaUnifOk(cid,/botina|cal[çc]ado|bota\b/))+'</td>'
      +'<td style="text-align:center"><span style="color:'+epiCor+';font-weight:600;font-size:11px">'+epiSt+'</span></td>'
      +'<td style="text-align:center;cursor:pointer" title="Clique para alternar (manual)" onclick="turmaSetPart(\''+p.id+'\',\'cracha_ok\','+(p.cracha_ok?'false':'true')+');openTurmaDetalhe(\''+t.id+'\')">'+_okNao(!!p.cracha_ok)+'</td>'
      +'<td style="text-align:center">'+(har==='ok'?'<span style="color:#3B6D11;font-weight:700">ok</span>':'<span style="color:#854F0B;font-weight:700">Fazer</span>')+'</td>'
      +'<td style="text-align:center">'+(integ==='Sim'?'<span style="color:#3B6D11;font-weight:700">Sim</span>':'<span style="color:#A32D2D;font-weight:700">Não</span>')+'</td>'
      +'<td style="font-size:11px;color:#555;white-space:nowrap">'+escHtml(cont?(cont.nome||cont.codigo):'—')+'</td>'
      +'<td style="text-align:center"><input type="checkbox" '+(p.presente?'checked':'')+' onchange="turmaSetPart(\''+p.id+'\',\'presente\',this.checked)"/></td>'
      +'<td style="text-align:center"><input type="number" min="0" max="100" value="'+(p.presenca_pct!=null?p.presenca_pct:'')+'" style="width:52px;text-align:center" class="inp" onchange="turmaSetPart(\''+p.id+'\',\'presenca_pct\',this.value)"/></td>'
      +'<td style="text-align:center"><input type="checkbox" '+(p.concluiu?'checked':'')+' onchange="turmaSetPart(\''+p.id+'\',\'concluiu\',this.checked)"/></td>'
      +'<td style="text-align:center"><button class="btn btn-sm" style="color:#A32D2D;border-color:#A32D2D" onclick="turmaRemoverParticipante(\''+p.id+'\')">✕</button></td>'
      +'</tr>';
  }).join('');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:1150px;width:96vw;max-height:92vh;overflow-y:auto">'
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:.5rem"><h3 style="margin:0;font-size:15px">👥 '+escHtml(t.titulo)+'</h3><button class="btn" onclick="closeModal()" style="margin-left:auto;padding:3px 9px">✕</button></div>'
    +'<div style="font-size:12px;color:#888;margin-bottom:.6rem">🏫 '+escHtml(t.instituicao)+' · 📅 '+fmtD(t.data_inicio)+(t.data_fim?' — '+fmtD(t.data_fim):'')+' · Status: <b>'+escHtml(t.status)+'</b></div>'
    +'<div class="fg" style="margin-bottom:.6rem"><label style="font-size:11px;font-weight:500">+ Adicionar participante</label><div style="position:relative">'
    +'<input class="inp" id="turma-busca" style="width:100%;max-width:420px" placeholder="Buscar por nome ou RE..." oninput="turmaBuscarColab(this.value)" autocomplete="off"/>'
    +'<div id="turma-drop" style="display:none;position:absolute;left:0;right:0;top:100%;z-index:50;background:#fff;border:.5px solid #e0dfd8;border-radius:0 0 8px 8px;max-height:220px;overflow-y:auto;box-shadow:0 4px 12px rgba(0,0,0,.12)"></div>'
    +'</div></div>'
    +'<div style="font-size:10px;color:#aaa;margin-bottom:4px">Camisa/Calça/Botina = Uniformes · EPIs = Entregue/Parcial/Pendente · Crachá = clique para alternar (manual) · HAR/Integrado = treinamentos</div>'
    +'<div style="overflow-x:auto"><table class="tbl" style="font-size:12px"><thead><tr>'
    +'<th style="position:sticky;left:0;background:#f5f5f3">Colaborador</th><th>Cargo</th><th style="text-align:center">Treino</th>'
    +'<th style="text-align:center">Camisa</th><th style="text-align:center">Calça</th><th style="text-align:center">Botina</th>'
    +'<th style="text-align:center">EPIs</th><th style="text-align:center">Crachá</th><th style="text-align:center">HAR</th><th style="text-align:center">Integrado</th>'
    +'<th>Contrato</th><th style="text-align:center">Presente</th><th style="text-align:center">Presença %</th><th style="text-align:center">Concluiu</th><th></th></tr></thead>'
    +'<tbody>'+(linhas||'<tr><td colspan="15" style="text-align:center;color:#aaa;padding:1rem">Nenhum participante. Adicione acima.</td></tr>')+'</tbody></table></div>'
    +'<div class="ma"><button class="btn btn-pri" onclick="closeModal();renderTurmas()">Fechar</button></div>'
    +'</div></div>');
}
function turmaBuscarColab(q){
  var drop=document.getElementById('turma-drop'); if(!drop) return;
  q=(q||'').toLowerCase().trim(); if(q.length<2){ drop.style.display='none'; return; }
  // Exclui apenas participantes ATIVOS; quem saiu (Desistiu/Demitido/Removido) pode reaparecer p/ ser reativado.
  var saiuIds={}; var ativIds=[];
  _turmaPartDe(_turmaAbertaId).forEach(function(p){ if(['Desistiu','Demitido','Removido'].indexOf(p.status)>=0) saiuIds[p.colaborador_id]=p.status; else ativIds.push(p.colaborador_id); });
  var res=colaboradores.filter(function(c){ if(c.ativo===false) return false; if(ativIds.indexOf(c.id)>=0) return false; return (c.nome||'').toLowerCase().indexOf(q)>=0||String(c.re||'').toLowerCase().indexOf(q)>=0; }).slice(0,30);
  drop.style.display='';
  drop.innerHTML=res.map(function(c){ var voltou=saiuIds[c.id]; return '<div onclick="turmaAddParticipante(\''+c.id+'\')" style="padding:7px 10px;cursor:pointer;border-bottom:.5px solid #f0efe8;font-size:12px"><b>'+escHtml(c.nome)+'</b>'+(c.re?' <span style="color:#aaa;font-size:10px">RE '+escHtml(String(c.re))+'</span>':'')+(voltou?' <span style="color:#854F0B;font-size:10px">↩ reativar ('+escHtml(voltou)+')</span>':'')+'</div>'; }).join('')||'<div style="padding:10px;color:#aaa;font-size:12px;text-align:center">Nenhum encontrado.</div>';
}
function turmaAddParticipante(colabId){
  var t=_sesmtTurmas.find(function(x){return x.id===_turmaAbertaId;}); if(!t) return;
  var c=colaboradores.find(function(x){return x.id===colabId;})||{};
  // Já existe registro deste colaborador nesta turma? (evita 409 da constraint turma_id+colaborador_id)
  var existente=_sesmtTurmaPart.find(function(x){ return x.turma_id===_turmaAbertaId && x.colaborador_id===colabId; });
  if(existente){
    var saiu=['Desistiu','Demitido','Removido'].indexOf(existente.status)>=0;
    if(!saiu){ progShowToast('ℹ '+(c.nome||'Colaborador')+' já está nesta turma.'); openTurmaDetalhe(_turmaAbertaId); return; }
    // Estava como Desistiu/Demitido/Removido → reativar o registro existente
    existente.status='Inscrito'; existente.data_conclusao=null; existente.concluiu=false;
    if(!DEMO) sbUpdate('sesmt_turma_participantes',{status:'Inscrito',data_conclusao:null,concluiu:false},'id=eq.'+existente.id).catch(function(){});
    if(t.status==='Em andamento') turmaAplicarEscalaUm(t,existente);
    progShowToast('✅ '+(c.nome||'Colaborador')+' reativado na turma.');
    openTurmaDetalhe(_turmaAbertaId); return;
  }
  var part={ turma_id:_turmaAbertaId, colaborador_id:colabId, contrato_id:c.contrato_id||null, presente:false, concluiu:false, status:'Inscrito' };
  if(!DEMO){ sbInsert('sesmt_turma_participantes',part).then(function(r){
      if(r&&r[0]){ _sesmtTurmaPart.push(r[0]); if(t.status==='Em andamento') turmaAplicarEscalaUm(t,r[0]); openTurmaDetalhe(_turmaAbertaId); return; }
      // r===null → falhou (provável duplicata no banco fora do cache). Reativa por turma+colab e recarrega.
      sbUpdate('sesmt_turma_participantes',{status:'Inscrito',data_conclusao:null,concluiu:false},'turma_id=eq.'+_turmaAbertaId+'&colaborador_id=eq.'+colabId)
        .then(function(ok){ if(ok){ progShowToast('✅ '+(c.nome||'Colaborador')+' já constava — reativado na turma.'); sesmtCarregarTurmas(function(){ openTurmaDetalhe(_turmaAbertaId); }); }
                            else { openTurmaDetalhe(_turmaAbertaId); } })
        .catch(function(){ openTurmaDetalhe(_turmaAbertaId); });
    }); }
  else { part.id='tp'+Date.now(); _sesmtTurmaPart.push(part); openTurmaDetalhe(_turmaAbertaId); }
}
function turmaRemoverParticipante(pid){
  var p=_sesmtTurmaPart.find(function(x){return x.id===pid;}); if(!p) return;
  var c=(colaboradores||[]).find(function(x){return x.id===p.colaborador_id;})||{};
  setModal('<div class="modal-bg"><div class="modal" style="max-width:420px">'
    +'<h3 style="margin-bottom:.4rem">Retirar participante</h3>'
    +'<div style="font-size:12px;color:#555;margin-bottom:.7rem"><b>'+escHtml(c.nome||'—')+'</b>'+(c.re?' · RE '+escHtml(String(c.re)):'')+'</div>'
    +'<div style="display:flex;flex-direction:column;gap:8px">'
    +'<button class="btn" onclick="turmaPartAcao(\''+pid+'\',\'excluir\')" style="text-align:left">🗑 <b>Excluir</b> — cadastrado por engano (sai do curso, sem outros efeitos)</button>'
    +'<button class="btn" style="text-align:left;color:#854F0B;border-color:#854F0B" onclick="turmaPartAcao(\''+pid+'\',\'Desistiu\')">🚪 <b>Desistiu</b> — não volta aos disponíveis; <b>inativa</b> o colaborador</button>'
    +'<button class="btn" style="text-align:left;color:#A32D2D;border-color:#A32D2D" onclick="turmaPartAcao(\''+pid+'\',\'Demitido\')">❌ <b>Demitido</b> — não volta aos disponíveis; <b>inativa</b> o colaborador</button>'
    +'</div>'
    +'<div class="ma" style="margin-top:.7rem"><button class="btn" onclick="openTurmaDetalhe(\''+_turmaAbertaId+'\')">Cancelar</button></div>'
    +'</div></div>');
}
function turmaPartAcao(pid, acao){
  var p=_sesmtTurmaPart.find(function(x){return x.id===pid;}); if(!p) return;
  var hoje=dataHojeLocal();
  if(acao==='excluir'){
    _sesmtTurmaPart=_sesmtTurmaPart.filter(function(x){return x.id!==pid;});
    if(!DEMO) sbDelete('sesmt_turma_participantes','id=eq.'+pid);
    progShowToast('🗑 Participante removido (cadastro por engano).');
  } else {
    // Desistiu / Demitido — marca o participante e INATIVA o colaborador
    p.status=acao; p.data_conclusao=null;
    if(!DEMO) sbUpdate('sesmt_turma_participantes',{status:acao},'id=eq.'+pid).catch(function(){});
    var c=(colaboradores||[]).find(function(x){return x.id===p.colaborador_id;});
    if(c){
      c.ativo=false;
      var upd={ativo:false};
      if(acao==='Demitido'){ c.dispensado=true; c.data_dispensa=hoje; upd.dispensado=true; upd.data_dispensa=hoje; }
      if(!DEMO) sbUpdate('colaboradores',upd,'id=eq.'+c.id).catch(function(){ progShowToast('⚠ Erro ao inativar colaborador.','erro'); });
    }
    // liberar eventual status de treinamento desta turma na escala (não volta aos disponíveis pois está inativo)
    if(!DEMO){ var tt=_sesmtTurmas.find(function(x){return x.id===p.turma_id;})||{}; if(tt.data_inicio) sbUpdate('prog_status_diario',{data_retorno:hoje},'colaborador_id=eq.'+p.colaborador_id+'&data=eq.'+tt.data_inicio+'&status=eq.treinamento').catch(function(){}); }
    progShowToast(acao==='Demitido'?'❌ Marcado como Demitido e inativado no cadastro.':'🚪 Marcado como Desistiu e inativado no cadastro.');
  }
  openTurmaDetalhe(_turmaAbertaId);
}
function turmaSetPart(pid,campo,val){
  var p=_sesmtTurmaPart.find(function(x){return x.id===pid;}); if(!p) return;
  if(campo==='presenca_pct') val=(val===''?null:parseFloat(val));
  p[campo]=val; var upd={}; upd[campo]=val;
  if(!DEMO) sbUpdate('sesmt_turma_participantes',upd,'id=eq.'+pid);
}
// Aplica status "treinamento" na escala de UM participante (período da turma)
function turmaAplicarEscalaUm(turma,part){
  if(DEMO) return;
  var ret=_dataMaisDias(turma.data_fim||turma.data_inicio,1);
  var row={ colaborador_id:part.colaborador_id, data:turma.data_inicio, status:'treinamento',
    data_retorno:ret, obs:'Turma: '+turma.titulo+(turma.instituicao?' ('+turma.instituicao+')':''),
    deleted_at:null, registrado_por:usuarioLogado?usuarioLogado.nome:'' };
  sbUpsert('prog_status_diario',row,'colaborador_id,data');
  var c=colaboradores.find(function(x){return x.id===part.colaborador_id;});
  if(c){ c.turma_ativa_id=turma.id; sbUpdate('colaboradores',{turma_ativa_id:turma.id},'id=eq.'+part.colaborador_id).catch(function(){}); }
}
function turmaIniciar(id){
  var t=_sesmtTurmas.find(function(x){return x.id===id;}); if(!t) return;
  var parts=_turmaPartDe(id);
  if(!parts.length){ progShowToast('⚠ Adicione participantes antes de iniciar.','erro'); return; }
  if(!confirm('Iniciar a turma "'+t.titulo+'"?\n\n'+parts.length+' colaborador(es) ficarão como "Em treinamento" nas escalas de '+fmtD(t.data_inicio)+(t.data_fim?' a '+fmtD(t.data_fim):'')+' e sairão dos Disponíveis.')) return;
  t.status='Em andamento'; t.qtd_inicio=parts.length;
  if(!DEMO) sbUpdate('sesmt_turmas',{status:'Em andamento',qtd_inicio:parts.length},'id=eq.'+id);
  parts.forEach(function(p){ turmaAplicarEscalaUm(t,p); });
  progShowToast('▶ Turma iniciada — '+parts.length+' em treinamento nas escalas.');
  renderTurmas();
}
function turmaConcluir(id){
  var t=_sesmtTurmas.find(function(x){return x.id===id;}); if(!t) return;
  var parts=_turmaPartDe(id);
  if(!confirm('Concluir a turma "'+t.titulo+'"?\n\nOs participantes voltam a ficar DISPONÍVEIS nas escalas e geram alerta de 7 dias na Programação para os supervisores.')) return;
  var hoje=dataHojeLocal(), concluidos=0;
  parts.forEach(function(p){
    var c=colaboradores.find(function(x){return x.id===p.colaborador_id;});
    // liberar escala a partir de hoje (status treinamento deixa de valer)
    if(!DEMO) sbUpdate('prog_status_diario',{data_retorno:hoje},'colaborador_id=eq.'+p.colaborador_id+'&data=eq.'+t.data_inicio+'&status=eq.treinamento').catch(function(){});
    if(p.concluiu){
      concluidos++;
      p.status='Concluído'; p.data_conclusao=hoje;
      if(!DEMO) sbUpdate('sesmt_turma_participantes',{status:'Concluído',data_conclusao:hoje},'id=eq.'+p.id).catch(function(){});
      if(c){ c.turma_ativa_id=null; c.data_novo_disponivel=hoje; if(!DEMO) sbUpdate('colaboradores',{turma_ativa_id:null,data_novo_disponivel:hoje},'id=eq.'+c.id).catch(function(){}); }
      var curso=_cad_cursos.find(function(x){return x.id===t.curso_id;});
      var tr={ funcionario_id:p.colaborador_id, nr:(curso&&curso.sigla)||'TR', titulo:t.titulo, escola:t.instituicao, curso_id:t.curso_id||null };
      if(!DEMO) sbInsert('treinamentos',tr).then(function(r){ if(r&&r[0]) treinamentos.push(r[0]); }).catch(function(){});
    } else if(c){ c.turma_ativa_id=null; if(!DEMO) sbUpdate('colaboradores',{turma_ativa_id:null},'id=eq.'+c.id).catch(function(){}); }
  });
  t.status='Concluído'; t.data_conclusao=hoje; t.qtd_conclusao=concluidos;
  if(!DEMO) sbUpdate('sesmt_turmas',{status:'Concluído',data_conclusao:hoje,qtd_conclusao:concluidos},'id=eq.'+id);
  progShowToast('✅ Turma concluída — '+concluidos+' concluíram. Liberados aos disponíveis.');
  renderTurmas();
}

function renderOc(){
  var sc={'Vale emitido':'warn','Assinado — desconto folha':'danger','Aguardando aprovação':'warn','Substituído':'ok'};
  document.getElementById('tbody-oc').innerHTML=ocorrencias.map(function(o){
    return '<tr><td>'+fmtD(o.data_ocorrencia)+'</td><td>'+fNome(o.funcionario_id)+'</td><td>'+o.item+'</td>'
      +'<td><span class="bdg '+(o.tipo.indexOf('Perda')>=0?'danger':o.tipo.indexOf('mau')>=0||o.tipo==='Dano'?'warn':'gray')+'">'+o.tipo+'</span></td>'
      +'<td style="color:#888">'+o.motivo+'</td>'
      +'<td><span class="bdg '+(sc[o.status]||'info')+'">'+o.status+'</span></td>'
      +'<td><button class="btn btn-sm" onclick="verRelatorio(\''+fNome(o.funcionario_id)+'\',\''+o.item+'\',\''+o.tipo+'\','+o.valor+',\''+fmtD(o.data_ocorrencia)+'\')">Ver</button></td></tr>';
  }).join('');
}
function renderAprovacoes(){
  var pend=aprovacoes.filter(function(a){return a.status==='pendente';});
  var el=document.getElementById('m-aprov');if(el)el.textContent=pend.length;
  if(!pend.length){document.getElementById('aprovacoes-list').innerHTML='<div style="border:0.5px solid #e0dfd8;border-radius:12px;display:flex;align-items:center;justify-content:center;height:120px;color:#bbb;font-size:13px">Nenhuma aprovação pendente</div>';return;}
  document.getElementById('aprovacoes-list').innerHTML=pend.map(function(a){
    return '<div class="aprov-card"><h4>Aprovação pendente — '+a.tipo+'</h4>'
      +'<div style="font-size:12px;margin-bottom:.75rem;line-height:1.7">'
      +'<b>Colaborador:</b> '+fNome(a.funcionario_id)+'<br>'
      +'<b>Item:</b> '+(a.item||'—')+'<br><b>Motivo:</b> '+(a.motivo||'—')+'<br>'
      +(a.valor>0?'<b>Valor:</b> R$ '+Number(a.valor).toLocaleString('pt-BR')+'<br>':'')
      +'<b>Data:</b> '+(a.data||todayStr())+'</div>'
      +'<div style="display:flex;gap:8px">'
      +'<button class="btn btn-pri" onclick="aprovar(\''+a.id+'\')">Aprovar</button>'
      +'<button class="btn" style="border-color:#A32D2D;color:#A32D2D" onclick="rejeitar(\''+a.id+'\')">Rejeitar</button>'
      +'</div></div>';
  }).join('');
  renderNavCards('aprovacoes');
}
function aprovar(id){
  var a=aprovacoes.find(function(x){return x.id===id;});if(!a)return;
  a.status='aprovado';
  var n=vales.length+1;
  var novo={id:'v'+n,numero:'VALE-'+('000'+n).slice(-4),funcionario_id:a.funcionario_id,item:a.item||'—',motivo:a.motivo||'—',tipo:Number(a.valor)>0?'Desconto folha':'Substituição',valor:Number(a.valor),status:'Aprovado',data_emissao:dataHojeLocal()};
  vales.push(novo);if(!DEMO)sbInsert('vales',Object.assign({},novo,{id:undefined}));
  renderAprovacoes();renderOc();alert('Aprovado! Vale '+novo.numero+' gerado.');
}
function rejeitar(id){var a=aprovacoes.find(function(x){return x.id===id;});if(a)a.status='rejeitado';renderAprovacoes();}

function renderAlertas(){
  var items=[];
  epis.forEach(function(e){
    var s=stV(e.validade);if(s&&s.cls!=='ok')items.push({tipo:'EPI vencido',desc:e.nome+' — '+fNome(e.responsavel_id),s:s,data:fmtD(e.validade)});
    if(e.ca_validade){var sc=stV(e.ca_validade);if(sc&&sc.cls!=='ok')items.push({tipo:'CA vencido',desc:e.nome+' — '+e.ca,s:sc,data:fmtD(e.ca_validade)});}
  });
  estoque.forEach(function(e){if(e.saldo<e.saldo_minimo)items.push({tipo:'Estoque crítico',desc:e.nome+' — '+e.saldo+'/'+e.saldo_minimo,s:{lbl:'Abaixo do mín.',cls:'danger'},data:'—'});});
  treinamentos.forEach(function(t){var val=t.val||t.validade;var s=stV(val);if(s&&s.cls!=='ok')items.push({tipo:'Treinamento vencido',desc:fNome(t.funcionario_id)+' — '+t.nr,s:s,data:fmtD(val)});});
  ferramentas.forEach(function(f){if(f.proxima_calibracao){var s=stV(f.proxima_calibracao);if(s&&s.cls!=='ok')items.push({tipo:'Calibração pendente',desc:f.nome,s:s,data:fmtD(f.proxima_calibracao)});}});
  locacoes.forEach(function(l){if(l.termino){var d=Math.round((new Date(l.termino+'T00:00:00')-new Date())/86400000);if(d<=30&&d>=0)items.push({tipo:'Contrato vencendo',desc:l.nome+' — '+l.locadora,s:{lbl:d+' dias',cls:d<=7?'danger':'warn'},data:fmtD(l.termino)});}});
  var el=document.getElementById('alert-badge');if(el)el.textContent=items.length;
  if(!items.length){document.getElementById('alertas-list').innerHTML='<div style="border:0.5px solid #e0dfd8;border-radius:12px;display:flex;align-items:center;justify-content:center;height:120px;color:#bbb;font-size:13px">Nenhum alerta</div>';return;}
  document.getElementById('alertas-list').innerHTML='<div class="card"><div class="ch"><span class="ct">Alertas ativos ('+items.length+')</span></div>'
    +'<table class="tbl tbl-r"><thead><tr><th>Tipo</th><th>Descrição</th><th>Status</th><th>Data</th></tr></thead><tbody>'
    +items.map(function(a){return '<tr><td><span class="bdg '+(a.s.cls==='danger'?'danger':'warn')+'">'+a.tipo+'</span></td><td>'+a.desc+'</td><td><span class="bdg '+a.s.cls+'">'+a.s.lbl+'</span></td><td>'+a.data+'</td></tr>';}).join('')
    +'</tbody></table></div>';
}
function renderNR6(){
  var fid=(document.getElementById('nr6-func')||{}).value;if(!fid)return;
  var f=funcs.find(function(x){return x.id===fid;});if(!f)return;
  var idx=funcs.indexOf(f);
  var myE=epis.filter(function(e){return e.responsavel_id===fid && epiEmPoderFicha(e);});
  var myV=vales.filter(function(v){return v.funcionario_id===fid;});
  var myT=treinamentos.filter(function(t){return t.funcionario_id===fid;});
  var myU=uniformesEnt.filter(function(u){return u.funcionario_id===fid&&u.ativo;});
  var cc={Novo:'ok',Higienizado:'teal',Reparado:'info'};
  var hoje = dataHoje();

  // Resolver contrato
  var cont = (typeof contratos!=='undefined' && f.contrato_id)
    ? contratos.find(function(c){return c.id===f.contrato_id;})
    : null;
  var contLabel = cont ? escHtml(almContratoLabel(cont,false)) : (f.contrato_nome||'<span style="color:#A32D2D">Sem contrato vinculado</span>');

  // Resolver equipe
  var equipe = (typeof equipes!=='undefined' && f.equipe_id)
    ? equipes.find(function(e){return e.id===f.equipe_id;})
    : null;

  // Alertas de aptidão
  var apt = (typeof calcularAptidao==='function') ? calcularAptidao(f) : null;
  var aptBanner = apt && apt.status !== 'Apto'
    ? '<div style="background:#FEE8E8;border:.5px solid #A32D2D;border-radius:8px;padding:.6rem 1rem;margin-bottom:.75rem;font-size:12px;color:#A32D2D">'
      +'⚠ Aptidão: <strong>'+apt.status+'</strong>'+(apt.pendencias.length?' — Pendente: '+apt.pendencias.slice(0,3).join(', '):'')+'</div>'
    : '';

  var html = '<div class="card" style="margin-bottom:1rem">'
    +'<div class="ch" style="flex-wrap:wrap;gap:6px">'
    +'<div style="display:flex;align-items:center;gap:10px">'+av(f.nome,idx)
    +'<div><div style="font-weight:600;font-size:15px">'+f.nome+'</div>'
    +'<div style="font-size:11px;color:#888">RE/Matr.: '+(f.re||f.matricula||'—')+'</div>'
    +'</div></div>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap">'
    +'<button class="btn btn-pri" onclick="openNovaEntregaEpi(\''+fid+'\')">+ Entregar EPI</button>'
    +(myE.some(epiEmPoderFicha)?'<button class="btn" style="color:#854F0B;border-color:#854F0B" onclick="openDevolucaoEpi(\''+fid+'\')">📤 Devolver EPI/EPC</button>':'')
    +'<button class="btn" onclick="imprimirFichaNR6(\''+fid+'\')">🖨 Imprimir Ficha</button>'
    +'</div></div>'
    // Cabeçalho NR-6
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem 1.5rem;padding:.75rem 1rem;background:#f9f9f7;border-radius:8px;margin:.5rem 1rem 0;font-size:12px">'
    +'<div><span style="color:#888">Contrato:</span> <strong>'+contLabel+'</strong></div>'
    +'<div><span style="color:#888">Cargo/Função:</span> <strong>'+(f.cargo||f.funcao||'—')+'</strong></div>'
    +'<div><span style="color:#888">Equipe:</span> '+(equipe?equipe.nome_equipe:'—')+'</div>'
    +'<div><span style="color:#888">Empresa:</span> '+(f.empresa||'—')+'</div>'
    +'<div><span style="color:#888">Admissão:</span> '+fmtD(f.admissao)+'</div>'
    +'<div><span style="color:#888">Status:</span> '+(f.ativo===false?'<span style="color:#A32D2D">Inativo</span>':'<span style="color:#3B6D11">Ativo</span>')+'</div>'
    +(f.setor?'<div><span style="color:#aaa">Setor (complementar):</span> '+f.setor+'</div>':'')
    +'</div></div>'
    + aptBanner;

  // EPIs com CA e validade
  html+='<div class="card" style="margin-bottom:1rem"><div class="ch" style="background:#EBF4FD"><span class="ct" style="color:#185FA5">🦺 EPIs / Ficha NR-6</span></div>';
  html+='<table class="tbl tbl-r"><thead><tr>'
    +'<th>EPI</th><th>Qtd</th><th>CA</th><th>Val. CA</th><th>Data entrega</th><th>Data troca prev.</th><th>Assinatura</th><th>Status</th><th>Motivo</th>'
    +'</tr></thead><tbody>';
  if(myE.length){
    myE.forEach(function(e){
      var sCA = e.ca_validade ? stV(e.ca_validade) : null;
      var sEPI= e.validade    ? stV(e.validade)    : null;
      var dtTroca = e.data_prevista_substituicao || e.validade;
      var semAssin = !e.assinatura_url && e.status !== 'Devolvido';
      html+='<tr>'
        +'<td><strong>'+e.nome+'</strong></td>'
        +'<td style="text-align:center">'+(e.quantidade||1)+'</td>'
        +'<td>'+(e.ca||'—')+'</td>'
        +'<td>'+(sCA?'<span class="bdg '+sCA.cls+'">'+fmtD(e.ca_validade)+'</span>':'—')+'</td>'
        +'<td>'+fmtD(e.data_entrega)+'</td>'
        +'<td>'+(dtTroca?'<span class="bdg '+(sEPI?sEPI.cls:'ok')+'">'+fmtD(dtTroca)+'</span>':'—')+'</td>'
        +'<td>'+(semAssin?'<span class="bdg warn">Pendente</span>':'<span class="bdg ok">✓</span>')+'</td>'
        +'<td><span class="bdg '+(sEPI?sEPI.cls:'ok')+'">'+(e.status||'Ativo')+'</span></td>'
        +'<td style="font-size:11px;color:#888">'+(e.motivo_entrega||'—')+'</td>'
        +'</tr>';
    });
  } else {
    html+='<tr><td colspan="9" style="color:#A32D2D;padding:.75rem">⚠ Nenhum EPI registrado — colaborador sem cobertura de EPI</td></tr>';
  }
  html+='</tbody></table></div>';

  // Uniformes
  html+='<div class="card" style="margin-bottom:1rem"><div class="ch" style="background:#E1F5EE"><span class="ct" style="color:#085041">👕 Uniformes</span></div>';
  html+='<table class="tbl tbl-r"><thead><tr><th>Uniforme</th><th>Tamanho</th><th>Qtd</th><th>Condição</th><th>Data entrega</th><th>Tipo</th><th>Status</th></tr></thead><tbody>';
  if(myU.length){
    myU.forEach(function(u){
      var uni=uniformesCat.find(function(x){return x.id===u.uniforme_id;})||{};
      html+='<tr><td>'+(uni.tipo||'—')+(uni.modelo?' '+uni.modelo:'')+'</td><td>'+(uni.tamanho||u.tamanho||'—')+'</td><td>'+(u.quantidade||1)+'</td>'
        +'<td><span class="bdg '+(cc[u.condicao_entrega]||'info')+'">'+(u.condicao_entrega||'—')+'</span></td>'
        +'<td>'+fmtD(u.data_entrega)+'</td>'
        +'<td style="font-size:11px">'+(u.tipo_entrega||'—')+'</td>'
        +'<td><span class="bdg ok">Em uso</span></td>'
        +'</tr>';
    });
  } else html+='<tr><td colspan="7" style="color:#aaa;padding:.75rem">Nenhum uniforme em uso</td></tr>';
  html+='</tbody></table></div>';

  // Treinamentos / NRs
  html+='<div class="card" style="margin-bottom:1rem"><div class="ch" style="background:#EEEDFE"><span class="ct" style="color:#3C3489">🎓 Treinamentos / NRs</span></div>';
  html+='<table class="tbl tbl-r"><thead><tr><th>NR</th><th>Título</th><th>Data</th><th>Validade</th><th>Status</th></tr></thead><tbody>';
  if(myT.length){
    myT.forEach(function(t){
      var val=t.val||t.validade; var s=val?stV(val):null;
      html+='<tr><td><strong>'+(t.nr||'—')+'</strong></td><td>'+t.titulo+'</td><td>'+fmtD(t.data||t.data_inicio||t.criado_em)+'</td>'
        +'<td>'+(s?'<span class="bdg '+s.cls+'">'+fmtD(val)+'</span>':'Sem validade')+'</td>'
        +'<td>'+(s?'<span class="bdg '+s.cls+'">'+s.lbl+'</span>':'<span class="bdg ok">Válido</span>')+'</td></tr>';
    });
  } else html+='<tr><td colspan="5" style="color:#aaa;padding:.75rem">Nenhum treinamento registrado</td></tr>';
  html+='</tbody></table></div>';

  // Vales
  if(myV.length){
    html+='<div class="card" style="margin-bottom:1rem"><div class="ch" style="background:#FEF3E2"><span class="ct" style="color:#854F0B">📄 Vales / Ocorrências</span></div>';
    html+='<table class="tbl tbl-r"><thead><tr><th>Item</th><th>Motivo</th><th>Valor</th><th>Data</th><th>Status</th></tr></thead><tbody>';
    myV.forEach(function(v){
      html+='<tr><td>'+v.item+'</td><td>'+v.motivo+'</td><td>R$ '+Number(v.valor).toFixed(2)+'</td><td>'+fmtD(v.data_emissao)+'</td>'
        +'<td><span class="bdg warn">'+(v.status||'Pendente')+'</span></td></tr>';
    });
    html+='</tbody></table></div>';
  }

  var el=document.getElementById('nr6-content');
  if(el) el.innerHTML=html;
}
