    '.campo{margin-bottom:4px}',
    '.label{font-size:9px;color:#666;text-transform:uppercase;letter-spacing:.3px}',
    '.valor{font-size:11px;font-weight:500;border-bottom:1px solid #ccc;min-width:120px;display:inline-block;padding-bottom:1px}',
    'table{width:100%;border-collapse:collapse;margin-bottom:8px;font-size:10px}',
    'th{background:#1a1a18;color:#fff;padding:4px 6px;text-align:left;font-size:10px}',
