    'tr:nth-child(even) td{background:#f9f9f7}',
    '.badge-ok{background:#d4edda;color:#155724;border-radius:3px;padding:1px 5px;font-size:9px}',
    '.badge-venc{background:#f8d7da;color:#721c24;border-radius:3px;padding:1px 5px;font-size:9px}',
    '.badge-av{background:#fff3cd;color:#856404;border-radius:3px;padding:1px 5px;font-size:9px}',
    '.assinatura{margin-top:24px;display:flex;gap:40px}',
