function renderLavagem(){
  var and=uniformesMov.filter(function(m){return m.status==='Em andamento';});
  var hist=uniformesMov.filter(function(m){return m.status!=='Em andamento';});
  var tc={'Saída lavagem':'teal','Saída reparo':'warn','Retorno lavagem':'ok','Retorno reparo':'ok','Devolução definitiva':'info'};
  document.getElementById('tbody-lav-and').innerHTML=and.map(function(m){
    var cat=uniformesCat.find(function(c){return c.id===m.uniforme_id;})||{};
    var cs=_uniCodigoSku(cat);
    return '<tr><td>'+fNome(m.funcionario_id)+'</td>'
      +'<td>'+(cat.tipo||'—')+' '+(cat.tamanho||'')
      +'<div style="font-size:10px;color:#888;font-family:monospace">'+(cs.codigoRaw||'—')+' · '+(cs.skuRaw||'—')+'</div></td>'
      +'<td>'+m.quantidade+'</td><td><span class="bdg '+(tc[m.tipo_mov]||'gray')+'">'+m.tipo_mov+'</span></td>'
      +'<td>'+(m.prestador||'—')+'</td><td>'+fmtD(m.data_saida)+'</td><td>'+fmtD(m.previsao_retorno)+'</td>'
      +'<td><span class="bdg '+(stV(m.previsao_retorno)?stV(m.previsao_retorno).cls:'ok')+'">Em andamento</span></td>'
      +'<td><button class="btn btn-sm btn-teal" onclick="registrarRetorno(\''+m.id+'\',\''+m.tipo_mov+'\',\''+m.uniforme_id+'\','+m.quantidade+')">Retorno</button></td></tr>';
  }).join('')||'<tr><td colspan="9" style="padding:1.5rem;text-align:center;color:#aaa">Nenhuma saída</td></tr>';
  document.getElementById('tbody-lav-hist').innerHTML=hist.map(function(m){
    var cat=uniformesCat.find(function(c){return c.id===m.uniforme_id;})||{};
    var cs=_uniCodigoSku(cat);
    return '<tr><td>'+fNome(m.funcionario_id)+'</td>'
      +'<td>'+(cat.tipo||'—')+' '+(cat.tamanho||'')
      +'<div style="font-size:10px;color:#888;font-family:monospace">'+(cs.codigoRaw||'—')+' · '+(cs.skuRaw||'—')+'</div></td>'
      +'<td>'+m.quantidade+'</td><td><span class="bdg '+(tc[m.tipo_mov]||'gray')+'">'+m.tipo_mov+'</span></td>'
      +'<td>'+(m.prestador||'—')+'</td><td>'+fmtD(m.data_saida)+'</td><td>'+fmtD(m.data_retorno)+'</td>'
      +'<td><span class="bdg ok">'+m.status+'</span></td></tr>';
  }).join('')||'<tr><td colspan="8" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum histórico</td></tr>';
  atualizarMetricas();
}
function openSaidaLavagem(){
  var fOpts=funcs.map(function(f){return '<option value="'+f.id+'">'+f.nome+'</option>';}).join('');
  var uOpts=uniformesCat.map(function(u){return '<option value="'+u.id+'">'+_uniOptLabel(u)+'</option>';}).join('');
  setModal('<div class="modal-bg"><div class="modal"><h3>Registrar saída</h3>'
    +'<div class="fg"><label>Colaborador</label><select id="lav-func">'+fOpts+'</select></div>'
    +'<div class="fg"><label>Uniforme</label><select id="lav-uni">'+uOpts+'</select></div>'
    +'<div class="fg"><label>Tipo</label><select id="lav-tipo"><option>Saída lavagem</option><option>Saída reparo</option></select></div>'
    +'<div class="fg"><label>Quantidade</label><input id="lav-qtd" type="number" min="1" value="1"/></div>'
    +'<div class="fg"><label>Prestador</label><input id="lav-prest"/></div>'
    +'<div class="fg"><label>Prev. retorno</label><input id="lav-prev" type="date" value="'+isoD(7)+'"/></div>'
    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="salvarSaida()">Registrar</button></div></div></div>');
}
