function salvarSaidaRapida(tipo,fid){
  var uid=(document.getElementById('lav-uni')||{}).value;
  var prest=(document.getElementById('lav-prest')||{}).value||'—';
  var prev=(document.getElementById('lav-prev')||{}).value||isoD(7);
  var tipoMov=tipo==='lavagem'?'Saída lavagem':'Saída reparo';
  var novo={id:'um'+Date.now(),funcionario_id:fid,uniforme_id:uid,tipo_mov:tipoMov,quantidade:1,data_saida:dataHojeLocal(),previsao_retorno:prev,data_retorno:null,prestador:prest,status:'Em andamento'};
  uniformesMov.unshift(novo);if(!DEMO)sbInsert('uniformes_movimentacoes',Object.assign({},novo,{id:undefined}));
  var sub={id:'ue'+Date.now(),funcionario_id:fid,uniforme_id:uid,condicao_entrega:'Higienizado',quantidade:1,data_entrega:dataHojeLocal(),tipo_entrega:'Temporária',ativo:true};
  uniformesEnt.push(sub);if(!DEMO)sbInsert('uniformes_colaborador',Object.assign({},sub,{id:undefined}));
  closeModal();renderLavagem();renderUniformesEntregues();atualizarMetricas();
  alert('Saída registrada e substituto entregue a '+fNome(fid)+'.');
}
async function registrarRetorno(mid,tipoMov,uid,qtd){
  var m=uniformesMov.find(function(x){return x.id===mid;});if(!m)return;
  var cond=tipoMov.indexOf('lavagem')>=0?'Higienizado':'Reparado';
  m.status='Retornado';m.data_retorno=dataHojeLocal();
  if(!DEMO)await sbUpdate('uniformes_movimentacoes',{status:'Retornado',data_retorno:m.data_retorno},'id=eq.'+mid);
  var sub=uniformesEnt.find(function(u){return u.funcionario_id===m.funcionario_id&&u.tipo_entrega==='Temporária'&&u.uniforme_id===uid;});
  if(sub){sub.ativo=false;if(!DEMO)await sbUpdate('uniformes_colaborador',{ativo:false},'id=eq.'+sub.id);}
  var est=estoqueUni.find(function(e){return e.uniforme_id===uid&&e.condicao===cond;});
  if(est)est.quantidade+=qtd;else estoqueUni.push({id:'eu'+Date.now(),uniforme_id:uid,condicao:cond,quantidade:qtd});
  renderLavagem();renderEstoqueUni();atualizarMetricas();
  alert('Retorno registrado! '+qtd+' unidade(s) ao estoque como "'+cond+'".');
}
function devolverDefinitivo(ueid,fid,uid){
  var u=uniformesEnt.find(function(x){return x.id===ueid;});if(!u)return;
  if(!confirm('Confirmar devolução?'))return;
  u.ativo=false;if(!DEMO)sbUpdate('uniformes_colaborador',{ativo:false},'id=eq.'+ueid);
  var cond=u.condicao_entrega||'Higienizado';
  var est=estoqueUni.find(function(e){return e.uniforme_id===uid&&e.condicao===cond;});
  if(est)est.quantidade+=u.quantidade;
  uniformesMov.unshift({id:'um'+Date.now(),funcionario_id:fid,uniforme_id:uid,tipo_mov:'Devolução definitiva',quantidade:u.quantidade,data_saida:dataHojeLocal(),previsao_retorno:null,data_retorno:dataHojeLocal(),prestador:'Almoxarifado',status:'Retornado'});
  renderUniformesEntregues();atualizarMetricas();alert('Devolução registrada.');
}
