function renderFunc(){
  // Popular selects de funcionário
  ['nr6-func','fil-uni-func'].forEach(function(id){
    var el=document.getElementById(id);if(!el)return;
    el.innerHTML=(id==='fil-uni-func'?'<option value="">Todos</option>':'<option value="">Selecione</option>')
      +funcs.map(function(f){return '<option value="'+f.id+'">'+f.nome+(f.re?' (RE '+f.re+')':'')+'</option>';}).join('');
  });

  // Popular filtro de contrato (se existir no HTML)
  var filCont = document.getElementById('fil-func-contrato');
  if(filCont && !filCont.hasAttribute('data-populado')){
    filCont.innerHTML = '<option value="">Todos os contratos</option>'
      +(typeof contratos!=='undefined'?contratos.map(function(c){ return '<option value="'+c.id+'">'+c.nome+'</option>'; }).join(''):'');
    filCont.setAttribute('data-populado','1');
  }

  var filtCont  = (document.getElementById('fil-func-contrato')||{}).value||'';
  var filtCargo = ((document.getElementById('fil-func-cargo')||{}).value||'').toLowerCase();
  var filtBusca = ((document.getElementById('fil-func-busca')||{}).value||'').toLowerCase();

  var lista = funcs.filter(function(f){
    if(filtCont  && f.contrato_id !== filtCont) return false;
    if(filtCargo && !(f.cargo||f.funcao||'').toLowerCase().includes(filtCargo)) return false;
    if(filtBusca && !(f.nome||'').toLowerCase().includes(filtBusca) && !(f.matricula||f.re||'').toLowerCase().includes(filtBusca)) return false;
    return true;
  });

  var ec=function(f){return epis.filter(function(e){return e.responsavel_id===f.id;}).length;};
  var fc=function(f){return ferramentas.filter(function(t){return t.responsavel_id===f.id;}).length;};
  var uc=function(f){return uniformesEnt.filter(function(u){return u.funcionario_id===f.id&&u.ativo;}).length;};
  var cv=function(f){return vales.filter(function(v){return v.funcionario_id===f.id&&v.valor>0;}).reduce(function(s,v){return s+Number(v.valor);},0);};

  // Helper: resolver contrato do colaborador
  var getContrato = function(f){
    var cid = f.contrato_id;
    if(!cid && f.contrato_nome) return {codigo:'', nome:f.contrato_nome};
    if(!cid) return null;
    return (typeof contratos!=='undefined' ? contratos.find(function(c){return c.id===cid;}) : null)||null;
  };

  var tbody = document.getElementById('tbody-func');
  if(!tbody) return;

  if(!lista.length){
    tbody.innerHTML = '<tr><td colspan="10" style="text-align:center;color:#aaa;padding:1rem">Nenhum colaborador encontrado.</td></tr>';
    return;
  }

  tbody.innerHTML = lista.map(function(f,i){
    var cont = getContrato(f);
    var contLabel = cont
      ? '<span style="font-size:11px">'+escHtml(almContratoLabel(cont,false))+'</span>'
      : '<span class="bdg warn" style="font-size:10px">Sem contrato</span>';
    var apt = (typeof calcularAptidao==='function') ? calcularAptidao(f) : null;
    var aptBadge = apt
      ? '<span style="font-size:10px;padding:2px 6px;border-radius:4px;background:'+({'Apto':'#EAF3DE','Bloqueado':'#FEE8E8','Pendente':'#FFF3E0'}[apt.status]||'#f5f5f3')+';color:'+({'Apto':'#3B6D11','Bloqueado':'#A32D2D','Pendente':'#854F0B'}[apt.status]||'#555')+'">'+apt.status+'</span>'
      : '';
    return '<tr>'
      +'<td><div style="display:flex;align-items:center;gap:8px">'+av(f.nome,i)+'<div><div style="font-weight:500">'+f.nome+'</div><div style="font-size:10px;color:#aaa">'+(f.empresa||'')+'</div></div></div></td>'
      +'<td style="font-size:12px;color:#888">'+(f.re||f.matricula||'—')+'</td>'
      +'<td>'+contLabel+'</td>'
      +'<td style="font-size:12px">'+(f.cargo||f.funcao||'—')+'</td>'
      +'<td style="font-size:11px;color:#888">'+(f.equipe_id&&typeof equipes!=='undefined'?(equipes.find(function(e){return e.id===f.equipe_id;})||{}).nome_equipe||'—':'—')+'</td>'
      +'<td style="font-size:11px">'+fmtD(f.admissao)+'</td>'
      +'<td><span class="bdg info">'+ec(f)+'</span></td>'
      +'<td><span class="bdg purple">'+fc(f)+'</span></td>'
      +'<td><span class="bdg teal">'+uc(f)+'</span></td>'
      +'<td>'+aptBadge+'</td>'
      +'<td><button class="btn btn-sm" onclick="showAlm(\''+f.id+'\')">Ver ficha</button></td>'
      +'</tr>';
  }).join('');

  var el=document.getElementById('m-func');if(el)el.textContent=lista.length;
}

// ── HELPERS CONTRATO / FICHA NR-6 ────────────────────────────────────────────

function getContratoColaborador(colab){
  if(!colab) return null;
  if(colab.contrato_id && typeof contratos!=='undefined')
    return contratos.find(function(c){return c.id===colab.contrato_id;})||null;
  if(colab.contrato_nome) return {codigo:'',nome:colab.contrato_nome};
  return null;
}

// ══ EPIs/EPCs — sub-abas (entregar / lista / ficha / cadastro) ════════════
function epiEntregaAtualizarColabs(){
  var cid = (document.getElementById('epi-ent-contrato')||{}).value||'';
  var sel = document.getElementById('epi-ent-colab'); if(!sel) return;
  var cols = (typeof colaboradores!=='undefined')
    ? colaboradores.filter(function(c){ return c.ativo!==false && (!cid || c.contrato_id===cid); }) : [];
  var cur = sel.value;
  sel.innerHTML = '<option value="">Selecione o colaborador...</option>'
    + cols.map(function(c){ return '<option value="'+c.id+'">'+escHtml(c.nome)+(c.re?' (RE '+c.re+')':'')+'</option>'; }).join('');
  if(cur && cols.some(function(c){ return String(c.id)===String(cur); })) sel.value = cur;
}
function renderEpiEntregaTab(){
  if(typeof funcs==='undefined'||!funcs.length) window.funcs=(typeof colaboradores!=='undefined'?colaboradores:[]).filter(function(c){return c.ativo!==false;});
  var selCont = document.getElementById('epi-ent-contrato');
  if(selCont && selCont.options.length<=1 && typeof contratos!=='undefined'){
    selCont.innerHTML = '<option value="">Todos os contratos</option>'
      + contratos.map(function(c){ return '<option value="'+c.id+'">'+escHtml(almContratoLabel(c,true))+'</option>'; }).join('');
  }
  epiEntregaAtualizarColabs();
}
function epiAbrirModalEntrega(){
  var fid = (document.getElementById('epi-ent-colab')||{}).value||'';
  if(!fid){ progShowToast('Selecione o colaborador para entregar EPI/EPC.','erro'); return; }
  if(typeof funcs==='undefined'||!funcs.length) window.funcs=(typeof colaboradores!=='undefined'?colaboradores:[]).filter(function(c){return c.ativo!==false;});
  openNovaEntregaEpi(fid);
}
function epiAbrirModalDevolucao(){
  var fid = (document.getElementById('epi-ent-colab')||{}).value||'';
  if(typeof funcs==='undefined'||!funcs.length) window.funcs=(typeof colaboradores!=='undefined'?colaboradores:[]).filter(function(c){return c.ativo!==false;});
  openDevolucaoEpi(fid||null);
}
function epiTabView(v){
  ['entregar','lista','ficha','cad','fichas','caepi'].forEach(function(x){
    var d=document.getElementById('epi-view-'+x); if(d) d.style.display=(x===v?'':'none');
    var b=document.getElementById('epiv-btn-'+x); if(b){ if(x===v) b.classList.add('btn-pri'); else b.classList.remove('btn-pri'); }
  });
  if(v==='entregar'){ renderEpiEntregaTab(); if(typeof almReqRenderFilaEntrega==='function') almReqRenderFilaEntrega(); }
  else if(v==='lista'){ if(typeof renderEpis==='function') renderEpis(); }
  else if(v==='ficha'){ if(typeof iniciarFichaEpi==='function') iniciarFichaEpi(); }
  else if(v==='cad'){ renderEpiCatalogo(); }
  else if(v==='fichas'){ renderEpiFichas(); }
  else if(v==='caepi'){ renderCaepiConsulta({containerId:'epi-view-caepi',idPrefix:'caepi-fil-'}); }
}
