  var TIPO={completa:{l:'Completa',c:'#3B6D11',bg:'#EAF3DE'},parcial:{l:'Parcial',c:'#854F0B',bg:'#FEF3E2'},complementar:{l:'Complementar',c:'#534AB7',bg:'#EEEDFE'}};
