  var rows=its.map(function(it){ return '<tr><td style="border:1px solid #ccc;padding:4px">'+escHtml(it.nome||'')+(it.mauUso?' <b style="color:#A32D2D">(mau uso)</b>':'')+'</td><td style="border:1px solid #ccc;padding:4px;text-align:center">'+(it.qtd||1)+'</td><td style="border:1px solid #ccc;padding:4px;text-align:center">'+escHtml(it.ca||'—')+'</td><td style="border:1px solid #ccc;padding:4px;text-align:center">'+(it.ca_validade?fmtD(it.ca_validade):'—')+'</td></tr>'; }).join('');
  var TIPO={completa:'Completa',parcial:'Parcial',complementar:'Complementar'};
