function almKitColabCargoInicial(k){
  if(!k) return '';
  if(k.colaborador_id){
    var col=(colaboradores||[]).find(function(c){ return c.id===k.colaborador_id; });
    if(col&&(col.cargo||'').trim()) return col.cargo.trim();
  }
  return (k.cargo||'').trim();
}
function almKitColabSyncCargo(){
  var colId=(document.getElementById('almkit-c-col')||{}).value||'';
  var selWrap=document.getElementById('almkit-c-cargo-wrap');
  var infoEl=document.getElementById('almkit-c-cargo-info');
  var cargoEl=document.getElementById('almkit-c-cargo');
  if(!colId){
    if(selWrap) selWrap.style.display='';
    if(infoEl) infoEl.style.display='none';
    return;
  }
  var col=(colaboradores||[]).find(function(c){ return c.id===colId; });
  var cargo=col?(col.cargo||'').trim():'';
  if(cargoEl) cargoEl.value=cargo;
  if(selWrap) selWrap.style.display='none';
  if(infoEl){
    infoEl.style.display='';
    infoEl.innerHTML=cargo
      ?('<b>'+escHtml(cargo)+'</b> <span style="color:#888;font-weight:400">(do cadastro do colaborador)</span>')
      :'<span style="color:#854F0B">Colaborador sem cargo cadastrado — cadastre o cargo no colaborador ou use kit por cargo (modelo).</span>';
  }
}
