  corpo.innerHTML='<div class="card" style="margin-bottom:.75rem">'
    +'<div class="ch"><span class="ct">🔍 Vistoria inicial (mobilização)</span>'
    +'<button class="btn btn-sm" onclick="almCarregarFrotaVistoria(function(){almRenderVistoriaInicialEmbutida();})" style="margin-left:auto">🔄</button></div>'
    +'<div id="alm-kc-vistoria-embed" style="padding:.75rem 1rem;color:#aaa;font-size:12px">Carregando frota...</div></div>'
    +'<div id="alm-kc-carga-kanban-wrap"></div>';
